#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define ADS1115_CONFIG_SINGLE_SHOT 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0060
#define ADS1115_CONFIG_COMP_MODE_TRADITIONAL 0x0000
#define ADS1115_CONFIG_COMP_POL_ACTIVE_LOW 0x0000
#define ADS1115_CONFIG_COMP_LAT_NON_LATCHING 0x0000
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003

// MLX91219 sensitivity (40mV/A)
#define SENSITIVITY 0.04

// MLX91219 zero-current offset (mid-supply)
#define ZERO_CURRENT_OFFSET 2.5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to configure the ADS1115
int configure_ads1115() {
    uint16_t config = ADS1115_CONFIG_SINGLE_SHOT |
                      ADS1115_CONFIG_MUX_AIN0_GND |
                      ADS1115_CONFIG_PGA_4_096V |
                      ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS |
                      ADS1115_CONFIG_COMP_MODE_TRADITIONAL |
                      ADS1115_CONFIG_COMP_POL_ACTIVE_LOW |
                      ADS1115_CONFIG_COMP_LAT_NON_LATCHING |
                      ADS1115_CONFIG_COMP_QUE_DISABLE;

    uint8_t buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;        // LSB

    int result = i2cWriteI2CBlockData(i2c_handle, buf[0], (char *)buf + 1, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to ADS1115 configuration register: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read the ADS1115 conversion register
int16_t read_ads1115_conversion() {
    uint8_t buf[1];
    buf[0] = ADS1115_REG_CONVERT;

    int result = i2cWriteI2CBlockData(i2c_handle, buf[0], (char *)buf + 1, 0); // Write register address
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 conversion register: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERT, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register: %d\n", result);
        return -1;
    }

    int16_t conversion = (read_buf[0] << 8) | read_buf[1];
    return conversion;
}

// Function to calculate current from ADC reading
float calculate_current(int16_t adc_reading) {
    // Convert ADC reading to voltage (assuming 16-bit ADC and 4.096V range)
    float voltage = (float)adc_reading * 4.096 / 32768.0;

    // Calculate current using the sensor's sensitivity and zero-current offset
    float current = (voltage - ZERO_CURRENT_OFFSET) / SENSITIVITY;
    return current;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        fprintf(stderr, "ADS1115 configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC conversion
        int16_t adc_reading = read_ads1115_conversion();
        if (adc_reading == -1) {
            fprintf(stderr, "Error reading ADC conversion\n");
            break; // Exit loop on error
        }

        // Calculate current
        float current = calculate_current(adc_reading);

        // Log current to console
        printf("Current: %.3f A\n", current);

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

