// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_FULL_SCALE_VOLTAGE 4.096
#define ADS1115_SAMPLE_RATE 128
#define ADS1115_PGA_4_096V 0x60 // +/- 4.096V range
#define ADS1115_CONTINUOUS_MODE 0x8000
#define ADS1115_CHANNEL_0 0x4000

#define CO_LOG_FILE "co_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold calibration data
typedef struct {
    float slope;
    float intercept;
} CalibrationData;

