// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from specified channel
int read_adc(int channel) {
    unsigned char config[3];
    int raw_value;

    // Configure ADS1115 for single-ended read on specified channel
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONTINUOUS_MODE | ADS1115_PGA_4_096V | ADS1115_CHANNEL_0) >> 8;
    config[2] = (ADS1115_CONTINUOUS_MODE | ADS1115_PGA_4_096V | ADS1115_CHANNEL_0) & 0xFF;

    if (i2cWriteDevice(i2c_handle, (char *)config, 3) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 configuration register\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

