    config[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(i2c_handle, (char *)config, 1) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 conversion register\n");
        return -1;
    }

    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Failed to read from ADS1115 conversion register\n");
        return -1;
    }

    raw_value = (buf[0] << 8) | buf[1];

    return raw_value;
}

