    // Use a logarithmic curve to estimate CO concentration
    // This is a placeholder; replace with the actual calibration curve from the datasheet
    // Example logarithmic curve: PPM = a * log(resistance) + b
    float ppm = co_calibration.slope * log10(resistance) + co_calibration.intercept;

