#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define I2C addresses for the microphones
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49

// Define the I2C bus number (usually 1 on Raspberry Pi)
#define I2C_BUS 1

// Define the microphone sensitivity (dBV/Pa)
#define SENSITIVITY -38.0

// Define the reference pressure (Pa)
#define REFERENCE_PRESSURE 20e-6

// Define the sampling interval (milliseconds)
#define SAMPLING_INTERVAL 100

// Global variables for I2C handles and program state
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_microphone_data(int i2c_handle);
double convert_to_db(int raw_data);
void log_data(double db_value);
void signal_handler(int signal);

// Structure to hold program configuration
typedef struct {
    int i2c_bus;
    int mic1_addr;
    int mic2_addr;
    int sampling_interval;
    double sensitivity;
    double reference_pressure;
    char log_file[64];
} program_config_t;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read raw microphone data from the I2C bus
int read_microphone_data(int i2c_handle) {
    char buffer[2];
    int bytes_read;
    int raw_data;

    bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1; // Indicate an error
    }

    // Combine the two bytes into a 16-bit signed integer
    raw_data = (buffer[0] << 8) | buffer[1];
    raw_data = raw_data >> 2; // Shift right by 2 bits

    return raw_data;
}

// Function to convert raw data to dB
double convert_to_db(int raw_data) {
    double voltage = (double)raw_data / 32768.0 * 3.3; // Assuming 3.3V reference
    double pressure = voltage / 3.3 * 1000.0; // Convert voltage to pressure (Pa)
    double db = SENSITIVITY + 20 * log10(pressure / REFERENCE_PRESSURE);
    return db;
}

// Function to log the timestamped average dB value to a file
void log_data(double db_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    FILE *fp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen("audio_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(fp, "%s, %.2f dB\n", timestamp, db_value);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both microphones
    i2c_handle1 = i2cOpen(I2C_BUS, MIC1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, MIC2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int raw_data1, raw_data2;
        double db1, db2, average_db;

        // Read data from microphone 1
        raw_data1 = read_microphone_data(i2c_handle1);
        if (raw_data1 == -1) {
            db1 = -999.0; // Indicate an error
        } else {
            db1 = convert_to_db(raw_data1);
        }

        // Read data from microphone 2
        raw_data2 = read_microphone_data(i2c_handle2);
        if (raw_data2 == -1) {
            db2 = -999.0; // Indicate an error
        } else {
            db2 = convert_to_db(raw_data2);
        }

        // Calculate the average dB value
        average_db = (db1 + db2) / 2.0;

        // Log the data
        log_data(average_db);

        // Wait for the next sample
        gpioDelay(SAMPLING_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Close I2C handles and terminate pigpio
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

