#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1
#define SAMPLE_INTERVAL_MS 1
#define SAMPLE_WINDOW_MS 100
#define NUM_SAMPLES (SAMPLE_WINDOW_MS / SAMPLE_INTERVAL_MS)
#define THRESHOLD 0.7
#define LED_GPIO 27
#define LED_ON_TIME_MS 500
#define CSV_FILE "audio_events.csv"

// Global variables
int spi_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
double calculate_rms(int *samples, int num_samples);
void control_led(int on);
void log_data(double mic1_rms, double mic2_rms);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate RMS value
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Function to log data to CSV file
void log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%.6f,%.6f\n", timestamp, mic1_rms, mic2_rms);
    fflush(csv_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open CSV file for logging
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error: Failed to open CSV file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    int mic1_samples[NUM_SAMPLES];
    int mic2_samples[NUM_SAMPLES];
    int sample_index = 0;

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC values
        int mic1_adc = read_adc(MIC1_CHANNEL);
        int mic2_adc = read_adc(MIC2_CHANNEL);

        if (mic1_adc == -1 || mic2_adc == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            break; // Exit loop on error
        }

        // Store samples
        mic1_samples[sample_index] = mic1_adc;
        mic2_samples[sample_index] = mic2_adc;

        // Calculate RMS values
        double mic1_rms = calculate_rms(mic1_samples, NUM_SAMPLES);
        double mic2_rms = calculate_rms(mic2_samples, NUM_SAMPLES);

        // Normalize RMS values (assuming ADC range is 0-1023)
        double mic1_normalized = mic1_rms / 1023.0;
        double mic2_normalized = mic2_rms / 1023.0;

        // Check threshold and control LED
        if (mic1_normalized > THRESHOLD || mic2_normalized > THRESHOLD) {
            control_led(1); // Turn LED on
            gpioDelay(LED_ON_TIME_MS * 1000); // Delay for 500ms
            control_led(0); // Turn LED off
        }

        // Log data
        log_data(mic1_rms, mic2_rms);

        // Increment sample index and reset if necessary
        sample_index = (sample_index + 1) % NUM_SAMPLES;

        // Delay for sampling interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_led(0); // Turn off LED
    spiClose(spi_handle);
    fclose(csv_file);
    gpioTerminate();

    return 0;
}

