#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_ADDR 0x48
#define I2C_BUS 1
#define LED_GPIO 17
#define OVERCURRENT_THRESHOLD 50.0
#define SAMPLE_RATE_HZ 10
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_adc(int16_t *value);
float convert_to_current(int16_t adc_value);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void control_led(float average_current);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from ADS1115
int read_adc(int16_t *value) {
    char config[3];
    char read_buffer[2];

    // Configure ADS1115 for single-ended A0, 4.096V, continuous conversion
    config[0] = 0x01; // Configuration register address
    config[1] = 0xC3; // MSB: 11000011 (Single-ended A0, +/-4.096V, Continuous conversion, 128 SPS)
    config[2] = 0x83; // LSB: 10000011 (128 SPS)

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "I2C write failed\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10);

    // Read conversion register
    config[0] = 0x00; // Conversion register address
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "I2C write failed\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, read_buffer, 2) != 2) {
        fprintf(stderr, "I2C read failed\n");
        return -1;
    }

    *value = (read_buffer[0] << 8) | read_buffer[1];
    return 0;
}

// Convert ADC value to current (0-100A)
float convert_to_current(int16_t adc_value) {
    // Assuming 0.5V = 0A and 4.5V = 100A
    // Linear interpolation: 0.5 + (adc_value / 2^15) * (4.5 - 0.5)
    // Simplified: 0.5 + (adc_value / 32768.0) * 4
    return 0.5 + (adc_value / 32768.0) * 4;
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate the average of the values in the circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Control the LED based on the average current
void control_led(float average_current) {
    if (average_current > OVERCURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize circular buffer
    CircularBuffer current_buffer;
    init_circular_buffer(&current_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t adc_value;
    float current;
    float average_current;
    int sample_count = 0;

    while (!terminate) {
        // Read ADC value
        if (read_adc(&adc_value) == 0) {
            // Convert ADC value to current
            current = convert_to_current(adc_value);

            // Add current to circular buffer
            add_to_buffer(&current_buffer, current);

            // Calculate average current
            average_current = calculate_average(&current_buffer);

            // Control LED
            control_led(average_current);

            // Print current and average current (for debugging)
            printf("Current: %.2fA, Average Current: %.2fA\n", current, average_current);
        } else {
            fprintf(stderr, "Failed to read ADC value. Retrying...\n");
        }

        // Delay to achieve 10Hz sampling rate
        gpioDelay(100); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

