#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// TCS34725 Registers
#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A
#define TCS34725_ID 0x12

// Configuration
#define I2C_BUS 1
#define ATIME_VALUE 0xFF
#define GAIN_VALUE 0x01
#define POWER_ON_DELAY_MS 3
#define LOG_FILE "color_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int verify_sensor_id();
int configure_sensor();
int read_color_data(unsigned short *clear, unsigned short *red, unsigned short *green, unsigned short *blue);
int log_color_data(unsigned short clear, unsigned short red, unsigned short green, unsigned short blue);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    unsigned short clear;
    unsigned short red;
    unsigned short green;
    unsigned short blue;
} sensor_data_t;

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        cleanup();
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id() != 0) {
        fprintf(stderr, "Failed to verify sensor ID. Exiting.\n");
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        fprintf(stderr, "Failed to configure sensor. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read color data
        if (read_color_data(&sensor_data.clear, &sensor_data.red, &sensor_data.green, &sensor_data.blue) == 0) {
            // Log color data
            if (log_color_data(sensor_data.clear, sensor_data.red, sensor_data.green, sensor_data.blue) != 0) {
                fprintf(stderr, "Failed to log color data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read color data.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

int verify_sensor_id() {
    int id = i2cReadByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ID);
    if (id < 0) {
        fprintf(stderr, "Failed to read sensor ID: %d\n", id);
        return 1;
    }

    if ((id & 0x0F) != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        return 1;
    }
    return 0;
}

int configure_sensor() {
    // Set integration time
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ATIME, ATIME_VALUE) < 0) {
        fprintf(stderr, "Failed to write ATIME: %d\n", i2c_handle);
        return 1;
    }

    // Set gain
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_CONTROL, GAIN_VALUE) < 0) {
        fprintf(stderr, "Failed to write CONTROL: %d\n", i2c_handle);
        return 1;
    }

    // Power on and enable ADC
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, 0x01 | 0x02) < 0) {
        fprintf(stderr, "Failed to write ENABLE: %d\n", i2c_handle);
        return 1;
    }

    gpioDelay(POWER_ON_DELAY_MS); // Wait for power-on
    return 0;
}

int read_color_data(unsigned short *clear, unsigned short *red, unsigned short *green, unsigned short *blue) {
    int retries = 0;
    int result;

    while (retries < 3) {
        result = i2cReadWordData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_CDATA);
        if (result >= 0) {
            *clear = (unsigned short)result;
            break;
        } else {
            fprintf(stderr, "I2C read error (clear): %d, retry %d\n", result, retries + 1);
            retries++;
            gpioDelay(1); // Small delay before retry
        }
    }
    if (retries == 3) return 1;

    retries = 0;
    while (retries < 3) {
        result = i2cReadWordData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_RDATA);
        if (result >= 0) {
            *red = (unsigned short)result;
            break;
        } else {
            fprintf(stderr, "I2C read error (red): %d, retry %d\n", result, retries + 1);
            retries++;
            gpioDelay(1); // Small delay before retry
        }
    }
    if (retries == 3) return 1;

    retries = 0;
    while (retries < 3) {
        result = i2cReadWordData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_GDATA);
        if (result >= 0) {
            *green = (unsigned short)result;
            break;
        } else {
            fprintf(stderr, "I2C read error (green): %d, retry %d\n", result, retries + 1);
            retries++;
            gpioDelay(1); // Small delay before retry
        }
    }
    if (retries == 3) return 1;

    retries = 0;
    while (retries < 3) {
        result = i2cReadWordData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_BDATA);
        if (result >= 0) {
            *blue = (unsigned short)result;
            break;
        } else {
            fprintf(stderr, "I2C read error (blue): %d, retry %d\n", result, retries + 1);
            retries++;
            gpioDelay(1); // Small delay before retry
        }
    }
    if (retries == 3) return 1;

    return 0;
}

int log_color_data(unsigned short clear, unsigned short red, unsigned short green, unsigned short blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
    }

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fclose(log_file);
    return 0;
}

void signal_handler(int signal) {
