#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Define SPI device and chip select pins
#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN_0 8
#define CS_PIN_1 7

// Define moisture sensor channels
#define MOISTURE_SENSOR_1_CHANNEL 0
#define MOISTURE_SENSOR_2_CHANNEL 1

// Define moisture scale
#define MOISTURE_SCALE 100.0

// Global variables for SPI file descriptor and GPIO line
int spi_fd = -1;
struct gpiod_line *cs_line_0 = NULL;
struct gpiod_line *cs_line_1 = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Function prototypes
int spi_init(void);
int gpio_init(void);
int read_mcp3008(int channel);
float map_adc_to_moisture(int adc_value);
int log_data(float moisture1, float moisture2);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Initialize SPI interface
int spi_init(void) {
    int mode = SPI_MODE_0;
    int bits_per_word = 8;
    int speed = 1000000; // 1 MHz

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Initialize GPIO lines for chip select
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line_0 = gpiod_chip_get_line(gpio_chip, CS_PIN_0);
    if (!cs_line_0) {
        perror("Error getting GPIO line for CS_PIN_0");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    cs_line_1 = gpiod_chip_get_line(gpio_chip, CS_PIN_1);
    if (!cs_line_1) {
        perror("Error getting GPIO line for CS_PIN_1");
        gpiod_line_release(cs_line_0);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line_0, "moisture_sensor", 1) < 0) {
        perror("Error requesting GPIO line for CS_PIN_0 as output");
        gpiod_line_release(cs_line_1);
        gpiod_line_release(cs_line_0);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line_1, "moisture_sensor", 1) < 0) {
        perror("Error requesting GPIO line for CS_PIN_1 as output");
        gpiod_line_release(cs_line_0);
        gpiod_line_release(cs_line_1);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    // Activate chip select
    if (gpiod_line_set_value(cs_line_0, 0) < 0) {
        perror("Error setting CS_PIN_0 low");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        if (gpiod_line_set_value(cs_line_0, 1) < 0) {
            perror("Error setting CS_PIN_0 high after SPI error");
        }
        return -1;
    }

    // Deactivate chip select
    if (gpiod_line_set_value(cs_line_0, 1) < 0) {
        perror("Error setting CS_PIN_0 high");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Map ADC value to moisture percentage
float map_adc_to_moisture(int adc_value) {
    return ((float)adc_value / 1023.0) * MOISTURE_SCALE;
}

// Log data to CSV file
int log_data(float moisture1, float moisture2) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("moisture_log.csv", "a");
    if (fp == NULL) {
        perror("Error opening moisture_log.csv");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Moisture1,Moisture2\n");
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, moisture1, moisture2);
    fclose(fp);

    return 0;
}

// Cleanup resources
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (cs_line_0) {
        gpiod_line_set_value(cs_line_0, 1);
        gpiod_line_release(cs_line_0);
    }
    if (cs_line_1) {
        gpiod_line_set_value(cs_line_1, 1);
        gpiod_line_release(cs_line_1);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Moisture sensor data logger started.\n");

    while (1) {
        // Read moisture sensor values
        int adc_value_1 = read_mcp3008(MOISTURE_SENSOR_1_CHANNEL);
        int adc_value_2 = read_mcp3008(MOISTURE_SENSOR_2_CHANNEL);

        if (adc_value_1 < 0 || adc_value_2 < 0) {
            fprintf(stderr, "Error reading ADC values. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Map ADC values to moisture percentages
        float moisture1 = map_adc_to_moisture(adc_value_1);
        float moisture2 = map_adc_to_moisture(adc_value_2);

        // Log data to CSV file
        if (log_data(moisture1, moisture2) < 0) {
            fprintf(stderr, "Error logging data. Retrying in 5 seconds.\n");
        }

        // Print data to console
        printf("Moisture Sensor 1: %.2f%%, Moisture Sensor 2: %.2f%%\n", moisture1, moisture2);

        // Wait 5 seconds
        sleep(5);
    }

    return 0;
}

