            sleep(1);
            if (gpio_set_shutdown(1) < 0) {
                fprintf(stderr, "Failed to enable motor shutdown\n");
            }
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Program terminated gracefully\n");
    return 0;
}

