#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define PRESSURE_REGISTER 0x00
#define LOG_FILE "pressure_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold program state
typedef struct {
    int i2c_handle;
    FILE *log_file;
    volatile sig_atomic_t terminate;
} ProgramState;

ProgramState state = {-1, NULL, 0};

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get the current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(21 * sizeof(char)); // YYYY-MM-DDTHH:MM:SSZ\0

    if (timestamp == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for timestamp.\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to read pressure data from the MLX90817 sensor
int read_pressure(int i2c_handle, unsigned int *pressure) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: I2C read failed (register 0x%02X, error code %d)\n", PRESSURE_REGISTER, result);
        return -1;
    }

    *pressure = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to convert raw pressure value to kPa
float convert_to_kPa(unsigned int raw_value) {
    return (float)raw_value / 65535.0 * 500.0;
}

// Function to log the pressure reading to a file
int log_pressure(FILE *log_file, const char *timestamp, float pressure_kPa) {
    if (fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main() {
    int result;
    unsigned int raw_pressure;
    float pressure_kPa;
    char *timestamp;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (error code %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
        fflush(log_file);
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read pressure
        if (read_pressure(i2c_handle, &raw_pressure) == 0) {
            // Convert to kPa
            pressure_kPa = convert_to_kPa(raw_pressure);

            // Get timestamp
            timestamp = get_timestamp();
            if (timestamp != NULL) {
                // Log pressure
                if (log_pressure(log_file, timestamp, pressure_kPa) != 0) {
                    fprintf(stderr, "Error: Failed to log pressure.\n");
                }
                free(timestamp);
            } else {
                fprintf(stderr, "Error: Failed to get timestamp.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read pressure.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

