#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8
#define OVERCURRENT_PIN 27
#define ADC_MAX 1023
#define VOLTAGE_MAX 3.3
#define SENSITIVITY 0.066 // 66 mV/A
#define CURRENT_MAX 10.0  // 10A

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
void log_current(float current);
void check_overcurrent(float current);
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    if (adc_value < 0 || adc_value > ADC_MAX) {
        fprintf(stderr, "Error: Invalid ADC value %d\n", adc_value);
        return -1.0;
    }
    return (float)adc_value / ADC_MAX * VOLTAGE_MAX;
}

// Function to convert voltage to current
float voltage_to_current(float voltage) {
    return voltage / SENSITIVITY;
}

// Function to log current reading with timestamp
void log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f A\n", timestamp, current);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

// Function to check for overcurrent condition
void check_overcurrent(float current) {
    if (current > CURRENT_MAX) {
        gpioWrite(OVERCURRENT_PIN, 1); // Set GPIO HIGH
        log_current(current);
        fprintf(stderr, "OVERCURRENT detected! Current: %.2f A\n", current);
        terminate = 1; // Signal termination
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(OVERCURRENT_PIN, PI_OUTPUT);
    gpioWrite(OVERCURRENT_PIN, 0); // Initialize to LOW

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(0); // Read from channel 0
        if (adc_value >= 0) {
            float voltage = adc_to_voltage(adc_value);
            if (voltage >= 0) {
                float current = voltage_to_current(voltage);
                log_current(current);
                check_overcurrent(current);
            }
        }
        gpioDelay(100); // Sample every 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioWrite(OVERCURRENT_PIN, 0); // Reset GPIO
    gpioTerminate();

    printf("Current monitoring stopped.\n");
    return 0;
}

