#define SPI_SCLK 11    // Serial Clock (SCLK)
#define SPI_MOSI 10    // Master Out Slave In (MOSI)
#define SPI_MISO 9     // Master In Slave Out (MISO)
#define ALARM_PIN 4    // Alarm output (GPIO4)

// Define SPI parameters
#define SPI_CHANNEL 0  // SPI channel 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0     // SPI mode 0

// Define CO sensor parameters
#define VREF 3.3       // Reference voltage
#define CO_THRESHOLD 2.5 // CO alarm threshold voltage

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value, float vref);
void set_alarm(int alarm_state);
void log_data(float voltage);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;                  // Don't care

    // Perform SPI transfer
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value, float vref) {
    return (adc_value / 1023.0) * vref;
}

// Function to set the alarm state
void set_alarm(int alarm_state) {
    gpioWrite(ALARM_PIN, alarm_state);
}

// Function to log data to file
void log_data(float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,Voltage: %.2f V\n", timestamp, voltage);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

