#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8
#define NUM_CHANNELS 3
#define SENSITIVITY 0.00300 // 300 mV/g
#define SUPPLY_VOLTAGE 3.3
#define ZERO_G_VOLTAGE 1.65
#define IMPACT_THRESHOLD 2.0
#define LOG_FILE "impact_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float calculate_acceleration(int raw_value);
void log_data(int x, int y, int z, float x_g, float y_g, float z_g);
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select MCP3008
    int spi_result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008

    if (spi_result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", spi_result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate acceleration in g
float calculate_acceleration(int raw_value) {
    float voltage = (float)raw_value / 1023.0 * SUPPLY_VOLTAGE;
    float acceleration = (voltage - ZERO_G_VOLTAGE) / SENSITIVITY;
    return acceleration;
}

// Function to log data to file
void log_data(int x, int y, int z, float x_g, float y_g, float z_g) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%d,%d,%.3f,%.3f,%.3f", timestamp, x, y, z, x_g, y_g, z_g);

    float magnitude = sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
    if (magnitude > IMPACT_THRESHOLD) {
        fprintf(log_file, ",IMPACT DETECTED");
    }

    fprintf(log_file, "\n");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (returned %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008 initially

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        int x_raw = read_adc(0);
        int y_raw = read_adc(1);
        int z_raw = read_adc(2);

        if (x_raw == -1 || y_raw == -1 || z_raw == -1) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        float x_g = calculate_acceleration(x_raw);
        float y_g = calculate_acceleration(y_raw);
        float z_g = calculate_acceleration(z_raw);

        log_data(x_raw, y_raw, z_raw, x_g, y_g, z_g);

        gpioDelay(10); // 100 Hz sampling rate (10 ms delay)
    }

    // Cleanup
    printf("Closing SPI, log file, and terminating pigpio...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

