#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define LOG_FILE "biometric_log.csv"
#define SAMPLE_INTERVAL_MS 1000 // 1 second

// Si1172 Registers
#define SI1172_REG_PART_ID 0x00
#define SI1172_REG_REV_ID 0x01
#define SI1172_REG_SEQ_ID 0x02
#define SI1172_REG_INT_CFG 0x03
#define SI1172_REG_INT_STATUS 0x04
#define SI1172_REG_MEAS_RATE0 0x08
#define SI1172_REG_MEAS_RATE1 0x09
#define SI1172_REG_ALS_RATE0 0x0A
#define SI1172_REG_ALS_RATE1 0x0B
#define SI1172_REG_PS_RATE0 0x0C
#define SI1172_REG_PS_RATE1 0x0D
#define SI1172_REG_PS_LED21_SELECT 0x10
#define SI1172_REG_PS_LED1_SELECT 0x11
#define SI1172_REG_PS_LED2_SELECT 0x12
#define SI1172_REG_PS_LED3_SELECT 0x13
#define SI1172_REG_PS1_ADCMUX 0x14
#define SI1172_REG_PS2_ADCMUX 0x15
#define SI1172_REG_PS3_ADCMUX 0x16
#define SI1172_REG_PS_ADC_GAIN 0x17
#define SI1172_REG_PS_ADC_MISC 0x18
#define SI1172_REG_PS_LED12_SELECT 0x19
#define SI1172_REG_PS_LED3_SELECT 0x1A
#define SI1172_REG_PS_LED4_SELECT 0x1B
#define SI1172_REG_PS_LED5_SELECT 0x1C
#define SI1172_REG_PS_LED6_SELECT 0x1D
#define SI1172_REG_PS_LED7_SELECT 0x1E
#define SI1172_REG_PS_LED8_SELECT 0x1F
#define SI1172_REG_PS_LED9_SELECT 0x20
#define SI1172_REG_PS_LED10_SELECT 0x21
#define SI1172_REG_PS_LED11_SELECT 0x22
#define SI1172_REG_PS_LED12_SELECT 0x23
#define SI1172_REG_PS_LED13_SELECT 0x24
#define SI1172_REG_PS_LED14_SELECT 0x25
#define SI1172_REG_PS_LED15_SELECT 0x26
#define SI1172_REG_PS_LED16_SELECT 0x27
#define SI1172_REG_PS_LED17_SELECT 0x28
#define SI1172_REG_PS_LED18_SELECT 0x29
#define SI1172_REG_PS_LED19_SELECT 0x2A
#define SI1172_REG_PS_LED20_SELECT 0x2B
#define SI1172_REG_PS_LED21_SELECT 0x2C
#define SI1172_REG_PS_LED22_SELECT 0x2D
#define SI1172_REG_PS_LED23_SELECT 0x2E
#define SI1172_REG_PS_LED24_SELECT 0x2F
#define SI1172_REG_PS_LED25_SELECT 0x30
#define SI1172_REG_PS_LED26_SELECT 0x31
#define SI1172_REG_PS_LED27_SELECT 0x32
#define SI1172_REG_PS_LED28_SELECT 0x33
#define SI1172_REG_PS_LED29_SELECT 0x34
#define SI1172_REG_PS_LED30_SELECT 0x35
#define SI1172_REG_PS_LED31_SELECT 0x36
#define SI1172_REG_PS_LED32_SELECT 0x37
#define SI1172_REG_PS_LED33_SELECT 0x38
#define SI1172_REG_PS_LED34_SELECT 0x39
#define SI1172_REG_PS_LED35_SELECT 0x3A
#define SI1172_REG_PS_LED36_SELECT 0x3B
#define SI1172_REG_PS_LED37_SELECT 0x3C
#define SI1172_REG_PS_LED38_SELECT 0x3D
#define SI1172_REG_PS_LED39_SELECT 0x3E
#define SI1172_REG_PS_LED40_SELECT 0x3F
#define SI1172_REG_COMMAND 0xC0
#define SI1172_REG_FIFO_DATA 0xC1
#define SI1172_REG_FIFO_DATA_HIGH 0xC2
#define SI1172_REG_FIFO_DATA_LOW 0xC3
#define SI1172_REG_FIFO_CONFIG 0xC4

// Commands
#define SI1172_CMD_RESET 0x01
#define SI1172_CMD_ALS_FORCE 0x06
#define SI1172_CMD_PS_FORCE 0x07
#define SI1172_CMD_FIFO_READ 0x0F

// Global variables
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(unsigned short *ir, unsigned short *red);
int log_data(time_t timestamp, unsigned short ir, unsigned short red, int error_flag);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize the sensor
int initialize_sensor() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, SI1172_REG_COMMAND, SI1172_CMD_RESET) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, SI1172_REG_MEAS_RATE0, 0x08) < 0) return -1; // Measurement rate
    if (i2cWriteByteData(i2c_handle, SI1172_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS_RATE0, 0x08) < 0) return -1; // Proximity sensing rate
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS_RATE1, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS_LED21_SELECT, 0x03) < 0) return -1; // LED select
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS_LED1_SELECT, 0x03) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS_LED2_SELECT, 0x03) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS_LED3_SELECT, 0x03) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS1_ADCMUX, 0x00) < 0) return -1; // ADC mux
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS2_ADCMUX, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS3_ADCMUX, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS_ADC_GAIN, 0x03) < 0) return -1; // ADC gain
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS_ADC_MISC, 0x00) < 0) return -1;

    return 0;
}

// Read sensor data
int read_sensor_data(unsigned short *ir, unsigned short *red) {
    char buffer[4];

    // Trigger a measurement
    if (i2cWriteByteData(i2c_handle, SI1172_REG_COMMAND, SI1172_CMD_PS_FORCE) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }
    gpioDelay(10); // Wait for measurement to complete

    // Read FIFO data (IR and RED ADC values)
    if (i2cReadI2CBlockData(i2c_handle, SI1172_REG_FIFO_DATA, buffer, 4) != 4) {
        fprintf(stderr, "Error reading FIFO data\n");
        return -1;
    }

    // Combine high and low bytes for IR and RED values
    *ir = (buffer[1] << 8) | buffer[0];
    *red = (buffer[3] << 8) | buffer[2];

    return 0;
}

// Log data to file
int log_data(time_t timestamp, unsigned short ir, unsigned short red, int error_flag) {
    char *timestamp_str = ctime(&timestamp);
    timestamp_str[strlen(timestamp_str) - 1] = '\0'; // Remove trailing newline

    fprintf(log_file, "%s,%u,%u,%d\n", timestamp_str, ir, red, error_flag);
    fflush(log_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,IR,RED,ErrorFlag\n");
    }
    fflush(log_file);

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        log_data(time(NULL), 0, 0, 2); // Log sensor absent error
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    unsigned short ir, red;
    time_t timestamp;
    int read_result;

    while (!terminate) {
        timestamp = time(NULL);
        read_result = read_sensor_data(&ir, &red);

        if (read_result == 0) {
            log_data(timestamp, ir, red, 0); // Log data with no error
        } else {
            fprintf(stderr, "Error reading sensor data\n");
            log_data(timestamp, 0, 0, 1); // Log read error
        }

        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

