    if (i2cWriteByteData(i2c_handle, SI1172_REG_COMMAND, SI1172_CMD_RESET) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, SI1172_REG_MEAS_RATE0, 0x08) < 0) return -1; // Measurement rate
    if (i2cWriteByteData(i2c_handle, SI1172_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS_RATE0, 0x08) < 0) return -1; // Proximity sensing rate
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS_RATE1, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS_LED21_SELECT, 0x03) < 0) return -1; // LED select
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS_LED1_SELECT, 0x03) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS_LED2_SELECT, 0x03) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS_LED3_SELECT, 0x03) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS1_ADCMUX, 0x00) < 0) return -1; // ADC mux
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS2_ADCMUX, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS3_ADCMUX, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS_ADC_GAIN, 0x03) < 0) return -1; // ADC gain
    if (i2cWriteByteData(i2c_handle, SI1172_REG_PS_ADC_MISC, 0x00) < 0) return -1;

    return 0;
}

// Read sensor data
int read_sensor_data(unsigned short *ir, unsigned short *red) {
    char buffer[4];

    // Trigger a measurement
    if (i2cWriteByteData(i2c_handle, SI1172_REG_COMMAND, SI1172_CMD_PS_FORCE) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }
    gpioDelay(10); // Wait for measurement to complete

    // Read FIFO data (IR and RED ADC values)
    if (i2cReadI2CBlockData(i2c_handle, SI1172_REG_FIFO_DATA, buffer, 4) != 4) {
        fprintf(stderr, "Error reading FIFO data\n");
        return -1;
    }

    // Combine high and low bytes for IR and RED values
    *ir = (buffer[1] << 8) | buffer[0];
    *red = (buffer[3] << 8) | buffer[2];

    return 0;
}

// Log data to file
int log_data(time_t timestamp, unsigned short ir, unsigned short red, int error_flag) {
    char *timestamp_str = ctime(&timestamp);
    timestamp_str[strlen(timestamp_str) - 1] = '\0'; // Remove trailing newline

    fprintf(log_file, "%s,%u,%u,%d\n", timestamp_str, ir, red, error_flag);
    fflush(log_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,IR,RED,ErrorFlag\n");
    }
    fflush(log_file);

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        log_data(time(NULL), 0, 0, 2); // Log sensor absent error
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    unsigned short ir, red;
    time_t timestamp;
    int read_result;

    while (!terminate) {
        timestamp = time(NULL);
        read_result = read_sensor_data(&ir, &red);

        if (read_result == 0) {
            log_data(timestamp, ir, red, 0); // Log data with no error
        } else {
            fprintf(stderr, "Error reading sensor data\n");
            log_data(timestamp, 0, 0, 1); // Log read error
        }

        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

