#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define FLOW_LOG_FILE "flow_log.csv"
#define MIN_FLOW_RATE 0.0
#define MAX_FLOW_RATE 5.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_spi_channel();
int read_adc(int channel);
float convert_to_flow_rate(int adc_value);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    int mcp3008_channel;
    const char *log_file_name;
    float min_flow_rate;
    float max_flow_rate;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_BAUD,
    MCP3008_CHANNEL,
    FLOW_LOG_FILE,
    MIN_FLOW_RATE,
    MAX_FLOW_RATE
};

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open SPI channel
int open_spi_channel() {
    spi_handle = spiOpen(config.spi_channel, config.spi_baud, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Convert ADC value to flow rate (L/min)
float convert_to_flow_rate(int adc_value) {
    // Linear scaling: 0-3.3V maps to 0-5.0 L/min
    // Assuming 10-bit ADC (0-1023)
    return (float)adc_value * (MAX_FLOW_RATE / 1023.0);
}

// Log flow rate to file
int log_flow_rate(float flow_rate) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

    if (flow_rate < config.min_flow_rate || flow_rate > config.max_flow_rate) {
        fprintf(stderr, "Error: Flow rate out of range: %.2f L/min\n", flow_rate);
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file);

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open SPI channel
    if (open_spi_channel() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", config.log_file_name);
        cleanup();
        return 1;
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Try again
        }

        float flow_rate = convert_to_flow_rate(adc_value);

        if (log_flow_rate(flow_rate) != 0) {
            fprintf(stderr, "Failed to log flow rate\n");
        }

        gpioDelay(1000); // 1 second delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

