#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Define sensor-specific constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x67
#define MEASUREMENT_COMMAND 0x6845 // High-precision measurement command
#define DATA_LENGTH 6

// Calibration parameters (replace with actual values from your sensor)
#define SENSITIVITY 0.01 // Example sensitivity
#define OFFSET 100.0     // Example offset

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
sensor_data_t process_sensor_data(const uint8_t *data);
int log_data(sensor_data_t data);
void display_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Read sensor data from I2C
int read_sensor_data(uint8_t *data) {
    uint8_t command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    if (write(i2c_fd, command, 2) != 2) {
        perror("Error writing measurement command");
        return -1;
    }

    // Wait for conversion (adjust delay as needed)
    usleep(10000); // 10ms

    if (read(i2c_fd, data, DATA_LENGTH) != DATA_LENGTH) {
        perror("Error reading sensor data");
        return -1;
    }

    return 0;
}

// Process sensor data and convert to temperature and pressure
sensor_data_t process_sensor_data(const uint8_t *data) {
    sensor_data_t processed_data;
    int32_t raw_pressure = (data[0] << 8) | data[1];
    int32_t raw_temperature = (data[3] << 8) | data[4];

    // Apply calibration formulas (replace with actual formulas from the datasheet)
    processed_data.pressure = (float)raw_pressure * SENSITIVITY + OFFSET;
    processed_data.temperature = (float)raw_temperature * SENSITIVITY + OFFSET;

    return processed_data;
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.pressure);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Display data on the console
void display_data(sensor_data_t data) {
    printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", data.temperature, data.pressure);
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Pressure(Pa)\n");
    }

    uint8_t sensor_data[DATA_LENGTH];
    sensor_data_t processed_data;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Process sensor data
            processed_data = process_sensor_data(sensor_data);

            // Log data
            log_data(processed_data);

            // Display data
            display_data(processed_data);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying in 5 seconds.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

