#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define BUZZER_GPIO 18
#define TEMPERATURE_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define VOLTAGE_THRESHOLD 1.0
#define DEFAULT_TEMPERATURE 25.0
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *buzzer_line = NULL;
static int spi_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int spi_read_adc(int channel);
float read_temperature();
float calculate_compensated_voltage(int raw_adc, float temperature);
int is_flame_detected(float compensated_voltage);
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void control_buzzer(int flame_detected);
void signal_handler(int sig);

// SPI read ADC function
int spi_read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];
    int ret;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;
    transfer[0].delay_usecs = 0;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer);
    if (ret < 0) {
        perror("SPI transaction failed");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Temperature reading function
float read_temperature() {
    FILE *fp;
    float temperature;

    fp = fopen(TEMPERATURE_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open temperature file");
        return DEFAULT_TEMPERATURE;
    }

    if (fscanf(fp, "%f", &temperature) != 1) {
        fprintf(stderr, "Invalid temperature format in file\n");
        fclose(fp);
        return DEFAULT_TEMPERATURE;
    }

    fclose(fp);
    return temperature;
}

// Voltage compensation function
float calculate_compensated_voltage(int raw_adc, float temperature) {
    float voltage = (float)raw_adc * 3.3 / 1024.0;
    return voltage + (temperature - 25.0) * 0.001;
}

// Flame detection function
int is_flame_detected(float compensated_voltage) {
    return (compensated_voltage > VOLTAGE_THRESHOLD) ? 1 : 0;
}

// Data logging function
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Buzzer control function
void control_buzzer(int flame_detected) {
    int ret;
    if (flame_detected) {
        ret = gpiod_line_set_value(buzzer_line, 1); // Turn buzzer ON
        if (ret < 0) {
            perror("Failed to set buzzer ON");
        }
    } else {
        ret = gpiod_line_set_value(buzzer_line, 0); // Turn buzzer OFF
        if (ret < 0) {
            perror("Failed to set buzzer OFF");
        }
    }
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

int main() {
    int raw_adc;
    float voltage, compensated_voltage, temperature;
    int flame_detected;
    int ret;

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        perror("Failed to get buzzer GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(buzzer_line, "flame_sensor", 0); // Request GPIO as output
    if (ret < 0) {
        perror("Failed to request buzzer GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure SPI mode
    unsigned int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
