// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 17
#define WATER_LEVEL_THRESHOLD_HIGH 75.0
#define WATER_LEVEL_THRESHOLD_LOW 70.0
#define JSON_FILE "water_levels.json"
#define SLEEP_MS 5000 // 5 seconds

// Global variables
int spi_handle;
FILE *json_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_percentage(int adc_value);
void log_to_json(float percentage);
void control_led(float percentage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx[3];
    char rx[3];

    tx[0] = 0x01; // Start bit
    tx[1] = 0x80 | (channel << 4); // Single-ended mode, channel select
    tx[2] = 0x00; // Padding

    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result < 0) {
        pigpio_error(result, "SPI transfer failed");
        return -1; // Indicate error
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

// Function to convert ADC value to percentage
float convert_to_percentage(int adc_value) {
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to log water level to JSON file
void log_to_json(float percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.000Z", timeinfo);

    fprintf(json_file, "{\"timestamp\": \"%s\", \"water_level\": %.2f}\n", timestamp, percentage);
    fflush(json_file);
}

// Function to control the LED based on water level
void control_led(float percentage) {
    static int led_on = 0; // Track LED state

    if (percentage > WATER_LEVEL_THRESHOLD_HIGH && !led_on) {
        gpioWrite(LED_GPIO, 1); // Turn LED ON
        led_on = 1;
        printf("Water level above %.2f%%, turning LED ON\n", WATER_LEVEL_THRESHOLD_HIGH);
    } else if (percentage < WATER_LEVEL_THRESHOLD_LOW && led_on) {
        gpioWrite(LED_GPIO, 0); // Turn LED OFF
        led_on = 0;
        printf("Water level below %.2f%%, turning LED OFF\n", WATER_LEVEL_THRESHOLD_LOW);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        pigpio_error(spi_handle, "SPI open failed");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open JSON file for logging
    json_file = fopen(JSON_FILE, "a+");
    if (json_file == NULL) {
        perror("Failed to open JSON file");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, add the opening bracket
    fseek(json_file, 0, SEEK_END);
    long file_size = ftell(json_file);
    if (file_size == 0) {
        fprintf(json_file, "[");
    } else {
        // If not empty, go back one character and check if it's a closing bracket. If so, remove it.
        fseek(json_file, -1, SEEK_END);
        char last_char;
        fread(&last_char, 1, 1, json_file);
        if (last_char == ']') {
            fseek(json_file, -1, SEEK_END);
            ftruncate(fileno(json_file), file_size - 1);
        }
        fprintf(json_file, ","); // Add a comma before the new entry
    }
    fflush(json_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float percentage = convert_to_percentage(adc_value);
            printf("Water level: %.2f%%\n", percentage);
            log_to_json(percentage);
            control_led(percentage);
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        gpioDelay(SLEEP_MS * 1000); // Sleep for 5 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    fprintf(json_file, "]"); // Close the JSON array
    fclose(json_file);
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

