// Default values
#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_RAW 300
#define DEFAULT_MAX_RAW 700
#define DEFAULT_MOISTURE_THRESHOLD 30
#define DEFAULT_LOGGING_FREQUENCY 60
#define DEFAULT_RECIPIENT_EMAIL "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG_FILE "/etc/msmtprc"

// Global variables
int spi_handle;
int spi_channel = DEFAULT_SPI_CHANNEL;
int adc_channel = DEFAULT_ADC_CHANNEL;
int min_raw = DEFAULT_MIN_RAW;
int max_raw = DEFAULT_MAX_RAW;
int moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
int logging_frequency = DEFAULT_LOGGING_FREQUENCY;
char recipient_email[256] = DEFAULT_RECIPIENT_EMAIL;
char msmtp_config_file[256] = DEFAULT_MSMTP_CONFIG_FILE;

// Function prototypes
int read_mcp3008(int spi_handle, int channel);
float calculate_moisture_percentage(int raw_value, int min_raw, int max_raw);
void log_data(float moisture_percentage);
void send_email_alert(float moisture_percentage);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

// Reads the MCP3008 ADC value from the specified channel
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Calculates the moisture percentage based on the raw ADC value
float calculate_moisture_percentage(int raw_value, int min_raw, int max_raw) {
    float percentage = 100.0 - ((float)(raw_value - min_raw) / (float)(max_raw - min_raw)) * 100.0;
    if (percentage < 0.0) {
        percentage = 0.0;
    } else if (percentage > 100.0) {
        percentage = 100.0;
    }
    return percentage;
}

// Logs the timestamp and moisture percentage to plant_data.txt
void log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("plant_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open plant_data.txt for writing\n");
        return;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);
}

// Sends an email alert using msmtp
void send_email_alert(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    char command[512];
    snprintf(command, sizeof(command), "echo \"Subject: Plant Moisture Alert\n\nPlant moisture level dropped below %d%% at %s. Current moisture: %.2f%%\" | msmtp -C %s %s",
             moisture_threshold, timestamp, moisture_percentage, msmtp_config_file, recipient_email);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not execute msmtp command\n");
        return;
    }

    int status = pclose(fp);
    if (status != 0) {
        fprintf(stderr, "Error: msmtp command failed with status %d\n", status);
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "s:a:m:x:t:l:e:c:")) != -1) {
        switch (opt) {
            case 's':
                spi_channel = atoi(optarg);
                break;
            case 'a':
                adc_channel = atoi(optarg);
                break;
            case 'm':
                min_raw = atoi(optarg);
                break;
            case 'x':
                max_raw = atoi(optarg);
                break;
            case 't':
                moisture_threshold = atoi(optarg);
                break;
            case 'l':
                logging_frequency = atoi(optarg);
                break;
            case 'e':
                strncpy(recipient_email, optarg, sizeof(recipient_email) - 1);
                recipient_email[sizeof(recipient_email) - 1] = '\0'; // Ensure null termination
                break;
            case 'c':
                strncpy(msmtp_config_file, optarg, sizeof(msmtp_config_file) - 1);
                msmtp_config_file[sizeof(msmtp_config_file) - 1] = '\0'; // Ensure null termination
                break;
            default:
                fprintf(stderr, "Usage: %s [-s spi_channel] [-a adc_channel] [-m min_raw] [-x max_raw] [-t moisture_threshold] [-l logging_frequency] [-e recipient_email] [-c msmtp_config_file]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(spi_channel, 500000, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int raw_value = read_mcp3008(spi_handle, adc_channel);
        if (raw_value >= 0) {
            float moisture_percentage = calculate_moisture_percentage(raw_value, min_raw, max_raw);
            log_data(moisture_percentage);

            if (moisture_percentage < moisture_threshold) {
                send_email_alert(moisture_percentage);
            }
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        sleep(logging_frequency);
    }

    return 0;
}

