float calculate_moisture_percentage(int adc_value) {
    float percentage = 100.0 - ((float)(adc_value - WET_ADC) / (float)(DRY_ADC - WET_ADC)) * 100.0;

    // Clamp percentage between 0 and 100
    if (percentage < 0.0) {
        percentage = 0.0;
    } else if (percentage > 100.0) {
        percentage = 100.0;
    }

    return percentage;
}

