#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define CS_PIN 8
#define CS_CHIP_SELECT_PIN "GPIO8_12"
#define CS_CHIP_SELECT_CHIP "gpiochip0"
#define CS_CHIP_SELECT_LINE 8
#define CS_CHIP_SELECT_LINE_REQUEST_NAME "mcp3008_cs"

// Global variables
static volatile int keep_running = 1;
static int spi_fd = -1;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int spi_init(void);
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_mcp3008(int channel);
float voltage_convert(int adc_value);
void log_data(float v0, float v1, float v2, float v3);
void signal_handler(int sig);
int gpio_init(void);
int gpio_deinit(void);

// SPI initialization function
int spi_init(void) {
    int ret;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read MCP3008 channel function
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    if (gpio_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error setting CS low\n");
        return -1;
    }

    if (spi_transfer(tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        if (gpio_line_set_value(cs_line, 1) < 0) {
            fprintf(stderr, "Error setting CS high\n");
        }
        return -1;
    }

    if (gpio_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error setting CS high\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Convert ADC value to voltage function
float voltage_convert(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Log data to CSV file function
void log_data(float v0, float v1, float v2, float v3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, v0, v1, v2, v3);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    keep_running = 0;
}

// GPIO initialization function
int gpio_init(void) {
    struct gpiod_chip *chip;

    chip = gpiod_chip_open_by_name(CS_CHIP_SELECT_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_CHIP_SELECT_LINE);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpio_line_request_output(cs_line, CS_CHIP_SELECT_LINE_REQUEST_NAME, 1) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// GPIO deinitialization function
int gpio_deinit(void) {
    if (cs_line) {
        gpio_line_release(cs_line);
    }
    return 0;
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return EXIT_FAILURE;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpio_deinit();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpio_deinit();
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        int adc_values[4];
        float voltages[4];

        // Read ADC values from MCP3008 channels
        for (int i = 0; i < 4; i++) {
            adc_values[i] = read_mcp3008(i);
            if (adc_values[i] < 0) {
                fprintf(stderr, "Error reading channel %d\n", i);
                continue; // Skip to the next channel
            }
            voltages[i] = voltage_convert(adc_values[i]);
        }

        // Log data
        log_data(voltages[0], voltages[1], voltages[2], voltages[3]);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    close(spi_fd);
    gpio_deinit();

    return EXIT_SUCCESS;
}

