// Define GPIO pins
#define PUMP_PIN 17
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define moisture thresholds
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600

// Define circular buffer size
#define BUFFER_SIZE 20

// Structure for log entry
typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

// Circular buffer
LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int spi_handle;
int pump_state = 0; // 0 = off, 1 = on

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_data(int moisture_level, int pump_state);
void print_log();
void timer_callback();
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    if (gpioWrite(PUMP_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", PUMP_PIN);
    }
    pump_state = state;
}

// Function to log data to the circular buffer
void log_data(int moisture_level, int pump_state) {
    time_t now = time(NULL);
    log_buffer[buffer_index].timestamp = now;
    log_buffer[buffer_index].moisture_level = moisture_level;
    log_buffer[buffer_index].pump_state = pump_state;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the log buffer
void print_log() {
    printf("\n--- Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Correct order
        struct tm *timeinfo = localtime(&log_buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Moisture: %d, Pump: %s\n", timestamp_str, log_buffer[index].moisture_level, log_buffer[index].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log ---\n");
}

// Timer callback function
void timer_callback() {
    int moisture_level = read_mcp3008(0);
    if (moisture_level == -1) {
        fprintf(stderr, "Failed to read moisture level\n");
        return;
    }

    if (moisture_level < LOW_THRESHOLD && pump_state == 0) {
        control_pump(1);
        log_data(moisture_level, 1);
        print_log();
    } else if (moisture_level > HIGH_THRESHOLD && pump_state == 1) {
        control_pump(0);
        log_data(moisture_level, 0);
        print_log();
    } else {
        log_data(moisture_level, pump_state);
        print_log();
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PUMP_PIN, PI_OUTPUT);
    gpioSetMode(SPI_MOSI, PI_OUTPUT);
    gpioSetMode(SPI_MISO, PI_INPUT);
    gpioSetMode(SPI_SCLK, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback
    gpioSetTimerFunc(0, 5000, timer_callback); // 5-second interval

    // Main loop
    while (1) {
        gpioDelay(100); // Small delay to prevent busy-waiting
    }

    return 0;
}

