#define LED2_PA_VALUE 0x24      // 50mA

// Define logging constants
#define LOG_FILE "health_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int red_sum;
    int ir_sum;
    int count;
} sensor_data_t;

