    int status;

    // Check Part ID
    status = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading Part ID: %d\n", status);
        return -1;
    }
    if (status != PART_ID_VALUE) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X (expected 0x%02X)\n", status, PART_ID_VALUE);
        return -1;
    }
    printf("Part ID: 0x%02X\n", status);

    // Reset sensor
    status = i2cWriteByteData(i2c_handle, MODE_CONFIG_REG, 0x40); // Reset
    if (status < 0) {
        fprintf(stderr, "Error resetting sensor: %d\n", status);
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure SpO2 mode
    status = i2cWriteByteData(i2c_handle, MODE_CONFIG_REG, 0x03); // SpO2 mode
    if (status < 0) {
        fprintf(stderr, "Error configuring SpO2 mode: %d\n", status);
        return -1;
    }

    // Configure SpO2 parameters
    status = i2cWriteByteData(i2c_handle, SPO2_CONFIG_REG, SPO2_CONFIG_VALUE);
    if (status < 0) {
        fprintf(stderr, "Error configuring SpO2 parameters: %d\n", status);
        return -1;
    }

    // Set LED pulse amplitudes
    status = i2cWriteByteData(i2c_handle, LED1_PA_REG, LED1_PA_VALUE);
    if (status < 0) {
        fprintf(stderr, "Error setting LED1 pulse amplitude: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, LED2_PA_REG, LED2_PA_VALUE);
    if (status < 0) {
        fprintf(stderr, "Error setting LED2 pulse amplitude: %d\n", status);
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

