int read_sensor_data(sensor_data_t *data) {
    char buffer[6];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, FIFO_DATA_REG, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading FIFO data: %d\n", status);
        return -1;
    }

    // Extract red and IR values from the buffer
    int red = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
    int ir = (buffer[3] << 16) | (buffer[4] << 8) | buffer[5];

    // Basic data validation
    if (red < 0 || red > 65535 || ir < 0 || ir > 65535) {
        fprintf(stderr, "Invalid sensor data: red=%d, ir=%d\n", red, ir);
        return -1;
    }

    data->red_sum += red;
    data->ir_sum += ir;
    data->count++;

    return 0;
}

