    int status;
    sensor_data_t sensor_data = {0, 0, 0};
    float spo2;
    int heart_rate;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Calculate SpO2 and heart rate
            spo2 = calculate_spo2(sensor_data.red_sum / sensor_data.count, sensor_data.ir_sum / sensor_data.count);
            heart_rate = calculate_heart_rate(sensor_data.ir_sum / sensor_data.count);

            // Log data
            log_data(spo2, heart_rate);

            printf("SpO2: %.2f, Heart Rate: %d BPM\n", spo2, heart_rate);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Reset sensor data
        sensor_data.red_sum = 0;
        sensor_data.ir_sum = 0;
        sensor_data.count = 0;

        // Wait for 1 second
        gpioDelay(1000); // 1000 milliseconds = 1 second
    }

    // Clean up resources
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

