    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    // Reset GPIO states
    gpioSetMode(BUZZER_PIN, PI_INPUT); // Set buzzer pin to input to avoid leaving it high
    gpioSetMode(SPI_CE0_PIN, PI_INPUT); // Set CE0 pin to input

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

