    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Configure buzzer pin as output
    int result = gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output with code %d\n", BUZZER_PIN, result);
        gpioTerminate();
        return 1;
    }

    // Configure CE0 pin as output
    result = gpioSetMode(SPI_CE0_PIN, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output with code %d\n", SPI_CE0_PIN, result);
        gpioTerminate();
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0); // Channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Gas sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Continue to the next iteration
        }

        // Control buzzer based on threshold
        if (adc_value < GAS_THRESHOLD) {
            control_buzzer(0); // Turn buzzer OFF
