            control_buzzer(1); // Turn buzzer ON
        }

        // Print ADC value and buzzer state
        printf("ADC Value: %d, Buzzer: %s\n", adc_value, (adc_value < GAS_THRESHOLD) ? "OFF" : "ON");

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    return 0;
}

