#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_FULL_SCALE_VOLTAGE 4.096
#define ADS1115_SINGLE_CONVERSION_START 0x8000
#define ADS1115_PGA_4_096V 0x0000
#define ADS1115_MODE_SINGLE 0x0100
#define ADS1115_DR_128SPS 0x0080
#define ADS1115_COMP_MODE_TRADITIONAL 0x0000
#define ADS1115_COMP_POL_ACTIVE_LOW 0x0000
#define ADS1115_COMP_LAT_NON_LATCHING 0x0000
#define ADS1115_COMP_QUE_DISABLE 0x0003
#define ADS1115_CONFIG_DEFAULT (ADS1115_SINGLE_CONVERSION_START | ADS1115_PGA_4_096V | ADS1115_MODE_SINGLE | ADS1115_DR_128SPS | ADS1115_COMP_MODE_TRADITIONAL | ADS1115_COMP_POL_ACTIVE_LOW | ADS1115_COMP_LAT_NON_LATCHING | ADS1115_COMP_QUE_DISABLE)

#define RELAY_GPIO 17
#define REED_SENSOR_GPIO 27

#define NUM_BASELINE_SAMPLES 10
#define BASELINE_SAMPLE_INTERVAL_MS 50
#define TRIGGER_THRESHOLD_PERCENT 80
#define RELAY_ACTIVATION_DURATION_S 3
#define POLL_INTERVAL_MS 200

#define LOG_FILE "/var/log/door_events.log"

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *reed_sensor_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int fd, int *value);
double calculate_distance(int adc_value);
double calculate_baseline(int fd);
int control_relay(struct gpiod_line *line, int state);
int read_reed_sensor(struct gpiod_line *line);
void log_event(const char *event);
void signal_handler(int sig);

// Function to read ADC value from ADS1115
int read_adc(int fd, int *value) {
    unsigned char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (ADS1115_CONFIG_DEFAULT >> 8) & 0xFF;
    buf[2] = ADS1115_CONFIG_DEFAULT & 0xFF;

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write config to ADS1115");
        return -1;
    }

    usleep(10000); // Wait for conversion

    buf[0] = ADS1115_REG_CONVERT;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write read request to ADS1115");
        return -1;
    }

    unsigned char read_buf[2];
    if (read(fd, read_buf, 2) != 2) {
        perror("Failed to read ADC value from ADS1115");
        return -1;
    }

    *value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Function to calculate distance from ADC value (using inverse relationship)
double calculate_distance(int adc_value) {
    // This is a simplified approximation.  A more accurate model
    // would involve a lookup table or a more complex equation.
    // The GP2Y0A21YK0F has a non-linear relationship between voltage and distance.
    // This is a simplified linear approximation.
    // Assuming 0.5V = 200mm, 4.096V = 20mm
    // y = mx + c
    // 200 = 0.5 * m + c
    // 20 = 4.096 * m + c
    // m = (20 - 200) / (4.096 - 0.5)
    // c = 200 - 0.5 * m
    // y = 1000 * x + 1000
    // x = (y - 1000) / 1000
    // y = 1000 * (1 - exp(-x/100))
    // x = 100 * log(y/1000)
    // x = 100 * log(adc_value/4096)
    // distance = 100 * log(adc_value/4096)
    if (adc_value <= 0) return 1000.0; // Return a large value if ADC value is invalid
    return 100.0 * log10((double)adc_value / 4096.0);
}

// Function to calculate baseline distance
double calculate_baseline(int fd) {
    int adc_value;
    double sum = 0.0;
    for (int i = 0; i < NUM_BASELINE_SAMPLES; i++) {
        if (read_adc(fd, &adc_value) == 0) {
            sum += calculate_distance(adc_value);
        } else {
            log_event("Error reading ADC during baseline calculation.");
            return -1.0; // Indicate error
        }
        usleep(BASELINE_SAMPLE_INTERVAL_MS * 1000);
    }
    return sum / NUM_BASELINE_SAMPLES;
}

// Function to control the relay
