int read_adc(int fd, int *value) {
    unsigned char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (ADS1115_CONFIG_DEFAULT >> 8) & 0xFF;
    buf[2] = ADS1115_CONFIG_DEFAULT & 0xFF;

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write config to ADS1115");
        return -1;
    }

    usleep(10000); // Wait for conversion

    buf[0] = ADS1115_REG_CONVERT;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write read request to ADS1115");
        return -1;
    }

    unsigned char read_buf[2];
    if (read(fd, read_buf, 2) != 2) {
        perror("Failed to read ADC value from ADS1115");
        return -1;
    }

    *value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

