// Define the number of bytes to send to the MCP3008
#define SPI_TX_LEN 3

// Define the number of bytes to receive from the MCP3008
#define SPI_RX_LEN 3

// Global variables for file descriptors and GPIO lines
int spi_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *cs0_line = NULL;
struct gpiod_line *cs1_line = NULL;
struct gpiod_line *cs2_line = NULL;

// Function prototypes
int read_mcp3008(int chip_select_pin, int channel);
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int sensor3_value);
void signal_handler(int signal);
int setup_gpio(void);
void cleanup_gpio(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

// Function to set up GPIO lines
int setup_gpio(void) {
    int ret;

    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs0_line = gpiod_chip_get_line(gpio_chip, CS0_PIN);
    cs1_line = gpiod_chip_get_line(gpio_chip, CS1_PIN);
    cs2_line = gpiod_chip_get_line(gpio_chip, CS2_PIN);

    if (!cs0_line || !cs1_line || !cs2_line) {
        perror("Error getting GPIO line");
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(cs0_line, "soil_moisture_logger", 1); // Initial value HIGH
    if (ret < 0) {
        perror("Error requesting GPIO line CS0");
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(cs1_line, "soil_moisture_logger", 1); // Initial value HIGH
    if (ret < 0) {
        perror("Error requesting GPIO line CS1");
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(cs2_line, "soil_moisture_logger", 1); // Initial value HIGH
    if (ret < 0) {
        perror("Error requesting GPIO line CS2");
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Function to clean up GPIO lines
void cleanup_gpio(void) {
    if (cs0_line) {
        gpiod_line_release(cs0_line);
    }
    if (cs1_line) {
        gpiod_line_release(cs1_line);
    }
    if (cs2_line) {
        gpiod_line_release(cs2_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

// Function to read from MCP3008 ADC
int read_mcp3008(int chip_select_pin, int channel) {
    unsigned char tx_buf[SPI_TX_LEN];
    unsigned char rx_buf[SPI_RX_LEN];
    struct spi_ioc_transfer transfer[1];
    int ret;

    // Construct the SPI message to send to the MCP3008
    tx_buf[0] = 0x01;                           // Start bit
    tx_buf[1] = (0x08 | channel) << 4;           // Single-ended mode, channel selection
    tx_buf[2] = 0x00;                           // Don't care

    // Configure the SPI transfer
    memset(transfer, 0, sizeof(transfer));
    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = SPI_TX_LEN;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;
    transfer[0].delay_usecs = 0;

    // Set chip select low
    if (chip_select_pin == CS0_PIN) {
        gpiod_line_set_value(cs0_line, 0);
    } else if (chip_select_pin == CS1_PIN) {
        gpiod_line_set_value(cs1_line, 0);
    } else if (chip_select_pin == CS2_PIN) {
        gpiod_line_set_value(cs2_line, 0);
    } else {
        fprintf(stderr, "Invalid chip select pin: %d\n", chip_select_pin);
        return -1;
    }

    // Perform the SPI transfer
    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer);
    if (ret < 0) {
        perror("Error during SPI transfer");
        if (chip_select_pin == CS0_PIN) {
            gpiod_line_set_value(cs0_line, 1);
        } else if (chip_select_pin == CS1_PIN) {
            gpiod_line_set_value(cs1_line, 1);
        } else if (chip_select_pin == CS2_PIN) {
            gpiod_line_set_value(cs2_line, 1);
        }
        return -1;
    }

    // Set chip select high
    if (chip_select_pin == CS0_PIN) {
        gpiod_line_set_value(cs0_line, 1);
    } else if (chip_select_pin == CS1_PIN) {
        gpiod_line_set_value(cs1_line, 1);
    } else if (chip_select_pin == CS2_PIN) {
        gpiod_line_set_value(cs2_line, 1);
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to log data to a CSV file
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int sensor3_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, sensor3_value) < 0) {
        perror("Error writing to file");
        return -1;
    }

    return 0;
}

int main() {
    FILE *fp;
    int sensor1_value, sensor2_value, sensor3_value;
    int ret;

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    // Open the SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        cleanup_gpio();
        return 1;
    }

    // Configure SPI mode
    unsigned char mode = SPI_MODE;
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        cleanup_gpio();
        return 1;
    }

    // Configure SPI speed
    unsigned int speed = SPI_SPEED;
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        cleanup_gpio();
        return 1;
    }

    // Open the CSV file in append mode
    fp = fopen("soil_moisture_log.csv", "a");
    if (fp == NULL) {
        perror("Error opening file");
        close(spi_fd);
        cleanup_gpio();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n");
    }
    fseek(fp, 0, SEEK_END);

    // Main loop to read and log data
    while (1) {
        // Read sensor values from each MCP3008 chip
        sensor1_value = read_mcp3008(CS0_PIN, 0);
        sensor2_value = read_mcp3008(CS1_PIN, 0);
        sensor3_value = read_mcp3008(CS2_PIN, 0);

        // Log the data to the CSV file
        if (log_data(fp, sensor1_value, sensor2_value, sensor3_value) < 0) {
            fprintf(stderr, "Error logging data. Continuing.\n");
        }

        fflush(fp); // Flush the buffer to ensure data is written to the file

        // Wait for 5 seconds
        sleep(5);
    }

    // The following lines will never be reached because of the infinite loop.
    fclose(fp);
    close(spi_fd);
    cleanup_gpio();

    return 0;
}

