#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define DRY_ADC_VALUE 200
#define WET_ADC_VALUE 800
#define DEFAULT_THRESHOLD 30.0
#define DEFAULT_DURATION 10
#define DEFAULT_INTERVAL 60
#define MAX_RETRIES 3

// Global variables
int spi_handle;
double moisture_threshold = DEFAULT_THRESHOLD;
int pump_duration = DEFAULT_DURATION;
int sleep_interval = DEFAULT_INTERVAL;
FILE *log_file;

// Function prototypes
int read_mcp3008(int channel);
double adc_to_moisture(int adc_value);
void control_pump(int state);
void log_message(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message("Error: Invalid MCP3008 channel.");
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    for (int i = 0; i < MAX_RETRIES; ++i) {
        if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) == 0) {
            // Extract ADC value (10 bits)
            int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            char error_message[100];
            sprintf(error_message, "SPI read error (attempt %d): %d", i + 1, spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3));
            log_message(error_message);
            gpioDelay(100000); // Wait 100ms before retrying
        }
    }

    log_message("Error: Max retries reached for SPI read.");
    return -1; // Indicate failure
}

// Function to convert ADC value to moisture percentage
double adc_to_moisture(int adc_value) {
    double moisture = 100.0 - ((double)(adc_value - DRY_ADC_VALUE) / (WET_ADC_VALUE - DRY_ADC_VALUE)) * 100.0;
    if (moisture < 0.0) moisture = 0.0;
    if (moisture > 100.0) moisture = 100.0;
    return moisture;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    char message[50];
    sprintf(message, "Pump %s", state ? "activated" : "deactivated");
    log_message(message);
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    char message[50];
    sprintf(message, "Received signal %d, shutting down...", signal);
    log_message(message);
    cleanup();
    exit(0);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_message("System initialized.");
    return 0;
}

// Cleanup function
void cleanup() {
    log_message("Cleaning up...");
    control_pump(0); // Turn off the pump
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                moisture_threshold = atof(optarg);
                break;
            case 'd':
                pump_duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s interval]\n", argv[0]);
                return 1;
        }
    }

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read soil moisture
        int adc_value = read_mcp3008(0);
        if (adc_value == -1) {
            log_message("Error reading soil moisture, skipping irrigation cycle.");
        } else {
            double moisture = adc_to_moisture(adc_value);
            char message[100];
            sprintf(message, "Moisture: %.2f%% (ADC: %d)", moisture, adc_value);
            log_message(message);

            // Irrigation logic
            if (moisture < moisture_threshold) {
                log_message("Moisture below threshold, activating pump.");
                control_pump(1);
                gpioDelay(pump_duration * 1000000); // Pump duration in microseconds
                control_pump(0);
            }
        }

        // Sleep for the specified interval
        gpioDelay(sleep_interval * 1000000); // Interval in microseconds
    }

    return 0; // This line will never be reached due to the infinite loop, but it's good practice to include it.
}

