#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48

// Define the control byte for single-ended mode on AIN0
#define PCF8591_CTRL_BYTE 0x40 // Enable AIN0, disable analog output

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler for SIGINT (Ctrl-C)
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
        printf("I2C device closed.\n");
    }
    exit(0);
}

// Function to read a single byte from the PCF8591
int read_pcf8591(int fd) {
    unsigned char buf[1];
    int result;

    // Write the control byte to the PCF8591
    result = write(fd, &PCF8591_CTRL_BYTE, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Read a dummy byte to clear the bus
    buf[0] = 0; // Dummy value
    result = write(fd, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing dummy byte to I2C device: %s\n", strerror(errno));
        return -1;
    }
    result = read(fd, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Read the actual byte
    result = read(fd, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return buf[0];
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("PCF8591 monitoring started. Press Ctrl-C to exit.\n");

    // Main loop
    while (1) {
        int value = read_pcf8591(i2c_fd);
        if (value >= 0) {
            printf("AIN0: %d\n", value);
        } else {
            fprintf(stderr, "Error reading PCF8591 value.\n");
        }

        usleep(100000); // 100 ms
    }

    return 0;
}

