#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_FULL_SCALE_VOLTAGE 4.096 // +/- 4.096V
#define ADS1115_SINGLE_SHOT_MODE 0x8000
#define ADS1115_PGA_4_096V 0x0000
#define ADS1115_MUX_AIN0_GND 0x4000
#define ADS1115_128SPS 0x0080
#define GPIO_SHUTDOWN 27
#define THRESHOLD 500.0 // Gauss
#define BUFFER_SIZE 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float magnetic_field_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_adc(int *raw_value);
float convert_to_voltage(int raw_value);
float convert_to_gauss(float voltage);
void add_to_buffer(float gauss);
float calculate_average();
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    syslog(LOG_INFO, "pigpio initialised");
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }
    syslog(LOG_INFO, "I2C device opened");
    return 0;
}

// Function to read from the ADC
int read_adc(int *raw_value) {
    unsigned char config[3];
    unsigned char buf[2];
    int16_t conv;

    // Configure ADS1115 for single-shot mode, AIN0, +/-4.096V, 128 SPS
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_SINGLE_SHOT_MODE | ADS1115_MUX_AIN0_GND | ADS1115_PGA_4_096V | ADS1115_128SPS) >> 8;
    config[2] = (ADS1115_SINGLE_SHOT_MODE | ADS1115_MUX_AIN0_GND | ADS1115_PGA_4_096V | ADS1115_128SPS) & 0xFF;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        syslog(LOG_ERR, "Failed to write to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion result
    config[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        syslog(LOG_ERR, "Failed to write to I2C device");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        syslog(LOG_ERR, "Failed to read from I2C device");
        return -1;
    }

    conv = (buf[0] << 8) | buf[1];
    *raw_value = (int)conv;

    return 0;
}

// Function to convert raw ADC value to voltage
float convert_to_voltage(int raw_value) {
    float voltage = (float)raw_value * ADS1115_FULL_SCALE_VOLTAGE / 32768.0;
    return voltage;
}

// Function to convert voltage to magnetic field strength (Gauss)
float convert_to_gauss(float voltage) {
    // Assuming zero-field output is 2.5 V and sensitivity is 1.4 mV/Gauss
    // Gauss = (Voltage - ZeroFieldOutput) / Sensitivity
    float zero_field_output = 2.5;
    float sensitivity = 0.0014; // 1.4 mV/Gauss
    float gauss = (voltage - zero_field_output) / sensitivity;
    return gauss;
}

// Function to add a value to the circular buffer
void add_to_buffer(float gauss) {
    magnetic_field_buffer[buffer_index] = gauss;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the rolling average of the buffer
float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += magnetic_field_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    gpioWrite(GPIO_SHUTDOWN, 0); // Set GPIO LOW
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("magnetic_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, 0); // Initially LOW

    int raw_value;
    float voltage;
    float gauss;
    float average_gauss;

    // Main loop
    while (!terminate) {
        // Read ADC value
        if (read_adc(&raw_value) == 0) {
            // Convert to voltage
            voltage = convert_to_voltage(raw_value);

            // Validate voltage
            if (voltage >= 0.0 && voltage <= 3.3) {
                // Convert to Gauss
                gauss = convert_to_gauss(voltage);

                // Add to buffer
                add_to_buffer(gauss);

                // Calculate average
                average_gauss = calculate_average();

                // Log data
                syslog(LOG_INFO, "Raw: %d, Voltage: %.3f V, Gauss: %.3f, Average Gauss: %.3f", raw_value, voltage, gauss, average_gauss);

                // Check threshold
                if (average_gauss > THRESHOLD) {
                    syslog(LOG_WARNING, "Threshold exceeded! Average Gauss: %.3f", average_gauss);
                    gpioWrite(GPIO_SHUTDOWN, 1); // Set GPIO HIGH
                } else {
                    gpioWrite(GPIO_SHUTDOWN, 0); // Set GPIO LOW
                }
            } else {
                syslog(LOG_ERR, "Invalid voltage reading: %.3f V", voltage);
            }
        } else {
            syslog(LOG_ERR, "Failed to read ADC value");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

