#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 18
#define MOISTURE_THRESHOLD 300
#define PUMP_DURATION 10 // seconds
#define SLEEP_INTERVAL 60 // seconds
#define MAX_RETRIES 3
#define MAX_ADC_VALUE 1023 // 10-bit ADC

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_event(int moisture_level);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int retries = 0;
    int result = -1;

    while (retries < MAX_RETRIES) {
        result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
        if (result == 3) {
            // Extract ADC value (10 bits)
            int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

            // Validate ADC value
            if (adc_value >= 0 && adc_value <= MAX_ADC_VALUE) {
                return adc_value;
            } else {
                fprintf(stderr, "Error: Invalid ADC value %d (attempt %d)\n", adc_value, retries + 1);
            }
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d), result = %d\n", retries + 1, result);
        }

        retries++;
        gpioDelay(1000); // Wait 1ms before retrying
    }

    fprintf(stderr, "Error: Failed to read ADC after %d retries\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
}

// Function to log events to file
void log_event(int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Moisture Level: %d\n", timestamp, moisture_level);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("watering_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read soil moisture
        int moisture_level = read_mcp3008(0);
        if (moisture_level == -1) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
        } else {
            printf("Moisture Level: %d\n", moisture_level);

            // Log event
            log_event(moisture_level);

            // Control pump
            if (moisture_level < MOISTURE_THRESHOLD) {
                printf("Moisture below threshold, activating pump.\n");
                control_pump(1); // Turn pump on
                gpioDelay(PUMP_DURATION * 1000); // Wait for pump duration
                control_pump(0); // Turn pump off
                printf("Pump deactivated.\n");
            }
        }

        // Sleep for specified interval
        gpioDelay(SLEEP_INTERVAL * 1000);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

