#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // YL-83 sensor connected to CH0
#define MAX_RETRIES 3

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int map_adc_to_intensity(int adc_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        terminate = 1;
    }
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int adc_value = -1; // Initialize to an error value
    int retries = 0;

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract ADC value from response
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            break; // Exit retry loop on success
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d). Retrying...\n", retries + 1);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }

    if (adc_value == -1) {
        fprintf(stderr, "Error: SPI transfer failed after %d retries. Using stale data.\n", MAX_RETRIES);
    }

    return adc_value;
}

// Function to map ADC value to rainfall intensity
int map_adc_to_intensity(int adc_value) {
    // Linear mapping: 0 -> 0, 1023 -> 10
    return (int)(((float)adc_value / 1023.0) * 10.0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value from YL-83 sensor
        int adc_value = read_mcp3008(MCP3008_CHANNEL);

        // Map ADC value to rainfall intensity
        int intensity = map_adc_to_intensity(adc_value);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log data to stdout
        printf("%s, ADC: %d, Intensity: %d\n", timestamp, adc_value, intensity);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

