// Define GPIO pins
#define SPI_CE 0       // Chip Enable 0 (GPIO8)
#define PWM_PIN 18     // GPIO18

// Define SPI parameters
#define SPI_CHANNEL 0  // SPI channel 0 (CE0)
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0      // SPI mode 0

// Define PWM parameters
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1024    // 0-1023

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void set_pwm_duty_cycle(int duty_cycle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    gpioPWM(PWM_PIN, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure PWM pin as output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Configure PWM frequency and range
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Set PWM duty cycle
        set_pwm_duty_cycle(adc_value);

        // Print ADC and PWM values
        printf("ADC: %d, PWM: %d\n", adc_value, adc_value);

        // Wait 100 ms
        gpioDelay(100);
    }

    // Stop PWM
    gpioPWM(PWM_PIN, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

