#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <getopt.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_PGA_4_096V 4.096
#define ADS1115_FULL_SCALE_VOLTAGE 6.144
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0
#define BLINK_DURATION 1000 // milliseconds
#define BLINK_ON_TIME 50    // milliseconds
#define BLINK_OFF_TIME 50   // milliseconds

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int16_t read_adc_value();
double convert_to_gauss(int16_t adc_value);
void blink_led();
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_gpio;
    double default_threshold;
} config_t;

config_t config = {
    .i2c_bus = I2C_BUS,
    .ads1115_address = ADS1115_ADDR,
    .led_gpio = LED_GPIO,
    .default_threshold = DEFAULT_THRESHOLD
};

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

