#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_CE_PIN 8
#define SPI_CLOCK_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_HOST "localhost" // Change to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_PUMP_CONTROL_TOPIC "pump_control"
#define MQTT_SOIL_MOISTURE_TOPIC "soil_moisture"
#define MQTT_CLIENT_ID "soil_moisture_sensor"
#define SENSOR_PRESENT_MIN 200
#define SENSOR_PRESENT_MAX 800

// Global variables
int spi_handle;
struct mosquitto *mqtt_client = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(int moisture);
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int sig);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    // Assuming ADC range is 0-1023
    // Adjust these values based on your sensor's characteristics
    float moisture = 100.0 - ((float)adc_value / 1023.0) * 100.0;
    return moisture;
}

// Function to control the water pump
void control_pump(int moisture) {
    static int pump_state = 0; // 0 = off, 1 = on

    if (moisture < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
        gpioWrite(PUMP_GPIO, 1); // Activate relay (turn on pump)
        pump_state = 1;
        syslog(LOG_INFO, "Pump activated (Moisture: %d%%)", moisture);
    } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
        gpioWrite(PUMP_GPIO, 0); // Deactivate relay (turn off pump)
        pump_state = 0;
        syslog(LOG_INFO, "Pump deactivated (Moisture: %d%%)", moisture);
    }
}

// MQTT connect callback
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_HOST, MQTT_PORT);
        // Subscribe to the pump control topic
        mosquitto_subscribe(mosq, NULL, MQTT_PUMP_CONTROL_TOPIC, 0);
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_connack_string(result));
    }
}

// MQTT disconnect callback
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "MQTT disconnected with code %d", rc);
}

// MQTT message callback
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(message->topic, MQTT_PUMP_CONTROL_TOPIC) == 0) {
            if (strcmp(payload, "pump_on") == 0) {
                gpioWrite(PUMP_GPIO, 1); // Activate relay (turn on pump)
                syslog(LOG_INFO, "Pump activated via MQTT");
            } else if (strcmp(payload, "pump_off") == 0) {
                gpioWrite(PUMP_GPIO, 0); // Deactivate relay (turn off pump)
                syslog(LOG_INFO, "Pump deactivated via MQTT");
            } else {
                syslog(LOG_WARNING, "Invalid MQTT command: %s", payload);
            }
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int main() {
    // Initialize syslog
    openlog("soil_moisture_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially off

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_CLOCK_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI initialisation failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mqtt_client = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mqtt_client) {
        syslog(LOG_ERR, "MQTT client creation failed");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mqtt_client, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mqtt_client, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mqtt_client, mqtt_message_callback);

    int rc = mosquitto_connect(mqtt_client, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connection failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mqtt_client);
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mqtt_client);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read soil moisture
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            continue; // Skip to the next iteration
        }

        // Check for sensor presence
        if (adc_value < SENSOR_PRESENT_MIN || adc_value > SENSOR_PRESENT_MAX) {
            syslog(LOG_WARNING, "Sensor not present (ADC value: %d)", adc_value);
        } else {
            // Calculate moisture percentage
            float moisture = calculate_moisture(adc_value);

            // Control the pump
            control_pump((int)moisture);

            // Publish moisture reading to MQTT
            char payload[20];
            snprintf(payload, sizeof(payload), "%.2f", moisture);
            rc = mosquitto_publish(mqtt_client, NULL, MQTT_SOIL_MOISTURE_TOPIC, strlen(payload), payload, 0, false);
            if (rc != MOSQ_ERR_SUCCESS) {
                syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
            }
        }

        sleep(60); // Wait 60 seconds
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");
    gpioWrite(PUMP_GPIO, 0); // Turn off pump
    spiClose(spi_handle);
    mosquitto_loop_stop(mqtt_client, false);
    mosquitto_disconnect(mqtt_client);
    mosquitto_destroy(mqtt_client);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

