        syslog(LOG_ERR, "MQTT connection failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mqtt_client);
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mqtt_client);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read soil moisture
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            continue; // Skip to the next iteration
        }

        // Check for sensor presence
        if (adc_value < SENSOR_PRESENT_MIN || adc_value > SENSOR_PRESENT_MAX) {
            syslog(LOG_WARNING, "Sensor not present (ADC value: %d)", adc_value);
        } else {
            // Calculate moisture percentage
            float moisture = calculate_moisture(adc_value);

            // Control the pump
            control_pump((int)moisture);

            // Publish moisture reading to MQTT
            char payload[20];
            snprintf(payload, sizeof(payload), "%.2f", moisture);
            rc = mosquitto_publish(mqtt_client, NULL, MQTT_SOIL_MOISTURE_TOPIC, strlen(payload), payload, 0, false);
            if (rc != MOSQ_ERR_SUCCESS) {
                syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
            }
        }

        sleep(60); // Wait 60 seconds
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");
    gpioWrite(PUMP_GPIO, 0); // Turn off pump
    spiClose(spi_handle);
    mosquitto_loop_stop(mqtt_client, false);
    mosquitto_disconnect(mqtt_client);
    mosquitto_destroy(mqtt_client);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

