#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define SPI device
#define SPI_DEVICE "/dev/spidev0.0"

// Define noise threshold
#define NOISE_THRESHOLD 500

// Define PWM frequency
#define PWM_FREQUENCY 100

// Global variables for graceful shutdown
int spi_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int read_adc(int channel);
void set_motor_speed(int gpio, int duty_cycle);
void log_event(int adc_value, int duty_cycle1, int duty_cycle2);
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to set motor speed using PWM
void set_motor_speed(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Function to log events to file
void log_event(int adc_value, int duty_cycle1, int duty_cycle2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ADC: %d, Motor1: %d, Motor2: %d\n", timestamp, adc_value, duty_cycle1, duty_cycle2);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Stop motors
    set_motor_speed(MOTOR1_GPIO, 0);
    set_motor_speed(MOTOR2_GPIO, 0);

    // Close SPI device
    if (spi_handle != -1) {
        spiClose(spi_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for vibration motors
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    // Set PWM frequency for vibration motors
    gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY);

    // Open SPI device
    spi_handle = spiOpen(0, 1000000, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed, skipping iteration\n");
            gpioDelay(10000); // 10ms delay
            continue;
        }

        // Check noise threshold
        if (adc_value > NOISE_THRESHOLD) {
            // Map ADC value to PWM duty cycle
            int duty_cycle1 = (int)(((float)adc_value / 1023.0) * 255.0);
            int duty_cycle2 = (int)(((float)adc_value / 1023.0) * 255.0);

            // Set motor speeds
            set_motor_speed(MOTOR1_GPIO, duty_cycle1);
            set_motor_speed(MOTOR2_GPIO, duty_cycle2);

            // Log event
            log_event(adc_value, duty_cycle1, duty_cycle2);
        } else {
            // Turn off motors
            set_motor_speed(MOTOR1_GPIO, 0);
            set_motor_speed(MOTOR2_GPIO, 0);
        }

        // 10ms delay
        gpioDelay(10000);
    }

    return 0;
}

