#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <math.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define LOG_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int spi_fd = -1;
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_read_adc(int spi_fd, int channel);
float adc_to_db(int adc_value);
int i2c_init(const char *device, int addr);
int i2c_read_bh1750(int i2c_fd);
float bh1750_to_lux(int raw_value);
int log_data(FILE *fp, float sound_level_db, float light_level_lux, int error_code);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI bits per word
    int bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    // Configure SPI max speed
    int speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI read ADC function
int spi_read_adc(int spi_fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    // MCP3008 command: start bit, single-ended mode, channel number (0-7), don't care bit
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = 1000000; // 1 MHz
    tr.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Convert ADC value to dB (example formula, adjust as needed)
float adc_to_db(int adc_value) {
    // Assuming ADC range is 0-1023 and maximum sound level is 100 dB
    float db_value = (float)adc_value / 1023.0 * 100.0;
    return db_value;
}

// I2C initialization function
int i2c_init(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read BH1750 function
int i2c_read_bh1750(int i2c_fd) {
    unsigned char cmd = 0x11; // Continuous high-resolution mode 2
    unsigned char buf[2];

    // Send command to start measurement
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement (at least 180 ms)
    usleep(180000);

    // Read 2 bytes of data
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Combine the bytes to get the raw value
    int raw_value = (buf[0] << 8) | buf[1];
    return raw_value;
}

// Convert BH1750 raw value to lux (example formula, adjust as needed)
float bh1750_to_lux(int raw_value) {
    float lux = (float)raw_value / 1.2; // Example conversion factor
    return lux;
}

// Log data to CSV file function
int log_data(FILE *fp, float sound_level_db, float light_level_lux, int error_code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, sound_level_db, light_level_lux, error_code) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = i2c_init(I2C_DEVICE, BH1750_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }
    rewind(log_file);

    printf("Starting tamper detection...\n");

    while (!terminate) {
        // Read sound level
        int adc_value = spi_read_adc(spi_fd, 0);
        float sound_level_db = -1.0; // Initialize to an invalid value
        int sound_error = 0;
        if (adc_value < 0) {
            sound_error = -1; // ADC read error
            fprintf(stderr, "Error reading ADC value.\n");
        } else {
            sound_level_db = adc_to_db(adc_value);
        }

        // Read light level
        int raw_light_value = i2c_read_bh1750(i2c_fd);
        float light_level_lux = -1.0; // Initialize to an invalid value
        int light_error = 0;
        if (raw_light_value < 0) {
            light_error = -1; // I2C read error
            fprintf(stderr, "Error reading BH1750 value.\n");
        } else {
            light_level_lux = bh1750_to_lux(raw_light_value);
        }

        // Log data
        int log_error = log_data(log_file, sound_level_db, light_level_lux, sound_error | (light_error << 1));
        if (log_error != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    printf("Tamper detection stopped.\n");
    return 0;
}

