    while (retries < MAX_RETRIES) {
        result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
        if (result == 0) {
            // Extract ADC value from response
            int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    // Assuming 0 ADC value is 0% moisture and 1023 is 100%
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
void control_pump(int moisture_percentage) {
    if (moisture_percentage < MOISTURE_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump ON
        printf("Pump ON\n");
    } else {
        gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
        printf("Pump OFF\n");
    }
}

// Function to log data
void log_data(int adc_value, float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - ADC Value: %d, Moisture: %.2f%%\n", timestamp, adc_value, moisture_percentage);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
    gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially OFF

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Monitoring System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read ADC value from VH400 sensor (channel 0)
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(LOG_INTERVAL * 1000); // Wait before next attempt
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);

        // Control the water pump
        control_pump(moisture_percentage);

        // Log the data
        log_data(adc_value, moisture_percentage);

        // Wait for the next reading
        gpioDelay(LOG_INTERVAL * 1000); // Convert seconds to milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

