    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to distance (cm)
float adc_to_distance(int adc_value) {
    // Approximate formula for GP2Y0A21YK0F
    // This is a simplified approximation and may need calibration
    if (adc_value == 0) return 100.0; // Avoid division by zero, return a large value
    float voltage = (float)adc_value / 1023.0 * 3.3; // Assuming 3.3V reference
    float distance = 100.0 / (voltage + 0.42); // Example formula, adjust as needed
    return distance;
}

// Function to control the relay
void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", RELAY_GPIO);
    }
}

