    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int relay_state = 0; // 0 = off, 1 = on
    time_t last_trigger_time = 0;

    printf("Monitoring IR distance sensor...\n");

    while (!terminate) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to distance
        float distance = adc_to_distance(adc_value);

        // Check for proximity
        if (distance < PROXIMITY_THRESHOLD) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_trigger_time) >= (DEBOUNCE_DELAY / 1000.0)) {
                // Activate relay
                control_relay(1);
                relay_state = 1;
                log_event("Proximity detected, relay activated");
                printf("Proximity detected, relay activated\n");
                last_trigger_time = current_time;
            }
        } else {
            // Deactivate relay
            if (relay_state == 1) {
                control_relay(0);
                relay_state = 0;
                log_event("Proximity lost, relay deactivated");
                printf("Proximity lost, relay deactivated\n");
            }
        }

        // Wait for 100ms
        gpioDelay(100); // pigpio's delay function
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_relay(0); // Ensure relay is off
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

