// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // YL-69 sensor connected to channel 0
#define RETRY_COUNT 5
#define BACKOFF_DELAY 1 // Initial delay in seconds
#define LOG_FILE "soil_data.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_moisture_percentage(int adc_value);
void log_data(float moisture_percentage);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int adc_value = -1; // Initialize to an invalid value
    int retries = 0;
    int delay = BACKOFF_DELAY;

    // Construct SPI command bytes
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    while (retries < RETRY_COUNT) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract ADC value from response
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

            // Validate ADC value
            if (adc_value >= 0 && adc_value <= 1023) {
                return adc_value;
            } else {
                fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
                log_data(-1.0); // Log an error
                return -1; // Indicate error
            }
        } else {
            fprintf(stderr, "Error: SPI communication failed (attempt %d).\n", retries + 1);
            log_data(-1.0); // Log an error
            retries++;
            gpioDelay(delay * 1000000); // Exponential backoff
            delay *= 2;
        }
    }

    fprintf(stderr, "Error: SPI communication failed after %d retries. Skipping reading.\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// Function to convert ADC value to moisture percentage
float convert_to_moisture_percentage(int adc_value) {
    if (adc_value == -1) return -1.0; // Return -1.0 for error
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to log data to file
void log_data(float moisture_percentage) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (moisture_percentage == -1.0) {
        fprintf(fp, "%s - ERROR: SPI communication failed\n", timestamp);
    } else {
        fprintf(fp, "%s - Moisture: %.2f%%\n", timestamp, moisture_percentage);
    }

    fclose(fp);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        float moisture_percentage = convert_to_moisture_percentage(adc_value);

        if (moisture_percentage != -1.0) {
            printf("Moisture: %.2f%%\n", moisture_percentage);
        } else {
            printf("Error reading moisture data.\n");
        }

        log_data(moisture_percentage);
        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

