#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <gpiod.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define PWM parameters
#define PWM_PERIOD 1000000 // 1 kHz

// Define distance and frequency ranges
#define MIN_DISTANCE 2.0  // cm
#define MAX_DISTANCE 20.0 // cm
#define MIN_FREQUENCY 220.0 // Hz
#define MAX_FREQUENCY 880.0 // Hz

// Define LDR sensitivity range
#define MIN_LDR_VALUE 0
#define MAX_LDR_VALUE 1023

// Define timeout values
#define TRIG_TIMEOUT_US 10000 // 10 ms
#define ECHO_TIMEOUT_US 50000 // 50 ms

// Define calibration file
#define CALIBRATION_FILE "theremin_config.txt"

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trig_line, *echo_line, *pwm_line;
static int spi_fd;
static volatile int echo_start_time, echo_end_time;
static double distance = 10.0; // Default distance
static int ldr_value = 512;    // Default LDR value
static double frequency = 440.0; // Default frequency
static int pwm_duty_cycle = 500000; // Default duty cycle
static int running = 1;

// Function prototypes
double get_distance();
int read_ldr();
double map_distance_to_frequency(double distance);
int map_ldr_to_duty_cycle(int ldr_value);
void set_pwm_frequency(double frequency);
void set_pwm_duty_cycle(int duty_cycle);
void save_calibration();
void load_calibration();
void signal_handler(int sig);

// Function to get the current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    static char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log messages with timestamps
void log_message(const char *message) {
    printf("[%s] %s\n", get_timestamp(), message);
}

// Function to handle errors
void error_handler(const char *message) {
    fprintf(stderr, "[%s] ERROR: %s\n", get_timestamp(), message);
}

// Function to get distance from HC-SR04 sensor
double get_distance() {
    struct timespec start, end;
    long elapsed_time;

    // Trigger the sensor
    if (gpiod_line_set_value(trig_line, 1) < 0) {
        error_handler("Failed to set TRIG pin high");
        return -1.0;
    }
    nanosleep(&(struct timespec){0, 10000}, NULL); // 10 us
    if (gpiod_line_set_value(trig_line, 0) < 0) {
        error_handler("Failed to set TRIG pin low");
        return -1.0;
    }

    // Measure the echo pulse width
    echo_start_time = 0;
    echo_end_time = 0;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_time = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);
        if (elapsed_time > TRIG_TIMEOUT_US * 1000) {
            error_handler("Timeout waiting for echo start");
            return -1.0;
        }
    }
    echo_start_time = elapsed_time / 1000; // Store in microseconds

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_time = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);
        if (elapsed_time > ECHO_TIMEOUT_US * 1000) {
            error_handler("Timeout waiting for echo end");
            return -1.0;
        }
    }
    echo_end_time = elapsed_time / 1000; // Store in microseconds

    // Calculate the distance
    elapsed_time = echo_end_time - echo_start_time;
    if (elapsed_time <= 0) {
        error_handler("Invalid echo pulse width");
        return -1.0;
    }
    double distance = elapsed_time * 0.0343 / 2.0; // Speed of sound: 0.0343 cm/us

    return distance;
}

// Function to read the LDR value from MCP3008
int read_ldr() {
    unsigned char buffer[3];
    buffer[0] = 0x01;                  // Start bit
    buffer[1] = (0x08 | SPI_CHANNEL) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;                  // Don't care

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        error_handler("SPI read failed");
        return -1;
    }

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Function to map distance to frequency
double map_distance_to_frequency(double distance) {
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    double frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    return frequency;
}

// Function to map LDR value to duty cycle
int map_ldr_to_duty_cycle(int ldr_value) {
    if (ldr_value < MIN_LDR_VALUE) {
        ldr_value = MIN_LDR_VALUE;
    } else if (ldr_value > MAX_LDR_VALUE) {
        ldr_value = MAX_LDR_VALUE;
    }

    int duty_cycle = (int)((double)(ldr_value - MIN_LDR_VALUE) * (1000000.0 - 0.0) / (MAX_LDR_VALUE - MIN_LDR_VALUE));
    return duty_cycle;
}

// Function to set PWM frequency
void set_pwm_frequency(double frequency) {
    // Calculate the period in nanoseconds
