#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define FAN_GPIO 18
#define LOG_FILE "air_quality.log"
#define MCP3008_CHANNEL 0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int convert_adc_to_aqi(int adc_value);
void control_fan(int aqi);
void log_data(int aqi);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int adc_value = -1; // Initialize to an error value
    int retries = 3;
    int delay_ms = 1000;

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)) & 0xFF; // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract ADC value from response
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            break; // Exit retry loop on success
        } else {
            fprintf(stderr, "SPI read failed, retrying... (%d retries left)\n", retries - 1);
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }

    if (adc_value == -1) {
        fprintf(stderr, "SPI read failed after multiple retries.\n");
    }

    return adc_value;
}

// Function to convert ADC value to AQI
int convert_adc_to_aqi(int adc_value) {
    // Linear mapping: 0-1023 -> 0-500
    return (int)(((float)adc_value / 1023.0) * 500.0);
}

// Function to control the ventilation fan
void control_fan(int aqi) {
    if (aqi > 100) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
        printf("Fan ON (AQI: %d)\n", aqi);
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
        printf("Fan OFF (AQI: %d)\n", aqi);
    }
}

// Function to log data to file
void log_data(int aqi) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, AQI: %d\n", timestamp, aqi);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is initially OFF

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value from MQ-135 sensor
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value != -1) {
            // Convert ADC value to AQI
            int aqi = convert_adc_to_aqi(adc_value);

            // Control the fan
            control_fan(aqi);

            // Log the data
            log_data(aqi);

            printf("ADC Value: %d, AQI: %d\n", adc_value, aqi);
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }

        gpioDelay(5000000); // Wait 5 seconds (5000000 microseconds)
    }

    cleanup();
    return 0;
}

