void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value from MQ-135 sensor
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value != -1) {
            // Convert ADC value to AQI
            int aqi = convert_adc_to_aqi(adc_value);

            // Control the fan
