static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len);
int gpio_init(void);
int gpio_read(void);
int read_mcp3008(int channel);
float adc_to_ppm(int adc_value);
void log_data(float ppm, const char *status);
void signal_handler(int sig);
