// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// GPIO initialization function
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "mq3_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO read function
int gpio_read(void) {
    int value = gpiod_line_get_value(gpio_line);
    if (value < 0) {
        perror("Error reading GPIO value");
        return -1;
    }
    return value;
}

// MCP3008 read function
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int adc_value = -1;
    int retries = 3;
    int delay_ms = 100;

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (channel << 4) | 0x80; // Single-ended mode + channel
    tx_buf[2] = 0x00;

    while (retries > 0) {
        if (spi_transfer(tx_buf, rx_buf, 3) == 0) {
            adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
            break; // Success, exit retry loop
        } else {
            fprintf(stderr, "SPI transfer failed, retrying (%d retries left)...\n", retries - 1);
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }

    if (adc_value == -1) {
        fprintf(stderr, "Failed to read MCP3008 after multiple retries.\n");
        return -1;
    }

    return adc_value;
}

// ADC to PPM conversion function
float adc_to_ppm(int adc_value) {
    return (adc_value * 0.5) - 10.0;
}

// Data logging function
void log_data(float ppm, const char *status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f, %s\n", timestamp, ppm, status);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize logging
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        log_data(0.0, "SPI initialization failed.");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        log_data(0.0, "GPIO initialization failed.");
        cleanup();
        return EXIT_FAILURE;
    }

    int consecutive_high = 0;
    int consecutive_low = 0;
    int adc_value;
    float ppm;
    const char *status;

    while (!terminate) {
        adc_value = read_mcp3008(MQ3_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Error reading MCP3008, skipping this iteration.\n");
            sleep(1);
            continue;
        }

        ppm = adc_to_ppm(adc_value);

        if (adc_value == 0) {
            consecutive_low++;
            consecutive_high = 0; // Reset high counter
        } else if (adc_value == 1023) {
            consecutive_high++;
            consecutive_low = 0; // Reset low counter
        } else {
            consecutive_low = 0;
            consecutive_high = 0;
        }

        if (consecutive_low >= 5) {
            status = "Sensor absent!";
            log_data(ppm, status);
            fprintf(stderr, "%s\n", status);
            consecutive_low = 0; // Reset counter
        } else if (consecutive_high >= 5) {
            status = "Sensor failure!";
            log_data(ppm, status);
            fprintf(stderr, "%s\n", status);
            consecutive_high = 0; // Reset counter
        } else if (ppm > 50.0) {
            status = "Alcohol detected! Limit exceeded.";
            log_data(ppm, status);
            fprintf(stderr, "%s\n", status);
        } else if (ppm < 20.0) {
            status = "Sobriety confirmed.";
            log_data(ppm, status);
            fprintf(stderr, "%s\n", status);
        } else {
            status = "Alcohol level within acceptable range.";
            log_data(ppm, status);
            fprintf(stderr, "%s\n", status);
        }

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

