#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PUMP_PIN 18
#define SPI_CE0 8
#define SPI_CE1 7

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define moisture threshold
#define MOISTURE_THRESHOLD 300

// Define pump activation time
#define PUMP_ACTIVATION_TIME 5 // seconds

// Global variables
int spi_handle0, spi_handle1;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int spi_handle, int channel);
void control_pump(int pump_state);
void log_data(int sensor0_value, int sensor1_value, int pump_state);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to control the water pump
void control_pump(int pump_state) {
    gpioWrite(PUMP_PIN, pump_state);
}

// Function to log data to file
void log_data(int sensor0_value, int sensor1_value, int pump_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor0: %d, Sensor1: %d, Pump: %s\n",
            timestamp, sensor0_value, sensor1_value, pump_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel 0
    spi_handle0 = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle0 < 0) {
        fprintf(stderr, "Error: SPI open failed for channel 0 (CE0)\n");
        gpioTerminate();
        return 1;
    }

    // Open SPI channel 1
    spi_handle1 = spiOpen(1, SPI_SPEED, 0); // Mode 0, CE1
    if (spi_handle1 < 0) {
        fprintf(stderr, "Error: SPI open failed for channel 1 (CE1)\n");
        spiClose(spi_handle0);
        gpioTerminate();
        return 1;
    }

    // Set pump pin as output
    gpioSetMode(PUMP_PIN, PI_OUTPUT);

    // Open log file in append mode
    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle0);
        spiClose(spi_handle1);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
