#include <pigpio.h>

// Define GPIO pins
#define PUMP_PIN 18
#define SPI_CE0 8
#define SPI_CE1 7

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define moisture threshold
#define MOISTURE_THRESHOLD 300

// Define pump activation time
#define PUMP_ACTIVATION_TIME 5 // seconds

// Global variables
int spi_handle0, spi_handle1;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int spi_handle, int channel);
void control_pump(int pump_state);
void log_data(int sensor0_value, int sensor1_value, int pump_state);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to control the water pump
void control_pump(int pump_state) {
    gpioWrite(PUMP_PIN, pump_state);
}

// Function to log data to file
void log_data(int sensor0_value, int sensor1_value, int pump_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor0: %d, Sensor1: %d, Pump: %s\n",
            timestamp, sensor0_value, sensor1_value, pump_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
