#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Motor GPIO pins
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Potentiometer channels
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// Speed limits
#define MIN_SPEED 50
#define MAX_SPEED 255

// Motion profile parameters
#define ACCELERATION_TIME 2 // seconds
#define CONSTANT_SPEED_TIME 2 // seconds
#define DECELERATION_TIME 2 // seconds
#define PAUSE_TIME 5 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int map_potentiometer_to_speed(int pot_value);
void set_motor_speed(int motor, int speed);
void set_motor_direction(int motor, int direction);
void motion_profile(int motor1_speed, int motor2_speed);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to map potentiometer value to speed factor
int map_potentiometer_to_speed(int pot_value) {
    // Logarithmic mapping
    double log_value = log10(1 + pot_value);
    double normalized_log_value = log_value / log10(1024); // Normalize to 0-1 range

    // Scale to speed range
    int speed_factor = (int)(normalized_log_value * (MAX_SPEED - MIN_SPEED) + MIN_SPEED);

    // Clamp to speed limits
    if (speed_factor < MIN_SPEED) {
        speed_factor = MIN_SPEED;
    } else if (speed_factor > MAX_SPEED) {
        speed_factor = MAX_SPEED;
    }

    return speed_factor;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor, int speed) {
    if (motor != 1 && motor != 2) {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
        return;
    }

    int enable_pin, direction_pin;
    if (motor == 1) {
        enable_pin = MOTOR1_ENABLE;
        direction_pin = MOTOR1_DIRECTION;
    } else {
        enable_pin = MOTOR2_ENABLE;
        direction_pin = MOTOR2_DIRECTION;
    }

    gpioPWM(enable_pin, speed);
}

// Function to set motor direction
void set_motor_direction(int motor, int direction) {
    if (motor != 1 && motor != 2) {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
        return;
    }

    int direction_pin;
    if (motor == 1) {
        direction_pin = MOTOR1_DIRECTION;
    } else {
        direction_pin = MOTOR2_DIRECTION;
    }

    gpioWrite(direction_pin, direction);
}

// Function to implement motion profile
void motion_profile(int motor1_speed, int motor2_speed) {
    int i;
    int steps = 100; // Number of steps in the acceleration/deceleration
    double acceleration_rate = (double)(motor1_speed - MIN_SPEED) / steps;
    double deceleration_rate = (double)(MIN_SPEED - motor1_speed) / steps;
    double current_speed = MIN_SPEED;

    // Acceleration
    for (i = 0; i < steps && !terminate; i++) {
        current_speed += acceleration_rate;
        set_motor_speed(1, (int)current_speed);
        set_motor_speed(2, motor2_speed);
        gpioDelay(ACCELERATION_TIME * 1000000 / steps); // Delay for acceleration time
    }

    // Constant speed
    for (i = 0; i < CONSTANT_SPEED_TIME && !terminate; i++) {
        set_motor_speed(1, motor1_speed);
        set_motor_speed(2, motor2_speed);
        gpioDelay(1000000); // 1 second delay
    }

    // Deceleration
    for (i = 0; i < steps && !terminate; i++) {
        current_speed -= deceleration_rate;
        set_motor_speed(1, (int)current_speed);
        set_motor_speed(2, motor2_speed);
        gpioDelay(DECELERATION_TIME * 1000000 / steps); // Delay for deceleration time
    }

    // Stop motors
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR1_ENABLE, 255);
    gpioSetPWMrange(MOTOR2_ENABLE, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read potentiometer values
        int pot1_value = read_mcp3008(POT1_CHANNEL);
        int pot2_value = read_mcp3008(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error: Failed to read potentiometer values\n");
            // Optionally, add retry logic here
            gpioDelay(100000); // Small delay before retrying
            continue;
        }

        // Map potentiometer values to speed factors
        int motor1_speed_factor = map_potentiometer_to_speed(pot1_value);
        int motor2_speed_factor = map_potentiometer_to_speed(pot2_value);

        // Run motion profile
        motion_profile(motor1_speed_factor, motor2_speed_factor);

        // Pause
        gpioDelay(PAUSE_TIME * 1000000);

        // Reverse directions
        set_motor_direction(1, !gpioRead(MOTOR1_DIRECTION));
        set_motor_direction(2, !gpioRead(MOTOR2_DIRECTION));

        // Reverse motion profile
        motion_profile(motor1_speed_factor, motor2_speed_factor);

        // Pause
        gpioDelay(PAUSE_TIME * 1000000);
    }

    // Stop motors
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

