#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 17
#define SPI_CE 8 // Chip Enable for MCP3008

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define calibration parameters
#define CALIBRATION_TIME 5 // seconds
#define SAMPLE_RATE 100    // Hz

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calibrate_noise_level(int num_samples);
int is_threshold_exceeded(int sample, float noise_level);
void set_led(int state);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calibrate the noise level
float calibrate_noise_level(int num_samples) {
    int total = 0;
    for (int i = 0; i < num_samples; i++) {
        int sample = read_mcp3008(0);
        if (sample < 0) {
            fprintf(stderr, "Error: Failed to read ADC during calibration\n");
            return -1.0;
        }
        total += sample;
        gpioDelay(1000000 / SAMPLE_RATE); // Delay to achieve desired sample rate
    }
    return (float)total / num_samples;
}

// Function to check if the sound level exceeds the threshold
int is_threshold_exceeded(int sample, float noise_level) {
    return (sample > (noise_level * 1.10)); // 10% above average
}

// Function to set the LED state
void set_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Calibrate noise level
    float noise_level = calibrate_noise_level(CALIBRATION_TIME * SAMPLE_RATE);
    if (noise_level < 0) {
        fprintf(stderr, "Error: Calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
