#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define SAMPLE_RATE 1000 // Hz
#define SAMPLE_PERIOD_NS 1000000 // 1 ms in nanoseconds

// Global variables
static int spi_fd = -1;
static struct gpiod_line *gpio_line = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int gpio_init(void);
int log_init(void);
void sample_audio(void);
void signal_handler(int sig);
void cleanup(void);

// SPI initialization function
int spi_init(void) {
    int ret;
    uint8_t mode = 0;
    uint8_t bits = 8;
    uint32_t speed = 1000000; // 1 MHz

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// GPIO initialization function
int gpio_init(void) {
    int ret;

    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_output(gpio_line, "audio_logger", 1); // Initial value HIGH
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Log file initialization function
int log_init(void) {
    log_file = fopen("audio_log.txt", "w");
    if (!log_file) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

// Audio sampling function
void sample_audio(void) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct timespec ts;
    long long timestamp_ns;
    int ret;

    // MCP3008 command: start bit (0x01), single-ended channel 0 (0x08), dummy bit (0x00)
    tx_buf[0] = 0x01;
    tx_buf[1] = 0x80; // Start bit + single-ended + channel 0
    tx_buf[2] = 0x00;

    // Set CS low
    ret = gpiod_line_set_value(gpio_line, 0);
    if (ret < 0) {
        perror("Error setting GPIO line value");
        return;
    }

    // Perform SPI transfer
    ret = write(spi_fd, tx_buf, 3);
    if (ret != 3) {
        perror("Error writing to SPI device");
        // Set CS high even on error
        gpiod_line_set_value(gpio_line, 1);
        return;
    }

    ret = read(spi_fd, rx_buf, 3);
    if (ret != 3) {
        perror("Error reading from SPI device");
        // Set CS high even on error
        gpiod_line_set_value(gpio_line, 1);
        return;
    }

    // Set CS high
    ret = gpiod_line_set_value(gpio_line, 1);
    if (ret < 0) {
        perror("Error setting GPIO line value");
        return;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    // Get timestamp
    ret = clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
    if (ret < 0) {
        perror("Error getting timestamp");
        return;
    }
    timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

    // Log data
    fprintf(log_file, "%lld|%d\n", timestamp_ns, adc_value);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (gpio_line != NULL) {
        gpiod_line_release(gpio_line);
    }

    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Cleanup complete.\n");
}

int main(void) {
    struct timespec sleep_time;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize log file
    if (log_init() < 0) {
        fprintf(stderr, "Log file initialization failed. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set sleep time for 1ms
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_PERIOD_NS;

    printf("Audio logger started. Press Ctrl+C to terminate.\n");

    // Main loop
    while (!terminate) {
        sample_audio();
        ret = nanosleep(&sleep_time, NULL);
        if (ret < 0 && errno != EINTR) {
            perror("nanosleep");
        }
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

