    while (!terminate) {
        int adc_value = read_mcp3008(0); // Read from channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying in %d ms\n", RETRY_DELAY_MS);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue; // Retry the loop
        }

        float voltage = adc_to_voltage(adc_value, VREF);
        float ppm = voltage_to_ppm(voltage);

        print_data(voltage, ppm);
        log_data(voltage, ppm);

        gpioDelay(1000000); // Delay for 1 second (1000000 microseconds)
    }

    // Cleanup
    printf("Closing SPI, log file, and terminating pigpio...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

