#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define MCP3008_CS   8
#define SPI_CHANNEL  0
#define SPI_BAUD     1000000 // 1 MHz

// ADXL335 sensitivity and zero-g voltage
#define SENSITIVITY  0.00300 // 300 mV/g = 0.00300 V/g
#define ZERO_G_VOLTAGE 1.5

// Kalman filter parameters
#define PROCESS_NOISE 0.01
#define MEASUREMENT_NOISE 0.1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman filter state
float x_k = 0.0; // State estimate
float P_k = 1.0; // Covariance

// Function prototypes
int read_mcp3008(int channel);
float scale_to_g(int adc_value);
float kalman_filter(float measurement);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008

    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to scale ADC reading to g-force
float scale_to_g(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * 3.3; // Assuming 3.3V reference
    float g_force = (voltage - ZERO_G_VOLTAGE) / SENSITIVITY;
    return g_force;
}

// Kalman filter implementation
float kalman_filter(float measurement) {
    // Prediction step
    float x_k_minus = x_k;
    float P_k_minus = P_k + PROCESS_NOISE;

    // Update step
    float K = P_k_minus / (P_k_minus + MEASUREMENT_NOISE);
    float x_k_plus = x_k_minus + K * (measurement - x_k_minus);
    float P_k_plus = (1 - K) * P_k_minus;

    // Update state
    x_k = x_k_plus;
    P_k = P_k_plus;

    return x_k;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure MCP3008 CS pin as output
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008 initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values from all three axes
        int x_adc = read_mcp3008(0);
        int y_adc = read_mcp3008(1);
        int z_adc = read_mcp3008(2);

        if (x_adc == -1 || y_adc == -1 || z_adc == -1) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Scale ADC readings to g-force
        float x_g = scale_to_g(x_adc);
        float y_g = scale_to_g(y_adc);
        float z_g = scale_to_g(z_adc);

        // Apply Kalman filter
        float x_filtered = kalman_filter(x_g);
        float y_filtered = kalman_filter(y_g);
        float z_filtered = kalman_filter(z_g);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x_filtered, y_filtered, z_filtered);

        // Delay for 100 ms (10 Hz sampling rate)
        gpioDelay(100);
    }

    // Clean up and exit
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

