#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the log file name
#define LOG_FILE "magnetic_log.txt"

// Define the sampling interval in milliseconds
#define SAMPLING_INTERVAL_MS 100

// Define the quiescent voltage (VCC/2)
#define V_QUIESCENT 1.65

// Define the sensitivity of the DRV5055VA sensor (25 mV/mT)
#define SENSITIVITY 0.025

// Define the minimum and maximum magnetic field values (mT)
#define MIN_FIELD -100.0
#define MAX_FIELD 100.0

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *sensor1_line, *sensor2_line, *sensor3_line;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(struct gpiod_line *line);
float calculate_magnetic_field(int sensor_value);
void log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT);
void signal_handler(int signal);
int setup_gpio(void);
void cleanup_gpio(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to read the digital value from a sensor
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(-value));
        return -1; // Indicate an error
    }
    return value;
}

// Function to calculate the magnetic field strength in millitesla
float calculate_magnetic_field(int sensor_value) {
    float v_out = (float)sensor_value; // Treat sensor value as digital voltage (0 or 1)
    float b = (v_out - V_QUIESCENT) / SENSITIVITY;
    return b;
}

// Function to log the magnetic field readings to a file
void log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(fp);
    fclose(fp);
}

// Function to set up the GPIO lines
int setup_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    sensor3_line = gpiod_chip_get_line(chip, SENSOR3_GPIO);

    if (!sensor1_line || !sensor2_line || !sensor3_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        cleanup_gpio();
        return -1;
    }

    int ret1 = gpiod_line_request_input(sensor1_line, "sensor1");
    int ret2 = gpiod_line_request_input(sensor2_line, "sensor2");
    int ret3 = gpiod_line_request_input(sensor3_line, "sensor3");

    if (ret1 < 0 || ret2 < 0 || ret3 < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(-ret1)); // Use the first error code
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Function to clean up the GPIO lines
void cleanup_gpio(void) {
    if (sensor1_line) {
