// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the log file name
#define LOG_FILE "magnetic_log.txt"

// Define the sampling interval in milliseconds
#define SAMPLING_INTERVAL_MS 100

// Define the quiescent voltage (VCC/2)
#define V_QUIESCENT 1.65

// Define the sensitivity of the DRV5055VA sensor (25 mV/mT)
#define SENSITIVITY 0.025

// Define the minimum and maximum magnetic field values (mT)
#define MIN_FIELD -100.0
#define MAX_FIELD 100.0

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *sensor1_line, *sensor2_line, *sensor3_line;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(struct gpiod_line *line);
float calculate_magnetic_field(int sensor_value);
void log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT);
void signal_handler(int signal);
int setup_gpio(void);
void cleanup_gpio(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to read the digital value from a sensor
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(-value));
        return -1; // Indicate an error
    }
    return value;
}

// Function to calculate the magnetic field strength in millitesla
float calculate_magnetic_field(int sensor_value) {
    float v_out = (float)sensor_value; // Treat sensor value as digital voltage (0 or 1)
    float b = (v_out - V_QUIESCENT) / SENSITIVITY;
    return b;
}

// Function to log the magnetic field readings to a file
void log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(fp);
    fclose(fp);
}

// Function to set up the GPIO lines
