#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

// Define SPI device and settings
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Define MCP3008 channel numbers
#define CHANNEL_0 0
#define CHANNEL_1 1
#define CHANNEL_2 2

// Global variables
int spi_fd = -1; // SPI file descriptor
FILE *fp = NULL;  // File pointer for CSV file

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed);
int read_mcp3008(int channel);
void log_data(FILE *fp, int channel0_value, int channel1_value, int channel2_value);
void signal_handler(int signal);

// Structure to hold SPI configuration
typedef struct {
    const char *device;
    uint8_t mode;
    uint8_t bits;
    uint32_t speed;
} spi_config_t;

int main() {
    spi_config_t spi_config = {SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED};
    int channel0_value, channel1_value, channel2_value;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(spi_config.device, spi_config.mode, spi_config.bits, spi_config.speed);
    if (spi_fd < 0) {
        fprintf(stderr, "Error initializing SPI. Exiting.\n");
        return 1;
    }

    // Open CSV file for writing
    fp = fopen("sensor_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    // Write CSV header
    fprintf(fp, "Timestamp,Channel0,Channel1,Channel2\n");

    // Main loop
    while (1) {
        // Read ADC values from channels
        channel0_value = read_mcp3008(CHANNEL_0);
        channel1_value = read_mcp3008(CHANNEL_1);
        channel2_value = read_mcp3008(CHANNEL_2);

        // Log data to CSV file
        log_data(fp, channel0_value, channel1_value, channel2_value);

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

// Initialize SPI interface
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from MCP3008 channel
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01;                           // Start bit
    tx_buf[1] = 0x80 | (channel << 4);          // Single-ended mode + channel select
    tx_buf[2] = 0x00;                           // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    // Transfer SPI data
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Log data to CSV file
void log_data(FILE *fp, int channel0_value, int channel1_value, int channel2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write data to CSV file
    fprintf(fp, "%s,%d,%d,%d\n", timestamp, channel0_value, channel1_value, channel2_value);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting.\n");

    // Close CSV file
    if (fp != NULL) {
        fclose(fp);
    }

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    exit(0);
}

