#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"

#define GPIO_PIN 17

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;
static int reconnect_delay = 1;

// Mutex for protecting the running variable
static pthread_mutex_t running_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void signal_handler(int sig);
void *reconnect_thread(void *arg);
void on_connect(struct mosquitto *mosq, void *userdata, int result);
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc);
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
int parse_json_payload(const char *payload);
void log_error(const char *message);

// Signal handler for clean shutdown
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    pthread_mutex_lock(&running_mutex);
    running = 0;
    pthread_mutex_unlock(&running_mutex);
    printf("Signal received, exiting...\n");
}

// Reconnect thread function
void *reconnect_thread(void *arg) {
    (void)arg; // Suppress unused parameter warning
    while (1) {
        pthread_mutex_lock(&running_mutex);
        if (!running) {
            pthread_mutex_unlock(&running_mutex);
            pthread_exit(NULL);
        }
        pthread_mutex_unlock(&running_mutex);

        int rc = mosquitto_reconnect(mosq);
        if (rc == MOSQ_ERR_SUCCESS) {
            printf("Reconnected to MQTT broker.\n");
            reconnect_delay = 1; // Reset reconnect delay
            pthread_exit(NULL);
        } else {
            log_error("Failed to reconnect to MQTT broker.");
            sleep(reconnect_delay);
            reconnect_delay *= 2;
            if (reconnect_delay > 60) {
                reconnect_delay = 60;
            }
        }
    }
    return NULL;
}

// MQTT connect callback
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    (void)userdata; // Suppress unused parameter warning
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker.\n");
        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to topic.");
            pthread_mutex_lock(&running_mutex);
            running = 0;
            pthread_mutex_unlock(&running_mutex);
        }
    } else {
        log_error("MQTT connection error.");
    }
}

// MQTT disconnect callback
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    (void)userdata; // Suppress unused parameter warning
    (void)rc;       // Suppress unused parameter warning
    printf("Disconnected from MQTT broker.\n");
    pthread_mutex_lock(&running_mutex);
    if (running) {
        pthread_t reconnect_thread_id;
        if (pthread_create(&reconnect_thread_id, NULL, reconnect_thread, NULL) != 0) {
            log_error("Failed to create reconnect thread.");
            running = 0;
        }
    }
    pthread_mutex_unlock(&running_mutex);
}

// MQTT message callback
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    (void)mosq;    // Suppress unused parameter warning
    (void)userdata; // Suppress unused parameter warning
    if (message->payloadlen > 0) {
        if (parse_json_payload((char *)message->payload)) {
            printf("Received valid LED state: %s\n", (char *)message->payload);
        } else {
            log_error("Invalid JSON payload received.");
        }
    } else {
        log_error("Empty message received.");
    }
}

// JSON parsing function
int parse_json_payload(const char *payload) {
    cJSON *json = cJSON_Parse(payload);
    if (json == NULL) {
        const char *error_ptr = cJSON_GetErrorPtr();
        if (error_ptr != NULL) {
            fprintf(stderr, "Error before: %s\n", error_ptr);
        }
        return 0;
    }

    cJSON *led_state_json = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (cJSON_IsBool(led_state_json)) {
        int led_state = led_state_json->valueint;
        gpioWrite(GPIO_PIN, led_state);
        cJSON_Delete(json);
        return 1;
    } else {
        log_error("Invalid led_state value in JSON.");
        cJSON_Delete(json);
        return 0;
    }
}

// Error logging function
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Turn off LED on startup

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create mosquitto instance.");
        gpioTerminate();
        return 1;
    }

