#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO resources
struct gpiod_chip *chip;
struct gpiod_line *sound_line;
struct gpiod_line *alarm_line;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (sound_line) {
        gpiod_line_release(sound_line);
    }
    if (alarm_line) {
        gpiod_line_release(alarm_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int sound_level;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100 ms

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return 1;
    }

    // Request GPIO lines
    sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SOUND_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    alarm_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!alarm_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", ALARM_LED_PIN, strerror(errno));
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request input for sound sensor line
    if (gpiod_line_request_input(sound_line, "sound_sensor") < 0) {
        fprintf(stderr, "Error requesting input for GPIO line %d: %s\n", SOUND_SENSOR_PIN, strerror(errno));
        gpiod_line_release(sound_line);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request output for alarm LED line
    if (gpiod_line_request_output(alarm_line, "alarm_led", 0) < 0) {
        fprintf(stderr, "Error requesting output for GPIO line %d: %s\n", ALARM_LED_PIN, strerror(errno));
        gpiod_line_release(sound_line);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sound sensor value
        sound_level = gpiod_line_get_value(sound_line);
        if (sound_level < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", SOUND_SENSOR_PIN, strerror(errno));
            // Attempt to recover by releasing and re-requesting the line
            gpiod_line_release(sound_line);
            sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
            if (!sound_line) {
                fprintf(stderr, "Error getting GPIO line %d: %s\n", SOUND_SENSOR_PIN, strerror(errno));
                break; // Exit loop if recovery fails
            }
            if (gpiod_line_request_input(sound_line, "sound_sensor") < 0) {
                fprintf(stderr, "Error requesting input for GPIO line %d: %s\n", SOUND_SENSOR_PIN, strerror(errno));
                break; // Exit loop if recovery fails
            }
            nanosleep(&sleep_time, NULL); // Wait before retrying
            continue; // Skip to the next iteration
        }

        // Print sound level
        printf("Sound Level: %d\n", sound_level);

        // Check for sound detection
        if (sound_level == 0) {
            // Trigger alarm
            printf("Sound detected! Triggering alarm...\n");
            if (gpiod_line_set_value(alarm_line, 1) < 0) {
                fprintf(stderr, "Error setting GPIO line %d output: %s\n", ALARM_LED_PIN, strerror(errno));
                break; // Exit loop on error
            }

            // Wait for 1 second
            sleep_time.tv_sec = 1;
            sleep_time.tv_nsec = 0;
            nanosleep(&sleep_time, NULL);

            // Turn off alarm
            if (gpiod_line_set_value(alarm_line, 0) < 0) {
                fprintf(stderr, "Error setting GPIO line %d output: %s\n", ALARM_LED_PIN, strerror(errno));
                break; // Exit loop on error
            }
        }

        // Delay
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup (should not reach here under normal circumstances due to signal handler)
    if (sound_line) {
        gpiod_line_release(sound_line);
    }
    if (alarm_line) {
        gpiod_line_release(alarm_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 1;
}

