#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get the current timestamp as a string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a message to the log file
int log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s: %s\n", timestamp, message);
    free(timestamp);

    if (fclose(fp) != 0) {
        perror("Failed to close log file");
        return -1;
    }

    return 0;
}

// Function to handle vibration detection
void handle_vibration() {
    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp, skipping log.\n");
        return;
    }

    char log_message_buffer[256];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "Vibration detected at %s", timestamp);
    free(timestamp);

    if (log_message(log_message_buffer) != 0) {
        fprintf(stderr, "Failed to log message.\n");
    }

    printf("%s\n", log_message_buffer);

    if (system("sudo shutdown -h now") != 0) {
        perror("Failed to execute shutdown command");
    }
}

int main() {
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to install signal handler");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for falling-edge detection
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "vibration-monitor";
    config.request_type = GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE;

    if (gpiod_line_request(line, &config, 0) != 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        struct timespec timeout;
        timeout.tv_sec = 1; // Wait for 1 second
        timeout.tv_nsec = 0;

        int ret = gpiod_line_event_wait(line, &timeout);
        if (ret < 0) {
            perror("Failed to wait for event");
            break;
        } else if (ret == 0) {
            // Timeout occurred, check for termination signal
            continue;
        }

        // Read event
        struct gpiod_line_event event;
        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            perror("Failed to read event");
            break;
        }

        // Handle vibration detection
        handle_vibration();

        // Exit after handling the first vibration event
        break;
    }

    // Clean up resources
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Vibration monitoring stopped.\n");

    return EXIT_SUCCESS;
}

