#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_CALIB_00 0x88
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CTRL_MEAS 0xF4

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

// Global variables
int i2c_handle;
FILE *log_file;
bmp280_calib_data calib;

// Function prototypes
int init_i2c();
int verify_chip_id();
int read_calibration_data(bmp280_calib_data *calib);
int configure_sensor();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temp, bmp280_calib_data calib);
double compensate_pressure(int32_t raw_press, int32_t raw_temp, bmp280_calib_data calib);
double calculate_altitude(double pressure);
int log_data(double altitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify the BMP280 chip ID
int verify_chip_id() {
    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_CHIPID);
    if (chip_id < 0) {
        fprintf(stderr, "Error reading chip ID: %d\n", chip_id);
        return -1;
    }
    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%X\n", chip_id);
        return -1;
    }
    return 0;
}

// Read the BMP280 calibration data
int read_calibration_data(bmp280_calib_data *calib) {
    char data[24];
    int result = i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, data, 24);
    if (result < 0) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Configure the BMP280 sensor
int configure_sensor() {
    int result = i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0b00100011); // Temperature x1, Pressure x1, Normal mode
    if (result < 0) {
        fprintf(stderr, "Error writing to CTRL_MEAS register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read raw temperature and pressure data
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    char data[6];
    int result = i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, data, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading raw data: %d\n", result);
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Compensate temperature using the BMP280 formulas
double compensate_temperature(int32_t raw_temp, bmp280_calib_data calib) {
    double var1, var2, T;
    var1 = (((double)raw_temp / 16384.0) - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temp / 131072.0) - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temp / 131072.0) - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure using the BMP280 formulas
double compensate_pressure(int32_t raw_press, int32_t raw_temp, bmp280_calib_data calib) {
    double var1, var2, p;
    double t_fine;
    var1 = (((double)raw_temp / 16384.0) - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temp / 131072.0) - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temp / 131072.0) - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    t_fine = (var1 + var2);

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)raw_press;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;
    return p;
}

// Calculate altitude using the barometric formula
double calculate_altitude(double pressure) {
    double sea_level_pressure = 101325.0; // Standard sea-level pressure in Pa
    return 44330.0 * (1.0 - pow(pressure / sea_level_pressure, 0.1903));
}

// Log the altitude data to a file
int log_data(double altitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, altitude);
    fflush(log_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify chip ID
    if (verify_chip_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calib) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int32_t raw_temperature, raw_pressure;
    double temperature, pressure, altitude;

    // Main loop
    while (1) {
        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            temperature = compensate_temperature(raw_temperature, calib);
            pressure = compensate_pressure(raw_pressure, raw_temperature, calib);

            // Calculate altitude
            altitude = calculate_altitude(pressure);

            // Log data
            log_data(altitude);

            printf("Altitude: %.2f meters\n", altitude);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup (should not reach here in normal operation due to the signal handler)
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

