#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define LM35_SCALE 0.01
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"

// Global variables
int spi_handle;
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
void log_temperature(float temperature);
void write_to_file(float temperature);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx[3];
    char rx[3];

    tx[0] = 0x01; // Start bit
    tx[1] = (0x08 | (channel << 4)); // Single-ended mode + channel
    tx[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx, rx, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (adc_value * VREF) / 1024.0;
    float temperature = voltage / LM35_SCALE;
    return temperature;
}

// Function to log temperature to console
void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Temperature: %.2f °C\n", timestamp, temperature);
}

// Function to write temperature to file
void write_to_file(float temperature) {
    FILE *fp = fopen(LOG_FILE, "wb+");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open file %s for writing\n", LOG_FILE);
        return;
    }

    // Overwrite the buffer starting from the current index
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_buffer[i] = temperature;
    }

    if (fwrite(temperature_buffer, sizeof(float), BUFFER_SIZE, fp) != BUFFER_SIZE) {
        fprintf(stderr, "Error: Could not write to file %s\n", LOG_FILE);
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            float temperature = convert_to_celsius(adc_value);
            log_temperature(temperature);
            write_to_file(temperature);
        } else {
            fprintf(stderr, "Error: Failed to read temperature\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    return 0;
}

