#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/file.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define MCP3008_CHANNEL 0
#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "environmental_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;
static int log_fd = -1;

// Function prototypes
int init_i2c(void);
int init_spi(void);
int read_bh1750(float *lux);
int read_mcp3008(int channel, int *adc_value);
int log_data(float lux, int adc_value);
void signal_handler(int sig);
void cleanup(void);

// I2C initialization function
int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// SPI initialization function
int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }
    return 0;
}

// Function to read data from BH1750 sensor
int read_bh1750(float *lux) {
    unsigned char buf[2];
    int result;

    // Send start measurement command (High Resolution Mode)
    buf[0] = 0x10; // Continuous H-resolution mode
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Convert to lux
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel, int *adc_value) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    *adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return 0;
}

// Function to log data to file
int log_data(float lux, int adc_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    char log_entry[100];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    snprintf(log_entry, sizeof(log_entry), "%s, Light: %.2f lux, Sound: %d\n", timestamp, lux, adc_value);

    if (flock(log_fd, LOCK_EX) == -1) {
        perror("Error acquiring file lock");
        return -1;
    }

    if (write(log_fd, log_entry, strlen(log_entry)) < 0) {
        perror("Error writing to log file");
        flock(log_fd, LOCK_UN);
        return -1;
    }

    if (flock(log_fd, LOCK_UN) == -1) {
        perror("Error releasing file lock");
        return -1;
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    keep_running = 0;
}

// Cleanup function
void cleanup(void) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
}

int main(void) {
    float lux;
    int adc_value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Starting environmental data logging...\n");

    // Main loop
    while (keep_running) {
        // Read sensor data
        if (read_bh1750(&lux) != 0) {
            fprintf(stderr, "Error reading BH1750 sensor.\n");
        }
        if (read_mcp3008(MCP3008_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Error reading MCP3008 sensor.\n");
        }

        // Log data
        if (log_data(lux, adc_value) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting cleanly.\n");
    return 0;
}

