#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define CHIP_NAME "gpiochip0"
#define LOG_FILE "flame_events.log"

static struct gpiod_line *line = NULL;
static struct gpiod_chip *chip = NULL;
static FILE *log_fp = NULL;
static volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
static void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get current timestamp in ISO 8601 format
static char* get_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[30]; // Static to persist across calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return timestamp;
}

// Function to read the flame sensor value
static int read_flame_sensor(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(-value));
        return -1; // Indicate error
    }
    return value;
}

// Function to log the sensor event to a file
static int log_event(const char *timestamp, int pin, int state)
{
    if (log_fp == NULL) {
        fprintf(stderr, "Log file not opened.\n");
        return -1;
    }

    if (fprintf(log_fp, "%s,%d,%d\n", timestamp, pin, state) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(log_fp); // Ensure data is written to disk
    return 0;
}

// Function to handle flame detection
static void handle_flame_detection()
{
    printf("Flame Detected!\n");
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for input with pull-down
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PUD_DOWN;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_PIN, strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        int value = read_flame_sensor(line);
        if (value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        char *timestamp = get_timestamp();
        if (log_event(timestamp, GPIO_PIN, value) < 0) {
            fprintf(stderr, "Error logging event, exiting.\n");
            break;
        }

        if (value == 1) {
            handle_flame_detection();
        }

        sleep(1);
    }

    // Cleanup
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_fp) {
        fclose(log_fp);
    }

    return EXIT_SUCCESS;
}

