#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define I2C_BUS 1
#define I2C_ADDRESS 0x62
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 0.5

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_celsius(int adc_value);
float celsius_to_voltage(float celsius);
int write_mcp4725(float voltage);
void log_data(int adc_value, float celsius, float voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (read_mcp3008): %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to Celsius
float adc_to_celsius(int adc_value) {
    float voltage = (adc_value * 3.3) / 1024.0;
    float celsius = (voltage - 0.5) * 100.0;
    return celsius;
}

// Function to convert Celsius to voltage
float celsius_to_voltage(float celsius) {
    float voltage = (celsius / 50.0) * 3.3;
    return voltage;
}

// Function to write voltage to MCP4725 DAC
int write_mcp4725(float voltage) {
    if (voltage < 0.0 || voltage > 3.3) {
        fprintf(stderr, "Error: Invalid voltage: %f\n", voltage);
        return -1;
    }

    // Convert voltage to 12-bit DAC value (0-4095)
    int dac_value = (int)(voltage / 3.3 * 4095.0);

    // Construct I2C message (MCP4725 datasheet)
    char i2c_tx_buf[3];
    i2c_tx_buf[0] = 0x40; // Command to write DAC value (no EEPROM write)
    i2c_tx_buf[1] = (dac_value >> 4) & 0xFF; // Upper 8 bits
    i2c_tx_buf[2] = (dac_value << 4) & 0xF0; // Lower 4 bits

    int result = i2cWriteDevice(i2c_handle, i2c_tx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: I2C write failed (write_mcp4725): %d\n", result);
        return -1;
    }

    return 0;
}

// Function to log data to file
void log_data(int adc_value, float celsius, float voltage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, celsius, voltage);
    printf("%s, %d, %.2f, %.2f\n", timestamp, adc_value, celsius, voltage);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed: %d\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Retry
        }

        // Convert ADC value to Celsius
        float celsius = adc_to_celsius(adc_value);

        // Convert Celsius to voltage
        float voltage = celsius_to_voltage(celsius);

        // Write voltage to DAC
        if (write_mcp4725(voltage) != 0) {
            fprintf(stderr, "Error: Failed to write voltage to DAC\n");
        }

        // Log data
        log_data(adc_value, celsius, voltage);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000000); // microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

