#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the GPIO pins connected to the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Function prototypes
void activate_relay(int pin);
void deactivate_relay(int pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Deactivate all relays
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

// Function to activate a relay
void activate_relay(int pin) {
    gpioWrite(pin, 1); // Set the GPIO pin HIGH to activate the relay
    printf("Relay on pin %d activated.\n", pin);
}

// Function to deactivate a relay
void deactivate_relay(int pin) {
    gpioWrite(pin, 0); // Set the GPIO pin LOW to deactivate the relay
    printf("Relay on pin %d deactivated.\n", pin);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Light sequencer started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Activate relay 1
        activate_relay(RELAY1_PIN);
        sleep(1);
        deactivate_relay(RELAY1_PIN);

        // Activate relay 2
        activate_relay(RELAY2_PIN);
        sleep(1);
        deactivate_relay(RELAY2_PIN);

        // Activate relay 3
        activate_relay(RELAY3_PIN);
        sleep(1);
        deactivate_relay(RELAY3_PIN);

        // Activate relay 4
        activate_relay(RELAY4_PIN);
        sleep(1);
        deactivate_relay(RELAY4_PIN);
    }

    return 0; // This line will never be reached due to the infinite loop
}

