#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define rain threshold
#define RAIN_THRESHOLD 5

// Define motor control parameters
#define MOTOR_FORWARD 1
#define MOTOR_REVERSE 0
#define MOTOR_STOP 2
#define MOTOR_SPEED 150
#define MOTOR_DURATION 3 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rain_sensor();
int convert_adc_to_rain_level(int adc_value);
void control_motor(int direction);
void log_rain_reading(int rain_level);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read the rain sensor value from MCP3008 ADC
int read_rain_sensor() {
    unsigned char tx[3];
    unsigned char rx[3];
    int adc_value;

    tx[0] = 0x01;
    tx[1] = (0x08 | 0) << 4; // Channel 0, single-ended
    tx[2] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    adc_value = ((rx[1] & 0x03) << 8) + rx[2];
    return adc_value;
}

// Function to convert ADC value to rain level (0-10)
int convert_adc_to_rain_level(int adc_value) {
    // Map ADC value (0-1023) to rain level (0-10)
    // Since the sensor outputs higher voltage when dry, invert the mapping
    return 10 - (int)(((float)adc_value / 1023.0) * 10.0);
}

// Function to control the motor
void control_motor(int direction) {
    switch (direction) {
        case MOTOR_FORWARD:
            gpioWrite(MOTOR_IN1, 1);
            gpioWrite(MOTOR_IN2, 0);
            gpioPWM(MOTOR_ENA, MOTOR_SPEED);
            printf("Closing window...\n");
            break;
        case MOTOR_REVERSE:
            gpioWrite(MOTOR_IN1, 0);
            gpioWrite(MOTOR_IN2, 1);
            gpioPWM(MOTOR_ENA, MOTOR_SPEED);
            printf("Opening window...\n");
            break;
        case MOTOR_STOP:
            gpioWrite(MOTOR_IN1, 0);
            gpioWrite(MOTOR_IN2, 0);
            gpioPWM(MOTOR_ENA, 0);
            printf("Stopping motor...\n");
            break;
        default:
            fprintf(stderr, "Error: Invalid motor direction\n");
            return;
    }
    gpioDelay(MOTOR_DURATION * 1000000); // Delay for motor duration (microseconds)
    control_motor(MOTOR_STOP); // Stop the motor after the duration
}

// Function to log the rain reading to a file
void log_rain_reading(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

