    close(fd);
    return 0;
}

// Function to unexport the GPIO pin
int gpio_unexport(int pin) {
    char unexport_path[64];
    int fd;

    snprintf(unexport_path, sizeof(unexport_path), GPIO_PATH "/unexport");
    fd = open(unexport_path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", unexport_path, strerror(errno));
        return -1;
    }

    char pin_str[4];
    snprintf(pin_str, sizeof(pin_str), "%d", pin);
    if (write(fd, pin_str, strlen(pin_str)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", unexport_path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the GPIO direction (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char direction_path[64];
    int fd;

    snprintf(direction_path, sizeof(direction_path), GPIO_PATH "/gpio%d/direction", pin);
    fd = open(direction_path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", direction_path, strerror(errno));
        return -1;
    }

    if (write(fd, direction, strlen(direction)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", direction_path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read the GPIO value
int gpio_read(int pin) {
    char value_path[64];
    int fd;
    char value_str[3];

    snprintf(value_path, sizeof(value_path), GPIO_PATH "/gpio%d/value", pin);
    fd = open(value_path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", value_path, strerror(errno));
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", value_path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

// Function to calculate distance from voltage
float calculate_distance(float voltage) {
    float A = 26.0;
    float B = -6.0;
    return A / voltage + B;
}

// Function to log the distance reading to a file
int log_distance(float distance) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    fprintf(fp, "%s, Distance: %.2f mm\n", timestamp, distance);
    fclose(fp);
    return 0;
}

// Function to check feeder activation condition
void check_feeder_activation(float distance) {
    if (distance < 200.0) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (gpio_export(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        return 1;
    }

    // Set GPIO direction to input
    if (gpio_set_direction(GPIO_PIN, "in") < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to input\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    printf("Monitoring distance from GPIO %d...\n", GPIO_PIN);

    while (program_running) {
        int gpio_value = gpio_read(GPIO_PIN);
        if (gpio_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d value\n", GPIO_PIN);
            sleep(1);
            continue;
        }

        float voltage = (float)gpio_value; // Treat 0 as 0V, 1 as 3.3V
        float distance = calculate_distance(voltage);

        if (log_distance(distance) < 0) {
            fprintf(stderr, "Failed to log distance\n");
        }

        check_feeder_activation(distance);

        sleep(1);
    }

    // Unexport GPIO pin on exit
    if (gpio_unexport(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to unexport GPIO %d\n", GPIO_PIN);
    }

    return 0;
}

