float calculate_moisture(int adc_value) {
    float moisture = 100.0 - ((float)(adc_value - WET_ADC) / (float)(DRY_ADC - WET_ADC)) * 100.0;
    if (moisture < 0.0) moisture = 0.0;
    if (moisture > 100.0) moisture = 100.0;
    return moisture;
}

