            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture(adc_value);

        // Control pump based on moisture level
        int pump_status = (moisture_percentage < MOISTURE_THRESHOLD) ? 1 : 0;
        if (control_pump(pump_status) < 0) {
            fprintf(stderr, "Error controlling pump. Retrying in 60 seconds.\n");
