#include <gpiod.h>
#include <errno.h>

// Constants
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define VREF 3.3 // Reference voltage for MCP3008
#define SENSITIVITY 0.1 // Sensor sensitivity (100 mV/A = 0.1 V/A)
#define LOG_FILE "current_log.txt"

// Global variables
static struct gpiod_line *gpio_line = NULL;
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, int mode, int bits_per_word, int speed);
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_adc_channel(int fd, int channel);
float adc_to_current(int adc_value, float vref, float sensitivity);
int log_current_data(FILE *fp, float current);
void signal_handler(int sig);
int gpio_init(const char *chipname, int line);
int gpio_read(struct gpiod_line *line);
void gpio_cleanup(struct gpiod_line *line);

// SPI initialization function
int spi_init(const char *device, int mode, int bits_per_word, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
