#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17

// Define the GPIO chip name (adjust if needed)
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO resources
struct gpiod_chip *chip;
struct gpiod_line *sensor1_line;
struct gpiod_line *sensor2_line;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int debounce_sensor(struct gpiod_line *line);
void log_sensor_state(int sensor1_state, int sensor2_state);
void check_alert(int sensor1_state, int sensor2_state);
void signal_handler(int sig);

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, releasing GPIO resources...\n");
        if (sensor1_line) {
            gpiod_line_release(sensor1_line);
        }
        if (sensor2_line) {
            gpiod_line_release(sensor2_line);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(0);
    }
}

// Function to read the sensor state
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(-value));
        return -1; // Indicate an error
    }
    return value;
}

// Function to debounce the sensor reading
int debounce_sensor(struct gpiod_line *line) {
    int count_no_object = 0;
    int count_object = 0;
    int value;

    for (int i = 0; i < 5; i++) {
        value = read_sensor(line);
        if (value < 0) return -1; // Propagate error
        if (value == 1) {
            count_no_object++;
        } else {
            count_object++;
        }
        usleep(2000); // 2 ms delay
    }

    return (count_object > count_no_object) ? 0 : 1;
}

// Function to log the sensor state with timestamp
void log_sensor_state(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_state, sensor2_state);
}

// Function to check for simultaneous object detection alert
void check_alert(int sensor1_state, int sensor2_state) {
    if (sensor1_state == 0 && sensor2_state == 0) {
        printf("ALERT: Both sensors detect object\n");
    }
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the line for sensor 1
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!sensor1_line) {
        perror("Error getting GPIO line for sensor 1");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get the line for sensor 2
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!sensor2_line) {
        perror("Error getting GPIO line for sensor 2");
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the lines for input
    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0) {
        perror("Error requesting input for sensor 1");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(sensor2_line, "sensor2") < 0) {
        perror("Error requesting input for sensor 2");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_state = debounce_sensor(sensor1_line);
        int sensor2_state = debounce_sensor(sensor2_line);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Error debouncing sensor, exiting...\n");
            break; // Exit the loop on error
        }

        log_sensor_state(sensor1_state, sensor2_state);
        check_alert(sensor1_state, sensor2_state);

        sleep(1); // Wait for 1 second
    }

    // Release GPIO resources before exiting
    gpiod_line_release(sensor1_line);
    gpiod_line_release(sensor2_line);
