#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int baud;
} spi_config_t;

// Function prototypes
int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
int log_data(double moisture_level);
void signal_handler(int signal);
int spi_setup(spi_config_t config);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// SPI setup function
int spi_setup(spi_config_t config) {
    spi_handle = spiOpen(config.channel, config.baud, 0); // SPI_MODE0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", config.channel, spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80 | (channel << 4); // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Calculate moisture level
double calculate_moisture_level(int adc_value) {
    double moisture_level = 100.0 - ((adc_value - MIN_ADC) / (double)(MAX_ADC - MIN_ADC)) * 100.0;
    if (moisture_level < 0.0) moisture_level = 0.0;
    if (moisture_level > 100.0) moisture_level = 100.0;
    return moisture_level;
}

// Log data to file
int log_data(double moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    fclose(fp);

    printf("%s,%.2f\n", timestamp, moisture_level);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI
    spi_config_t spi_config = {SPI_CHANNEL, SPI_BAUD};
    if (spi_setup(spi_config) != 0) {
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);

        if (log_data(moisture_level) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        sleep(READ_DELAY);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

