#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define IMAGE_FORMAT "JPEG"
#define IMAGE_DIR "/home/pi/security_cam/"
#define DEBOUNCE_DELAY 200 // milliseconds

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, stopping program.");
    program_running = 0;
}

int main() {
    int current_state, previous_state;
    time_t rawtime;
    struct tm *timeinfo;
    char filename[80];
    char command[256];
    int status;

    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    syslog(LOG_INFO, "Starting motion detection program.");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    previous_state = gpioRead(GPIO_PIN);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (program_running) {
        current_state = gpioRead(GPIO_PIN);

        if (current_state != previous_state) {
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce
            current_state = gpioRead(GPIO_PIN);

            if (current_state == previous_state) {
                previous_state = current_state;
                continue;
            }

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(filename, sizeof(filename), IMAGE_DIR "%Y%m%d_%H%M%S.jpg", timeinfo);

            if (access(IMAGE_DIR, W_OK) != 0) {
                syslog(LOG_ERR, "Permission denied to write to directory: %s", IMAGE_DIR);
                previous_state = current_state;
                continue;
            }

            snprintf(command, sizeof(command), "libcamera-still -o %s -w %d -h %d -n -f %s", filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_FORMAT);

            syslog(LOG_INFO, "Motion detected, capturing image: %s", filename);

            pid_t pid = fork();

            if (pid == 0) {
                // Child process
                execlp("libcamera-still", "libcamera-still", "-o", filename, "-w", "1280", "-h", "720", "-n", "-f", "JPEG", (char *)NULL);
                syslog(LOG_ERR, "Failed to execute libcamera-still");
                exit(1); // Exit child process if execlp fails
            } else if (pid < 0) {
                // Fork failed
                syslog(LOG_ERR, "Failed to fork process");
            } else {
                // Parent process
                wait(&status);
                if (WIFEXITED(status)) {
                    if (WEXITSTATUS(status) == 0) {
                        syslog(LOG_INFO, "Image capture successful.");
                    } else {
                        syslog(LOG_ERR, "Image capture failed with exit code: %d", WEXITSTATUS(status));
                    }
                } else {
                    syslog(LOG_ERR, "Image capture terminated abnormally.");
                }
            }

            previous_state = current_state;
        }

        gpioDelay(50 * 1000); // Poll every 50ms
    }

    gpioTerminate();
    syslog(LOG_INFO, "Program terminated.");
    closelog();

    return 0;
}

