#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <signal.h>

#define DEFAULT_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_GREY
#define NUM_BUFFERS 1

// Structure to hold camera parameters
typedef struct {
    int fd;
    struct v4l2_buffer buffer;
    void *buffer_start;
    int image_number;
    char device_name[20];
} camera_params_t;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signum) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, stopping...\n", signum);
}

// Function to initialize the camera
int init_camera(camera_params_t *params) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    // Open the device
    params->fd = open(params->device_name, O_RDWR | O_NONBLOCK, 0);
    if (params->fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", params->device_name, strerror(errno));
        return -1;
    }

    // Query capabilities
    if (ioctl(params->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(params->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(params->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(params->fd);
        return -1;
    }

    // Set format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(params->fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(params->fd);
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(params->fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(params->fd);
        return -1;
    }

    if (req.count != NUM_BUFFERS) {
        fprintf(stderr, "Warning: requested %d buffers, got %d\n", NUM_BUFFERS, req.count);
    }

    // Map the buffer
    params->buffer.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    params->buffer.memory = V4L2_MEMORY_MMAP;
    params->buffer.index = 0;

    if (ioctl(params->fd, VIDIOC_QUERYBUF, &params->buffer) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(params->fd);
        return -1;
    }

    params->buffer_start = mmap(NULL, params->buffer.length, PROT_READ | PROT_WRITE, MAP_SHARED, params->fd, params->buffer.m.offset);
    if (params->buffer_start == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        close(params->fd);
        return -1;
    }

    return 0;
}

// Function to start streaming
int start_streaming(camera_params_t *params) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    // Queue the buffer
    params->buffer.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    params->buffer.memory = V4L2_MEMORY_MMAP;
    params->buffer.index = 0;

    if (ioctl(params->fd, VIDIOC_QBUF, &params->buffer) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    // Start streaming
    if (ioctl(params->fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting streaming: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(camera_params_t *params) {
    fd_set fds;
    struct timeval tv;
    int r;

    // Prepare select()
    FD_ZERO(&fds);
    FD_SET(params->fd, &fds);

    // Timeout: 2 seconds
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    // Wait for a frame to be ready
    r = select(params->fd + 1, &fds, NULL, NULL, &tv);

