#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <poll.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define LOG_FILE "frame_log.txt"
#define WIDTH 640
#define HEIGHT 480

// Structure to hold camera and memory mapping information
typedef struct {
    int fd;
    struct v4l2_buffer buf;
    void *buffer;
    size_t buffer_size;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
} camera_info_t;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signum) {
    if (signum == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to initialize the camera
int init_camera(camera_info_t *cam) {
    int fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }
    cam->fd = fd;

    if (ioctl(fd, VIDIOC_QUERYCAP, &cam->cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cam->cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return -1;
    }

    if (!(cam->cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return -1;
    }

    cam->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    cam->fmt.fmt.pix.width = WIDTH;
    cam->fmt.fmt.pix.height = HEIGHT;
    cam->fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    cam->fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &cam->fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    cam->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    cam->buf.memory = V4L2_MEMORY_MMAP;
    cam->buf.index = 0;

    if (ioctl(fd, VIDIOC_REQBUFS, &cam->buf) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    cam->buffer_size = cam->buf.length;
    cam->buffer = mmap(NULL, cam->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, cam->buf.m.offset);
    if (cam->buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &cam->buf) < 0) {
        perror("Error queuing buffer");
        munmap(cam->buffer, cam->buffer_size);
        close(fd);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        munmap(cam->buffer, cam->buffer_size);
        close(fd);
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(camera_info_t *cam) {
    struct pollfd pfd;
    pfd.fd = cam->fd;
    pfd.events = POLLPRI | POLLERR;

    int ret = poll(&pfd, 1, -1); // Wait indefinitely
    if (ret < 0) {
        perror("Error polling");
        return -1;
    }

    if (pfd.revents & POLLPRI) {
        if (ioctl(cam->fd, VIDIOC_DQBUF, &cam->buf) < 0) {
            perror("Error dequeuing buffer");
            return -1;
        }

        if (ioctl(cam->fd, VIDIOC_QBUF, &cam->buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }

        return 0; // Frame captured successfully
    } else if (pfd.revents & POLLERR) {
        fprintf(stderr, "Poll error occurred\n");
        return -1;
    }

    return -1; // Timeout or other error
}

// Function to log the frame timestamp
int log_timestamp(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("Error getting timestamp");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%ld.%06ld\n", ts.tv_sec, ts.tv_nsec / 1000);
    fclose(fp);
    return 0;
}

// Function to release camera resources
void release_camera(camera_info_t *cam) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (cam->fd != -1) {
        ioctl(cam->fd, VIDIOC_STREAMOFF, &type);
        munmap(cam->buffer, cam->buffer_size);
        close(cam->fd);
        cam->fd = -1;
    }
}

int main() {
    camera_info_t camera = { .fd = -1, .buffer = NULL, .buffer_size = 0 };

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize camera
    if (init_camera(&camera) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (program_running) {
        if (capture_frame(&camera) == 0) {
            if (log_timestamp(LOG_FILE) != 0) {
                fprintf(stderr, "Error logging timestamp\n");
            }
        } else {
            fprintf(stderr, "Error capturing frame\n");
        }
    }

    // Release camera resources
    release_camera(&camera);

    return EXIT_SUCCESS;
}

