        if (ioctl(cam->fd, VIDIOC_QBUF, &cam->buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }

        return 0; // Frame captured successfully
    } else if (pfd.revents & POLLERR) {
        fprintf(stderr, "Poll error occurred\n");
        return -1;
    }

    return -1; // Timeout or other error
