    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("Error getting timestamp");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%ld.%06ld\n", ts.tv_sec, ts.tv_nsec / 1000);
