#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

#define NUM_BUFFERS 4
#define MAX_FRAME_SIZE 640 * 480 * 2 // YUYV
#define MAX_UDP_PAYLOAD 65000

// Structure to hold V4L2 buffer information
struct buffer {
    void   *start;
    size_t  length;
};

// Structure to hold frame fragment information
struct fragment {
    uint8_t *data;
    size_t size;
};

// Global variables
static int                  fd_v4l2 = -1;
static int                  fd_udp  = -1;
static struct buffer        buffers[NUM_BUFFERS];
static unsigned int         frame_index = 0;
static struct v4l2_format   fmt;
static struct v4l2_requestbuffers req;
static struct in_addr       server_ip;
static int                  server_port;
static volatile sig_atomic_t stop_flag = 0;

// Function prototypes
int  init_v4l2(void);
int  init_udp(void);
int  start_streaming(void);
int  capture_frame(void);
int  fragment_frame(const void *frame_data, size_t frame_size, struct fragment **fragments, size_t *num_fragments);
int  send_fragments(const struct fragment *fragments, size_t num_fragments);
void cleanup(void);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal %d received, stopping...\n", sig);
    stop_flag = 1;
}

// Initialize V4L2 device
int init_v4l2(void) {
    fd_v4l2 = open("/dev/video0", O_RDWR | O_NONBLOCK, 0);
    if (fd_v4l2 < 0) {
        perror("Error opening /dev/video0");
        return -1;
    }

    // Set format
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd_v4l2, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd_v4l2);
        return -1;
    }

    // Request buffers
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd_v4l2, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd_v4l2);
        return -1;
    }

    // Map buffers
    for (int i = 0; i < NUM_BUFFERS; ++i) {
        struct v4l2_buffer buf;
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd_v4l2, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            cleanup();
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd_v4l2, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            cleanup();
            return -1;
        }

        if (ioctl(fd_v4l2, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            cleanup();
            return -1;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd_v4l2, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        cleanup();
        return -1;
    }

    return 0;
}

// Initialize UDP socket
int init_udp(void) {
    fd_udp = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd_udp < 0) {
        perror("Error creating socket");
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr = server_ip;
    addr.sin_port = htons(server_port);

    if (connect(fd_udp, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error connecting socket");
        close(fd_udp);
        return -1;
    }

    return 0;
}

// Start streaming
int start_streaming(void) {
    if (init_v4l2() < 0) {
        return -1;
    }

    if (init_udp() < 0) {
        cleanup();
        return -1;
    }

    return 0;
}

// Capture a single frame
int capture_frame(void) {
    struct v4l2_buffer buf;
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd_v4l2, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    if (fragment_frame(buffers[buf.index].start, buffers[buf.index].length, NULL, NULL) == 0) {
        if (ioctl(fd_v4l2, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    } else {
        fprintf(stderr, "Error fragmenting frame\n");
        if (ioctl(fd_v4l2, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
        return -1;
    }

    return 0;
}

// Fragment a frame into UDP datagrams
int fragment_frame(const void *frame_data, size_t frame_size, struct fragment **fragments, size_t *num_fragments) {
    *num_fragments = (frame_size + MAX_UDP_PAYLOAD - 1) / MAX_UDP_PAYLOAD;
    *fragments = (struct fragment *)malloc(sizeof(struct fragment) * (*num_fragments));
    if (*fragments == NULL) {
        perror("Error allocating memory for fragments");
        return -1;
    }

    for (size_t i = 0; i < *num_fragments; ++i) {
        (*fragments)[i].data = (uint8_t *)malloc(MAX_UDP_PAYLOAD);
        if ((*fragments)[i].data == NULL) {
            perror("Error allocating memory for fragment data");
            // Free already allocated fragments
            for (size_t j = 0; j < i; ++j) {
                free((*fragments)[j].data);
            }
            free(*fragments);
            return -1;
        }
        (*fragments)[i].size = (i < *num_fragments - 1) ? MAX_UDP_PAYLOAD : frame_size - i * MAX_UDP_PAYLOAD;
        memcpy((*fragments)[i].data, (uint8_t *)frame_data + i * MAX_UDP_PAYLOAD, (*fragments)[i].size);
    }

    return 0;
}

// Send fragments over UDP
int send_fragments(const struct fragment *fragments, size_t num_fragments) {
    for (size_t i = 0; i < num_fragments; ++i) {
        // Construct header
        uint8_t header[12];
        memcpy(header, &frame_index, sizeof(frame_index));
        memcpy(header + sizeof(frame_index), &i, sizeof(i));
        memcpy(header + sizeof(frame_index) + sizeof(i), &num_fragments, sizeof(num_fragments));
        memcpy(header + sizeof(frame_index) + sizeof(i) + sizeof(num_fragments), &fragments[i].size, sizeof(fragments[i].size));

        // Send data
        uint8_t *packet = (uint8_t *)malloc(fragments[i].size + 12);
        if (packet == NULL) {
            perror("Error allocating memory for packet");
            return -1;
        }
        memcpy(packet, header, 12);
        memcpy(packet + 12, fragments[i].data, fragments[i].size);

        ssize_t bytes_sent = sendto(fd_udp, packet, fragments[i].size + 12, 0, NULL, 0);
        if (bytes_sent < 0) {
            perror("Error sending data");
            free(packet);
            return -1;
        }
        free(packet);
    }
    return 0;
}

// Cleanup resources
void cleanup(void) {
    stop_flag = 1;
    if (fd_v4l2 != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ioctl(fd_v4l2, VIDIOC_STREAMOFF, &type);

        for (int i = 0; i < NUM_BUFFERS; ++i) {
            if (buffers[i].start != MAP_FAILED && buffers[i].start != NULL) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        close(fd_v4l2);
    }
    if (fd_udp != -1) {
        close(fd_udp);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    // Parse server IP address
    if (inet_pton(AF_INET, argv[1], &server_ip) <= 0) {
        fprintf(stderr, "Invalid server IP address\n");
        return EXIT_FAILURE;
    }

    // Parse server port
    server_port = atoi(argv[2]);
    if (server_port <= 0 || server_port > 65535) {
        fprintf(stderr, "Invalid server port\n");
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    // Start streaming
    if (start_streaming() < 0) {
        fprintf(stderr, "Failed to start streaming\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (!stop_flag) {
        if (capture_frame() < 0) {
            fprintf(stderr, "Failed to capture frame\n");
            break;
        }
        frame_index++;
    }

    // Cleanup
    cleanup();

    return EXIT_SUCCESS;
}

