#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <signal.h>
#include <errno.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 1920
#define IMAGE_HEIGHT 1080
#define NUM_BUFFERS 4
#define IMAGE_FILE "image.jpg"

// Structure to hold camera information
typedef struct {
    int fd;
    struct v4l2_buffer *buffers;
    void **buffer_start;
    int n_buffers;
    int streaming;
} camera_t;

camera_t camera;

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    printf("\nCaught signal %d, cleaning up...\n", signum);
    camera.streaming = 0; // Stop streaming

    // Unmap buffers
    if (camera.buffer_start) {
        for (int i = 0; i < camera.n_buffers; ++i) {
            if (camera.buffer_start[i]) {
                if (munmap(camera.buffer_start[i], camera.buffers[i].length) == -1) {
                    perror("munmap");
                }
            }
        }
    }

    // Close device
    if (camera.fd != -1) {
        close(camera.fd);
    }

    // Free buffers
    if (camera.buffers) {
        free(camera.buffers);
    }
    if (camera.buffer_start) {
        free(camera.buffer_start);
    }

    exit(0);
}

// Function to initialize the camera
int init_camera(camera_t *camera) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_streamparm streamparm;

    camera->fd = open(DEVICE_NAME, O_RDWR); // Open device in blocking mode
    if (camera->fd == -1) {
        perror("open");
        return -1;
    }

    // Check device capabilities
    if (ioctl(camera->fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        close(camera->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(camera->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
