#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_BUTTON 6
#define TILT_DOWN_BUTTON 7
#define PAN_LEFT_BUTTON 8
#define PAN_RIGHT_BUTTON 9

// Define servo limits
#define SERVO_MIN_PULSE_WIDTH 1000  // 1 ms
#define SERVO_MAX_PULSE_WIDTH 2000  // 2 ms
#define SERVO_RANGE (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH)

// Define servo position limits
#define SERVO_MIN_POSITION 25
#define SERVO_MAX_POSITION 125

// Global variables
volatile sig_atomic_t terminate = 0;
int pan_position = 75;
int tilt_position = 75;

// Function prototypes
void signal_handler(int signal);
void set_servo_position(int pin, int position);
int get_button_state(int pin);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Function to set servo position using pigpio
void set_servo_position(int pin, int position) {
    if (position < SERVO_MIN_POSITION) {
        position = SERVO_MIN_POSITION;
    } else if (position > SERVO_MAX_POSITION) {
        position = SERVO_MAX_POSITION;
    }

    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)(position - SERVO_MIN_POSITION) / (SERVO_MAX_POSITION - SERVO_MIN_POSITION)) * SERVO_RANGE);
    gpioServo(pin, pulse_width);
}

// Function to read button state using pigpio
int get_button_state(int pin) {
    return gpioRead(pin);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_UP_BUTTON, PI_INPUT);
    gpioSetMode(TILT_DOWN_BUTTON, PI_INPUT);
    gpioSetMode(PAN_LEFT_BUTTON, PI_INPUT);
    gpioSetMode(PAN_RIGHT_BUTTON, PI_INPUT);

    // Enable pull-ups on buttons
    gpioSetPullUpDown(TILT_UP_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(PAN_LEFT_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_BUTTON, PI_PUD_UP);

    // Set initial servo positions
    set_servo_position(PAN_SERVO_PIN, pan_position);
    set_servo_position(TILT_SERVO_PIN, tilt_position);

    // Install signal handler
    signal(SIGINT, signal_handler);

    printf("Pan-Tilt control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read button states
        int tilt_up = get_button_state(TILT_UP_BUTTON);
        int tilt_down = get_button_state(TILT_DOWN_BUTTON);
        int pan_left = get_button_state(PAN_LEFT_BUTTON);
        int pan_right = get_button_state(PAN_RIGHT_BUTTON);

        // Update servo positions based on button presses
        if (tilt_up == 0) {
            tilt_position += 5;
            set_servo_position(TILT_SERVO_PIN, tilt_position);
            gpioDelay(20000); // Debounce delay (20 ms)
        }
        if (tilt_down == 0) {
            tilt_position -= 5;
            set_servo_position(TILT_SERVO_PIN, tilt_position);
            gpioDelay(20000); // Debounce delay (20 ms)
        }
        if (pan_left == 0) {
            pan_position -= 5;
            set_servo_position(PAN_SERVO_PIN, pan_position);
            gpioDelay(20000); // Debounce delay (20 ms)
        }
        if (pan_right == 0) {
            pan_position += 5;
            set_servo_position(PAN_SERVO_PIN, pan_position);
            gpioDelay(20000); // Debounce delay (20 ms)
        }

        gpioDelay(50000); // Poll every 50 ms
    }

    // Cleanup
    set_servo_position(PAN_SERVO_PIN, 75);
    set_servo_position(TILT_SERVO_PIN, 75);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

