#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/select.h>
#include <jpeglib.h>
#include <setjmp.h>

#define VIDEO_DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define NUM_BUFFERS 4
#define BLUR_RADIUS 2
#define JPEG_QUALITY 75

// Structure to hold camera parameters
typedef struct {
    int fd;
    struct v4l2_buffer buf;
    void *buffer_start[NUM_BUFFERS];
    size_t buffer_size[NUM_BUFFERS];
    int current_buffer;
    int running;
} camera_params_t;

// Global camera parameters
camera_params_t camera_params;

// Signal handler for SIGINT
void signal_handler(int signum) {
    if (signum == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
        camera_params.running = 0; // Stop the main loop
    }
}

// Function to initialize the camera
int init_camera(camera_params_t *params) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    int i;

    params->fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (params->fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", VIDEO_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(params->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(params->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", VIDEO_DEVICE);
        close(params->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", VIDEO_DEVICE);
        close(params->fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(params->fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(params->fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(params->fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(params->fd);
        return -1;
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(params->fd);
        return -1;
    }

    for (i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(params->fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer %d: %s\n", i, strerror(errno));
            close(params->fd);
            return -1;
        }

        params->buffer_start[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, params->fd, buf.m.offset);
        if (params->buffer_start[i] == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %d: %s\n", i, strerror(errno));
            close(params->fd);
            return -1;
        }
        params->buffer_size[i] = buf.length;
    }

    for (i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(params->fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer %d: %s\n", i, strerror(errno));
            close(params->fd);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(params->fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        close(params->fd);
        return -1;
    }

    return 0;
}

// Function to capture a single frame
int capture_frame(camera_params_t *params, void **frame_data, size_t *frame_size) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(params->fd, &fds);

    tv.tv_sec = 2; // 2-second timeout
    tv.tv_usec = 0;

    r = select(params->fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    memset(&params->buf, 0, sizeof(params->buf));
    params->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    params->buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(params->fd, VIDIOC_DQBUF, &params->buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    *frame_data = params->buffer_start[params->buf.index];
    *frame_size = params->buffer_size[params->buf.index];
    params->current_buffer = params->buf.index;

    if (ioctl(params->fd, VIDIOC_QBUF, &params->buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to convert YUYV to RGB24
void yuyv_to_rgb24(void *yuyv_data, int width, int height, void *rgb24_data) {
    unsigned char *yuyv = (unsigned char *)yuyv_data;
    unsigned char *rgb = (unsigned char *)rgb24_data;
    int i, j;

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j += 2) {
            unsigned char y1 = yuyv[i * width * 2 + j * 2 + 0];
            unsigned char u = yuyv[i * width * 2 + j * 2 + 1];
            unsigned char y2 = yuyv[i * width * 2 + j * 2 + 2];
            unsigned char v = yuyv[i * width * 2 + j * 2 + 3];

            int c = y1 - 16;
            int d = u - 128;
            int e = v - 128;

            int r1 = (298 * c + 409 * e + 128) >> 8;
            int g1 = (298 * c - 100 * d - 208 * e + 128) >> 8;
            int b1 = (298 * c + 516 * d + 128) >> 8;

            int r2 = (298 * c + 409 * e + 128) >> 8;
            int g2 = (298 * c - 100 * d - 208 * e + 128) >> 8;
            int b2 = (298 * c + 516 * d + 128) >> 8;

            if (r1 < 0) r1 = 0; if (r1 > 255) r1 = 255;
            if (g1 < 0) g1 = 0; if (g1 > 255) g1 = 255;
            if (b1 < 0) b1 = 0; if (b1 > 255) b1 = 255;
            if (r2 < 0) r2 = 0; if (r2 > 255) r2 = 255;
            if (g2 < 0) g2 = 0; if (g2 > 255) g2 = 255;
            if (b2 < 0) b2 = 0; if (b2 > 255) b2 = 255;

            rgb[i * width * 3 + j * 3 + 0] = r1;
            rgb[i * width * 3 + j * 3 + 1] = g1;
            rgb[i * width * 3 + j * 3 + 2] = b1;
            rgb[i * width * 3 + (j + 1) * 3 + 0] = r2;
            rgb[i * width * 3 + (j + 1) * 3 + 1] = g2;
            rgb[i * width * 3 + (j + 1) * 3 + 2] = b2;
        }
    }
}

// Function to apply a 5x5 box blur filter
void box_blur(void *rgb24_data, int width, int height, void *blurred_data) {
    unsigned char *input = (unsigned char *)rgb24_data;
    unsigned char *output = (unsigned char *)blurred_data;
    int i, j, k, l;
    int r, g, b;

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j++) {
            r = 0;
            g = 0;
            b = 0;
            int count = 0;

            for (k = -BLUR_RADIUS; k <= BLUR_RADIUS; k++) {
                for (l = -BLUR_RADIUS; l <= BLUR_RADIUS; l++) {
                    int x = j + k;
                    int y = i + l;

                    if (x >= 0 && x < width && y >= 0 && y < height) {
                        r += input[(y * width + x) * 3 + 0];
                        g += input[(y * width + x) * 3 + 1];
                        b += input[(y * width + x) * 3 + 2];
                        count++;
                    }
                }
            }

            output[(i * width + j) * 3 + 0] = r / count;
            output[(i * width + j) * 3 + 1] = g / count;
            output[(i * width + j) * 3 + 2] = b / count;
        }
    }
}

// Function to save JPEG image using libjpeg
int save_jpeg(void *image_data, int width, int height, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        fprintf(stderr, "Error opening output file: %s\n", filename);
        jpeg_destroy_compress(&cinfo);
        return -1;
    }
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &((unsigned char *)image_data)[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

// Function to generate filename with timestamp
void generate_filename(char *filename, size_t filename_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, filename_size, "capture_%Y%m%d_%H%M%S.jpg", timeinfo);
}

// Function to clean up camera resources
void cleanup_camera(camera_params_t *params) {
    int i;
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (params->fd != -1) {
        if (params->running) {
            ioctl(params->fd, VIDIOC_STREAMOFF, &type);
        }

        for (i = 0; i < NUM_BUFFERS; i++) {
            if (params->buffer_start[i] != NULL) {
                munmap(params->buffer_start[i], params->buffer_size[i]);
            }
        }

        close(params->fd);
    }
}

int main() {
    void *frame_data = NULL;
    size_t frame_size = 0;
    void *rgb24_data = NULL;
    void *blurred_data = NULL;
    char filename[64];

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize camera
    camera_params.fd = -1; // Initialize to an invalid file descriptor
    camera_params.running = 1; // Initialize running flag
    if (init_camera(&camera_params) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return 1;
    }

    // Allocate memory for RGB24 and blurred images
    rgb24_data = malloc(WIDTH * HEIGHT * 3);
    blurred_data = malloc(WIDTH * HEIGHT * 3);
    if (!rgb24_data || !blurred_data) {
        fprintf(stderr, "Memory allocation failed\n");
        cleanup_camera(&camera_params);
        return 1;
    }

    // Capture frame
    if (capture_frame(&camera_params, &frame_data, &frame_size) < 0) {
        fprintf(stderr, "Frame capture failed\n");
        free(rgb24_data);
        free(blurred_data);
        cleanup_camera(&camera_params);
        return 1;
    }

    // Convert YUYV to RGB24
    yuyv_to_rgb24(frame_data, WIDTH, HEIGHT, rgb24_data);

    // Apply box blur
    box_blur(rgb24_data, WIDTH, HEIGHT, blurred_data);

    // Generate filename
    generate_filename(filename, sizeof(filename));

    // Save JPEG image
    if (save_jpeg(blurred_data, WIDTH, HEIGHT, filename) < 0) {
        fprintf(stderr, "JPEG saving failed\n");
    } else {
        printf("Saved JPEG to %s\n", filename);
    }

    // Clean up resources
    free(rgb24_data);
    free(blurred_data);
    cleanup_camera(&camera_params);

    return 0;
}

