// Function to save JPEG image using libjpeg
int save_jpeg(void *image_data, int width, int height, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        fprintf(stderr, "Error opening output file: %s\n", filename);
        jpeg_destroy_compress(&cinfo);
        return -1;
    }
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &((unsigned char *)image_data)[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

// Function to generate filename with timestamp
void generate_filename(char *filename, size_t filename_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, filename_size, "capture_%Y%m%d_%H%M%S.jpg", timeinfo);
}

// Function to clean up camera resources
void cleanup_camera(camera_params_t *params) {
    int i;
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (params->fd != -1) {
        if (params->running) {
            ioctl(params->fd, VIDIOC_STREAMOFF, &type);
        }

        for (i = 0; i < NUM_BUFFERS; i++) {
            if (params->buffer_start[i] != NULL) {
                munmap(params->buffer_start[i], params->buffer_size[i]);
            }
        }

        close(params->fd);
    }
}

int main() {
    void *frame_data = NULL;
    size_t frame_size = 0;
    void *rgb24_data = NULL;
    void *blurred_data = NULL;
    char filename[64];

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize camera
    camera_params.fd = -1; // Initialize to an invalid file descriptor
    camera_params.running = 1; // Initialize running flag
    if (init_camera(&camera_params) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return 1;
    }

    // Allocate memory for RGB24 and blurred images
    rgb24_data = malloc(WIDTH * HEIGHT * 3);
    blurred_data = malloc(WIDTH * HEIGHT * 3);
    if (!rgb24_data || !blurred_data) {
        fprintf(stderr, "Memory allocation failed\n");
        cleanup_camera(&camera_params);
        return 1;
    }

    // Capture frame
    if (capture_frame(&camera_params, &frame_data, &frame_size) < 0) {
        fprintf(stderr, "Frame capture failed\n");
        free(rgb24_data);
        free(blurred_data);
        cleanup_camera(&camera_params);
        return 1;
    }

    // Convert YUYV to RGB24
    yuyv_to_rgb24(frame_data, WIDTH, HEIGHT, rgb24_data);

    // Apply box blur
    box_blur(rgb24_data, WIDTH, HEIGHT, blurred_data);

    // Generate filename
    generate_filename(filename, sizeof(filename));

    // Save JPEG image
    if (save_jpeg(blurred_data, WIDTH, HEIGHT, filename) < 0) {
        fprintf(stderr, "JPEG saving failed\n");
    } else {
        printf("Saved JPEG to %s\n", filename);
    }

    // Clean up resources
    free(rgb24_data);
    free(blurred_data);
    cleanup_camera(&camera_params);

    return 0;
}

