#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_fmtdesc fmtdesc;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    struct v4l2_queryctrl queryctrl;
    int i, j, k;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("Error opening device");
        return 1;
    }

    // Query capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    printf("Driver: %s\n", cap.driver);
    printf("Card: %s\n", cap.card);
    printf("Bus info: %s\n", cap.bus_info);
    printf("Version: %d.%d.%d\n", (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);
    printf("Capabilities: 0x%08X\n", cap.capabilities);

    // Enumerate supported formats
    fmtdesc.index = 0;
    fmtdesc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    printf("\nSupported Formats:\n");
    while (ioctl(fd, VIDIOC_ENUM_FMT, &fmtdesc) != -1) {
        printf("  %d. %s (%s)\n", fmtdesc.index + 1, fmtdesc.description, fmtdesc.pixelformat);
        fmtdesc.index++;
    }

    // Enumerate supported frame sizes
    frmsize.index = 0;
    frmsize.pixel_format = V4L2_PIX_FMT_MJPEG; // Choose a format
    printf("\nSupported Frame Sizes:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) != -1) {
        if (frmsize.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            printf("  %d. %dx%d\n", frmsize.index + 1, frmsize.discrete.width, frmsize.discrete.height);
        } else if (frmsize.type == V4L2_FRMSIZE_TYPE_CONTINUOUS) {
            printf("  %d. Continuous: %dx%d - %dx%d\n", frmsize.index + 1, frmsize.continuous.min_width, frmsize.continuous.min_height, frmsize.continuous.max_width, frmsize.continuous.max_height);
        } else if (frmsize.type == V4L2_FRMSIZE_TYPE_STEPWISE) {
            printf("  %d. Stepwise: %dx%d - %dx%d, step %dx%d\n", frmsize.index + 1, frmsize.stepwise.min_width, frmsize.stepwise.min_height, frmsize.stepwise.max_width, frmsize.stepwise.max_height, frmsize.stepwise.step_width, frmsize.stepwise.step_height);
        }
        frmsize.index++;
    }

    // Enumerate supported frame intervals
    frmival.index = 0;
    frmival.pixel_format = V4L2_PIX_FMT_MJPEG; // Choose a format
    frmival.width = 640; // Choose a width
    frmival.height = 480; // Choose a height
    printf("\nSupported Frame Intervals:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) != -1) {
        if (frmival.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
            printf("  %d. Discrete: %d/%d\n", frmival.index + 1, frmival.discrete.numerator, frmival.discrete.denominator);
        } else if (frmival.type == V4L2_FRMIVAL_TYPE_CONTINUOUS) {
            printf("  %d. Continuous: %d/%d - %d/%d\n", frmival.index + 1, frmival.continuous.min.numerator, frmival.continuous.min.denominator, frmival.continuous.max.numerator, frmival.continuous.max.denominator);
        } else if (frmival.type == V4L2_FRMIVAL_TYPE_STEPWISE) {
            printf("  %d. Stepwise: %d/%d - %d/%d, step %d/%d\n", frmival.index + 1, frmival.stepwise.min.numerator, frmival.stepwise.min.denominator, frmival.stepwise.max.numerator, frmival.stepwise.max.denominator, frmival.stepwise.step.numerator, frmival.stepwise.step.denominator);
        }
        frmival.index++;
    }

    // Check for autofocus support
    queryctrl.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) != -1) {
        printf("\nAutofocus Support: %s\n", (queryctrl.flags & V4L2_CTRL_FLAG_DISABLED) ? "No" : "Yes");
    } else {
        printf("\nAutofocus Support: No (Control not found)\n");
    }

    close(fd);
    return 0;
}

