#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000

// Servo center position
#define SERVO_CENTER_PULSE_WIDTH 1500

// Servo increment/decrement step
#define SERVO_STEP 10

// Servo movement delay (ms)
#define SERVO_DELAY 50

// Global variables for servo positions
int pan_position = SERVO_CENTER_PULSE_WIDTH;
int tilt_position = SERVO_CENTER_PULSE_WIDTH;

// Function prototypes
void cleanup_handler(int signum);
void button_pressed_callback(int gpio, int level, uint32_t tick);

// Signal handler for graceful shutdown
void cleanup_handler(int signum) {
    printf("\nCaught signal %d, cleaning up...\n", signum);
    gpioServo(PAN_SERVO_PIN, 0); // Stop PWM on pan servo
    gpioServo(TILT_SERVO_PIN, 0); // Stop PWM on tilt servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Callback function for button presses
void button_pressed_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Button pressed (active low)
        if (gpio == UP_BUTTON_PIN) {
            tilt_position += SERVO_STEP;
            if (tilt_position > SERVO_MAX_PULSE_WIDTH) {
                tilt_position = SERVO_MAX_PULSE_WIDTH;
            }
            gpioServo(TILT_SERVO_PIN, tilt_position);
        } else if (gpio == DOWN_BUTTON_PIN) {
            tilt_position -= SERVO_STEP;
            if (tilt_position < SERVO_MIN_PULSE_WIDTH) {
                tilt_position = SERVO_MIN_PULSE_WIDTH;
            }
            gpioServo(TILT_SERVO_PIN, tilt_position);
        } else if (gpio == LEFT_BUTTON_PIN) {
            pan_position -= SERVO_STEP;
            if (pan_position < SERVO_MIN_PULSE_WIDTH) {
                pan_position = SERVO_MIN_PULSE_WIDTH;
            }
            gpioServo(PAN_SERVO_PIN, pan_position);
        } else if (gpio == RIGHT_BUTTON_PIN) {
            pan_position += SERVO_STEP;
            if (pan_position > SERVO_MAX_PULSE_WIDTH) {
                pan_position = SERVO_MAX_PULSE_WIDTH;
            }
            gpioServo(PAN_SERVO_PIN, pan_position);
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    // Enable internal pull-ups on button pins
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set initial servo positions
    gpioServo(PAN_SERVO_PIN, SERVO_CENTER_PULSE_WIDTH);
    gpioServo(TILT_SERVO_PIN, SERVO_CENTER_PULSE_WIDTH);

    // Set alert functions for button presses
    gpioSetAlertFunc(UP_BUTTON_PIN, button_pressed_callback);
    gpioSetAlertFunc(DOWN_BUTTON_PIN, button_pressed_callback);
    gpioSetAlertFunc(LEFT_BUTTON_PIN, button_pressed_callback);
    gpioSetAlertFunc(RIGHT_BUTTON_PIN, button_pressed_callback);

    // Install signal handlers
    signal(SIGINT, cleanup_handler);
    signal(SIGTERM, cleanup_handler);

    // Print startup message
    printf("Pan-Tilt Control Program\n");
    printf("Pan Servo: GPIO %d\n", PAN_SERVO_PIN);
    printf("Tilt Servo: GPIO %d\n", TILT_SERVO_PIN);
    printf("UP Button: GPIO %d\n", UP_BUTTON_PIN);
    printf("DOWN Button: GPIO %d\n", DOWN_BUTTON_PIN);
    printf("LEFT Button: GPIO %d\n", LEFT_BUTTON_PIN);
    printf("RIGHT Button: GPIO %d\n", RIGHT_BUTTON_PIN);
    printf("Servo Center Position: %d us\n", SERVO_CENTER_PULSE_WIDTH);
    printf("Press Ctrl+C to exit\n");

    // Main loop
    while (1) {
        gpioDelay(SERVO_DELAY * 1000); // Delay for 50ms
    }

    return 0;
}

