#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_QUALITY 85
#define SERVER_URL "http://<server_ip>:<server_port>/upload" // Replace with your server URL
#define MOTION_CAPTURE_DIR "motion_captures"

// Global variables for signal handling
static volatile int running = 1;
static char *server_ip = NULL;
static char *server_port = NULL;

// Structure to hold the timestamp
typedef struct {
    char timestamp[30];
} Timestamp;

// Function prototypes
int initialize_gpio();
int detect_motion();
int capture_image(char *filename);
int send_data(char *filename, char *timestamp);
void signal_handler(int signal);
int create_directory(const char *path);
int get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    running = 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    return 0;
}

