#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Configuration
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_TIMEOUT_MS 50

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
void cleanup_gpio(void);
int capture_image(const char *filename);
int generate_filename(char *filename, size_t filename_size);
int log_event(const char *message);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        log_event("Received termination signal.");
    }
}

// Initialize GPIO
int init_gpio(void) {
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_rising_edge_events(line, "motion_sensor");
    if (ret < 0) {
        perror("gpiod_line_request_rising_edge_events");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO
void cleanup_gpio(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Capture image using libcamera-still
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview", filename);
    int ret = system(command);
    if (ret == -1) {
        perror("system");
        return -1;
    }
    return ret;
}

// Generate filename with timestamp
int generate_filename(char *filename, size_t filename_size) {
    time_t rawtime;
    struct tm *timeinfo;
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, filename_size, IMAGE_DIR "/%Y%m%d_%H%M%S_", timeinfo);
    snprintf(filename + strlen(filename), filename_size - strlen(filename), "%03ld.jpg", ts.tv_nsec / 1000000);
    return 0;
}

// Log event to file
int log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
    return 0;
}

int main(void) {
    char filename[256];
    int ret;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    log_event("Starting motion capture program.");

    // Initialize GPIO
    if (init_gpio() < 0) {
        log_event("GPIO initialization failed.");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    log_event("GPIO initialized successfully.");

    // Main loop
    while (!terminate) {
        ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        }

        // Debounce
        struct timespec debounce_time = {0, DEBOUNCE_TIMEOUT_MS * 1000000L}; // 50ms
        nanosleep(&debounce_time, NULL);

        // Generate filename
        if (generate_filename(filename, sizeof(filename)) < 0) {
            log_event("Failed to generate filename.");
            continue;
        }

        // Capture image
        ret = capture_image(filename);
        if (ret == 0) {
            char log_message[256];
            snprintf(log_message, sizeof(log_message), "Image captured: %s", filename);
            log_event(log_message);
        } else {
            char log_message[256];
            snprintf(log_message, sizeof(log_message), "Failed to capture image: %s", filename);
            log_event(log_message);
        }
    }

    // Cleanup
    log_event("Exiting program.");
    cleanup_gpio();
    fclose(log_file);

    return EXIT_SUCCESS;
}

