#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Define pulse width limits (microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define angle limits (degrees)
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define angle increment (degrees)
#define ANGLE_INCREMENT 5

// Global variables for current pan and tilt angles
int current_pan_angle = 90;
int current_tilt_angle = 90;

// Function prototypes
int set_servo_angle(int gpio, int angle);
int get_user_input(char *input);
void handle_input(char input);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, setting servos to neutral position and exiting...\n");
        set_servo_angle(PAN_GPIO, 90);
        set_servo_angle(TILT_GPIO, 90);
        gpioTerminate();
        exit(0);
    }
}

// Function to set the servo angle
int set_servo_angle(int gpio, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (0-180 degrees).\n");
        return -1;
    }

    // Calculate pulse width in microseconds
    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)(angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

    // Set PWM duty cycle
    int result = gpioPWM(gpio, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle for GPIO %d. pigpio error code: %d\n", gpio, result);
        return -1;
    }

    return 0;
}

// Function to get user input
int get_user_input(char *input) {
    printf("Enter input (arrow keys or 'q'): ");
    if (fgets(input, 256, stdin) == NULL) {
        perror("Error reading input");
        return -1;
    }

    // Remove trailing newline character
    size_t len = strlen(input);
    if (len > 0 && input[len - 1] == '\n') {
        input[len - 1] = '\0';
    }

    return 0;
}

// Function to handle user input
void handle_input(char input) {
    switch (input) {
        case 'a': // Left
            if (current_pan_angle > MIN_ANGLE) {
                current_pan_angle -= ANGLE_INCREMENT;
                set_servo_angle(PAN_GPIO, current_pan_angle);
            } else {
                fprintf(stderr, "Error: Pan angle already at minimum.\n");
            }
            break;
        case 'd': // Right
            if (current_pan_angle < MAX_ANGLE) {
                current_pan_angle += ANGLE_INCREMENT;
                set_servo_angle(PAN_GPIO, current_pan_angle);
            } else {
                fprintf(stderr, "Error: Pan angle already at maximum.\n");
            }
            break;
        case 'w': // Up
            if (current_tilt_angle > MIN_ANGLE) {
                current_tilt_angle -= ANGLE_INCREMENT;
                set_servo_angle(TILT_GPIO, current_tilt_angle);
            } else {
                fprintf(stderr, "Error: Tilt angle already at minimum.\n");
            }
            break;
        case 's': // Down
            if (current_tilt_angle < MAX_ANGLE) {
                current_tilt_angle += ANGLE_INCREMENT;
                set_servo_angle(TILT_GPIO, current_tilt_angle);
            } else {
                fprintf(stderr, "Error: Tilt angle already at maximum.\n");
            }
            break;
        case 'q': // Quit
            printf("Exiting...\n");
            set_servo_angle(PAN_GPIO, 90);
            set_servo_angle(TILT_GPIO, 90);
            gpioTerminate();
            exit(0);
        default:
            printf("Invalid input. Use arrow keys (a, d, w, s) or 'q' to quit.\n");
            break;
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for pan and tilt servos
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);

    // Set initial servo angles
    set_servo_angle(PAN_GPIO, current_pan_angle);
    set_servo_angle(TILT_GPIO, current_tilt_angle);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    char input[256];

    // Main loop
    while (1) {
        if (get_user_input(input) == 0) {
            handle_input(input[0]);
        }

        // Delay to prevent excessive CPU usage
        gpioDelay(100); // 100 milliseconds
    }

    return 0;
}

