    {0x00, 0x7C, 0x14, 0x14, 0x08},   // p
    {0x00, 0x18, 0x24, 0x24, 0x7C},   // q
    {0x00, 0x7C, 0x08, 0x04, 0x04},   // r
    {0x00, 0x48, 0x54, 0x54, 0x24},   // s
    {0x00, 0x04, 0x3F, 0x44, 0x04},   // t
    {0x00, 0x3C, 0x40, 0x40, 0x3C},   // u
    {0x00, 0x1C, 0x20, 0x40, 0x1C},   // v
    {0x00, 0x3C, 0x40, 0x30, 0x3C},   // w
    {0x00, 0x44, 0x28, 0x10, 0x44},   // x
    {0x00, 0x1C, 0xA0, 0xA0, 0x7C},   // y
    {0x00, 0x44, 0x64, 0x54, 0x4C},   // z
    {0x00, 0x08, 0x36, 0x41, 0x00},   // {
    {0x00, 0x00, 0x00, 0x7F, 0x00},   // |
    {0x00, 0x41, 0x36, 0x08, 0x00},   // }
    {0x00, 0x10, 0x08, 0x08, 0x10}    // ~
};

// Function prototypes
int read_cpu_temp(void);
float read_cpu_usage(void);
int oled_init(int i2c_handle);
int oled_clear(int i2c_handle);
int oled_display_text(int i2c_handle, int x, int y, const char *text);
int oled_display_temp_usage(int i2c_handle, float temperature, float usage);
void signal_handler(int signal);

// Function to read CPU temperature from file
int read_cpu_temp(void) {
    FILE *fp;
    int temp = -1;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file.\n");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error: Could not read temperature from file.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to read CPU usage from /proc/stat
float read_cpu_usage(void) {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    static unsigned long long prev_total = 0;
    static unsigned long long prev_idle_total = 0;
    float usage;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open /proc/stat.\n");
        return -1.0;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error: Could not read CPU stats from /proc/stat.\n");
        fclose(fp);
        return -1.0;
    }

    fclose(fp);

    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    unsigned long long idle_total = idle + iowait;

    if (prev_total != 0) {
        unsigned long long total_diff = total - prev_total;
        unsigned long long idle_diff = idle_total - prev_idle_total;
        usage = (float)(total_diff - idle_diff) / total_diff * 100.0;
    } else {
        usage = 0.0; // Initial reading
    }

    prev_total = total;
    prev_idle_total = idle_total;

    return usage;
}

// Function to initialize the OLED screen
int oled_init(int i2c_handle) {
    // Initialization sequence (SSD1306 datasheet)
    char init_commands[] = {
        0xAE,       // Display off
        0xD5, 0x80, // Clock divide ratio (0x80 = 100 fps)
        0xA8, 0x3F, // Multiplex ratio (63 = 64 rows)
        0xD3, 0x00, // Display offset
        0x40,       // Start line
        0x8D, 0x14, // Charge pump setting (0x14 = enable)
        0x20, 0x00, // Memory addressing mode (0x00 = horizontal)
        0xA1,       // Segment remap (A1 = column address 127 is mapped to SEG0)
        0xC8,       // COM output scan direction (C8 = scan from COM[N-1] to COM0)
        0xDA, 0x12, // COM pins hardware configuration
        0x81, 0xCF, // Contrast control
        0xD9, 0xF1, // Pre-charge period
        0xDB, 0x40, // VCOM deselect level
        0xA4,       // Entire display ON/OFF (A4 = normal, A5 = all ON)
        0xA6,       // Normal/Inverse display (A6 = normal, A7 = inverse)
        0xAF        // Display on
    };

    for (int i = 0; i < sizeof(init_commands); i++) {
        char buf[2] = {0x00, init_commands[i]};
        int result = i2cWriteDevice(i2c_handle, buf, 2);
        if (result != 0) {
            fprintf(stderr, "Error: I2C write failed during initialization (command %d): %d\n", i, result);
            return -1;
        }
        usleep(100); // Small delay after each command
    }

    return 0;
}

// Function to clear the OLED screen
int oled_clear(int i2c_handle) {
    char buf[OLED_WIDTH * OLED_HEIGHT / 8 + 1];
    buf[0] = 0x40; // Data command
    memset(buf + 1, 0x00, OLED_WIDTH * OLED_HEIGHT / 8);
    int result = i2cWriteDevice(i2c_handle, buf, OLED_WIDTH * OLED_HEIGHT / 8 + 1);
    if (result != 0) {
        fprintf(stderr, "Error: I2C write failed during clear: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to display text on the OLED screen
int oled_display_text(int i2c_handle, int x, int y, const char *text) {
    if (x < 0 || x >= OLED_WIDTH || y < 0 || y >= OLED_HEIGHT) {
        fprintf(stderr, "Error: Text position out of bounds.\n");
        return -1;
    }

    int char_width = 5; // Font width
    int char_height = 7; // Font height

    int start_page = y / 8;
    int start_line = y % 8;

    char page_buffer[OLED_WIDTH];
    memset(page_buffer, 0, OLED_WIDTH);

    for (int i = 0; text[i] != '\0'; i++) {
        unsigned char c = text[i];
        if (c < 32 || c > 126) {
            c = 0; // Use space for unknown characters
        }
        c -= 32; // Adjust index to font array

        for (int j = 0; j < char_width; j++) {
            unsigned char pixel_data = font[c][j];
            for (int k = 0; k < char_height; k++) {
                if ((pixel_data >> k) & 0x01) {
                    int pixel_x = x + i * char_width + j;
                    int pixel_y = y + k;
                    int pixel_page = pixel_y / 8;
                    int pixel_line = pixel_y % 8;

                    if (pixel_x >= 0 && pixel_x < OLED_WIDTH) {
                        page_buffer[pixel_x] |= (1 << pixel_line);
                    }
                }
            }
        }
    }

    // Send data to the OLED
    char data_buffer[OLED_WIDTH + 1];
    data_buffer[0] = 0x40; // Data command
    memcpy(data_buffer + 1, page_buffer, OLED_WIDTH);

    // Set column and page address
    char col_addr[2] = {0x21, (x + OLED_WIDTH - 1)}; // Column address
    char page_addr[2] = {0x22, (start_page + OLED_HEIGHT / 8 - 1)}; // Page address

    int result;
    result = i2cWriteDevice(i2c_handle, col_addr, 2);
    if (result != 0) {
        fprintf(stderr, "Error: I2C write failed during column address setting: %d\n", result);
        return -1;
    }
    result = i2cWriteDevice(i2c_handle, page_addr, 2);
    if (result != 0) {
        fprintf(stderr, "Error: I2C write failed during page address setting: %d\n", result);
        return -1;
    }

    result = i2cWriteDevice(i2c_handle, data_buffer, OLED_WIDTH + 1);
    if (result != 0) {
        fprintf(stderr, "Error: I2C write failed during text display: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to display temperature and usage on the OLED screen
int oled_display_temp_usage(int i2c_handle, float temperature, float usage) {
    char temp_str[20];
    char usage_str[20];

    if (temperature == -1.0) {
        snprintf(temp_str, sizeof(temp_str), "Temp: Error");
    } else {
        snprintf(temp_str, sizeof(temp_str), "Temp: %.1f C", temperature / 1000.0);
    }

    if (usage == -1.0) {
        snprintf(usage_str, sizeof(usage_str), "Usage: Error");
    } else {
        snprintf(usage_str, sizeof(usage_str), "Usage: %.1f %%", usage);
    }

    if (oled_display_text(i2c_handle, 0, 0, temp_str) != 0) {
        fprintf(stderr, "Error: Failed to display temperature.\n");
        return -1;
    }

    if (oled_display_text(i2c_handle, 0, 16, usage_str) != 0) {
        fprintf(stderr, "Error: Failed to display CPU usage.\n");
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, OLED_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize OLED screen
    if (oled_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: OLED initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature and usage
        int temp_raw = read_cpu_temp();
        float temperature = (temp_raw == -1) ? -1.0 : (float)temp_raw;
        float usage = read_cpu_usage();

        // Clear the screen
        if (oled_clear(i2c_handle) != 0) {
            fprintf(stderr, "Error: Failed to clear OLED screen.\n");
        }

        // Display temperature and usage
        if (oled_display_temp_usage(i2c_handle, temperature, usage) != 0) {
            fprintf(stderr, "Error: Failed to display temperature and usage.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

