#include <pigpio.h>
#include <unistd.h>
#include <string.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define PULSES_PER_LITER 450.0
#define FLOW_RATE_UPDATE_INTERVAL 1 // seconds
#define LCD_UPDATE_INTERVAL 10      // seconds

// Global variables
volatile int pulse_count = 0;
double total_volume = 0.0;
int i2c_handle;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user);
double calculate_flow_rate(int pulse_count);
void update_lcd(double flow_rate, double total_volume);
void signal_handler(int signal);

// Pulse callback function
void pulse_callback(int gpio, int level, uint32_t tick, void *user)
{
    if (level == PI_HIGH) // Rising edge
    {
        pulse_count++;
    }
}

// Calculate flow rate in liters per minute
double calculate_flow_rate(int pulse_count)
{
    return (double)pulse_count / PULSES_PER_LITER * 60.0;
}

// Update LCD screen
void update_lcd(double flow_rate, double total_volume)
{
    char buffer[32];

    // Format strings for LCD display
    snprintf(buffer, sizeof(buffer), "Flow: %.2f LPM", flow_rate);
    char volume_str[32];
    snprintf(volume_str, sizeof(volume_str), "Vol: %.2f L", total_volume);

    // Send commands to clear LCD and set cursor position
    char lcd_commands[] = {0x01, 0x80}; // Clear display and set cursor to home
    if (i2cWriteDevice(i2c_handle, lcd_commands, sizeof(lcd_commands)) < 0) {
        fprintf(stderr, "Error writing to LCD: %d\n", i2c_handle);
        return;
    }

    // Send commands to set cursor position to the first line
    char lcd_command_1[] = {0x80}; // Set cursor to the first line
    if (i2cWriteDevice(i2c_handle, lcd_command_1, sizeof(lcd_command_1)) < 0) {
        fprintf(stderr, "Error writing to LCD: %d\n", i2c_handle);
        return;
    }

    // Send data to LCD (first line)
    if (i2cWriteDevice(i2c_handle, buffer, strlen(buffer)) < 0) {
        fprintf(stderr, "Error writing to LCD: %d\n", i2c_handle);
        return;
    }

    // Send commands to set cursor position to the second line
    char lcd_command_2[] = {0xC0}; // Set cursor to the second line
    if (i2cWriteDevice(i2c_handle, lcd_command_2, sizeof(lcd_command_2)) < 0) {
        fprintf(stderr, "Error writing to LCD: %d\n", i2c_handle);
        return;
    }

    // Send data to LCD (second line)
    if (i2cWriteDevice(i2c_handle, volume_str, strlen(volume_str)) < 0) {
        fprintf(stderr, "Error writing to LCD: %d\n", i2c_handle);
        return;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set up interrupt on GPIO17
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_callback, NULL);

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "I2C initialisation failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_pulse_count = 0;
    double flow_rate;
    time_t last_lcd_update = 0;
    time_t last_flow_rate_update = 0;
    time_t current_time;

    // Main loop
    while (1)
    {
        time(&current_time);

        // Calculate flow rate every FLOW_RATE_UPDATE_INTERVAL seconds
        if (difftime(current_time, last_flow_rate_update) >= FLOW_RATE_UPDATE_INTERVAL)
        {
            flow_rate = calculate_flow_rate(pulse_count - last_pulse_count);
            last_pulse_count = pulse_count;
            total_volume += flow_rate / 60.0; // Accumulate volume in liters
            last_flow_rate_update = current_time;

            // Print flow rate and total volume to console
            printf("Flow Rate: %.2f LPM, Total Volume: %.2f L\n", flow_rate, total_volume);
        }

        // Update LCD every LCD_UPDATE_INTERVAL seconds
        if (difftime(current_time, last_lcd_update) >= LCD_UPDATE_INTERVAL)
        {
            update_lcd(flow_rate, total_volume);
            last_lcd_update = current_time;
        }

        gpioDelay(100); // Check every 100ms
    }

    return 0;
}

