#include <pigpio.h>

// Define GPIO pins
#define ANEMOMETER_PIN 17
#define LCD_I2C_ADDR 0x27
#define MCP3008_SPI_CHANNEL 0

// Define LCD commands
#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_CURSORSHIFT 0x10
#define LCD_FUNCTIONSET 0x20
#define LCD_SETCGRAMADDR 0x40
#define LCD_SETDDRAMADDR 0x80

// Define LCD flags
#define LCD_ENTRYRIGHT 0x00
#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTINCREMENT 0x01
#define LCD_ENTRYSHIFTDECREMENT 0x00

#define LCD_DISPLAYON 0x04
#define LCD_DISPLAYOFF 0x00
#define LCD_CURSORON 0x02
#define LCD_CURSOROFF 0x00
#define LCD_BLINKON 0x01
#define LCD_BLINKOFF 0x00

#define LCD_8BITMODE 0x10
#define LCD_4BITMODE 0x00
#define LCD_2LINE 0x08
#define LCD_1LINE 0x00
#define LCD_5x10DOTS 0x04
#define LCD_5x8DOTS 0x00

// Define LCD backlight control
#define LCD_BACKLIGHT 0x08
#define LCD_NOBACKLIGHT 0x00

#define ENABLE 0b00000100 // Enable bit

// Global variables
static volatile int pulse_count = 0;
static int i2c_handle;
static int spi_handle;
static int lcd_initialized = 0;

// Function prototypes
void anemometer_interrupt_handler(int gpio, int level, uint32_t tick, void *user);
float calculate_wind_speed(int pulse_count);
int read_wind_direction();
int lcd_init();
void lcd_byte(int bits, int mode);
void lcd_string(const char *s);
void lcd_clear();
void lcd_print(const char *s);
void signal_handler(int signal);

// Anemometer interrupt handler
void anemometer_interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    pulse_count++;
}

// Calculate wind speed from pulse count
float calculate_wind_speed(int pulse_count) {
    return (float)pulse_count * 0.5; // 0.5 m/s per pulse
}

// Read wind direction from MCP3008 ADC
int read_wind_direction() {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value;

    // MCP3008 configuration: single-ended, channel 0
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = 0x80; // Single-ended, channel 0 (10000000)
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// LCD initialization
int lcd_init() {
    // 4-bit initialization sequence
    gpioDelay(50000); // Wait 50ms
    lcd_byte(0x33, 0); // Initialize
    gpioDelay(50000); // Wait 50ms
    lcd_byte(0x32, 0); // Initialize
    gpioDelay(1000);  // Wait 1ms
    lcd_byte(0x28, 0); // 4-bit mode, 2 lines, 5x8 font
