#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define LCD_ADDR 0x27
#define PULSES_PER_LITER 7.5
#define FLOW_RATE_CALCULATION_INTERVAL_MS 1000
#define ZERO_PULSE_THRESHOLD_MS 5000
#define LCD_CHR 1 // Mode - Sending data
#define LCD_CMD 0 // Mode - Sending command

#define LCD_BACKLIGHT 0x08  // On
// LCD_BACKLIGHT = 0x00  # Off

#define E 0x04 // Enable bit
#define RS 0x01 // Register select bit

// Global variables
volatile int pulse_count = 0;
int lcd_fd;

// Function prototypes
void flow_sensor_callback(int gpio, int level, uint32_t tick, void *user);
float calculate_flow_rate(int pulses);
void lcd_init();
void lcd_byte(int bits, int mode);
void lcd_string(const char *s);
void lcd_clear();
void lcd_print_flow_rate(float flow_rate);
void signal_handler(int signal);

// Structure to hold LCD configuration (optional)
typedef struct {
    int fd;
} lcd_config_t;

lcd_config_t lcd_config;

// Callback function for flow sensor pulses
void flow_sensor_callback(int gpio, int level, uint32_t tick, void *user)
{
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Function to calculate flow rate in liters per minute
float calculate_flow_rate(int pulses)
{
    return (float)pulses / PULSES_PER_LITER * 60.0;
}

// LCD initialization function
void lcd_init()
{
    // Initialise display
    lcd_byte(0x33, LCD_CMD); // Initialise
    lcd_byte(0x32, LCD_CMD); // Initialise
    lcd_byte(0x06, LCD_CMD); // Cursor move direction
    lcd_byte(0x0C, LCD_CMD); // 0x0F = Display on,Enable cursor and blinker
    lcd_byte(0x28, LCD_CMD); // Data length, number of lines, font size
    lcd_byte(0x01, LCD_CMD); // Clear display
    gpioDelay(500);
}

// LCD byte function
void lcd_byte(int bits, int mode)
{
    // Send byte to data pins
    // bits = the data
    // mode = 1 for data, 0 for command
    int bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT ;
    int bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT ;

    // High bits
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_high);
    lcd_byte_internal(bits_high);

    // Low bits
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_low);
    lcd_byte_internal(bits_low);
}

void lcd_byte_internal(int bits)
{
    int retries = 3;
    while (retries > 0) {
        if (wiringPiI2CWriteReg8(lcd_fd, 0, bits | E) == 0) {
            gpioDelay(1);
            if (wiringPiI2CWriteReg8(lcd_fd, 0, bits & ~E) == 0) {
                gpioDelay(500);
                return;
            }
        }
        retries--;
        gpioDelay(1000); // Wait before retrying
    }
    fprintf(stderr, "Error: LCD I2C write failed after multiple retries.\n");
}

// LCD string function
void lcd_string(const char *s)
{
    while (*s) {
        lcd_byte(*s++, LCD_CHR);
    }
}

// LCD clear function
void lcd_clear()
{
    lcd_byte(0x01, LCD_CMD);
    gpioDelay(500);
}

// LCD print flow rate function
void lcd_print_flow_rate(float flow_rate)
{
    char buffer[17];

    lcd_clear();
    lcd_string("Flow Rate:");
    sprintf(buffer, "%.2f L/min", flow_rate);
    lcd_byte(0xC0, LCD_CMD); // Move cursor to the beginning of the second line
    lcd_string(buffer);
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    lcd_clear();
    lcd_string("Shutting down...");
    gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, NULL, NULL); // Disable callback
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Initialize wiringPi I2C
    lcd_fd = wiringPiI2CSetup(LCD_ADDR);
    if (lcd_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed\n");
        gpioTerminate();
        return 1;
    }

    lcd_config.fd = lcd_fd;

    // Initialize LCD
    lcd_init();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt on flow sensor GPIO
    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, flow_sensor_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    int zero_pulse_count = 0;
    while (1) {
        gpioDelay(FLOW_RATE_CALCULATION_INTERVAL_MS);

        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count for the next interval

        float flow_rate = calculate_flow_rate(current_pulse_count);

        if (current_pulse_count == 0) {
            zero_pulse_count += FLOW_RATE_CALCULATION_INTERVAL_MS;
            if (zero_pulse_count >= ZERO_PULSE_THRESHOLD_MS) {
                lcd_clear();
                lcd_string("Sensor Absent");
                gpioDelay(1000); // Wait 1 second before re-checking
                zero_pulse_count = 0; // Reset the counter
                continue; // Skip the rest of the loop and re-check
            }
        } else {
            zero_pulse_count = 0; // Reset the counter if we get a pulse
        }

        lcd_print_flow_rate(flow_rate);
    }

    return 0;
}

