// Define GPIO pins for rows and columns
const int row_pins[] = {17, 18, 27, 22, 23, 24, 25, 4};
const int col_pins[] = {5, 6, 12, 13, 19, 16, 26, 20};
const int num_rows = 8;
const int num_cols = 8;

// Wave direction enum
enum wave_direction {
    LEFT_TO_RIGHT,
    RIGHT_TO_LEFT
};

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set row pins as outputs and set initial state to LOW (anode)
    for (int i = 0; i < num_rows; i++) {
        gpioSetMode(row_pins[i], PI_OUTPUT);
        gpioWrite(row_pins[i], 0);
    }

    // Set column pins as outputs and set initial state to HIGH (cathode)
    for (int i = 0; i < num_cols; i++) {
        gpioSetMode(col_pins[i], PI_OUTPUT);
        gpioWrite(col_pins[i], 1);
    }

    return 0;
}

// Function to display a single row
void display_row(int row, int col_mask) {
    gpioWrite(row_pins[row], 1); // Set row HIGH
    for (int i = 0; i < num_cols; i++) {
        gpioWrite(col_pins[i], (col_mask >> i) & 1); // Set column LOW if bit is set
    }
    gpioDelay(800); // Delay for scan time
    gpioWrite(row_pins[row], 0); // Set row LOW
}

// Function to display the entire matrix
void display_matrix(int *rows) {
    for (int i = 0; i < num_rows; i++) {
        display_row(i, rows[i]);
    }
}

// Function to generate a wave pattern
void generate_wave(int *rows, enum wave_direction direction) {
    static int wave_index = 0;
    static bool direction_changed = false;

    // Clear the rows
    for (int i = 0; i < num_rows; i++) {
        rows[i] = 0;
    }

    // Shift the wave pattern
    if (direction == LEFT_TO_RIGHT) {
        for (int i = 0; i < num_rows; i++) {
            rows[i] = (1 << (wave_index + i)) & ((1 << num_cols) - 1);
        }
        wave_index++;
        if (wave_index >= num_cols - num_rows + 1) {
            wave_index = num_cols - num_rows;
            direction_changed = true;
        }
    } else {
        for (int i = 0; i < num_rows; i++) {
            rows[i] = (1 << (wave_index + i)) & ((1 << num_cols) - 1);
        }
        wave_index--;
        if (wave_index < 0) {
            wave_index = 0;
            direction_changed = true;
        }
    }

    if (direction_changed) {
        if (direction == LEFT_TO_RIGHT) {
            direction = RIGHT_TO_LEFT;
        } else {
            direction = LEFT_TO_RIGHT;
        }
        direction_changed = false;
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    int rows[num_rows];
    enum wave_direction current_direction = LEFT_TO_RIGHT;

    while (!terminate) {
        generate_wave(rows, current_direction);
        display_matrix(rows);
    }

    // Cleanup GPIO
    gpioTerminate();
    fprintf(stderr, "pigpio terminated\n");

    return 0;
}

