const int col_pins[] = {14, 15, 18, 23, 24, 25, 8, 7};
const int num_rows = 8;
const int num_cols = 8;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Set all GPIO pins to HIGH (common anode off)
    for (int i = 0; i < num_rows; i++) {
        gpioWrite(row_pins[i], 1);
    }
    for (int i = 0; i < num_cols; i++) {
        gpioWrite(col_pins[i], 1);
    }
    gpioTerminate();
    exit(0);
}

// Function to clear the LED matrix
void clear_matrix() {
    // Set all column cathodes HIGH (common anode off)
    for (int i = 0; i < num_cols; i++) {
        gpioWrite(col_pins[i], 1);
    }
    // Set all row anodes LOW (common anode off)
    for (int i = 0; i < num_rows; i++) {
        gpioWrite(row_pins[i], 0);
    }
}

// Function to light up a column
void light_column(int col) {
    clear_matrix();
    gpioWrite(col_pins[col], 0); // Set column cathode LOW
    for (int i = 0; i < num_rows; i++) {
        gpioWrite(row_pins[i], 1); // Set row anode HIGH
    }
    gpioDelay(150000); // 150ms delay
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

