    int result = i2cWriteI2CBlockData(handle, reg, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing byte to register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a 16-bit word from the VL53L3CX
int vl53l3cx_read_word(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading word from register 0x%04X: %d\n", reg, result);
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to write a 16-bit word to the VL53L3CX
int vl53l3cx_write_word(int handle, uint16_t reg, uint16_t value) {
