    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s, Distance1: %d mm, Distance2: %d mm, Distance3: %d mm\n", timestamp, data.distance1, data.distance2, data.distance3);
}

