        fprintf(stderr, "VL53L3CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read distance measurements
        if (vl53l3cx_read_distance(i2c_handle, &sensor_data) == 0) {
            // Log the data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading distance data\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

