int vl53l3cx_read_distance(int handle, sensor_data_t *data) {
    uint16_t range_status;
    uint16_t distance1, distance2, distance3;

    // Read range status
    if (vl53l3cx_read_word(handle, VL53L3CX_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read distance measurements
    if (vl53l3cx_read_word(handle, VL53L3CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance1) != 0) {
        fprintf(stderr, "Error reading distance 1\n");
        return -1;
    }
    if (vl53l3cx_read_word(handle, VL53L3CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 2, &distance2) != 0) {
        fprintf(stderr, "Error reading distance 2\n");
        return -1;
    }
    if (vl53l3cx_read_word(handle, VL53L3CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 4, &distance3) != 0) {
        fprintf(stderr, "Error reading distance 3\n");
        return -1;
    }

    data->distance1 = distance1;
    data->distance2 = distance2;
    data->distance3 = distance3;

    return 0;
}

// Function to log the sensor data with an ISO-8601 timestamp
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s, Distance1: %d mm, Distance2: %d mm, Distance3: %d mm\n", timestamp, data.distance1, data.distance2, data.distance3);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the VL53L3CX sensor
    if (vl53l3cx_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L3CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read distance measurements
        if (vl53l3cx_read_distance(i2c_handle, &sensor_data) == 0) {
            // Log the data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading distance data\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

