#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define MLX75031_ADDR 0x4C
#define DISTANCE_REG 0x0D
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int mlx75031_address;
    int sample_interval_ms;
    char *log_file_name;
} config_t;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_distance(int handle, uint16_t *distance);
int log_data(FILE *fp, uint16_t distance);
void signal_handler(int signal);
void cleanup(int handle, FILE *fp);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read distance from the sensor
int read_distance(int handle, uint16_t *distance) {
    char reg = DISTANCE_REG;
    char buffer[2];
    int result;

    result = i2cWriteDevice(handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    *distance = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to log data to a file
int log_data(FILE *fp, uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%u\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup function to close I2C and file
void cleanup(int handle, FILE *fp) {
    if (handle >= 0) {
        i2cClose(handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    config_t config = {
        .i2c_bus = I2C_BUS,
        .mlx75031_address = MLX75031_ADDR,
        .sample_interval_ms = SAMPLE_INTERVAL_MS,
        .log_file_name = "depth_log.csv"
    };

    uint16_t distance;
    int retries;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup(-1, NULL);
        return 1;
    }

    // Check if the file is newly created and add a header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
    }
    fseek(log_file, 0, SEEK_END);

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            // Initialize I2C
            i2c_handle = initialize_i2c(config.i2c_bus, config.mlx75031_address);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to initialize I2C, retry %d/%d\n", retries + 1, MAX_RETRIES);
                retries++;
                gpioDelay(100); // Wait before retrying
                continue;
            }

            // Read distance
            if (read_distance(i2c_handle, &distance) == 0) {
                // Log data
                if (log_data(log_file, distance) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Failed to read distance, retry %d/%d\n", retries + 1, MAX_RETRIES);
                retries++;
                i2cClose(i2c_handle);
                i2c_handle = -1; // Reset handle for next retry
                gpioDelay(100); // Wait before retrying
            }
        }

        if (retries == MAX_RETRIES) {
            // Log error if all retries failed
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s,-1\n", timestamp);
            fflush(log_file);
            fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(config.sample_interval_ms);
    }

    // Cleanup and exit
    cleanup(i2c_handle, log_file);
    return 0;
}

