// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_PART_ID 0x00
#define SI1145_COMMAND 0x18
#define SI1145_ALS_VIS_DATA0 0x22
#define SI1145_PS1_DATA0 0x24

// Command values
#define SI1145_RESET 0x01
#define SI1145_ALS_FORCE 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int read_proximity();
int read_ambient_light();
void log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize the Si1145 sensor
int si1145_init() {
    // Check PART ID
    int part_id = i2cReadByteData(i2c_handle, SI1145_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X\n", part_id);
        return -1;
    }

    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, SI1145_COMMAND, SI1145_RESET) < 0) {
        fprintf(stderr, "Error resetting sensor.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure measurement rates (example values)
    // These values are specific to the Si1145 and need to be adjusted based on the datasheet.
    // For example, writing 0x77 to register 0x02 sets the ALS rate to 100ms and PS rate to 100ms.
    // Writing 0x01 to register 0x03 enables ALS and PS.
    // Writing 0x00 to register 0x04 sets the PS LED drive current to 100mA.

    // Clear any stale IRQ (optional, depends on application)
    // i2cWriteByteData(i2c_handle, SI1145_COMMAND, 0x00); // Example: Clear interrupt

    return 0;
}

// Read proximity data from the sensor
int read_proximity() {
    int proximity = i2cReadWordData(i2c_handle, SI1145_PS1_DATA0);
    if (proximity < 0) {
        fprintf(stderr, "Error reading proximity data: %d\n", proximity);
        return -1;
    }
    return proximity;
}

// Read ambient light data from the sensor
int read_ambient_light() {
    int ambient_light = i2cReadWordData(i2c_handle, SI1145_ALS_VIS_DATA0);
    if (ambient_light < 0) {
        fprintf(stderr, "Error reading ambient light data: %d\n", ambient_light);
        return -1;
    }
    return ambient_light;
}

// Log data to file with ISO-8601 timestamp
void log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Proximity: %d, Ambient Light: %d\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (si1145_init() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int proximity = read_proximity();
        int ambient_light = read_ambient_light();

        if (proximity >= 0 && ambient_light >= 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
        }

        gpioDelay(500); // Sample every 500 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

