#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_PART_ID 0x00
#define SI1145_HW_KEY 0x07
#define SI1145_CH_LIST 0x4F
#define SI1145_MEAS_RATE0 0x08
#define SI1145_MEAS_RATE1 0x09
#define SI1145_COMMAND 0x30
#define SI1145_PS1_DATA0 0x18
#define SI1145_PS1_DATA1 0x19
#define SI1145_ALS_VIS_DATA0 0x22
#define SI1145_ALS_VIS_DATA1 0x23

// Command codes
#define SI1145_ALS_FORCE 0x06
#define SI1145_PS_FORCE 0x07

// Global variables
int i2c_handle;
FILE *log_file;

// Function prototypes
int si1145_init();
int read_proximity();
int read_ambient_light();
void log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int proximity;
    int ambient_light;
} sensor_data_t;

// Function to write a byte to a Si1145 register
int write_register(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a Si1145 register
int read_register(int handle, int reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to initialize the Si1145 sensor
int si1145_init() {
    // Check PART_ID
    int part_id = read_register(i2c_handle, SI1145_PART_ID);
    if (part_id < 0 || part_id != 0x45) {
        fprintf(stderr, "Error: Si1145 not found or incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    // Write HW_KEY
    if (write_register(i2c_handle, SI1145_HW_KEY, 0x17) != 0) {
        return -1;
    }

    // Set CH_LIST to enable PS1 and ALS_VIS
    if (write_register(i2c_handle, SI1145_CH_LIST, 0x77) != 0) {
        return -1;
    }

    // Configure measurement rates
    if (write_register(i2c_handle, SI1145_MEAS_RATE0, 0x08) != 0) {
        return -1;
    }
    if (write_register(i2c_handle, SI1145_MEAS_RATE1, 0x00) != 0) {
        return -1;
    }

    return 0;
}

// Function to read proximity data
int read_proximity() {
    int data0 = read_register(i2c_handle, SI1145_PS1_DATA0);
    int data1 = read_register(i2c_handle, SI1145_PS1_DATA1);

    if (data0 < 0 || data1 < 0) {
        return -1;
    }

    return (data1 << 8) | data0;
}

// Function to read ambient light data
int read_ambient_light() {
    int data0 = read_register(i2c_handle, SI1145_ALS_VIS_DATA0);
    int data1 = read_register(i2c_handle, SI1145_ALS_VIS_DATA1);

    if (data0 < 0 || data1 < 0) {
        return -1;
    }

    return (data1 << 8) | data0;
}

// Function to log data to a CSV file
void log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1145 sensor
    if (si1145_init() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Trigger measurement
        if (write_register(i2c_handle, SI1145_COMMAND, SI1145_ALS_FORCE) != 0) {
            fprintf(stderr, "Error triggering ALS measurement\n");
        }
        if (write_register(i2c_handle, SI1145_COMMAND, SI1145_PS_FORCE) != 0) {
            fprintf(stderr, "Error triggering PS measurement\n");
        }

        // Read sensor data
        int proximity = read_proximity();
        int ambient_light = read_ambient_light();

        // Log data
        if (proximity >= 0 && ambient_light >= 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    return 0;
}

