#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define TRIGGER_PULSE_DURATION 10 // microseconds
#define TIMEOUT_DURATION 30000    // milliseconds
#define MIN_DISTANCE 2.0         // cm
#define MAX_DISTANCE 400.0       // cm
#define REMINDER_THRESHOLD 15.0   // cm

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold edge times
typedef struct {
    struct timespec rising_edge;
    struct timespec falling_edge;
    int valid;
} EchoPulse;

static EchoPulse echo_pulse;

// Function prototypes
void signal_handler(int signal);
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_distance(struct timespec rising_edge, struct timespec falling_edge);
void log_message(const char *message);
void check_distance(double distance);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to generate a 10 microsecond trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin events
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    if (level == 1) {
        echo_pulse.rising_edge = ts;
        echo_pulse.valid = 0; // Reset valid flag on rising edge
    } else if (level == 0) {
        echo_pulse.falling_edge = ts;
        echo_pulse.valid = 1; // Set valid flag on falling edge
    }
}

// Function to calculate distance in centimeters
double calculate_distance(struct timespec rising_edge, struct timespec falling_edge) {
    double pulse_seconds = (falling_edge.tv_sec - rising_edge.tv_sec) + (falling_edge.tv_nsec - rising_edge.tv_nsec) / 1000000000.0;
    return (pulse_seconds * 34300) / 2.0;
}

// Function to log messages to a file with ISO-8601 timestamp
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", buf, message);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
    }
}

// Function to check distance and log a reminder if necessary
void check_distance(double distance) {
    if (distance < REMINDER_THRESHOLD) {
        log_message("Time to water the plant!");
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (running) {
        echo_pulse.valid = 0; // Reset valid flag before each measurement

        // Trigger the sensor
        trigger_pulse();

        // Wait for echo pulse or timeout
        int timeout_count = 0;
        while (!echo_pulse.valid && timeout_count < TIMEOUT_DURATION) {
            gpioDelay(1); // Check every millisecond
            timeout_count++;
        }

        // Process the echo pulse
        if (echo_pulse.valid) {
