#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATA 0x9C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity);
int log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the APDS9960 sensor
int initialize_sensor() {
    int result;

    // Check sensor ID
    result = i2cReadByteData(i2c_handle, APDS9960_ID);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor ID: %s\n", strerror(errno));
        return -1;
    }
    if (result != 0xAB) {
        fprintf(stderr, "Incorrect sensor ID: 0x%X\n", result);
        return -1;
    }

    // Configure sensor registers
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xDB) < 0) {
        fprintf(stderr, "Error writing to ATIME register: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xF6) < 0) {
        fprintf(stderr, "Error writing to WTIME register: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87) < 0) {
        fprintf(stderr, "Error writing to PPULSE register: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03) < 0) {
        fprintf(stderr, "Error writing to CONTROL register: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, APDS9960_CONFIG2, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONFIG2 register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity) {
    int result;

    // Read proximity data
    result = i2cReadByteData(i2c_handle, APDS9960_PDATA);
    if (result < 0) {
        fprintf(stderr, "Error reading proximity data: %s\n", strerror(errno));
        return -1;
    }
    *proximity = (uint8_t)result;

    // Read RGB data
    result = i2cReadWordData(i2c_handle, APDS9960_RDATAL);
    if (result < 0) {
        fprintf(stderr, "Error reading red data: %s\n", strerror(errno));
        return -1;
    }
    *red = (uint16_t)result;

    result = i2cReadWordData(i2c_handle, APDS9960_GDATAL);
    if (result < 0) {
        fprintf(stderr, "Error reading green data: %s\n", strerror(errno));
        return -1;
    }
    *green = (uint16_t)result;

    result = i2cReadWordData(i2c_handle, APDS9960_BDATAL);
    if (result < 0) {
        fprintf(stderr, "Error reading blue data: %s\n", strerror(errno));
        return -1;
    }
    *blue = (uint16_t)result;

    return 0;
}

// Function to log data to CSV file
int log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    int result;
    uint16_t red, green, blue;
    uint8_t proximity;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&red, &green, &blue, &proximity) == 0) {
            // Check proximity threshold
            if (proximity > 200) {
                // Log data
                log_data(red, green, blue, proximity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, re-initializing...\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            gpioInitialise();
            i2c_handle = i2cOpen(1, APDS9960_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %s\n", strerror(errno));
                terminate = 1; // Exit loop if re-initialization fails
                continue;       // Skip to next iteration
            }
            if (initialize_sensor() < 0) {
                fprintf(stderr, "Sensor re-initialization failed\n");
                terminate = 1; // Exit loop if re-initialization fails
                continue;       // Skip to next iteration
            }
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

