// Si1182-A-GMR I2C address
#define SI1182_ADDR 0x5A

// Si1182 Part ID register
#define PART_ID_REG 0x00
#define PART_ID_VALUE 0x82

// MEAS_RATE0 register
#define MEAS_RATE0_REG 0x08
#define MEAS_RATE0_VALUE 0x0A // Example value, adjust as needed

// COMMAND register
#define COMMAND_REG 0x47
#define COMMAND_RESET_START 0x01

// Proximity data registers
#define PS_DATA0_REG 0x24
#define PS_DATA1_REG 0x25

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t running = 1;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int si1182_init(int fd);
int read_proximity_data(int fd, uint16_t *proximity);
