// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Si1182 initialization function
int si1182_init(int fd) {
    uint8_t part_id;

    // Verify Part ID
    if (i2c_read_reg(fd, PART_ID_REG, &part_id) < 0) {
        fprintf(stderr, "Error reading Part ID\n");
        return -1;
    }

    if (part_id != PART_ID_VALUE) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X (expected 0x%02X)\n", part_id, PART_ID_VALUE);
        return -1;
    }

    // Configure measurement rate
    if (i2c_write_reg(fd, MEAS_RATE0_REG, MEAS_RATE0_VALUE) < 0) {
        fprintf(stderr, "Error writing MEAS_RATE0\n");
        return -1;
    }

    // Reset and start measurement
    if (i2c_write_reg(fd, COMMAND_REG, COMMAND_RESET_START) < 0) {
        fprintf(stderr, "Error writing COMMAND_RESET_START\n");
        return -1;
    }

    return 0;
}

// Read proximity data function
int read_proximity_data(int fd, uint16_t *proximity) {
    uint8_t data0, data1;

    if (i2c_read_reg(fd, PS_DATA0_REG, &data0) < 0) {
        fprintf(stderr, "Error reading PS_DATA0\n");
        return -1;
    }

    if (i2c_read_reg(fd, PS_DATA1_REG, &data1) < 0) {
        fprintf(stderr, "Error reading PS_DATA1\n");
        return -1;
    }

    *proximity = (uint16_t)data0 | ((uint16_t)data1 << 8);
    return 0;
}

// BPM calculation placeholder
float calculate_bpm(uint16_t proximity) {
    // This is a placeholder.  A real implementation would
    // analyze the proximity data to detect peaks and calculate
    // a reasonable BPM.
    return (float)proximity / 100.0; // Example calculation
}

// Log data to CSV file
