    if (i2cWriteByteData(i2c_handle, 0xFF, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x00, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x91, 0x00) < 0) return -1;
