// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize the sensor
int initialize_sensor() {
    // Example initialization sequence (replace with actual ICU-20201 init)
    // This is a placeholder, refer to the ICU-20201 datasheet for the correct sequence
    char init_data[] = {0x00, 0x01}; // Example: Write 0x01 to register 0x00
    int result = i2cWriteDevice(i2c_handle, init_data, sizeof(init_data));
    if (result != 0) {
        fprintf(stderr, "Error initializing sensor: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    init_data[0] = 0x01;
    init_data[1] = 0x02;
    result = i2cWriteDevice(i2c_handle, init_data, sizeof(init_data));
    if (result != 0) {
        fprintf(stderr, "Error initializing sensor: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    return 0;
}

// Read distance from the sensor
int read_distance(float *distance) {
    // Example: Read two bytes from register 0x02 (replace with actual register)
    char reg = 0x02; // Register to read from
    char buffer[2];
    int result = i2cWriteDevice(i2c_handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert the two bytes to a distance value (example conversion)
    *distance = (float)((buffer[0] << 8) | buffer[1]) / 10.0; // Example: cm

    return 0;
}

