    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        terminate = 1;
    }
}

// Function to read proximity data
int read_proximity() {
    int proximity = -1; // Initialize to an error value
    int retries = 0;

    while (retries < RETRY_COUNT) {
        proximity = i2cReadWordData(i2c_handle, PROXIMITY_REGISTER);
        if (proximity >= 0) {
            return proximity;
        } else {
            fprintf(stderr, "Error reading proximity data (attempt %d): %d\n", retries + 1, proximity);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read proximity data after %d retries.\n", RETRY_COUNT);
    return -1; // Return error value if all retries fail
}

// Function to read ambient light data
int read_ambient_light() {
    int ambient_light = -1; // Initialize to an error value
    int retries = 0;

    while (retries < RETRY_COUNT) {
        ambient_light = i2cReadWordData(i2c_handle, AMBIENT_LIGHT_REGISTER);
        if (ambient_light >= 0) {
            return ambient_light;
        } else {
            fprintf(stderr, "Error reading ambient light data (attempt %d): %d\n", retries + 1, ambient_light);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read ambient light data after %d retries.\n", RETRY_COUNT);
    return -1; // Return error value if all retries fail
}

// Function to log data to file
void log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Proximity: %d, Ambient Light: %d\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int proximity = read_proximity();
        int ambient_light = read_ambient_light();

        if (proximity >= 0 && ambient_light >= 0) {
