            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read proximity data after %d retries.\n", RETRY_COUNT);
    return -1; // Return error value if all retries fail
}

// Function to read ambient light data
int read_ambient_light() {
    int ambient_light = -1; // Initialize to an error value
    int retries = 0;

    while (retries < RETRY_COUNT) {
        ambient_light = i2cReadWordData(i2c_handle, AMBIENT_LIGHT_REGISTER);
        if (ambient_light >= 0) {
            return ambient_light;
        } else {
            fprintf(stderr, "Error reading ambient light data (attempt %d): %d\n", retries + 1, ambient_light);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read ambient light data after %d retries.\n", RETRY_COUNT);
    return -1; // Return error value if all retries fail
}

