    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Proximity: %d, Ambient Light: %d\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to file immediately
}

