        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        }

        gpioDelay(500000); // 500ms delay
    }

    // Clean up resources before exiting
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

