// Define sensor and LED parameters
#define I2C_BUS 1
#define I2C_ADDRESS 0x6A
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0x41
#define DISTANCE_REG_HIGH 0x00
#define DISTANCE_REG_LOW 0x01
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100 // mm

// Global variables
int i2c_handle;
int threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
void control_led(int distance);
void log_data(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C connection and verifies the WHO_AM_I register
int initialize_sensor() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        i2cClose(i2c_handle);
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: 0x%02X != 0x%02X\n", who_am_i, WHO_AM_I_VALUE);
        i2cClose(i2c_handle);
        return -1;
    }

    printf("Sensor initialized successfully. WHO_AM_I: 0x%02X\n", who_am_i);
    return 0;
}

// Reads the distance measurement from the sensor
int read_distance(int *distance) {
    char buffer[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG_HIGH, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", bytes_read);
        return -1;
    }

    *distance = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Controls the LED based on the distance measurement
void control_led(int distance) {
    if (distance < threshold) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Logs the distance measurement with a timestamp to a file
void log_data(int distance) {
    FILE *fp = fopen("tof_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Distance: %d mm\n", s, distance);
    fclose(fp);
}

