#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define the I2C bus and sensor address
#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x50

// Define the command frame for requesting a distance measurement
const uint8_t command_frame[] = {0x50, 0x0A, 0x00, 0x01};
const size_t command_frame_size = sizeof(command_frame);

// Define the response frame size
const size_t response_frame_size = 15;

// Define the intrusion threshold in millimeters
const int intrusion_threshold = 1000;

// Global variables for I2C file descriptor and log file pointer
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_open(const char *bus);
int i2c_set_slave_address(int fd, int address);
int i2c_write(int fd, const uint8_t *data, size_t size);
int i2c_read(int fd, uint8_t *data, size_t size);
int request_distance_measurement(int fd);
int read_response_frame(int fd, uint8_t *response_frame);
int validate_response_frame(const uint8_t *response_frame);
int16_t extract_distance(const uint8_t *response_frame);
float calculate_average_distance(int16_t distances[], int num_samples);
void log_intrusion(float average_distance);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        exit(0);
    }
}

// Opens the I2C bus
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Sets the I2C slave address
int i2c_set_slave_address(int fd, int address) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    return 0;
}

// Writes data to the I2C bus
int i2c_write(int fd, const uint8_t *data, size_t size) {
    ssize_t bytes_written = write(fd, data, size);
    if (bytes_written < 0) {
        perror("Error writing to I2C bus");
        return -1;
    }
    if (bytes_written != (ssize_t)size) {
        fprintf(stderr, "Warning: Incomplete write to I2C bus. Wrote %zd bytes, expected %zu.\n", bytes_written, size);
    }
    return 0;
}

// Reads data from the I2C bus
int i2c_read(int fd, uint8_t *data, size_t size) {
    ssize_t bytes_read = read(fd, data, size);
    if (bytes_read < 0) {
        perror("Error reading from I2C bus");
        return -1;
    }
    if (bytes_read != (ssize_t)size) {
        fprintf(stderr, "Warning: Incomplete read from I2C bus. Read %zd bytes, expected %zu.\n", bytes_read, size);
    }
    return 0;
}

// Sends the command frame to the sensor to request a distance measurement
int request_distance_measurement(int fd) {
    return i2c_write(fd, command_frame, command_frame_size);
}

// Reads the response frame from the sensor
int read_response_frame(int fd, uint8_t *response_frame) {
    return i2c_read(fd, response_frame, response_frame_size);
}

// Validates the response frame by checking the header byte
int validate_response_frame(const uint8_t *response_frame) {
    if (response_frame[0] != 0x50) {
        fprintf(stderr, "Error: Invalid header byte in response frame: 0x%02X\n", response_frame[0]);
        return -1;
    }
    return 0;
}

// Extracts the distance from the response frame
int16_t extract_distance(const uint8_t *response_frame) {
    return (int16_t)((response_frame[11] << 8) | response_frame[12]);
}

// Calculates the average distance from the array of distances
float calculate_average_distance(int16_t distances[], int num_samples) {
    if (num_samples == 0) {
        return 0.0;
    }
    long sum = 0;
    for (int i = 0; i < num_samples; i++) {
        sum += distances[i];
    }
    return (float)sum / num_samples;
}

// Logs an intrusion event to the log file
void log_intrusion(float average_distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Intrusion detected! Average distance: %.2f mm\n", timestamp, average_distance);
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set the I2C slave address
    if (i2c_set_slave_address(i2c_fd, SENSOR_ADDRESS) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open the log file
    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    const int num_samples = 10;
    int distances[num_samples];

    // Main loop
    while (1) {
        // Sample the sensor 10 times
        for (int i = 0; i < num_samples; i++) {
            // Request a distance measurement
            if (request_distance_measurement(i2c_fd) < 0) {
                fprintf(stderr, "Error requesting distance measurement. Retrying...\n");
                usleep(10000); // Wait 10ms before retrying
                i--; // Retry the current sample
                continue;
            }

            usleep(10000); // Wait 10ms for the measurement

            uint8_t response_frame[response_frame_size];

            // Read the response frame
            if (read_response_frame(i2c_fd, response_frame) < 0) {
                fprintf(stderr, "Error reading response frame. Retrying...\n");
                usleep(10000); // Wait 10ms before retrying
                i--; // Retry the current sample
                continue;
            }

            // Validate the response frame
            if (validate_response_frame(response_frame) < 0) {
                fprintf(stderr, "Error validating response frame. Retrying...\n");
                usleep(10000); // Wait 10ms before retrying
                i--; // Retry the current sample
                continue;
            }

            // Extract the distance
            distances[i] = extract_distance(response_frame);
        }

        // Calculate the average distance
        float average_distance = calculate_average_distance(distances, num_samples);

        // Check for intrusion
        if (average_distance < intrusion_threshold) {
            log_intrusion(average_distance);
        }

        // Wait 100ms before the next sampling cycle
        usleep(100000);
    }

    // The program should never reach here due to the infinite loop, but include cleanup for completeness
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

