#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0xC0
#define VL53L0X_REG_SYSRANGE_START 0x00
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize the VL53L0X sensor
int init_vl53l0x() {
    int model_id;

    // Check sensor ID
    model_id = i2cReadByteData(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }

    if (model_id != 0xEE) {
        fprintf(stderr, "Error: Incorrect model ID: 0x%02X (expected 0xEE)\n", model_id);
        return -1;
    }

    return 0;
}

// Function to read distance from the VL53L0X sensor
int read_distance() {
    int distance = -1; // Initialize to an error value
    int status;
    int timeout_count = 0;

    // Start a single-shot measurement
    if (i2cWriteByteData(i2c_handle, VL53L0X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error writing to SYSRANGE_START: %s\n", strerror(errno));
        return -1;
    }

    // Wait for the measurement to complete (with timeout)
    while (1) {
        status = i2cReadByteData(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading interrupt status: %s\n", strerror(errno));
            return -1;
        }

        if (status & 0x01) {
            break; // Measurement complete
        }

        gpioDelay(1000); // 1 ms delay
        timeout_count++;
        if (timeout_count > 100) { // 100 * 1ms = 100ms timeout
            fprintf(stderr, "Timeout waiting for measurement\n");
            return -1;
        }
    }

    // Read the distance
    distance = i2cReadWordData(i2c_handle, VL53L0X_REG_RESULT_RANGE_STATUS);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }

    // Clear the interrupt
    if (i2cWriteByteData(i2c_handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error writing to SYSTEM_INTERRUPT_CLEAR: %s\n", strerror(errno));
        return -1;
    }

    return distance;
}

