// Si1182 I2C address
#define SI1182_ADDR 0x39

// Si1182 register addresses
#define SI1182_CONFIG 0x18
#define SI1182_IRQ_STATUS 0x25
#define SI1182_PROX_LSB 0x2A
#define SI1182_PROX_MSB 0x2B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to initialize the Si1182 sensor
int init_si1182()
{
    int status;

    // Enable proximity mode
    status = i2cWriteByteData(i2c_handle, SI1182_CONFIG, 0x01);
    if (status != 0) {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read proximity data from the Si1182 sensor
int read_proximity(uint16_t *proximity)
{
    int status;
    uint8_t lsb, msb;

    // Check if data is ready
    status = i2cReadByteData(i2c_handle, SI1182_IRQ_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error reading IRQ status register: %d\n", status);
        return -1;
    }

    if ((status & 0x01) == 0) {
        // Data not ready
        return -2;
    }

    // Read proximity data
    status = i2cReadByteData(i2c_handle, SI1182_PROX_LSB);
    if (status < 0) {
        fprintf(stderr, "Error reading proximity LSB: %d\n", status);
        return -1;
    }
    lsb = (uint8_t)status;

    status = i2cReadByteData(i2c_handle, SI1182_PROX_MSB);
    if (status < 0) {
        fprintf(stderr, "Error reading proximity MSB: %d\n", status);
        return -1;
    }
    msb = (uint8_t)status;

    *proximity = ((uint16_t)msb << 8) | lsb;

    return 0;
}

int main()
{
    int status;
    uint16_t proximity;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_si1182() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        status = read_proximity(&proximity);
        if (status == 0) {
            printf("Proximity: %u\n", proximity);
        } else if (status == -2) {
            // Data not ready, just continue
        } else {
            fprintf(stderr, "Error reading proximity data\n");
        }

        gpioDelay(500); // 500 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

