#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4C
#define DISTANCE_REG 0x00
#define DISTANCE_SCALE 0.125

static volatile int keep_running = 1;
static int i2c_fd = -1;

void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    struct timespec sleep_time = {0, 500000000}; // 500 milliseconds
    int retries = 3;
    int distance_raw;
    float distance_mm;

    // Install signal handlers
    if (signal(SIGINT, sigint_handler) == SIG_ERR || signal(SIGTERM, sigint_handler) == SIG_ERR) {
        perror("Failed to install signal handler");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify device presence
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("Failed to re-set I2C slave address after verification");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read distance register
        distance_raw = -1; // Initialize to an invalid value
        for (int i = 0; i < retries; ++i) {
            distance_raw = i2c_smbus_read_word_data(i2c_fd, DISTANCE_REG);
            if (distance_raw >= 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "I2C read failed (attempt %d): %s\n", i + 1, strerror(errno));
                nanosleep(&sleep_time, NULL); // Wait before retrying
            }
        }

        if (distance_raw < 0) {
            fprintf(stderr, "Failed to read distance after multiple retries.\n");
            continue; // Skip to the next iteration
        }

        // Convert to millimeters
        distance_mm = (float)distance_raw * DISTANCE_SCALE;

        // Print distance
        printf("Distance: %.2f mm\n", distance_mm);

        // Sleep for 500ms
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C bus
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    return 0;
}

