#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define TRIGGER_PULSE_DURATION 10 // microseconds
#define MAX_PULSE_DURATION 38000 // microseconds (38 ms)
#define TIMEOUT_DURATION 200000 // microseconds (200 ms)

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void triggerSensor();
long measurePulseWidth();
double calculateDistance(long pulse_width);
void logDistance(double distance);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to send a trigger pulse
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measurePulseWidth() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high, with a timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_DURATION) {
        count++;
        gpioDelay(1); // Check every microsecond
    }

    if (count >= TIMEOUT_DURATION) {
        fprintf(stderr, "Error: Echo rising edge timeout\n");
        return -1; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low, with a timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_DURATION) {
        count++;
        gpioDelay(1); // Check every microsecond
    }

    if (count >= TIMEOUT_DURATION) {
        fprintf(stderr, "Error: Echo falling edge timeout\n");
        return -1; // Indicate timeout error
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;

    // Validate pulse width
    if (pulse_width <= 0 || pulse_width > MAX_PULSE_DURATION) {
        fprintf(stderr, "Error: Invalid pulse width: %ld us\n", pulse_width);
        return -1; // Indicate invalid pulse width
    }

    return pulse_width;
}

// Function to calculate distance in centimeters
double calculateDistance(long pulse_width) {
    return (pulse_width * 0.0343) / 2.0;
}

// Function to log the distance with a timestamp
void logDistance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulse_width = measurePulseWidth();

        if (pulse_width > 0) {
            double distance = calculateDistance(pulse_width);
            logDistance(distance);
        } else {
            fprintf(stderr, "Error: Failed to measure distance\n");
        }

        gpioDelay(1000000); // Wait for 1 second
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

