#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 1.0 // meters
#define LED_ON_TIME 2 // seconds
#define RANGE_RESOLUTION 0.0486 // meters per bin
#define NUM_RANGE_BINS 64
#define MAGIC_WORD_SIZE 8
#define RANGE_PROFILE_SIZE (NUM_RANGE_BINS * 2) // 16-bit integers
#define FRAME_SIZE (MAGIC_WORD_SIZE + RANGE_PROFILE_SIZE)

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_uart(const char *device, speed_t baud_rate);
int read_range_profile(int fd, short *range_profile);
float detect_intrusion(const short *range_profile, float distance_threshold);
void trigger_alert(int gpio_pin, int on_time);
void log_intrusion(float distance);
void signal_handler(int signal);
void cleanup();

// Function to initialize the UART
int initialize_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read doesn't block
    tty.c_cc[VTIME] = 5;                             // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read the range profile from the UART
int read_range_profile(int fd, short *range_profile) {
    unsigned char buffer[FRAME_SIZE];
    ssize_t bytes_read = read(fd, buffer, FRAME_SIZE);

    if (bytes_read != FRAME_SIZE) {
        fprintf(stderr, "Error reading frame: %zd bytes read (expected %d), errno: %d\n", bytes_read, FRAME_SIZE, errno);
        return -1;
    }

    // Verify magic word
    unsigned char magic_word[MAGIC_WORD_SIZE] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    if (memcmp(buffer, magic_word, MAGIC_WORD_SIZE) != 0) {
        fprintf(stderr, "Invalid magic word\n");
        return -1;
    }

    // Convert little-endian data to short integers
    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        range_profile[i] = (short)((buffer[MAGIC_WORD_SIZE + 2 * i + 1] << 8) | buffer[MAGIC_WORD_SIZE + 2 * i]);
    }

    return 0;
}

// Function to detect intrusion
float detect_intrusion(const short *range_profile, float distance_threshold) {
    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        if (range_profile[i] > 0) { // Assuming a threshold for valid data
            float distance = i * RANGE_RESOLUTION;
            if (distance <= distance_threshold) {
                return distance;
            }
        }
    }
    return -1.0; // No intrusion detected
}

// Function to trigger the alert (LED control)
void trigger_alert(int gpio_pin, int on_time) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(on_time * 1000000); // Delay for on_time seconds
    gpioWrite(gpio_pin, 0); // Turn LED off
}

// Function to log the intrusion
void log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = initialize_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        fprintf(stderr, "UART initialization failed. Exiting.\n");
        return 1;
    }
    printf("UART initialized successfully.\n");

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed. Exiting.\n");
        close(uart_fd);
        return 1;
    }
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    printf("pigpio initialized successfully.\n");

    // Open log file
    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }
    printf("Log file opened successfully.\n");

    short range_profile[NUM_RANGE_BINS];

    // Main loop
    while (program_running) {
        if (read_range_profile(uart_fd, range_profile) == 0) {
            float distance = detect_intrusion(range_profile, DISTANCE_THRESHOLD);
            if (distance > 0) {
                printf("Intrusion detected! Distance: %.4f meters\n", distance);
                trigger_alert(GPIO_LED, LED_ON_TIME);
                log_intrusion(distance);
            }
        } else {
            fprintf(stderr, "Failed to read range profile. Retrying...\n");
            // Optionally add a small delay here to avoid busy-waiting
            gpioDelay(100000); // 0.1 seconds
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

