        close(uart_fd);
        return 1;
    }
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    printf("pigpio initialized successfully.\n");

    // Open log file
    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }
    printf("Log file opened successfully.\n");

    short range_profile[NUM_RANGE_BINS];

    // Main loop
    while (program_running) {
        if (read_range_profile(uart_fd, range_profile) == 0) {
            float distance = detect_intrusion(range_profile, DISTANCE_THRESHOLD);
            if (distance > 0) {
                printf("Intrusion detected! Distance: %.4f meters\n", distance);
                trigger_alert(GPIO_LED, LED_ON_TIME);
                log_intrusion(distance);
            }
        } else {
            fprintf(stderr, "Failed to read range profile. Retrying...\n");
            // Optionally add a small delay here to avoid busy-waiting
            gpioDelay(100000); // 0.1 seconds
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

