#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x69
#define DISTANCE_HIGH_REG 0x31
#define DISTANCE_LOW_REG 0x32
#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_distance(int i2c_handle);
char* get_iso8601_timestamp();
int log_distance(FILE *log_file, char *timestamp, int distance);
void trigger_alert(int gpio_pin, int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read distance from the sensor
int read_distance(int i2c_handle) {
    char buffer[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_HIGH_REG, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit value
    int distance = (buffer[0] << 8) | buffer[1];
    return distance;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the distance to a file
int log_distance(FILE *log_file, char *timestamp, int distance) {
    if (fprintf(log_file, "%s, %d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1; // Indicate error
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to trigger an alert if the distance is below the threshold
void trigger_alert(int gpio_pin, int distance) {
    if (distance < DISTANCE_THRESHOLD * 10) { // Convert cm to mm
        gpioWrite(gpio_pin, 1); // Set GPIO HIGH
        gpioDelay(1000);        // Wait for 1 second
        gpioWrite(gpio_pin, 0); // Set GPIO LOW
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting distance measurement...\n");

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            char *timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                if (log_distance(log_file, timestamp, distance) == 0) {
                    trigger_alert(GPIO_PIN, distance);
                }
                free(timestamp); // Free the allocated memory
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Delay for 100 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

