// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_SYSRANGE_START 0x000
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x013
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x078
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x014

// VL53L1X model ID
#define VL53L1X_MODEL_ID 0xEA

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int init_sensor();
int read_distance();
void log_distance(int distance);
void print_guidance(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize the VL53L1X sensor
int init_sensor() {
    // Check sensor ID
    int model_id = i2cReadWordData(i2c_handle, VL53L1X_REG_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Incorrect model ID: 0x%02X (expected 0x%02X)\n", model_id, VL53L1X_MODEL_ID);
        return -1;
    }

    // Software reset
    if (i2cWriteWordData(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x00) < 0) {
        fprintf(stderr, "Error writing to SYSTEM__START register\n");
        return -1;
    }
    gpioDelay(2000); // Wait 2 ms

    // Start continuous ranging
    if (i2cWriteWordData(i2c_handle, 0x007, 0x01) < 0) {
        fprintf(stderr, "Error writing to SYSTEM__MODE_START register\n");
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance() {
    int data_ready = 0;
    int distance = -1;
    int timeout_count = 0;

    // Wait for data ready
    while (!data_ready && timeout_count < 100) {
        data_ready = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS) & 0x01;
        if (!data_ready) {
            gpioDelay(1000); // Wait 1 ms
            timeout_count++;
        }
    }

    if (!data_ready) {
        fprintf(stderr, "Timeout waiting for data ready\n");
        return -1;
    }

    // Read distance
    distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS + 10);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    // Clear interrupt
    if (i2cWriteWordData(i2c_handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error clearing interrupt\n");
        return -1;
    }

    return distance;
}

// Log distance to file
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Print parking guidance message
void print_guidance(int distance) {
    if (distance < 300) {
        printf("STOP\n");
    } else if (distance >= 300 && distance < 600) {
        printf("APPROACH\n");
    } else if (distance >= 600 && distance < 1200) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
