#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define CH201_ADDR 0x45
#define LED_GPIO 18
#define MIN_DISTANCE 50.0  // mm
#define MAX_DISTANCE 500.0 // mm
#define MIN_FREQUENCY 10.0  // Hz
#define MAX_FREQUENCY 1.0   // Hz
#define SAMPLE_INTERVAL 100 // ms

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(float *distance);
float map_distance_to_frequency(float distance);
void set_led_frequency(float frequency);
void log_data(float distance, float frequency);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int ch201_address;
    int led_gpio;
    float min_distance;
    float max_distance;
    float min_frequency;
    float max_frequency;
    int sample_interval;
} config_t;

config_t config = {
    .i2c_bus = I2C_BUS,
    .ch201_address = CH201_ADDR,
    .led_gpio = LED_GPIO,
    .min_distance = MIN_DISTANCE,
    .max_distance = MAX_DISTANCE,
    .min_frequency = MIN_FREQUENCY,
    .max_frequency = MAX_FREQUENCY,
    .sample_interval = SAMPLE_INTERVAL
};

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.ch201_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the CH201 sensor
int read_distance(float *distance) {
    char buf[2];
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Combine the two bytes to form the distance value
            uint16_t raw_distance = (buf[0] << 8) | buf[1];
            *distance = (float)raw_distance; // Distance in mm
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %d, retries remaining: %d\n", result, retries);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Failure
}

// Map distance to blink frequency
float map_distance_to_frequency(float distance) {
    float frequency;

    if (distance <= config.min_distance) {
        frequency = config.min_frequency;
    } else if (distance >= config.max_distance) {
        frequency = config.max_frequency;
    } else {
        frequency = config.min_frequency - (distance - config.min_distance) * (config.min_frequency - config.max_frequency) / (config.max_distance - config.min_distance);
    }

    return frequency;
}

// Set LED blink frequency using PWM
void set_led_frequency(float frequency) {
    int range = 1000; // PWM range
    int duty_cycle = (int)(range * (1.0 - (frequency / config.min_frequency))); // Invert for higher frequency = lower duty cycle

    gpioPWM(config.led_gpio, duty_cycle);
}

// Log data to stdout
void log_data(float distance, float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Distance: %.2f mm, Blink Frequency: %.2f Hz\n", timestamp, distance, frequency);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(config.led_gpio, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);

    float distance, frequency;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            frequency = map_distance_to_frequency(distance);
            set_led_frequency(frequency);
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(config.sample_interval * 1000); // Delay for sample interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

