#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define MEASURE_CMD 0x00 // Example command, check datasheet
#define MEASURE_CMD_LEN 1
#define DISTANCE_LEN 2
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int sample_interval_ms;
    char *log_file_name;
} config_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_distance(uint16_t *distance);
int log_data(uint16_t distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger a measurement on the MLX75030
int trigger_measurement() {
    int result = i2cWriteByteData(i2c_handle, MEASURE_CMD, 0); // Assuming no data to write
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(1000); // Delay for measurement (1ms)
    return 0;
}

// Read distance data from the MLX75030
int read_distance(uint16_t *distance) {
    char buffer[DISTANCE_LEN];
    int result = i2cReadI2CBlockData(i2c_handle, 0, buffer, DISTANCE_LEN);
    if (result != DISTANCE_LEN) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    // Convert the 2 bytes to a 16-bit unsigned integer (assuming little-endian)
    *distance = (uint16_t)((buffer[1] << 8) | buffer[0]);
    return 0;
}

// Log data to a CSV file
int log_data(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

