    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    uint16_t distance;
    int retries;

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (trigger_measurement() == 0) {
                if (read_distance(&distance) == 0) {
                    log_data(distance);
                    break; // Exit retry loop on success
                } else {
                    fprintf(stderr, "Retrying distance read... (%d/%d)\n", retries + 1, MAX_RETRIES);
                }
            } else {
                fprintf(stderr, "Retrying measurement trigger... (%d/%d)\n", retries + 1, MAX_RETRIES);
            }
            retries++;
            gpioDelay(10000); // Wait before retrying (10ms)
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for the sample interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

