#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define sensor and I2C parameters
#define I2C_BUS "/dev/i2c-1"
#define CH101_ADDR 0x49
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09
#define TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 500

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_write_register(int fd, unsigned char reg, unsigned char value);
int i2c_read_register(int fd, unsigned char reg, unsigned char *value);
int i2c_read_register_block(int fd, unsigned char reg, unsigned char *buf, int len);
int trigger_measurement(int fd);
int wait_for_data(int fd);
int read_distance(int fd, int *distance);
char* get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size);
int log_data(FILE *fp, const char *timestamp, int distance);
void signal_handler(int signum);

// I2C write function
int i2c_write_register(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_register(int fd, unsigned char reg, unsigned char *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_register_block(int fd, unsigned char reg, unsigned char *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for block read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading block from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Trigger a single range measurement
int trigger_measurement(int fd) {
    return i2c_write_register(fd, MEAS_TRIGGER, 0x01);
}

// Wait for data to be ready with timeout
int wait_for_data(int fd) {
    unsigned char status;
    struct timespec start, current;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        if (i2c_read_register(fd, MEAS_STATUS, &status) != 0) {
            return -1;
        }

        if (status & 0x01) {
            return 0; // Data ready
        }

        clock_gettime(CLOCK_MONOTONIC, &current);
        long elapsed_ms = (current.tv_sec - start.tv_sec) * 1000 + (current.tv_nsec - start.tv_nsec) / 1000000;
        if (elapsed_ms >= TIMEOUT_MS) {
            fprintf(stderr, "Timeout waiting for data\n");
            return -1; // Timeout
        }
        usleep(1000); // Check every 1 ms
    }
}

// Read the distance from the sensor
int read_distance(int fd, int *distance) {
    unsigned char high, low;
    if (i2c_read_register(fd, DIST_HIGH, &high) != 0) return -1;
    if (i2c_read_register(fd, DIST_LOW, &low) != 0) return -1;
    *distance = (high << 8) | low;
    return 0;
}

// Get current timestamp in ISO-8601 format
char* get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp_str;
}

// Log data to CSV file
int log_data(FILE *fp, const char *timestamp, int distance) {
    if (fprintf(fp, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    program_running = 0;
    fprintf(stderr, "Signal received, exiting...\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        int distance;
        char timestamp[32];

        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Error triggering measurement\n");
            continue;
        }

        // Wait for data
        if (wait_for_data(i2c_fd) != 0) {
            fprintf(stderr, "Error waiting for data\n");
            continue;
        }

        // Read distance
        if (read_distance(i2c_fd, &distance) != 0) {
            fprintf(stderr, "Error reading distance\n");
            continue;
        }

        // Get timestamp
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        // Log data
        if (log_data(log_file, timestamp, distance) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait before next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

