// Define the I2C bus and device
#define I2C_BUS "/dev/i2c-1"
#define VL53L5CX_ADDR 0x29

// Define register addresses (example, adjust based on datasheet)
#define REG_IDENTIFICATION_MODEL_ID 0x0000
#define REG_RANGING_MODE 0x001D
#define REG_START_RANGING 0x0008
#define REG_RESULT_RANGE_STATUS 0x0013
#define REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to a specific register
int write_register(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = value;

    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "Error writing to register 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a byte from a specific register
int read_register(int fd, uint16_t reg, uint8_t *value) {
    uint8_t reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    reg_buf[1] = reg & 0xFF;        // LSB of register address

    if (write(fd, reg_buf, 2) != 2) {
        fprintf(stderr, "Error writing register address for read 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from a specific register
int read_register_16(int fd, uint16_t reg, uint16_t *value) {
