#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C

// Define the register address for distance reading
#define DISTANCE_REG 0x00

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read distance from the MLX75030 sensor
int read_distance(int handle, uint16_t *distance)
{
    char buf[2];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadI2CBlockData(handle, DISTANCE_REG, buf, 2);
        if (result == 2) {
            // Combine the two bytes into a 16-bit distance value
            *distance = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (error code: %d), retrying...\n", result);
            gpioDelay(10); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        uint16_t distance;
        if (read_distance(i2c_handle, &distance) == 0) {
            // Get millisecond timestamp
            uint32_t micros = gpioTick();
            uint32_t millis = micros / 1000;

            // Log the distance and timestamp
            printf("Timestamp: %u ms, Distance: %u mm\n", millis, distance);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Clean up and exit
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

