// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// VL53L4CX register addresses
#define VL53L4CX_REG_SOFT_RESET 0x7FFF
#define VL53L4CX_REG_START_RANGING 0x0009
#define VL53L4CX_REG_INTERRUPT_STATUS 0x0046
#define VL53L4CX_REG_DISTANCE_HIGH 0x0096
#define VL53L4CX_REG_DISTANCE_LOW 0x0097

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l4cx_write_byte(int handle, uint16_t reg, uint8_t data);
int vl53l4cx_read_byte(int handle, uint16_t reg, uint8_t *data);
int vl53l4cx_read_word(int handle, uint16_t reg, uint16_t *data);
int vl53l4cx_start_ranging(int handle);
int vl53l4cx_get_distance(int handle, uint16_t *distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to write a byte to a VL53L4CX register
int vl53l4cx_write_byte(int handle, uint16_t reg, uint8_t data) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = data;

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L4CX register
int vl53l4cx_read_byte(int handle, uint16_t reg, uint8_t *data) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%04X: %d\n", reg, result);
        return -1;
    }

    result = i2cReadDevice(handle, (char *)data, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VL53L4CX register
int vl53l4cx_read_word(int handle, uint16_t reg, uint16_t *data) {
    char buf[2];
    char read_buf[2];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%04X: %d\n", reg, result);
        return -1;
    }

    result = i2cReadDevice(handle, read_buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading from register 0x%04X: %d\n", reg, result);
        return -1;
    }

    *data = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Function to start ranging on the VL53L4CX
int vl53l4cx_start_ranging(int handle) {
    return vl53l4cx_write_byte(handle, VL53L4CX_REG_START_RANGING, 0x01);
}

// Function to get the distance from the VL53L4CX
int vl53l4cx_get_distance(int handle, uint16_t *distance) {
    uint8_t interrupt_status;

    if (vl53l4cx_read_byte(handle, VL53L4CX_REG_INTERRUPT_STATUS, &interrupt_status) != 0) {
        return -1;
    }

    if (!(interrupt_status & 0x01)) {
        // Interrupt not set, skip this cycle
        return -2; // Indicate no data available
    }

    if (vl53l4cx_read_word(handle, VL53L4CX_REG_DISTANCE_HIGH, distance) != 0) {
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // VL53L4CX startup sequence
    if (vl53l4cx_write_byte(i2c_handle, VL53L4CX_REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Error during VL53L4CX soft reset\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(10000); // 10 ms delay

    if (vl53l4cx_start_ranging(i2c_handle) != 0) {
        fprintf(stderr, "Error starting VL53L4CX ranging\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t distance;
        int result = vl53l4cx_get_distance(i2c_handle, &distance);

        if (result == 0) {
            // Get current time
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);

            // Format timestamp
            char timestamp[30];
            struct tm *tm_info;
            tm_info = localtime(&ts.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            char microseconds[7];
            sprintf(microseconds, ".%06ld", ts.tv_nsec / 1000);
            strcat(timestamp, microseconds);

            // Log distance with timestamp
            printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);
        } else if (result != -2) {
            fprintf(stderr, "Error getting distance\n");
        }

        gpioDelay(500000); // 500 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

