volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int read_distance();
void control_buzzer(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// VL53L1X initialization function
int vl53l1x_init() {
    int status;
    char buf[2];

    // Soft reset
    buf[0] = 0x00; // Reset command
    status = i2cWriteByteData(i2c_handle, SOFT_RESET, buf[0]);
    if (status < 0) {
        fprintf(stderr, "Error: Soft reset failed (I2C error %d)\n", status);
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Set I2C address (optional, but good practice)
    buf[0] = VL53L1X_ADDR;
    status = i2cWriteByteData(i2c_handle, I2C_SLAVE__DEVICE_ADDRESS, buf[0]);
    if (status < 0) {
        fprintf(stderr, "Error: Setting I2C address failed (I2C error %d)\n", status);
        return -1;
    }

    // Start continuous ranging mode
    buf[0] = 0x01; // Continuous ranging mode
    status = i2cWriteByteData(i2c_handle, SYSTEM__MODE_START, buf[0]);
    if (status < 0) {
        fprintf(stderr, "Error: Starting continuous ranging failed (I2C error %d)\n", status);
        return -1;
    }

    return 0;
}

// Function to read distance from VL53L1X
int read_distance() {
    int distance = -1;
    char buf[2];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM, buf, 2);
    if (status < 0) {
        fprintf(stderr, "Error: Reading distance failed (I2C error %d)\n", status);
        return -1;
    }

    distance = (buf[0] << 8) | buf[1];
