    init_result = vl53l1x_init();
    if (init_result != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed. Attempting to re-initialize...\n");
        i2cClose(i2c_handle);
        i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
