    while (!terminate) {
        distance = read_distance();

        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);

            if (distance < DISTANCE_THRESHOLD) {
                control_buzzer(1); // Turn buzzer on
            } else {
                control_buzzer(0); // Turn buzzer off
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance. Attempting to re-initialize...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not re-open I2C bus (error %d)\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (vl53l1x_init() != 0) {
                    fprintf(stderr, "Error: VL53L1X re-initialization failed. Exiting.\n");
                    terminate = 1;
                }
            }
        }

        gpioDelay(500000); // Wait 500ms
    }

    // Cleanup
    control_buzzer(0); // Ensure buzzer is off
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

