#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0      // cm
#define BUZZER_DURATION 500      // ms

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;
volatile int distance = 0;

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, unsigned int tick);
float calculateDistance(unsigned int pulse_width);
void controlBuzzer(float distance);
void signalHandler(int signal);

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();           // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echoCallback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Set flag to indicate echo received
    } else if (level == 0) {
        end_tick = tick;
    }
}

// Function to calculate distance in centimeters
float calculateDistance(unsigned int pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 for us to s conversion
}

// Function to control the buzzer
void controlBuzzer(float distance) {
    if (distance < 30.0) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
        gpioDelay(BUZZER_DURATION);
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL);

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (1) {
        // Trigger the sensor
        triggerSensor();

        // Wait for echo or timeout
        int timeout = 0;
        while (!echo_received && timeout < 100000) { // 100ms timeout
            gpioDelay(1); // Small delay to avoid busy-waiting
            timeout++;
        }

        if (!echo_received) {
            fprintf(stderr, "Sensor absent or timeout occurred\n");
            gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
            echo_received = 0; // Reset flag
        } else {
            // Calculate pulse width
            unsigned int pulse_width = end_tick - start_tick;

            // Calculate distance
            float distance = calculateDistance(pulse_width);

            // Validate distance
            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                fprintf(stderr, "Invalid reading: %.2f cm\n", distance);
                gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
            } else {
                // Control buzzer
                controlBuzzer(distance);

                // Display distance
                printf("Distance: %.2f cm\n", distance);
            }

            echo_received = 0; // Reset flag
        }

        gpioDelay(100); // Delay 100ms
    }

    return 0;
}

