#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_GPIO 18
#define DISTANCE_THRESHOLD 200 // 20 cm in mm
#define SERVO_OPEN_PULSE 1500
#define SERVO_CLOSE_PULSE 1000
#define MQTT_HOST "localhost" // Change to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "gate_control"
#define MQTT_CLIENT_ID "gate_controller"

// Global variables
int i2c_handle;
FILE *log_file;
struct mosquitto *mosq = NULL;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void servo_set_pulse(int pulse_width);
void log_event(const char *event);
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int signum);

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050


// VL53L1X Initialization
int vl53l1x_init() {
    // Example initialization sequence (adjust based on VL53L1X datasheet)
    char init_data[] = {
        0x00, 0x01, // Example register and value
        0x02, 0x03  // Example register and value
    };
    int init_len = sizeof(init_data);
    int retries = 3;
    int status;

    while (retries > 0) {
        status = i2cWriteDevice(i2c_handle, init_data, init_len);
        if (status == 0) {
            return 0; // Success
        } else {
            log_event("VL53L1X initialization failed, retrying...");
            gpioDelay(100000); // 100ms delay
            retries--;
        }
    }

    log_event("VL53L1X initialization failed after multiple retries.");
    return -1; // Failure
}

// VL53L1X Distance Reading
int vl53l1x_read_distance() {
    char cmd[1] = {VL53L1X_REG_SYSRANGE_START};
    char data[2];
    int distance = -1; // Default to error value
    int retries = 3;
    int status;

    while (retries > 0) {
        status = i2cWriteDevice(i2c_handle, cmd, 1);
        if (status != 0) {
            log_event("Error writing to VL53L1X for start ranging.");
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        gpioDelay(10000); // Wait for measurement (adjust as needed)

        status = i2cReadDevice(i2c_handle, data, 2);
        if (status == 0) {
            distance = (data[0] << 8) | data[1];
            return distance;
        } else {
            log_event("Error reading from VL53L1X.");
            gpioDelay(100000); // 100ms delay
            retries--;
        }
    }

    log_event("VL53L1X read failed after multiple retries.");
    return -1; // Indicate error
}

// Servo Motor Control
void servo_set_pulse(int pulse_width) {
    gpioServo(SERVO_GPIO, pulse_width);
}

// Logging
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

// MQTT Callbacks
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        log_event("MQTT connected to broker.");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_event("MQTT connection failed.");
    }
}

void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(payload, "force_open") == 0) {
            log_event("Received force_open command.");
            servo_set_pulse(SERVO_OPEN_PULSE);
            log_event("Gate opened.");
        } else if (strcmp(payload, "force_close") == 0) {
            log_event("Received force_close command.");
            servo_set_pulse(SERVO_CLOSE_PULSE);
            log_event("Gate closed.");
        } else if (strcmp(payload, "status_request") == 0) {
            log_event("Received status_request command.");
            // Implement status reporting (e.g., distance, gate state)
            char status_message[100];
            int distance = vl53l1x_read_distance();
            if (distance >= 0) {
                snprintf(status_message, sizeof(status_message), "Distance: %d mm, Gate: %s", distance, (distance < DISTANCE_THRESHOLD) ? "Open" : "Closed");
            } else {
                snprintf(status_message, sizeof(status_message), "Error reading distance, Gate: Unknown");
            }
            log_event(status_message);
            mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(status_message), status_message, 0, false);
        } else {
            log_event("Received unknown command.");
        }
    }
}

// Signal Handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_event("Received signal, shutting down...");
        servo_set_pulse(0); // Stop the servo
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        if (mosq) {
            mosquitto_disconnect(mosq);
            mosquitto_destroy(mosq);
            mosquitto_lib_cleanup();
        }
        exit(0);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Error opening I2C bus.");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        log_event("VL53L1X initialization failed.");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize Servo Motor
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_GPIO, 50); // 50 Hz
    gpioSetPWMrange(SERVO_GPIO, 20000); // 20ms period

