#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define TIMEOUT_US 60000       // 60 ms timeout
#define MEASUREMENT_INTERVAL_US 200000 // 200 ms interval

// Global variables
static volatile unsigned int rising_tick = 0;
static volatile unsigned int falling_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
double calculate_distance(unsigned int pulse_duration);
void log_distance(double distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Trigger pulse function
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIG_PIN, 0);
}

// Echo callback function
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        rising_tick = tick;
        echo_received = 1;
    } else if (level == 0) {
        falling_tick = tick;
    }
}

// Calculate distance function
double calculate_distance(unsigned int pulse_duration) {
    return (double)pulse_duration * SPEED_OF_SOUND / 2.0;
}

// Log distance function
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);

    if (log_file != NULL) {
        fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register callback function for ECHO pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_received = 0;
        rising_tick = 0;
        falling_tick = 0;

        trigger_pulse();

        // Wait for echo or timeout
        unsigned int start_time = gpioTick();
        while (!echo_received && (gpioTick() - start_time) < TIMEOUT_US && running) {
            gpioDelay(10); // Small delay to avoid busy-waiting
        }

        if (echo_received) {
            // Calculate pulse duration
            unsigned int pulse_duration = falling_tick - rising_tick;

            // Validate pulse width
            if (pulse_duration < 100 || pulse_duration > 30000) {
                fprintf(stderr, "Warning: Invalid pulse width: %u us\n", pulse_duration);
                if (log_file != NULL) {
                    fprintf(log_file, "Warning: Invalid pulse width: %u us\n", pulse_duration);
                    fflush(log_file);
                }
            } else {
                // Calculate distance
                double distance = calculate_distance(pulse_duration);

                // Log distance
                log_distance(distance);
            }
        } else {
            fprintf(stderr, "Warning: No echo received within timeout.\n");
            if (log_file != NULL) {
                fprintf(log_file, "Warning: No echo received within timeout.\n");
                fflush(log_file);
            }
        }

        gpioDelay(MEASUREMENT_INTERVAL_US);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

