    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to initialize the VL53L1X sensor
int vl53l1x_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x00, 0x00) < 0) {
        log_event("Error: VL53L1X soft reset failed");
        return -1;
    }
    gpioDelay(10000); // 10 ms delay

    // Check sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id < 0) {
        log_event("Error: VL53L1X sensor ID read failed");
        return -1;
    }
    if (sensor_id != 0xea) {
        log_event("Error: VL53L1X sensor ID mismatch");
        return -1;
    }

    // Configure timing budget (100 ms)
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x01) < 0) {
        log_event("Error: VL53L1X pre-range timeout config failed");
