#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 24
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18

// Define I2C bus
#define I2C_BUS 1

// Define VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// Define VL53L1X register addresses
#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_START_MEASUREMENT 0x0000
#define VL53L1X_REG_DATA_READY 0x0089
#define VL53L1X_REG_DISTANCE_HIGH 0x0096
#define VL53L1X_REG_DISTANCE_LOW 0x0097

// Define distance thresholds
#define DISTANCE_FORWARD 100 // mm
#define DISTANCE_BACKWARD 300 // mm

// Global variables
int i2c_handle;
volatile int running = 1;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void control_motor(int distance);
void isr_trigger(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int reg, int data) {
    char buf[2];
    buf[0] = reg & 0xFF;
    buf[1] = data & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int reg, int *data) {
    char reg_addr = reg & 0xFF;
    int result = i2cWriteDevice(i2c_handle, &reg_addr, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read: 0x%02X\n", reg);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, (char *)data, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a 16-bit word from a VL53L1X register
int vl53l1x_read_word(int reg, int *data) {
    char reg_addr = reg & 0xFF;
    int result = i2cWriteDevice(i2c_handle, &reg_addr, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read: 0x%02X\n", reg);
        return -1;
    }

    char buf[2];
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02X: %d\n", reg, result);
        return -1;
    }

    *data = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to initialize the VL53L1X sensor
int vl53l1x_init() {
    // Soft reset
    if (vl53l1x_write_byte(VL53L1X_REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(1000); // 1 ms delay

    // Start measurement
    if (vl53l1x_write_byte(VL53L1X_REG_START_MEASUREMENT, 0x01) != 0) return -1;

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int vl53l1x_read_distance(int *distance) {
    int data_ready;
    int retries = 0;
    int delay_ms = 1;

    // Wait for data ready
    while (retries < 10) {
        if (vl53l1x_read_byte(VL53L1X_REG_DATA_READY, &data_ready) != 0) {
            fprintf(stderr, "Error reading data ready status, retrying...\n");
            gpioDelay(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            retries++;
            continue;
        }

        if (data_ready & 0x01) {
            break; // Data ready
        }

        gpioDelay(1000); // 1 ms delay
    }

