    if (i2c_write_byte(fd, 0x5E, 0x82) < 0) return -1; // Filter level
    if (i2c_write_byte(fd, 0x5F, 0xB4) < 0) return -1; // Release time

    // Enable all electrodes
    if (i2c_write_byte(fd, 0x5E, 0x0C) < 0) return -1;

    return 0;
}

// MPR121 read touch status function
int mpr121_read_touch_status(int fd, uint16_t *touch_status) {
    uint8_t msb, lsb;

    if (i2c_read_byte(fd, 0x00, &lsb) < 0) return -1;
    if (i2c_read_byte(fd, 0x01, &msb) < 0) return -1;

    *touch_status = ((uint16_t)msb << 8) | lsb;
    return 0;
}

// Set LED pattern function
void set_led_pattern(int pattern) {
    int led1_val = (pattern & 0x01) ? 1 : 0;
    int led2_val = (pattern & 0x02) ? 1 : 0;
    int led3_val = (pattern & 0x04) ? 1 : 0;
    int led4_val = (pattern & 0x08) ? 1 : 0;

    gpiod_line_set_value(led1_line, led1_val);
    gpiod_line_set_value(led2_line, led2_val);
    gpiod_line_set_value(led3_line, led3_val);
    gpiod_line_set_value(led4_line, led4_val);
}

// Log event function
void log_event(int electrode, int pattern) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Electrode %d: Pattern 0x%02X\n", timestamp, electrode, pattern);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO lines
    led1_line = gpiod_chip_get_line(chip, LED1_PIN);
    led2_line = gpiod_chip_get_line(chip, LED2_PIN);
    led3_line = gpiod_chip_get_line(chip, LED3_PIN);
    led4_line = gpiod_chip_get_line(chip, LED4_PIN);

    if (!led1_line || !led2_line || !led3_line || !led4_line) {
        perror("Failed to get GPIO line");
        if (led1_line) gpiod_line_release(led1_line);
        if (led2_line) gpiod_line_release(led2_line);
        if (led3_line) gpiod_line_release(led3_line);
        if (led4_line) gpiod_line_release(led4_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(led1_line, "mpr121_art", 0) < 0 ||
        gpiod_line_request_output(led2_line, "mpr121_art", 0) < 0 ||
        gpiod_line_request_output(led3_line, "mpr121_art", 0) < 0 ||
        gpiod_line_request_output(led4_line, "mpr121_art", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_line_release(led1_line);
        gpiod_line_release(led2_line);
        gpiod_line_release(led3_line);
        gpiod_line_release(led4_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    uint16_t touch_status;
    int active_electrode = -1;
    int active_pattern = 0;

    // Main loop
    while (1) {
        if (mpr121_read_touch_status(i2c_fd, &touch_status) < 0) {
            fprintf(stderr, "Error reading touch status\n");
            continue; // Continue to the next iteration
        }

        // Find the first electrode that is active
        int new_active_electrode = -1;
        for (int i = 0; i < 12; i++) {
            if (touch_status & (1 << i)) {
                new_active_electrode = i;
                break;
            }
        }

        // Determine the LED pattern based on the active electrode
        int new_active_pattern = 0;
        if (new_active_electrode != -1) {
            switch (new_active_electrode) {
                case 0: new_active_pattern = 0x01; break;
                case 1: new_active_pattern = 0x02; break;
                case 2: new_active_pattern = 0x04; break;
                case 3: new_active_pattern = 0x08; break;
                case 4: new_active_pattern = 0x03; break;
                case 5: new_active_pattern = 0x06; break;
                case 6: new_active_pattern = 0x0C; break;
                case 7: new_active_pattern = 0x0A; break;
                case 8: new_active_pattern = 0x05; break;
                case 9: new_active_pattern = 0x0A; break;
                case 10: new_active_pattern = 0x05; break;
                case 11: new_active_pattern = 0x0A; break;
                default: new_active_pattern = 0x00; break;
            }
        }

        // Update LEDs and log event if the active electrode or pattern has changed
        if (new_active_electrode != active_electrode || new_active_pattern != active_pattern) {
            active_electrode = new_active_electrode;
            active_pattern = new_active_pattern;
            set_led_pattern(active_pattern);

            if (active_electrode == -1) {
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[80];

                time(&rawtime);
                timeinfo = localtime(&rawtime);

                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                printf("[%s] No electrode is currently active\n", timestamp);
            } else {
                log_event(active_electrode, active_pattern);
            }
        }

        usleep(50000); // 50ms delay
    }

    return 0;
}

