#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define LED_GPIO 27
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x05
#define LOG_FILE "proximity.log"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpr121();
int read_mpr121_register(int reg);
int write_mpr121_register(int reg, int value);
int is_proximity_detected();
void control_led(int on);
void log_event();
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize MPR121
int initialize_mpr121() {
    // Verify device ID
    int device_id = read_mpr121_register(0x00);
    if (device_id != 0x5A) {
        fprintf(stderr, "Error: Invalid device ID: 0x%02X\n", device_id);
        return -1;
    }

    // Configure touch and release thresholds
    if (write_mpr121_register(0x41, TOUCH_THRESHOLD) < 0) return -1;
    if (write_mpr121_register(0x42, RELEASE_THRESHOLD) < 0) return -1;

    // Configure electrode 0
    if (write_mpr121_register(0x5E, 0x01) < 0) return -1; // Enable electrode 0

    // Configure FFI, SFI, ESI, debounce, AFE config, and baseline filtering
    if (write_mpr121_register(0x2B, 0x01) < 0) return -1; // FFI
    if (write_mpr121_register(0x2C, 0x01) < 0) return -1; // SFI
    if (write_mpr121_register(0x2D, 0x01) < 0) return -1; // ESI
    if (write_mpr121_register(0x5B, 0x06) < 0) return -1; // Debounce
    if (write_mpr121_register(0x5C, 0x24) < 0) return -1; // AFE config
    if (write_mpr121_register(0x5D, 0x10) < 0) return -1; // Baseline filtering

    // Start the sensor
    if (write_mpr121_register(0x80, 0x01) < 0) return -1; // Enable all electrodes

    return 0;
}

// Read MPR121 register
int read_mpr121_register(int reg) {
    int value = i2cReadByteData(i2c_handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Write MPR121 register
int write_mpr121_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Check if proximity is detected on electrode 0
int is_proximity_detected() {
    int touch_status = read_mpr121_register(0x00);
    if (touch_status < 0) return 0; // Return 0 on error
    return (touch_status & 0x01) ? 1 : 0; // Check electrode 0
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Log event to file
void log_event() {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: Proximity detected\n", s);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity detector running. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (is_proximity_detected()) {
            control_led(1);
            log_event();
            gpioDelay(1000); // 1 second
            control_led(0);
        }
        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

