#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 343.0 // m/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define TIMEOUT_US 30000       // 30 ms

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
void trigger_sensor(void);
long long measure_pulse_width(void);
double calculate_distance(long long pulse_width);
void log_distance(double distance);
void cleanup(int signal);

// Signal handler
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;

    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

// Initialize GPIO lines
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "distance_sensor", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "distance_sensor") < 0) {
        perror("Error requesting echo line as input");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor(void) {
    gpiod_line_set_value(trigger_line, 1);
    usleep(10); // 10 microseconds
    gpiod_line_set_value(trigger_line, 0);
    usleep(5);  // 5 microseconds
}

// Measure the echo pulse width
long long measure_pulse_width(void) {
    struct timespec start, end;
    int rising_edge = 0;
    long long pulse_width = 0;
    int value;

    // Wait for the rising edge
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (!rising_edge) {
        value = gpiod_line_get_value(echo_line);
        if (value < 0) {
            fprintf(stderr, "Error reading echo line value\n");
            return -1;
        }
        if (value == 1) {
            rising_edge = 1;
            clock_gettime(CLOCK_MONOTONIC, &start);
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000) > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return -1;
        }
    }

    // Measure the pulse width
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        value = gpiod_line_get_value(echo_line);
        if (value < 0) {
            fprintf(stderr, "Error reading echo line value\n");
            return -1;
        }
        if (value == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            pulse_width = ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000);
            return pulse_width;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000) > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return -1;
        }
    }
}

// Calculate the distance in centimeters
double calculate_distance(long long pulse_width) {
    return (pulse_width * 0.0343) / 2.0;
}

// Log the distance to a file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
    fflush(log_file);
}

int main(void) {
    // Install signal handler
    signal(SIGINT, cleanup);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup(0);
        return 1;
    }

    // Main loop
    while (!terminate) {
        trigger_sensor();
        long long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            double distance = calculate_distance(pulse_width);

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
            }
        } else {
            fprintf(stderr, "Error measuring pulse width\n");
        }

        sleep(1);
    }

    // Cleanup (should not reach here if signal handler works)
    cleanup(0);

    return 0;
}

