#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIG_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 343.0 // m/s
#define TIMEOUT_US 25000      // 25ms timeout

// Global variables
static volatile unsigned int start_tick = 0;
static volatile unsigned int end_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int running;
} program_state_t;

program_state_t state = {1}; // Initialize running to 1

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);
}

// Interrupt service routine for echo pin
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 0; // Reset echo received flag for new pulse
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 1; // Set echo received flag
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    state.running = 0; // Set running to 0 to exit the main loop

    // Disable the ISR
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open the log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up the ISR
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (state.running) {
        // Fire a trigger pulse
        trigger_pulse();

        // Wait for a short period
        gpioDelay(1000000); // 1 second

        // Calculate pulse width
        unsigned int pulse_width = end_tick - start_tick;
        if (pulse_width > 0xFFFFFFFF - start_tick) {
            pulse_width = end_tick + (0xFFFFFFFF - start_tick); // Handle tick wraparound
        }

        // Validate pulse width
        if (pulse_width < 58 || pulse_width > TIMEOUT_US || !echo_received) {
            fprintf(stderr, "Invalid pulse width: %u us\n", pulse_width);
            fprintf(log_file, "Invalid pulse width: %u us\n", pulse_width);
            fflush(log_file);
            continue;
        }

        // Calculate distance
        float distance = (float)pulse_width * SPEED_OF_SOUND / 1000000.0;

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log the distance
        fprintf(log_file, "%s, %.2f m\n", timestamp, distance);
        fflush(log_file);

        printf("%s, Distance: %.2f m\n", timestamp, distance);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

