#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define XSHUT_GPIO 27
#define CONTINUOUS_MODE_REG 0x0018
#define NO_TIMEOUT_REG 0x0019
#define START_RANGING_REG 0x0020
#define DISTANCE_REG 0x0014
#define STATUS_REG 0x0016
#define READ_DELAY_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_distance(int *distance, int *status);
void log_data(int distance, int status);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to initialize the VL53L1X sensor
int init_sensor() {
    // Enable continuous mode
    if (i2cWriteByteData(i2c_handle, CONTINUOUS_MODE_REG, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to set continuous mode");
        return -1;
    }

    // Disable timeout
    if (i2cWriteByteData(i2c_handle, NO_TIMEOUT_REG, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to set no timeout");
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, START_RANGING_REG, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to start ranging");
        return -1;
    }

    return 0;
}

// Function to read distance and status from the sensor
int read_distance(int *distance, int *status) {
    char buffer[3];

    // Read 3 bytes: distance (2 bytes) and status (1 byte)
    if (i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buffer, 3) != 3) {
        syslog(LOG_ERR, "Failed to read distance and status");
        return -1;
    }

    // Combine the two distance bytes into a single integer
    *distance = (buffer[0] << 8) | buffer[1];
    *status = buffer[2];

    return 0;
}

// Function to log data to syslog
void log_data(int distance, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (status == 0) {
        syslog(LOG_INFO, "%s Distance: %d mm, Status: %d", timestamp, distance, status);
    } else {
        syslog(LOG_ERR, "%s Error: Distance = %d, Status = %d", timestamp, distance, status);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    // Set XSHUT_GPIO as output and set it high
    gpioSetMode(XSHUT_GPIO, PI_OUTPUT);
    gpioWrite(XSHUT_GPIO, 1);

    // Initialize the sensor
    if (init_sensor() < 0) {
        syslog(LOG_ERR, "Sensor initialization failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int distance, status;
    while (!terminate) {
        if (read_distance(&distance, &status) == 0) {
            log_data(distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read sensor data");
        }

        gpioDelay(READ_DELAY_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    syslog(LOG_INFO, "Program terminated cleanly");
    return 0;
}

