#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD 20 // cm
#define LOG_FILE "gate_log.txt"

// VL53L1X register addresses
#define VL53L1X_REG_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MODE 0x0021
#define VL53L1X_REG_START_RANGING 0x0015
#define VL53L1X_REG_DISTANCE 0x0089

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_gate(int distance);
void log_data(int distance, int gate_state);
void signal_handler(int signal);

// Structure to hold VL53L1X configuration
typedef struct {
    int ranging_mode;
} vl53l1x_config_t;

// Function to write a byte to a VL53L1X register
int write_register(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = value;

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int read_register(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%04X: %d\n", reg, result);
        return -1;
    }

    result = i2cReadDevice(handle, (char *)value, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    uint8_t model_id;

    // Check Model ID
    if (read_register(i2c_handle, VL53L1X_REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading Model ID\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect Model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Set ranging mode to short
    if (write_register(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x00) != 0) {
        fprintf(stderr, "Error setting ranging mode\n");
        return -1;
    }

    // Start ranging
    if (write_register(i2c_handle, VL53L1X_REG_START_RANGING, 0x01) != 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int read_distance() {
    uint8_t distance_msb, distance_lsb;
    int distance;

    if (read_register(i2c_handle, VL53L1X_REG_DISTANCE, &distance_msb) != 0) {
        fprintf(stderr, "Error reading distance MSB\n");
        return -1;
    }
    if (read_register(i2c_handle, VL53L1X_REG_DISTANCE + 1, &distance_lsb) != 0) {
        fprintf(stderr, "Error reading distance LSB\n");
        return -1;
    }

    distance = (distance_msb << 8) | distance_lsb;
    return distance;
}

