#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0      // cm
#define MIN_ANGLE 0.0          // degrees
#define MAX_ANGLE 180.0         // degrees
#define MIN_PULSE_WIDTH 500.0   // us
#define MAX_PULSE_WIDTH 2500.0  // us
#define TIMEOUT_US 30000        // 30 ms

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_valid = 0;
static volatile int trigger_requested = 0;
static volatile int program_running = 1;

// Moving average filter
#define MOVING_AVG_SIZE 5
static float distance_buffer[MOVING_AVG_SIZE];
static int buffer_index = 0;

// File pointer for logging
FILE *log_file = NULL;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(int pulse_width);
float apply_moving_average(float new_distance);
float map_distance_to_angle(float distance);
int set_servo_angle(float angle);
void log_data(float distance, float angle);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
    trigger_requested = 0; // Reset trigger flag
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_valid = 0; // Reset validity flag for each rising edge
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_valid = 1; // Set validity flag
    }
}

// Function to calculate distance from pulse width
float calculate_distance(int pulse_width) {
    if (pulse_width < 0) return -1.0; // Error condition
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // cm
}

// Function to apply a moving average filter
float apply_moving_average(float new_distance) {
    distance_buffer[buffer_index] = new_distance;
    buffer_index = (buffer_index + 1) % MOVING_AVG_SIZE;

    float sum = 0.0;
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        sum += distance_buffer[i];
    }
    return sum / MOVING_AVG_SIZE;
}

// Function to map distance to servo angle (logarithmic mapping)
float map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) return -1.0; // Invalid distance

    // Logarithmic mapping
    float angle = (log10(distance / MIN_DISTANCE) / log10(MAX_DISTANCE / MIN_DISTANCE)) * (MAX_ANGLE - MIN_ANGLE);
    return angle;
}

// Function to set the servo angle
int set_servo_angle(float angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) return -1; // Invalid angle

    // Map angle to pulse width
    int pulse_width = (int)(MIN_PULSE_WIDTH + (angle / MAX_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

    int result = gpioServo(SERVO_PIN, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo pulse width: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to log data to a CSV file
void log_data(float distance, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Stop the servo
    gpioServo(SERVO_PIN, 0); // Set pulse width to 0 to stop the servo

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM range for servo (optional, but recommended)
    gpioSetPWMrange(SERVO_PIN, 2000); // Set PWM range to 2000 for 500-2500 us pulse widths
    gpioSetPWMfrequency(SERVO_PIN, 50); // Set PWM frequency to 50 Hz

    // Register alert callback for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register alert callback\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (degrees)\n");
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize distance buffer with 0s
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        distance_buffer[i] = 0.0;
    }

    // Main loop
    while (program_running) {
        trigger_requested = 1; // Request a trigger

        // Wait for trigger to be processed
        while (trigger_requested && program_running) {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        // Wait for echo pulse with timeout
        int timeout_count = 0;
        while (!echo_valid && timeout_count < TIMEOUT_US && program_running) {
            gpioDelay(1); // Small delay to avoid busy-waiting
            timeout_count++;
        }

        if (!echo_valid) {
            fprintf(stderr, "Timeout waiting for echo\n");
            log_data(-1.0, 90.0); // Log -1.0 for invalid reading
            set_servo_angle(90.0); // Default to 90 degrees
        } else {
            // Calculate pulse width
            int pulse_width = echo_end_tick - echo_start_tick;
            if (pulse_width < 0) {
                // Handle tick counter wrap-around
                pulse_width = (0xFFFFFFFF - echo_start_tick) + echo_end_tick;
            }

            // Calculate distance
            float distance = calculate_distance(pulse_width);

            // Apply moving average filter
            float filtered_distance = apply_moving_average(distance);

            // Map distance to servo angle
            float angle = map_distance_to_angle(filtered_distance);

            if (angle < 0) {
                fprintf(stderr, "Invalid distance for angle mapping\n");
                log_data(-1.0, 90.0); // Log -1.0 for invalid reading
                set_servo_angle(90.0); // Default to 90 degrees
            } else {
                // Set servo angle
                if (set_servo_angle(angle) != 0) {
                    fprintf(stderr, "Failed to set servo angle\n");
                }

                // Log data
                log_data(filtered_distance, angle);
            }
        }

        gpioDelay(100); // Trigger every 100 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioServo(SERVO_PIN, 0); // Stop the servo
    fclose(log_file);
    gpioTerminate();

    return 0;
}

