#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define PROXIMITY_REG_HIGH 0x08
#define PROXIMITY_REG_LOW 0x09
#define INTERRUPT_GPIO 27
#define LOG_FILE "proximity.log"

// Global variables
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile int running = 1;
static int threshold = DEFAULT_THRESHOLD;
static int i2c_address = DEFAULT_I2C_ADDRESS;

// Mutex for thread safety
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
int init_i2c(int address);
int read_proximity(int handle);
void log_data(int proximity, const char *status);
void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata);
void signal_handler(int signal);
void cleanup();

// Structure to hold interrupt data
typedef struct {
    int proximity;
    int gpio;
    int level;
    uint32_t tick;
} interrupt_data_t;

// Queue for interrupt data
static interrupt_data_t interrupt_queue[10]; // Simple circular buffer
static int queue_head = 0;
static int queue_tail = 0;
static int queue_size = 0;

// Function to enqueue data
void enqueue(interrupt_data_t data) {
    if (queue_size < 10) {
        interrupt_queue[queue_tail] = data;
        queue_tail = (queue_tail + 1) % 10;
        queue_size++;
    } else {
        fprintf(stderr, "Error: Interrupt queue is full.\n");
    }
}

// Function to dequeue data
interrupt_data_t dequeue() {
    interrupt_data_t data = {0, 0, 0, 0}; // Initialize to default values
    if (queue_size > 0) {
        data = interrupt_queue[queue_head];
        queue_head = (queue_head + 1) % 10;
        queue_size--;
    }
    return data;
}

// Function to check if the queue is empty
int is_queue_empty() {
    return queue_size == 0;
}

// Initialize I2C
int init_i2c(int address) {
    i2c_handle = i2cOpen(I2C_BUS, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02x: %d\n", address, i2c_handle);
        return -1;
    }
    return 0;
}

// Read proximity value from sensor
int read_proximity(int handle) {
    int high_byte, low_byte;

    high_byte = i2cReadByteData(handle, PROXIMITY_REG_HIGH);
    if (high_byte < 0) {
        fprintf(stderr, "Error: Could not read high byte from I2C: %d\n", high_byte);
        return -1;
    }

    low_byte = i2cReadByteData(handle, PROXIMITY_REG_LOW);
    if (low_byte < 0) {
        fprintf(stderr, "Error: Could not read low byte from I2C: %d\n", low_byte);
        return -1;
    }

    return (high_byte << 8) | low_byte;
}

// Log data to file
void log_data(int proximity, const char *status) {
    pthread_mutex_lock(&log_mutex);
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %d, %s\n", timestamp, proximity, status);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    pthread_mutex_unlock(&log_mutex);
}

// Interrupt handler
void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    int proximity = read_proximity(i2c_handle);
    if (proximity >= 0) {
        if (proximity > threshold) {
            log_data(proximity, "ALERT");
        } else {
            log_data(proximity, "SAFE");
        }
    } else {
        fprintf(stderr, "Error: Could not read proximity in interrupt handler.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&log_mutex);
    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c(i2c_address) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler
    if (gpioSetISRFuncEx(INTERRUPT_GPIO, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: Could not set up interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Threshold: %d, I2C Address: 0x%02x, Logging to %s. Press Ctrl+C to exit.\n", threshold, i2c_address, LOG_FILE);

    // Main loop
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

