// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SPEAKER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 200.0     // cm
#define MIN_FREQUENCY 200.0    // Hz
#define MAX_FREQUENCY 2000.0   // Hz
#define TIMEOUT_US 200000       // 200 ms
#define TRIGGER_PULSE_US 10     // 10 us

// Global variables
static volatile int running = 1;
static double last_frequency = MIN_FREQUENCY; // Initialize with a safe default

// Function prototypes
double measure_distance();
double map_distance_to_frequency(double distance);
void set_speaker_frequency(double frequency);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioPWM(SPEAKER_PIN, 0); // Stop PWM
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

// Function to measure distance using HC-SR04
double measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1);

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate the distance
    double distance = (double)diff_tick / 1000000.0 * SPEED_OF_SOUND / 2.0;

    return distance;
}

// Function to map distance to frequency
double map_distance_to_frequency(double distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        return 200 * exp(distance / 50);
    }
}

// Function to set the speaker frequency
void set_speaker_frequency(double frequency) {
    int range = 1000000 / (int)frequency; // Calculate PWM range
    gpioSetPWMrange(SPEAKER_PIN, range);
    gpioPWM(SPEAKER_PIN, range / 2); // 50% duty cycle
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SPEAKER_PIN, PI_OUTPUT);

    // Set PWM frequency (initial value)
    set_speaker_frequency(MIN_FREQUENCY);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        double distance = measure_distance();

        if (distance > 0) {
            double frequency = map_distance_to_frequency(distance);
            set_speaker_frequency(frequency);
            last_frequency = frequency; // Update last frequency
        } else {
            // Keep the last known frequency if distance measurement fails
            set_speaker_frequency(last_frequency);
        }

        gpioDelay(10); // Delay for 10 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(SPEAKER_PIN, 0); // Stop PWM
    gpioTerminate();         // Terminate pigpio

    return 0;
}

