// Define GPIO pins
#define BUZZER_PIN 18
#define TRIGGER_PIN 23
#define ECHO_PIN 24

// Define frequency range
#define MIN_FREQ 200
#define MAX_FREQ 2000

// Define distance range
#define MIN_DIST 5.0
#define MAX_DIST 50.0

// Define timeout value
#define TIMEOUT_US 100000 // 100 ms

// Global variables
static volatile int running = 1;
static float last_distance = 50.0; // Initialize with a reasonable default

// Function prototypes
float read_distance();
float map_distance_to_frequency(float distance);
void set_buzzer_frequency(float frequency);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    set_buzzer_frequency(0.0); // Stop the buzzer
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read distance from HC-SR04 sensor
float read_distance() {
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low
    gpioDelay(2); // Wait for 2 us

    gpioWrite(TRIGGER_PIN, 1); // Send a 10 us pulse
    gpioDelay(10); // Wait for 10 us
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = gpioTick();
    uint32_t end_tick = start_tick;

    // Wait for echo to go high
    while (gpioRead(ECHO_PIN) == 0) {
        end_tick = gpioTick();
        if (end_tick - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo timeout\n");
            return last_distance; // Return the last valid distance
        }
    }

    start_tick = gpioTick();

    // Wait for echo to go low
    while (gpioRead(ECHO_PIN) == 1) {
        end_tick = gpioTick();
        if (end_tick - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo timeout\n");
            return last_distance; // Return the last valid distance
        }
    }

    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    float distance = (pulse_width / 1000000.0) * 34300.0 / 2.0;

    last_distance = distance; // Update last valid distance
    return distance;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    float frequency = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST);

    // Clamp frequency to the defined range
    if (frequency < MIN_FREQ) {
        frequency = MIN_FREQ;
    } else if (frequency > MAX_FREQ) {
        frequency = MAX_FREQ;
    }

    return frequency;
}

// Function to set buzzer frequency using pigpio's gpioHardwarePWM
void set_buzzer_frequency(float frequency) {
    if (frequency > 0.0) {
        gpioHardwarePWM(BUZZER_PIN, (int)frequency, 500000); // Set PWM frequency and duty cycle (50%)
    } else {
        gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop the PWM output
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Theremin-like instrument running. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        float distance = read_distance();
        float frequency = map_distance_to_frequency(distance);

        set_buzzer_frequency(frequency);

        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);

        gpioDelay(10000); // Delay for 10 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_buzzer_frequency(0.0);
    gpioTerminate();

    return 0;
}

