// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define TRIGGER_PULSE_DURATION 10 // us
#define TIMEOUT_DURATION 50000      // us (50ms)
#define SPEED_OF_SOUND 29.1        // cm/us
#define MIN_DISTANCE 2.0           // cm
#define MAX_DISTANCE 400.0         // cm
#define DISTANCE_THRESHOLD 10.0    // cm

// Global variable for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to measure distance in centimeters
float measure_distance() {
    long long start_time, end_time, pulse_width;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);

    // Measure the echo pulse width
    start_time = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_time > TIMEOUT_DURATION) {
            return -1.0; // Timeout
        }
    }

    start_time = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_time > TIMEOUT_DURATION) {
            return -1.0; // Timeout
        }
    }
    end_time = gpioTick();

    pulse_width = end_time - start_time;

    // Calculate distance
    float distance = (float)pulse_width / 2.0 / SPEED_OF_SOUND;

    return distance;
}

int main() {
    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Main loop
    while (program_running) {
        float distance = measure_distance();

        if (distance > 0) {
            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                printf("Invalid reading\n");
            } else {
                printf("Distance: %.2f cm", distance);
                if (distance < DISTANCE_THRESHOLD) {
                    printf(" - Too close!");
                }
                printf("\n");
            }
        } else {
            printf("Timeout occurred\n");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

