#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define sensor and SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // Chip Select pin (GPIO8)

// Define sensor registers
#define MEASURE_REG 0x00
#define CONTINUOUS_MODE 0x01
#define RANGE_REG 0x02
#define DISTANCE_LOW_REG 0x0C
#define DISTANCE_HIGH_REG 0x0D

// Define distance range
#define MIN_DISTANCE 200
#define MAX_DISTANCE 5000

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_sensor();
int read_distance(int *distance);
int log_distance(int distance);
void signal_handler(int signal);

// Structure to hold sensor configuration
typedef struct {
    int spi_channel;
    int spi_speed;
    int cs_pin;
    int continuous_mode;
    int range;
} sensor_config_t;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the sensor
int init_sensor() {
    // Configure sensor registers
    char tx_buf[2];
    char rx_buf[2];

    // Set continuous measurement mode
    tx_buf[0] = MEASURE_REG;
    tx_buf[1] = CONTINUOUS_MODE;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to set continuous mode.\n");
        return -1;
    }

    // Set range to 5m
    tx_buf[0] = RANGE_REG;
    tx_buf[1] = 0x00; // 5m range
