#include <linux/i2c-dev.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <errno.h>

// Define the I2C bus and device address
#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x60

// Define the register addresses for ALS visible light
#define ALS_VISIBLE_LOW 0x22
#define ALS_VISIBLE_HIGH 0x23

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Global variable for the log file pointer
FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close the I2C device if it's open
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    exit(0);
}

// Function to read a 16-bit value from the Si1175 sensor
uint16_t read_si1175_als_visible() {
    uint8_t buffer[2];
    int result;

    // Read the low byte
    result = i2c_smbus_read_byte_data(i2c_fd, ALS_VISIBLE_LOW);
    if (result < 0) {
        fprintf(stderr, "Error reading ALS_VISIBLE_LOW: %s\n", strerror(errno));
        return 0; // Return 0 on error
    }
    buffer[0] = (uint8_t)result;

    // Read the high byte
    result = i2c_smbus_read_byte_data(i2c_fd, ALS_VISIBLE_HIGH);
    if (result < 0) {
        fprintf(stderr, "Error reading ALS_VISIBLE_HIGH: %s\n", strerror(errno));
        return 0; // Return 0 on error
    }
    buffer[1] = (uint8_t)result;

    // Combine the bytes into a 16-bit value (little-endian)
    return (uint16_t)((buffer[1] << 8) | buffer[0]);
}

// Function to get the current timestamp in ISO-8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log the data to a CSV file
int log_data(const char *timestamp, uint16_t als_visible) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%u\n", timestamp, als_visible);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int result;
    uint16_t als_visible;
    char *timestamp;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    result = ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDR);
    if (result < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,als_visible\n");
    }
    rewind(log_file);

    // Main loop
    while (1) {
        // Read the ALS visible light value
        als_visible = read_si1175_als_visible();

        // Get the current timestamp
        timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Error getting timestamp\n");
            continue; // Skip logging this iteration
        }

        // Log the data
        if (log_data(timestamp, als_visible) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        free(timestamp); // Free the allocated memory

        // Wait for 5 seconds
        sleep(5);
    }

    // The following lines will never be reached because of the infinite loop.
    // However, they are included for completeness and to demonstrate proper cleanup.
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

