#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1120 I2C address
#define SI1120_ADDR 0x60

// Si1120 register addresses
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_ALS_DATA_LOW 0x22
#define SI1120_REG_ALS_DATA_HIGH 0x23
#define SI1120_REG_PS1_DATA_LOW 0x18
#define SI1120_REG_PS1_DATA_HIGH 0x19
#define SI1120_REG_RESET 0x30

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1120_init();
int read_als_data(uint16_t *als_value);
int read_ps1_data(uint16_t *ps1_value);
char* get_timestamp();
int log_data(const char *timestamp, uint16_t als_value, uint16_t ps1_value);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the Si1120 sensor
int si1120_init() {
    int retries = 3;
    int result;

    // Reset the sensor
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, SI1120_REG_RESET, 0x01);
        if (result == 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error resetting Si1120: %d. Retrying...\n", result);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to reset Si1120 after multiple retries.\n");
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete

    // Verify Part ID
    retries = 3;
    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, SI1120_REG_PART_ID);
        if (result >= 0) {
            if (result == 0x41) {
                break; // Success
            } else {
                fprintf(stderr, "Error: Incorrect Part ID: 0x%02X\n", result);
                return -1;
            }
        } else {
            fprintf(stderr, "Error reading Part ID: %d. Retrying...\n", result);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read Part ID after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Read ALS data from the sensor
int read_als_data(uint16_t *als_value) {
    int retries = 3;
    int result;
    uint8_t low_byte, high_byte;

    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, SI1120_REG_ALS_DATA_LOW);
        if (result >= 0) {
            low_byte = (uint8_t)result;
            result = i2cReadByteData(i2c_handle, SI1120_REG_ALS_DATA_HIGH);
            if (result >= 0) {
                high_byte = (uint8_t)result;
                *als_value = (high_byte << 8) | low_byte;
                return 0; // Success
            } else {
                fprintf(stderr, "Error reading ALS high byte: %d. Retrying...\n", result);
                gpioDelay(10000); // 10 ms delay
                retries--;
            }
        } else {
            fprintf(stderr, "Error reading ALS low byte: %d. Retrying...\n", result);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read ALS data after multiple retries.\n");
    return -1;
}

// Read PS1 data from the sensor
int read_ps1_data(uint16_t *ps1_value) {
    int retries = 3;
    int result;
    uint8_t low_byte, high_byte;

    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, SI1120_REG_PS1_DATA_LOW);
        if (result >= 0) {
            low_byte = (uint8_t)result;
            result = i2cReadByteData(i2c_handle, SI1120_REG_PS1_DATA_HIGH);
            if (result >= 0) {
                high_byte = (uint8_t)result;
                *ps1_value = (high_byte << 8) | low_byte;
                return 0; // Success
            } else {
                fprintf(stderr, "Error reading PS1 high byte: %d. Retrying...\n", result);
                gpioDelay(10000); // 10 ms delay
                retries--;
            }
        } else {
            fprintf(stderr, "Error reading PS1 low byte: %d. Retrying...\n", result);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read PS1 data after multiple retries.\n");
    return -1;
}

// Get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Static to persist across calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Log the data to a file
int log_data(const char *timestamp, uint16_t als_value, uint16_t ps1_value) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, ALS: %u, PS1: %u\n", timestamp, als_value, ps1_value) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    uint16_t als_value, ps1_value;
    char *timestamp;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
