// Define the I2C bus and sensor address
#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x39

// Define register addresses
#define SI1182_PART_ID 0x00
#define SI1182_MEAS_RATE 0x08
#define SI1182_ALS_DATA_L 0x22
#define SI1182_ALS_DATA_H 0x23
#define SI1182_PROX_DATA_L 0x24
#define SI1182_PROX_DATA_H 0x25

// Global variables for file descriptors and program state
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_register(int fd, unsigned char reg);
int i2c_write_register(int fd, unsigned char reg, unsigned char value);
int initialize_sensor(int fd);
int read_sensor_data(int fd, float *lux, int *proximity);
void log_data(FILE *fp, float lux, int proximity);
void print_data(float lux, int proximity);
void signal_handler(int sig);

// I2C read function
int i2c_read_register(int fd, unsigned char reg) {
    int result;
    unsigned char buf[1];

    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address for read");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }

    result = buf[0];
    return result;
}

// I2C write function
int i2c_write_register(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];

    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register and value");
        return -1;
    }

    return 0;
}

// Sensor initialization function
int initialize_sensor(int fd) {
    int part_id;

    // Verify Part ID
    part_id = i2c_read_register(fd, SI1182_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID\n");
        return -1;
    }
    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    // Configure measurement rate
    if (i2c_write_register(fd, SI1182_MEAS_RATE, 0x07) < 0) {
        fprintf(stderr, "Error writing measurement rate\n");
        return -1;
    }

    return 0;
}

// Read sensor data function
int read_sensor_data(int fd, float *lux, int *proximity) {
    int als_low, als_high, prox_low, prox_high;
    int als_raw, prox_raw;

    als_low = i2c_read_register(fd, SI1182_ALS_DATA_L);
    als_high = i2c_read_register(fd, SI1182_ALS_DATA_H);
    prox_low = i2c_read_register(fd, SI1182_PROX_DATA_L);
    prox_high = i2c_read_register(fd, SI1182_PROX_DATA_H);

    if (als_low < 0 || als_high < 0 || prox_low < 0 || prox_high < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    als_raw = (als_high << 8) | als_low;
    prox_raw = (prox_high << 8) | prox_low;

    *lux = (float)als_raw * 0.1;
    *proximity = prox_raw;

    return 0;
}

