void log_data(FILE *fp, float lux, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[25];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%03ld", timeinfo);

    fprintf(fp, "%s,%.2f,%d\n", timestamp, lux, proximity);
    fflush(fp); // Ensure data is written to file immediately
}

