void print_data(float lux, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[25];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%03ld", timeinfo);

    printf("%s,%.2f,%d\n", timestamp, lux, proximity);
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int main() {
    float lux;
    int proximity;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        if (read_sensor_data(i2c_fd, &lux, &proximity) == 0) {
            log_data(log_file, lux, proximity);
            print_data(lux, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(100000); // 100 ms
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

