#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PROXIMITY_LOG_FILE "proximity_log.txt"
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int read_proximity();
int log_data(int proximity);
void signal_handler(int signal);

// Structure for sensor configuration (optional)
typedef struct {
    unsigned char hw_key;
    unsigned char meas_rate;
    unsigned char interrupt_config;
    unsigned char als_vis_ir_adc_counter;
    unsigned char als_vis_adc_gain;
    unsigned char ps_adc_counter;
    unsigned char ps_led21;
    unsigned char ps_led3;
    unsigned char ps_adc_misc;
    unsigned char ps_adc_gain;
    unsigned char command;
} si1145_config_t;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1145 sensor
int si1145_init() {
    int retries = 0;
    int status;

    // Hardware Key
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, 0x07, 0x03);
        if (status == 0) break; // Success
        fprintf(log_file, "%s", "Error writing to HW_KEY register. Retrying...\n");
        fflush(log_file);
        gpioDelay(1000); // Wait 1ms before retrying
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(log_file, "%s", "Failed to write to HW_KEY register after multiple retries.\n");
        fflush(log_file);
        return -1;
    }

    // MEAS_RATE
    retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, 0x06, 0x02);
        if (status == 0) break; // Success
        fprintf(log_file, "%s", "Error writing to MEAS_RATE register. Retrying...\n");
        fflush(log_file);
        gpioDelay(1000); // Wait 1ms before retrying
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(log_file, "%s", "Failed to write to MEAS_RATE register after multiple retries.\n");
        fflush(log_file);
        return -1;
    }

    // Interrupt Config
    retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, 0x1A, 0x00);
        if (status == 0) break; // Success
        fprintf(log_file, "%s", "Error writing to INTERRUPT_CONFIG register. Retrying...\n");
        fflush(log_file);
        gpioDelay(1000); // Wait 1ms before retrying
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(log_file, "%s", "Failed to write to INTERRUPT_CONFIG register after multiple retries.\n");
        fflush(log_file);
        return -1;
    }

    // ALS_VIS_IR_ADC_COUNTER
    retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, 0x21, 0x0B);
        if (status == 0) break; // Success
