        falling_edge_time = tick;
        echo_valid = 1; // Pulse is valid if both edges are detected
    }
}

// Function to calculate distance in centimeters
float calculate_distance(uint32_t pulse_width) {
    return (float)pulse_width * 0.0343 / 2.0;
}

// Function to control the buzzer
void control_buzzer(float distance) {
    if (distance < 20.0) {
        gpioWrite(BUZZER_PIN, 1); // Activate buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Deactivate buzzer
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    // Set alert function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        trigger_pulse();

        // Wait for a valid echo pulse
        int timeout_count = 0;
        while (!echo_valid && timeout_count < 100) {
            gpioDelay(1000); // Wait 1 ms
            timeout_count++;
        }

        if (echo_valid) {
            uint32_t pulse_width = falling_edge_time - rising_edge_time;
            float distance = calculate_distance(pulse_width);
            printf("Distance: %.2f cm\n", distance);
            control_buzzer(distance);
        } else {
            fprintf(stderr, "Timeout waiting for echo pulse\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    return 0;
}

