// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000        // 50ms timeout for echo pulse
#define MAX_DISTANCE 400.0     // Maximum measurable distance (cm)
#define MIN_DISTANCE 20.0      // Minimum measurable distance (cm)

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
float measure_distance();
void set_servo_angle(float distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
        gpioServo(SERVO_PIN, 0); // Stop the servo
        gpioTerminate();         // Terminate pigpio
        exit(0);
    }
}

// Function to measure distance using the HC-SR04 sensor
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for the echo pulse to start
    long long timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - timeout_start > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pulse timeout (start)\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    // Wait for the echo pulse to end
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - timeout_start > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pulse timeout (end)\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    // Calculate the pulse duration
    diff_tick = end_tick - start_tick;

    // Calculate the distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 for one-way distance

    return distance;
}

// Function to set the servo angle based on the distance
void set_servo_angle(float distance) {
    // Map distance to servo pulse width (microseconds)
    // 0 degrees: 500 us, 90 degrees: 1500 us, 180 degrees: 2500 us
    // distance: 200 cm -> 500 us, 110 cm -> 1500 us, 20 cm -> 2500 us

    float pulse_width;

    if (distance >= 20.0 && distance <= 200.0) {
        pulse_width = 500.0 + (1500.0 - 500.0) * (distance - 20.0) / (200.0 - 20.0);
    } else if (distance < 20.0) {
        pulse_width = 2500.0;
    } else {
        pulse_width = 500.0;
    }

    // Set the servo pulse width
    gpioServo(SERVO_PIN, (int)pulse_width);
}

