#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_GPIO 18
#define DISTANCE_THRESHOLD_OPEN 200 // mm
#define DISTANCE_THRESHOLD_CLOSE 250 // mm
#define SERVO_CLOSED_PULSEWIDTH 1000 // us
#define SERVO_OPEN_PULSEWIDTH 2000  // us
#define SERVO_RANGE 1000
#define SERVO_NEUTRAL 500
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void control_servo(int distance);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    int status;
    unsigned char model_id;

    // Check model ID
    status = i2cReadByteData(i2c_handle, 0x010F);
    if (status < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", status);
        return -1;
    }
    model_id = (unsigned char)status;

    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Set timing budget to 20ms
    status = i2cWriteByteData(i2c_handle, 0x001D, 0x0A); // timing_budget_ms = 20
    if (status < 0) {
        fprintf(stderr, "Error setting timing budget: %d\n", status);
        return -1;
    }

    // Start ranging
    status = i2cWriteByteData(i2c_handle, 0x0008, 0x01); // VL53L1X_REG_START_STOP_CONTROL
    if (status < 0) {
        fprintf(stderr, "Error starting ranging: %d\n", status);
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    int status;
    unsigned char data[2];

    status = i2cReadI2CBlockData(i2c_handle, 0x0089, (char *)data, 2); // VL53L1X_REG_RESULT_RANGE_STATUS
    if (status < 0) {
        fprintf(stderr, "Error reading distance: %d\n", status);
        return -1;
    }

    *distance = (data[0] << 8) | data[1];
    return 0;
}

// Control servo motor
void control_servo(int distance) {
    int pulsewidth;

    if (distance < DISTANCE_THRESHOLD_OPEN) {
        pulsewidth = SERVO_OPEN_PULSEWIDTH;
        log_event("Gate Open");
    } else if (distance > DISTANCE_THRESHOLD_CLOSE) {
        pulsewidth = SERVO_CLOSED_PULSEWIDTH;
        log_event("Gate Closed");
    } else {
        // Smooth transition
        pulsewidth = SERVO_OPEN_PULSEWIDTH - (int)(((float)(distance - DISTANCE_THRESHOLD_OPEN) / (DISTANCE_THRESHOLD_CLOSE - DISTANCE_THRESHOLD_OPEN)) * (SERVO_OPEN_PULSEWIDTH - SERVO_CLOSED_PULSEWIDTH));
    }

    gpioServo(SERVO_GPIO, pulsewidth);
}

// Log event to file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

int main() {
    int distance;
    int init_result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    init_result = init_vl53l1x();
    if (init_result != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set servo GPIO as output
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioSetPWMrange(SERVO_GPIO, SERVO_RANGE);
    gpioSetPWMfrequency(SERVO_GPIO, 50); // 50 Hz

    // Set initial servo position
    gpioServo(SERVO_GPIO, SERVO_NEUTRAL);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            control_servo(distance);
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    gpioServo(SERVO_GPIO, 0); // Stop PWM
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

