#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50 ms timeout
#define MIN_DISTANCE 20.0      // cm
#define MAX_DISTANCE 200.0     // cm
#define MIN_ANGLE 0.0          // degrees
#define MAX_ANGLE 180.0        // degrees
#define MIN_PULSE_WIDTH 500.0  // us
#define MAX_PULSE_WIDTH 2500.0 // us

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, long timeout);
float calculateDistance(long pulse_duration);
float mapDistanceToAngle(float distance);
void setServoAngle(float angle);
void signalHandler(int signal);

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Stopping servo and exiting.\n");
        program_running = 0;
        setServoAngle(0.0); // Stop the servo
        gpioTerminate();     // Terminate pigpio
        exit(0);
    }
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration with timeout
long pulseIn(int pin, int level, long timeout) {
    long start_time = gpioTick();
    long current_time;

    // Wait for the rising edge
    while (gpioRead(pin) != level) {
        current_time = gpioTick();
        if (current_time - start_time > timeout) {
            return -1; // Timeout
        }
    }

    long pulse_start = gpioTick();

    // Wait for the falling edge
    while (gpioRead(pin) == level) {
        current_time = gpioTick();
        if (current_time - start_time > timeout) {
            return -1; // Timeout
        }
    }

    long pulse_end = gpioTick();
    return pulse_end - pulse_start;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_duration) {
    if (pulse_duration < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_duration * 0.0343 / 2.0;
}

// Function to map the distance to an angle between 0 and 180 degrees
float mapDistanceToAngle(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE;
    }
}

// Function to set the servo angle
void setServoAngle(float angle) {
    if (angle < MIN_ANGLE) {
        angle = MIN_ANGLE;
    } else if (angle > MAX_ANGLE) {
        angle = MAX_ANGLE;
    }

    float pulse_width = MIN_PULSE_WIDTH + (angle / MAX_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH);
    gpioServo(SERVO_PIN, (int)pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

