#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x40

// Define the registers
#define CONFIG_REGISTER 0x03
#define TEMPERATURE_REGISTER 0x01
#define HUMIDITY_REGISTER 0x02

// Global variable for the I2C handle
int i2c_handle = -1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to write a byte to the I2C device
int write_byte(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read a word from the I2C device
int read_word(int handle, int reg, unsigned int *value) {
    int result = i2cReadWordData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    *value = (unsigned int)result;
    return 0;
}

// Function to configure the Si7005 sensor
int configure_sensor(int handle) {
    if (write_byte(handle, CONFIG_REGISTER, 0x00) != 0) {
        return -1;
    }
    gpioDelay(10); // Wait 10 ms
    return 0;
}

// Function to read the temperature from the sensor
int read_temperature(int handle, float *temperature) {
    unsigned int raw_temperature;
    if (read_word(handle, TEMPERATURE_REGISTER, &raw_temperature) != 0) {
        return -1;
    }
    *temperature = (175.72 * raw_temperature) / 65536.0 - 46.85;
    return 0;
}

// Function to read the humidity from the sensor
int read_humidity(int handle, float *humidity) {
    unsigned int raw_humidity;
    if (read_word(handle, HUMIDITY_REGISTER, &raw_humidity) != 0) {
        return -1;
    }
    *humidity = (125.0 * raw_humidity) / 65536.0 - 6.0;
    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Error configuring sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        float temperature, humidity;

        // Read the temperature
        if (read_temperature(i2c_handle, &temperature) != 0) {
            fprintf(stderr, "Error reading temperature\n");
        } else {
            // Read the humidity
            if (read_humidity(i2c_handle, &humidity) != 0) {
                fprintf(stderr, "Error reading humidity\n");
            } else {
                // Print the temperature and humidity
                printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
            }
        }

        // Wait for 2 seconds
        gpioDelay(2000);
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

