// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_HIGH_REP 0x2C06
#define SAMPLE_INTERVAL 5 // seconds
#define ERROR_LOG_FILE "error_log.txt"
#define TEMP_LOG_FILE "enclosure_temp_log.txt"

// Global variables
int i2c_handle;
FILE *temp_log_file = NULL;
FILE *error_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_temperature();
void log_temperature(float temperature);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data (optional, but good practice)
typedef struct {
    float temperature;
    time_t timestamp;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from the STS30-DIS sensor
float read_temperature() {
    char cmd[2] = {(MEASURE_HIGH_REP >> 8) & 0xFF, MEASURE_HIGH_REP & 0xFF};
    char buf[3];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Error writing to I2C device");
        return -1000.0; // Indicate error
    }

    gpioDelay(20); // Wait for measurement (datasheet specifies 12.1ms for high repeatability)

    result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        log_error("Error reading from I2C device");
        return -1000.0; // Indicate error
    }

    int raw_temperature = (buf[0] << 8) | buf[1];
    float temperature = -45.0 + (175.0 * (float)raw_temperature / 65535.0);

    return temperature;
}

// Function to log temperature to a file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (temp_log_file != NULL) {
        fprintf(temp_log_file, "%s, %.2f\n", timestamp, temperature);
        fflush(temp_log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Temperature log file is not open.\n");
    }
}

// Function to log errors to a file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (error_log_file != NULL) {
        fprintf(error_log_file, "%s, ERROR: %s\n", timestamp, message);
        fflush(error_log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Error log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (temp_log_file != NULL) {
        fclose(temp_log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    temp_log_file = fopen(TEMP_LOG_FILE, "a");
    if (temp_log_file == NULL) {
        fprintf(stderr, "Error opening temperature log file!\n");
        gpioTerminate();
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Error opening error log file!\n");
        fclose(temp_log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        log_error("I2C initialization failed");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
        } else {
            log_error("Failed to read temperature");
        }
        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

