// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, unsigned char command1, unsigned char command2);
int read_data(int handle, char *buffer, int count);
int validate_crc(const char *data, int count);
sensor_data_t convert_data(const char *buffer);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// CRC-8 checksum calculation
unsigned char crc8(const char *data, int count) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < count; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the SDP810 sensor
int send_command(int handle, unsigned char command1, unsigned char command2) {
    char buf[2];
    buf[0] = command1;
    buf[1] = command2;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error sending command: %d\n", result);
        return -1;
    }
    return 0;
}

