    if (send_command(i2c_handle, MEASUREMENT_COMMAND_1, MEASUREMENT_COMMAND_2) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char buffer[9];
        // Read data
        if (read_data(i2c_handle, buffer, 9) == 0) {
            // Validate CRC
            if (validate_crc(buffer, 3) == 0 && validate_crc(buffer + 3, 3) == 0 && validate_crc(buffer + 6, 3) == 0) {
                // Convert data
                sensor_data_t sensor_data = convert_data(buffer);

