#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// SHT40 measurement command (high repeatability)
#define SHT40_MEASURE_CMD 0xFD

// CRC polynomial
#define CRC_POLY 0x31

// Global variables for I2C file descriptor and log file pointer
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_open(const char *device);
int i2c_write(int fd, uint8_t data);
int i2c_read(int fd, uint8_t *data, int len);
int sht40_measure(int fd);
int sht40_read_data(int fd, uint8_t *data);
int sht40_validate_data(const uint8_t *data);
float sht40_convert_temperature(uint16_t raw_temp);
float sht40_convert_humidity(uint16_t raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// I2C open function
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, uint8_t data) {
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// SHT40 measurement function
int sht40_measure(int fd) {
    if (i2c_write(fd, SHT40_MEASURE_CMD) < 0) {
        fprintf(stderr, "Error sending measurement command\n");
        return -1;
    }
    usleep(10000); // Wait 10 ms for measurement
    return 0;
}

// SHT40 read data function
int sht40_read_data(int fd, uint8_t *data) {
    if (i2c_read(fd, data, 6) < 0) {
        fprintf(stderr, "Error reading data from SHT40\n");
        return -1;
    }
    return 0;
}

// SHT40 validate data function
int sht40_validate_data(const uint8_t *data) {
    // CRC validation for temperature
    uint8_t temp_data[2] = {data[0], data[1]};
    uint8_t temp_crc = data[2];
    uint8_t temp_crc_calculated = 0xFF;

    for (int i = 0; i < 2; i++) {
        temp_crc_calculated ^= temp_data[i];
        for (int j = 0; j < 8; j++) {
            if (temp_crc_calculated & 0x80) {
                temp_crc_calculated = (temp_crc_calculated << 1) ^ CRC_POLY;
            } else {
                temp_crc_calculated = (temp_crc_calculated << 1);
            }
        }
    }

    if (temp_crc != temp_crc_calculated) {
        fprintf(stderr, "Temperature CRC validation failed\n");
        return -1;
    }

    // CRC validation for humidity
    uint8_t humidity_data[2] = {data[3], data[4]};
    uint8_t humidity_crc = data[5];
    uint8_t humidity_crc_calculated = 0xFF;

    for (int i = 0; i < 2; i++) {
        humidity_crc_calculated ^= humidity_data[i];
        for (int j = 0; j < 8; j++) {
            if (humidity_crc_calculated & 0x80) {
                humidity_crc_calculated = (humidity_crc_calculated << 1) ^ CRC_POLY;
            } else {
                humidity_crc_calculated = (humidity_crc_calculated << 1);
            }
        }
    }

    if (humidity_crc != humidity_crc_calculated) {
        fprintf(stderr, "Humidity CRC validation failed\n");
        return -1;
    }

    return 0;
}

// SHT40 convert temperature function
float sht40_convert_temperature(uint16_t raw_temp) {
    return -45.0 + 175.0 * (float)raw_temp / 65535.0;
}

// SHT40 convert humidity function
float sht40_convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Log data function
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (t == NULL) {
        perror("Error getting local time");
        return -1;
    }

    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen("sht40_log.txt", "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open("/dev/i2c-1");
    if (i2c_fd < 0) {
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    uint8_t data[6];
    uint16_t raw_temp, raw_humidity;
    float temperature, humidity;

    while (1) {
        // Measure temperature and humidity
        if (sht40_measure(i2c_fd) < 0) {
            fprintf(stderr, "Error measuring temperature and humidity, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Read data from SHT40
        if (sht40_read_data(i2c_fd, data) < 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Validate data
        if (sht40_validate_data(data) < 0) {
            fprintf(stderr, "Error validating data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert raw data to temperature and humidity
        raw_temp = (data[0] << 8) | data[1];
        raw_humidity = (data[3] << 8) | data[4];

        temperature = sht40_convert_temperature(raw_temp);
        humidity = sht40_convert_humidity(raw_humidity);

        // Log data
        if (log_data(temperature, humidity) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        sleep(5); // Wait 5 seconds
    }

    return 0;
}

