    return 100.0 * (float)raw_humidity / 65535.0;
}

// Log data function
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (t == NULL) {
        perror("Error getting local time");
        return -1;
    }

    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen("sht40_log.txt", "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open("/dev/i2c-1");
    if (i2c_fd < 0) {
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    uint8_t data[6];
    uint16_t raw_temp, raw_humidity;
    float temperature, humidity;

    while (1) {
        // Measure temperature and humidity
        if (sht40_measure(i2c_fd) < 0) {
            fprintf(stderr, "Error measuring temperature and humidity, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Read data from SHT40
        if (sht40_read_data(i2c_fd, data) < 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Validate data
        if (sht40_validate_data(data) < 0) {
            fprintf(stderr, "Error validating data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert raw data to temperature and humidity
        raw_temp = (data[0] << 8) | data[1];
        raw_humidity = (data[3] << 8) | data[4];

        temperature = sht40_convert_temperature(raw_temp);
        humidity = sht40_convert_humidity(raw_humidity);

        // Log data
        if (log_data(temperature, humidity) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        sleep(5); // Wait 5 seconds
    }

    return 0;
}

