        while (retry_count < 3) {
            if (send_command(i2c_handle, SDP31_MEASURE_CMD_1, SDP31_MEASURE_CMD_2) == 0) {
                break;
            } else {
                fprintf(stderr, "Retrying I2C write... (%d/3)\n", retry_count + 1);
                gpioDelay(1000 * (1 << retry_count)); // Exponential backoff (1ms, 2ms, 4ms)
                retry_count++;
            }
        }
        if (retry_count == 3) {
            fprintf(stderr, "Failed to send command after 3 retries. Exiting.\n");
            cleanup();
            return 1;
        }

        gpioDelay(1000); // Wait 1 ms

        retry_count = 0;
        while (retry_count < 3) {
            if (read_data(i2c_handle, data, 6) == 0) {
                break;
            } else {
                fprintf(stderr, "Retrying I2C read... (%d/3)\n", retry_count + 1);
                gpioDelay(1000 * (1 << retry_count)); // Exponential backoff
                retry_count++;
            }
        }
        if (retry_count == 3) {
            fprintf(stderr, "Failed to read data after 3 retries. Exiting.\n");
            cleanup();
            return 1;
        }

        sensor_data = process_data(data);
        log_data(sensor_data);

        gpioDelay(100000); // Sample every 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

