#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define TEMPERATURE_COMMAND 0xF3
#define HUMIDITY_COMMAND 0xF5
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int i2c_handle, int command, float *value);
float convert_temperature(unsigned int raw_temperature);
float convert_humidity(unsigned int raw_humidity);
int log_data(FILE *log_file, float temperature, float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        terminate = 1;
    }
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, int command, float *value) {
    int retries = 0;
    int result;
    unsigned int raw_data;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, command);
        if (result != 0) {
            fprintf(stderr, "Error writing command 0x%02X: %s\n", command, strerror(errno));
            retries++;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        gpioDelay(20000); // Wait for measurement (20ms)

        raw_data = i2cReadWordData(i2c_handle, 0); // Read two bytes
        if (raw_data >= 0) {
            *value = (float)raw_data;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading data: %s\n", strerror(errno));
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to convert raw temperature to Celsius
float convert_temperature(unsigned int raw_temperature) {
    return (175.72 * raw_temperature / 65536.0) - 46.85;
}

// Function to convert raw humidity to %RH
float convert_humidity(unsigned int raw_humidity) {
    float humidity = (125.0 * raw_humidity / 65536.0) - 6.0;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

// Function to log data to file
int log_data(FILE *log_file, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    float temperature, humidity;
    int result;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", pigpio_error(gpioInitialise()));
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting sensor data logging...\n");

    while (!terminate) {
        // Read temperature
        if (read_sensor_data(i2c_handle, TEMPERATURE_COMMAND, &temperature) != 0) {
            fprintf(stderr, "Error reading temperature.\n");
        } else {
            temperature = convert_temperature((unsigned int)temperature);
        }

        // Read humidity
        if (read_sensor_data(i2c_handle, HUMIDITY_COMMAND, &humidity) != 0) {
            fprintf(stderr, "Error reading humidity.\n");
        } else {
            humidity = convert_humidity((unsigned int)humidity);
        }

        // Log data
        if (log_data(log_file, temperature, humidity) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Print to console
        printf("Temperature: %.2f C, Humidity: %.2f %%RH\n", temperature, humidity);

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Delay for 5 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

