// Function to calculate CRC8 checksum
unsigned char crc8(const unsigned char *data, int length) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to open the I2C bus
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to write data to the I2C bus
int i2c_write(int fd, int addr, unsigned char *data, int length) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    if (write(fd, data, length) != length) {
        perror("Error writing to I2C bus");
        return -1;
    }
    return 0;
}

// Function to read data from the I2C bus
int i2c_read(int fd, int addr, unsigned char *data, int length) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    if (read(fd, data, length) != length) {
        perror("Error reading from I2C bus");
        return -1;
    }
    return 0;
}

