    // Validate CRC for each word
    if (!validate_crc(data, 3) || !validate_crc(data + 3, 3) || !validate_crc(data + 6, 3)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Extract raw values
    *pressure = (data[0] << 8) | data[1];
    *temperature = (data[3] << 8) | data[4];
    *scale_factor = (data[6] << 8) | data[7];

    return 0;
}

