#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASUREMENT_COMMAND 0x2C06
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(const uint8_t *data, int count);
float convert_to_celsius(uint16_t raw_value);
int log_temperature(float temperature);
int log_error(const char *message);
void signal_handler(int signal);

// CRC-8 checksum calculation
uint8_t calculate_crc(const uint8_t *data, int count) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < count; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        log_error("Failed to write command to I2C device");
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        log_error("Failed to read data from I2C device");
        return -1;
    }
    return 0;
}

// Function to convert raw temperature data to Celsius
float convert_to_celsius(uint16_t raw_value) {
    return -45.0 + 175.0 * (float)raw_value / 65535.0;
}

// Function to log temperature readings to a file
int log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        log_error("Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

// Function to log errors to a file
int log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s, ERROR: %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, MEASUREMENT_COMMAND) != 0) {
            log_error("Failed to send measurement command");
            break;
        }

        // Wait for conversion (at least 15 ms)
        gpioDelay(15000); // 15 ms

        // Read data
        uint8_t data[3];
        if (read_data(i2c_handle, data, 3) != 0) {
            log_error("Failed to read data");
            break;
        }

        // Validate CRC
        uint8_t crc = calculate_crc(data, 2);
        if (crc != data[2]) {
            log_error("CRC mismatch");
            continue; // Skip to the next iteration
        }

        // Convert to temperature
        uint16_t raw_temperature = (data[0] << 8) | data[1];
        float temperature = convert_to_celsius(raw_temperature);

        // Log temperature
        if (log_temperature(temperature) != 0) {
            log_error("Failed to log temperature");
        }

        printf("Temperature: %.2f °C\n", temperature);

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");

    return 0;
}

