#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <stdbool.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define PRESSURE_SCALE_FACTOR 240.0
#define TEMPERATURE_SCALE_FACTOR 200.0
#define TEMPERATURE_OFFSET -45.0
#define LOG_FILE "airflow_data.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
bool running = true;

// Function prototypes
int i2c_setup(const char *bus, int addr);
int i2c_write_command(int fd, unsigned int command);
int i2c_read_data(int fd, unsigned char *data, int len);
bool validate_crc(const unsigned char *data, int len);
float convert_pressure(int raw_pressure);
float convert_temperature(int raw_temperature);
char *get_timestamp();
int log_data(const char *timestamp, float pressure, float temperature);
void signal_handler(int signal);

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C setup function
int i2c_setup(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write command function
int i2c_write_command(int fd, unsigned int command) {
    unsigned char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read data function
int i2c_read_data(int fd, unsigned char *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// CRC validation function
bool validate_crc(const unsigned char *data, int len) {
    for (int i = 0; i < len - 1; i += 3) {
        unsigned char crc = crc8(data + i, 2);
        if (crc != data[i + 2]) {
            fprintf(stderr, "CRC validation failed for data[%d:%d]\n", i, i + 2);
            return false;
        }
    }
    return true;
}

// Pressure conversion function
float convert_pressure(int raw_pressure) {
    return (float)raw_pressure / PRESSURE_SCALE_FACTOR;
}

// Temperature conversion function
float convert_temperature(int raw_temperature) {
    return (float)raw_temperature / TEMPERATURE_SCALE_FACTOR + TEMPERATURE_OFFSET;
}

// Timestamp generation function
char *get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char *)malloc(20 * sizeof(char)); // Allocate memory for timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Data logging function
int log_data(const char *timestamp, float pressure, float temperature) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = false;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, SDP800_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C setup failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Send continuous measurement command
        if (i2c_write_command(i2c_fd, CONTINUOUS_MEASUREMENT_CMD) < 0) {
            fprintf(stderr, "Failed to send measurement command. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for at least 1 ms
        usleep(1000); // 1 ms

        // Read data
        unsigned char data[6];
        if (i2c_read_data(i2c_fd, data, 6) < 0) {
            fprintf(stderr, "Failed to read data. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Validate CRC
        if (!validate_crc(data, 6)) {
            fprintf(stderr, "CRC validation failed. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert raw data
        int raw_pressure = (data[0] << 8) | data[1];
        int raw_temperature = (data[3] << 8) | data[4];
        float pressure = convert_pressure(raw_pressure);
        float temperature = convert_temperature(raw_temperature);

        // Get timestamp
        char *timestamp = get_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Log data
        if (log_data(timestamp, pressure, temperature) < 0) {
            fprintf(stderr, "Failed to log data. Retrying.\n");
            free(timestamp);
            sleep(1); // Wait before retrying
            continue;
        }

        free(timestamp);

        // Print data to console
        printf("Timestamp: %s, Pressure: %.2f Pa, Temperature: %.2f °C\n", timestamp, pressure, temperature);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    close(i2c_fd);
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

