#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60
#define MAX_RETRIES 3

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} Reading;

// Circular buffer
Reading readings[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int handle, unsigned char command, unsigned short *raw_value);
float convert_temperature(unsigned short raw_value);
float convert_humidity(unsigned short raw_value);
void control_fan(float temperature);
void log_reading(float temperature, float humidity);
void print_buffer();
void signal_handler(int signal);

// Function to read data from the Si7021 sensor
int read_sensor(int handle, unsigned char command, unsigned short *raw_value) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(handle, command);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %d\n", result);
            retries++;
            gpioDelay(10000); // 10 ms delay
            continue;
        }

        gpioDelay(10000); // 10 ms delay

        result = i2cReadWordData(handle, command);
        if (result >= 0) {
            *raw_value = (unsigned short)result;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C: %d\n", result);
            retries++;
            gpioDelay(10000); // 10 ms delay
        }
    }

    fprintf(stderr, "Failed to read sensor after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to convert raw temperature data to Celsius
float convert_temperature(unsigned short raw_value) {
    return 175.72 * raw_value / 65536.0 - 46.85;
}

// Function to convert raw humidity data to percentage RH
float convert_humidity(unsigned short raw_value) {
    return 125.0 * raw_value / 65536.0 - 6.0;
}

// Function to control the cooling fan
void control_fan(float temperature) {
    static int fan_on = 0;

    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
        fan_on = 1;
        printf("Fan ON (Temperature: %.2f°C)\n", temperature);
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
        fan_on = 0;
        printf("Fan OFF (Temperature: %.2f°C)\n", temperature);
    }
}

// Function to log the sensor readings to the circular buffer
void log_reading(float temperature, float humidity) {
    time_t now = time(NULL);
    readings[buffer_index].timestamp = now;
    readings[buffer_index].temperature = temperature;
    readings[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Readings ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        time_t timestamp = readings[i].timestamp;
        struct tm *timeinfo = localtime(&timestamp);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("[%s] Temperature: %.2f°C, Humidity: %.2f%%\n", time_str, readings[i].temperature, readings[i].humidity);
    }
    printf("-----------------------\n\n");
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    program_running = 0;
    gpioWrite(FAN_GPIO, 0); // Turn off the fan
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is initially off

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Starting sensor readings...\n");

    while (program_running) {
        unsigned short raw_temperature, raw_humidity;
        float temperature, humidity;

        // Read temperature
        if (read_sensor(i2c_handle, 0xE3, &raw_temperature) == 0) {
            temperature = convert_temperature(raw_temperature);
        } else {
            temperature = -999.0; // Indicate error
        }

        // Read humidity
        if (read_sensor(i2c_handle, 0xE5, &raw_humidity) == 0) {
            humidity = convert_humidity(raw_humidity);
        } else {
            humidity = -999.0; // Indicate error
        }

        // Log the reading
        log_reading(temperature, humidity);

        // Control the fan
        control_fan(temperature);

        // Print the buffer (for debugging)
        print_buffer();

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(FAN_GPIO, 0); // Turn off the fan
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

