#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define START_PERIODIC_MEASUREMENT 0x21B1
#define STOP_PERIODIC_MEASUREMENT 0x3F86
#define READ_MEASUREMENT 0xEC05
#define DATA_READY 0xE4B8

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_device();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
int read_sensor_data(int handle, sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
uint8_t crc8(const uint8_t *data, int len);

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device() {
    int handle = i2cOpen(1, SCD40_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Send command to SCD40
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = command >> 8;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read data from SCD40
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data (CO2, temperature, humidity)
int read_sensor_data(int handle, sensor_data_t *data) {
    uint8_t raw_data[9];
    uint16_t co2_raw, temp_raw, humidity_raw;

    // Check data ready flag
    if (send_command(handle, DATA_READY) != 0) {
        fprintf(stderr, "Failed to send data ready command\n");
        return -1;
    }
    gpioDelay(1); // Small delay after sending the command

    uint8_t ready_data[3];
    if (read_data(handle, ready_data, 3) != 0) {
        fprintf(stderr, "Failed to read data ready status\n");
        return -1;
    }

    uint16_t ready_status = (ready_data[0] << 8) | ready_data[1];
    if ((ready_status & 0x0008) == 0) {
        fprintf(stderr, "Data not ready\n");
        return -1;
    }

    // Read measurement data
    if (send_command(handle, READ_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to send read measurement command\n");
        return -1;
    }
    gpioDelay(1); // Small delay after sending the command

    if (read_data(handle, raw_data, 9) != 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    // CRC check
    for (int i = 0; i < 3; i++) {
        uint8_t crc = crc8(&raw_data[i * 3], 2);
        if (crc != raw_data[i * 3 + 2]) {
            fprintf(stderr, "CRC check failed for byte %d\n", i);
            return -1;
        }
    }

    // Convert raw data to CO2, temperature, and humidity
    co2_raw = (raw_data[0] << 8) | raw_data[1];
    temp_raw = (raw_data[3] << 8) | raw_data[4];
    humidity_raw = (raw_data[6] << 8) | raw_data[7];

    data->co2 = (float)co2_raw;
    data->temperature = -45.0 + 175.0 * ((float)temp_raw / 65535.0);
    data->humidity = 100.0 * ((float)humidity_raw / 65535.0);

    return 0;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c_device();
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (send_command(i2c_handle, START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000); // Wait 1 second after starting measurement

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(5); // Wait 5 seconds
    }

    // Stop periodic measurement
    if (send_command(i2c_handle, STOP_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    // Close I2C device and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

