#define STOP_PERIODIC_MEASUREMENT 0x3F86
#define GET_DATA_READY_STATUS 0xE4B8
#define READ_MEASUREMENT 0xEC05

// GPIO pin for LED
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 20

// Structure to hold sensor data
typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer
sensor_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Function prototypes
int start_periodic_measurement();
int get_data_ready_status();
int read_measurement(uint16_t *co2, float *temperature, float *humidity);
int stop_periodic_measurement();
uint8_t crc8(const uint8_t *data, int len);
void add_to_buffer(sensor_data_t data);
void print_buffer();
void signal_handler(int signal);

// Function to start periodic measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing start periodic measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to get data ready status
int get_data_ready_status() {
    char buf[2];
    buf[0] = (GET_DATA_READY_STATUS >> 8) & 0xFF;
    buf[1] = GET_DATA_READY_STATUS & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing get data ready status command: %d\n", result);
        return -1;
    }

    char read_buf[3];
    result = i2cReadDevice(i2c_handle, read_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading get data ready status: %d\n", result);
        return -1;
    }

    uint16_t status = (read_buf[0] << 8) | read_buf[1];
    return (status & 0x0001);
}

// Function to read measurement
int read_measurement(uint16_t *co2, float *temperature, float *humidity) {
    char buf[2];
    buf[0] = (READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = READ_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing read measurement command: %d\n", result);
        return -1;
    }

    char read_buf[9];
    result = i2cReadDevice(i2c_handle, read_buf, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading read measurement: %d\n", result);
        return -1;
    }

    // CRC validation
    if (crc8(read_buf, 2) != read_buf[2]) {
        fprintf(stderr, "CRC error for CO2\n");
        return -1;
    }
    if (crc8(read_buf + 3, 2) != read_buf[5]) {
        fprintf(stderr, "CRC error for Temperature\n");
        return -1;
    }
    if (crc8(read_buf + 6, 2) != read_buf[8]) {
        fprintf(stderr, "CRC error for Humidity\n");
        return -1;
    }

    // Convert data
    *co2 = (read_buf[0] << 8) | read_buf[1];
    uint16_t temp_raw = (read_buf[3] << 8) | read_buf[4];
    uint16_t humidity_raw = (read_buf[6] << 8) | read_buf[7];

    *temperature = -45 + 175 * (float)temp_raw / 65535.0;
    *humidity = 100 * (float)humidity_raw / 65535.0;

    return 0;
}

