#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 4
#define TIMEOUT_US 50000 // 50 ms
#define SAMPLE_INTERVAL_S 5

static volatile int running = 1;
static int failure_count = 0;
static FILE *log_file = NULL;

// Function to get current timestamp in ISO-8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log data to file
void log_data(const char *timestamp, float temperature) {
    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to log errors to file
void log_error(const char *timestamp, const char *message) {
    if (log_file != NULL) {
        fprintf(log_file, "%s,ERROR,%s\n", timestamp, message);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to read temperature from TMP05 sensor
float read_temperature() {
    int high_start, high_end, total_end;
    unsigned int high_duration, total_duration;
    unsigned int start_time, current_time;

    // Wait for the start of the cycle (falling edge)
    start_time = gpioTick();
    while (gpioRead(GPIO_PIN) == 1) {
        current_time = gpioTick();
        if (current_time - start_time > TIMEOUT_US) {
            return -999.0; // Timeout error
        }
    }

    high_start = gpioTick();

    // Wait for the rising edge (end of high time)
    start_time = gpioTick();
    while (gpioRead(GPIO_PIN) == 0) {
        current_time = gpioTick();
        if (current_time - start_time > TIMEOUT_US) {
            return -999.0; // Timeout error
        }
    }

    high_end = gpioTick();

    // Wait for the falling edge (end of total cycle)
    start_time = gpioTick();
    while (gpioRead(GPIO_PIN) == 1) {
        current_time = gpioTick();
        if (current_time - start_time > TIMEOUT_US) {
            return -999.0; // Timeout error
        }
    }

    total_end = gpioTick();

    high_duration = high_end - high_start;
    total_duration = total_end - high_start;

    if (total_duration == 0) {
        return -999.0; // Avoid division by zero
    }

    float temperature = 4215.0 - (2143.0 * (float)high_duration / (float)total_duration);
    return temperature;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    int init_result;
    char *timestamp;
    float temperature;

    // Initialize pigpio
    init_result = gpioInitialise();
    if (init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", init_result);
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open log file in append mode
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open temperature_log.txt");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, skipping this sample.\n");
            gpioDelay(SAMPLE_INTERVAL_S * 1000000); // Sleep for sample interval
            continue;
        }

        temperature = read_temperature();

        if (temperature == -999.0) {
            log_error(timestamp, "Sensor read timeout or division by zero.");
            failure_count++;
        } else if (temperature < -40.0 || temperature > 150.0) {
            log_error(timestamp, "Temperature out of range.");
            failure_count++;
        } else {
            log_data(timestamp, temperature);
            failure_count = 0; // Reset failure count on successful read
        }

        free(timestamp);

        if (failure_count >= 3) {
            timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                log_error(timestamp, "SENSOR MALFUNCTION");
                free(timestamp);
            }
            running = 0; // Stop the program after 3 consecutive failures
        }

        gpioDelay(SAMPLE_INTERVAL_S * 1000000); // Sleep for sample interval
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

