                        // Simulate offset
                        temperature = simulate_offset(temperature, 2.0, 3600.0, time(NULL));
                        humidity = simulate_offset(humidity, 5.0, 3600.0, time(NULL));

                        // Log data
                        if (log_data(temperature, humidity) != 0) {
                            fprintf(stderr, "Failed to log data\n");
                        }
                        break; // Exit retry loop on success
                    } else {
                        fprintf(stderr, "Humidity CRC validation failed\n");
                    }
                } else {
                    fprintf(stderr, "Temperature CRC validation failed\n");
                }
            } else {
                fprintf(stderr, "Failed to read sensor data, retrying...\n");
            }

            retries++;
            gpioDelay(RETRY_DELAY_SEC * 1000000); // Delay in microseconds
        }

        if (retries == MAX_RETRIES) {
            // Log NaN values
            now = time(NULL);
            utc_tm = gmtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_tm);
            fprintf(log_file, "%s,NaN,NaN\n", timestamp);
            fflush(log_file);
            fprintf(stderr, "Failed to read sensor data after %d retries, logging NaN values\n", MAX_RETRIES);
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

