#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CSV_FILE "airflow.csv"
#define SAMPLE_INTERVAL_MS 1000

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int i2c_setup(int bus, int addr);
int send_command(int fd, uint16_t command);
int read_data(int fd, uint8_t *data, int len);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len, uint8_t checksum);
int read_sensor_data(int fd, sensor_data_t *data);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int sig);

// I2C setup function
int i2c_setup(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// Send command function
int send_command(int fd, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Read data function
int read_data(int fd, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// CRC-8 checksum function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const uint8_t *data, int len, uint8_t checksum) {
    uint8_t calculated_crc = crc8(data, len);
    return (calculated_crc == checksum) ? 0 : -1;
}

// Read sensor data function
int read_sensor_data(int fd, sensor_data_t *data) {
    uint8_t raw_data[9];
    if (read_data(fd, raw_data, 9) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    // Validate CRC for pressure
    if (validate_crc(raw_data, 2, raw_data[2]) < 0) {
        fprintf(stderr, "CRC error for pressure data\n");
        return -1;
    }

    // Validate CRC for temperature
    if (validate_crc(raw_data + 3, 2, raw_data[5]) < 0) {
        fprintf(stderr, "CRC error for temperature data\n");
        return -1;
    }

    // Validate CRC for scale factor
    if (validate_crc(raw_data + 6, 2, raw_data[8]) < 0) {
        fprintf(stderr, "CRC error for scale factor data\n");
        return -1;
    }

    // Convert raw data to pressure and temperature
    int16_t raw_pressure = (raw_data[0] << 8) | raw_data[1];
    int16_t raw_temperature = (raw_data[3] << 8) | raw_data[4];
    int16_t raw_scale_factor = (raw_data[6] << 8) | raw_data[7];

    data->pressure = (float)raw_pressure / (float)raw_scale_factor * 100.0f; // Pressure in Pa
    data->temperature = (float)raw_temperature / 200.0f; // Temperature in °C

    return 0;
}

// Log data to CSV file function
int log_data(FILE *fp, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(fp); // Ensure data is written to file immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, SDP810_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        close(i2c_fd);
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_fd, MEASURE_CMD) < 0) {
            fprintf(stderr, "Error sending measurement command\n");
            break;
        }

        // Wait for conversion
        usleep(45000); // 45 ms

        // Read sensor data
        if (read_sensor_data(i2c_fd, &sensor_data) < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            break;
        }

        // Log data to CSV file
        if (log_data(csv_file, sensor_data) < 0) {
            fprintf(stderr, "Error logging data\n");
            break;
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Cleanup
    close(i2c_fd);
    fclose(csv_file);

    fprintf(stderr, "Program terminated\n");
    return 0;
}

