#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdbool.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define HUMIDITY_CMD 0xF5
#define TEMPERATURE_CMD 0xF3
#define RESET_CMD 0xFE
#define CSV_FILE "environment.log"
#define POLL_DELAY_MS 10
#define TIMEOUT_MS 100

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;

// Function prototypes
int i2c_open(const char *bus, int addr);
int i2c_write(int fd, unsigned char data);
int i2c_read(int fd, unsigned char *data, int len);
bool read_sensor_data(int fd, float *temperature, float *humidity);
bool verify_crc(const unsigned char *data, int len, unsigned char checksum);
void log_data(float temperature, float humidity);
void log_error(const char *message);
void signal_handler(int sig);
void cleanup(int fd);

// CRC-8 calculation (polynomial 0x31, initial value 0x00)
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C open function
int i2c_open(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write function
int i2c_write(int fd, unsigned char data) {
    int result = write(fd, &data, 1);
    if (result != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char *data, int len) {
    int result = read(fd, data, len);
    if (result != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Read sensor data function
bool read_sensor_data(int fd, float *temperature, float *humidity) {
    unsigned char data[3];
    int retries = 5; // Number of retries for each measurement

    // Read humidity
    if (i2c_write(fd, HUMIDITY_CMD) < 0) return false;
    for (int i = 0; i < retries; i++) {
        if (i2c_read(fd, data, 3) == 0) break;
        usleep(POLL_DELAY_MS * 1000); // Delay in microseconds
    }
    if (i2c_read(fd, data, 3) < 0) {
        log_error("Failed to read humidity data");
        return false;
    }
    if (!verify_crc(data, 2, data[2])) {
        log_error("Humidity CRC check failed");
        return false;
    }
    unsigned int humidity_raw = (data[0] << 8) | data[1];
    *humidity = 125.0 * humidity_raw / 65536.0 - 6.0;

    // Read temperature
    if (i2c_write(fd, TEMPERATURE_CMD) < 0) return false;
    for (int i = 0; i < retries; i++) {
        if (i2c_read(fd, data, 3) == 0) break;
        usleep(POLL_DELAY_MS * 1000); // Delay in microseconds
    }
    if (i2c_read(fd, data, 3) < 0) {
        log_error("Failed to read temperature data");
        return false;
    }
    if (!verify_crc(data, 2, data[2])) {
        log_error("Temperature CRC check failed");
        return false;
    }
    unsigned int temperature_raw = (data[0] << 8) | data[1];
    *temperature = 175.72 * temperature_raw / 65536.0 - 46.85;

    return true;
}

// CRC verification function
bool verify_crc(const unsigned char *data, int len, unsigned char checksum) {
    unsigned char calculated_crc = crc8(data, len);
    return (calculated_crc == checksum);
}

// Log data function
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        perror("Error opening CSV file");
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
}

// Log error function
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        perror("Error opening CSV file");
        return;
    }

    fprintf(fp, "%s,ERROR,ERROR\n", timestamp);
    fclose(fp);
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

// Signal handler function
void signal_handler(int sig) {
    keep_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Cleanup function
void cleanup(int fd) {
    if (fd != -1) {
        close(fd);
    }
    printf("Cleaned up and exited.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS, SI7021_ADDR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return 1;
    }

    // Main loop
    float temperature, humidity;
    while (keep_running) {
        if (read_sensor_data(i2c_fd, &temperature, &humidity)) {
            log_data(temperature, humidity);
        } else {
            log_error("Failed to read sensor data");
            // Reset the sensor
            if (i2c_write(i2c_fd, RESET_CMD) < 0) {
                log_error("Failed to reset sensor");
            }
            usleep(100000); // Wait 100ms after reset
        }
        sleep(5);
    }

    // Cleanup and exit
    cleanup(i2c_fd);
    return 0;
}

