    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS, SI7021_ADDR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return 1;
    }

    // Main loop
    float temperature, humidity;
    while (keep_running) {
        if (read_sensor_data(i2c_fd, &temperature, &humidity)) {
            log_data(temperature, humidity);
        } else {
            log_error("Failed to read sensor data");
            // Reset the sensor
            if (i2c_write(i2c_fd, RESET_CMD) < 0) {
                log_error("Failed to reset sensor");
            }
            usleep(100000); // Wait 100ms after reset
        }
        sleep(5);
    }

    // Cleanup and exit
    cleanup(i2c_fd);
    return 0;
}

