#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x362F
#define SAMPLE_INTERVAL_MS 1000
#define FILENAME "airflow.dat"

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_device();
int write_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(const uint8_t *data, int count);
int validate_crc(const uint8_t *data, int count);
sensor_data_t process_data(const uint8_t *data);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device() {
    int handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Write command to the sensor
int write_command(int handle, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, (char *)buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int count) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < count; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc(const uint8_t *data, int count) {
    uint8_t crc = calculate_crc(data, count);
    return (crc == 0);
}

// Process raw data to get pressure and temperature
sensor_data_t process_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    uint16_t scale_factor = (data[6] << 8) | data[7];

    sensor_data.pressure = (float)raw_pressure / (float)scale_factor - 1000.0;
    sensor_data.temperature = (float)raw_temperature / 200.0 - 45.0;

    return sensor_data;
}

// Log data to file
int log_data(FILE *fp, sensor_data_t data) {
    if (fwrite(&data.pressure, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Failed to write pressure to file\n");
        return -1;
    }
    if (fwrite(&data.temperature, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Failed to write temperature to file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c_device();
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open file for logging
    fp = fopen(FILENAME, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    uint8_t data[9];
    while (!terminate) {
        // Send measurement command
        if (write_command(i2c_handle, MEASUREMENT_COMMAND) != 0) {
            break;
        }

        // Wait for conversion
        gpioDelay(20); // 20ms

        // Read data
        if (read_data(i2c_handle, data, 9) != 0) {
            break;
        }

        // Validate CRC
        if (!validate_crc(data, 2) || !validate_crc(data + 3, 2)) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        // Process data
        sensor_data_t sensor_data = process_data(data);

        // Log data
        if (log_data(fp, sensor_data) != 0) {
            break;
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

