#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x3603
#define SCALE_FACTOR 60.0
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
int validate_crc(const char *data, int count);
float convert_pressure(int16_t raw_pressure);
int log_pressure(float pressure);
void signal_handler(int signal);

// CRC8 calculation (Sensirion polynomial)
uint8_t crc8(const char *data, int count) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < count; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC
int validate_crc(const char *data, int count) {
    uint8_t crc_calculated = crc8(data, count - 1);
    uint8_t crc_received = data[count - 1];
    if (crc_calculated != crc_received) {
        fprintf(stderr, "CRC validation failed: calculated 0x%02X, received 0x%02X\n", crc_calculated, crc_received);
        return -1;
    }
    return 0;
}

// Convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / SCALE_FACTOR;
}

