    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Send continuous measurement command
    if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_CMD) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char buffer[9];
        int16_t raw_pressure;
        float pressure;

        // Read data
        if (read_data(i2c_handle, buffer, 9) != 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        // Validate CRC for pressure data
        if (validate_crc(buffer, 3) != 0) {
            fprintf(stderr, "CRC validation failed for pressure data, retrying...\n");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        // Validate CRC for temperature data
        if (validate_crc(buffer + 3, 3) != 0) {
            fprintf(stderr, "CRC validation failed for temperature data, retrying...\n");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        // Validate CRC for status data
        if (validate_crc(buffer + 6, 3) != 0) {
            fprintf(stderr, "CRC validation failed for status data, retrying...\n");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        // Convert raw pressure
        raw_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
        pressure = convert_pressure(raw_pressure);

        // Log pressure
        log_pressure(pressure);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Convert seconds to milliseconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

