#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5D

// LPS33HW register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Expected WHO_AM_I value
#define WHO_AM_I_VALUE 0xB1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize the LPS33HW sensor
int init_sensor() {
    int who_am_i;
    int status;

    // Check WHO_AM_I register
    who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: 0x%X != 0x%X\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }

    // Configure CTRL_REG1 (0x10)
    status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0xB0);
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read pressure and temperature data from the sensor
int read_sensor_data(sensor_data_t *data) {
    int32_t pressure_raw;
    int16_t temperature_raw;
    int status;

    // Read pressure data
    int press_xl = i2cReadByteData(i2c_handle, PRESS_OUT_XL);
    int press_l = i2cReadByteData(i2c_handle, PRESS_OUT_L);
    int press_h = i2cReadByteData(i2c_handle, PRESS_OUT_H);

    if (press_xl < 0 || press_l < 0 || press_h < 0) {
        fprintf(stderr, "Error reading pressure data: %s\n", strerror(errno));
        return -1;
    }

    pressure_raw = (int32_t)((press_h << 16) | (press_l << 8) | press_xl);
    if (pressure_raw & 0x800000) {
        pressure_raw |= 0xFF000000; // Sign extend
    }

    // Read temperature data
    int temp_l = i2cReadByteData(i2c_handle, TEMP_OUT_L);
    int temp_h = i2cReadByteData(i2c_handle, TEMP_OUT_H);

    if (temp_l < 0 || temp_h < 0) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }

    temperature_raw = (int16_t)((temp_h << 8) | temp_l);
    if (temperature_raw & 0x8000) {
        temperature_raw |= 0xFFFF0000; // Sign extend
    }

    // Convert data
    data->pressure = (float)pressure_raw / 4096.0;
    data->temperature = 42.5 + (float)temperature_raw / 480.0;

    return 0;
}

// Log the sensor data to a file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, data.pressure, data.temperature);
    fflush(log_file);
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log the data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

