void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to read temperature from STLM75
float read_temperature() {
    int raw_data;
    float temperature;

    raw_data = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_data < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_data);
        return -1000.0; // Indicate an error
    }

    // Swap bytes (pigpio returns little-endian)
    raw_data = ((raw_data & 0xFF) << 8) | ((raw_data & 0xFF00) >> 8);

    // Extract 9-bit value and convert to Celsius
    int16_t temp_9bit = (raw_data >> 7) & 0x1FF; // Extract 9 bits and mask
    if (temp_9bit & 0x100) {
        temp_9bit |= 0xFE00; // Sign extend if negative
    }
    temperature = temp_9bit / 2.0;

    return temperature;
}

// Function to update the LED based on temperature
void update_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize circular buffer with 0s
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_buffer[i] = 0.0;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for read error
            // Update circular buffer
            temperature_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Calculate average temperature
            float sum = 0.0;
            for (int i = 0; i < BUFFER_SIZE; i++) {
                sum += temperature_buffer[i];
            }
            float average_temperature = sum / BUFFER_SIZE;

            // Update LED
            update_led(average_temperature);

            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Skipping temperature update due to read error.\n");
        }

        sleep(1);
    }

    // Cleanup
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Temperature monitoring stopped.\n");
    return 0;
}

