#include <pigpio.h>

// SCD30 I2C address
#define SCD30_ADDR 0x61

// SCD30 commands
#define CMD_START_CONT_MEAS 0x0010
#define CMD_SET_MEAS_INTERVAL 0x4600
#define CMD_READ_MEASUREMENT 0x0300
#define CMD_GET_DATA_READY 0x0202

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int write_command(int handle, unsigned short command, unsigned short argument);
int read_data(int handle, unsigned char *data, int count);
int set_measurement_interval(int handle, int interval);
int start_continuous_measurement(int handle);
int get_data_ready(int handle);
int read_measurement(int handle, sensor_data_t *data);
unsigned char crc8(const unsigned char *data, int len);
void log_data(sensor_data_t data);
void control_ventilation(float co2);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(1, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Write command to SCD30
int write_command(int handle, unsigned short command, unsigned short argument) {
    unsigned char data[3];
    data[0] = (command >> 8) & 0xFF;
    data[1] = command & 0xFF;
    data[2] = crc8(data, 2);

    if (i2cWriteDevice(handle, (char *)data, 3) != 3) {
        fprintf(stderr, "Failed to write command 0x%04X\n", command);
        return -1;
    }

    if (argument != 0) {
        unsigned char arg_data[3];
        arg_data[0] = (argument >> 8) & 0xFF;
        arg_data[1] = argument & 0xFF;
        arg_data[2] = crc8(arg_data, 2);

        if (i2cWriteDevice(handle, (char *)arg_data, 3) != 3) {
            fprintf(stderr, "Failed to write argument for command 0x%04X\n", command);
            return -1;
        }
    }

    return 0;
}

// Read data from SCD30
int read_data(int handle, unsigned char *data, int count) {
    if (i2cReadDevice(handle, (char *)data, count) != count) {
        fprintf(stderr, "Failed to read data\n");
        return -1;
    }
    return 0;
}

// Set measurement interval
int set_measurement_interval(int handle, int interval) {
    return write_command(handle, CMD_SET_MEAS_INTERVAL, interval);
}

// Start continuous measurement
int start_continuous_measurement(int handle) {
    return write_command(handle, CMD_START_CONT_MEAS, 0);
}

// Get data ready status
int get_data_ready(int handle) {
    unsigned char data[3];
    data[0] = (CMD_GET_DATA_READY >> 8) & 0xFF;
    data[1] = CMD_GET_DATA_READY & 0xFF;
    data[2] = crc8(data, 2);

    if (i2cWriteDevice(handle, (char *)data, 3) != 3) {
        fprintf(stderr, "Failed to write data ready command\n");
        return -1;
    }

    unsigned char response[3];
    if (read_data(handle, response, 3) != 0) {
        return -1;
    }

    if (response[2] != crc8(response, 2)) {
        fprintf(stderr, "CRC mismatch in data ready response\n");
        return -1;
    }

    return (response[0] << 8) | response[1];
}

// Read measurement
int read_measurement(int handle, sensor_data_t *data) {
    unsigned char raw_data[18];
    if (read_data(handle, raw_data, 18) != 0) {
        return -1;
    }

    // CRC check for each value
    for (int i = 0; i < 6; i += 3) {
        unsigned char crc = crc8(&raw_data[i], 2);
        if (crc != raw_data[i + 2]) {
            fprintf(stderr, "CRC mismatch for value %d\n", i / 3);
            return -1;
        }
    }

    // Convert raw data to float
    data->co2 = (float)((raw_data[0] << 24) | (raw_data[1] << 16) | (raw_data[3] << 8) | raw_data[4]) / 100.0;
    data->temperature = (float)((raw_data[6] << 24) | (raw_data[7] << 16) | (raw_data[9] << 8) | raw_data[10]) / 100.0;
    data->humidity = (float)((raw_data[12] << 24) | (raw_data[13] << 16) | (raw_data[15] << 8) | raw_data[16]) / 100.0;

    return 0;
}

// CRC-8 checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Log data to file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *utc_tm = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_tm);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file);
}

// Control ventilation based on CO2 level
void control_ventilation(float co2) {
    if (co2 < 800.0) {
        printf("VENTILATION: OFF\n");
    } else if (co2 < 1200.0) {
        printf("VENTILATION: LOW\n");
    } else {
        printf("VENTILATION: HIGH\n");
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Set measurement interval
    if (set_measurement_interval(i2c_handle, 2) != 0) {
        cleanup();
        return 1;
    }

    // Start continuous measurement
    if (start_continuous_measurement(i2c_handle) != 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Check if data is ready
        int data_ready = get_data_ready(i2c_handle);
        if (data_ready > 0) {
            // Read measurement
            if (read_measurement(i2c_handle, &sensor_data) == 0) {
                // Log data
                log_data(sensor_data);

                // Control ventilation
                control_ventilation(sensor_data.co2);
            } else {
                fprintf(stderr, "Failed to read measurement\n");
            }
        } else if (data_ready < 0) {
            fprintf(stderr, "Failed to get data ready status\n");
        }

        // Wait for 2 seconds
        gpioDelay(2000000); // 2 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

