// SDP32 I2C address
#define SDP32_ADDR 0x21

// Continuous measurement command
#define CMD_MEASURE 0x362F

// CRC polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
int sampling_interval_ms = 1000;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint16_t scale_factor;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_sensor_data(int handle, sensor_data_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
float convert_pressure(int16_t raw_pressure, uint16_t scale_factor);
void log_data(float pressure_pa, float temperature_c);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send command to SDP32
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }

    return 0;
}

// Read sensor data from SDP32
int read_sensor_data(int handle, sensor_data_t *data) {
    char buf[9];
    int result = i2cReadDevice(handle, buf, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // Extract raw data
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    int16_t raw_temperature = (buf[3] << 8) | buf[4];
    uint16_t raw_scale_factor = (buf[6] << 8) | buf[7];

    // CRC check
    uint8_t pressure_crc = calculate_crc(buf, 2);
    uint8_t temperature_crc = calculate_crc(buf + 3, 2);
    uint8_t scale_factor_crc = calculate_crc(buf + 6, 2);

    if (pressure_crc != buf[2] || temperature_crc != buf[5] || scale_factor_crc != buf[8]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    data->pressure = raw_pressure;
    data->temperature = raw_temperature;
    data->scale_factor = raw_scale_factor;

    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

