#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and device address
#define I2C_BUS "/dev/i2c-1"
#define HDC1000_ADDR 0x40

// Define the register addresses
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define HUMID_REG 0x01

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to configure the HDC1000 sensor
int configure_hdc1000(int fd) {
    // Set configuration register to enable temperature and humidity measurement
    // with 14-bit resolution
    unsigned char config_data[3];
    config_data[0] = CONFIG_REG;
    config_data[1] = 0x00; // Default value
    config_data[2] = 0x00; // Default value

    if (write(fd, config_data, 3) != 3) {
        fprintf(stderr, "Error writing to configuration register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read temperature and humidity data from the HDC1000 sensor
int read_hdc1000(int fd, float *temperature, float *humidity) {
    unsigned char temp_data[2];
    unsigned char humid_data[2];
    unsigned char read_buf[4];

    // Trigger temperature and humidity measurement by writing to the temperature register
    if (write(fd, (unsigned char[]){TEMP_REG}, 1) != 1) {
        fprintf(stderr, "Error writing to temperature register: %s\n", strerror(errno));
        return -1;
    }

    // Wait for at least 20 ms for the measurement to complete
    usleep(20000); // 20 ms

    // Read 4 bytes from the sensor (2 bytes temperature, 2 bytes humidity)
    if (read(fd, read_buf, 4) != 4) {
        fprintf(stderr, "Error reading from sensor: %s\n", strerror(errno));
        return -1;
    }

    // Combine the bytes to form the raw temperature and humidity values
    int raw_temp = (read_buf[0] << 8) | read_buf[1];
    int raw_humid = (read_buf[2] << 8) | read_buf[3];

    // Convert the raw values to temperature and humidity
    *temperature = ((float)raw_temp / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humid / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Configure the HDC1000 sensor
    if (configure_hdc1000(i2c_fd) != 0) {
        fprintf(stderr, "Error configuring HDC1000 sensor.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and print temperature and humidity data
    while (1) {
        float temperature, humidity;

        // Read temperature and humidity data
        if (read_hdc1000(i2c_fd, &temperature, &humidity) == 0) {
            // Print the temperature and humidity data
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading temperature and humidity data.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close the I2C bus (this will not be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

