// Si7051 I2C address
#define SI7051_ADDR 0x40

// Si7051 commands
#define SI7051_MEASURE_TEMP_HOLD 0xE3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to read temperature from Si7051
float read_temperature() {
    unsigned char buf[2];
    int result;

    // Send temperature measurement command
    result = i2cWriteByte(i2c_handle, SI7051_MEASURE_TEMP_HOLD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Wait for measurement to complete (at least 11ms)
    gpioDelay(11000); // 11ms

    // Read 2 bytes of temperature data
    result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Convert raw data to temperature in Celsius
    unsigned int raw_temperature = (buf[0] << 8) | buf[1];
    float temperature = (175.72 * raw_temperature / 65536.0) - 46.85;

    return temperature;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        sleep(5);
    }

    // Clean up and exit
    i2cClose(i2c_handle);
    gpioTerminate();
    fprintf(stderr, "Program terminated.\n");
    return 0;
}

