#include <pigpio.h>

// Sensor I2C address
#define I2C_ADDR 0x63

// I2C bus
#define I2C_BUS 1

// Calibration coefficients command
#define CALIBRATION_COMMAND 0x50

// Measurement command
#define MEASUREMENT_COMMAND 0x40

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration coefficients
unsigned int scale_factor_lut;
unsigned int scale_factor_h;
unsigned int scale_factor_p;

// Function prototypes
int read_calibration_coefficients();
int trigger_measurement();
int read_sensor_data(unsigned char *data);
void convert_data(unsigned char *data, float *temperature, float *pressure);
void log_data(float temperature, float pressure);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Read calibration coefficients from sensor
int read_calibration_coefficients() {
    unsigned char buffer[8];
    int result = i2cReadI2CBlockData(i2c_handle, CALIBRATION_COMMAND, (char *)buffer, 8);
    if (result < 0) {
        fprintf(stderr, "Error reading calibration coefficients: %d\n", result);
        return -1;
    }

    // Extract calibration coefficients
    scale_factor_lut = (buffer[0] << 8) | buffer[1];
    scale_factor_h = (buffer[2] << 8) | buffer[3];
    scale_factor_p = (buffer[4] << 8) | buffer[5];

    return 0;
}

// Trigger high-precision measurement
int trigger_measurement() {
    int result = i2cWriteByteData(i2c_handle, MEASUREMENT_COMMAND, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(7000); // Wait 7 ms
    return 0;
}

// Read sensor data
int read_sensor_data(unsigned char *data) {
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Convert raw data to temperature and pressure
void convert_data(unsigned char *data, float *temperature, float *pressure) {
    // Extract raw values
    int raw_temperature = (data[0] << 8) | data[1];
    int raw_pressure = (data[2] << 24) | (data[3] << 16) | (data[4] << 8) | data[5];

    // Datasheet formulas (simplified for brevity)
    *temperature = (float)raw_temperature / 100.0; // Example scaling
    *pressure = (float)raw_pressure / 1000.0;       // Example scaling
}

// Log data to stdout
void log_data(float temperature, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read calibration coefficients
    if (read_calibration_coefficients() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        unsigned char data[6];
        float temperature, pressure;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error during measurement, retrying...\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Read sensor data
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Convert data
        convert_data(data, &temperature, &pressure);

        // Log data
        log_data(temperature, pressure);

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

