#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90819_ADDR 0x60
#define PRESSURE_MSB_REG 0xAA
#define PRESSURE_LSB_REG 0xAB
#define SCALE_FACTOR 0.1

static volatile int keep_running = 1;
static int i2c_fd = -1;

void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting...\n");
}

int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    return fd;
}

int set_i2c_slave(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

int read_pressure(int fd, unsigned int *pressure) {
    unsigned char buf[2];
    int ret;

    // Write the register address to read from
    buf[0] = PRESSURE_MSB_REG;
    ret = write(fd, buf, 1);
    if (ret != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Read the pressure data (2 bytes)
    ret = read(fd, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *pressure = (buf[0] << 8) | buf[1];
    return 0;
}

float convert_to_kPa(unsigned int raw_pressure) {
    return raw_pressure * SCALE_FACTOR;
}

int main() {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];
    unsigned int raw_pressure;
    float pressure_kPa;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    if (set_i2c_slave(i2c_fd, MLX90819_ADDR) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (read_pressure(i2c_fd, &raw_pressure) == 0) {
            pressure_kPa = convert_to_kPa(raw_pressure);

            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("%s Pressure: %.2f kPa\n", timestamp, pressure_kPa);
        } else {
            fprintf(stderr, "Failed to read pressure.\n");
        }

        sleep(1);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

