#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define LOG_FILE "pressure_log.txt"
#define I2C_DEVICE_PATH "/dev/i2c-1"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int i2c_open(int bus);
int i2c_write(int fd, uint8_t addr, uint16_t data);
int i2c_read(int fd, uint8_t addr, uint8_t *data, int len);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len, uint8_t crc);
sensor_data_t read_sdp800(int fd);
void log_data(FILE *fp, sensor_data_t data);
void signal_handler(int sig);
void cleanup();

// I2C open function
int i2c_open(int bus) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, uint8_t addr, uint16_t data) {
    uint8_t buf[3];
    buf[0] = addr;
    buf[1] = (data >> 8) & 0xFF;
    buf[2] = data & 0xFF;

    if (write(fd, buf, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t addr, uint8_t *data, int len) {
    if (write(fd, &addr, 1) != 1) {
        perror("Error writing address to I2C device");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const uint8_t *data, int len, uint8_t crc) {
    uint8_t calculated_crc = crc8(data, len);
    return (calculated_crc == crc);
}

// Read SDP800 sensor data function
sensor_data_t read_sdp800(int fd) {
    sensor_data_t data;
    uint8_t buffer[9];

    // Send continuous measurement command
    if (i2c_write(fd, SDP800_ADDR, CONTINUOUS_MEASUREMENT_CMD) < 0) {
        fprintf(stderr, "Error sending measurement command.\n");
        data.pressure = -999.0; // Indicate error
        data.temperature = -999.0;
        return data;
    }

    usleep(45000); // Wait 45 ms

    // Read sensor data
    if (i2c_read(fd, SDP800_ADDR, buffer, 9) < 0) {
        fprintf(stderr, "Error reading sensor data.\n");
        data.pressure = -999.0; // Indicate error
        data.temperature = -999.0;
        return data;
    }

    // Validate CRCs
    if (!validate_crc(buffer, 2, buffer[2])) {
        fprintf(stderr, "Pressure CRC validation failed.\n");
        data.pressure = -999.0; // Indicate error
        data.temperature = -999.0;
        return data;
    }
    if (!validate_crc(buffer + 3, 2, buffer[5])) {
        fprintf(stderr, "Temperature CRC validation failed.\n");
        data.pressure = -999.0; // Indicate error
        data.temperature = -999.0;
        return data;
    }

    // Convert raw values
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    data.pressure = (float)raw_pressure / 60.0;
    data.temperature = (float)raw_temperature / 200.0;

    return data;
}

// Log data to file function
void log_data(FILE *fp, sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            data.pressure, data.temperature);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sdp800(i2c_fd);
        if (data.pressure != -999.0) {
            log_data(log_file, data);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
        }
        sleep(1); // Read every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

