#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASUREMENT_COMMAND_1 0x36
#define MEASUREMENT_COMMAND_2 0x2F
#define SLEEP_DURATION_US 1000000 // 1 second
#define LOG_FILE "airflow_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int trigger_measurement();
int read_sensor_data(int16_t *raw_pressure);
uint8_t calculate_crc(const uint8_t *data, size_t len);
int verify_checksum(const uint8_t *data);
float convert_to_pressure(int16_t raw_pressure);
int log_data(float pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger a single measurement
int trigger_measurement() {
    char command[2] = {MEASUREMENT_COMMAND_1, MEASUREMENT_COMMAND_2};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data and verify checksum
int read_sensor_data(int16_t *raw_pressure) {
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    if (!verify_checksum((uint8_t *)buffer)) {
        fprintf(stderr, "Checksum verification failed\n");
        return -1;
    }

    *raw_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Verify checksum
int verify_checksum(const uint8_t *data) {
    uint8_t calculated_crc = calculate_crc(data, 2);
    return (calculated_crc == data[2]);
}

// Convert raw pressure to Pascals
float convert_to_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / 60.0;
}

// Log data to CSV file
int log_data(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa)\n");
    }
    rewind(log_file);

    int16_t raw_pressure;
    float pressure;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Wait for measurement to complete
        gpioDelay(8000); // 8 ms

        // Read sensor data
        if (read_sensor_data(&raw_pressure) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Convert to pressure
        pressure = convert_to_pressure(raw_pressure);

        // Log data
        if (log_data(pressure) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Sleep for 1 second
        gpioDelay(SLEEP_DURATION_US);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

