#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576 // 1MB

int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig) {
    fprintf(stderr, "\nSignal received, exiting gracefully...\n");
    terminate = 1;
}

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read raw data from the HIH6130 sensor
int read_raw_data(unsigned char *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate the sensor status
int validate_status(unsigned char status) {
    if (status & 0x03) {
        fprintf(stderr, "Sensor status indicates an error: 0x%02X\n", status);
        return -1;
    }
    return 0;
}

// Function to convert raw data to temperature and humidity
SensorData convert_data(unsigned char *data) {
    SensorData sensor_data;
    unsigned int raw_humidity = ((unsigned int)data[0] << 8) | data[1];
    unsigned int raw_temperature = ((unsigned int)data[2] << 6) | (data[3] >> 2);

    sensor_data.humidity = (float)raw_humidity * 100.0 / 16383.0;
    sensor_data.temperature = (float)raw_temperature * 165.0 / 16383.0 - 40.0;

    return sensor_data;
}

// Function to log the sensor data to a file
int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fclose(fp);

    // Check log file size and truncate if necessary
    struct stat st;
    if (stat(LOG_FILE, &st) == 0 && st.st_size > LOG_FILE_SIZE_LIMIT) {
        fp = fopen(LOG_FILE, "w"); // Open in write mode to truncate
        if (fp != NULL) {
            fclose(fp);
        } else {
            fprintf(stderr, "Failed to truncate log file\n");
        }
    }

    return 0;
}

// Function to trigger a measurement
int trigger_measurement() {
    int result = i2cWriteByte(i2c_handle, 0x00);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to clean up resources before exiting
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
    fprintf(stderr, "Cleaned up resources.\n");
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    fprintf(stderr, "Environmental monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        unsigned char data[4];

        if (trigger_measurement() != 0) {
            fprintf(stderr, "Measurement trigger failed, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        gpioDelay(40000); // Wait 40 ms

        if (read_raw_data(data) != 0) {
            fprintf(stderr, "Data read failed, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        unsigned char status = data[0] & 0x03;
        if (validate_status(status) != 0) {
            fprintf(stderr, "Status validation failed, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        SensorData sensor_data = convert_data(data);

        if (log_data(sensor_data.temperature, sensor_data.humidity) != 0) {
            fprintf(stderr, "Data logging failed\n");
        }

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);

        sleep(5); // Sample every 5 seconds
    }

    cleanup();
    return 0;
}

