#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define SENT_TICK 3
#define SYNC_PULSE_TICKS 56
#define MIN_PULSE_TICKS 12
#define MAX_PULSE_TICKS 271
#define TIMEOUT_US 100000 // 100ms timeout

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold SENT data
typedef struct {
    unsigned int status;
    unsigned int data;
    unsigned int checksum;
} SENTData;

// Function prototypes
int initialize_gpio();
int read_sent_data(SENTData *data);
int validate_nibble(unsigned int nibble);
int validate_checksum(SENTData data);
float convert_to_pressure(unsigned int raw_value);
void log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    return 0;
}

// Read SENT data
int read_sent_data(SENTData *data) {
    unsigned int start_tick, end_tick, pulse_width;
    unsigned int nibble_values[5]; // 4 data nibbles + checksum
    int i;

    // Wait for the start of the SENT frame (falling edge)
    int timeout_counter = 0;
    while (gpioRead(GPIO_PIN) == 1 && timeout_counter < TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_US) {
        fprintf(stderr, "Error: Sensor absent timeout\n");
        return 1; // Sensor absent
    }

    start_tick = gpioTick();

    // Read the synchronization pulse
    timeout_counter = 0;
    while (gpioRead(GPIO_PIN) == 0 && timeout_counter < TIMEOUT_US) {
        gpioDelay(1);
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_US) {
        fprintf(stderr, "Error: Synchronization pulse timeout\n");
        return 2; // Bus error
    }

    end_tick = gpioTick();
    pulse_width = end_tick - start_tick;
    if (pulse_width < SYNC_PULSE_TICKS * 0.8 || pulse_width > SYNC_PULSE_TICKS * 1.2) {
        fprintf(stderr, "Error: Invalid synchronization pulse width: %u\n", pulse_width);
        return 2; // Bus error
    }

    // Read the status nibble
    for (i = 0; i < 5; i++) {
        timeout_counter = 0;
        while (gpioRead(GPIO_PIN) == 1 && timeout_counter < TIMEOUT_US) {
            gpioDelay(1);
            timeout_counter++;
        }

        if (timeout_counter >= TIMEOUT_US) {
            fprintf(stderr, "Error: Nibble start timeout\n");
            return 2; // Bus error
        }

        start_tick = gpioTick();

        timeout_counter = 0;
        while (gpioRead(GPIO_PIN) == 0 && timeout_counter < TIMEOUT_US) {
            gpioDelay(1);
            timeout_counter++;
        }

        if (timeout_counter >= TIMEOUT_US) {
            fprintf(stderr, "Error: Nibble end timeout\n");
            return 2; // Bus error
        }

        end_tick = gpioTick();
