#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define TEMP_SCALE 0.0078125
#define FILENAME "greenhouse_temps.dat"
#define SLEEP_SECONDS 60

// Global variables
int i2c_handle = -1;
FILE *fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_sensor_id();
float read_temperature();
int write_temperature_to_file(float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify sensor ID
int verify_sensor_id() {
    int device_id = i2cReadWordData(i2c_handle, 0x0F); // Read Device ID register
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }

    if (device_id != 0x0117) {
        fprintf(stderr, "Incorrect device ID: 0x%04X (expected 0x0117)\n", device_id);
        return -1;
    }

    printf("Sensor ID verified successfully.\n");
    return 0;
}

// Read temperature from the sensor
float read_temperature() {
    int raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw temperature to Celsius
    float temperature = (float)raw_temp * TEMP_SCALE;
    return temperature;
}

// Write temperature to file in little-endian format
int write_temperature_to_file(float temperature) {
    uint32_t temp_int = *(uint32_t *)&temperature; // Cast float to uint32_t
    uint32_t temp_le = __builtin_bswap32(temp_int); // Convert to little-endian

    size_t bytes_written = fwrite(&temp_le, sizeof(uint32_t), 1, fp);
    if (bytes_written != 1) {
        fprintf(stderr, "Error writing to file.\n");
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id() != 0) {
        cleanup();
        return 1;
    }

    // Open file for writing
    fp = fopen(FILENAME, "ab");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing.\n");
        cleanup();
        return 1;
    }

    printf("Monitoring temperature... Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            printf("Temperature: %.2f °C\n", temperature);
            if (write_temperature_to_file(temperature) != 0) {
                fprintf(stderr, "Error writing temperature to file.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

