#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// Measurement command (High Precision)
#define MEASURE_CMD 0xFD

// CRC polynomial
#define CRC_POLY 0x31

// CRC initial value
#define CRC_INIT 0xFF

// Global variables for I2C handle and log file
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int write_i2c_device(int handle, int data);
int read_i2c_device(int handle, char *buf, int count);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len, uint8_t crc);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_hum);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to write to the I2C device
int write_i2c_device(int handle, int data) {
    int result = i2cWriteByteData(handle, 0, data);
    if (result < 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read from the I2C device
int read_i2c_device(int handle, char *buf, int count) {
    int result = i2cReadDevice(handle, buf, count);
    if (result < 0) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }
    return result;
}

// Function to calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC-8 checksum
int validate_crc(const uint8_t *data, int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    if (calculated_crc != crc) {
        fprintf(stderr, "CRC validation failed. Expected: 0x%02X, Calculated: 0x%02X\n", crc, calculated_crc);
        return -1;
    }
    return 0;
}

// Function to convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return -45.0 + 175.0 * (float)raw_temp / 65535.0;
}

// Function to convert raw humidity to percentage
float convert_humidity(uint16_t raw_hum) {
    return -6.0 + 125.0 * (float)raw_hum / 65535.0;
}

// Function to log data to file
int log_data(float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Temperature: %.2f °C, Humidity: %.2f %%RH\n", timestamp, temperature, humidity);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(1, SHT40_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Send measurement command
        if (write_i2c_device(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            break;
        }

        // Wait for conversion
        gpioDelay(8500); // 8.5 ms

        // Read sensor data
        char buf[6];
        if (read_i2c_device(i2c_handle, buf, 6) != 6) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        // Validate CRC
        if (validate_crc((uint8_t *)buf, 2, buf[2]) != 0 || validate_crc((uint8_t *)buf + 3, 2, buf[5]) != 0) {
            fprintf(stderr, "CRC validation failed\n");
            continue; // Skip to the next iteration
        }

        // Convert raw values
        uint16_t raw_temp = (buf[0] << 8) | buf[1];
        uint16_t raw_hum = (buf[3] << 8) | buf[4];
        float temperature = convert_temperature(raw_temp);
