        // Log data
        if (log_data(temperature, humidity) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

