#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define TEMP_RESOLUTION 0.0078125
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_device();
int read_temperature(float *temperature);
void add_to_buffer(float temperature);
void flush_buffer_to_file();
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from TMP117
int read_temperature(float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature: %d\n", result);
        return -1;
    }

    // Convert big-endian to signed 16-bit integer
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Convert to Celsius
    *temperature = raw_temp * TEMP_RESOLUTION;
    return 0;
}

// Add temperature to circular buffer
void add_to_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Flush buffer to file
void flush_buffer_to_file() {
    FILE *fp = fopen("temperature_log.dat", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open temperature_log.dat for writing\n");
        return;
    }

    size_t elements_written = fwrite(temperature_buffer, sizeof(float), BUFFER_SIZE, fp);
    if (elements_written != BUFFER_SIZE) {
        fprintf(stderr, "Failed to write all elements to file\n");
    }

    fclose(fp);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    if (open_i2c_device() != 0) {
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    float temperature;
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            printf("Temperature: %.4f °C\n", temperature);
            add_to_buffer(temperature);
            flush_buffer_to_file();
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping sample.\n");
        }
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

