#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SHTC3 I2C address
#define SHTC3_ADDR 0x70

// SHTC3 command for normal power measurement
#define SHTC3_MEASURE_CMD 0x7866

// CRC polynomial
#define CRC8_POLY 0x31

// Temperature and humidity ranges
#define TEMP_MIN -40.0
#define TEMP_MAX 125.0
#define HUMID_MIN 0.0
#define HUMID_MAX 100.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_shtc3(sensor_data_t *data);
uint8_t crc8(const uint8_t *data, size_t len);
int validate_data(const sensor_data_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0); // Bus 1, address 0x70, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from SHTC3
int read_shtc3(sensor_data_t *data) {
    uint8_t cmd[2] = {(SHTC3_MEASURE_CMD >> 8) & 0xFF, SHTC3_MEASURE_CMD & 0xFF};
    uint8_t buffer[6];

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for measurement (at least 12.4 ms)
    gpioDelay(12400); // 12.4 ms

    // Read 6 bytes of data
    if (i2cReadDevice(i2c_handle, (char *)buffer, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // CRC validation
    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data
    int32_t temp_raw = (buffer[0] << 8) | buffer[1];
    int32_t humid_raw = (buffer[3] << 8) | buffer[4];

    data->temperature = 175.0 * temp_raw / 65535.0 - 45.0;
    data->humidity = 100.0 * humid_raw / 65535.0;

    return 0;
}

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate temperature and humidity data
int validate_data(const sensor_data_t *data) {
    if (data->temperature < TEMP_MIN || data->temperature > TEMP_MAX) {
        fprintf(stderr, "Temperature out of range: %.2f\n", data->temperature);
        return -1;
    }
    if (data->humidity < HUMID_MIN || data->humidity > HUMID_MAX) {
        fprintf(stderr, "Humidity out of range: %.2f\n", data->humidity);
        return -1;
    }
    return 0;
}

// Function to log data to file
int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->temperature, data->humidity);
    fflush(log_file); // Ensure data is written to disk

    printf("%s,%.2f,%.2f\n", timestamp, data->temperature, data->humidity);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("shtc3_environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_shtc3(&sensor_data) == 0) {
            if (validate_data(&sensor_data) == 0) {
                if (log_data(&sensor_data) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

