            temperature = convert_to_celsius(raw_value);

            if (log_data(magnetic_field, temperature) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s,NaN,NaN\n", timestamp);
            fflush(log_file);
            fprintf(stderr, "Error reading sensor, logging NaN values.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_SEC, 0); // Sleep for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

