#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define TEMP_RESOLUTION 0.0078125
#define MAX_REINIT_ATTEMPTS 3

static volatile int running = 1;
static int i2c_handle = -1;

// Structure to hold program state
typedef struct {
    int reinit_attempts;
} ProgramState;

ProgramState state = {0};

// Function to handle SIGINT signal
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from TMP117
int read_temperature(float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1;
    }

    // Convert raw data to signed 16-bit integer
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Convert to Celsius
    *temperature = raw_temp * TEMP_RESOLUTION;
    return 0;
}

// Function to log temperature to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    FILE *fp = fopen("temperature_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(fp, "%s, Temperature: %.4f C\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Initialize I2C
        if (i2c_handle < 0) {
            if (initialize_i2c() != 0) {
                state.reinit_attempts++;
                fprintf(stderr, "I2C initialization failed. Attempt: %d\n", state.reinit_attempts);
                if (state.reinit_attempts > MAX_REINIT_ATTEMPTS) {
                    fprintf(stderr, "Max re-initialization attempts reached. Exiting.\n");
                    running = 0;
                    break;
                }
                gpioDelay(1000); // Wait before retrying
                continue;
            } else {
                state.reinit_attempts = 0; // Reset reinit attempts on success
            }
        }

        float temperature;
        // Read temperature
        if (read_temperature(&temperature) == 0) {
            // Log temperature
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

