#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int *raw_flow, int *raw_temp);
float convert_flow(int raw_flow);
float convert_temperature(int raw_temp);
int log_data(float flow_slpm, float temperature_celsius);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw sensor data from the I2C device
int read_sensor_data(int *raw_flow, int *raw_temp) {
    char buffer[4];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1;
    }

    *raw_flow = ((buffer[0] & 0xFF) << 8) | (buffer[1] & 0xFF);
    *raw_temp = ((buffer[2] & 0xFF) << 8) | (buffer[3] & 0xFF);

    return 0;
}

// Convert raw flow data to SLPM
float convert_flow(int raw_flow) {
    return ((float)raw_flow / 16384.0 - 0.1) / 0.8 * 25.0;
}

// Convert raw temperature data to Celsius
float convert_temperature(int raw_temp) {
    return ((float)raw_temp / 4096.0 - 0.1) / 0.8 * 80.0 - 40.0;
}

// Log data to file with timestamp
int log_data(float flow_slpm, float temperature_celsius) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Flow: %.2f SLPM, Temperature: %.2f °C\n", timestamp, flow_slpm, temperature_celsius);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(log_file, "I2C initialization failed. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    int raw_flow, raw_temp;
    float flow_slpm, temperature_celsius;

    // Discard first two readings
    for (int i = 0; i < 2; i++) {
        if (read_sensor_data(&raw_flow, &raw_temp) != 0) {
            fprintf(log_file, "Error reading sensor data during initial discard.\n");
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }
        gpioDelay(100); // Small delay to allow sensor to settle
    }

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&raw_flow, &raw_temp) == 0) {
            flow_slpm = convert_flow(raw_flow);
            temperature_celsius = convert_temperature(raw_temp);
            log_data(flow_slpm, temperature_celsius);
        } else {
            fprintf(log_file, "Error reading sensor data. Attempting to re-initialize.\n");
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(log_file, "I2C re-initialization failed. Exiting.\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Delay for 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

