        fprintf(log_file, "I2C initialization failed. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    int raw_flow, raw_temp;
    float flow_slpm, temperature_celsius;

    // Discard first two readings
    for (int i = 0; i < 2; i++) {
        if (read_sensor_data(&raw_flow, &raw_temp) != 0) {
            fprintf(log_file, "Error reading sensor data during initial discard.\n");
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }
        gpioDelay(100); // Small delay to allow sensor to settle
    }

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&raw_flow, &raw_temp) == 0) {
            flow_slpm = convert_flow(raw_flow);
            temperature_celsius = convert_temperature(raw_temp);
            log_data(flow_slpm, temperature_celsius);
        } else {
            fprintf(log_file, "Error reading sensor data. Attempting to re-initialize.\n");
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(log_file, "I2C re-initialization failed. Exiting.\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Delay for 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

