int read_dht11(int gpio, int *humidity, int *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int byte_idx = 0;
    unsigned int start_tick, end_tick, pulse_duration;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(18000); // 18 ms
    gpioWrite(gpio, 1);
    gpioDelay(30); // 20 us
    gpioSetMode(gpio, PI_INPUT);

    start_tick = gpioTick();
    while (gpioRead(gpio) == 1) {
        end_tick = gpioTick();
        if (end_tick - start_tick > 100000) { // Timeout after 100 ms
            log_message("DHT11: Sensor absent (initial HIGH)");
            return -1;
        }
    }
    start_tick = gpioTick();
    while (gpioRead(gpio) == 0) {
        end_tick = gpioTick();
        if (end_tick - start_tick > 100000) { // Timeout after 100 ms
            log_message("DHT11: Sensor absent (initial LOW)");
            return -1;
        }
    }
    start_tick = gpioTick();
    while (gpioRead(gpio) == 1) {
        end_tick = gpioTick();
        if (end_tick - start_tick > 100000) { // Timeout after 100 ms
            log_message("DHT11: Sensor absent (response HIGH)");
            return -1;
        }
    }

    for (int i = 0; i < 40; i++) {
        start_tick = gpioTick();
        while (gpioRead(gpio) == 0) {
