        while (gpioRead(gpio) == 1) {
            end_tick = gpioTick();
            if (end_tick - start_tick > 100000) { // Timeout after 100 ms
                log_message("DHT11: Timeout waiting for bit end");
                return -1;
            }
        }
        pulse_duration = end_tick - start_tick;

        if (pulse_duration > 40000) { // 40 us
