                fclose(readings_file);
            } else {
                fprintf(stderr, "Error opening readings file!\n");
            }
        } else {
            log_message("DHT11: Failed to read data");
        }

        gpioDelay(2000000); // 2 seconds
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    return 0;
}

