#include <signal.h>
#include <pigpio.h>

#define SHT31_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2C06
#define LOG_FILE "sht31d_data.log"

int i2c_handle;
FILE *log_file;

// Function to calculate CRC-8
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT31-D
int read_sht31d(float *temperature, float *humidity) {
    unsigned char data[6];
    unsigned char command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, (char *)command, 2);
        if (result == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to I2C device: %d\n", result);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to write to I2C device after multiple retries.\n");
        return -1;
    }

    gpioDelay(15000); // Wait 15ms

    retries = 3;
    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result == 6) {
            break;
        } else {
            fprintf(stderr, "Error reading from I2C device: %d\n", result);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read from I2C device after multiple retries.\n");
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed.\n");
        return -1;
    }

    // Convert raw values
    int temperature_raw = (data[0] << 8) | data[1];
    int humidity_raw = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
    *humidity = 100.0 * (float)humidity_raw / 65535.0;

    return 0;
}

// Function to log data to file
void log_data(float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    float temperature, humidity;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        if (read_sht31d(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    return 0;
}

