#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Sensor addresses
#define SENSOR1_ADDR 0x64
#define SENSOR2_ADDR 0x65

// Register addresses
#define DEVICE_ID_REG 0x00
#define RED_CHANNEL_REG 0x64
#define GREEN_CHANNEL_REG 0x66
#define BLUE_CHANNEL_REG 0x68

// Expected device ID
#define EXPECTED_DEVICE_ID 0x2A

// I2C bus
#define I2C_BUS 1

// Global variables for I2C handles and file pointer
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, unsigned int *red, unsigned int *green, unsigned int *blue);
float calculate_cct(unsigned int red, unsigned int green, unsigned int blue);
float calculate_average_cct(float cct1, float cct2);
void log_data(float average_cct);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);

    // Close I2C handles
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to initialize a sensor
int initialize_sensor(int i2c_handle) {
    int device_id;

    // Read device ID
    device_id = i2cReadByteData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }

    // Verify device ID
    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Incorrect device ID: 0x%02X (expected 0x%02X)\n", device_id, EXPECTED_DEVICE_ID);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, unsigned int *red, unsigned int *green, unsigned int *blue) {
    char buffer[6];
    int result;

    // Read red, green, and blue channel data
    result = i2cReadI2CBlockData(i2c_handle, RED_CHANNEL_REG, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Combine bytes to form 16-bit values (little-endian)
    *red = (unsigned int)buffer[1] << 8 | (unsigned int)buffer[0];
    *green = (unsigned int)buffer[3] << 8 | (unsigned int)buffer[2];
    *blue = (unsigned int)buffer[5] << 8 | (unsigned int)buffer[4];

    return 0;
}

// Function to calculate CCT using McCamy's formula
float calculate_cct(unsigned int red, unsigned int green, unsigned int blue) {
    float x, y, z;

    // Convert RGB to XYZ
    x = (float)red * 0.3623 + (float)green * 0.3270 + (float)blue * 0.1986;
    y = (float)red * 0.1545 + (float)green * 0.8475 + (float)blue * 0.0029;
    z = (float)red * 0.0000 + (float)green * 0.0593 + (float)blue * 0.9393;

    // McCamy's formula
    float n = (x - (0.3623 * y)) / (0.1986 * y - (0.3623 * z));
    float cct = 449.0 * pow(n, 3) + 3525.0 * pow(n, 2) + 6823.3 * n + 5520.33;

    return cct;
}

// Function to calculate the average CCT
float calculate_average_cct(float cct1, float cct2) {
    return (cct1 + cct2) / 2.0;
}

// Function to log data to a CSV file
void log_data(float average_cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Open log file in append mode
