// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x60
#define PRESSURE_REGISTER 0x0A2C
#define TEMPERATURE_REGISTER 0x0A2E
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define PMIN_KPA 0.0
#define PMAX_KPA 800.0
#define SAMPLE_INTERVAL_SEC 2

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_raw_pressure(int i2c_handle, unsigned int *raw_pressure);
int read_raw_temperature(int i2c_handle, unsigned int *raw_temperature);
float convert_pressure(unsigned int raw_pressure);
float convert_temperature(unsigned int raw_temperature);
int log_data(FILE *log_file, float pressure_kPa, float temperature_C);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to read raw pressure from the sensor
int read_raw_pressure(int i2c_handle, unsigned int *raw_pressure) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading pressure: %d\n", result);
        return -1;
    }
    *raw_pressure = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw temperature from the sensor
int read_raw_temperature(int i2c_handle, unsigned int *raw_temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REGISTER, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1;
    }
    *raw_temperature = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to convert raw pressure to kPa
float convert_pressure(unsigned int raw_pressure) {
    return (float)(raw_pressure - OUTPUT_MIN) * (PMAX_KPA - PMIN_KPA) / (OUTPUT_MAX - OUTPUT_MIN);
}

// Function to convert raw temperature to Celsius
float convert_temperature(unsigned int raw_temperature) {
    return (float)raw_temperature * 0.01 - 40.0;
}

// Function to log data to a file
int log_data(FILE *log_file, float pressure_kPa, float temperature_C) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
