    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        unsigned int raw_pressure, raw_temperature;
        float pressure_kPa, temperature_C;

        // Read raw pressure
        if (read_raw_pressure(i2c_handle, &raw_pressure) != 0) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
            fprintf(log_file, "%s,Error reading pressure\n", timestamp);
            fflush(log_file);
        } else {
            // Convert pressure
            pressure_kPa = convert_pressure(raw_pressure);

            // Read raw temperature
            if (read_raw_temperature(i2c_handle, &raw_temperature) != 0) {
                time_t now = time(NULL);
                struct tm *t = localtime(&now);
                char timestamp[32];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
                fprintf(log_file, "%s,Error reading temperature\n", timestamp);
                fflush(log_file);
            } else {
                // Convert temperature
                temperature_C = convert_temperature(raw_temperature);

                // Log data
                if (log_data(log_file, pressure_kPa, temperature_C) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            }
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

