    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize circular buffer
    CircularBuffer temp_buffer;
    initialize_circular_buffer(&temp_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            add_to_buffer(&temp_buffer, temperature);
            float average_temperature = calculate_average(&temp_buffer);
            control_fan(average_temperature);
            printf("Temperature: %.2f°C, Average: %.2f°C\n", temperature, average_temperature);
        } else {
