#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASURE_COMMAND 0x362F
#define PRESSURE_SCALE 60.0
#define TEMPERATURE_SCALE 200.0
#define LOG_FILE "airflow.log"
#define PRESSURE_THRESHOLD 5.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
int validate_crc(const uint8_t *data, int count);
float convert_pressure(int16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// CRC8 calculation (Sensirion polynomial)
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC
int validate_crc(const uint8_t *data, int count) {
    for (int i = 0; i < count - 1; i += 3) {
        uint8_t crc = crc8(data + i, 2);
        if (crc != data[i + 2]) {
            fprintf(stderr, "CRC mismatch at byte %d: calculated %02X, expected %02X\n", i, crc, data[i + 2]);
            return -1;
        }
    }
    return 0;
}

// Convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / PRESSURE_SCALE;
}

// Convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return (float)raw_temperature / TEMPERATURE_SCALE;
}

// Log data to file
int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        int16_t raw_pressure, raw_temperature;
        float pressure, temperature;

        // Send continuous measurement command
        if (send_command(i2c_handle, MEASURE_COMMAND) != 0) {
            fprintf(stderr, "Error sending measurement command\n");
            break;
        }

        // Wait for measurement
        gpioDelay(45000); // 45 ms

        // Read data
        if (read_data(i2c_handle, data, 9) != 0) {
            fprintf(stderr, "Error reading data\n");
            break;
        }

        // Validate CRC
        if (validate_crc(data, 9) != 0) {
            fprintf(stderr, "CRC validation failed\n");
            continue; // Skip to the next iteration
        }

        // Convert data
        raw_pressure = (data[0] << 8) | data[1];
        raw_temperature = (data[3] << 8) | data[4];

        pressure = convert_pressure(raw_pressure);
        temperature = convert_temperature(raw_temperature);

        // Log data
        log_data(pressure, temperature);

        // Check pressure threshold
        if (pressure > PRESSURE_THRESHOLD) {
            fprintf(stderr, "Warning: Pressure exceeds threshold (%.2f Pa > %.2f Pa)\n", pressure, PRESSURE_THRESHOLD);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

