#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x4A
#define GPIO_PIN 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define TEMP_REGISTER 0x00
#define TEMP_SCALE 0.0625
#define MAX_I2C_RETRIES 3

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg, uint16_t *value);
float convert_to_celsius(uint16_t raw_temp);
int gpio_set_value(struct gpiod_line *line, int value);
void signal_handler(int sig);

// I2C read function with retry mechanism
int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    int retries = 0;
    while (retries < MAX_I2C_RETRIES) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            retries++;
            usleep(10000); // 10ms delay
            continue;
        }

        if (read(fd, value, 2) != 2) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            retries++;
            usleep(10000); // 10ms delay
            continue;
        }

        // Successful read
        return 0;
    }

    fprintf(stderr, "I2C read failed after %d retries. Exiting.\n", MAX_I2C_RETRIES);
    return -1; // Indicate failure
}

// Temperature conversion function
float convert_to_celsius(uint16_t raw_temp) {
    return (float)(raw_temp >> 4) * TEMP_SCALE;
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "temperature_led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(gpio_line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(-ret));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_temp;
        if (i2c_read_word(i2c_fd, TEMP_REGISTER, &raw_temp) == 0) {
            float temperature = convert_to_celsius(raw_temp);
            printf("Temperature: %.2f °C\n", temperature);

            if (temperature > TEMP_THRESHOLD_HIGH) {
                gpio_set_value(gpio_line, 1); // Turn LED on
            } else if (temperature < TEMP_THRESHOLD_LOW) {
                gpio_set_value(gpio_line, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }

        sleep(1);
    }

    // Cleanup
    gpio_set_value(gpio_line, 0); // Turn LED off
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    fprintf(stderr, "Exiting cleanly.\n");
    return 0;
}

