        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "temperature_led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(gpio_line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(-ret));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_temp;
        if (i2c_read_word(i2c_fd, TEMP_REGISTER, &raw_temp) == 0) {
            float temperature = convert_to_celsius(raw_temp);
            printf("Temperature: %.2f °C\n", temperature);

            if (temperature > TEMP_THRESHOLD_HIGH) {
                gpio_set_value(gpio_line, 1); // Turn LED on
            } else if (temperature < TEMP_THRESHOLD_LOW) {
                gpio_set_value(gpio_line, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }

        sleep(1);
    }

    // Cleanup
    gpio_set_value(gpio_line, 0); // Turn LED off
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    fprintf(stderr, "Exiting cleanly.\n");
    return 0;
}

