#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define MEASUREMENT_DELAY_MS 45
#define SCALE_FACTOR_BYTES 2
#define PRESSURE_BYTES 2
#define TEMPERATURE_BYTES 2
#define CRC_BYTES 1
#define DATA_BYTES (PRESSURE_BYTES + CRC_BYTES + TEMPERATURE_BYTES + CRC_BYTES + SCALE_FACTOR_BYTES)

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(const uint8_t *data, int count);
int validate_crc(const uint8_t *data, int count);
sensor_data_t process_data(const uint8_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, int count) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < count; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 validation function
int validate_crc(const uint8_t *data, int count) {
    uint8_t calculated_crc = calculate_crc(data, count - 1);
    return (calculated_crc == data[count - 1]);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to process the raw data and convert it to physical units
sensor_data_t process_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t scale_factor = (data[6] << 8) | data[7];

    sensor_data.pressure = (float)raw_pressure / (float)scale_factor;
    sensor_data.temperature = (float)raw_temperature / 200.0f;

    return sensor_data;
}

// Function to log the data to a file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f Pa, %.2f °C\n", timestamp, data.pressure, data.temperature);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("flow_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Send continuous measurement command
    if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_CMD) != 0) {
        cleanup();
        return 1;
    }

    uint8_t data[DATA_BYTES];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read data
        if (read_data(i2c_handle, data, DATA_BYTES) == 0) {
            // Validate CRC
            if (validate_crc(data, PRESSURE_BYTES + CRC_BYTES) && validate_crc(data + PRESSURE_BYTES + CRC_BYTES, TEMPERATURE_BYTES + CRC_BYTES)) {
                // Process data
                sensor_data = process_data(data);

                // Log data
                log_data(sensor_data);
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read data, retrying...\n");
        }

        // Delay
        gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

