#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define LOG_FILE "environment.log"

// Global variables for signal handling
static int i2c_handle = -1;
static FILE *log_file = NULL;

// Function prototypes
int read_sensor_data(int i2c_handle, float *temperature, float *humidity);
int log_data(FILE *log_file, float temperature, float humidity);
void signal_handler(int signal);
int validate_sensor(int i2c_handle);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to validate the sensor by reading its ID
int validate_sensor(int i2c_handle) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading sensor ID: %d\n", result);
        return -1;
    }
    printf("Sensor ID: 0x%02X%02X\n", buf[0], buf[1]);
    return 0;
}

// Function to read temperature and humidity from the Si7021 sensor
int read_sensor_data(int i2c_handle, float *temperature, float *humidity) {
    char cmd_humidity = 0xF5;
    char cmd_temperature = 0xF3;
    char buf[2];
    int raw_humidity, raw_temperature;
    int retries = 3;
    int result;

    // Measure Humidity
    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, &cmd_humidity, 1);
        if (result == 0) break;
        fprintf(stderr, "Error writing humidity command, retrying...\n");
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write humidity command after multiple retries.\n");
        return -1;
    }
    gpioDelay(20000); // Wait 20ms

    retries = 3;
    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) break;
        fprintf(stderr, "Error reading humidity data, retrying...\n");
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read humidity data after multiple retries.\n");
        return -1;
    }
    raw_humidity = (buf[0] << 8) | buf[1];

    // Measure Temperature
    retries = 3;
    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, &cmd_temperature, 1);
        if (result == 0) break;
        fprintf(stderr, "Error writing temperature command, retrying...\n");
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write temperature command after multiple retries.\n");
        return -1;
    }
    gpioDelay(20000); // Wait 20ms

    retries = 3;
    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) break;
        fprintf(stderr, "Error reading temperature data, retrying...\n");
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read temperature data after multiple retries.\n");
        return -1;
    }
    raw_temperature = (buf[0] << 8) | buf[1];

    // Convert raw values
    *temperature = 175.72 * raw_temperature / 65536.0 - 46.85;
    *humidity = 125.0 * raw_humidity / 65536.0 - 6.0;

    // Clamp humidity to 0-100%
    if (*humidity < 0.0) *humidity = 0.0;
    if (*humidity > 100.0) *humidity = 100.0;

    return 0;
}

// Function to log data to a file
int log_data(FILE *log_file, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);
    printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);

    return 0;
}

int main() {
    float temperature, humidity;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Validate sensor
    if (validate_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor validation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        if (read_sensor_data(i2c_handle, &temperature, &humidity) == 0) {
            log_data(log_file, temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }
        sleep(60);
    }

    // Cleanup (should not reach here due to signal handler)
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

