#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define STS40_ADDR 0x44
#define MEASURE_CMD_1 0x2C
#define MEASURE_CMD_2 0xE0
#define LOG_FILE "temperature_log.txt"

static volatile int keep_running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

// CRC8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Function to calculate CRC8
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to get ISO-8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log temperature with timestamp
int log_temperature(float temperature) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp.\n");
        return -1;
    }

    if (log_fp != NULL) {
        fprintf(log_fp, "%s, %.2f\n", timestamp, temperature);
        fflush(log_fp); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Log file is not open.\n");
        free(timestamp);
        return -1;
    }
    free(timestamp);
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
    keep_running = 0;
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    exit(0);
}

int main() {
    uint8_t write_buffer[2];
    uint8_t read_buffer[3];
    int16_t raw_temperature;
    float temperature_celsius;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, STS40_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Send measurement command
        write_buffer[0] = MEASURE_CMD_1;
        write_buffer[1] = MEASURE_CMD_2;
        ret = write(i2c_fd, write_buffer, 2);
        if (ret != 2) {
            perror("Failed to write measurement command");
            fprintf(stderr, "Write returned: %d\n", ret);
            continue;
        }

        // Wait for conversion
        usleep(10000); // 10 ms

        // Read temperature data
        ret = read(i2c_fd, read_buffer, 3);
        if (ret != 3) {
            perror("Failed to read temperature data");
            fprintf(stderr, "Read returned: %d\n", ret);
            continue;
        }

        // Validate CRC
        uint8_t crc = crc8(read_buffer, 2);
        if (crc != read_buffer[2]) {
            fprintf(stderr, "CRC mismatch: calculated 0x%02X, received 0x%02X\n", crc, read_buffer[2]);
            continue;
        }

        // Convert raw temperature to Celsius
        raw_temperature = (read_buffer[0] << 8) | read_buffer[1];
        temperature_celsius = -45.0 + 175.0 * (float)raw_temperature / 65535.0;

        // Log temperature
        if (log_temperature(temperature_celsius) != 0) {
            fprintf(stderr, "Failed to log temperature.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup (should not reach here if signal handler works)
    close(i2c_fd);
    fclose(log_fp);

    return 0;
}

