#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define LOG_FILE "hvac_pressure_log.txt"

int i2c_handle;
FILE *log_file;

// Function to calculate CRC-8
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read pressure and temperature from the sensor
int read_sensor(float *pressure, float *temperature) {
    unsigned char cmd[2] = {0x36, 0x15};
    unsigned char buffer[9];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(50); // Wait for at least 50 ms

    result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // CRC validation
    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5] || crc8(buffer + 6, 3) != buffer[8]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Extract raw values
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];
    int16_t scale_factor = (buffer[6] << 8) | buffer[7];

    // Convert to physical units
    *pressure = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temperature / 200.0;

    return 0;
}

// Function to log data to a file
void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

