int buffer_count = 0;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

// Global variables
int i2c_handle;
volatile sig_atomic_t running = 1;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int send_command(int handle, unsigned short command);
