// Sensor I2C address
#define SDP810_ADDR 0x25

// Measurement command (continuous, no clock stretching)
#define MEASURE_CMD 0x362F

// CRC polynomial
#define CRC8_POLY 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_Pa;
    float temperature_C;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
