#include <signal.h>
#include <pigpio.h>

// Define sensor and I2C parameters
#define I2C_BUS 1
#define ICP10110_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define CALIB_COEFF_REG 0x05
#define MEASURE_REG 0x00
#define DATA_REG 0x00

// Define calibration coefficients
typedef struct {
    int32_t c0;
    int32_t c1;
    int32_t c00;
    int32_t c10;
} icp10110_calib_coeffs_t;

// Global variables
int i2c_handle;
icp10110_calib_coeffs_t calib_coeffs;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int verify_sensor_identity();
int read_calibration_coefficients();
int trigger_measurement();
int read_pressure_temperature(int32_t *pressure, int32_t *temperature);
float convert_pressure(int32_t raw_pressure);
float convert_temperature(int32_t raw_temperature);
char* get_iso8601_timestamp();
int log_data(char *timestamp, float pressure, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify sensor identity
int verify_sensor_identity() {
    int who_am_i;
    who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x08) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }
    return 0;
}

// Read calibration coefficients
int read_calibration_coefficients() {
    char buf[4];
    if (i2cReadI2CBlockData(i2c_handle, CALIB_COEFF_REG, buf, 4) != 4) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        return -1;
    }

    calib_coeffs.c0 = (int32_t)((uint32_t)buf[0] << 24 | (uint32_t)buf[1] << 16 | (uint32_t)buf[2] << 8 | (uint32_t)buf[3]);
    calib_coeffs.c1 = (int32_t)((uint32_t)buf[0] << 24 | (uint32_t)buf[1] << 16 | (uint32_t)buf[2] << 8 | (uint32_t)buf[3]);

    if (i2cReadI2CBlockData(i2c_handle, CALIB_COEFF_REG + 2, buf, 4) != 4) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        return -1;
    }

    calib_coeffs.c00 = (int32_t)((uint32_t)buf[0] << 24 | (uint32_t)buf[1] << 16 | (uint32_t)buf[2] << 8 | (uint32_t)buf[3]);
    calib_coeffs.c10 = (int32_t)((uint32_t)buf[0] << 24 | (uint32_t)buf[1] << 16 | (uint32_t)buf[2] << 8 | (uint32_t)buf[3]);

    return 0;
}

// Trigger measurement
int trigger_measurement() {
    if (i2cWriteByteData(i2c_handle, MEASURE_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(10); // Wait for measurement to complete
    return 0;
}

// Read pressure and temperature data
int read_pressure_temperature(int32_t *pressure, int32_t *temperature) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, DATA_REG, buf, 6) != 6) {
        fprintf(stderr, "Failed to read pressure and temperature data\n");
        return -1;
    }

    *pressure = (int32_t)((uint32_t)buf[0] << 16 | (uint32_t)buf[1] << 8 | (uint32_t)buf[2]);
    *temperature = (int32_t)((uint32_t)buf[3] << 16 | (uint32_t)buf[4] << 8 | (uint32_t)buf[5]);

    return 0;
}

// Convert raw pressure to hPa
float convert_pressure(int32_t raw_pressure) {
    // Placeholder conversion formula, replace with actual formula from datasheet
    return (float)raw_pressure / 100.0f; // Example conversion
}

// Convert raw temperature to Celsius
float convert_temperature(int32_t raw_temperature) {
    // Placeholder conversion formula, replace with actual formula from datasheet
    return (float)raw_temperature / 100.0f; // Example conversion
}

// Get ISO-8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to file
int log_data(char *timestamp, float pressure, float temperature) {
    FILE *fp = fopen("environmental_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(fp); // Flush the buffer to ensure data is written immediately
    fclose(fp);
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor identity
    if (verify_sensor_identity() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_pressure, raw_temperature;
        float pressure, temperature;
        char *timestamp;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error during measurement, skipping sample\n");
            gpioDelay(5000); // Wait 5 seconds before next sample
            continue;
        }

        // Read pressure and temperature data
        if (read_pressure_temperature(&raw_pressure, &raw_temperature) != 0) {
            fprintf(stderr, "Error reading pressure/temperature, skipping sample\n");
            gpioDelay(5000); // Wait 5 seconds before next sample
            continue;
        }

        // Convert raw data to hPa and Celsius
        pressure = convert_pressure(raw_pressure);
        temperature = convert_temperature(raw_temperature);

        // Get timestamp
        timestamp = get_iso8601_timestamp();

        // Log data
        if (log_data(timestamp, pressure, temperature) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Print to stdout
        printf("%s,%.2f,%.2f\n", timestamp, pressure, temperature);

        free(timestamp); // Free the allocated memory

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

