    // Extract raw pressure and temperature values
    int32_t raw_pressure = (data[0] << 8) | data[1];
    int32_t raw_temperature = (data[2] << 8) | data[3];
    uint8_t crc_pressure = data[4];
    uint8_t crc_temperature = data[5];

    // Verify CRC
    if (verify_crc(data, 2, crc_pressure) != 0) {
        fprintf(stderr, "Error: Pressure CRC check failed\n");
        return -1;
    }

    if (verify_crc(data + 2, 2, crc_temperature) != 0) {
        fprintf(stderr, "Error: Temperature CRC check failed\n");
        return -1;
    }

