    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("Error: Could not open /sys/class/gpio/export");
        return -1;
    }

    int len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        perror("Error: Could not write to /sys/class/gpio/export");
