    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error: Could not open GPIO direction file");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        perror("Error: Could not write to GPIO direction file");
