    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error: Could not open GPIO value file");
        return -1;
    }

    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);

    if (write(fd, val_str, 1) != 1) {
        perror("Error: Could not write to GPIO value file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C bus");
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Export GPIO pin
    if (gpio_export(GPIO_PIN) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Set GPIO direction to output
    if (gpio_set_direction(GPIO_PIN, "out") < 0) {
        gpio_unexport(GPIO_PIN);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_pressure, raw_temperature;
        float pressure, temperature;

        // Trigger measurement
        if (trigger_measurement(i2c_fd) < 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for measurement to complete (20 ms)
        usleep(20000);

        // Read pressure and temperature
        if (read_pressure_temperature(i2c_fd, &raw_pressure, &raw_temperature) < 0) {
            fprintf(stderr, "Error reading pressure and temperature, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert pressure and temperature
        pressure = convert_pressure(raw_pressure);
        temperature = convert_temperature(raw_temperature);

        // Print pressure and temperature
        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        // Blink LED based on pressure
        if (pressure < 95000) {
            // Blink at 5 Hz
            gpio_set_value(GPIO_PIN, 1);
            usleep(100000); // 100 ms
            gpio_set_value(GPIO_PIN, 0);
            usleep(100000); // 100 ms
        } else {
            // Blink at 1 Hz
            gpio_set_value(GPIO_PIN, 1);
            usleep(500000); // 500 ms
            gpio_set_value(GPIO_PIN, 0);
            usleep(500000); // 500 ms
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    gpio_set_value(GPIO_PIN, 0);
    gpio_unexport(GPIO_PIN);
    close(i2c_fd);

    return 0;
}

