#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define TEMP_HIGH 30.0
#define TEMP_LOW 28.0
#define LOG_FILE "temperature_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_device();
int read_raw_temperature(int reg, int *raw_value);
float convert_to_celsius(int raw_value);
int log_temperature(float ambient_temp, float object_temp);
int control_fan(float object_temp);
void signal_handler(int signal);
void cleanup();

// Structure to hold temperature data
typedef struct {
    float ambient_temp;
    float object_temp;
} TemperatureData;

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C device
int open_i2c_device() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read raw temperature data from the sensor
int read_raw_temperature(int reg, int *raw_value) {
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = i2cReadWordData(i2c_handle, reg);
        if (result >= 0) {
            *raw_value = result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (reg 0x%02X), retry %d: %d\n", reg, retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "I2C read failed after %d retries (reg 0x%02X)\n", RETRY_COUNT, reg);
    return -1; // Failure
}

