#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define PORT 8080
#define MAX_RETRIES 3

// Global variables for signal handling
static int i2c_handle = -1;
static int server_fd = -1;

// Function prototypes
int read_sht40(int i2c_handle, float *temperature, float *humidity);
int start_http_server(int port);
void handle_client(int client_socket);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to read temperature and humidity from SHT40 sensor
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    unsigned char buf[6];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, 0, MEASURE_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %d\n", result);
            retries++;
            gpioDelay(10000); // Wait 10ms before retry
            continue;
        }

        gpioDelay(10000); // Wait at least 10ms for measurement

        result = i2cReadDevice(i2c_handle, (char *)buf, 6);
        if (result != 6) {
            fprintf(stderr, "Error reading from I2C: %d\n", result);
            retries++;
            gpioDelay(10000); // Wait 10ms before retry
            continue;
        }

        // Convert raw data to temperature and humidity
        unsigned int raw_temperature = (buf[0] << 8) | buf[1];
        unsigned int raw_humidity = (buf[3] << 8) | buf[4];

        *temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
        *humidity = -6.0 + 125.0 * (float)raw_humidity / 65535.0;

        // Clamp humidity to 0-100%
        if (*humidity < 0.0) *humidity = 0.0;
        if (*humidity > 100.0) *humidity = 100.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to start the HTTP server
int start_http_server(int port) {
    int server_fd, client_fd;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        return -1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        close(server_fd);
        return -1;
    }

    printf("Server listening on port %d\n", port);
    return server_fd;
}

// Function to handle client connections
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    float temperature, humidity;
    int bytes_received;

    // Receive request
    bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("recv failed");
        close(client_socket);
        return;
    }

    // Read sensor data
    if (read_sht40(i2c_handle, &temperature, &humidity) != 0) {
        const char *error_response = "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/html\r\n\r\n<html><body><h1>Error: Could not read sensor data</h1></body></html>";
        send(client_socket, error_response, strlen(error_response), 0);
        close(client_socket);
        return;
    }

    // Format response
    char response[256];
    snprintf(response, sizeof(response), "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n<html><body><h1>Temperature: %.2f &deg;C</h1><h2>Humidity: %.2f %%</h2></body></html>", temperature, humidity);

    // Send response
    send(client_socket, response, strlen(response), 0);

    // Close connection
    close(client_socket);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    if (server_fd >= 0) {
        close(server_fd);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start HTTP server
    server_fd = start_http_server(PORT);
    if (server_fd < 0) {
        fprintf(stderr, "Error starting HTTP server\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct sockaddr_in client_address;
    int client_socket;
    int addrlen = sizeof(client_address);

    // Main loop
    while (1) {
        // Accept connection
        client_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&addrlen);
        if (client_socket < 0) {
            perror("accept failed");
            continue; // Continue listening for other connections
        }

        // Handle client connection
        handle_client(client_socket);
    }

    return 0;
}

