#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define TEMP_REG 0x00
#define LOG_FILE "temperature_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;

// Function to handle SIGINT signal (Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature from TMP102 sensor
float read_temperature() {
    char buf[2];
    int result;
    int raw_temp;
    float temperature;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1000.0; // Indicate error with a very low temperature
    }

    raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 4; // Shift right by 4 bits

    temperature = raw_temp * 0.0625;
    return temperature;
}

// Function to log temperature to CSV file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Error: Failed to read temperature. Skipping log.\n");
        }
        gpioDelay(5000); // Wait 5 seconds
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

