#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define MEASUREMENT_CONFIG 0x0E
#define TEMPERATURE_MSB 0x00
#define TEMPERATURE_LSB 0x01
#define HUMIDITY_MSB 0x02
#define HUMIDITY_LSB 0x03
#define CONFIG 0x0F

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to initialize the HDC2010 sensor
int init_hdc2010() {
    // Configure the sensor for continuous measurement mode, 14-bit resolution, and no heater
    // Write 0x00 to the CONFIG register (0x0F) to disable heater and set resolution to 14-bit
    if (i2cWriteByteData(i2c_handle, CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }
    return 0;
}

// Function to trigger a single temperature and humidity measurement
int trigger_measurement() {
    // Write 0x01 to the MEASUREMENT_CONFIG register (0x0E) to start a measurement
    if (i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Error writing to MEASUREMENT_CONFIG register\n");
        return -1;
    }
    return 0;
}

// Function to read the temperature and humidity data
int read_data(float *temperature, float *humidity) {
    uint16_t raw_temperature, raw_humidity;
    int retries = 0;
    int status;

    // Wait for the measurement to complete (bit 0 of MEASUREMENT_CONFIG is 0)
    while (retries < 100) {
        status = i2cReadByteData(i2c_handle, MEASUREMENT_CONFIG);
        if (status < 0) {
            fprintf(stderr, "Error reading MEASUREMENT_CONFIG register\n");
            return -1;
        }
        if ((status & 0x01) == 0) {
            break;
        }
        gpioDelay(1000); // Wait 1 ms
        retries++;
    }

    if (retries >= 100) {
        fprintf(stderr, "Timeout waiting for measurement completion\n");
        return -1;
    }

    // Read the temperature data (2 bytes)
    raw_temperature = i2cReadWordData(i2c_handle, TEMPERATURE_MSB);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    // Read the humidity data (2 bytes)
    raw_humidity = i2cReadWordData(i2c_handle, HUMIDITY_MSB);
    if (raw_humidity < 0) {
        fprintf(stderr, "Error reading humidity data\n");
        return -1;
    }

    // Convert the raw data to temperature and humidity
    *temperature = (float)raw_temperature / 65536.0 * 165.0 - 40.0;
    *humidity = (float)raw_humidity / 65536.0 * 100.0;

    return 0;
}

int main() {
    float temperature, humidity;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus 1
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the HDC2010 sensor
    if (init_hdc2010() != 0) {
        fprintf(stderr, "HDC2010 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Trigger a measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement\n");
        } else {
            // Read the temperature and humidity data
            if (read_data(&temperature, &humidity) == 0) {
                // Print the temperature and humidity values
                printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
            } else {
                fprintf(stderr, "Error reading data\n");
            }
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

