#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SDP800-500Pa I2C address
#define SDP800_ADDR 0x25

// Continuous measurement command
#define MEASURE_CMD 0x362F

// CRC polynomial
#define CRC_POLY 0x31

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_device();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(const uint8_t *data, int count);
int verify_crc(const uint8_t *data, int count, uint8_t crc);
sensor_data_t process_data(const uint8_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device() {
    int handle = i2cOpen(1, SDP800_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int count) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < count; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Verify CRC-8 checksum
int verify_crc(const uint8_t *data, int count, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, count);
    if (calculated_crc != crc) {
        fprintf(stderr, "CRC check failed: calculated = 0x%02X, expected = 0x%02X\n", calculated_crc, crc);
        return -1;
    }
    return 0;
}

// Process raw data
sensor_data_t process_data(const uint8_t *data) {
    sensor_data_t sensor_data;

    // Pressure data
    uint8_t pressure_data[2] = {data[0], data[1]};
    if (verify_crc(pressure_data, 2, data[2]) != 0) {
        sensor_data.pressure = 0; // Set to default value on CRC failure
    } else {
        sensor_data.pressure = (int16_t)((data[0] << 8) | data[1]);
    }

    // Temperature data
    uint8_t temperature_data[2] = {data[3], data[4]};
    if (verify_crc(temperature_data, 2, data[5]) != 0) {
        sensor_data.temperature = 0; // Set to default value on CRC failure
    } else {
        sensor_data.temperature = (int16_t)((data[3] << 8) | data[4]);
    }

    return sensor_data;
}

// Log sensor data
void log_data(sensor_data_t data) {
    printf("Pressure: %d, Temperature: %d\n", data.pressure, data.temperature);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c_device();
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Send continuous measurement command
    if (send_command(i2c_handle, MEASURE_CMD) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    uint8_t data[6];
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read data
        if (read_data(i2c_handle, data, 6) == 0) {
            // Process data
            sensor_data = process_data(data);

            // Log data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 us
    }

    // Cleanup resources
    cleanup();

    return 0;
}

