#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define PWM_PERIOD_US 1000000 // 1 Hz
#define PROFILE_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"

// PID Constants
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global Variables
static volatile int keep_running = 1;
static int spi_fd;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;
static FILE *log_file;

// Profile Data
static int profile_time[100]; // Assuming a maximum of 100 points
static float profile_temp[100];
static int profile_size = 0;

// Function Prototypes
int spi_init(void);
int gpio_init(void);
int read_temperature(void);
float calculate_pid(float setpoint, float actual_temp, float *integral, float *previous_error);
int set_relay_duty_cycle(float duty_cycle);
int load_profile(const char *filename);
int log_data(int time, float temperature, float setpoint, float pid_output);
void signal_handler(int sig);

// SPI Initialization
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI bits per word
    int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI max speed Hz
    int speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI max speed Hz");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// GPIO Initialization
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "reflow_oven";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Read Temperature from MAX6675
int read_temperature(void) {
    unsigned char tx_buf[1] = {0x00}; // Dummy byte for reading
    unsigned char rx_buf[2];
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 2,
        .speed_hz = 1000000, // 1 MHz
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    int raw_data = (rx_buf[0] << 8) | rx_buf[1];

    if (raw_data & 0x0004) {
        fprintf(stderr, "Thermocouple open circuit!\n");
        return -1;
    }

    if (raw_data & 0x0002) {
        fprintf(stderr, "Thermocouple shorted to GND!\n");
        return -1;
    }

    if (raw_data & 0x0001) {
        fprintf(stderr, "Thermocouple shorted to VCC!\n");
        return -1;
    }

    int temperature = (raw_data >> 3) * 0.25;
    return temperature;
}

// PID Controller
float calculate_pid(float setpoint, float actual_temp, float *integral, float *previous_error) {
    float error = setpoint - actual_temp;
    *integral += error;
    float derivative = error - *previous_error;
    float output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;

    // Clamp the output to the range [0.0, 1.0]
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

// Set Relay Duty Cycle
int set_relay_duty_cycle(float duty_cycle) {
    int pulse_width_us = (int)(duty_cycle * PWM_PERIOD_US);
    if (gpiod_line_set_value(gpio_line, 1) < 0) {
        perror("Error setting GPIO line value (high)");
        return -1;
    }
    usleep(pulse_width_us);
    if (gpiod_line_set_value(gpio_line, 0) < 0) {
        perror("Error setting GPIO line value (low)");
        return -1;
    }
    usleep(PWM_PERIOD_US - pulse_width_us);
    return 0;
}

// Load Profile from File
int load_profile(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening profile file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (profile_size >= 100) {
            fprintf(stderr, "Profile too large, ignoring remaining lines.\n");
            break;
        }
        if (sscanf(line, "%d,%f", &profile_time[profile_size], &profile_temp[profile_size]) == 2) {
            profile_size++;
        } else {
            fprintf(stderr, "Invalid line in profile file: %s", line);
        }
    }

    fclose(fp);
    return 0;
}

// Log Data to File
int log_data(int time, float temperature, float setpoint, float pid_output) {
    fprintf(log_file, "%d,%.2f,%.2f,%.2f\n", time, temperature, setpoint, pid_output);
    fflush(log_file);
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    keep_running = 0;
}

int main(void) {
    // Initialize
    if (spi_init() < 0) return 1;
    if (gpio_init() < 0) {
        close(spi_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Error opening log file");
        close(spi_fd);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    fprintf(log_file, "Time,Temperature,Setpoint,PID Output\n");

    if (load_profile(PROFILE_FILE) < 0) {
        fclose(log_file);
        close(spi_fd);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // PID Variables
    float integral = 0.0;
    float previous_error = 0.0;

    // Signal Handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main Loop
    int current_time = 0;
    int current_profile_index = 0;
    float setpoint = 0.0;

    while (keep_running) {
        // Update Setpoint
        if (current_profile_index < profile_size) {
            if (current_time >= profile_time[current_profile_index]) {
                setpoint = profile_temp[current_profile_index];
                current_profile_index++;
            }
        } else {
            setpoint = profile_temp[profile_size - 1]; // Keep the last setpoint
        }

        // Read Temperature
        int temperature = read_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value.\n");
            // Consider handling the error more gracefully, e.g., using a default value
        } else {
            // Calculate PID Output
            float pid_output = calculate_pid(setpoint, (float)temperature, &integral, &previous_error);

            // Set Relay Duty Cycle
            if (set_relay_duty_cycle(pid_output) < 0) {
                fprintf(stderr, "Error setting relay duty cycle.\n");
            }

            // Log Data
            log_data(current_time, (float)temperature, setpoint, pid_output);
        }

        // Wait for 1 second
        sleep(1);
        current_time++;
    }

    // Cleanup
    fclose(log_file);
    close(spi_fd);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);

