#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <stdbool.h>

// Configuration
#define HEATER_RELAY_GPIO 17
#define HEATER_PWM_GPIO 18
#define DHT22_GPIO 4
#define LIGHT_SENSOR_I2C_ADDR 0x23
#define LOG_FILE "greenhouse.log"
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1024

// Global variables (minimize usage)
static volatile int running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *heater_relay_line = NULL;
static struct gpiod_line *heater_pwm_line = NULL;
static int dht22_fd = -1;
static int light_sensor_fd = -1;

// PID gains
static float Kp = 1.0;
static float Ki = 0.1;
static float Kd = 0.01;

// Setpoint temperature
static float setpoint = 25.0;

// PID variables
static float integral = 0.0;
static float previous_error = 0.0;

// Function prototypes
float read_temperature();
float read_light_level();
float calculate_pid(float setpoint, float actual_temperature, float light_level);
void set_heater_pwm(float duty_cycle);
void log_data(float temperature, float light_level, float pid_output, float duty_cycle);
void signal_handler(int sig);
int initialize_gpio();
int initialize_i2c();
void cleanup();
bool dht22_read(float *temperature, float *humidity);

// CRC-8-H2F checksum function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x07;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from DS18B20 sensor
float read_temperature() {
    char filepath[100];
    snprintf(filepath, sizeof(filepath), "/sys/bus/w1/devices/28-*/w1_slave");
    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    char line1[256], line2[256];
    if (fgets(line1, sizeof(line1), fp) == NULL || fgets(line2, sizeof(line2), fp) == NULL) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        fclose(fp);
        return -1000.0;
    }
    fclose(fp);

    // CRC check
    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "CRC check failed\n");
        return -1000.0;
    }

    // Extract temperature
    char *temp_str = strstr(line2, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found\n");
        return -1000.0;
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    return (float)temp_raw / 1000.0;
}

// Function to read light level from BH1750 sensor
float read_light_level() {
    int light_level = wiringPiI2CReadReg16(light_sensor_fd, 0x10); // Read light level
    if (light_level < 0) {
        fprintf(stderr, "Error reading light level: %s\n", strerror(errno));
        return -1.0;
    }
    return (float)light_level;
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature, float light_level) {
    float error = setpoint - actual_temperature;
    integral += error;
    float derivative = error - previous_error;
    float output = (Kp * error) + (Ki * integral) + (Kd * derivative);
    previous_error = error;

    // Clamp output to 0-100
    if (output < 0) output = 0;
    if (output > 100) output = 100;

    return output;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(float duty_cycle) {
    int pwm_value = (int)(duty_cycle * PWM_RANGE / 100.0);
    if (pwm_value < 0) pwm_value = 0;
    if (pwm_value > PWM_RANGE) pwm_value = PWM_RANGE;

    if (pwm_value > 0) {
        gpiod_line_set_value(heater_relay_line, 1); // Turn on relay
    } else {
        gpiod_line_set_value(heater_relay_line, 0); // Turn off relay
    }

    // Set PWM duty cycle (using wiringPi directly)
    pwmWrite(HEATER_PWM_GPIO, pwm_value);
}

// Function to log data to file
void log_data(float temperature, float light_level, float pid_output, float duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f, %.2f, %.2f, %.2f, %.2f\n",
            timestamp, temperature, setpoint, pid_output, light_level, duty_cycle);
    fflush(log_file); // Ensure data is written to disk
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("Received signal %d, shutting down...\n", sig);
}

// Initialize GPIO using gpiod
int initialize_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    heater_relay_line = gpiod_chip_get_line(gpio_chip, HEATER_RELAY_GPIO);
    heater_pwm_line = gpiod_chip_get_line(gpio_chip, HEATER_PWM_GPIO);

    if (!heater_relay_line || !heater_pwm_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(heater_relay_line, "greenhouse", 0) < 0) {
        fprintf(stderr, "Error requesting relay GPIO: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(heater_pwm_line, "greenhouse", 0) < 0) {
        fprintf(stderr, "Error requesting PWM GPIO: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Initialize I2C for BH1750 sensor
int initialize_i2c() {
    light_sensor_fd = wiringPiI2CSetup(LIGHT_SENSOR_I2C_ADDR);
    if (light_sensor_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");

    // Turn off heater
    if (heater_relay_line) {
        gpiod_line_set_value(heater_relay_line, 0);
        gpiod_line_release(heater_relay_line);
    }
    if (heater_pwm_line) {
        gpiod_line_release(heater_pwm_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    // Close I2C
    if (light_sensor_fd != -1) {
        // No specific I2C close function in wiringPi, just set to -1
        light_sensor_fd = -1;
    }

    printf("Cleanup complete. Exiting.\n");
}

// DHT22 read function using bit-banging
bool dht22_read(float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = HIGH;
    int j = 0;

    // Set pin to output
    pinMode(DHT22_GPIO, OUTPUT);
    digitalWrite(DHT22_GPIO, HIGH);
    delay(10);
    digitalWrite(DHT22_GPIO, LOW);
    delay(18); // > 18ms
    digitalWrite(DHT22_GPIO, HIGH);
    delayMicroseconds(40);
    pinMode(DHT22_GPIO, INPUT);

    // Read data
    for (int i = 0; i < 85; i++) {
        int counter = 0;
        while (digitalRead(DHT22_GPIO) == laststate) {
            counter++;
            delayMicroseconds(1);
            if (counter == 255) {
                return false; // Timeout
            }
        }
        laststate = digitalRead(DHT22_GPIO);

        if (counter > 3) {
            data[j / 8] <<= 1;
            if (counter > 16) data[j / 8] |= 1;
            j++;
        }
    }

    // Check checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return false; // Checksum failure
    }

    // Convert data to temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1;
