#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define AHT20_ADDR 0x38
#define DEHUMIDIFIER_GPIO 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define AHT20_INIT_CMD_1 0xBE
#define AHT20_INIT_CMD_2 0x08
#define AHT20_INIT_CMD_3 0x00
#define AHT20_MEASURE_CMD_1 0xAC
#define AHT20_MEASURE_CMD_2 0x33
#define AHT20_MEASURE_CMD_3 0x00
#define AHT20_CALIBRATED_STATUS 0x08
#define AHT20_NOT_BUSY_STATUS 0x00
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10
#define POLL_INTERVAL_SEC 5

// Global variables
static int i2c_fd = -1;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int aht20_init(int i2c_fd);
int aht20_measure(int i2c_fd, float *humidity);
int gpio_init(void);
int gpio_set_state(int state);
void log_data(float humidity);
void signal_handler(int sig);
void cleanup(void);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up...\n");
    if (gpio_line) {
        gpio_set_state(0); // Turn off dehumidifier
        gpiod_line_release(gpio_line);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    gpioTerminate();
}

// AHT20 initialization function
int aht20_init(int i2c_fd) {
    uint8_t init_cmd[] = {AHT20_INIT_CMD_1, AHT20_INIT_CMD_2, AHT20_INIT_CMD_3};
    int retries = I2C_RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = write(i2c_fd, init_cmd, sizeof(init_cmd));
        if (result == sizeof(init_cmd)) {
            usleep(100000); // Wait 100ms
            return 0; // Success
        } else {
            fprintf(stderr, "Error initializing AHT20: %s\n", strerror(errno));
            retries--;
            usleep(I2C_RETRY_DELAY_MS * 1000); // Delay before retry
        }
    }
    return -1; // Failure
}

// AHT20 measurement function
int aht20_measure(int i2c_fd, float *humidity) {
    uint8_t measure_cmd[] = {AHT20_MEASURE_CMD_1, AHT20_MEASURE_CMD_2, AHT20_MEASURE_CMD_3};
    uint8_t data[6];
    int retries = I2C_RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = write(i2c_fd, measure_cmd, sizeof(measure_cmd));
        if (result == sizeof(measure_cmd)) {
            usleep(80000); // Wait 80ms

            result = read(i2c_fd, data, sizeof(data));
            if (result == sizeof(data)) {
                // Verify status
                if ((data[0] & 0x7F) == AHT20_CALIBRATED_STATUS && (data[1] & 0x80) == AHT20_NOT_BUSY_STATUS) {
                    // Calculate humidity
                    uint32_t humidity_raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
                    *humidity = ((float)humidity_raw / 0x100000) * 100;
                    return 0; // Success
                } else {
                    fprintf(stderr, "AHT20 not calibrated or busy. Status: 0x%02X\n", data[0]);
                    return -1; // Status error
                }
            } else {
                fprintf(stderr, "Error reading AHT20 data: %s\n", strerror(errno));
            }
        } else {
            fprintf(stderr, "Error triggering AHT20 measurement: %s\n", strerror(errno));
        }
        retries--;
        usleep(I2C_RETRY_DELAY_MS * 1000); // Delay before retry
    }
    return -1; // Failure
}

// GPIO initialization function
int gpio_init(void) {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    gpio_line = gpiod_chip_get_line(chip, DEHUMIDIFIER_GPIO);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(gpio_line, "dehumidifier", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// GPIO state setting function
int gpio_set_state(int state) {
    int ret;

    if (!gpio_line) {
        fprintf(stderr, "GPIO line not initialized\n");
        return -1;
    }

    ret = gpiod_line_set_value(gpio_line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO state: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Data logging function
void log_data(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("%s Humidity: %.2f%%\n", timestamp, humidity);
}

int main(void) {
    float humidity;
    int dehumidifier_state = 0; // 0 = off, 1 = on

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize AHT20 sensor
    if (aht20_init(i2c_fd) != 0) {
        fprintf(stderr, "AHT20 initialisation failed\n");
        cleanup();
        return 1;
    }

    printf("AHT20 sensor initialized. Monitoring humidity...\n");

    // Main loop
    while (!terminate) {
        // Measure humidity
        if (aht20_measure(i2c_fd, &humidity) == 0) {
            log_data(humidity);

            // Control dehumidifier
            if (humidity > HUMIDITY_THRESHOLD_HIGH && dehumidifier_state == 0) {
                if (gpio_set_state(1) == 0) {
                    dehumidifier_state = 1;
                    printf("Dehumidifier turned ON\n");
                }
            } else if (humidity < HUMIDITY_THRESHOLD_LOW && dehumidifier_state == 1) {
                if (gpio_set_state(0) == 0) {
                    dehumidifier_state = 0;
                    printf("Dehumidifier turned OFF\n");
                }
            }
        } else {
            fprintf(stderr, "Error measuring humidity\n");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

