#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define API_ENDPOINT "http://api.example.com/humidity"
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 80

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    keep_running = 0;
}

int i2c_read_bytes(int fd, unsigned char reg, unsigned char *buf, int len) {
    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave.");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C device.");
        return -1;
    }

    if (read(fd, buf, len) != len) {
        syslog(LOG_ERR, "Failed to read from I2C device.");
        return -1;
    }

    return 0;
}

int i2c_write_byte(int fd, unsigned char data) {
    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave.");
        return -1;
    }

    if (write(fd, &data, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C device.");
        return -1;
    }

    return 0;
}

float read_humidity(int fd) {
    unsigned char buf[3];
    unsigned int raw_humidity;

    if (i2c_write_byte(fd, 0xE5) < 0) {
        syslog(LOG_ERR, "Failed to trigger humidity measurement.");
        return -1.0;
    }
    usleep(100000); // Wait for measurement (at least 50ms)

    if (i2c_read_bytes(fd, 0xE3, buf, 3) < 0) {
        syslog(LOG_ERR, "Failed to read humidity data.");
        return -1.0;
    }

    raw_humidity = (buf[0] << 8) | buf[1];
    raw_humidity &= 0xFFFC; // Clear status bits

    // CRC Check
    unsigned char crc = buf[2];
    unsigned char calculated_crc = 0x00;
    unsigned char data[2] = {buf[0], buf[1]};

    for (int i = 0; i < 16; i++) {
        calculated_crc <<= 1;
        if (data[i / 8] & (1 << (7 - (i % 8))))
            calculated_crc ^= 0x131; // Polynomial X^8 + X^5 + X^4 + 1
        if (calculated_crc & 0x100)
            calculated_crc ^= 0x131;
    }

    if (crc != calculated_crc) {
        syslog(LOG_ERR, "CRC mismatch!");
        return -1.0;
    }

    float humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);
    return humidity;
}

int post_data(const char *url, const char *data) {
    int sockfd;
    struct sockaddr_in servaddr;
    char response[1024];

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);

    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection Failed");
        close(sockfd);
        return -1;
    }

    char request[2048];
    snprintf(request, sizeof(request), "POST %s HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s",
             url, SERVER_IP, strlen(data), data);

    if (send(sockfd, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Send failed");
        close(sockfd);
        return -1;
    }

    ssize_t bytes_received = recv(sockfd, response, sizeof(response) - 1, 0);
    if (bytes_received < 0) {
        syslog(LOG_ERR, "Receive failed");
        close(sockfd);
        return -1;
    }
    response[bytes_received] = '\0';

    close(sockfd);

    // Basic response parsing (check for 200 OK)
    if (strstr(response, "200 OK") == NULL) {
        syslog(LOG_ERR, "HTTP POST failed: %s", response);
        return -1;
    }

    return 0;
}

int main() {
    openlog("humidity_sensor", LOG_PID, LOG_USER);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus.");
        closelog();
        return 1;
    }

    while (keep_running) {
        float humidity = read_humidity(i2c_fd);
        if (humidity >= 0.0) {
            char json_data[128];
            snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

            if (post_data(API_ENDPOINT, json_data) == 0) {
                syslog(LOG_INFO, "Humidity data posted successfully: %.2f", humidity);
            } else {
                syslog(LOG_ERR, "Failed to post humidity data.");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity.");
        }

        sleep(60);
    }

    close(i2c_fd);
    closelog();
    return 0;
}

