#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_CALIB_START 0x88
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

// Global variables
int i2c_handle;
bmp280_calib_data calib;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_chip_id();
int read_calibration_data(bmp280_calib_data *calib);
int trigger_measurement();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib);
double compensate_pressure(int32_t raw_pressure, int32_t raw_temperature, bmp280_calib_data calib);
void log_pressure_breach(double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify BMP280 chip ID
int verify_chip_id() {
    int chip_id;
    int retries = 3;

    while (retries > 0) {
        chip_id = i2cReadByteData(i2c_handle, BMP280_REG_CHIPID);
        if (chip_id >= 0) {
            if (chip_id == 0x58) {
                return 0; // Success
            } else {
                fprintf(stderr, "Error: Invalid chip ID: 0x%X\n", chip_id);
                return -1; // Failure
            }
        } else {
            fprintf(stderr, "Error reading chip ID: %d, retrying...\n", chip_id);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    return -1; // All retries failed
}

// Read calibration data from BMP280
int read_calibration_data(bmp280_calib_data *calib) {
    char data[24];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_START, data, 24) == 24) {
            calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
            calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
            calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
            calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
            calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
            calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
            calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
            calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
            calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
            calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
            calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
            calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading calibration data: %d, retrying...\n", i2c_handle);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    return -1; // All retries failed
}

// Trigger a single measurement
int trigger_measurement() {
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27); // Oversampling x1, forced mode
        if (result >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error triggering measurement: %d, retrying...\n", result);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    return -1; // All retries failed
}

// Read raw temperature and pressure data
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    char data[6];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, data, 6) == 6) {
            *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
            *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading raw data: %d, retrying...\n", i2c_handle);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    return -1; // All retries failed
}

// Compensate temperature
double compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib) {
    double var1, var2, T;
    double T1 = (double)calib.dig_T1;
    double T2 = (double)calib.dig_T2;
    double T3 = (double)calib.dig_T3;

    var1 = (((double)raw_temperature / 16384.0) - (T1 / 1024.0)) * (T2);
    var2 = ((((double)raw_temperature / 131072.0) - (T1 / 8192.0)) * (((double)raw_temperature / 131072.0) - (T1 / 8192.0))) * (T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure
double compensate_pressure(int32_t raw_pressure, int32_t raw_temperature, bmp280_calib_data calib) {
    double var1, var2, p;
    double T1 = (double)calib.dig_T1;
    double T2 = (double)calib.dig_T2;
    double T3 = (double)calib.dig_T3;
    double P1 = (double)calib.dig_P1;
    double P2 = (double)calib.dig_P2;
    double P3 = (double)calib.dig_P3;
    double P4 = (double)calib.dig_P4;
    double P5 = (double)calib.dig_P5;
    double P6 = (double)calib.dig_P6;
