int log_data(float temperature, float humidity, int motion_detected);
int create_log_file(void);
void close_resources(void);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, exiting gracefully.\n", sig);
        keep_running = 0;
    }
}

// Initialize I2C
int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    pir_line = gpiod_chip_get_line(gpio_chip, PIR_GPIO);
    if (!pir_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_input(pir_line, "pir_input") < 0) {
        perror("Error requesting GPIO line as input");
        gpiod_chip_close(gpio_chip);
        return -1;
    }
    return 0;
}

// Detect sensors
int detect_sensors(void) {
    int tmp117_detected = 0;
    int aht20_detected = 0;
    int retries = 3;
    int delay_ms = 10;
    unsigned char buf[1];

    // Detect TMP117
    while (retries > 0) {
        if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
            perror("Error setting I2C slave address for TMP117");
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }
        tmp117_detected = 1;
        break;
    }

    if (!tmp117_detected) {
        fprintf(stderr, "Warning: TMP117 sensor not detected.\n");
    }

    retries = 3;
    delay_ms = 10;

    // Detect AHT20
    while (retries > 0) {
        if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
            perror("Error setting I2C slave address for AHT20");
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        // Send init command
        buf[0] = 0xBE;
        if (write(i2c_fd, buf, 1) != 1) {
            perror("Error writing init command to AHT20");
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }
        buf[0] = 0x08;
        if (write(i2c_fd, buf, 1) != 1) {
            perror("Error writing init command to AHT20");
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }
        buf[0] = 0x00;
        if (write(i2c_fd, buf, 1) != 1) {
            perror("Error writing init command to AHT20");
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }
        aht20_detected = 1;
        break;
    }

    if (!aht20_detected) {
        fprintf(stderr, "Warning: AHT20 sensor not detected.\n");
    }

    return (tmp117_detected && aht20_detected) ? 0 : -1;
}

// Read temperature from TMP117
int read_tmp117(float *temperature) {
    int retries = 3;
    int delay_ms = 10;
    unsigned char buf[2];
    int16_t raw_temp;

    while (retries > 0) {
        if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
            perror("Error setting I2C slave address for TMP117");
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        // Read temperature register
        if (write(i2c_fd, "\x00", 1) != 1) {
            perror("Error writing to TMP117");
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        if (read(i2c_fd, buf, 2) != 2) {
            perror("Error reading from TMP117");
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        raw_temp = (buf[0] << 8) | buf[1];
        *temperature = raw_temp * 0.0078125;
        return 0;
    }
    return -1;
}

// Read humidity and temperature from AHT20
int read_aht20(float *humidity, float *temperature) {
    int retries = 3;
    int delay_ms = 10;
    unsigned char buf[7];
    unsigned char measure_cmd[3] = {0xAC, 0x33, 0x00};
    int32_t raw_humidity, raw_temperature;

    while (retries > 0) {
        if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
            perror("Error setting I2C slave address for AHT20");
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        // Send measure command
        if (write(i2c_fd, measure_cmd, 3) != 3) {
            perror("Error writing measure command to AHT20");
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        // Wait for measurement to complete (at least 80ms)
        usleep(80000);

        // Read data
        if (read(i2c_fd, buf, 7) != 7) {
            perror("Error reading from AHT20");
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        // Check busy bit
        if (buf[0] & 0x80) {
            fprintf(stderr, "AHT20 busy\n");
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        // Convert data
        raw_humidity = ((unsigned int)buf[1] << 12) | ((unsigned int)buf[2] << 4) | (buf[3] >> 4);
        raw_temperature = ((unsigned int)buf[3] & 0x0F) << 16 | ((unsigned int)buf[4] << 8) | buf[5];

        *humidity = ((float)raw_humidity / 0x100000) * 100;
        *temperature = ((float)raw_temperature / 0x100000) * 200 - 50;
        return 0;
    }
    return -1;
}

// Read motion from PIR sensor
int read_pir(int *motion_detected) {
    if (!pir_line) {
        fprintf(stderr, "PIR line not initialized.\n");
        return -1;
    }

    *motion_detected = gpiod_line_get_value(pir_line);
    if (*motion_detected < 0) {
        perror("Error reading PIR sensor");
        return -1;
    }
    return 0;
}

