#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define motor run duration (seconds)
#define MOTOR_RUN_DURATION 5

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *rain_sensor_line;
struct gpiod_line *motor_enable_line;
struct gpiod_line *motor_in1_line;
struct gpiod_line *motor_in2_line;

// Function prototypes
int read_rain_sensor(struct gpiod_line *line);
int control_motor(struct gpiod_line *enable_line, struct gpiod_line *in1_line, struct gpiod_line *in2_line, int duration);
void log_event(const char *message);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    log_event("Signal received, stopping motor and exiting...");

    // Stop the motor
    if (motor_enable_line) {
        gpiod_line_set_value(motor_enable_line, 0);
    }

    // Release GPIO lines
    if (rain_sensor_line) {
        gpiod_line_release(rain_sensor_line);
    }
    if (motor_enable_line) {
        gpiod_line_release(motor_enable_line);
    }
    if (motor_in1_line) {
        gpiod_line_release(motor_in1_line);
    }
    if (motor_in2_line) {
        gpiod_line_release(motor_in2_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read the rain sensor value
int read_rain_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        log_event("Error reading rain sensor value");
        return -1; // Indicate error
    }
    return value;
}

// Function to control the motor
int control_motor(struct gpiod_line *enable_line, struct gpiod_line *in1_line, struct gpiod_line *in2_line, int duration) {
    // Set direction to forward
    if (gpiod_line_set_value(in1_line, 1) < 0) {
        log_event("Error setting IN1 pin value");
        return -1;
    }
    if (gpiod_line_set_value(in2_line, 0) < 0) {
        log_event("Error setting IN2 pin value");
        return -1;
    }

    // Enable the motor
    if (gpiod_line_set_value(enable_line, 1) < 0) {
        log_event("Error setting ENA pin value");
        return -1;
    }

    log_event("Motor started");

    // Run for specified duration
    sleep(duration);

    // Disable the motor
    if (gpiod_line_set_value(enable_line, 0) < 0) {
        log_event("Error setting ENA pin value");
        return -1;
    }

    log_event("Motor stopped");

    return 0;
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    rain_sensor_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    motor_enable_line = gpiod_chip_get_line(chip, MOTOR_ENABLE_PIN);
    motor_in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    motor_in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);

    if (!rain_sensor_line || !motor_enable_line || !motor_in1_line || !motor_in2_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "rain_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(rain_sensor_line, &config, 0) < 0) {
        perror("Error requesting rain sensor line");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request(motor_enable_line, &config, 0) < 0) {
        perror("Error requesting motor enable line");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request(motor_in1_line, &config, 0) < 0) {
        perror("Error requesting motor IN1 line");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request(motor_in2_line, &config, 0) < 0) {
        perror("Error requesting motor IN2 line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int rain_detected = read_rain_sensor(rain_sensor_line);
        if (rain_detected == 0) {
            log_event("Rain detected!");
            if (control_motor(motor_enable_line, motor_in1_line, motor_in2_line, MOTOR_RUN_DURATION) == 0) {
                log_event("Window closed");
            } else {
                log_event("Error controlling motor");
            }
        } else if (rain_detected > 0) {
            // No rain detected, do nothing
        } else {
            log_event("Error reading rain sensor, retrying...");
        }

        sleep(2); // Poll every 2 seconds
    }

    return 0;
}

