#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to read CPU usage from /proc/stat
int read_cpu_usage(unsigned long *user, unsigned long *nice, unsigned long *system, unsigned long *idle, unsigned long *iowait, unsigned long *irq, unsigned long *softirq, unsigned long *steal, unsigned long *guest, unsigned long *guest_nice) {
    FILE *fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        perror("Error reading /proc/stat");
        return -1;
    }

    if (sscanf(line, "cpu  %lu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
               user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice) != 10) {
        fclose(fp);
        fprintf(stderr, "Error parsing /proc/stat\n");
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to calculate CPU load percentage
float calculate_cpu_load(unsigned long prev_user, unsigned long prev_nice, unsigned long prev_system, unsigned long prev_idle, unsigned long prev_iowait, unsigned long prev_irq, unsigned long prev_softirq, unsigned long prev_steal, unsigned long prev_guest, unsigned long prev_guest_nice,
                          unsigned long curr_user, unsigned long curr_nice, unsigned long curr_system, unsigned long curr_idle, unsigned long curr_iowait, unsigned long curr_irq, unsigned long curr_softirq, unsigned long curr_steal, unsigned long curr_guest, unsigned long curr_guest_nice) {
    unsigned long prev_total = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal + prev_guest + prev_guest_nice;
    unsigned long curr_total = curr_user + curr_nice + curr_system + curr_idle + curr_iowait + curr_irq + curr_softirq + curr_steal + curr_guest + curr_guest_nice;

    unsigned long prev_idle_all = prev_idle + prev_iowait;
    unsigned long curr_idle_all = curr_idle + curr_iowait;

    unsigned long totald = curr_total - prev_total;
    unsigned long idled = curr_idle_all - prev_idle_all;

    float cpu_usage = (float)(totald - idled) / totald;

    return cpu_usage * 100.0;
}

// Function to map CPU load to RGB color values
void map_load_to_color(float cpu_load, int *red, int *green, int *blue) {
    if (cpu_load <= 50.0) {
        // Green to Yellow
        *red = (int)(cpu_load / 50.0 * 255.0);
        *green = 255;
        *blue = 0;
    } else {
        // Yellow to Red
        *red = 255;
        *green = 255 - (int)((cpu_load - 50.0) / 50.0 * 255.0);
        *blue = 0;
    }
}

// Function to set the RGB LED color using pigpio
void set_led_color(int red, int green, int blue) {
    // Common anode, so invert the PWM values
    gpioPWM(RED_PIN, 255 - red);
    gpioPWM(GREEN_PIN, 255 - green);
    gpioPWM(BLUE_PIN, 255 - blue);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Set PWM frequency (e.g., 1000 Hz)
    gpioSetPWMfrequency(RED_PIN, 1000);
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Variables for CPU usage
    unsigned long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    unsigned long curr_user, curr_nice, curr_system, curr_idle, curr_iowait, curr_irq, curr_softirq, curr_steal, curr_guest, curr_guest_nice;
    float cpu_load;
    int red, green, blue;

    // Read initial CPU usage
    if (read_cpu_usage(&prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read current CPU usage
        if (read_cpu_usage(&curr_user, &curr_nice, &curr_system, &curr_idle, &curr_iowait, &curr_irq, &curr_softirq, &curr_steal, &curr_guest, &curr_guest_nice) != 0) {
            break; // Exit loop on error
        }

        // Calculate CPU load
        cpu_load = calculate_cpu_load(prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice,
                                      curr_user, curr_nice, curr_system, curr_idle, curr_iowait, curr_irq, curr_softirq, curr_steal, curr_guest, curr_guest_nice);

        // Map CPU load to RGB color
        map_load_to_color(cpu_load, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Update previous CPU usage
        prev_user = curr_user;
        prev_nice = curr_nice;
        prev_system = curr_system;
        prev_idle = curr_idle;
        prev_iowait = curr_iowait;
        prev_irq = curr_irq;
        prev_softirq = curr_softirq;
        prev_steal = curr_steal;
        prev_guest = curr_guest;
        prev_guest_nice = curr_guest_nice;

        // Sleep for 500 ms
        usleep(500000); // 500 ms = 500000 microseconds
    }

    // Turn off the LED
    set_led_color(0, 0, 0);

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

