#include <pigpio.h>

// Define constants
#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define BUFFER_SIZE 20

// Structure for logging data
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} LogEntry;

// Global variables
int spi_handle;
LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_max31855(float *temperature);
int calculate_duty_cycle(float temperature);
void log_data(float temperature, int duty_cycle);
void print_log_buffer();
void signal_handler(int signal);

// Function to read temperature from MAX31855
int read_max31855(float *temperature) {
    unsigned char buffer[4];
    int result;

    result = spiXfer(spi_handle, buffer, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error: spiXfer failed (%d)\n", result);
        return -1;
    }

    // Check for fault bits
    if (buffer[3] & 0x01) {
        fprintf(stderr, "Error: MAX31855 fault detected (OC)\n");
        return -1;
    }
    if (buffer[3] & 0x02) {
        fprintf(stderr, "Error: MAX31855 fault detected (SCG)\n");
        return -1;
    }
    if (buffer[3] & 0x04) {
        fprintf(stderr, "Error: MAX31855 fault detected (SCV)\n");
        return -1;
    }

    // Extract thermocouple temperature
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 2;
    *temperature = raw_temp * 0.25;

    return 0;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle = 0;

    if (temperature < 25.0) {
        duty_cycle = 0;
    } else if (temperature >= 25.0 && temperature < 40.0) {
        duty_cycle = (int)((temperature - 25.0) / (40.0 - 25.0) * 50.0);
    } else if (temperature >= 40.0 && temperature < 60.0) {
        duty_cycle = 50 + (int)((temperature - 40.0) / (60.0 - 40.0) * 150.0);
    } else {
        duty_cycle = 200;
    }

    if (duty_cycle > 255) {
        duty_cycle = 255;
    }

    return duty_cycle;
}

// Function to log data to the circular buffer
void log_data(float temperature, int duty_cycle) {
    time_t now = time(NULL);
    log_buffer[buffer_index].timestamp = now;
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].duty_cycle = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_log_buffer() {
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Correct order
        struct tm *timeinfo = localtime(&log_buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Temperature: %.2f°C, Duty Cycle: %d\n", timestamp_str, log_buffer[index].temperature, log_buffer[index].duty_cycle);
    }
    printf("--- End of Log Buffer ---\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 to PWM output mode
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency to 1 kHz
    gpioSetPWMfrequency(FAN_GPIO, 1000);

    // Set PWM range to 255
    gpioSetPWMrange(FAN_GPIO, 255);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature;
    int duty_cycle;

    // Main loop
    while (program_running) {
        if (read_max31855(&temperature) == 0) {
            duty_cycle = calculate_duty_cycle(temperature);
            gpioPWM(FAN_GPIO, duty_cycle);
            log_data(temperature, duty_cycle);
            printf("Temperature: %.2f°C, Duty Cycle: %d\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "Error: Failed to read temperature\n");
        }

        sleep(1);
    }

    // Stop PWM
    gpioPWM(FAN_GPIO, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Print log buffer
    print_log_buffer();

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

