// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 // OSS = 0
#define BMP180_CMD_PRESSURE1 0x74 // OSS = 1
#define BMP180_CMD_PRESSURE2 0xB4 // OSS = 2
#define BMP180_CMD_PRESSURE3 0xF4 // OSS = 3

// Oversampling setting (OSS)
#define OSS 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t logging_enabled = 0;

// Calibration data
short ac1, ac2, ac3, b1, b2, mb, mc, md;
unsigned short ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(long *raw_temp);
int read_raw_pressure(long *raw_pressure);
double calculate_temperature(long raw_temp);
double calculate_pressure(long raw_pressure, long raw_temp);
int log_data(double temperature, double pressure);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to read a short (2 bytes) from I2C
int read_short(int handle, char reg, short *value)
{
    char buf[2];
    if (i2cWriteDevice(handle, &reg, 1) != 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read an unsigned short (2 bytes) from I2C
int read_ushort(int handle, char reg, unsigned short *value)
{
    char buf[2];
    if (i2cWriteDevice(handle, &reg, 1) != 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data()
{
    if (read_short(i2c_handle, 0xAA, &ac1) != 0) return -1;
    if (read_short(i2c_handle, 0xAC, &ac2) != 0) return -1;
    if (read_short(i2c_handle, 0xAE, &ac3) != 0) return -1;
    if (read_ushort(i2c_handle, 0xB0, &ac4) != 0) return -1;
    if (read_ushort(i2c_handle, 0xB2, &ac5) != 0) return -1;
    if (read_ushort(i2c_handle, 0xB4, &ac6) != 0) return -1;
    if (read_short(i2c_handle, 0xB6, &b1) != 0) return -1;
    if (read_short(i2c_handle, 0xB8, &b2) != 0) return -1;
    if (read_short(i2c_handle, 0xBA, &mb) != 0) return -1;
    if (read_short(i2c_handle, 0xBC, &mc) != 0) return -1;
    if (read_short(i2c_handle, 0xBE, &md) != 0) return -1;

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(long *raw_temp)
{
    char buf[1];
    buf[0] = BMP180_CMD_TEMP;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) return -1;
    gpioDelay(5000); // Wait 5ms

    char reg = BMP180_REG_MSB;
    char data[2];
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) return -1;
    if (i2cReadDevice(i2c_handle, data, 2) != 2) return -1;

    *raw_temp = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data from BMP180
int read_raw_pressure(long *raw_pressure)
{
    char buf[1];
    buf[0] = BMP180_CMD_PRESSURE3; // OSS = 3
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) return -1;
    gpioDelay(26000); // Wait 26ms

    char reg = BMP180_REG_MSB;
    char data[3];
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) return -1;
    if (i2cReadDevice(i2c_handle, data, 3) != 3) return -1;

    *raw_pressure = ((long)data[0] << 16 | (long)data[1] << 8 | (long)data[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate temperature in Celsius
double calculate_temperature(long raw_temp)
{
    long X1 = ((raw_temp - (long)ac6) * (long)ac5) >> 15;
    long X2 = ((long)mc << 11) / (X1 + md);
    long B5 = X1 + X2;
    double temperature = ((B5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(long raw_pressure, long raw_temp)
{
    long X1 = ((raw_temp - (long)ac6) * (long)ac5) >> 15;
    long X2 = ((long)mc << 11) / (X1 + md);
    long B5 = X1 + X2;

    long B6 = B5 - 4000;
    long X3 = ((long)b2 * (B6 * B6) >> 12) >> 11;
    long X4 = ((long)ac2 * B6) >> 11;
    long B3 = (((((long)ac1) * 4 + X3) << OSS) + 2) >> 2;

    unsigned long X1_pressure = ((unsigned long)ac3 * B6) >> 13;
    unsigned long X2_pressure = ((unsigned long)b1 * ((B6 * B6) >> 12)) >> 16;
    unsigned long B4 = X1_pressure + X2_pressure + 32768;
    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> OSS);

    long pressure;
    if (B7 < 0x80000000)
    {
        pressure = (B7 * 2) / B4;
    }
    else
    {
        pressure = (B7 / B4) * 2;
    }

    X1 = (pressure >> 8) * (pressure >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * pressure) >> 16;
    pressure = pressure + ((X1 + X2 + 3791) >> 4);

    return pressure;
}

// Function to log data to file
int log_data(double temperature, double pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure) < 0)
    {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user)
{
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully...\n", signal);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main()
