        gpioTerminate();
        return 1;
    }

    // Configure GPIO2 as input with pull-up enabled
    gpioSetMode(2, PI_INPUT);
    gpioSetPullUpDown(2, PI_PUD_UP);

    // Set interrupt handler for falling edge on GPIO2
    if (gpioSetISRFuncEx(2, FALLING_EDGE, 0, interrupt_handler, NULL) != 0)
    {
        fprintf(stderr, "Error setting interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Data logging is initially disabled.  Toggling GPIO2 will enable/disable logging.\n");

    // Main loop
    while (1)
    {
        if (logging_enabled)
        {
            long raw_temp, raw_pressure;
            double temperature, pressure;

            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0)
