#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8
#define LOG_FILE "rtd_log.csv"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define RTD_NOMINAL_RESISTANCE 100.0
#define RREF 430.0
#define A 0.0039083
#define B -0.0000005775
#define C 0.0000000000039866

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, int mode, int bits, int speed);
int gpio_init(const char *chip, int pin);
int read_max31865_register(int fd, unsigned char reg);
int write_max31865_register(int fd, unsigned char reg, unsigned char value);
int read_rtd_data(int fd, unsigned int *rtd_raw);
double calculate_temperature(unsigned int rtd_raw);
int log_data(FILE *fp, double temperature);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, int mode, int bits, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// GPIO initialization function
int gpio_init(const char *chip, int pin) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "max31865";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    gpio_chip = gpiod_chip_open_by_name(chip);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request(gpio_line, &config, 1) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to read a register from MAX31865
int read_max31865_register(int fd, unsigned char reg) {
    unsigned char tx_buf[2];
    unsigned char rx_buf[2];
    struct spi_ioc_transfer tr;

    tx_buf[0] = reg | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00;       // Dummy byte for reading

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 2;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    if (gpiod_line_set_value(gpio_line, 0) < 0) {
        perror("Error setting CS low");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error sending SPI message");
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            perror("Error setting CS high");
        }
        return -1;
    }

    if (gpiod_line_set_value(gpio_line, 1) < 0) {
        perror("Error setting CS high");
        return -1;
    }

    return rx_buf[1];
}

// Function to write a register to MAX31865
int write_max31865_register(int fd, unsigned char reg, unsigned char value) {
    unsigned char tx_buf[2];
    struct spi_ioc_transfer tr;

    tx_buf[0] = reg & 0x7F; // Clear MSB for write operation
    tx_buf[1] = value;

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = 0; // Not used for write
    tr.len = 2;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    if (gpiod_line_set_value(gpio_line, 0) < 0) {
        perror("Error setting CS low");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error sending SPI message");
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            perror("Error setting CS high");
        }
        return -1;
    }

    if (gpiod_line_set_value(gpio_line, 1) < 0) {
        perror("Error setting CS high");
        return -1;
    }

    return 0;
}

// Function to read RTD data from MAX31865
int read_rtd_data(int fd, unsigned int *rtd_raw) {
    int rtd_msb = read_max31865_register(fd, 0x01);
    int rtd_lsb = read_max31865_register(fd, 0x02);

    if (rtd_msb < 0 || rtd_lsb < 0) {
        fprintf(stderr, "Error reading RTD data\n");
        return -1;
    }

    *rtd_raw = ((unsigned int)rtd_msb << 8) | (unsigned int)rtd_lsb;
    *rtd_raw = *rtd_raw >> 1; // Remove fault bit

    return 0;
}

// Function to calculate temperature from RTD raw value
double calculate_temperature(unsigned int rtd_raw) {
    double rtd_resistance = (rtd_raw * RREF) / 32768.0;
    double temperature = (rtd_resistance - RTD_NOMINAL_RESISTANCE) / (A + B * RTD_NOMINAL_RESISTANCE + C * pow(RTD_NOMINAL_RESISTANCE, 3));
    return temperature;
}

// Function to log data to CSV file
int log_data(FILE *fp, double temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_CHIP, GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize MAX31865 (example configuration)
    if (write_max31865_register(spi_fd, 0x00, 0xC2) < 0) { // Configuration register: Enable bias, 3-wire, auto conversion
        fprintf(stderr, "MAX31865 configuration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    unsigned int rtd_raw;
    double temperature;
    while (!terminate) {
        // Read RTD data
        if (read_rtd_data(spi_fd, &rtd_raw) == 0) {
            // Calculate temperature
            temperature = calculate_temperature(rtd_raw);

            // Log data
            if (log_data(log_file, temperature) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
        } else {
            fprintf(stderr, "RTD read failed\n");
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

