}

// Read raw data
int read_raw_data(int32_t *temperature, int32_t *pressure, int32_t *humidity) {
    int32_t raw_pressure_msb = read_register(BME280_REG_DATA_PRESS_MSB);
    int32_t raw_pressure_lsb = read_register(BME280_REG_DATA_PRESS_LSB);
