int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(BME280_I2C_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Check chip ID
    int chip_id = read_register(BME280_REG_CHIPID);
    if (chip_id != 0x60) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X. Expected 0x60. Exiting.\n", chip_id);
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calib) < 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Set sensor control registers
    if (write_register(BME280_REG_CTRL_HUM, BME280_OVERSAMPLING_HUM) < 0) {
