        close(i2c_fd);
        return 1;
    }

    int ctrl_meas = (BME280_OVERSAMPLING_TEMP << 5) | (BME280_OVERSAMPLING_PRESS << 2) | BME280_MODE_NORMAL;
    if (write_register(BME280_REG_CTRL_MEAS, ctrl_meas) < 0) {
        fprintf(stderr, "Failed to write control measurement register. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("bme280_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_temperature, raw_pressure, raw_humidity;

        if (read_raw_data(&raw_temperature, &raw_pressure, &raw_humidity) == 0) {
            double temperature = compensate_temperature(raw_temperature);
            double pressure = compensate_pressure(raw_pressure, temperature);
            double humidity = compensate_humidity(raw_humidity, temperature);

            log_data(temperature, humidity, pressure);
        } else {
            fprintf(stderr, "Failed to read raw data. Retrying in 5 seconds.\n");
        }

        sleep(5);
    }

    // Cleanup
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

