#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP180 Registers
#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration Data Registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling Setting (OSS)
#define BMP180_OSS 0 // Ultra-low power

// GPIO Pin for Alert
#define ALERT_GPIO 24

// Circular Buffer Size (60 seconds * 20 readings/second)
#define BUFFER_SIZE 1200

// Structure to hold calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Structure to hold pressure reading and timestamp
typedef struct {
    time_t timestamp;
    float pressure;
} pressure_reading_t;

// Global variables
int i2c_handle;
bmp180_calibration_data_t calibration_data;
pressure_reading_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;
float rolling_average = 0.0;

// Function prototypes
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration_data);
int read_raw_temperature(int i2c_handle);
int read_raw_pressure(int i2c_handle);
float calculate_pressure(int raw_temperature, int raw_pressure, bmp180_calibration_data_t calibration_data);
void update_circular_buffer(float pressure);
float calculate_rolling_average();
void check_pressure_deviation(float current_pressure, float rolling_average);
void timer_callback();
void signal_handler(int signal);

// Function to read a 16-bit value from the I2C bus
int16_t read_i2c_word(int i2c_handle, uint8_t reg)
{
    char buf[2];
    if (i2cWriteByte(i2c_handle, reg) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read calibration data from the BMP180
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration_data) {
    calibration_data->ac1 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC1);
    calibration_data->ac2 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC2);
    calibration_data->ac3 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC3);
    calibration_data->ac4 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC4);
    calibration_data->ac5 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC5);
    calibration_data->ac6 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC6);
    calibration_data->b1 = read_i2c_word(i2c_handle, BMP180_REG_CAL_B1);
    calibration_data->b2 = read_i2c_word(i2c_handle, BMP180_REG_CAL_B2);
    calibration_data->mb = read_i2c_word(i2c_handle, BMP180_REG_CAL_MB);
    calibration_data->mc = read_i2c_word(i2c_handle, BMP180_REG_CAL_MC);
    calibration_data->md = read_i2c_word(i2c_handle, BMP180_REG_CAL_MD);

    if (calibration_data->ac1 == -1 || calibration_data->ac2 == -1 || calibration_data->ac3 == -1 ||
        calibration_data->ac4 == -1 || calibration_data->ac5 == -1 || calibration_data->ac6 == -1 ||
        calibration_data->b1 == -1 || calibration_data->b2 == -1 || calibration_data->mb == -1 ||
        calibration_data->mc == -1 || calibration_data->md == -1) {
        fprintf(stderr, "Error reading calibration data.\n");
        return -1;
    }

    return 0;
}

// Function to read the raw temperature value from the BMP180
int read_raw_temperature(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) {
        fprintf(stderr, "Error writing temperature conversion command.\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5 ms
    return read_i2c_word(i2c_handle, BMP180_REG_MSB);
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) {
        fprintf(stderr, "Error writing pressure conversion command.\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5 ms
    return read_i2c_word(i2c_handle, BMP180_REG_MSB);
}

// Function to calculate the pressure in hPa
float calculate_pressure(int raw_temperature, int raw_pressure, bmp180_calibration_data_t calibration_data) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    b5 = (((long)raw_temperature - (long)calibration_data.ac6) * (long)calibration_data.ac5) >> 15;
    x1 = ((long)calibration_data.mc << 11) / (b5 + calibration_data.md);
    b6 = b5 + x1 - 4000;

    x2 = (b6 * b6) >> 12;
    x2 = (x2 * (long)calibration_data.b2) >> 11;
    x3 = ((long)calibration_data.ac2 * b6) >> 11;
    b3 = (((((long)calibration_data.ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    x1 = ((long)calibration_data.ac3 * b6) >> 13;
    x2 = ((b6 * b6) >> 12) * ((long)calibration_data.b1) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = ((unsigned long)calibration_data.ac4 * (unsigned long)(x3 + 32768)) >> 15;
    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);

    if (b7 < 0x80000000)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    return (float)p / 100.0; // Convert to hPa
}

// Function to update the circular buffer with the latest pressure reading
void update_circular_buffer(float pressure) {
    time(&circular_buffer[buffer_index].timestamp);
    circular_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the rolling average of the pressure readings
float calculate_rolling_average() {
    float sum = 0.0;
    int count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (circular_buffer[i].timestamp != 0) {
            sum += circular_buffer[i].pressure;
            count++;
        }
    }
    if (count > 0) {
        return sum / count;
    } else {
        return 0.0;
    }
}

// Function to check for pressure deviation and trigger an alert
void check_pressure_deviation(float current_pressure, float rolling_average) {
    if (rolling_average != 0.0 && (current_pressure - rolling_average) > 5.0) {
        gpioWrite(ALERT_GPIO, 1); // Set GPIO HIGH
        fprintf(stderr, "ALERT: Pressure deviation detected! Current: %.2f hPa, Average: %.2f hPa\n", current_pressure, rolling_average);
    } else {
        gpioWrite(ALERT_GPIO, 0); // Set GPIO LOW
    }
}

// Timer callback function
void timer_callback() {
    int raw_temperature, raw_pressure;
    float pressure;

    raw_temperature = read_raw_temperature(i2c_handle);
    if (raw_temperature == -1) {
        fprintf(stderr, "Error reading raw temperature.\n");
        return;
    }

    raw_pressure = read_raw_pressure(i2c_handle);
    if (raw_pressure == -1) {
        fprintf(stderr, "Error reading raw pressure.\n");
        return;
    }

    pressure = calculate_pressure(raw_temperature, raw_pressure, calibration_data);

    update_circular_buffer(pressure);
    rolling_average = calculate_rolling_average();
    check_pressure_deviation(pressure, rolling_average);

    printf("Pressure: %.2f hPa, Rolling Average: %.2f hPa\n", pressure, rolling_average);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(ALERT_GPIO, 0); // Reset GPIO
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calibration_data) != 0) {
        fprintf(stderr, "Error reading calibration data. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO for alert
