#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQUENCY 25000
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0

volatile sig_atomic_t program_running = 1;
FILE *log_fp = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

float read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    float temp = -1.0;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temp = atof(buffer) / 1000.0;
    }

    fclose(fp);
    return temp;
}

int calculate_duty_cycle(float temperature) {
    if (temperature <= MIN_TEMP) {
        return 0;
    } else if (temperature >= MAX_TEMP) {
        return 255;
    } else {
        return (int)(((temperature - MIN_TEMP) / (MAX_TEMP - MIN_TEMP)) * 255.0);
    }
}

int set_fan_speed(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting fan speed.\n");
        return -1;
    }
    return 0;
}

int log_data(float temperature, int duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_fp != NULL) {
        fprintf(log_fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
        fflush(log_fp); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }
}

int main() {
    int duty_cycle;
    float temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error reading CPU temperature.\n");
        } else {
            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(temperature);

            // Set fan speed
            if (set_fan_speed(duty_cycle) != 0) {
                fprintf(stderr, "Error setting fan speed.\n");
            }

            // Log data
            if (log_data(temperature, duty_cycle) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        sleep(5);
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_fan_speed(0); // Stop the fan
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

