#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// BMP280 Registers
#define BMP280_ADDR_PRIMARY 0x76
#define BMP280_ADDR_SECONDARY 0x77
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_CALIB_START_REG 0x88
#define BMP280_CALIB_END_REG 0xA1
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CONFIG_REG 0xF5
#define BMP280_DATA_START_REG 0xF7
#define BMP280_STATUS_REG 0xF3

// Oversampling settings
#define BMP280_OVERSAMPLING_TEMP 1
#define BMP280_OVERSAMPLING_PRESS 1

// Global variables
static int i2c_fd = -1;
static int bmp280_address = BMP280_ADDR_PRIMARY;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static bmp280_calib_data calib;

// Function prototypes
int init_i2c(int address);
int read_calibration_data(int fd, bmp280_calib_data *calib);
int read_raw_data(int fd, int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib);
double compensate_pressure(int32_t raw_pressure, int32_t raw_temperature, bmp280_calib_data calib);
int log_data(double temperature, double pressure);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Initialize I2C
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read calibration data from BMP280
int read_calibration_data(int fd, bmp280_calib_data *calib) {
    uint8_t buffer[24];
    if (read(fd, buffer, 24) != 24) {
        perror("Error reading calibration data");
        return -1;
    }

    calib->dig_T1 = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    calib->dig_T2 = (int16_t)buffer[2] | ((int16_t)buffer[3] << 8);
    calib->dig_T3 = (int16_t)buffer[4] | ((int16_t)buffer[5] << 8);
    calib->dig_P1 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);
    calib->dig_P2 = (int16_t)buffer[8] | ((int16_t)buffer[9] << 8);
    calib->dig_P3 = (int16_t)buffer[10] | ((int16_t)buffer[11] << 8);
    calib->dig_P4 = (int16_t)buffer[12] | ((int16_t)buffer[13] << 8);
    calib->dig_P5 = (int16_t)buffer[14] | ((int16_t)buffer[15] << 8);
    calib->dig_P6 = (int16_t)buffer[16] | ((int16_t)buffer[17] << 8);
    calib->dig_P7 = (int16_t)buffer[18] | ((int16_t)buffer[19] << 8);
    calib->dig_P8 = (int16_t)buffer[20] | ((int16_t)buffer[21] << 8);
    calib->dig_P9 = (int16_t)buffer[22] | ((int16_t)buffer[23] << 8);

    return 0;
}

// Read raw temperature and pressure data from BMP280
int read_raw_data(int fd, int32_t *temperature, int32_t *pressure) {
    uint8_t buffer[6];
    uint8_t ctrl_meas = (BMP280_OVERSAMPLING_TEMP << 5) | (BMP280_OVERSAMPLING_PRESS << 2) | 0x03; // Forced mode

    // Write control register
    if (write(fd, &ctrl_meas, 1) != 1) {
        perror("Error writing to control register");
        return -1;
    }

    // Wait for measurement to complete (with timeout)
    int timeout = 100; // 100ms timeout
    while (timeout > 0) {
        uint8_t status;
        if (read(fd, &status, 1) != 1) {
            perror("Error reading status register");
            return -1;
        }
        if ((status & 0x08) == 0) {
            break; // Measurement complete
        }
        usleep(1000); // Wait 1ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    // Read raw data
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading raw data");
        return -1;
    }

    *pressure = ((int32_t)buffer[0] << 12) | ((int32_t)buffer[1] << 4) | ((int32_t)buffer[2] >> 4);
    *temperature = ((int32_t)buffer[3] << 12) | ((int32_t)buffer[4] << 4) | ((int32_t)buffer[5] >> 4);

    return 0;
}

// Compensate temperature
double compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib) {
    double var1, var2, T;
    double T1 = (double)calib.dig_T1;
    double T2 = (double)calib.dig_T2;
    double T3 = (double)calib.dig_T3;

    var1 = (((double)raw_temperature / 16384.0) - (T1 / 1024.0)) * (T2);
    var2 = ((((double)raw_temperature / 131072.0) - (T1 / 8192.0)) * (((double)raw_temperature / 131072.0) - (T1 / 8192.0))) * (T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure
double compensate_pressure(int32_t raw_pressure, int32_t raw_temperature, bmp280_calib_data calib) {
    double var1, var2, p;
    double T1 = (double)calib.dig_T1;
    double T2 = (double)calib.dig_T2;
    double T3 = (double)calib.dig_T3;
    double P1 = (double)calib.dig_P1;
    double P2 = (double)calib.dig_P2;
    double P3 = (double)calib.dig_P3;
    double P4 = (double)calib.dig_P4;
    double P5 = (double)calib.dig_P5;
    double P6 = (double)calib.dig_P6;
    double P7 = (double)calib.dig_P7;
    double P8 = (double)calib.dig_P8;
    double P9 = (double)calib.dig_P9;

    double var1_t, var2_t;
    var1_t = (((double)raw_temperature / 16384.0) - (T1 / 1024.0)) * (T2);
    var2_t = ((((double)raw_temperature / 131072.0) - (T1 / 8192.0)) * (((double)raw_temperature / 131072.0) - (T1 / 8192.0))) * (T3);
    double t_fine = (var1_t + var2_t);

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * (P6 / 32768.0);
    var2 = var2 + var1 * (P5 * 2.0);
    var2 = (var2 / 4.0) + (P4 * 65536.0);
    var1 = (P3 * var1 * var1 / 524288.0 + P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * P1;

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = (P9 * p * p) / 2147483648.0;
    var2 = p * (P8 / 32768.0);
    p = p + (var1 + var2 + P7) / 16.0;

    return p / 100.0; // in hPa
}

