    uint8_t buffer[6];
    uint8_t ctrl_meas = (BMP280_OVERSAMPLING_TEMP << 5) | (BMP280_OVERSAMPLING_PRESS << 2) | 0x03; // Forced mode

    // Write control register
    if (write(fd, &ctrl_meas, 1) != 1) {
        perror("Error writing to control register");
        return -1;
