    // Wait for measurement to complete (with timeout)
    int timeout = 100; // 100ms timeout
    while (timeout > 0) {
        uint8_t status;
        if (read(fd, &status, 1) != 1) {
            perror("Error reading status register");
            return -1;
        }
        if ((status & 0x08) == 0) {
