#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define GPIO_LED 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SAMPLE_INTERVAL_MS 1000

// Global variables
int i2c_handle;
pthread_t thread_id;
pthread_mutex_t mutex;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer temp_buffer;

// Function prototypes
void *read_temperature(void *arg);
void control_led(float temperature);
void signal_handler(int signal);
void init_circular_buffer(CircularBuffer *cb);
void add_to_circular_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    memset(cb->buffer, 0, sizeof(cb->buffer));
}

// Add value to circular buffer
void add_to_circular_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate running average
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Read temperature from LM75 sensor
void *read_temperature(void *arg) {
    while (!terminate) {
        char buf[2];
        int result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Convert raw data to temperature
        int16_t raw_temp = (buf[0] << 8) | buf[1];
        float temperature = (float)raw_temp / 256.0;

        // Mutex lock
        pthread_mutex_lock(&mutex);
        add_to_circular_buffer(&temp_buffer, temperature);
        float avg_temp = calculate_average(&temp_buffer);

        // Mutex unlock
        pthread_mutex_unlock(&mutex);

        printf("Temperature: %.2f°C, Average: %.2f°C\n", temperature, avg_temp);
        gpioDelay(SAMPLE_INTERVAL_MS);
    }
    return NULL;
}

// Control LED based on temperature
void control_led(float temperature) {
    if (temperature > TEMP_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize mutex
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&temp_buffer);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Create thread
    if (pthread_create(&thread_id, NULL, read_temperature, NULL) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        pthread_mutex_destroy(&mutex);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop (monitor temperature and control LED)
    while (!terminate) {
        pthread_mutex_lock(&mutex);
        float avg_temp = calculate_average(&temp_buffer);
        pthread_mutex_unlock(&mutex);
        control_led(avg_temp);
        gpioDelay(100); // Check every 100ms
    }

    // Clean up
    pthread_join(thread_id, NULL);
    pthread_mutex_destroy(&mutex);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

