#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <jansson.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define TARGET_TEMPERATURE 25.0
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01
#define MAX_TEMPERATURE 80.0
#define CONFIG_FILE "config.json"
#define LOG_FILE "error.log"

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x80
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_FAULT_REG 0x07

// PT100 Constants
#define R_REF 430.0
#define R0 100.0
#define A 0.0039083
#define B -0.0000005775

// Global Variables
int spi_handle;
double kp = DEFAULT_KP;
double ki = DEFAULT_KI;
double kd = DEFAULT_KD;
double integral = 0.0;
double previous_error = 0.0;

// Function Prototypes
int initialize_spi();
int initialize_max31865();
int read_rtd_code(unsigned int *rtd_code);
double convert_rtd_to_resistance(unsigned int rtd_code);
double convert_resistance_to_temperature(double resistance);
double calculate_pid(double current_temperature, double target_temperature);
void set_pwm_duty_cycle(double duty_cycle);
void log_error(const char *message);
void signal_handler(int signal);
int load_configuration();

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        log_error("Failed to open SPI channel");
        return -1;
    }
    return 0;
}

// Function to initialize MAX31865
int initialize_max31865() {
    char buf[2];
    buf[0] = MAX31865_CONFIG_REG;
    buf[1] = 0xC1; // Enable VBIAS, auto conversion, clear faults

    if (spiWrite(spi_handle, buf, 2) != 0) {
        log_error("Failed to write to MAX31865 configuration register");
        return -1;
    }
    return 0;
}

// Function to read RTD code from MAX31865
int read_rtd_code(unsigned int *rtd_code) {
    char tx_buf[1];
    char rx_buf[2];

    tx_buf[0] = MAX31865_RTD_MSB_REG | 0x01; // Read RTD MSB and LSB

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        log_error("Failed to read RTD code from MAX31865");
        return -1;
    }

    *rtd_code = ((unsigned int)rx_buf[1] << 8) | (unsigned int)rx_buf[2];
    *rtd_code = *rtd_code >> 1; // Remove fault bit

    return 0;
}

// Function to convert RTD code to resistance
double convert_rtd_to_resistance(unsigned int rtd_code) {
    return ((double)rtd_code / 32768.0) * R_REF;
}

// Function to convert resistance to temperature (Callendar-Van Dusen equation)
double convert_resistance_to_temperature(double resistance) {
    double t = (resistance - R0) / A;
    t = t - B * pow(t, 2);
    return t;
}

// Function to calculate PID output
double calculate_pid(double current_temperature, double target_temperature) {
    double error = target_temperature - current_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = kp * error + ki * integral + kd * derivative;
    previous_error = error;
    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;
    int pwm_value = (int)(duty_cycle * PWM_RANGE / 100.0);
    gpioPWM(PWM_GPIO, pwm_value);
}

// Function to log errors to file
void log_error(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm *tm = localtime(&tv.tv_sec);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s.%06ld: %s\n", timestamp, tv.tv_usec, message);
    fclose(fp);
    fprintf(stderr, "%s.%06ld: %s\n", timestamp, tv.tv_usec, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    set_pwm_duty_cycle(0.0);
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to load configuration from JSON file
int load_configuration() {
    json_t *root;
    json_error_t error;

    root = json_load_file(CONFIG_FILE, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        fprintf(stderr, "Using default configuration: target=%.2f, Kp=%.2f, Ki=%.2f, Kd=%.2f\n", TARGET_TEMPERATURE, DEFAULT_KP, DEFAULT_KI, DEFAULT_KD);
        return -1;
    }

    json_t *target = json_object_get(root, "target_temperature");
    json_t *kp_json = json_object_get(root, "Kp");
    json_t *ki_json = json_object_get(root, "Ki");
    json_t *kd_json = json_object_get(root, "Kd");

    if (json_is_real(target)) {
        TARGET_TEMPERATURE = json_real_value(target);
    }
    if (json_is_real(kp_json)) {
        kp = json_real_value(kp_json);
    }
    if (json_is_real(ki_json)) {
        ki = json_real_value(ki_json);
    }
    if (json_is_real(kd_json)) {
        kd = json_real_value(kd_json);
    }

    json_decref(root);
    printf("Configuration loaded: target=%.2f, Kp=%.2f, Ki=%.2f, Kd=%.2f\n", TARGET_TEMPERATURE, kp, ki, kd);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Load configuration
    if (load_configuration() != 0) {
        // Use default values if config file loading fails
        TARGET_TEMPERATURE = 25.0;
        kp = DEFAULT_KP;
        ki = DEFAULT_KI;
        kd = DEFAULT_KD;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MAX31865
    if (initialize_max31865() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency and range
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned int rtd_code;
    double resistance, temperature, pid_output;

    while (1) {
        // Read RTD code
        if (read_rtd_code(&rtd_code) != 0) {
            log_error("Failed to read RTD code, shutting down");
            set_pwm_duty_cycle(0.0);
            spiClose(spi_handle);
            gpioTerminate();
            return 1;
        }

        // Convert RTD code to resistance
        resistance = convert_rtd_to_resistance(rtd_code);

        // Convert resistance to temperature
        temperature = convert_resistance_to_temperature(resistance);

        // Check for over-temperature condition
        if (temperature > MAX_TEMPERATURE) {
            log_error("Temperature exceeds maximum limit, shutting down");
            set_pwm_duty_cycle(0.0);
            spiClose(spi_handle);
            gpioTerminate();
            return 1;
        }

        // Calculate PID output
        pid_output = calculate_pid(temperature, TARGET_TEMPERATURE);

        // Set PWM duty cycle
        set_pwm_duty_cycle(pid_output);

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

