#include <errno.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 // Oss = 0
#define BMP180_CMD_PRESSURE1 0x74 // Oss = 1
#define BMP180_CMD_PRESSURE2 0xB4 // Oss = 2
#define BMP180_CMD_PRESSURE3 0xF4 // Oss = 3

// Thresholds
#define TEMPERATURE_THRESHOLD 30.0
#define PRESSURE_THRESHOLD 950.0

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Calibration data
short ac1, ac2, ac3, b1, b2, mb, mc, md;
unsigned short ac4, ac5, ac6;

// Function prototypes
int init_i2c(const char *device);
int read_calibration_data();
int read_raw_temperature(long *raw_temperature);
int read_raw_pressure(long *raw_pressure);
double calculate_temperature(long raw_temperature);
double calculate_pressure(long raw_pressure, long raw_temperature);
int check_thresholds(double temperature, double pressure);
int log_breach(double temperature, double pressure);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C
int init_i2c(const char *device) {
    i2c_fd = open(device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read calibration data from BMP180
int read_calibration_data() {
    unsigned char buffer[22];
    int retries = 3;
    int i;

    while (retries > 0) {
        if (read(i2c_fd, buffer, 22) == 22) {
            ac1 = (buffer[0] << 8) | buffer[1];
            ac2 = (buffer[2] << 8) | buffer[3];
            ac3 = (buffer[4] << 8) | buffer[5];
            ac4 = (buffer[6] << 8) | buffer[7];
            ac5 = (buffer[8] << 8) | buffer[9];
            ac6 = (buffer[10] << 8) | buffer[11];
            b1 = (buffer[12] << 8) | buffer[13];
            b2 = (buffer[14] << 8) | buffer[15];
            mb = (buffer[16] << 8) | buffer[17];
            mc = (buffer[18] << 8) | buffer[19];
            md = (buffer[20] << 8) | buffer[21];
            return 0;
        } else {
            perror("Error reading calibration data");
            retries--;
            usleep(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read calibration data after multiple retries.\n");
    return -1;
}

// Read raw temperature data from BMP180
int read_raw_temperature(long *raw_temperature) {
    unsigned char write_buffer[2];
    unsigned char read_buffer[2];
    int retries = 3;

    write_buffer[0] = BMP180_REG_CONTROL;
    write_buffer[1] = BMP180_CMD_TEMP;

    while (retries > 0) {
        if (write(i2c_fd, write_buffer, 2) == 2) {
            usleep(5000); // Wait 4.5ms

            write_buffer[0] = BMP180_REG_MSB;
            if (write(i2c_fd, write_buffer, 1) == 1) {
                if (read(i2c_fd, read_buffer, 2) == 2) {
                    *raw_temperature = (read_buffer[0] << 8) | read_buffer[1];
                    return 0;
                } else {
                    perror("Error reading raw temperature data (MSB/LSB)");
                }
            } else {
                perror("Error writing to read raw temperature register");
            }
        } else {
            perror("Error writing temperature conversion command");
        }
        retries--;
        usleep(10000); // Wait 10ms before retrying
    }

    fprintf(stderr, "Failed to read raw temperature after multiple retries.\n");
    return -1;
}

// Read raw pressure data from BMP180
int read_raw_pressure(long *raw_pressure) {
    unsigned char write_buffer[2];
    unsigned char read_buffer[3];
    int retries = 3;

    write_buffer[0] = BMP180_REG_CONTROL;
    write_buffer[1] = BMP180_CMD_PRESSURE3; // OSS = 3

    while (retries > 0) {
        if (write(i2c_fd, write_buffer, 2) == 2) {
            usleep(26000); // Wait 25.5ms

            write_buffer[0] = BMP180_REG_MSB;
            if (write(i2c_fd, write_buffer, 1) == 1) {
                if (read(i2c_fd, read_buffer, 3) == 3) {
                    *raw_pressure = ((long)read_buffer[0] << 16 | (long)read_buffer[1] << 8 | (long)read_buffer[2]) >> 8;
                    return 0;
                } else {
                    perror("Error reading raw pressure data (MSB/LSB/XLSB)");
                }
            } else {
                perror("Error writing to read raw pressure register");
            }
        } else {
            perror("Error writing pressure conversion command");
        }
        retries--;
        usleep(10000); // Wait 10ms before retrying
    }

    fprintf(stderr, "Failed to read raw pressure after multiple retries.\n");
    return -1;
}

// Calculate temperature in degrees Celsius
double calculate_temperature(long raw_temperature) {
    long X1 = ((raw_temperature - (long)ac6) * (long)ac5) >> 15;
    long X2 = ((long)mc << 11) / (X1 + md);
    long B5 = X1 + X2;
    double temperature = ((B5 + 8) >> 4) / 10.0;
    return temperature;
}

// Calculate pressure in hPa
double calculate_pressure(long raw_pressure, long raw_temperature) {
    long X1 = ((raw_temperature - (long)ac6) * (long)ac5) >> 15;
    long X2 = ((long)mc << 11) / (X1 + md);
    long B5 = X1 + X2;

    long B6 = B5 - 4000;
    long X3 = ((long)b2 * (B6 * B6) >> 12) >> 11;
    long X4 = ((long)ac2 * B6) >> 11;
    long B3 = (((((long)ac1) * 4 + X3) << 3) + 2) / 4;

    unsigned long X1_pressure = ((unsigned long)ac3 * B6) >> 13;
    unsigned long X2_pressure = ((unsigned long)b1 * ((B6 * B6) >> 12)) >> 16;
    unsigned long B4 = X1_pressure + X2_pressure + 32768;
    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> 0);

    long pressure;
    if (B7 < 0x80000000)
    {
        pressure = (B7 * 2) / B4;
    }
    else
    {
        pressure = (B7 / B4) * 2;
    }

    X1 = (pressure >> 8) * (pressure >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * pressure) >> 16;
    pressure = pressure + ((X1 + X2 + 3791) >> 4);

    return pressure / 100.0; // Convert to hPa
}

// Check if temperature or pressure exceeds thresholds
int check_thresholds(double temperature, double pressure) {
    if (temperature > TEMPERATURE_THRESHOLD || pressure < PRESSURE_THRESHOLD) {
        return 1;
    } else {
        return 0;
    }
}

// Log breach to file
int log_breach(double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

