#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling Setting (OSS)
#define BMP180_OSS 0

// GPIO pin for fan control
#define FAN_GPIO 18

// Circular buffer size
#define BUFFER_SIZE 60

// Structure to hold sensor readings
typedef struct {
    time_t timestamp;
    float temperature;
    float pressure;
} sensor_reading_t;

// Circular buffer
sensor_reading_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temperature);
int read_raw_pressure(int32_t *raw_pressure);
float calculate_temperature(int32_t ut);
float calculate_pressure(int32_t up, int32_t ut);
void store_reading(time_t timestamp, float temperature, float pressure);
void control_fan(float temperature);
void timer_callback();
void signal_handler(int signal);

// Function to read a 16-bit value from the I2C bus
int read_i2c_word(int handle, uint8_t reg, int16_t *value)
{
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }
    *value = (data[0] << 8) | data[1];
    return 0;
}

// Function to read an unsigned 16-bit value from the I2C bus
int read_i2c_uword(int handle, uint8_t reg, uint16_t *value)
{
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }
    *value = (data[0] << 8) | data[1];
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC1, &ac1) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC2, &ac2) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC3, &ac3) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC4, &ac4) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC5, &ac5) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC6, &ac6) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_B1, &b1) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_B2, &b2) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MB, &mb) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MC, &mc) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MD, &md) != 0) return -1;

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int32_t *raw_temperature)
{
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // Temperature measurement command

    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 4.5ms (minimum)

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    *raw_temperature = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int32_t *raw_pressure)
{
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command

    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return -1;
    }

    gpioDelay(2 + (3 << BMP180_OSS)); // Wait for conversion

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    char data[3];
    if (i2cReadDevice(i2c_handle, data, 3) != 3) {
        fprintf(stderr, "Error reading pressure data\n");
        return -1;
    }

    *raw_pressure = ((int32_t)data[0] << 16 | (int32_t)data[1] << 8 | (int32_t)data[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate true temperature in degrees Celsius
float calculate_temperature(int32_t ut)
{
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    float temperature = ((b5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Function to calculate true pressure in Pascals
float calculate_pressure(int32_t up, int32_t ut)
{
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    int32_t x3 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x4 = ((int32_t)ac2 * b6) >> 11;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    uint32_t x1_u = ((uint32_t)ac3 * b6) >> 13;
    uint32_t x2_u = ((uint32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    uint32_t x3_u = ((x1_u + x2_u + 2) >> 2);
    uint32_t b4 = ((uint32_t)ac4 * (x3_u + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);

    int32_t p;
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    float pressure = p + ((x1 + x2 + 3791) >> 4);

    return pressure;
}

// Function to store a sensor reading in the circular buffer
void store_reading(time_t timestamp, float temperature, float pressure)
{
    circular_buffer[buffer_index].timestamp = timestamp;
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to control the cooling fan based on temperature
void control_fan(float temperature)
{
    if (temperature > 30.0f) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
    }
}

// Timer callback function
void timer_callback()
{
    int32_t raw_temperature, raw_pressure;
    float temperature, pressure;
    time_t current_time;

    if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
        temperature = calculate_temperature(raw_temperature);
        pressure = calculate_pressure(raw_pressure, raw_temperature);
        current_time = time(NULL);
        store_reading(current_time, temperature, pressure);
        control_fan(temperature);

        printf("Timestamp: %ld, Temperature: %.2f °C, Pressure: %.2f Pa\n", current_time, temperature, pressure);
    } else {
        fprintf(stderr, "Error reading sensor data in timer callback\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Initially turn the fan off

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback
    gpioSetTimerFuncEx(0, 500, timer_callback, NULL);

    // Main loop
    while (!terminate) {
        sleep(1);
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn off the fan
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

