    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC2, &ac2) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC3, &ac3) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC4, &ac4) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC5, &ac5) != 0) return -1;
