    if (read_ushort(i2c_handle, 0xB0, &ac4) != 0) return -1;
    if (read_ushort(i2c_handle, 0xB2, &ac5) != 0) return -1;
    if (read_ushort(i2c_handle, 0xB4, &ac6) != 0) return -1;
    if (read_short(i2c_handle, 0xB6, &b1) != 0) return -1;
    if (read_short(i2c_handle, 0xB8, &b2) != 0) return -1;
    if (read_short(i2c_handle, 0xBA, &mb) != 0) return -1;
