int log_pressure(double pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, %.2f Pa\n", timestamp, pressure) < 0)
    {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to toggle logging state
void toggle_logging()
{
    unsigned long current_time = gpioTick();
    if (current_time - last_toggle_time > DEBOUNCE_TIME * 1000)
    {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        last_toggle_time = current_time;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0)
    {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL)
    {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0)
    {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL)
    {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as input with pull-up resistor
    gpioSetMode(TOGGLE_PIN, PI_INPUT);
    gpioSetPullUpDown(TOGGLE_PIN, PI_PUD_UP);

    // Set interrupt handler for falling edge on GPIO27
    gpioSetAlertFunc(TOGGLE_PIN, toggle_logging);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Pressure logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1)
    {
        if (logging_enabled)
        {
            long raw_temperature, raw_pressure;
            double pressure;

            if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0)
            {
                pressure = calculate_pressure(raw_temperature, raw_pressure);
                if (log_pressure(pressure) != 0)
                {
                    fprintf(stderr, "Error logging pressure data\n");
                }
            }
            else
            {
                fprintf(stderr, "Error reading raw data\n");
            }
        }
        gpioDelay(LOGGING_INTERVAL * 1000000); // Delay for 2 seconds
    }

    return 0;
}

