#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define HEATER_PIN 17
#define SPI_CE0 8
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 2000000

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PI controller parameters
#define KP 1.0
#define KI 0.1

// Define safe maximum duty cycle
#define MAX_DUTY_CYCLE 800000 // 80% of 1000000

// Define heater on time (seconds)
#define HEATER_ON_TIME 5

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static double target_temperature = 25.0;
static double integral = 0.0;
static double last_error = 0.0;

// Function prototypes
double read_temperature();
void set_heater_duty_cycle(int duty_cycle);
double calculate_pid(double current_temperature);
void log_data(double temperature, int duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char buffer[4];
    int result;

    result = spiRead(spi_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from SPI: %d\n", result);
        log_data(-999.0, -1); // Log error
        return -999.0; // Indicate error
    }

    // Check for fault bits
    if (buffer[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        log_data(-998.0, -1); // Log error
        return -998.0; // Indicate fault
    } else if (buffer[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        log_data(-997.0, -1); // Log error
        return -997.0; // Indicate fault
    } else if (buffer[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        log_data(-996.0, -1); // Log error
        return -996.0; // Indicate fault
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 2;
    double temperature = raw_temp * 0.25;

    return temperature;
}

// Function to set heater duty cycle
void set_heater_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > MAX_DUTY_CYCLE) {
        duty_cycle = MAX_DUTY_CYCLE;
    }

    gpioPWM(HEATER_PIN, duty_cycle / 10000); // pigpio PWM range is 0-1000
}

// Function to calculate PID output
double calculate_pid(double current_temperature) {
    double error = target_temperature - current_temperature;
    integral += error;

    // Anti-windup
    if (integral > MAX_DUTY_CYCLE) {
        integral = MAX_DUTY_CYCLE;
    } else if (integral < 0) {
        integral = 0;
    }

    double derivative = error - last_error;
    double output = KP * error + KI * integral; // + KD * derivative;

    last_error = error;
    return output;
}

// Function to log data to CSV file
void log_data(double temperature, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for heater control
    gpioSetMode(HEATER_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heater_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Turn off heater
    set_heater_duty_cycle(0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        target_temperature = atof(argv[1]);
    }

    printf("Target temperature: %.2f°C\n", target_temperature);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    time_t start_time = time(NULL);
    while (running) {
        double temperature = read_temperature();
        if (temperature > -900) {
            int duty_cycle = (int)calculate_pid(temperature);
            set_heater_duty_cycle(duty_cycle);
            log_data(temperature, duty_cycle / 10000);
            printf("Temperature: %.2f°C, Duty Cycle: %d%%\n", temperature, duty_cycle / 10000);
        } else {
            set_heater_duty_cycle(0);
        }

        // Check if heater on time has elapsed
        if (time(NULL) - start_time >= HEATER_ON_TIME) {
            running = 0; // Stop after heater on time
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

