#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED (common anode)
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Temperature thresholds (millidegrees Celsius)
#define TEMP_BLUE  40000
#define TEMP_GREEN 59999

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    int temperature = -1;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file.\n");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        if (ferror(fp)) {
            fprintf(stderr, "Error: Could not read temperature from file.\n");
        } else {
            fprintf(stderr, "Error: End of file reached before temperature could be read.\n");
        }
        fclose(fp);
        return -1;
    }

    fclose(fp);

    temperature = atoi(buffer);
    return temperature;
}

// Function to set RGB LED color using PWM
void set_rgb_color(int red, int green, int blue) {
    // Common anode: invert brightness for full-on (0) and full-off (255)
    gpioPWM(RED_PIN, 255 - red);
    gpioPWM(GREEN_PIN, 255 - green);
    gpioPWM(BLUE_PIN, 255 - blue);
}

// Function to determine RGB color based on temperature
void determine_rgb(int temperature, int *red, int *green, int *blue) {
    if (temperature < TEMP_BLUE) {
        *red = 0;
        *green = 0;
        *blue = 255;
    } else if (temperature >= TEMP_BLUE && temperature <= TEMP_GREEN) {
        *red = 0;
        *green = 255;
        *blue = 0;
    } else {
        *red = 255;
        *green = 0;
        *blue = 0;
    }
}

int main() {
    int temperature, red, green, blue;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Set PWM frequency (e.g., 1000 Hz)
    gpioSetPWMfrequency(RED_PIN, 1000);
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature == -1) {
            fprintf(stderr, "Error: Could not read CPU temperature. Skipping update.\n");
        } else {
            // Determine RGB color
            determine_rgb(temperature, &red, &green, &blue);

            // Set RGB LED color
            set_rgb_color(red, green, blue);

            // Print temperature and RGB values
            printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temperature, red, green, blue);
        }

        // Wait for 0.5 seconds
        usleep(500000); // 0.5 seconds = 500000 microseconds
    }

    // Cleanup: Turn off RGB LED and terminate pigpio
    set_rgb_color(255, 255, 255); // Turn off all LEDs
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

