}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to read data from the DHT22 sensor
int read_dht22(SensorData *data) {
    int data_bits[40];
    int i, j;
    unsigned int pulse_start, pulse_end, pulse_len;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // Wait for sensor to respond

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for the start of the data bit (low pulse)
        pulse_start = gpioTick();
        while (gpioRead(DHT22_GPIO) == 1) {
            pulse_end = gpioTick();
            pulse_len = pulse_end - pulse_start;
            if (pulse_len > 200) {
                fprintf(stderr, "Timeout waiting for low pulse\n");
                return -1;
            }
        }

        // Measure the length of the high pulse
        pulse_start = gpioTick();
        while (gpioRead(DHT22_GPIO) == 0) {
            pulse_end = gpioTick();
            pulse_len = pulse_end - pulse_start;
            if (pulse_len > 200) {
                fprintf(stderr, "Timeout waiting for high pulse\n");
                return -1;
            }
        }
        pulse_end = gpioTick();
        pulse_len = pulse_end - pulse_start;

        // Determine if the bit is a 0 or a 1 based on the pulse length
        data_bits[i] = (pulse_len > 50) ? 1 : 0; // Adjust threshold as needed
    }

    // Convert the bits to bytes
    unsigned int raw_data[5] = {0, 0, 0, 0, 0};
    for (i = 0; i < 40; i++) {
        raw_data[i / 8] <<= 1;
        raw_data[i / 8] |= data_bits[i];
    }

    // Validate the checksum
    if ((raw_data[0] + raw_data[1] + raw_data[2] + raw_data[3]) & 0xFF != raw_data[4]) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    // Parse the data
    data->humidity = (float)(((raw_data[0] << 8) | raw_data[1])) / 10.0;
    data->temperature = (float)(((raw_data[2] << 8) | raw_data[3])) / 10.0;
    if (raw_data[2] & 0x80) {
        data->temperature *= -1;
    }

    return 0;
}

