            }
            retries++;
            sleep(1); // Wait before retrying
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor after %d retries\n", MAX_RETRIES);
        }

        sleep(5); // Wait 5 seconds before the next reading
    }

    // Clean up pigpio
    gpioTerminate();

