#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS=3)
#define BMP180_OSS 3

// Conversion delay (26 ms for OSS=3)
#define BMP180_CONVERSION_DELAY 26000 // microseconds

// GPIO pin for push-button interrupt
#define BUTTON_GPIO 4

// Debounce time (200 ms)
#define DEBOUNCE_TIME 200000 // microseconds

// Global variables
static int i2c_handle;
static volatile int logging_enabled = 0;
static volatile unsigned int last_interrupt_tick = 0;
static FILE *log_file = NULL;

// Calibration data
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
double calculate_pressure(int raw_temp, int raw_pressure);
void toggle_logging();
void isr_button(int gpio, int level, unsigned int tick, void *user);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data() {
    char data[22];
    int result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, data, 22);
    if (result != 22) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    // Basic validation (check for reasonable values)
    if (ac1 > 5000 || ac1 < -5000 || ac2 > 5000 || ac2 < -5000 || ac3 > 5000 || ac3 < -5000 ||
        ac4 > 65535 || ac4 < 0 || ac5 > 65535 || ac5 < 0 || ac6 > 65535 || ac6 < 0 ||
        b1 > 5000 || b1 < -5000 || b2 > 5000 || b2 < -5000 || mb > 5000 || mb < -5000 ||
        mc > 5000 || mc < -5000 || md > 5000 || md < -5000) {
        fprintf(stderr, "Error: Invalid calibration data. Check sensor connection.\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(int *raw_temp) {
    char write_data[2] = {BMP180_REG_CONTROL, 0x2E}; // Request temperature reading
    int result = i2cWriteDevice(i2c_handle, write_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C for temperature: %d\n", result);
        return -1;
    }
    gpioDelay(5000); // Wait 5 ms

    char read_data[2];
    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, read_data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }

    *raw_temp = (read_data[0] << 8) | read_data[1];
    return 0;
}

// Function to read raw pressure data from BMP180
int read_raw_pressure(int *raw_pressure) {
    char write_data[2] = {BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)}; // Request pressure reading
    int result = i2cWriteDevice(i2c_handle, write_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C for pressure: %d\n", result);
        return -1;
    }
    gpioDelay(BMP180_CONVERSION_DELAY); // Wait for conversion

    char read_data[3];
    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, read_data, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1;
    }

    *raw_pressure = ((read_data[0] << 16) | (read_data[1] << 8) | read_data[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate pressure in hPa
double calculate_pressure(int raw_temp, int raw_pressure) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    // Temperature calculations
    x1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    b5 = x1 + x2;

    // Pressure calculations
    b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6 / pow(2, 12))) / pow(2, 11);
    x2 = ac2 * b6 / pow(2, 11);
    x3 = x1 + x2;
    b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) / 4;

    x1 = ac3 * b6 / pow(2, 13);
    x2 = (b1 * (b6 * b6 / pow(2, 12))) / pow(2, 16);
    x3 = ((x1 + x2) + 2) / pow(2, 2);
    b4 = (ac4 * (unsigned long)(x3 + 32768)) / pow(2, 15);
    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);

    if (b7 < 0x80000000)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    p = p + (x1 + x2 + 3791) / pow(2, 4);

    return p / 100.0; // Convert to hPa
}

// Function to toggle logging
void toggle_logging() {
    logging_enabled = !logging_enabled;
    if (logging_enabled) {
        printf("Logging enabled.\n");
    } else {
        printf("Logging disabled.\n");
    }
}

// Interrupt service routine for push-button
void isr_button(int gpio, int level, unsigned int tick, void *user) {
    unsigned int diff = tick - last_interrupt_tick;

    if (diff > DEBOUNCE_TIME) {
        toggle_logging();
        last_interrupt_tick = tick;
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input with pull-up resistor
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    // Set interrupt handler for falling edge
    gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, isr_button, NULL);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        if (logging_enabled) {
            int raw_temp, raw_pressure;
            double pressure;
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[30];

            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                // Calculate pressure
                pressure = calculate_pressure(raw_temp, raw_pressure);

                // Get timestamp
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

                // Log data to file
                fprintf(log_file, "%s, %.2f hPa\n", timestamp, pressure);
                fflush(log_file); // Ensure data is written immediately

                printf("%s, %.2f hPa\n", timestamp, pressure);
            } else {
                fprintf(stderr, "Error reading sensor data.\n");
            }
        } else {
            printf("Logging is disabled. Press button to enable.\n");
        }

        gpioDelay(2000000); // Sample every 2 seconds
    }

    return 0;
}

