#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <curl/curl.h>
#include <pigpio.h>
#include <time.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define BACKOFF_DELAY 2
#define API_ENDPOINT "http://your-server.com/api/humidity"

static volatile int running = 1;
static char *server_url = NULL;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

int read_dht22(int gpio, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_count = 0;
    unsigned int last_tick = 0;
    unsigned int current_tick = 0;
    int i, j;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30);
    gpioSetMode(gpio, PI_INPUT);

    while (pulse_count < 80) {
        current_tick = gpioTick();
        if (gpioRead(gpio) != (pulse_count % 2)) {
            if (pulse_count > 1) {
                unsigned int pulse_length = current_tick - last_tick;
                if (pulse_length > 1000) {
                    return -1; // Timeout
                }
                if (pulse_length > 50) {
                    data[bit_count / 8] |= (1 << (7 - (bit_count % 8)));
                }
                bit_count++;
            }
            pulse_count++;
            last_tick = current_tick;
        }
        if (gpioTick() - current_tick > 200) {
            return -1; // Timeout
        }
    }

    if ((data[0] + data[1] + data[2] + data[3]) & 0xFF != data[4]) {
        return -2; // Checksum error
    }

    *humidity = (float)(((data[0] << 8) | data[1])) / 10.0;

    return 0;
}

int post_humidity(const char *url, float humidity) {
    CURL *curl;
    CURLcode res;
    char json_data[50];
    int retries = 0;

    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    while (retries < MAX_RETRIES) {
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, url);
            curl_easy_setopt(curl, CURLOPT_POST, 1L);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, NULL);

            struct curl_slist *headers = NULL;
            headers = curl_slist_append(headers, "Content-Type: application/json");
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

            res = curl_easy_perform(curl);

            if (res == CURLE_OK) {
                long response_code;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
                if (response_code >= 200 && response_code < 300) {
                    syslog(LOG_INFO, "POST successful, response code: %ld", response_code);
                    curl_slist_free_all(headers);
                    curl_easy_cleanup(curl);
                    curl_global_cleanup();
                    return 0;
                } else {
                    syslog(LOG_ERR, "HTTP POST failed with code: %ld", response_code);
                }
            } else {
                syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
            }

            curl_slist_free_all(headers);
            curl_easy_cleanup(curl);
        } else {
            syslog(LOG_ERR, "curl_easy_init() failed");
        }
        curl_global_cleanup();
        retries++;
        if (retries < MAX_RETRIES) {
            syslog(LOG_WARNING, "Retrying POST in %d seconds...", BACKOFF_DELAY * retries);
            sleep(BACKOFF_DELAY * retries);
        }
    }

    syslog(LOG_ERR, "Failed to POST humidity after %d retries", MAX_RETRIES);
    return -1;
}

int main(int argc, char *argv[]) {
    int opt;
    float humidity;
    int result;

    openlog("dht22_humidity", LOG_PID | LOG_CONS, LOG_USER);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <server_url>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    if (server_url == NULL) {
        server_url = API_ENDPOINT;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Starting DHT22 humidity monitor");

    while (running) {
        result = read_dht22(DHT22_GPIO, &humidity);
        if (result == 0) {
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            if (post_humidity(server_url, humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity to server");
            }
        } else {
            syslog(LOG_ERR, "Failed to read DHT22 sensor, error code: %d", result);
        }
        sleep(10);
    }

    gpioTerminate();
    closelog();
    return 0;
}

