int max_fan_state = -1; // Initialize to an invalid value

// Function prototypes
int read_temperature();
int calculate_fan_speed(int temperature);
int write_fan_speed(int speed);
int log_fan_speed(int temperature, int speed);
void signal_handler(int signal);
int get_max_fan_state();

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, shutting down...\n", signal);
    log_fan_speed(0, 0); // Log shutdown
    write_fan_speed(0);   // Stop the fan
    exit(0);
}

// Read temperature from file
int read_temperature() {
    FILE *fp;
    char buffer[10];
    int temperature = -1;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fp = fopen(TEMP_FILE, "r");
        if (fp == NULL) {
            fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 100ms
            continue;
        }

        if (fgets(buffer, sizeof(buffer), fp) == NULL) {
            fprintf(stderr, "Error reading temperature file: %s\n", strerror(errno));
            fclose(fp);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 100ms
            continue;
        }

        fclose(fp);
        temperature = atoi(buffer);
        return temperature;
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Calculate fan speed based on temperature
int calculate_fan_speed(int temperature) {
    if (temperature < 45000) {
        return 0;
    } else if (temperature < 55000) {
        return 1;
    } else if (temperature < 65000) {
        return 2;
    } else {
        return 3;
    }
}

// Write fan speed to file
int write_fan_speed(int speed) {
    FILE *fp;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fp = fopen(FAN_STATE_FILE, "w");
        if (fp == NULL) {
            fprintf(stderr, "Error opening fan state file: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 100ms
            continue;
        }

        if (fprintf(fp, "%d", speed) < 0) {
            fprintf(stderr, "Error writing to fan state file: %s\n", strerror(errno));
            fclose(fp);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 100ms
            continue;
        }

        fclose(fp);
        return 0; // Success
    }

    fprintf(stderr, "Failed to write fan speed after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Log fan speed to file
int log_fan_speed(int temperature, int speed) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    static int last_speed = -1; // Static variable to store the last logged speed

    if (speed == last_speed) {
        return 0; // Skip logging if the speed hasn't changed
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Temperature: %d, Fan Speed: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, speed);

    fclose(fp);
    last_speed = speed; // Update the last logged speed
    return 0;
}

// Get the maximum fan state from the sysfs file
int get_max_fan_state() {
    FILE *fp;
    char buffer[10];
    int max_state = -1;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fp = fopen("/sys/class/thermal/cooling_device0/max_state", "r");
        if (fp == NULL) {
            fprintf(stderr, "Error opening max_state file: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 100ms
            continue;
        }

        if (fgets(buffer, sizeof(buffer), fp) == NULL) {
            fprintf(stderr, "Error reading max_state file: %s\n", strerror(errno));
            fclose(fp);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 100ms
            continue;
        }

        fclose(fp);
        max_state = atoi(buffer);
        return max_state;
    }

    fprintf(stderr, "Failed to read max_state after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

int main() {
    int temperature, fan_speed;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Get the maximum fan state
    max_fan_state = get_max_fan_state();
    if (max_fan_state == -1) {
        fprintf(stderr, "Failed to get max fan state. Exiting.\n");
        return 1;
    }

    printf("Max fan state: %d\n", max_fan_state);

    while (program_running) {
        temperature = read_temperature();
        if (temperature != -1) {
            fan_speed = calculate_fan_speed(temperature);

            // Validate fan speed against max_state
            if (fan_speed > max_fan_state) {
                fprintf(stderr, "Fan speed (%d) exceeds max_state (%d). Setting to max_state.\n", fan_speed, max_fan_state);
                fan_speed = max_fan_state;
            }

            if (write_fan_speed(fan_speed) == 0) {
                log_fan_speed(temperature, fan_speed);
            } else {
                fprintf(stderr, "Failed to write fan speed.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        sleep(5);
    }

    return 0;
}

