#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define HEATER_GPIO 18
#define SPI_CLK_GPIO 11
#define SPI_CS_GPIO 8
#define SPI_DO_GPIO 9

// Define SPI channel
#define SPI_CHANNEL 0

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PID parameters
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01

// Define failsafe temperature range
#define FAILSAFE_MIN_TEMP 0.0
#define FAILSAFE_MAX_TEMP 100.0

// Define log file name
#define LOG_FILE "heater_log.txt"

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static double kp = DEFAULT_KP;
static double ki = DEFAULT_KI;
static double kd = DEFAULT_KD;
static double target_temperature = 50.0;

// PID variables
static double integral = 0.0;
static double previous_error = 0.0;

// Function prototypes
double read_temperature();
void set_heater_pwm(int duty_cycle);
void log_data(double temperature, int duty_cycle, double pid_output);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[]);

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char buffer[4];
    int result;

    result = spiRead(spi_handle, buffer, 4);
    if (result != 4) {
        fprintf(log_file, "%s", "Error: SPI read failed\n");
        fflush(log_file);
        return -273.15; // Return absolute zero on error
    }

    // Check for fault bits
    if (buffer[3] & 0x01) {
        fprintf(log_file, "%s", "Error: Thermocouple open circuit\n");
        fflush(log_file);
        return -273.15;
    } else if (buffer[3] & 0x02) {
        fprintf(log_file, "%s", "Error: Thermocouple short to GND\n");
        fflush(log_file);
        return -273.15;
    } else if (buffer[3] & 0x04) {
        fprintf(log_file, "%s", "Error: Thermocouple short to VCC\n");
        fflush(log_file);
        return -273.15;
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 2;
    double temperature = raw_temp * 0.25;

    return temperature;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    gpioPWM(HEATER_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(double temperature, int duty_cycle, double pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f, Duty Cycle: %d, PID Output: %.2f\n",
            timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "k:i:d:t:")) != -1) {
        switch (opt) {
            case 'k':
                kp = atof(optarg);
                break;
            case 'i':
                ki = atof(optarg);
                break;
            case 'd':
                kd = atof(optarg);
                break;
            case 't':
                target_temperature = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-k Kp] [-i Ki] [-d Kd] [-t target_temperature]\n", argv[0]);
                return 1;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (parse_arguments(argc, argv)) {
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, 500000, 0); // SPI0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(log_file, "%s", "Error: SPI open failed\n");
        fflush(log_file);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetMode(SPI_CLK_GPIO, PI_OUTPUT);
    gpioSetMode(SPI_CS_GPIO, PI_OUTPUT);
    gpioSetMode(SPI_DO_GPIO, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, 100); // Set PWM range to 0-100

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        double temperature = read_temperature();
        int duty_cycle = 0;
        double pid_output = 0.0;

        if (temperature > -273.0) {
            // Calculate PID output
            double error = target_temperature - temperature;
            integral += error;
            double derivative = error - previous_error;
            pid_output = kp * error + ki * integral + kd * derivative;
            previous_error = error;

            // Limit PID output to 0-100
            if (pid_output < 0) pid_output = 0;
            if (pid_output > 100) pid_output = 100;

            // Set heater PWM duty cycle
            duty_cycle = (int)pid_output;
            set_heater_pwm(duty_cycle);

            // Log data
            log_data(temperature, duty_cycle, pid_output);
        } else {
            // Disable heater and log error
            set_heater_pwm(0);
            fprintf(log_file, "%s", "Error: Invalid temperature reading\n");
            fflush(log_file);
        }

        // Failsafe check
        if (temperature < FAILSAFE_MIN_TEMP || temperature > FAILSAFE_MAX_TEMP) {
            set_heater_pwm(0);
            fprintf(log_file, "%s", "Failsafe triggered: Temperature out of range\n");
            fflush(log_file);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    set_heater_pwm(0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

