#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"

volatile sig_atomic_t program_running = 1;

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    int temp_milli;
    float temp_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    temp_celsius = (float)temp_milli / 1000.0;
    return temp_celsius;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature <= 40.0) {
        duty_cycle = 0;
    } else if (temperature >= 70.0) {
        duty_cycle = 100;
    } else {
        duty_cycle = (int)(((temperature - 40.0) / 30.0) * 100.0);
    }

    return duty_cycle;
}

// Function to set PWM duty cycle on GPIO
int set_fan_speed(int duty_cycle) {
    int pwm_range = 100; // pigpio uses a range of 0-100 for duty cycle
    int pwm_value = (int)((float)duty_cycle / 100.0 * pwm_range);

    if (gpioPWM(FAN_GPIO, pwm_value) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

// Function to log data to CSV file
int log_data(float temperature, int duty_cycle) {
    FILE *fp;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    program_running = 0;
}

int main() {
    int duty_cycle;
    float temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Set PWM range (optional, but recommended)
    gpioSetPWMrange(FAN_GPIO, 100); // Set range to 0-100 for percentage

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value or exiting.\n");
            // Consider exiting the program or using a default temperature
            break; // Exit the loop if temperature reading fails consistently
        }

        // Calculate duty cycle
        duty_cycle = calculate_duty_cycle(temperature);

        // Set fan speed
        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Error setting fan speed, exiting.\n");
            break;
        }

        // Log data
        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Shutdown sequence
    printf("Turning off fan and cleaning up...\n");
    set_fan_speed(0); // Turn off the fan
    gpioTerminate(); // Terminate pigpio

    return 0;
}

