// Define sensor addresses
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09

// Define measurement command
#define MEASURE_CMD 0x3608

// Define CRC polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables for I2C handles and program state
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int i2c_handle, float *flow_rate);
int validate_crc(const unsigned char *data, int len);
void log_data(float flow_rate1, float flow_rate2);
void signal_handler(int signal);

// CRC8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from a sensor
int read_sensor(int i2c_handle, float *flow_rate) {
    unsigned char data[3];
    int result;
    int retries = 3;

    while (retries > 0) {
        // Send measurement command
        result = i2cWriteByteData(i2c_handle, MEASURE_CMD >> 8, MEASURE_CMD & 0xFF);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", result);
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        // Read 3 bytes of data
        result = i2cReadDevice(i2c_handle, (char *)data, 3);
        if (result != 3) {
            fprintf(stderr, "Error reading from I2C device: %d\n", result);
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        // Validate CRC
        if (validate_crc(data, 2)) {
            // Convert raw value to flow rate
            int raw_value = (data[0] << 8) | data[1];
            *flow_rate = raw_value * 0.01;
            return 0; // Success
        } else {
            fprintf(stderr, "CRC validation failed\n");
            retries--;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read sensor after multiple retries\n");
    return -1; // Failure
}

// Function to validate CRC checksum
int validate_crc(const unsigned char *data, int len) {
    unsigned char crc = crc8(data, len);
    return (crc == data[2]);
}

// Function to log data to a file
void log_data(float flow_rate1, float flow_rate2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    FILE *fp = fopen("flow_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow_rate1, flow_rate2);
    fclose(fp);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(1, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(1, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow_rate1, flow_rate2;

    // Main loop
    while (program_running) {
        // Read data from both sensors
        if (read_sensor(i2c_handle1, &flow_rate1) != 0) {
            flow_rate1 = -1.0; // Indicate error
        }
        if (read_sensor(i2c_handle2, &flow_rate2) != 0) {
            flow_rate2 = -1.0; // Indicate error
        }

        // Log the data
        log_data(flow_rate1, flow_rate2);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Close I2C handles
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

