#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the rotary encoder
#define ENCODER_A_PIN 17
#define ENCODER_B_PIN 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold encoder state
typedef struct {
    int a_value;
    int b_value;
    int state;
    float angle;
} encoder_state_t;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void signal_handler(int signal);
int read_encoder_a();
int read_encoder_b();
int update_state(int a, int b, encoder_state_t *state);
float calculate_angle(int state);
int log_data(encoder_state_t state);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ENCODER_A_PIN, PI_INPUT);
    gpioSetMode(ENCODER_B_PIN, PI_INPUT);
    gpioSetPullUpDown(ENCODER_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_PIN, PI_PUD_UP);

    return 0;
}

// Cleanup GPIO pins
void cleanup_gpio() {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Read the state of Encoder A
int read_encoder_a() {
    return gpioRead(ENCODER_A_PIN);
}

// Read the state of Encoder B
int read_encoder_b() {
    return gpioRead(ENCODER_B_PIN);
}

// Update the state based on the current and previous states
int update_state(int a, int b, encoder_state_t *state) {
    int new_state = -1;

    if (a == 0 && b == 0) {
        new_state = 0;
    } else if (a == 1 && b == 0) {
        new_state = 1;
    } else if (a == 1 && b == 1) {
        new_state = 2;
    } else if (a == 0 && b == 1) {
        new_state = 3;
    }

    if (new_state != -1 && new_state != state->state) {
        state->state = new_state;
        return 1; // State changed
    }

    return 0; // State unchanged
}

// Calculate the angular position
float calculate_angle(int state) {
    return (float)state * (360.0 / 4.0);
}

// Log the data to the file
int log_data(encoder_state_t state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, state.angle);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    encoder_state_t encoder_state = {0, 0, 0, 0.0};

    // Main loop
    while (running) {
        int a = read_encoder_a();
        int b = read_encoder_b();

        if (update_state(a, b, &encoder_state)) {
            encoder_state.angle = calculate_angle(encoder_state.state);
            log_data(encoder_state);
        }

        gpioDelay(1000); // Delay for 1ms
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

