#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <stdbool.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x39
#define FIFO_DATA_REG 0x60
#define GPIO_PIN 17
#define IR_THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg, uint16_t *value);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int gpio_set_value(struct gpiod_line *line, int value);
int log_data(FILE *fp, uint16_t red, uint16_t ir);
void signal_handler(int sig);

// I2C read function
int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register address) failed");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }
    *value = (buf[1] << 8) | buf[0];
    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("GPIO set value failed");
        return -1;
    }
    return 0;
}

// Log data function
int log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(fp, "%s,%u,%u\n", timestamp, red, ir);
    fflush(fp);
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal %d received, terminating...\n", sig);
    terminate = 1;
}

int main() {
    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // I2C initialization
    char i2c_device[16];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // GPIO initialization
