    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register and value");
        return -1;
    }
    return 0;
}

// GPIO export function
int gpio_export(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open /sys/class/gpio/export");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Failed to write to /sys/class/gpio/export");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// GPIO unexport function
int gpio_unexport(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open /sys/class/gpio/unexport");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Failed to write to /sys/class/gpio/unexport");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// GPIO set direction function
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO direction file");
        return -1;
    }
    if (write(fd, direction, strlen(direction)) < 0) {
        perror("Failed to write to GPIO direction file");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// GPIO set value function
int gpio_set_value(int pin, int value) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO value file");
        return -1;
    }
    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d.  Must be 0 or 1.\n", value);
        close(fd);
        return -1;
    }
    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);
    if (write(fd, val_str, 1) < 0) {
        perror("Failed to write to GPIO value file");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Read ADPD144RI data function
int read_adpd144ri_data(int fd, uint16_t *red, uint16_t *ir) {
    uint8_t red_lsb, red_msb, ir_lsb, ir_msb;

    if (i2c_read_register(fd, RED_DATA_REG, &red_lsb) < 0) return -1;
    if (i2c_read_register(fd, RED_DATA_REG + 1, &red_msb) < 0) return -1;
    if (i2c_read_register(fd, IR_DATA_REG, &ir_lsb) < 0) return -1;
    if (i2c_read_register(fd, IR_DATA_REG + 1, &ir_msb) < 0) return -1;

    *red = (red_msb << 8) | red_lsb;
    *ir = (ir_msb << 8) | ir_lsb;

    return 0;
}

// Log data function
int log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%u,%u\n", timestamp, red, ir) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    uint8_t part_id;
    uint16_t red_value, ir_value;
    struct timespec sleep_time;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // I2C initialization
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Verify sensor presence
    if (i2c_read_register(i2c_fd, PART_ID_REG, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID register. Sensor may not be present.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (part_id != 0x50) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X. Expected 0x50. Sensor may not be present.\n", part_id);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("ADPD144RI sensor found with PART_ID: 0x%02X\n", part_id);

    // GPIO initialization
    if (gpio_export(GPIO_PIN) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 10ms
    nanosleep(&sleep_time, NULL);

    if (gpio_set_direction(GPIO_PIN, "out") < 0) {
        gpio_unexport(GPIO_PIN);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Log file initialization
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpio_unexport(GPIO_PIN);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        if (read_adpd144ri_data(i2c_fd, &red_value, &ir_value) == 0) {
            printf("Red: %u, IR: %u\n", red_value, ir_value);

            if (ir_value > IR_THRESHOLD) {
                gpio_set_value(GPIO_PIN, 1);
            } else {
                gpio_set_value(GPIO_PIN, 0);
            }

            if (log_data(log_file, red_value, ir_value) < 0) {
                fprintf(stderr, "Error logging data. Continuing...\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Continuing...\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    printf("Cleaning up resources...\n");
    gpio_set_value(GPIO_PIN, 0);
    gpio_unexport(GPIO_PIN);
    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

