#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <gpiod.h>

// Configuration
#define GPIOCHIP "gpiochip0"
#define AUDIO_PIN 17
#define GAIN_PIN 18
#define SAMPLE_INTERVAL_MS 10
#define LOG_FILE "audio_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *audio_line = NULL;
static struct gpiod_line *gain_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

// Function prototypes
int initialize_gpio(void);
void set_gain(int gain);
int read_audio_level(void);
void log_event(int level);
void cleanup(int signal);

// Signal handler
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;

    if (audio_line) {
        gpiod_line_release(audio_line);
    }
    if (gain_line) {
        gpiod_line_release(gain_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

// Initialize GPIO lines
int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    audio_line = gpiod_chip_get_line(chip, AUDIO_PIN);
    if (!audio_line) {
        perror("Error getting audio line");
        gpiod_chip_close(chip);
        return -1;
    }

    gain_line = gpiod_chip_get_line(chip, GAIN_PIN);
    if (!gain_line) {
        perror("Error getting gain line");
        gpiod_line_release(audio_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(audio_line, "audio_input") < 0) {
        perror("Error requesting audio line as input");
        gpiod_line_release(gain_line);
        gpiod_line_release(audio_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(gain_line, "gain_output", 0) < 0) {
        perror("Error requesting gain line as output");
        gpiod_line_release(audio_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Set gain (0 for 60dB, 1 for 30dB)
void set_gain(int gain) {
    if (gpiod_line_set_value(gain_line, gain) < 0) {
        perror("Error setting gain value");
    }
}

// Read audio level (0 or 1)
int read_audio_level(void) {
    int value = gpiod_line_get_value(audio_line);
    if (value < 0) {
        perror("Error reading audio level");
        return -1; // Indicate error
    }
    return value;
}

// Log event to file
void log_event(int level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s LEVEL %d\n", timestamp, level);
    fflush(log_file); // Ensure immediate write
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup(0); // Clean up GPIO before exiting
        return 1;
    }

    // Set initial gain to 60dB
    set_gain(0);

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int level = read_audio_level();
        if (level >= 0) {
            log_event(level);
        }
        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 10ms
    }

    // Cleanup (should not reach here if signal handler works)
    cleanup(0);

    return 0;
}

