#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x36
#define MEASUREMENT_COMMAND 0x3608
#define FLOW_RATE_SCALE_FACTOR 1000.0
#define LOG_FILE "flow_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int16_t *raw_flow, uint8_t *crc);
int validate_crc(int16_t raw_flow, uint8_t received_crc);
float convert_to_flow_rate(int16_t raw_flow);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);

// CRC-8 calculation (Sensirion polynomial 0x31, initial value 0xFF)
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int16_t raw_flow;
    uint8_t crc;
    float flow_rate;

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_flow, &crc) == 0) {
            // Validate CRC
            if (validate_crc(raw_flow, crc)) {
                // Convert to flow rate
                flow_rate = convert_to_flow_rate(raw_flow);

                // Log the flow rate
                if (log_flow_rate(flow_rate) != 0) {
                    fprintf(stderr, "Failed to log flow rate\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

int initialize_sensor() {
    char buf[2];
    buf[0] = (MEASUREMENT_COMMAND >> 8) & 0xFF;
    buf[1] = MEASUREMENT_COMMAND & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "I2C write failed during initialization: %d\n", result);
        return -1;
    }
    return 0;
}

int read_sensor_data(int16_t *raw_flow, uint8_t *crc) {
    char buf[3];
    int result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    *raw_flow = (buf[0] << 8) | buf[1];
    *crc = buf[2];

    return 0;
}

int validate_crc(int16_t raw_flow, uint8_t received_crc) {
    uint8_t data[2];
    data[0] = (raw_flow >> 8) & 0xFF;
    data[1] = raw_flow & 0xFF;

    uint8_t calculated_crc = crc8(data, 2);
    return (calculated_crc == received_crc);
}

float convert_to_flow_rate(int16_t raw_flow) {
    return (float)raw_flow / FLOW_RATE_SCALE_FACTOR;
}

int log_flow_rate(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.3f\n", timestamp, flow_rate);
    fflush(log_file);

    return 0;
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    exit(0);
}

