    uint8_t calculated_crc = crc8(data, 2);
    return (calculated_crc == received_crc);
}

float convert_to_flow_rate(int16_t raw_flow) {
    return (float)raw_flow / FLOW_RATE_SCALE_FACTOR;
}

int log_flow_rate(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.3f\n", timestamp, flow_rate);
    fflush(log_file);

    return 0;
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    exit(0);
}

