#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x70
#define LOG_FILE "air_quality_log.csv"

int i2c_handle;
FILE *log_file;

// Function to read sensor data
int read_sensor_data(int i2c_handle, unsigned char *data) {
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 7);
    if (result != 7) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to extract TVOC from the sensor data
int extract_tvoc(const unsigned char *data) {
    return (data[1] << 8) | data[2];
}

// Function to extract eCO2 from the sensor data
int extract_eco2(const unsigned char *data) {
    return (data[5] << 8) | data[6];
}

// Function to calculate the IAQ index
int calculate_iaq(int tvoc, int eco2) {
    float iaq = 100.0 - (tvoc / 10.0) - ((eco2 - 400) / 50.0);
    if (iaq < 0) iaq = 0;
    if (iaq > 100) iaq = 100;
    return (int)iaq;
}

// Function to log the data to a file
int log_data(FILE *log_file, int iaq, int tvoc, int eco2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, iaq, tvoc, eco2);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    unsigned char sensor_data[7];
    int tvoc, eco2, iaq;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, sensor_data) == 0) {
            // Extract TVOC and eCO2
            tvoc = extract_tvoc(sensor_data);
            eco2 = extract_eco2(sensor_data);

            // Calculate IAQ
            iaq = calculate_iaq(tvoc, eco2);

            // Log data
            log_data(log_file, iaq, tvoc, eco2);

            printf("IAQ: %d, TVOC: %d ppb, eCO2: %d ppm\n", iaq, tvoc, eco2);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 5 seconds.\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    return 0;
}

