#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define CONSUMER_LABEL "ttp223_tamper"
#define INTRUSION_DURATION_SEC 5

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;
static int intrusion_active = 0;
static struct timespec intrusion_start_time;

// Signal handler for graceful shutdown
static void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get current timestamp
static void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to check if intrusion duration has exceeded the threshold
static int check_intrusion_duration(struct timespec start_time)
{
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    double elapsed_time = (current_time.tv_sec - start_time.tv_sec) +
                          (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

    return (elapsed_time >= INTRUSION_DURATION_SEC);
}

int main()
{
    int value;
    struct timespec sleep_time = {0, 100000000}; // 100ms
    char timestamp[20];

    // Register signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR)
    {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip)
    {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line)
    {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line as input
    if (gpiod_line_request_input(line, CONSUMER_LABEL) < 0)
    {
        perror("gpiod_line_request_input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Tamper detection system started. Monitoring GPIO %d on %s...\n", GPIO_LINE, GPIO_CHIP);

    // Main loop
    while (!terminate)
    {
        value = gpiod_line_get_value(line);
        if (value < 0)
        {
            perror("gpiod_line_get_value");
            break;
        }

        if (value == 1) // Sensor is touched
        {
            if (!intrusion_active)
            {
                clock_gettime(CLOCK_MONOTONIC, &intrusion_start_time);
                intrusion_active = 1;
            }

            if (check_intrusion_duration(intrusion_start_time))
            {
                get_timestamp(timestamp);
                printf("%s Intrusion detected!\n", timestamp);
            }
        }
        else // Sensor is released
        {
            intrusion_active = 0;
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (line)
    {
        gpiod_line_release(line);
    }
    if (chip)
    {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

