#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>
#include <alsa/asoundlib.h>

// Define GPIO pin for microphone channel selection
#define GPIO_PIN 17

// Define ALSA device name
#define ALSA_DEVICE "default"

// Define ALSA sampling parameters
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 1
#define SAMPLE_SIZE 32 // 24-bit left-justified

// Define the number of frames to capture
#define NUM_FRAMES 10000

// Global variables for signal handling
volatile sig_atomic_t keep_running = 1;

// Structure to hold ALSA parameters
typedef struct {
    snd_pcm_t *pcm_handle;
    snd_pcm_hw_params_t *hw_params;
} alsa_params_t;

// Function prototypes
int gpio_init(struct gpiod_chip **chip, struct gpiod_line **line);
int gpio_set_value(struct gpiod_line *line, int value);
int alsa_init(alsa_params_t *alsa_params);
int alsa_capture(alsa_params_t *alsa_params, int16_t *buffer, int num_frames);
int write_to_file(const char *filename, const int16_t *buffer, int num_frames);
void signal_handler(int sig);
void cleanup(struct gpiod_chip *chip, struct gpiod_line *line, alsa_params_t *alsa_params);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

// Initialize GPIO
int gpio_init(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, GPIO_PIN);
    if (!*line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line, "audio_capture", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Set GPIO value
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Initialize ALSA
int alsa_init(alsa_params_t *alsa_params) {
    int err;

    // Open PCM device for capture
    err = snd_pcm_open(&alsa_params->pcm_handle, ALSA_DEVICE, SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&alsa_params->hw_params);

    // Fill with default values
    err = snd_pcm_hw_params_any(alsa_params->pcm_handle, alsa_params->hw_params);
    if (err < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(alsa_params->pcm_handle);
        return -1;
    }

    // Set access type
    err = snd_pcm_hw_params_set_access(alsa_params->pcm_handle, alsa_params->hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        snd_pcm_close(alsa_params->pcm_handle);
        return -1;
    }

    // Set format
    err = snd_pcm_hw_params_set_format(alsa_params->pcm_handle, alsa_params->hw_params, SND_PCM_FORMAT_S32_LE);
    if (err < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(alsa_params->pcm_handle);
        return -1;
    }

    // Set number of channels
    err = snd_pcm_hw_params_set_channels(alsa_params->pcm_handle, alsa_params->hw_params, NUM_CHANNELS);
    if (err < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(alsa_params->pcm_handle);
        return -1;
    }

    // Set sample rate
    unsigned int rate = SAMPLE_RATE;
    err = snd_pcm_hw_params_set_rate_near(alsa_params->pcm_handle, alsa_params->hw_params, &rate, 0);
    if (err < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(alsa_params->pcm_handle);
        return -1;
    }

    // Apply hardware parameters
    err = snd_pcm_hw_params(alsa_params->pcm_handle, alsa_params->hw_params);
    if (err < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(alsa_params->pcm_handle);
        return -1;
    }

    return 0;
}

// Capture audio data
int alsa_capture(alsa_params_t *alsa_params, int16_t *buffer, int num_frames) {
    int err;
    int16_t *ptr = buffer;
    int frames_read = 0;
    int16_t *sample_ptr;
    int32_t sample32;

    while (frames_read < num_frames && keep_running) {
        err = snd_pcm_readi(alsa_params->pcm_handle, ptr, num_frames - frames_read);
        if (err == -EPIPE) {
            // Overrun occurred
            fprintf(stderr, "Error: Overrun occurred\n");
            snd_pcm_prepare(alsa_params->pcm_handle);
        } else if (err < 0) {
            fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
            return -1;
        } else {
            // Extract and convert 24-bit samples to 16-bit
            for (int i = 0; i < err; i++) {
                sample32 = *((int32_t *)ptr + i);
                sample32 = (sample32 >> 8) & 0x00FFFFFF; // Right-shift to get 24-bit sample
                *ptr++ = (int16_t)(sample32 >> 8); // Right-shift to get 16-bit sample
            }
            frames_read += err;
        }
    }

    return frames_read;
}

// Write audio data to file
int write_to_file(const char *filename, const int16_t *buffer, int num_frames) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(buffer, sizeof(int16_t), num_frames, fp);
    if (bytes_written != num_frames) {
        fprintf(stderr, "Error writing to file: wrote %zu frames, expected %d\n", bytes_written, num_frames);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing file");
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup(struct gpiod_chip *chip, struct gpiod_line *line, alsa_params_t *alsa_params) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (alsa_params && alsa_params->pcm_handle) {
        snd_pcm_close(alsa_params->pcm_handle);
    }
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    alsa_params_t alsa_params = {0};
    int16_t *audio_buffer = NULL;
    int frames_captured;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (gpio_init(&chip, &line) < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return EXIT_FAILURE;
    }

    // Initialize ALSA
    if (alsa_init(&alsa_params) < 0) {
        fprintf(stderr, "ALSA initialization failed\n");
        cleanup(chip, line, &alsa_params);
        return EXIT_FAILURE;
    }

    // Allocate audio buffer
    audio_buffer = (int16_t *)malloc(NUM_FRAMES * sizeof(int16_t));
    if (!audio_buffer) {
        perror("Error allocating audio buffer");
        cleanup(chip, line, &alsa_params);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Select left channel
        if (gpio_set_value(line, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO value\n");
            break;
        }
        usleep(10000); // Small delay to allow the I2S clock to stabilize

        // Capture audio data
        frames_captured = alsa_capture(&alsa_params, audio_buffer, NUM_FRAMES);
        if (frames_captured < 0) {
            fprintf(stderr, "Audio capture failed\n");
            break;
        }

        // Write to file
        if (write_to_file("audio_capture.pcm", audio_buffer, frames_captured) < 0) {
            fprintf(stderr, "Failed to write to file\n");
            break;
        }

        printf("Captured %d frames and wrote to file\n", frames_captured);
    }

    // Cleanup resources
    free(audio_buffer);
    cleanup(chip, line, &alsa_params);

    return EXIT_SUCCESS;
}

