#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define FLAME_SENSOR_GPIO 4
#define FAN_GPIO 18
#define PWM_FREQUENCY 100
#define DEBOUNCE_PERIOD_MS 50
#define FLAME_DETECTED_TIMEOUT_S 5
#define LOG_FILE "flame_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int flame_detected, int duration_ms);
void log_event(const char *event_type, const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 1000); // Set PWM range to 1000 for finer control

    return 0;
}

// Function to read the flame sensor with debouncing
int read_flame_sensor() {
    int flame_detected = 0;
    int stable_count = 0;
    int current_value;

    for (int i = 0; i < DEBOUNCE_PERIOD_MS * 2; i++) {
        current_value = gpioRead(FLAME_SENSOR_GPIO);
        if (current_value < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", FLAME_SENSOR_GPIO);
            return -1; // Indicate an error
        }

        if (current_value == 0) { // Flame detected (LOW signal)
            stable_count++;
        }
        gpioDelay(DEBOUNCE_PERIOD_MS / 2); // Divide the debounce period for faster response
    }

    if (stable_count >= DEBOUNCE_PERIOD_MS) {
        flame_detected = 1;
    }

    return flame_detected;
}

// Function to control the cooling fan using PWM
void control_fan(int flame_detected, int duration_ms) {
    if (flame_detected) {
        // Calculate duty cycle based on flame duration (exponential curve)
        float duty_cycle = 0.0;
        if (duration_ms > 0) {
            duty_cycle = (float)duration_ms / 1000.0; // Scale duration to 0.0 - 1.0
            duty_cycle = 1.0 - exp(-duty_cycle);       // Exponential decay
            duty_cycle = duty_cycle * 0.8;             // Scale to 0.0 - 0.8
            if (duty_cycle > 1.0) duty_cycle = 1.0;   // Clamp to 1.0
        }

        int pwm_value = (int)(duty_cycle * 1000.0); // Scale to 0 - 1000
        gpioPWM(FAN_GPIO, pwm_value);
    } else {
        gpioPWM(FAN_GPIO, 0); // Turn off the fan
    }
}

// Function to log events to a file
void log_event(const char *event_type, const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s: %s\n", buf, event_type, message);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(FAN_GPIO, 0); // Turn off the fan
    gpioSetMode(FAN_GPIO, PI_INPUT); // Set back to input
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT); // Set back to input
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    log_event("System Start", "System started.");

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("Error", "GPIO initialization failed.");
        cleanup();
        return 1;
    }

    int flame_detected = 0;
    int flame_start_time = 0;
    int flame_duration = 0;

    while (running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            log_event("Error", "Error reading flame sensor.");
            break; // Exit loop on error
        }

        if (sensor_value == 1) {
            if (!flame_detected) {
                flame_detected = 1;
                flame_start_time = time(NULL);
                log_event("Flame Detected", "Flame detected.");
            }
        } else {
            if (flame_detected) {
                flame_detected = 0;
                flame_duration = (time(NULL) - flame_start_time) * 1000; // Duration in milliseconds
                log_event("Flame Ended", "Flame ended.");
            }
        }

        control_fan(flame_detected, flame_duration);

        gpioDelay(10); // Check every 10ms
    }

    cleanup();
    log_event("System Shutdown", "System shutting down.");

    return 0;
}

