#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_CE_PIN 8
#define SPI_CLK_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define TRIGGER_PIN 23
#define DATA_READY_PIN 24
#define HEATMAP_DATA_SIZE 32768 // 256 * 256 * 2 (2 bytes per sample)
#define FRAME_PERIOD_MS 100
#define LOG_FILE_NAME "radar_data.bin"

// Configuration structure
typedef struct {
    float start_frequency;
    float end_frequency;
    int num_chirps;
    int num_samples;
    int frame_period_ms;
} radar_config_t;

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int configure_radar();
int request_frame();
int wait_for_data_ready();
int read_heatmap_data(unsigned char *data);
int log_data(const unsigned char *data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(DATA_READY_PIN, PI_INPUT);
    gpioSetPullUpDown(DATA_READY_PIN, PI_PUD_DOWN);

    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_CLK_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Configure radar (Placeholder - Replace with actual AWR1642 configuration commands)
int configure_radar() {
    // This is a placeholder.  You'll need to send the appropriate
    // commands to the AWR1642 via SPI to configure the radar.
    // Refer to the AWR1642 datasheet and TI's mmWave SDK documentation.
    fprintf(stderr, "Radar configuration (Placeholder)\n");
    return 0;
}

// Request a frame from the radar
int request_frame() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(1); // Short pulse
    gpioWrite(TRIGGER_PIN, 0);
    return 0;
}

// Wait for data ready interrupt
int wait_for_data_ready() {
    int count = 0;
    while (gpioRead(DATA_READY_PIN) == 0 && count < 1000) {
        gpioDelay(1); // Wait 1 ms
        count++;
    }

    if (count >= 1000) {
        fprintf(stderr, "Timeout waiting for data ready\n");
        return -1;
    }
    return 0;
}

// Read heatmap data from SPI
int read_heatmap_data(unsigned char *data) {
    int bytes_read = spiRead(spi_handle, (char *)data, HEATMAP_DATA_SIZE);
    if (bytes_read != HEATMAP_DATA_SIZE) {
        fprintf(stderr, "SPI read failed: %d bytes read (expected %d)\n", bytes_read, HEATMAP_DATA_SIZE);
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(const unsigned char *data) {
    time_t now = time(NULL);
    if (fwrite(&now, sizeof(time_t), 1, log_file) != 1) {
        fprintf(stderr, "Error writing timestamp to log file\n");
        return -1;
    }
    if (fwrite(data, HEATMAP_DATA_SIZE, 1, log_file) != 1) {
        fprintf(stderr, "Error writing data to log file\n");
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Configure radar
    if (configure_radar() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write log file header
    unsigned int magic_number = 0x52444144; // "RDA"
    time_t timestamp = time(NULL);
    radar_config_t config = {77.0, 79.0, 64, 256, FRAME_PERIOD_MS};

    if (fwrite(&magic_number, sizeof(unsigned int), 1, log_file) != 1) {
        fprintf(stderr, "Error writing magic number to log file\n");
        cleanup();
        return 1;
    }
    if (fwrite(&timestamp, sizeof(time_t), 1, log_file) != 1) {
        fprintf(stderr, "Error writing timestamp to log file\n");
        cleanup();
        return 1;
