int log_data(const char *timestamp, double lux) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    uint16_t exponent, mantissa;
    double lux;
    char *timestamp;

    // Main loop
    while (!terminate) {
        // Read sensor data with retry
        int retry = 0;
        int read_result = -1;
        while (retry < RETRY_COUNT && read_result != 0) {
            read_result = read_sensor_data(&exponent, &mantissa);
            if (read_result != 0) {
                fprintf(stderr, "Sensor read failed, retrying (%d/%d)...\n", retry + 1, RETRY_COUNT);
                gpioDelay(100); // Wait before retrying
                retry++;
            }
        }

        if (read_result == 0) {
            // Calculate lux
            lux = calculate_lux(exponent, mantissa);

            // Get timestamp
            timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                // Log data
                if (log_data(timestamp, lux) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "Error getting timestamp.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
        }

        gpioDelay(100); // Wait 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

