static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

// Signal handler for SIGINT (Ctrl+C)
void int_handler(int dummy)
{
    keep_running = 0;
}

// Function to get the current timestamp as a string
char *get_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char *)malloc(20 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to read the flame detection status
int read_flame_status(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading line value: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the flame detection status with a timestamp
void log_flame_status(int status)
{
    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp.\n");
        return;
    }

    if (status == 0) {
        printf("%s Flame Detected: YES\n", timestamp);
    } else {
        printf("%s Flame Detected: NO\n", timestamp);
    }

    free(timestamp); // Free the allocated memory
}

int main()
{
    struct gpiod_line_request_config *config = NULL;
    struct gpiod_line_settings *settings = NULL;
    int ret;

    // Set up signal handling for Ctrl+C
    signal(SIGINT, int_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure the GPIO line as input with pull-up resistor
    settings = gpiod_line_settings_new();
    if (!settings) {
        perror("Error creating GPIO line settings");
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP);

    // Request the GPIO line
    config = gpiod_line_request_config_new();
    if (!config) {
        perror("Error creating GPIO line request config");
        gpiod_line_settings_free(settings);
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_request_config_set_consumer(config, "flame_detect");

    ret = gpiod_line_request(line, config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %d\n", ret);
        gpiod_line_request_config_free(config);
        gpiod_line_settings_free(settings);
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_request_config_free(config);
    gpiod_line_settings_free(settings);

    // Main loop to read and log the flame status
    while (keep_running) {
        int status = read_flame_status(line);
        if (status >= 0) {
            log_flame_status(status);
        } else {
            fprintf(stderr, "Failed to read flame status.\n");
        }

        sleep(1);
    }

    // Clean up resources before exiting
    printf("Exiting gracefully...\n");
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

