#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 18
#define RIGHT_SENSOR_PIN 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

// Signal handler for SIGTERM
void sigterm_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught SIGTERM, exiting gracefully...\n");
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (signal(SIGTERM, sigterm_handler) == SIG_ERR) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    // Main loop to read sensor values
    while (program_running) {
        // Read sensor values
        int left_value = gpioRead(LEFT_SENSOR_PIN);
        int center_value = gpioRead(CENTER_SENSOR_PIN);
        int right_value = gpioRead(RIGHT_SENSOR_PIN);

        // Print sensor values to the console
        printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);

        // Wait for 50 milliseconds
        usleep(50000);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

