#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define the GPIO chip name and line numbers
#define GPIOCHIP "gpiochip0"
#define NUM_CHANNELS 8
int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_CHANNELS];

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int ret;
    struct timespec ts;
    int values[NUM_CHANNELS];

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request each GPIO line for input
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            // Release previously requested lines before exiting
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }

        ret = gpiod_line_request_input(lines[i], "touch_sensor");
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO line %d: %d\n", channel_pins[i], ret);
            // Release previously requested lines before exiting
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop to read and log sensor data
    while (1) {
        // Read the value of each channel
        for (int i = 0; i < NUM_CHANNELS; i++) {
            ret = gpiod_line_get_value(lines[i]);
            if (ret < 0) {
                fprintf(stderr, "Error reading GPIO line %d: %d\n", channel_pins[i], ret);
                // Attempt to continue reading other lines, but log the error
                continue;
            }
            values[i] = ret;
        }

        // Get the current time
        ret = clock_gettime(CLOCK_REALTIME, &ts);
        if (ret < 0) {
            perror("Error getting time");
            continue; // Continue to the next iteration
        }

        // Log the sensor data with timestamp
        printf("%ld.%09ld: ", ts.tv_sec, ts.tv_nsec);
        for (int i = 0; i < NUM_CHANNELS; i++) {
            printf("%d ", values[i]);
        }
        printf("\n");

        // Wait for 100 milliseconds
        usleep(100000); // 100000 microseconds = 100 milliseconds
    }

    // The following lines will never be reached because of the infinite loop.
    // However, they are included for completeness and to demonstrate proper cleanup.
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

