const int num_channels = sizeof(ttp226_pins) / sizeof(ttp226_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Signal handler for SIGTERM
void sigterm_handler(int signal)
{
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure each GPIO pin as input with a pull-down resistor
    for (int i = 0; i < num_channels; i++)
    {
        if (gpioSetMode(ttp226_pins[i], PI_INPUT) != 0)
        {
            fprintf(stderr, "Failed to set GPIO %d as input\n", ttp226_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPullUpDown(ttp226_pins[i], PI_PUD_DOWN) != 0)
        {
            fprintf(stderr, "Failed to set pull-down resistor on GPIO %d\n", ttp226_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop to read and log sensor data
    while (!terminate)
    {
        // Read the state of each channel
        int sensor_states[num_channels];
        for (int i = 0; i < num_channels; i++)
        {
            sensor_states[i] = gpioRead(ttp226_pins[i]);
        }

        // Get the current timestamp
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

        // Print the timestamp and sensor states
        printf("[+%ld ms] ", timestamp_ms);
        for (int i = 0; i < num_channels; i++)
        {
            printf("CH%d=%d ", i + 1, sensor_states[i]);
        }
        printf("\n");

        // Delay for 100 milliseconds
        gpioDelay(100000);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

