#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

// Define the GPIO chip and lines
#define GPIOCHIP "gpiochip0"
#define NUM_CHANNELS 8
const int GPIO_PINS[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_CHANNELS];

// Function prototypes
int read_channel(struct gpiod_line *line);
char* get_iso8601_timestamp();
void log_data(char *timestamp, int *channel_states);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully.\n", signal);

    // Release GPIO lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Reads the state of a single GPIO line
int read_channel(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading line value: %d\n", value);
        return -1; // Indicate error
    }
    return value;
}

// Gets the current timestamp in ISO-8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Logs the timestamp and channel states to the console in CSV format
void log_data(char *timestamp, int *channel_states) {
    printf("%s,", timestamp);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        printf("%d", channel_states[i]);
        if (i < NUM_CHANNELS - 1) {
            printf(",");
        }
    }
    printf("\n");
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIOCHIP);
        return 1;
    }

    // Request GPIO lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d\n", GPIO_PINS[i]);
            // Release already requested lines before exiting
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }

        int ret = gpiod_line_request_input(lines[i], NULL);
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as input: %d\n", GPIO_PINS[i], ret);
            // Release already requested lines before exiting
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop
    while (1) {
        int channel_states[NUM_CHANNELS];
        char *timestamp = get_iso8601_timestamp();

        // Read channel states
        for (int i = 0; i < NUM_CHANNELS; i++) {
            channel_states[i] = read_channel(lines[i]);
            if (channel_states[i] == -1) {
                fprintf(stderr, "Error reading channel %d, exiting.\n", i);
                free(timestamp);
                // Release GPIO lines
                for (int j = 0; j < NUM_CHANNELS; j++) {
                    gpiod_line_release(lines[j]);
                }
                // Close GPIO chip
                gpiod_chip_close(chip);
                return 1;
            }
        }

        // Log data
        log_data(timestamp, channel_states);

        // Free the timestamp memory
        free(timestamp);

        // Wait 50 milliseconds
        usleep(50000); // 50000 microseconds = 50 milliseconds
    }

    return 0;
}

