#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int pigpio_init_result;
    int current_state, previous_state = -1; // Initialize to an invalid state
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Configure GPIO 4 as an input with a pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    // Print startup banner
    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to poll the tilt sensor
    while (program_running) {
        // Read the current state of the tilt sensor
        current_state = gpioRead(TILT_SENSOR_GPIO);

        // Validate the sensor reading
        if (current_state != 0 && current_state != 1) {
            fprintf(stderr, "Error: Invalid sensor reading: %d\n", current_state);
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Check if the tilt state has changed
        if (current_state != previous_state) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the timestamped message to the console
            if (current_state == 0) {
                printf("%s Tilted\n", timestamp);
            } else {
                printf("%s Not Tilted\n", timestamp);
            }

            fflush(stdout); // Flush stdout to prevent output loss

            // Update the previous state
            previous_state = current_state;
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

