#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_CHLIST 0x01
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_UV_INDEX0 0x2C
#define SI1145_REG_ALS_FORCE 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int read_uv_index(float *uv_index);
int read_als_visible(uint16_t *als_visible);
void log_data(float uv_index, uint16_t als_visible);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the Si1145 sensor
int si1145_init() {
    int part_id;

    // Verify PART ID
    part_id = i2cReadByteData(i2c_handle, SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X\n", part_id);
        return -1;
    }

    // Write 0x17 to HW_KEY register
    if (i2cWriteByteData(i2c_handle, SI1145_REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error writing to HW_KEY register\n");
        return -1;
    }

    // Configure CHLIST register to enable UV and ALS_VIS
    if (i2cWriteByteData(i2c_handle, SI1145_REG_CHLIST, 0x17) < 0) {
        fprintf(stderr, "Error writing to CHLIST register\n");
        return -1;
    }

    return 0;
}

// Read UV index from the sensor
int read_uv_index(float *uv_index) {
    int uv_index_raw;

    // Trigger a measurement by writing to ALS_FORCE register
    if (i2cWriteByteData(i2c_handle, SI1145_REG_ALS_FORCE, 0x01) < 0) {
        fprintf(stderr, "Error writing to ALS_FORCE register\n");
        return -1;
    }

    // Wait for a short period for the measurement to complete
    gpioDelay(10000); // 10ms

    // Read UV index data
    uv_index_raw = i2cReadByteData(i2c_handle, SI1145_REG_UV_INDEX0);
    if (uv_index_raw < 0) {
        fprintf(stderr, "Error reading UV index data: %d\n", uv_index_raw);
        return -1;
    }

    *uv_index = (float)uv_index_raw / 10.0;
    return 0;
}

// Read Visible ALS data from the sensor
int read_als_visible(uint16_t *als_visible) {
    int als_visible_low, als_visible_high;

    // Read ALS_VIS_DATA0 (low byte)
    als_visible_low = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA0);
    if (als_visible_low < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA0: %d\n", als_visible_low);
        return -1;
    }

    // Read ALS_VIS_DATA1 (high byte)
    als_visible_high = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA0 + 1);
    if (als_visible_high < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA1: %d\n", als_visible_high);
        return -1;
    }

    *als_visible = (uint16_t)als_visible_low | ((uint16_t)als_visible_high << 8);
    return 0;
}

// Log data to CSV file
void log_data(float uv_index, uint16_t als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.1f,%u\n", timestamp, uv_index, als_visible);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    float uv_index;
    uint16_t als_visible;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (si1145_init() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
