#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define GPIO_PIN 17
#define FLOW_SCALE_FACTOR 0.036
#define ALARM_THRESHOLD 0.5

// Global variables
int i2c_fd;
struct gpiod_chip *gpio_chip;
struct gpiod_line *gpio_line;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_sensor(int address, uint8_t *data);
int crc8(const uint8_t *data, int len);
float convert_flow(int16_t raw_flow);
float calculate_average_flow(float flow1, float flow2);
void set_alarm(float average_flow);
void log_data(float flow1, float flow2, float average_flow);
void signal_handler(int sig);
int gpio_init();
void gpio_cleanup();

// CRC8 calculation function
int crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C read function
int i2c_read_sensor(int address, uint8_t *data) {
    int retries = 3;
    while (retries > 0) {
        if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
            perror("Error: Could not set I2C slave address");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        if (read(i2c_fd, data, 9) == 9) {
            return 0; // Success
        } else {
            perror("Error: I2C read failed");
            retries--;
            usleep(10000); // Wait 10ms before retrying
        }
    }
    return -1; // Failure after retries
}

// Flow conversion function
float convert_flow(int16_t raw_flow) {
    return (float)raw_flow * FLOW_SCALE_FACTOR;
}

// Average flow calculation function
float calculate_average_flow(float flow1, float flow2) {
    return (flow1 + flow2) / 2.0;
}

// Alarm control function
void set_alarm(float average_flow) {
    if (average_flow < ALARM_THRESHOLD) {
        gpiod_line_set_value(gpio_line, 1); // Set GPIO high
    } else {
        gpiod_line_set_value(gpio_line, 0); // Set GPIO low
    }
}

// Data logging function
void log_data(float flow1, float flow2, float average_flow) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Flow1: %.2f ml/min, Flow2: %.2f ml/min, Average: %.2f ml/min\n",
            timestamp, flow1, flow2, average_flow);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// GPIO initialization function
int gpio_init() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error: Could not open GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error: Could not get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "flow_monitor", 0) < 0) {
        perror("Error: Could not request GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }
    return 0;
}

// GPIO cleanup function
void gpio_cleanup() {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    // Signal handling setup
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // I2C initialization
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C bus");
        return 1;
    }

    // GPIO initialization
    if (gpio_init() != 0) {
        close(i2c_fd);
        return 1;
    }

    // Log file initialization
    log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        perror("Error: Could not open log file");
        gpio_cleanup();
        close(i2c_fd);
        return 1;
    }

    // Sensor initialization
    uint8_t init_cmd[2] = {0x36, 0x08};
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        perror("Error: Could not set I2C slave address for sensor 1");
        fclose(log_file);
        gpio_cleanup();
        close(i2c_fd);
        return 1;
    }
    if (write(i2c_fd, init_cmd, 2) != 2) {
        perror("Error: Could not write initialization command to sensor 1");
        fclose(log_file);
        gpio_cleanup();
        close(i2c_fd);
        return 1;
    }
    usleep(100000); // Wait 100ms

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        perror("Error: Could not set I2C slave address for sensor 2");
        fclose(log_file);
        gpio_cleanup();
        close(i2c_fd);
        return 1;
    }
    if (write(i2c_fd, init_cmd, 2) != 2) {
        perror("Error: Could not write initialization command to sensor 2");
        fclose(log_file);
        gpio_cleanup();
        close(i2c_fd);
        return 1;
    }
    usleep(100000); // Wait 100ms

    // Main loop
    while (program_running) {
        uint8_t sensor1_data[9];
        uint8_t sensor2_data[9];
        int16_t raw_flow1, raw_flow2;
        float flow1, flow2, average_flow;

        // Read sensor 1
        if (i2c_read_sensor(SENSOR1_ADDR, sensor1_data) == 0) {
            // CRC validation
            if (crc8(sensor1_data, 2) == sensor1_data[2] &&
                crc8(sensor1_data + 3, 2) == sensor1_data[5] &&
                crc8(sensor1_data + 6, 2) == sensor1_data[8]) {
                // Convert flow data
                raw_flow1 = (int16_t)((sensor1_data[0] << 8) | sensor1_data[1]);
                flow1 = convert_flow(raw_flow1);
            } else {
                fprintf(stderr, "Error: CRC failure for sensor 1\n");
                flow1 = 0.0; // Set to 0 on CRC failure
            }
        } else {
            fprintf(stderr, "Error: I2C read failure for sensor 1\n");
            flow1 = 0.0; // Set to 0 on I2C failure
        }

        // Read sensor 2
        if (i2c_read_sensor(SENSOR2_ADDR, sensor2_data) == 0) {
            // CRC validation
            if (crc8(sensor2_data, 2) == sensor2_data[2] &&
                crc8(sensor2_data + 3, 2) == sensor2_data[5] &&
                crc8(sensor2_data + 6, 2) == sensor2_data[8]) {
                // Convert flow data
                raw_flow2 = (int16_t)((sensor2_data[0] << 8) | sensor2_data[1]);
                flow2 = convert_flow(raw_flow2);
            } else {
                fprintf(stderr, "Error: CRC failure for sensor 2\n");
                flow2 = 0.0; // Set to 0 on CRC failure
            }
        } else {
            fprintf(stderr, "Error: I2C read failure for sensor 2\n");
            flow2 = 0.0; // Set to 0 on I2C failure
        }

        // Calculate average flow
        average_flow = calculate_average_flow(flow1, flow2);

        // Set alarm
        set_alarm(average_flow);

        // Log data
        log_data(flow1, flow2, average_flow);

        sleep(1); // Wait 1 second
    }

    // Cleanup
    fclose(log_file);
    gpio_cleanup();
    close(i2c_fd);

    return 0;
}

