#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define sensor parameters
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x55
#define MODE_CONTROL_REG 0x1D
#define MODE_CONTROL_VALUE 0x10
#define OPERATING_STATUS_REG 0x1B
#define ACCEL_X_L 0x2A
#define ACCEL_X_H 0x2B
#define ACCEL_Y_L 0x2C
#define ACCEL_Y_H 0x2D
#define ACCEL_Z_L 0x2E
#define ACCEL_Z_H 0x2F
#define SCALE_FACTOR 0.0009765625

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int i2c_init(const char *bus, int address);
int sensor_init(int fd);
int sensor_read_status(int fd);
sensor_data_t sensor_read_acceleration(int fd);
void convert_to_g(sensor_data_t raw_data, float *x_g, float *y_g, float *z_g);
char* get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size);
int write_to_csv(const char *timestamp, float x_g, float y_g, float z_g);
void signal_handler(int sig);
void cleanup();

// I2C initialization function
int i2c_init(const char *bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Sensor initialization function
int sensor_init(int fd) {
    uint8_t buf[2];
    buf[0] = MODE_CONTROL_REG;
    buf[1] = MODE_CONTROL_VALUE;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to sensor");
        return -1;
    }

    return 0;
}

// Function to read the operating status register
int sensor_read_status(int fd) {
    uint8_t reg = OPERATING_STATUS_REG;
    uint8_t status;

    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to sensor");
        return -1;
    }

    if (read(fd, &status, 1) != 1) {
        perror("Error reading from sensor");
        return -1;
    }

    return status;
}

// Function to read acceleration data
sensor_data_t sensor_read_acceleration(int fd) {
    sensor_data_t data;
    uint8_t reg;
    uint8_t buffer[6];

    // Read X
    reg = ACCEL_X_L;
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to sensor");
        data.x = 0; data.y = 0; data.z = 0;
        return data;
    }
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from sensor");
        data.x = 0; data.y = 0; data.z = 0;
        return data;
    }
    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);

    // Read Y
    reg = ACCEL_Y_L;
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to sensor");
        data.x = 0; data.y = 0; data.z = 0;
        return data;
    }
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from sensor");
        data.x = 0; data.y = 0; data.z = 0;
        return data;
    }
    data.y = (int16_t)((buffer[1] << 8) | buffer[0]);

    // Read Z
    reg = ACCEL_Z_L;
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to sensor");
        data.x = 0; data.y = 0; data.z = 0;
        return data;
    }
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from sensor");
        data.x = 0; data.y = 0; data.z = 0;
        return data;
    }
    data.z = (int16_t)((buffer[1] << 8) | buffer[0]);

    return data;
}

// Function to convert raw data to g
void convert_to_g(sensor_data_t raw_data, float *x_g, float *y_g, float *z_g) {
    *x_g = raw_data.x * SCALE_FACTOR;
    *y_g = raw_data.y * SCALE_FACTOR;
    *z_g = raw_data.z * SCALE_FACTOR;
}

// Function to get ISO-8601 timestamp
char* get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp_str;
}

// Function to write data to CSV file
int write_to_csv(const char *timestamp, float x_g, float y_g, float z_g) {
    if (csv_file == NULL) {
        csv_file = fopen("fan_health.csv", "a+");
        if (csv_file == NULL) {
            perror("Error opening CSV file");
            return -1;
        }

        // Check if the file is empty, if so, write the header
        fseek(csv_file, 0, SEEK_END);
        long file_size = ftell(csv_file);
        if (file_size == 0) {
            fprintf(csv_file, "Timestamp,X_g,Y_g,Z_g\n");
        }
        fseek(csv_file, 0, SEEK_END);
    }

    fprintf(csv_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x_g, y_g, z_g);
    fflush(csv_file); // Ensure data is written immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", sig);
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize sensor
    if (sensor_init(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Wait for sensor to become active
    int status;
    int attempts = 0;
    while ((status = sensor_read_status(i2c_fd)) < 0 || (status & 0x01) == 0) {
        if (status < 0) {
            fprintf(stderr, "Error reading sensor status. Retrying.\n");
        } else {
            fprintf(stderr, "Sensor not active yet. Status: 0x%02X\n", status);
        }
        usleep(100000); // 100ms
        attempts++;
        if (attempts > 10) {
            fprintf(stderr, "Sensor failed to become active after 1 second. Exiting.\n");
            cleanup();
            return 1;
        }
    }
    printf("Sensor is now active. Status: 0x%02X\n", status);

    // Main loop
    char timestamp[32];
    sensor_data_t raw_data;
    float x_g, y_g, z_g;

    while (!terminate) {
        // Read acceleration data
        raw_data = sensor_read_acceleration(i2c_fd);

        // Convert to g
        convert_to_g(raw_data, &x_g, &y_g, &z_g);

        // Get timestamp
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        // Write to CSV
        if (write_to_csv(timestamp, x_g, y_g, z_g) < 0) {
            fprintf(stderr, "Error writing to CSV file. Retrying.\n");
        }

        // Wait 500ms
        usleep(500000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

