#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN 25

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set sensor pins as inputs with pull-up resistors
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SENSOR_1_PIN as input\n");
        gpioTerminate();
        return -1;
    }
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP);

    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SENSOR_2_PIN as input\n");
        gpioTerminate();
        return -1;
    }
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP);

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN as output\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor values
int read_sensors() {
    int sensor1_value = gpioRead(SENSOR_1_PIN);
    int sensor2_value = gpioRead(SENSOR_2_PIN);

    if (sensor1_value < 0 || sensor2_value < 0) {
        fprintf(stderr, "Error reading sensor values\n");
        return -1; // Indicate an error
    }

    return (sensor1_value == 0 || sensor2_value == 0) ? 1 : 0; // 1 if either sensor detects an obstacle, 0 otherwise
}

// Function to control the LED
void control_led(int obstacle_detected) {
    if (obstacle_detected) {
        if (gpioWrite(LED_PIN, 1) != 0) {
            fprintf(stderr, "Failed to turn LED ON\n");
        }
    } else {
        if (gpioWrite(LED_PIN, 0) != 0) {
            fprintf(stderr, "Failed to turn LED OFF\n");
        }
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
