#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x0E
#define CSV_FILE "magnetic_log.csv"
#define SAMPLE_INTERVAL_MS 100

// TMAG5170 Registers
#define REG_DEVICE_ID 0x00
#define REG_CONFIG 0x01
#define REG_X_AXIS_LSB 0x02
#define REG_X_AXIS_MSB 0x03
#define REG_Y_AXIS_LSB 0x04
#define REG_Y_AXIS_MSB 0x05
#define REG_Z_AXIS_LSB 0x06
#define REG_Z_AXIS_MSB 0x07

// Configuration values
#define CONFIG_CONTINUOUS 0x00 // Continuous conversion mode
#define CONFIG_50MT_RANGE 0x00 // 50 mT range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_mt(int16_t raw_value);
char* get_iso8601_timestamp();
int log_data(char *timestamp, float x, float y, float z);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Function to initialize the sensor
int initialize_sensor() {
    // Verify device ID
    int device_id = i2cReadByteData(i2c_handle, REG_DEVICE_ID);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }
    if (device_id != 0x8D) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }

    // Configure sensor for continuous conversion and 50 mT range
    int config_value = (CONFIG_CONTINUOUS << 4) | CONFIG_50MT_RANGE;
    int result = i2cWriteByteData(i2c_handle, REG_CONFIG, config_value);
    if (result < 0) {
        fprintf(stderr, "Error writing configuration: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, REG_X_AXIS_LSB, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to convert raw value to mT
float convert_to_mt(int16_t raw_value) {
    // LSB scale factor for 50 mT range: 0.0001 mT/LSB
    return (float)raw_value * 0.0001f;
}

// Function to get ISO-8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log data to CSV file
int log_data(char *timestamp, float x, float y, float z) {
    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float x, y, z;
    char *timestamp;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert raw values to mT
            x = convert_to_mt(raw_x);
            y = convert_to_mt(raw_y);
            z = convert_to_mt(raw_z);

            // Get timestamp
            timestamp = get_iso8601_timestamp();

            // Log data
            log_data(timestamp, x, y, z);

            free(timestamp); // Free the allocated memory
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Clean up resources
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

