#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"

volatile int pulse_count = 0;
FILE *log_file = NULL;
pthread_mutex_t mutex;

// Function to get current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(21 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return timestamp;
}

// Function to calculate RPM
double calculate_rpm(int pulses) {
    return (double)pulses * 60.0;
}

// Function to log RPM to file
void log_rpm(double rpm) {
    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp for logging.\n");
        return;
    }

    fprintf(log_file, "%s %.2f\n", timestamp, rpm);
    fflush(log_file);
    free(timestamp);
}

// Function to print RPM to stdout
void print_rpm(double rpm) {
    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp for printing.\n");
        return;
    }

    printf("%s %.2f\n", timestamp, rpm);
    free(timestamp);
}

// Interrupt handler function
void pulse_counter(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) { // Rising edge
        pthread_mutex_lock(&mutex);
        pulse_count++;
        pthread_mutex_unlock(&mutex);
    }
}

// Timer callback function
void timer_callback(void *user) {
    int current_pulse_count;
    double rpm;

    pthread_mutex_lock(&mutex);
    current_pulse_count = pulse_count;
    pulse_count = 0; // Reset pulse count
    pthread_mutex_unlock(&mutex);

    rpm = calculate_rpm(current_pulse_count);
    log_rpm(rpm);
    print_rpm(rpm);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable interrupt
    gpioSetTimerFuncEx(0, 1000, NULL, NULL); // Disable timer

    if (log_file != NULL) {
        fclose(log_file);
    }

    pthread_mutex_destroy(&mutex);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Initialize mutex
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        perror("Mutex initialization failed");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        pthread_mutex_destroy(&mutex);
        return 1;
    }

    // Set interrupt handler
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Failed to set interrupt handler\n");
        fclose(log_file);
        gpioTerminate();
        pthread_mutex_destroy(&mutex);
        return 1;
    }

    // Set timer callback
    if (gpioSetTimerFuncEx(0, 1000, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer callback\n");
        gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable interrupt
        fclose(log_file);
        gpioTerminate();
        pthread_mutex_destroy(&mutex);
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Keep the program running
    while (1) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    return 0;
}

