#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>

// Define GPIO pins for the Hall-effect sensors
#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the number of pulses per revolution (PPR) for the quadrature signal
#define PPR 4

// Define the states of the quadrature state machine
typedef enum {
    STATE_00,
    STATE_01,
    STATE_11,
    STATE_10
} QuadratureState;

// Global variables
static volatile QuadratureState current_state = STATE_00;
static volatile int rotation_direction = 0; // 1 for CW, -1 for CCW, 0 for no rotation
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile int running = 1; // Flag to control the main loop

// Function prototypes
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user);
void log_rotation_event(const char *direction);
void signal_handler(int signal);

// Structure to pass data to the ISR
typedef struct {
    int sensor_a_level;
    int sensor_b_level;
} sensor_data_t;

// ISR for Sensor A
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user) {
    sensor_data_t *data = (sensor_data_t *)user;
    data->sensor_a_level = level;
}

// ISR for Sensor B
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user) {
    sensor_data_t *data = (sensor_data_t *)user;
    data->sensor_b_level = level;
}

// Function to log rotation events with timestamp
void log_rotation_event(const char *direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    pthread_mutex_lock(&state_mutex);
    fprintf(log_file, "%s.%03d: %s\n", timestamp, (int)(gpioTick() % 1000), direction);
    fflush(log_file);
    pthread_mutex_unlock(&state_mutex);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0; // Set the flag to exit the main loop

    // Disable interrupts
    gpioSetAlertFuncEx(SENSOR_A_PIN, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_B_PIN, NULL, NULL);

    // Close the log file
    if (log_file != NULL) {
        pthread_mutex_lock(&state_mutex);
        fflush(log_file);
        fclose(log_file);
        pthread_mutex_unlock(&state_mutex);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_A_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP);
    gpioSetMode(SENSOR_B_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create sensor data structures for ISRs
    sensor_data_t sensor_a_data = {0, 0};
    sensor_data_t sensor_b_data = {0, 0};

    // Set up interrupts for both sensors
    gpioSetAlertFuncEx(SENSOR_A_PIN, sensor_a_isr, &sensor_a_data);
    gpioSetAlertFuncEx(SENSOR_B_PIN, sensor_b_isr, &sensor_b_data);

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor levels
        int sensor_a_level = gpioRead(SENSOR_A_PIN);
        int sensor_b_level = gpioRead(SENSOR_B_PIN);

        // Update quadrature state
        pthread_mutex_lock(&state_mutex);
        QuadratureState new_state;
        if (sensor_a_level == 0 && sensor_b_level == 0) {
            new_state = STATE_00;
        } else if (sensor_a_level == 0 && sensor_b_level == 1) {
            new_state = STATE_01;
        } else if (sensor_a_level == 1 && sensor_b_level == 1) {
            new_state = STATE_11;
        } else {
            new_state = STATE_10;
        }

        // Determine rotation direction
        if (current_state == new_state) {
            rotation_direction = 0; // No rotation
        } else {
            if ((current_state == STATE_00 && new_state == STATE_01) ||
                (current_state == STATE_01 && new_state == STATE_11) ||
                (current_state == STATE_11 && new_state == STATE_10) ||
                (current_state == STATE_10 && new_state == STATE_00)) {
                rotation_direction = 1; // Clockwise
            } else {
                rotation_direction = -1; // Counter-clockwise
            }
        }

        current_state = new_state;
        pthread_mutex_unlock(&state_mutex);

        // Log rotation event if any
        if (rotation_direction == 1) {
            log_rotation_event("CW");
        } else if (rotation_direction == -1) {
            log_rotation_event("CCW");
        }

        // Sleep for a short interval
        gpioDelay(10000); // 10ms
    }

    return 0;
}

