                (current_state == STATE_01 && new_state == STATE_11) ||
                (current_state == STATE_11 && new_state == STATE_10) ||
                (current_state == STATE_10 && new_state == STATE_00)) {
                rotation_direction = 1; // Clockwise
            } else {
                rotation_direction = -1; // Counter-clockwise
            }
        }

        current_state = new_state;
        pthread_mutex_unlock(&state_mutex);

        // Log rotation event if any
        if (rotation_direction == 1) {
            log_rotation_event("CW");
        } else if (rotation_direction == -1) {
            log_rotation_event("CCW");
        }

        // Sleep for a short interval
        gpioDelay(10000); // 10ms
    }

    return 0;
}

