#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 17
#define LED_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME_MS 50

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *touch_line;
struct gpiod_line *led_line;

// Function prototypes
int initialize_gpio(void);
int read_touch_sensor(void);
int toggle_led(void);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request touch sensor line
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        fprintf(stderr, "Error getting touch sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_rising_edge_events(touch_line, "touch_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting rising edge events: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line: %s\n", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read touch sensor state
int read_touch_sensor(void) {
    int value = gpiod_line_get_value(touch_line);
    if (value < 0) {
        fprintf(stderr, "Error reading touch sensor value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Toggle LED state
int toggle_led(void) {
    int current_value = gpiod_line_get_value(led_line);
    if (current_value < 0) {
        fprintf(stderr, "Error reading LED value: %s\n", strerror(errno));
        return -1;
    }

    int new_value = !current_value;
    int ret = gpiod_line_set_value(led_line, new_value);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    struct timespec last_touch_time = {0, 0};
    struct timespec current_time;
    long time_diff_ms;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Touch sensor and LED control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read touch sensor
        if (read_touch_sensor() > 0) {
            // Get current time
            if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
                fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
                cleanup_gpio();
                return 1;
            }

            // Calculate time difference since last touch
            time_diff_ms = (current_time.tv_sec - last_touch_time.tv_sec) * 1000 + (current_time.tv_nsec - last_touch_time.tv_nsec) / 1000000;

            // Debounce
            if (time_diff_ms > DEBOUNCE_TIME_MS) {
                // Toggle LED
                if (toggle_led() < 0) {
                    fprintf(stderr, "LED toggle failed. Exiting.\n");
                    cleanup_gpio();
                    return 1;
                }

                // Update last touch time
                last_touch_time = current_time;
            }
        }

        // Small delay to avoid busy-waiting
        struct timespec delay = {0, 10000000}; // 10 milliseconds
        nanosleep(&delay, NULL);
    }

    return 0;
}

