int buffer_index = 0;
int overflow_count = 0;

// Function prototypes
int read_sensor(int gpio_pin);
void control_led(int gpio_pin, int state);
void log_event(int sensor_pin, int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Turn off LEDs
    control_led(LED_1_PIN, 0);
    control_led(LED_2_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    // Print log buffer contents
    printf("\nLog Buffer Contents:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Sensor: %d, Timestamp: %ld, State: %d\n", event_buffer[i].sensor_pin, event_buffer[i].timestamp, event_buffer[i].state);
    }

    // Print overflow count
    printf("\nOverflow Count: %d\n", overflow_count);

    exit(0);
}

// Function to read sensor state
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to control LED state
void control_led(int gpio_pin, int state) {
    int result = gpioWrite(gpio_pin, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", gpio_pin, result);
    }
}

// Function to log events
void log_event(int sensor_pin, int state) {
    time_t now = time(NULL);

    event_buffer[buffer_index].sensor_pin = sensor_pin;
    event_buffer[buffer_index].timestamp = now;
    event_buffer[buffer_index].state = state;

    buffer_index++;
    if (buffer_index >= BUFFER_SIZE) {
        buffer_index = 0;
        overflow_count++;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to input\n", SENSOR_1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to input\n", SENSOR_2_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to output\n", LED_1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to output\n", LED_2_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int sensor1_state = 0;
    int sensor2_state = 0;
    int last_sensor1_state = 0;
    int last_sensor2_state = 0;

    while (1) {
        // Read sensor states
        int current_sensor1_state = read_sensor(SENSOR_1_PIN);
        int current_sensor2_state = read_sensor(SENSOR_2_PIN);

        if (current_sensor1_state < 0 || current_sensor2_state < 0) {
            // Error reading sensor, exit loop
            break;
        }

        // Control LEDs
        control_led(LED_1_PIN, current_sensor1_state);
        control_led(LED_2_PIN, current_sensor2_state);

        // Log events
        if (current_sensor1_state != last_sensor1_state) {
            log_event(SENSOR_1_PIN, current_sensor1_state);
            last_sensor1_state = current_sensor1_state;
        }
        if (current_sensor2_state != last_sensor2_state) {
            log_event(SENSOR_2_PIN, current_sensor2_state);
            last_sensor2_state = current_sensor2_state;
        }

        // Delay for debounce
        gpioDelay(50000); // 50ms
    }

    // Cleanup (in case of error)
    control_led(LED_1_PIN, 0);
    control_led(LED_2_PIN, 0);
    gpioTerminate();

    return 1;
}

