#define RAIN_SENSOR_GPIO 17
#define LOG_FILE_PATH "/var/log/rain_events.log"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(21 * sizeof(char)); // Allocate memory for the timestamp string
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a message to the log file
void log_message(const char *message) {
    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp, not logging message: %s\n", message);
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s %s\n", timestamp, message);
        fflush(log_file); // Ensure the message is written to the file immediately
    } else {
        fprintf(stderr, "Log file is not open, cannot log message: %s\n", message);
    }
    free(timestamp);
}

// Function to read the rain sensor state
int read_rain_sensor() {
    int sensor_value = gpioRead(RAIN_SENSOR_GPIO);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading rain sensor: %d\n", sensor_value);
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int current_state = -1; // Initialize to an invalid state
    int previous_state = -1;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
