    gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP);

    // Open the log file
    log_file = fopen(LOG_FILE_PATH, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        current_state = read_rain_sensor();
        if (current_state < 0) {
            // Error reading sensor, but continue running
            gpioDelay(500000); // Wait 500ms before retrying
            continue;
        }

        if (current_state != previous_state) {
            if (current_state == 0) {
                log_message("Rain Detected");
            } else {
                log_message("No Rain");
            }
            previous_state = current_state;
        }

        gpioDelay(500000); // Wait 500ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

