#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18

// Debounce time in microseconds
#define DEBOUNCE_TIME 5000

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

// Function prototypes
int initialize_gpio();
SensorStates read_sensors();
double calculate_rpm(double time_difference);
void log_data(SensorStates states);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Enable pull-up resistors (optional, depending on your wiring)
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    return 0;
}

// Function to read the state of the Hall-Effect sensors
SensorStates read_sensors() {
    SensorStates states;
    states.sensor1_state = gpioRead(SENSOR_1_GPIO);
    states.sensor2_state = gpioRead(SENSOR_2_GPIO);
    return states;
}

// Function to calculate the RPM based on the time difference between sensor changes
double calculate_rpm(double time_difference) {
    if (time_difference > 0) {
        return 60.0 / (time_difference * 2.0); // 2 pulses per revolution
    } else {
        return 0.0; // Avoid division by zero
    }
}

// Function to log the sensor data to a CSV file
void log_data(SensorStates states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, states.sensor1_state, states.sensor2_state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main() {
    // Register the cleanup function to be called on exit
    atexit(cleanup);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    SensorStates previous_states = {0, 0};
    double last_change_time = 0.0;
    double time_difference = 0.0;
    double rpm = 0.0;

    printf("Monitoring RPM... Press Ctrl+C to exit.\n");

    while (running) {
        SensorStates current_states = read_sensors();

        // Debounce sensor 1
        if (current_states.sensor1_state != previous_states.sensor1_state) {
            double current_time = time_time();
            if (current_time - last_change_time > (double)DEBOUNCE_TIME / 1000000.0) {
                time_difference = current_time - last_change_time;
                rpm = calculate_rpm(time_difference);
                printf("RPM: %.2f\n", rpm);
                last_change_time = current_time;
            }
        }

        // Log the data
        log_data(current_states);

        previous_states = current_states;
        gpioDelay(1000); // Check every 1 ms
    }

    return 0;
}

