int initialize_sensor();
int read_heart_rate(int *heart_rate);
int read_spo2(int *spo2);
int log_data(int heart_rate, int spo2);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initializes the Si1182 sensor
int initialize_sensor() {
    // Check if the sensor is present by reading the PART_ID register
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", part_id);
        return -1;
    }

    if (part_id != PART_ID) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X (expected 0x%02X)\n", part_id, PART_ID);
        return -1;
    }

    // Configure the sensor for continuous measurement mode
    int result = i2cWriteByteData(i2c_handle, CONFIG_REG, 0x01); // Example configuration value
    if (result < 0) {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", result);
        return -1;
    }

    return 0;
}

// Reads heart rate data from the sensor
int read_heart_rate(int *heart_rate) {
    int hr = i2cReadByteData(i2c_handle, HEART_RATE_REG);
    if (hr < 0) {
        fprintf(stderr, "Error reading heart rate data: %d\n", hr);
        return -1;
    }
    *heart_rate = hr; // Assuming heart rate is directly available in the register
    return 0;
}

// Reads SpO2 data from the sensor
int read_spo2(int *spo2) {
    int sp = i2cReadByteData(i2c_handle, SPO2_REG);
    if (sp < 0) {
        fprintf(stderr, "Error reading SpO2 data: %d\n", sp);
        return -1;
    }
    *spo2 = sp; // Assuming SpO2 is directly available in the register
    return 0;
}

// Logs the heart rate and SpO2 data to a file
int log_data(int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int heart_rate, spo2;

    // Main loop
    while (1) {
        // Read heart rate and SpO2 data
        if (read_heart_rate(&heart_rate) == 0 && read_spo2(&spo2) == 0) {
            // Log the data
            log_data(heart_rate, spo2);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

