#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define threshold duration (in seconds)
#define THRESHOLD_DURATION 2

// Define alarm activation duration (in seconds)
#define ALARM_DURATION 5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int check_threshold(int sensor_value, int *threshold_exceeded, int *start_time);
void activate_alarm();
void deactivate_alarm();
void log_event(const char *event_type);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0); // Ensure alarm is initially off

    return 0;
}

// Read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio_pin);
        return -1; // Indicate error
    }
    return value;
}

// Check if threshold is exceeded
int check_threshold(int sensor_value, int *threshold_exceeded, int *start_time) {
    time_t now = time(NULL);

    if (sensor_value == 1) {
        if (*threshold_exceeded == 0) {
            *start_time = now;
            *threshold_exceeded = 1;
            return 1; // Threshold exceeded
        } else {
            if (difftime(now, *start_time) >= THRESHOLD_DURATION) {
                return 1; // Threshold exceeded
            }
        }
    } else {
        *threshold_exceeded = 0;
    }

    return 0; // Threshold not exceeded
}

// Activate the alarm
void activate_alarm() {
    gpioWrite(ALARM_PIN, 1);
    log_event("alarm_activated");
}

// Deactivate the alarm
void deactivate_alarm() {
    gpioWrite(ALARM_PIN, 0);
    log_event("alarm_deactivated");
}

// Log an event to the log file
void log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", buf, event_type);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    int sensor1_threshold_exceeded = 0;
    int sensor1_start_time = 0;
    int sensor2_threshold_exceeded = 0;
    int sensor2_start_time = 0;
    int alarm_active = 0;

    printf("Monitoring bridge integrity... Press Ctrl+C to exit.\n");

    while (running) {
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value < 0 || sensor2_value < 0) {
            // Error reading sensor, exit loop
            break;
        }

        int sensor1_exceeded = check_threshold(sensor1_value, &sensor1_threshold_exceeded, &sensor1_start_time);
        int sensor2_exceeded = check_threshold(sensor2_value, &sensor2_threshold_exceeded, &sensor2_start_time);

        if (sensor1_exceeded || sensor2_exceeded) {
            if (!alarm_active) {
                activate_alarm();
                alarm_active = 1;
                gpioDelay(ALARM_DURATION * 1000000); // Delay for alarm duration (microseconds)
                deactivate_alarm();
                alarm_active = 0;
            }
        }

        gpioDelay(100000); // Poll every 100 milliseconds (microseconds)
    }

    // Cleanup
    printf("Cleaning up...\n");
    deactivate_alarm();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

