#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x1D
#define LED_GPIO 17
#define THRESHOLD 500.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t x, y, z;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
double calculate_vibration_magnitude(sensor_data_t data);
void control_led(int on);
void log_event(double magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the Omron D7S-A0011 sensor
int initialize_sensor() {
    int retries = RETRY_COUNT;
    int status;

    // Check sensor presence by reading CTRL1 register
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, 0x1F);
        if (status >= 0) {
            // Clear power-down bit (bit 7 of CTRL1)
            status = i2cWriteByteData(i2c_handle, 0x1F, 0x00); // Assuming no power down bit
            if (status < 0) {
                fprintf(stderr, "Error writing to CTRL1 register: %d\n", status);
                log_event(-1.0); // Log error
                return -1;
            }
            return 0; // Initialization successful
        } else {
            fprintf(stderr, "Error reading CTRL1 register: %d, retrying...\n", status);
            log_event(-1.0); // Log error
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    fprintf(stderr, "Failed to initialize sensor after %d retries.\n", RETRY_COUNT);
    return -1; // Initialization failed
}

// Reads acceleration data from the sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[6];
    int retries = RETRY_COUNT;
    int status;

    while (retries > 0) {
        status = i2cReadI2CBlockData(i2c_handle, 0x28, buffer, 6);
        if (status == 6) {
            // Convert little-endian data to signed 16-bit integers
            data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
            data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
            data.z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return data;
        } else {
            fprintf(stderr, "Error reading sensor data: %d, retrying...\n", status);
            log_event(-1.0); // Log error
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    data.x = data.y = data.z = 0; // Return default values
    return data;
}

// Calculates the Euclidean vibration magnitude
double calculate_vibration_magnitude(sensor_data_t data) {
    double x = (double)data.x;
    double y = (double)data.y;
    double z = (double)data.z;
    return sqrt(x * x + y * y + z * z);
}

// Controls the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Logs events to a file
void log_event(double magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        if (magnitude >= 0) {
            fprintf(log_file, "%s, Vibration Magnitude: %.2f\n", timestamp, magnitude);
        } else {
            fprintf(log_file, "%s, ERROR: I2C communication error\n", timestamp);
        }
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        double magnitude = calculate_vibration_magnitude(data);

        if (magnitude > THRESHOLD) {
            printf("Vibration detected! Magnitude: %.2f\n", magnitude);
            control_led(1); // Turn LED on
            log_event(magnitude);
            gpioDelay(1000000); // 1 second delay
            control_led(0); // Turn LED off
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

