        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        double magnitude = calculate_vibration_magnitude(data);

        if (magnitude > THRESHOLD) {
            printf("Vibration detected! Magnitude: %.2f\n", magnitude);
            control_led(1); // Turn LED on
            log_event(magnitude);
            gpioDelay(1000000); // 1 second delay
