#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for the flame sensors
#define FLAME_SENSOR_1_GPIO 2
#define FLAME_SENSOR_2_GPIO 3
#define FLAME_SENSOR_3_GPIO 4
#define FLAME_SENSOR_4_GPIO 17
#define FLAME_SENSOR_5_GPIO 27

// Define the log file path
#define LOG_FILE "/var/log/flame_events.log"

// Define the debounce time in milliseconds
#define DEBOUNCE_TIME_MS 50

// Structure to hold sensor data
typedef struct {
    int gpio_pin;
    int sensor_id;
    struct gpiod_line *line;
    int last_state;
} sensor_data_t;

// Global variables
static struct gpiod_chip *chip = NULL;
static sensor_data_t sensors[5];
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_sensor(sensor_data_t *sensor);
int debounce_sensor(sensor_data_t *sensor);
int log_event(int sensor_id, int gpio_pin);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up resources...");

    // Release GPIO lines
    for (int i = 0; i < 5; i++) {
        if (sensors[i].line) {
            gpiod_line_release(sensors[i].line);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close syslog
    closelog();

    syslog(LOG_INFO, "Cleanup complete.");
}

// Initialize GPIO using libgpiod
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    // Configure sensor data
    sensors[0].gpio_pin = FLAME_SENSOR_1_GPIO;
    sensors[0].sensor_id = 1;
    sensors[1].gpio_pin = FLAME_SENSOR_2_GPIO;
    sensors[1].sensor_id = 2;
    sensors[2].gpio_pin = FLAME_SENSOR_3_GPIO;
    sensors[2].sensor_id = 3;
    sensors[3].gpio_pin = FLAME_SENSOR_4_GPIO;
    sensors[3].sensor_id = 4;
    sensors[4].gpio_pin = FLAME_SENSOR_5_GPIO;
    sensors[4].sensor_id = 5;

    // Request GPIO lines
    for (int i = 0; i < 5; i++) {
        sensors[i].line = gpiod_chip_get_line(chip, sensors[i].gpio_pin);
        if (!sensors[i].line) {
            syslog(LOG_ERR, "Failed to get line for GPIO %d: %s", sensors[i].gpio_pin, strerror(errno));
            return -1;
        }

        ret = gpiod_line_request_input(sensors[i].line, "flame_monitor");
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to request line for GPIO %d: %s", sensors[i].gpio_pin, strerror(errno));
            return -1;
        }

        sensors[i].last_state = gpiod_line_get_value(sensors[i].line);
        if (sensors[i].last_state < 0) {
            syslog(LOG_ERR, "Failed to read initial value for GPIO %d: %s", sensors[i].gpio_pin, strerror(errno));
            return -1;
        }
    }

    return 0;
}

// Read sensor value
int read_sensor(sensor_data_t *sensor) {
    int value = gpiod_line_get_value(sensor->line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read value for GPIO %d: %s", sensor->gpio_pin, strerror(errno));
        return -1;
    }
    return value;
}

// Debounce sensor reading
int debounce_sensor(sensor_data_t *sensor) {
    int value = read_sensor(sensor);
    if (value < 0) {
        return -1; // Propagate error
    }

    struct timespec delay = {0, DEBOUNCE_TIME_MS * 1000000L}; // 50ms
    nanosleep(&delay, NULL);

    int debounced_value = read_sensor(sensor);
    if (debounced_value < 0) {
        return -1; // Propagate error
    }

    return debounced_value;
}

// Log event to file
int log_event(int sensor_id, int gpio_pin) {
    FILE *fp = NULL;
    int ret = 0;

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open log file %s: %s", LOG_FILE, strerror(errno));
        return -1;
    }

    // Acquire exclusive lock
    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Failed to acquire lock on log file %s: %s", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    // Get current timestamp
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    // Write event to log file
    ret = fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, sensor_id, gpio_pin);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to write to log file %s: %s", LOG_FILE, strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    // Flush the buffer to ensure immediate write
    if (fflush(fp) != 0) {
        syslog(LOG_ERR, "Failed to flush log file %s: %s", LOG_FILE, strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    // Release lock
    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Failed to release lock on log file %s: %s", LOG_FILE, strerror(errno));
    }

    fclose(fp);
    return 0;
}

int main(void) {
    // Initialize syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting.");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Flame monitor started.");

    // Main loop
    while (!terminate) {
        for (int i = 0; i < 5; i++) {
            int current_state = read_sensor(&sensors[i]);
            if (current_state < 0) {
                syslog(LOG_ERR, "Failed to read sensor %d, continuing...", sensors[i].sensor_id);
                continue; // Skip to the next sensor
            }

            if (current_state == 0 && sensors[i].last_state == 1) {
                // Flame detected (LOW to HIGH transition)
                int debounced_state = debounce_sensor(&sensors[i]);
                if (debounced_state < 0) {
                    syslog(LOG_ERR, "Debounce failed for sensor %d, continuing...", sensors[i].sensor_id);
                    continue; // Skip to the next sensor
                }

                if (debounced_state == 0) {
                    // Confirmed flame detection
                    if (log_event(sensors[i].sensor_id, sensors[i].gpio_pin) < 0) {
                        syslog(LOG_ERR, "Failed to log event for sensor %d, continuing...", sensors[i].sensor_id);
                    }
                }
            }

            sensors[i].last_state = current_state;
        }

        sleep(1); // Poll every 1 second
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

