#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define the GPIO chip name and lines
#define GPIOCHIP "gpiochip0"

// Define the GPIO lines connected to the TTP226 outputs
const int gpio_lines[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_lines = sizeof(gpio_lines) / sizeof(gpio_lines[0]);

// Structure to store the previous state of each line
struct {
    int previous_state[8];
} sensor_state = {{0}};

// Global variable to store the GPIO chip
struct gpiod_chip *chip = NULL;

// Function prototypes
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line ***lines);
int read_sensor_data(struct gpiod_line ***lines);
void log_data(int sensor_index, int bcm_pin, int state);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line ***lines);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        cleanup_gpio(chip, NULL); // Pass NULL as lines are not used in cleanup
        exit(0);
    }
}

// Function to initialize the GPIO chip and lines
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line ***lines) {
    *chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!*chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    *lines = malloc(num_lines * sizeof(struct gpiod_line *));
    if (!*lines) {
        fprintf(stderr, "Error allocating memory for lines: %s\n", strerror(errno));
        gpiod_chip_close(*chip);
        return -1;
    }

    for (int i = 0; i < num_lines; i++) {
        (*lines)[i] = gpiod_chip_get_line(*chip, gpio_lines[i]);
        if (!(*lines)[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", gpio_lines[i], strerror(errno));
            // Clean up already allocated lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release((*lines)[j]);
            }
            free(*lines);
            gpiod_chip_close(*chip);
            return -1;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_sensor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        if (gpiod_line_request(*(*lines)[i], &config, 0) < 0) {
            fprintf(stderr, "Error requesting line %d: %s\n", gpio_lines[i], strerror(errno));
            // Clean up already allocated lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release((*lines)[j]);
            }
            free(*lines);
            gpiod_chip_close(*chip);
            return -1;
        }
    }

    return 0;
}

// Function to read the sensor data
int read_sensor_data(struct gpiod_line ***lines) {
    for (int i = 0; i < num_lines; i++) {
        int current_state = gpiod_line_get_value((*lines)[i]);
        if (current_state < 0) {
            fprintf(stderr, "Error reading line %d: %s\n", gpio_lines[i], strerror(errno));
            return -1;
        }

        if (current_state != sensor_state.previous_state[i]) {
            log_data(i, gpio_lines[i], current_state);
            sensor_state.previous_state[i] = current_state;
        }
    }
    return 0;
}

// Function to log the data with ISO-8601 timestamp
void log_data(int sensor_index, int bcm_pin, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s - Sensor %d (BCM %d): %s\n", timestamp, sensor_index, bcm_pin, state ? "Touched" : "Released");
}

// Function to cleanup the GPIO lines and chip
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line ***lines) {
    if (chip) {
        if (lines && *lines) {
