#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define ALS_GAIN_1_8 0x00
#define ALS_INT_100MS 0x00
#define LED_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define LUX_THRESHOLD_1 100
#define LUX_THRESHOLD_2 500
#define LUX_THRESHOLD_3 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_device();
int config_veml7700();
int read_als_data(unsigned int *raw_data);
float convert_to_lux(unsigned int raw_data);
int set_led_brightness(float lux);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);
void cleanup();

// Structure for VEML7700 configuration
typedef struct {
    unsigned char gain;
    unsigned char integration_time;
} veml7700_config_t;

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C device
int open_i2c_device() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the VEML7700 sensor
int config_veml7700() {
    unsigned short config_value = (ALS_INT_100MS << 8) | ALS_GAIN_1_8;
    char buf[2];
    buf[0] = config_value & 0xFF; // Low byte
    buf[1] = (config_value >> 8) & 0xFF; // High byte

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write config to VEML7700: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read ALS data from the sensor
int read_als_data(unsigned int *raw_data) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read ALS data: %d\n", result);
        return -1;
    }

    *raw_data = (buf[1] << 8) | buf[0]; // Combine high and low bytes
    return 0;
}

// Function to convert raw data to lux
float convert_to_lux(unsigned int raw_data) {
    return (float)raw_data * 0.0576;
}

// Function to set the LED brightness using PWM
int set_led_brightness(float lux) {
    int brightness;

    if (lux < LUX_THRESHOLD_1) {
        brightness = 100;
    } else if (lux < LUX_THRESHOLD_2) {
        brightness = 75;
    } else if (lux < LUX_THRESHOLD_3) {
        brightness = 50;
    } else {
        brightness = 25;
    }

    gpioPWM(LED_GPIO, brightness);
    return 0;
}

// Function to log data to a file
int log_data(float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    gpioPWM(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    if (open_i2c_device() != 0) {
        cleanup();
        return 1;
    }

    // Configure VEML7700 sensor
    if (config_veml7700() != 0) {
        cleanup();
        return 1;
    }

    // Set PWM frequency and range for LED control
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    unsigned int raw_data;
    float lux;
    int brightness;
    int error_code = 0;

    // Main loop
    while (!terminate) {
        // Read ALS data
        if (read_als_data(&raw_data) == 0) {
            // Convert to lux
            lux = convert_to_lux(raw_data);

            // Set LED brightness
            set_led_brightness(lux);

            // Log data
            log_data(lux, brightness, error_code);
        } else {
            error_code = -1; // Indicate I2C read error
            log_data(0.0, 0, error_code);
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

