#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for touch sensors and LED
#define LED_PIN 17
#define TOUCH_PIN_START 2
#define TOUCH_PIN_END 9
#define NUM_CHANNELS 8

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_channels();
int debounce_channel(int channel);
int log_touch_event(int channel);
void control_led(int state);
void signal_handler(int signal);
void cleanup();

// Structure to hold previous touch states
struct {
    int previous_state[NUM_CHANNELS];
} touch_state = {{0}};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        int touch_data = read_touch_channels();

        // Debounce and log touch events
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int current_state = (touch_data >> i) & 1;
            if (current_state != touch_state.previous_state[i]) {
                if (debounce_channel(i + 1)) {
                    log_touch_event(i + 1);
                    touch_state.previous_state[i] = current_state;
                }
            }
        }

        // Control the LED based on touch data
        int any_touch = 0;
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if ((touch_data >> i) & 1) {
                any_touch = 1;
                break;
            }
        }
        control_led(any_touch);

        gpioDelay(10); // Small delay to reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set touch sensor pins as inputs with pull-down resistors
    for (int i = TOUCH_PIN_START; i <= TOUCH_PIN_END; i++) {
        gpioSetMode(i, PI_INPUT);
        gpioSetPullUpDown(i, PI_PUD_DOWN);
    }

    return 0;
}

// Read the digital values from the touch sensor channels
int read_touch_channels() {
    int touch_data = 0;
    for (int i = TOUCH_PIN_START; i <= TOUCH_PIN_END; i++) {
        int value = gpioRead(i);
        touch_data |= (value << (i - TOUCH_PIN_START));
    }
    return touch_data;
}

// Debounce a touch sensor channel
int debounce_channel(int channel) {
    int pin = TOUCH_PIN_START + channel - 1;
    int current_state = gpioRead(pin);
    gpioDelay(DEBOUNCE_TIME * 1000); // Convert ms to microseconds
    int debounced_state = gpioRead(pin);
    return (current_state == debounced_state) ? current_state : 0; // Return the debounced state
}

// Log a touch event to the log file
int log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
        fflush(log_file); // Ensure data is written to disk immediately
        printf("%s - Channel %d Touched\n", timestamp, channel);
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Control the LED based on the touch sensor state
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources.\n");
    control_led(0); // Turn off the LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
}

