#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_VALUE 0xC810
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_device();
int write_config_register(int handle, int config_value);
int read_result_register(int handle, uint16_t *result);
float calculate_lux(uint16_t result);
int log_data(float lux);
void print_lux(float lux);
void signal_handler(int signal);
void cleanup();

// Structure for grouping sensor data (optional)
typedef struct {
    float lux;
    time_t timestamp;
} sensor_data_t;

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device() {
    int handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write configuration register
int write_config_register(int handle, int config_value) {
    uint16_t swapped_value = ((config_value & 0xFF00) >> 8) | ((config_value & 0x00FF) << 8);
    int result = i2cWriteWordData(handle, CONFIG_REG, swapped_value);
    if (result < 0) {
        fprintf(stderr, "Failed to write config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read result register
int read_result_register(int handle, uint16_t *result) {
    int raw_result = i2cReadWordData(handle, RESULT_REG);
    if (raw_result < 0) {
        fprintf(stderr, "Failed to read result register: %d\n", raw_result);
        return -1;
    }

    *result = ((raw_result & 0xFF00) >> 8) | ((raw_result & 0x00FF) << 8);
    return 0;
}

// Calculate lux value
float calculate_lux(uint16_t result) {
    int exponent = (result >> 12) & 0x0F;
    int mantissa = result & 0x0FFF;
    return mantissa * 0.01 * (1 << exponent);
}

// Log data to file
int log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file);
    return 0;
}

// Print lux value to stdout
void print_lux(float lux) {
    printf("Lux: %.2f\n", lux);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c_device();
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write configuration register
    if (write_config_register(i2c_handle, CONFIG_VALUE) != 0) {
        cleanup();
        return 1;
    }

    // Wait for first conversion
    gpioDelay(100000); // 100 ms

    // Main loop
    while (!terminate) {
        uint16_t result;
        if (read_result_register(i2c_handle, &result) == 0) {
            float lux = calculate_lux(result);
            log_data(lux);
            print_lux(lux);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(1);
    }

    // Cleanup resources before exiting
    cleanup();
    return 0;
}

