#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define the GPIO chip and line
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4 // GPIO4 (physical pin 7)

// Debounce interval in milliseconds
#define DEBOUNCE_INTERVAL_MS 50

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_touch_sensor(void);
int log_touch_event(const char *event_type);
void cleanup(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Initialize GPIO line
int init_gpio(void)
{
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO line as input with pull-down bias
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "touch_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read touch sensor value
int read_touch_sensor(void)
{
    int value;
    int ret;

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        return -1;
    }
    value = ret;

    return value;
}

// Log touch event to file
int log_touch_event(const char *event_type)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write to log file
    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file);

    return 0;
}

// Cleanup resources
void cleanup(void)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void)
{
    int current_state = 0; // 0 = released, 1 = pressed
    int previous_state = 0;
    struct timespec sleep_time;
    int touch_value;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Set debounce interval
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = DEBOUNCE_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds

    // Main loop
    while (!terminate) {
        // Read touch sensor value
        touch_value = read_touch_sensor();
        if (touch_value < 0) {
            fprintf(stderr, "Error reading touch sensor. Continuing...\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }
        current_state = touch_value;

        // Detect state change
        if (current_state != previous_state) {
            if (current_state == 1) {
                log_touch_event("Touch Detected");
            } else {
                log_touch_event("Touch Released");
            }
            previous_state = current_state;
        }

        // Debounce
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

