#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x08
#define FLOW_COMMAND_1 0x36
#define FLOW_COMMAND_2 0x08
#define FLOW_COMMAND_LENGTH 2
#define FLOW_DATA_LENGTH 3
#define FLOW_RATE_SCALE_FACTOR 90.0
#define MIN_FLOW_RATE 0.0
#define MAX_FLOW_RATE 100.0
#define LOG_FILE "cooling_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int start_measurement();
int read_flow_data(int *raw_flow, unsigned char *crc);
int validate_crc(int raw_flow, unsigned char received_crc);
float convert_flow_rate(int raw_flow);
int log_data(float flow_rate, int raw_flow, const char *status);
void signal_handler(int signal);

// CRC8 calculation (polynomial 0x31, init 0xFF)
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Start continuous measurement
int start_measurement() {
    char command[FLOW_COMMAND_LENGTH] = {FLOW_COMMAND_1, FLOW_COMMAND_2};
    int result = i2cWriteDevice(i2c_handle, command, FLOW_COMMAND_LENGTH);
    if (result != FLOW_COMMAND_LENGTH) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    gpioDelay(2000); // Wait 2 ms
    return 0;
}

// Read flow data
int read_flow_data(int *raw_flow, unsigned char *crc) {
    char buffer[FLOW_DATA_LENGTH];
    int result = i2cReadDevice(i2c_handle, buffer, FLOW_DATA_LENGTH);
    if (result != FLOW_DATA_LENGTH) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    *raw_flow = (buffer[0] << 8) | buffer[1];
    *crc = buffer[2];

    return 0;
}

// Validate CRC
int validate_crc(int raw_flow, unsigned char received_crc) {
    unsigned char data[2] = {(raw_flow >> 8) & 0xFF, raw_flow & 0xFF};
    unsigned char calculated_crc = crc8(data, 2);
    return (calculated_crc == received_crc) ? 0 : -1;
}

// Convert raw flow to ml/min
float convert_flow_rate(int raw_flow) {
    return (float)raw_flow / FLOW_RATE_SCALE_FACTOR;
}

// Log data to file
int log_data(float flow_rate, int raw_flow, const char *status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%d,%s\n", timestamp, flow_rate, raw_flow, status);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Raw Flow,Status\n");
    }

    // Main loop
    while (!terminate) {
        // Initialize I2C
        if (initialize_i2c() != 0) {
            fprintf(stderr, "I2C initialization failed, retrying...\n");
            log_data(0.0, 0, "ERROR: I2C INIT");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Start measurement
        if (start_measurement() != 0) {
            fprintf(stderr, "Measurement start failed, retrying...\n");
            i2cClose(i2c_handle);
            log_data(0.0, 0, "ERROR: MEASUREMENT START");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Read flow data
        int raw_flow;
        unsigned char crc;
        if (read_flow_data(&raw_flow, &crc) != 0) {
            fprintf(stderr, "Flow data read failed, retrying...\n");
            i2cClose(i2c_handle);
            log_data(0.0, 0, "ERROR: FLOW DATA READ");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC
        if (validate_crc(raw_flow, crc) != 0) {
            fprintf(stderr, "CRC validation failed\n");
            log_data(0.0, raw_flow, "ERROR: CRC");
            i2cClose(i2c_handle);
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Convert flow rate
        float flow_rate = convert_flow_rate(raw_flow);

        // Validate flow rate
        const char *status = "OK";
        if (flow_rate < MIN_FLOW_RATE || flow_rate > MAX_FLOW_RATE) {
            status = "INVALID";
        }

        // Log data
        log_data(flow_rate, raw_flow, status);

        // Close I2C handle
        i2cClose(i2c_handle);

        // Wait 1 second
        gpioDelay(1000000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

