#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <stdbool.h>

// Define GPIO pins
#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define CSV file name
#define CSV_FILE "path_log.csv"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *left_line = NULL;
static struct gpiod_line *middle_line = NULL;
static struct gpiod_line *right_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(struct gpiod_line *line);
char *get_iso8601_timestamp(char *timestamp_buffer, size_t buffer_size);
int write_to_csv(const char *timestamp, int left, int middle, int right);
void signal_handler(int sig);
int setup_gpio(void);
void cleanup_gpio(void);

// Signal handler function
void signal_handler(int sig)
{
    if (sig == SIGINT)
    {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        terminate = 1;
    }
}

// Function to read sensor value
int read_sensor(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0)
    {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to get ISO-8601 timestamp
char *get_iso8601_timestamp(char *timestamp_buffer, size_t buffer_size)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp_buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp_buffer;
}

// Function to write data to CSV file
int write_to_csv(const char *timestamp, int left, int middle, int right)
{
    if (log_file == NULL)
    {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0)
    {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to setup GPIO lines
int setup_gpio(void)
{
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip)
    {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);

    if (!left_line || !middle_line || !right_line)
    {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        cleanup_gpio();
        return -1;
    }

    if (gpiod_line_request_input(left_line, "obstacle_avoidance") < 0 ||
        gpiod_line_request_input(middle_line, "obstacle_avoidance") < 0 ||
        gpiod_line_request_input(right_line, "obstacle_avoidance") < 0)
    {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(errno));
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void)
{
    if (left_line)
    {
        gpiod_line_release(left_line);
        left_line = NULL;
    }
    if (middle_line)
    {
        gpiod_line_release(middle_line);
        middle_line = NULL;
    }
    if (right_line)
    {
        gpiod_line_release(right_line);
        right_line = NULL;
    }
    if (chip)
    {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void)
{
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Setup GPIO
    if (setup_gpio() < 0)
    {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Open CSV file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0)
    {
        fprintf(log_file, "timestamp,left,middle,right\n");
        fflush(log_file);
    }

    // Main loop
    char timestamp[32];
    while (!terminate)
    {
        // Read sensor values
        int left_value = read_sensor(left_line);
        int middle_value = read_sensor(middle_line);
        int right_value = read_sensor(right_line);

        if (left_value < 0 || middle_value < 0 || right_value < 0)
        {
            fprintf(stderr, "Error reading sensor values. Continuing...\n");
            usleep(50000); // Sleep for 50ms
            continue;
        }

        // Get timestamp
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        // Write to CSV
        if (write_to_csv(timestamp, left_value, middle_value, right_value) < 0)
        {
            fprintf(stderr, "Error writing to CSV. Continuing...\n");
        }

        // Sleep for 50ms
        usleep(50000);
    }

    // Cleanup
    cleanup_gpio();
    if (log_file)
    {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

