#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24

// Define GPIO chip
#define GPIO_CHIP "gpiochip4"

// Define log file name
#define LOG_FILE "touch_log.txt"

// Global variables for GPIO lines and chip
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *touch_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_init(void);
int log_event(const char *event_type, const char *led_state);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// GPIO initialization function
int gpio_init(void)
{
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    // Request touch sensor line
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        cleanup();
        return -1;
    }

    ret = gpiod_line_request_input(touch_line, "touch_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        cleanup();
        return -1;
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", LED_PIN, strerror(errno));
        cleanup();
        return -1;
    }

    ret = gpiod_line_request_output(led_line, "led", 0); // Initial state: off
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        cleanup();
        return -1;
    }

    return 0;
}

// Log event function
int log_event(const char *event_type, const char *led_state)
{
    time_t now;
    struct tm *tm_info;
    char timestamp[30];

    // Get current time
    time(&now);
    tm_info = gmtime(&now);

    // Format timestamp as ISO-8601
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    // Write log entry
    fprintf(log_file, "%s - %s - LED: %s\n", timestamp, event_type, led_state);

    // Close log file
    fclose(log_file);
    log_file = NULL; // Reset log_file after closing

    return 0;
}

// Cleanup function
void cleanup(void)
{
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void)
{
    int value;
    int led_state = 0; // 0 = off, 1 = on
    int ret;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    fprintf(stderr, "Touch sensor application started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read touch sensor value
        value = gpiod_line_get_value(touch_line);
        if (value < 0) {
            fprintf(stderr, "Error reading touch sensor value: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        // Check for touch event (rising edge)
        if (value == 1) {
            // Toggle LED state
            led_state = !led_state;

            // Set LED value
            ret = gpiod_line_set_value(led_line, led_state);
            if (ret < 0) {
                fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
                cleanup();
                return EXIT_FAILURE;
            }

            // Log event
            if (log_event("touch", led_state ? "on" : "off") < 0) {
                fprintf(stderr, "Error logging event.\n");
            }

            // Wait for a short period to avoid multiple triggers from a single touch
            struct timespec delay = {0, 100000000}; // 100 milliseconds
            nanosleep(&delay, NULL);
        }

        // Poll for events with a timeout
        struct timespec timeout = {1, 0}; // 1 second timeout
        ret = gpiod_line_event_wait(touch_line, &timeout);
        if (ret < 0) {
            if (errno == ETIMEDOUT) {
                // Timeout occurred, continue the loop
                continue;
            } else {
                fprintf(stderr, "Error waiting for event: %s\n", strerror(errno));
                cleanup();
                return EXIT_FAILURE;
            }
        }
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Application terminated.\n");
    return EXIT_SUCCESS;
}

