#include <gpiod.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define buzzer duration
#define BUZZER_DURATION_MS 2000

// Global variables for GPIO resources
struct gpiod_chip *chip;
struct gpiod_line *flame_line;
struct gpiod_line *buzzer_line;
FILE *log_file;

// Function prototypes
int init_gpio(void);
int read_flame_sensor(void);
int activate_buzzer(void);
int log_event(const char *event);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Turn off the buzzer
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
    }

    // Release GPIO lines
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fprintf(log_file, "System stopped\n");
        fclose(log_file);
    }

    exit(0);
}

// Initialize GPIO lines
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        fprintf(stderr, "Error getting flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        gpiod_line_release(flame_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "Error requesting flame sensor line as input: %s\n", strerror(errno));
        gpiod_line_release(flame_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        gpiod_line_release(flame_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

