#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define LED_PIN 17
#define DEBOUNCE_DELAY_MS 200

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get current timestamp in ISO-8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for timestamp.\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the touch event to a file
int log_touch_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Warning: Failed to write to log file.\n");
        return -1;
    }
    fflush(log_file); // Ensure the data is written to the file immediately
    return 0;
}

// Function to toggle the LED state
int toggle_led() {
    int current_level = gpioRead(LED_PIN);
    if (current_level < 0) {
        fprintf(stderr, "Error reading LED pin: %d\n", current_level);
        return -1;
    }
    int new_level = (current_level == 0) ? 1 : 0;
    if (gpioWrite(LED_PIN, new_level) != 0) {
        fprintf(stderr, "Error writing to LED pin.\n");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set TOUCH_PIN to input mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set LED_PIN to output mode\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open touch_log.txt for appending\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_touch_state = gpioRead(TOUCH_PIN);
    if (last_touch_state < 0) {
        fprintf(stderr, "Error reading initial touch state.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        int current_touch_state = gpioRead(TOUCH_PIN);
        if (current_touch_state < 0) {
            fprintf(stderr, "Error reading touch state.\n");
            break;
        }

        // Detect rising edge (LOW to HIGH transition)
        if (last_touch_state == 0 && current_touch_state == 1) {
            // Get timestamp
            char *timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                // Log the event
                if (log_touch_event(timestamp) != 0) {
                    fprintf(stderr, "Error logging touch event.\n");
                }

                // Toggle the LED
                if (toggle_led() != 0) {
                    fprintf(stderr, "Error toggling LED.\n");
                }

                free(timestamp); // Free the allocated memory
            }

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
        }

        last_touch_state = current_touch_state;
        gpioDelay(10 * 1000); // Check every 10ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn off the LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

