#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the log file name
#define LOG_FILE "magnet_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    int sensor3_state;
} SensorStates;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int log_event(int sensor_id, int state);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_GPIO);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR1_GPIO);
        return -1;
    }

    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_GPIO);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR2_GPIO);
        return -1;
    }

    if (gpioSetMode(SENSOR3_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR3_GPIO);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR3_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR3_GPIO);
        return -1;
    }

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int state = gpioRead(gpio_pin);
    if (state < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1; // Indicate an error
    }
    return state;
}

// Function to log an event to the log file
int log_event(int sensor_id, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s Sensor %d: %s\n", timestamp, sensor_id, state ? "Removed" : "Present");
    fflush(log_file); // Ensure the log is written immediately

    return 0;
}

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    SensorStates initial_states;
    // Read initial states
    initial_states.sensor1_state = read_sensor(SENSOR1_GPIO);
    initial_states.sensor2_state = read_sensor(SENSOR2_GPIO);
    initial_states.sensor3_state = read_sensor(SENSOR3_GPIO);

    if (initial_states.sensor1_state == -1 || initial_states.sensor2_state == -1 || initial_states.sensor3_state == -1) {
        fprintf(stderr, "Failed to read initial sensor states. Exiting.\n");
        cleanup();
        return 1;
    }

    SensorStates previous_states = initial_states;

    // Main loop
    while (program_running) {
        SensorStates current_states;

        current_states.sensor1_state = read_sensor(SENSOR1_GPIO);
        current_states.sensor2_state = read_sensor(SENSOR2_GPIO);
        current_states.sensor3_state = read_sensor(SENSOR3_GPIO);

        if (current_states.sensor1_state == -1 || current_states.sensor2_state == -1 || current_states.sensor3_state == -1) {
            fprintf(stderr, "Error reading sensor data. Continuing...\n");
        } else {
            // Check for state changes
            if (current_states.sensor1_state != previous_states.sensor1_state) {
                log_event(1, current_states.sensor1_state);
            }
            if (current_states.sensor2_state != previous_states.sensor2_state) {
                log_event(2, current_states.sensor2_state);
            }
            if (current_states.sensor3_state != previous_states.sensor3_state) {
                log_event(3, current_states.sensor3_state);
            }

            previous_states = current_states;
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

