#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define LED_CURRENT_REG 0x3F
#define AVERAGING_REG 0x04
#define ENABLE_REG 0x01
#define HEART_RATE_REG 0x2A
#define PART_ID 0x02
#define HW_REV 0x01
#define LED_CURRENT 0x0A
#define AVERAGING 0x03
#define ENABLE_VAL 0x07
#define BPM_SCALE 0.5
#define BPM_MIN 30
#define BPM_MAX 220
#define MOVING_AVG_SIZE 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_heart_rate(int *raw_value);
float calculate_bpm(int raw_value);
float apply_moving_average(float new_value, float *moving_average, int *index);
int validate_bpm(float bpm);
void log_bpm(float bpm);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1182-A-GM sensor
int initialize_sensor() {
    int result;

    // Check PART_ID
    result = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", result);
        return -1;
    }
    if (result != PART_ID) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X (expected 0x%02X)\n", result, PART_ID);
        return -1;
    }

    // Check HW_REV
    result = i2cReadByteData(i2c_handle, HW_REV_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading HW_REV: %d\n", result);
        return -1;
    }
    if (result != HW_REV) {
        fprintf(stderr, "Incorrect HW_REV: 0x%02X (expected 0x%02X)\n", result, HW_REV);
        return -1;
    }

    // Configure LED current
    result = i2cWriteByteData(i2c_handle, LED_CURRENT_REG, LED_CURRENT);
    if (result < 0) {
        fprintf(stderr, "Error writing LED_CURRENT: %d\n", result);
        return -1;
    }

    // Configure averaging
    result = i2cWriteByteData(i2c_handle, AVERAGING_REG, AVERAGING);
    if (result < 0) {
        fprintf(stderr, "Error writing AVERAGING: %d\n", result);
        return -1;
    }

    // Enable sensor
    result = i2cWriteByteData(i2c_handle, ENABLE_REG, ENABLE_VAL);
    if (result < 0) {
        fprintf(stderr, "Error writing ENABLE: %d\n", result);
        return -1;
    }

    return 0;
}

// Read raw heart-rate data from the sensor
int read_heart_rate(int *raw_value) {
    int result;

    result = i2cReadWordData(i2c_handle, HEART_RATE_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading HEART_RATE: %d\n", result);
        return -1;
    }

    *raw_value = result;
    return 0;
}

// Calculate BPM from raw heart-rate data
float calculate_bpm(int raw_value) {
    return raw_value * BPM_SCALE;
}

// Apply a moving average filter
float apply_moving_average(float new_value, float *moving_average, int *index) {
    moving_average[*index] = new_value;
    *index = (*index + 1) % MOVING_AVG_SIZE;

    float sum = 0.0;
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        sum += moving_average[i];
    }

    return sum / MOVING_AVG_SIZE;
}

// Validate BPM value
int validate_bpm(float bpm) {
    return (bpm >= BPM_MIN && bpm <= BPM_MAX);
}

// Log BPM value to file
void log_bpm(float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file);
}

int main() {
    int raw_heart_rate;
    float bpm, filtered_bpm;
    float moving_average[MOVING_AVG_SIZE] = {0.0};
    int moving_average_index = 0;
    int retry_count;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        retry_count = 0;
        while (retry_count < 3) {
            if (read_heart_rate(&raw_heart_rate) == 0) {
                bpm = calculate_bpm(raw_heart_rate);
                filtered_bpm = apply_moving_average(bpm, moving_average, &moving_average_index);
                if (validate_bpm(filtered_bpm)) {
                    log_bpm(filtered_bpm);
                    printf("BPM: %.2f\n", filtered_bpm);
                } else {
                    fprintf(stderr, "Invalid BPM: %.2f\n", filtered_bpm);
                }
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "I2C read error, retrying... (%d/3)\n", retry_count + 1);
                retry_count++;
                gpioDelay(100); // Wait before retrying
            }
        }

        if (retry_count == 3) {
            fprintf(stderr, "Failed to read heart rate after multiple retries.\n");
        }

        gpioDelay(1000); // Read every 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

