#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define the GPIO chip and line
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17

// Define the log file name
#define LOG_FILE "flame_log.txt"

// Global variables for GPIO and file handling
struct gpiod_chip *chip = NULL;
struct gpiod_line *line = NULL;
FILE *log_file = NULL;

// Function prototypes
int read_flame_sensor(struct gpiod_line *line);
int log_flame_detection(const char *timestamp);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO line
    if (line) {
        gpiod_line_release(line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

// Function to read the flame sensor
int read_flame_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %d\n", value);
        return -1; // Indicate error
    }
    return value;
}

// Function to log flame detection
int log_flame_detection(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s FLAME DETECTED\n", timestamp);
    fflush(log_file);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    // Open GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_LINE);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line as input with pull-up
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_PULL_UP;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %d\n", ret);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    int last_value = gpiod_line_get_value(line);
    if (last_value < 0) {
        fprintf(stderr, "Error reading initial GPIO line value: %d\n", last_value);
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        int current_value = read_flame_sensor(line);
        if (current_value < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting...\n");
            break;
        }

        // Detect falling edge (HIGH to LOW transition)
        if (last_value == 1 && current_value == 0) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log flame detection
            if (log_flame_detection(timestamp) == 0) {
                printf("%s FLAME DETECTED\n", timestamp);
            } else {
                fprintf(stderr, "Error logging flame detection.\n");
            }
        }

        last_value = current_value;
        usleep(100000); // 100 ms
    }

    // Cleanup (should not reach here under normal circumstances due to signal handler)
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

