#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins for sensor inputs and output bits
#define SENSOR_BASE 5
#define OUTPUT_BASE 17
#define NUM_CHANNELS 8

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_lines[NUM_CHANNELS];
static struct gpiod_line *output_lines[NUM_CHANNELS];
static int counter = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int request_line(struct gpiod_chip *chip, int offset, struct gpiod_line **line);
int release_line(struct gpiod_line *line);
int set_direction(struct gpiod_line *line, const char *direction);
int get_value(struct gpiod_line *line);
int set_value(struct gpiod_line *line, int value);
int log_event(int channel, int counter);
void print_event(int channel, int counter);
void cleanup(int signal);

// Signal handler
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;

    // Reset output pins to 0
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (output_lines[i]) {
            set_value(output_lines[i], 0);
        }
    }

    // Release GPIO lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_lines[i]) {
            release_line(sensor_lines[i]);
        }
        if (output_lines[i]) {
            release_line(output_lines[i]);
        }
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Request a GPIO line
int request_line(struct gpiod_chip *chip, int offset, struct gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, offset);
    if (!*line) {
        fprintf(stderr, "Error: Could not get line %d: %s\n", offset, strerror(errno));
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "touch_counter";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(*line, &config, 0) < 0) {
        fprintf(stderr, "Error: Could not request line %d: %s\n", offset, strerror(errno));
        return -1;
    }

    return 0;
}

// Release a GPIO line
int release_line(struct gpiod_line *line) {
    if (!line) return 0; // Already released
    gpiod_line_release(line);
    return 0;
}

// Set the direction of a GPIO line (input or output)
int set_direction(struct gpiod_line *line, const char *direction) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "touch_counter";

    if (strcmp(direction, "input") == 0) {
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    } else if (strcmp(direction, "output") == 0) {
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    } else {
        fprintf(stderr, "Error: Invalid direction: %s\n", direction);
        return -1;
    }

    if (gpiod_line_request(line, &config, 0) < 0) {
