        for (int i = 0; i < NUM_CHANNELS; i++) {
            int current_value = get_value(sensor_lines[i]);
            if (current_value < 0) {
                fprintf(stderr, "Error reading sensor %d, skipping.\n", i + 1);
                continue;
            }

            if (current_value == 1 && previous_values[i] == 0) {
                // Rising edge detected
                counter = (counter + 1) % 256;
                log_event(i + 1, counter);
                print_event(i + 1, counter);

                // Update output lines
                for (int j = 0; j < NUM_CHANNELS; j++) {
