#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22

// Define the CSV file name
#define CSV_FILE "tracking_log.csv"

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *sensor1_line, *sensor2_line, *sensor3_line, *sensor4_line;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int write_to_csv(const char *timestamp, int sensor1, int sensor2, int sensor3, int sensor4);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    if (sensor1_line) gpiod_line_release(sensor1_line);
    if (sensor2_line) gpiod_line_release(sensor2_line);
    if (sensor3_line) gpiod_line_release(sensor3_line);
    if (sensor4_line) gpiod_line_release(sensor4_line);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    exit(0);
}

// Function to read the value of a sensor
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(-value));
        return -1; // Indicate an error
    }
    return value;
}

// Function to write data to the CSV file
int write_to_csv(const char *timestamp, int sensor1, int sensor2, int sensor3, int sensor4) {
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
    }

    // Write the data to the CSV file
    fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4);

    // Flush the buffer to ensure data is written to the file
    fflush(fp);

    // Close the file
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get the GPIO lines
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    sensor3_line = gpiod_chip_get_line(chip, SENSOR3_PIN);
    sensor4_line = gpiod_chip_get_line(chip, SENSOR4_PIN);

    if (!sensor1_line || !sensor2_line || !sensor3_line || !sensor4_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines as input
    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0 ||
        gpiod_line_request_input(sensor2_line, "sensor2") < 0 ||
        gpiod_line_request_input(sensor3_line, "sensor3") < 0 ||
        gpiod_line_request_input(sensor4_line, "sensor4") < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_value = read_sensor(sensor1_line);
        int sensor2_value = read_sensor(sensor2_line);
        int sensor3_value = read_sensor(sensor3_line);
        int sensor4_value = read_sensor(sensor4_line);

        if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0 || sensor4_value < 0) {
            // Error reading sensor, continue to the next iteration
            continue;
        }

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20]; // YYYY-MM-DD HH:MM:SS\0

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Write data to CSV file
        if (write_to_csv(timestamp, sensor1_value, sensor2_value, sensor3_value, sensor4_value) != 0) {
            fprintf(stderr, "Error writing to CSV file.\n");
        }

        // Wait for 100 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

