#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN 22

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "obstacle_log.csv"

// Global variables for GPIO lines and chip
struct gpiod_line *sensor1_line = NULL;
struct gpiod_line *sensor2_line = NULL;
struct gpiod_line *led_line = NULL;
struct gpiod_chip *chip = NULL;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int control_led(struct gpiod_line *line, int state);
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int led_state);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");

        // Turn off LED
        control_led(led_line, 0);

        // Release GPIO lines
        if (sensor1_line) {
            gpiod_line_release(sensor1_line);
        }
        if (sensor2_line) {
            gpiod_line_release(sensor2_line);
        }
        if (led_line) {
            gpiod_line_release(led_line);
        }

        // Close GPIO chip
        if (chip) {
            gpiod_chip_close(chip);
        }

        // Close log file
        if (log_file) {
            fclose(log_file);
        }

        exit(0);
    }
}

// Function to read sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to control LED state
int control_led(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return 0;
}

// Function to log data to file
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    int ret = fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, led_state);
    if (ret < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    fflush(fp); // Flush the buffer to ensure data is written to disk
    return 0;
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return 1;
    }

    // Get GPIO lines
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);

    if (!sensor1_line || !sensor2_line || !led_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        if (chip) gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for input and output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "sensor1";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(sensor1_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting sensor1 line: %s\n", strerror(errno));
        if (sensor1_line) gpiod_line_release(sensor1_line);
        if (sensor2_line) gpiod_line_release(sensor2_line);
        if (led_line) gpiod_line_release(led_line);
        if (chip) gpiod_chip_close(chip);
        return 1;
    }

    config.consumer = "sensor2";
    if (gpiod_line_request(sensor2_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting sensor2 line: %s\n", strerror(errno));
        if (sensor1_line) gpiod_line_release(sensor1_line);
        if (sensor2_line) gpiod_line_release(sensor2_line);
        if (led_line) gpiod_line_release(led_line);
        if (chip) gpiod_chip_close(chip);
        return 1;
    }

    config.consumer = "led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    if (gpiod_line_request(led_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting led line: %s\n", strerror(errno));
        if (sensor1_line) gpiod_line_release(sensor1_line);
        if (sensor2_line) gpiod_line_release(sensor2_line);
        if (led_line) gpiod_line_release(led_line);
        if (chip) gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        if (sensor1_line) gpiod_line_release(sensor1_line);
        if (sensor2_line) gpiod_line_release(sensor2_line);
        if (led_line) gpiod_line_release(led_line);
        if (chip) gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_value = read_sensor(sensor1_line);
        int sensor2_value = read_sensor(sensor2_line);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor values, exiting.\n");
            break; // Exit loop on error
        }

        int led_state = (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;
        control_led(led_line, led_state);

        if (log_data(log_file, sensor1_value, sensor2_value, led_state) < 0) {
            fprintf(stderr, "Error logging data, exiting.\n");
            break; // Exit loop on error
        }

        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup (in case of error)
    if (sensor1_line) gpiod_line_release(sensor1_line);
    if (sensor2_line) gpiod_line_release(sensor2_line);
    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);

    return 0;
}

