#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Sampling rate (approximately 8 kHz)
#define SAMPLE_PERIOD_US 125

// LED on time (100 ms)
#define LED_ON_TIME_MS 100

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, stopping...\n", signal);
}

// Function to get current timestamp in milliseconds
long long get_timestamp_ms() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)(ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL);
}

int main() {
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    result = gpioSetMode(MIC_PIN, PI_INPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set MIC_PIN mode: %d\n", result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set LED_PIN mode: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    fprintf(stdout, "Sampling microphone... Press Ctrl+C to stop.\n");

    // Main loop
    while (program_running) {
        // Read microphone input
        int mic_value = gpioRead(MIC_PIN);
        if (mic_value < 0) {
            fprintf(stderr, "Failed to read MIC_PIN: %d\n", mic_value);
            break; // Exit loop on error
        }

        // Check for HIGH reading (sound peak)
        if (mic_value == 1) {
            // Get timestamp
            long long timestamp = get_timestamp_ms();

            // Print timestamp to stdout
            printf("%lld\n", timestamp);

            // Turn LED ON
            result = gpioWrite(LED_PIN, 1);
            if (result != 0) {
                fprintf(stderr, "Failed to write to LED_PIN: %d\n", result);
                break; // Exit loop on error
            }

            // Wait for LED on time
            gpioDelay(LED_ON_TIME_MS * 1000); // Convert ms to us

            // Turn LED OFF
            result = gpioWrite(LED_PIN, 0);
            if (result != 0) {
                fprintf(stderr, "Failed to write to LED_PIN: %d\n", result);
                break; // Exit loop on error
            }
        }

        // Delay to achieve approximately 8 kHz sampling rate
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Clean shutdown
    fprintf(stderr, "Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Ensure LED is OFF
    gpioTerminate();       // Terminate pigpio

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

