#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the sensor values
int read_sensors(int *left, int *center, int *right) {
    *left = gpioRead(LEFT_SENSOR_PIN);
    *center = gpioRead(CENTER_SENSOR_PIN);
    *right = gpioRead(RIGHT_SENSOR_PIN);

    // Validate sensor readings
    if (*left != 0 && *left != 1) return -1; // Error: Invalid left sensor value
    if (*center != 0 && *center != 1) return -1; // Error: Invalid center sensor value
    if (*right != 0 && *right != 1) return -1; // Error: Invalid right sensor value

    return 0; // Success
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    int left_value, center_value, right_value;

    // Main loop to read and log sensor data
    while (program_running) {
        if (read_sensors(&left_value, &center_value, &right_value) == 0) {
            printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);
        } else {
            fprintf(stderr, "Error reading sensors\n");
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

