#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and device address
#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x49

// Define the register addresses for ALS visible data
#define ALS_VISIBLE_LSB 0x24
#define ALS_VISIBLE_MSB 0x25

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to set the I2C slave address
int set_slave_address(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    return 0;
}

// Function to read a single byte from an I2C register
int read_register(int fd, int reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// Function to combine two 8-bit values into a 16-bit value
unsigned int combine_bytes(unsigned char lsb, unsigned char msb) {
    return ((unsigned int)msb << 8) | lsb;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set the I2C slave address
    if (set_slave_address(i2c_fd, SI1175_ADDR) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and log the ALS visible data
    while (1) {
        // Read the ALS visible data registers
        int lsb = read_register(i2c_fd, ALS_VISIBLE_LSB);
        int msb = read_register(i2c_fd, ALS_VISIBLE_MSB);

        if (lsb >= 0 && msb >= 0) {
            // Combine the bytes into a 16-bit value
            unsigned int als_visible = combine_bytes((unsigned char)lsb, (unsigned char)msb);

            // Log the raw sensor value to the console
            printf("ALS Visible: %u\n", als_visible);
        } else {
            fprintf(stderr, "Error reading ALS visible data.\n");
        }

        // Wait for 100 milliseconds
        usleep(100000);
    }

    // The program should never reach here due to the infinite loop, but include cleanup for completeness
    close(i2c_fd);
    return 0;
}

