#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO_LEFT 2
#define GPIO_MIDDLE 3
#define GPIO_RIGHT 4

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *left_line = NULL;
struct gpiod_line *middle_line = NULL;
struct gpiod_line *right_line = NULL;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (middle_line) {
        gpiod_line_release(middle_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read sensor values
int read_sensor_values(int *left, int *middle, int *right)
{
    int left_val, middle_val, right_val;
    int ret;

    // Read left sensor
    ret = gpiod_line_get_value(left_line);
    if (ret < 0) {
        fprintf(stderr, "Error reading left sensor: %s\n", strerror(-ret));
        return -1;
    }
    left_val = ret;

    // Read middle sensor
    ret = gpiod_line_get_value(middle_line);
    if (ret < 0) {
        fprintf(stderr, "Error reading middle sensor: %s\n", strerror(-ret));
        return -1;
    }
    middle_val = ret;

    // Read right sensor
    ret = gpiod_line_get_value(right_line);
    if (ret < 0) {
        fprintf(stderr, "Error reading right sensor: %s\n", strerror(-ret));
        return -1;
    }
    right_val = ret;

    *left = left_val;
    *middle = middle_val;
    *right = right_val;

    return 0;
}

// Function to log sensor data with timestamp
void log_sensor_data(int left, int middle, int right)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s L:%d M:%d R:%d\n", timestamp, left, middle, right);
}

int main()
{
    int left_val, middle_val, right_val;
    int ret;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get GPIO lines
    left_line = gpiod_chip_get_line(chip, GPIO_LEFT);
    if (!left_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LEFT, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    middle_line = gpiod_chip_get_line(chip, GPIO_MIDDLE);
    if (!middle_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_MIDDLE, strerror(errno));
        gpiod_line_release(left_line);
        gpiod_chip_close(chip);
        return 1;
    }

    right_line = gpiod_chip_get_line(chip, GPIO_RIGHT);
    if (!right_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_RIGHT, strerror(errno));
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for input
    ret = gpiod_line_request_input(left_line, "sensor_left");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for input: %s\n", GPIO_LEFT, strerror(-ret));
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(middle_line, "sensor_middle");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for input: %s\n", GPIO_MIDDLE, strerror(-ret));
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(right_line, "sensor_right");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for input: %s\n", GPIO_RIGHT, strerror(-ret));
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor values
        if (read_sensor_values(&left_val, &middle_val, &right_val) == 0) {
            // Log sensor data
            log_sensor_data(left_val, middle_val, right_val);
        } else {
            fprintf(stderr, "Error reading sensor values.\n");
        }

        // Wait for 100 milliseconds
        struct timespec req = {0};
        req.tv_sec = 0;
        req.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&req, NULL);
    }

    return 0;
}

