    struct gpiod_line *line2;
    struct gpiod_line *line3;
    struct gpiod_line *line4;
    struct gpiod_line *line5;
    struct gpiod_line *line6;
    struct gpiod_line *line7;
    struct gpiod_line *line8;
};

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpio_lines lines;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(struct gpiod_chip **chip, struct gpio_lines *lines);
int read_sensor_data(struct gpio_lines *lines, int *data);
void log_data(int *data);
void cleanup(struct gpiod_chip *chip, struct gpio_lines *lines);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize GPIO lines
int init_gpio(struct gpiod_chip **chip, struct gpio_lines *lines) {
    *chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!*chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    lines->line1 = gpiod_chip_get_line(*chip, TP1);
    lines->line2 = gpiod_chip_get_line(*chip, TP2);
    lines->line3 = gpiod_chip_get_line(*chip, TP3);
    lines->line4 = gpiod_chip_get_line(*chip, TP4);
    lines->line5 = gpiod_chip_get_line(*chip, TP5);
    lines->line6 = gpiod_chip_get_line(*chip, TP6);
    lines->line7 = gpiod_chip_get_line(*chip, TP7);
    lines->line8 = gpiod_chip_get_line(*chip, TP8);

    if (!lines->line1 || !lines->line2 || !lines->line3 || !lines->line4 ||
        !lines->line5 || !lines->line6 || !lines->line7 || !lines->line8) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        cleanup(*chip, lines);
        return -1;
    }

    if (gpiod_line_request_input(lines->line1, "touch_sensor") < 0 ||
        gpiod_line_request_input(lines->line2, "touch_sensor") < 0 ||
        gpiod_line_request_input(lines->line3, "touch_sensor") < 0 ||
        gpiod_line_request_input(lines->line4, "touch_sensor") < 0 ||
        gpiod_line_request_input(lines->line5, "touch_sensor") < 0 ||
        gpiod_line_request_input(lines->line6, "touch_sensor") < 0 ||
        gpiod_line_request_input(lines->line7, "touch_sensor") < 0 ||
        gpiod_line_request_input(lines->line8, "touch_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(errno));
        cleanup(*chip, lines);
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(struct gpio_lines *lines, int *data) {
    data[0] = gpiod_line_get_value(lines->line1);
    data[1] = gpiod_line_get_value(lines->line2);
    data[2] = gpiod_line_get_value(lines->line3);
    data[3] = gpiod_line_get_value(lines->line4);
    data[4] = gpiod_line_get_value(lines->line5);
    data[5] = gpiod_line_get_value(lines->line6);
    data[6] = gpiod_line_get_value(lines->line7);
    data[7] = gpiod_line_get_value(lines->line8);

    return 0;
}

// Log sensor data
void log_data(int *data) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    printf("[%ld.%09lds] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
           ts.tv_sec, ts.tv_nsec, data[0], data[1], data[2], data[3], data[4], data[5], data[6], data[7]);
}

// Cleanup GPIO resources
void cleanup(struct gpiod_chip *chip, struct gpio_lines *lines) {
    if (lines->line1) gpiod_line_release(lines->line1);
    if (lines->line2) gpiod_line_release(lines->line2);
    if (lines->line3) gpiod_line_release(lines->line3);
    if (lines->line4) gpiod_line_release(lines->line4);
    if (lines->line5) gpiod_line_release(lines->line5);
    if (lines->line6) gpiod_line_release(lines->line6);
    if (lines->line7) gpiod_line_release(lines->line7);
    if (lines->line8) gpiod_line_release(lines->line8);
    if (chip) gpiod_chip_close(chip);
}

int main() {
    int sensor_data[8];

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio(&chip, &lines) < 0) {
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&lines, sensor_data) < 0) {
            fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
            break;
        }

        // Log sensor data
        log_data(sensor_data);

        // Wait 200 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 200 * 1000 * 1000; // 200 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup GPIO resources
    cleanup(chip, &lines);

    return EXIT_SUCCESS;
}

