#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define I2C address for BH1750 light sensor
#define BH1750_ADDR 0x23

// Define UDP server address and port
#define UDP_SERVER_IP   "127.0.0.1" // Loopback for simulation
#define UDP_SERVER_PORT 5000

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_fd;

// Function prototypes
void signal_handler(int signal);
int read_bh1750();
void set_rgb_color(int red, int green, int blue);
void interpolate_color(int start_red, int start_green, int start_blue, int end_red, int end_green, int end_blue, int steps);
void send_udp_message(int hue, int saturation, int brightness);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

// Function to read light level from BH1750 sensor
int read_bh1750() {
    unsigned char buf[2];
    int lux = -1; // Default to error value

    // Send start measurement command (High Resolution Mode)
    buf[0] = 0x10; // Continuous H-resolution mode
    if (write(i2c_fd, buf, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C device");
        return -1;
    }

    // Wait for measurement (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    if (read(i2c_fd, buf, 2) == 2) {
        lux = (buf[0] << 8) | buf[1];
    } else {
        syslog(LOG_ERR, "Failed to read from I2C device");
        return -1;
    }

    return lux;
}

// Function to set RGB color using pigpio
void set_rgb_color(int red, int green, int blue) {
    // Common anode, so invert PWM duty cycle
    int red_pwm   = 255 - red;
    int green_pwm = 255 - green;
    int blue_pwm  = 255 - blue;

    // Clamp values to [0, 255]
    if (red_pwm < 0)   red_pwm = 0;   if (red_pwm > 255)   red_pwm = 255;
    if (green_pwm < 0) green_pwm = 0; if (green_pwm > 255) green_pwm = 255;
    if (blue_pwm < 0)  blue_pwm = 0;  if (blue_pwm > 255)  blue_pwm = 255;

    int result;

    result = gpioPWM(RED_PIN,   red_pwm);
    if (result != 0) {
        syslog(LOG_ERR, "gpioPWM(RED_PIN, %d) failed with code %d", red_pwm, result);
    }

    result = gpioPWM(GREEN_PIN, green_pwm);
    if (result != 0) {
        syslog(LOG_ERR, "gpioPWM(GREEN_PIN, %d) failed with code %d", green_pwm, result);
    }

    result = gpioPWM(BLUE_PIN,  blue_pwm);
    if (result != 0) {
        syslog(LOG_ERR, "gpioPWM(BLUE_PIN, %d) failed with code %d", blue_pwm, result);
    }
}

// Function to interpolate between two colors
void interpolate_color(int start_red, int start_green, int start_blue, int end_red, int end_green, int end_blue, int steps) {
    float red_diff   = (float)(end_red   - start_red)   / steps;
    float green_diff = (float)(end_green - start_green) / steps;
    float blue_diff  = (float)(end_blue  - start_blue)  / steps;

    float current_red   = start_red;
    float current_green = start_green;
    float current_blue  = start_blue;

    for (int i = 0; i < steps; i++) {
        current_red   += red_diff;
        current_green += green_diff;
        current_blue  += blue_diff;

        int red   = (int)current_red;
        int green = (int)current_green;
        int blue  = (int)current_blue;

        set_rgb_color(red, green, blue);
        usleep(50000); // 50ms delay
    }
}

// Function to send UDP message
void send_udp_message(int hue, int saturation, int brightness) {
    int sockfd;
    struct sockaddr_in servaddr;
    char message[256];

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        syslog(LOG_ERR, "Socket creation failed");
        return;
    }

    memset(&servaddr, 0, sizeof(servaddr));

    // Fill server information
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        close(sockfd);
        return;
    }

    // Format message
    snprintf(message, sizeof(message), "Hue: %d, Saturation: %d, Brightness: %d", hue, saturation, brightness);

    // Send message
    if (sendto(sockfd, (const char *)message, strlen(message), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Send failed");
    }

    close(sockfd);
}

