#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// TCS34725 Registers
#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// GPIO Pin
#define GPIO_PIN 17

// I2C Device
#define I2C_DEVICE "/dev/i2c-1"

// Global Variables
static int i2c_fd = -1;
static struct gpiod_line *gpio_line = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration Parameters
static float red_offset = 0.0;
static float green_offset = 0.0;
static float blue_offset = 0.0;
static float red_gain = 1.0;
static float green_gain = 1.0;
static float blue_gain = 1.0;

// Function Prototypes
int init_i2c(void);
int init_gpio(void);
int init_sensor(void);
int read_sensor_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void calibrate_sensor(void);
void display_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void control_led(uint16_t red);
void cleanup(int signal);

// Helper function to write to I2C
int i2c_write(uint8_t reg, uint8_t value)
{
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Helper function to read from I2C
int i2c_read(uint8_t reg, uint8_t *value)
{
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c(void)
{
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize GPIO
int init_gpio(void)
{
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "led_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
        return -1;
    }

    return 0;
}

// Initialize TCS34725 Sensor
int init_sensor(void)
{
    uint8_t id;

    // Check sensor ID
    if (i2c_read(TCS34725_COMMAND_BIT | TCS34725_ID, &id) < 0) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }

    if (id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        return -1;
    }

    // Enable power and RGBC
    if (i2c_write(TCS34725_COMMAND_BIT | TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to enable register\n");
        return -1;
    }

    // Set integration time (ATIME = 154ms)
    if (i2c_write(TCS34725_COMMAND_BIT | TCS34725_ATIME, 0x00) < 0) {
        fprintf(stderr, "Error writing to ATIME register\n");
        return -1;
    }

    // Set gain (CONTROL = 1x)
    if (i2c_write(TCS34725_COMMAND_BIT | TCS34725_CONTROL, 0x00) < 0) {
        fprintf(stderr, "Error writing to CONTROL register\n");
        return -1;
    }

    return 0;
}

// Read Sensor Data
int read_sensor_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue)
{
    uint8_t buf[8];

    // Read all four channels in one go
    if (write(i2c_fd, &(uint8_t){TCS34725_COMMAND_BIT | TCS34725_CDATA}, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(i2c_fd, buf, 8) != 8) {
        perror("I2C read failed");
        return -1;
    }

    *clear = buf[1] << 8 | buf[0];
    *red = buf[3] << 8 | buf[2];
    *green = buf[5] << 8 | buf[4];
    *blue = buf[7] << 8 | buf[6];

    return 0;
}

// Calibrate Sensor (Placeholder)
void calibrate_sensor(void)
{
    // Implement calibration logic here
    // This is a placeholder, replace with actual calibration
    printf("Calibration not implemented, using default values.\n");
}

// Display Data
void display_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue)
{
    float calibrated_red = (red - red_offset) * red_gain;
    float calibrated_green = (green - green_offset) * green_gain;
    float calibrated_blue = (blue - blue_offset) * blue_gain;

    printf("C: %5u, R: %5.0f, G: %5.0f, B: %5.0f\n", clear, calibrated_red, calibrated_green, calibrated_blue);
}

// Control LED
void control_led(uint16_t red)
{
    if (red > 200) {
        gpiod_line_set_value(gpio_line, 1); // HIGH
    } else {
        gpiod_line_set_value(gpio_line, 0); // LOW
    }
}

// Cleanup Resources
void cleanup(int signal)
{
    printf("Cleaning up...\n");
    terminate = 1;

    // Power down sensor
    if (i2c_fd != -1) {
        i2c_write(TCS34725_COMMAND_BIT | TCS34725_ENABLE, 0x00); // Disable
        close(i2c_fd);
        i2c_fd = -1;
    }

    // Release GPIO
    if (gpio_line != NULL) {
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }

    exit(0);
}

int main(void)
{
    // Register signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup(0);
        return 1;
    }

    // Initialize Sensor
    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup(0);
        return 1;
    }

    // Calibrate Sensor
    calibrate_sensor();

    uint16_t clear, red, green, blue;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 200000000; // 200 ms

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&clear, &red, &green, &blue) == 0) {
            // Display data
            display_data(clear, red, green, blue);

            // Control LED
            control_led(red);
        } else {
            fprintf(stderr, "Error reading sensor data, re-initializing...\n");
            // Attempt sensor re-initialization
            if (init_sensor() < 0) {
                fprintf(stderr, "Sensor re-initialization failed\n");
                cleanup(0);
                return 1;
            }
        }

        // Sleep for 200 ms
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

