        return -1;
    }

    if (id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        return -1;
    }

    // Enable power and RGBC
    if (i2c_write(TCS34725_COMMAND_BIT | TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to enable register\n");
        return -1;
    }

