#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Constants
#define WS2812B_GPIO 18
#define BH1750_ADDR 0x23
#define NUM_LEDS 10
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int sig);
int init_i2c();
int read_bh1750(int fd);
double map_lux_to_brightness(int lux);
void set_led_brightness(double brightness);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize I2C
int init_i2c() {
    int fd = wiringPiI2CSetup(BH1750_ADDR);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C. Check your wiring and I2C configuration.\n");
        return -1;
    }
    return fd;
}

// Read BH1750 sensor
int read_bh1750(int fd) {
    int lux = -1;
    int retry = 0;

    while (retry < I2C_RETRY_COUNT) {
        if (wiringPiI2CWrite(fd, 0x10) == -1) {
            fprintf(stderr, "Error writing to BH1750 (attempt %d): %s\n", retry + 1, strerror(errno));
            retry++;
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(180 * 1000); // Wait for measurement (180ms)

        int msb = wiringPiI2CReadReg8(fd, 0x00);
        int lsb = wiringPiI2CReadReg8(fd, 0x01);

        if (msb == -1 || lsb == -1) {
            fprintf(stderr, "Error reading from BH1750 (attempt %d): %s\n", retry + 1, strerror(errno));
            retry++;
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        lux = (msb << 8 | lsb) / 1.2;
        break; // Success, exit retry loop
    }

    if (lux == -1) {
        fprintf(stderr, "Failed to read BH1750 after %d retries.\n", I2C_RETRY_COUNT);
    }

    return lux;
}

// Map lux to brightness (logarithmic mapping)
double map_lux_to_brightness(int lux) {
    if (lux <= 0) return 0.0;
    if (lux >= 1000) return 1.0;

    // Logarithmic mapping
    double brightness = log10((double)lux / 1000.0 + 1.0) / log10(10.0);

    // Clamp brightness to 0.0 - 1.0
    if (brightness < 0.0) brightness = 0.0;
    if (brightness > 1.0) brightness = 1.0;

    return brightness;
}

// Set LED strip brightness
void set_led_brightness(double brightness) {
    // Create a simple waveform for the WS2812B
    int num_samples = 2048; // Adjust for desired brightness resolution
    int *wave_data = malloc(num_samples * sizeof(int));
    if (wave_data == NULL) {
        fprintf(stderr, "Error allocating memory for waveform data.\n");
        return;
    }

    for (int i = 0; i < num_samples; i++) {
        // Generate a sine wave with a duty cycle based on brightness
        double duty_cycle = brightness; // Use brightness directly for simple brightness control
        double phase = (double)i / num_samples * 2.0 * M_PI;
        double amplitude = 0.5 * duty_cycle; // Adjust amplitude as needed
        double offset = 0.5; // Adjust offset as needed

        double value = offset + amplitude * sin(phase);

        // Scale the value to the range 0-255 (adjust as needed for your LED strip)
        int color_value = (int)(value * 255.0);

        // Combine RGB values (assuming monochrome)
        int rgb = (color_value << 16) | (color_value << 8) | color_value;

        wave_data[i] = rgb;
    }

    gpioWaveClear();
    gpioWaveAddGeneric(num_samples, wave_data);

    int wave_id = gpioWaveCreate();
    if (wave_id >= 0) {
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_REPEAT); // Send the waveform in a loop
    } else {
        fprintf(stderr, "Error creating waveform: %d\n", wave_id);
    }

    free(wave_data);
}

// Cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    gpioWaveTxStop();
    gpioWaveClear();
    gpioTerminate();
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    fprintf(stderr, "Cleanup complete.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c();
    if (i2c_fd == -1) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read light level
        int lux = read_bh1750(i2c_fd);
        if (lux != -1) {
            // Map lux to brightness
            double brightness = map_lux_to_brightness(lux);

            // Set LED strip brightness
            set_led_brightness(brightness);

            printf("Lux: %d, Brightness: %.2f\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read light level.\n");
        }

        gpioDelay(100 * 1000); // Delay 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

