    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    // Configure BH1750 for One-Time High-Resolution Mode
    uint8_t config_cmd = 0x20; // High-Resolution Mode
    if (write(fd, &config_cmd, 1) != 1) {
        perror("Error writing to I2C device");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI initialization function
int init_spi(const char *device, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode (CPHA=0, CPOL=0)
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// BH1750 read lux function
int bh1750_read_lux(int fd) {
    uint8_t buffer[2];
    int ret;

    // Wait for conversion (at least 120ms)
    usleep(120000); // 120 ms

    ret = read(fd, buffer, 2);
    if (ret != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    uint16_t raw_value = (buffer[0] << 8) | buffer[1];
    float lux = (float)raw_value / 1.2;

    return (int)lux;
}

// Map lux to APA102 brightness (5-bit)
int map_lux_to_brightness(float lux) {
    if (lux < 10.0) {
        return 0;
    } else if (lux > 300.0) {
        return 31;
    } else {
        // Linear mapping
        return (int)(((lux - 10.0) / (300.0 - 10.0)) * 31.0);
    }
}

// APA102 frame generation function
int apa102_generate_frame(uint8_t brightness, uint8_t *frame, size_t frame_size) {
    if (frame == NULL || frame_size < APA102_FRAME_SIZE) {
        fprintf(stderr, "Error: Invalid frame buffer or size\n");
        return -1;
    }

    // Start frame (4 bytes of 0x00)
    memset(frame, 0x00, APA102_START_FRAME_SIZE);

    // LED frame (0xE0 | brightness, blue, green, red)
    frame[APA102_START_FRAME_SIZE] = 0xE0 | brightness; // Global brightness
    frame[APA102_START_FRAME_SIZE + 1] = 0x00; // Blue
    frame[APA102_START_FRAME_SIZE + 2] = 0x00; // Green
    frame[APA102_START_FRAME_SIZE + 3] = 0x00; // Red

    // End frame (4 bytes of 0xFF)
    memset(frame + APA102_START_FRAME_SIZE + 1, 0xFF, APA102_END_FRAME_SIZE);

    return 0;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    if (tx_buf == NULL || rx_buf == NULL || len == 0) {
        fprintf(stderr, "Error: Invalid SPI buffer or length\n");
        return -1;
    }

    // No need to use struct spi_ioc_transfer here, just use write and read
    if (write(fd, tx_buf, len) != len) {
        perror("Error writing to SPI device");
        return -1;
    }

    if (read(fd, rx_buf, len) != len) {
        perror("Error reading from SPI device");
        return -1;
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_DEVICE, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    uint8_t frame[APA102_FRAME_SIZE];
    int lux;
    int brightness;

    while (!terminate) {
        // Read lux value
        lux = bh1750_read_lux(i2c_fd);
        if (lux < 0) {
            fprintf(stderr, "Failed to read lux value. Continuing.\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Map lux to brightness
        brightness = map_lux_to_brightness((float)lux);

        // Generate APA102 frame
        if (apa102_generate_frame((uint8_t)brightness, frame, sizeof(frame)) != 0) {
            fprintf(stderr, "Failed to generate APA102 frame. Continuing.\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Send frame via SPI
        if (spi_transfer(spi_fd, frame, frame, sizeof(frame)) != 0) {
            fprintf(stderr, "Failed to send SPI frame. Continuing.\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Delay
        usleep(100000); // 100ms
    }

    // Turn off LEDs (set brightness to 0)
    memset(frame, 0x00, sizeof(frame));
    apa102_generate_frame(0, frame, sizeof(frame));
    spi_transfer(spi_fd, frame, frame, sizeof(frame));

    // Close file descriptors
    close(i2c_fd);
    close(spi_fd);

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

