#define VEML7700_ADDR 0x10
#define CONFIG_REG 0x00
#define ALS_REG 0x04
#define GPIO_PIN 18
#define NUM_LEDS 1
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define LUX_TO_BRIGHTNESS_SCALE 0.0288f
#define LUX_MAX 120000.0f
#define GAMMA 2.2f

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(void);
int init_veml7700(void);
int read_veml7700_data(uint16_t *raw_data);
float convert_to_lux(uint16_t raw_data);
int init_gpio(void);
int set_gpio_output(int value);
int cleanup(void);
void signal_handler(int sig);
int map_lux_to_brightness(float lux);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// I2C initialization function
int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// VEML7700 initialization function
int init_veml7700(void) {
    uint8_t config_data[2] = {0x00, 0x00}; // Integration time 100 ms, gain 1/8
    uint8_t write_buf[3];

    write_buf[0] = CONFIG_REG;
    memcpy(write_buf + 1, config_data, 2);

    if (write(i2c_fd, write_buf, 3) != 3) {
        fprintf(stderr, "Error writing to VEML7700 configuration register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// VEML7700 data reading function with retry
int read_veml7700_data(uint16_t *raw_data) {
    uint8_t read_buf[1];
    uint8_t write_buf[1];
    int retries = RETRY_COUNT;

    write_buf[0] = ALS_REG;

    while (retries > 0) {
        if (write(i2c_fd, write_buf, 1) != 1) {
            fprintf(stderr, "Error writing to VEML7700 ALS register: %s\n", strerror(errno));
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 100ms
            retries--;
            continue;
        }

        if (read(i2c_fd, read_buf, 2) != 2) {
            fprintf(stderr, "Error reading from VEML7700 ALS register: %s\n", strerror(errno));
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 100ms
            retries--;
            continue;
        }

        *raw_data = (read_buf[1] << 8) | read_buf[0];
        return 0; // Success
    }

    fprintf(stderr, "Failed to read VEML7700 data after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

