#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *flame_sensor_line;
struct gpiod_line *buzzer_line;
struct gpiod_line *led_line;

// Function prototypes
int gpio_init(void);
int self_test(void);
void activate_alarm(void);
void deactivate_alarm(void);
void log_event(const char *message);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        log_event("Received SIGINT, exiting...");
        deactivate_alarm();
        if (flame_sensor_line) gpiod_line_release(flame_sensor_line);
        if (buzzer_line) gpiod_line_release(buzzer_line);
        if (led_line) gpiod_line_release(led_line);
        if (chip) gpiod_chip_close(chip);
        exit(0);
    }
}

// Initialize GPIO lines
int gpio_init(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO lines
    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);

    if (!flame_sensor_line || !buzzer_line || !led_line) {
        perror("Error getting GPIO line");
        if (flame_sensor_line) gpiod_line_release(flame_sensor_line);
        if (buzzer_line) gpiod_line_release(buzzer_line);
        if (led_line) gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(buzzer_line, "flame_sensor", 0);
    if (ret < 0) {
        perror("Error requesting buzzer line for output");
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(led_line, "flame_sensor", 0);
    if (ret < 0) {
        perror("Error requesting LED line for output");
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO line for input
    ret = gpiod_line_request_input(flame_sensor_line, "flame_sensor");
    if (ret < 0) {
        perror("Error requesting flame sensor line for input");
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Self-test function
int self_test(void) {
    int i;
    int flame_detected_count = 0;

    // Blink LED twice
    for (i = 0; i < 2; i++) {
        gpiod_line_set_value(led_line, 1);
        usleep(500000); // 500 ms
        gpiod_line_set_value(led_line, 0);
        usleep(500000); // 500 ms
    }

    // Read flame sensor 5 times
    for (i = 0; i < 5; i++) {
        int value = gpiod_line_get_value(flame_sensor_line);
        if (value < 0) {
