            return -1;
        }
        if (value == 0) {
            flame_detected_count++;
        }
        usleep(100000); // 100 ms
    }

    // Check if flame is consistently detected
    if (flame_detected_count == 5) {
        log_event("Self-test failed: Flame consistently detected.");
        // Rapid LED blinking
        for (i = 0; i < 5; i++) {
            gpiod_line_set_value(led_line, 1);
            usleep(100000); // 100 ms
            gpiod_line_set_value(led_line, 0);
            usleep(100000); // 100 ms
        }

        // Buzzer pattern
        gpiod_line_set_value(buzzer_line, 1);
        usleep(200000); // 200 ms
        gpiod_line_set_value(buzzer_line, 0);
        usleep(200000); // 200 ms
        gpiod_line_set_value(buzzer_line, 1);
        usleep(600000); // 600 ms
        gpiod_line_set_value(buzzer_line, 0);
        usleep(200000); // 200 ms

        for (i = 0; i < 2; i++) {
            gpiod_line_set_value(buzzer_line, 1);
            usleep(200000); // 200 ms
            gpiod_line_set_value(buzzer_line, 0);
            usleep(200000); // 200 ms
        }

        return -1;
    } else {
        log_event("Self-test passed.");
        return 0;
    }
}

// Activate alarm (buzzer and LED)
void activate_alarm(void) {
    gpiod_line_set_value(buzzer_line, 1);
    gpiod_line_set_value(led_line, 1);
    log_event("Alarm activated.");
}

// Deactivate alarm (buzzer and LED)
void deactivate_alarm(void) {
    gpiod_line_set_value(buzzer_line, 0);
    gpiod_line_set_value(led_line, 0);
    log_event("Alarm deactivated.");
}

// Log event with timestamp
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

int main(void) {
    int flame_detected = 0;
    int i;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Run self-test
    if (self_test() < 0) {
        log_event("Self-test failed. Exiting.");
        deactivate_alarm();
        if (flame_sensor_line) gpiod_line_release(flame_sensor_line);
        if (buzzer_line) gpiod_line_release(buzzer_line);
        if (led_line) gpiod_line_release(led_line);
        if (chip) gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int value = gpiod_line_get_value(flame_sensor_line);
        if (value < 0) {
            perror("Error reading flame sensor value");
            log_event("Error reading flame sensor value.");
            usleep(50000); // Small delay before retrying
            continue;
        }

        if (value == 0 && !flame_detected) {
            // Flame detected
            activate_alarm();
            flame_detected = 1;
            log_event("Flame detected!");
        } else if (value == 1 && flame_detected) {
            // Flame gone
            deactivate_alarm();
            flame_detected = 0;
            log_event("Flame gone.");
        }

        usleep(50000); // 50 ms delay
    }

    return 0;
}

