#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio/gpio17"
#define GPIO_EXPORT_PATH "/sys/class/gpio/export"
#define GPIO_UNEXPORT_PATH "/sys/class/gpio/unexport"
#define GPIO_DIRECTION_PATH GPIO_PATH "/direction"
#define GPIO_VALUE_PATH GPIO_PATH "/value"
#define BUFFER_SIZE 60
#define LUX_THRESHOLD 500.0

// Global variables
static int i2c_fd = -1;
static int gpio_fd = -1;
static volatile sig_atomic_t keep_running = 1;

// Circular buffer
static float lux_buffer[BUFFER_SIZE];
static int buffer_index = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int read_bh1750(float *lux);
int write_gpio(int value);
float calculate_average_lux();
float map_lux_to_frequency(float average_lux);
int set_gpio_frequency(float frequency);
void signal_handler(int sig);
void cleanup();

// Helper function to write to a file
int write_to_file(const char *path, const char *value)
{
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open file for writing");
        return -1;
    }
    if (write(fd, value, strlen(value)) < 0) {
        perror("Failed to write to file");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Helper function to read from a file
int read_from_file(const char *path, char *buffer, size_t buffer_size)
{
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open file for reading");
        return -1;
    }
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read < 0) {
        perror("Failed to read from file");
        close(fd);
        return -1;
    }
    buffer[bytes_read] = '\0';
    close(fd);
    return 0;
}

// Initialize I2C
int init_i2c()
{
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Set continuous high-resolution mode
    uint8_t config_cmd = 0x10; // Continuous H-resolution mode
    if (write(i2c_fd, &config_cmd, 1) != 1) {
        perror("Failed to write config command to I2C");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize GPIO
int init_gpio()
{
    // Export GPIO
    if (write_to_file(GPIO_EXPORT_PATH, "17") != 0) {
        fprintf(stderr, "GPIO already exported or failed to export. Continuing.\n");
    }
    usleep(100000); // Wait for the sysfs entry to be created

    // Set GPIO direction to output
    if (write_to_file(GPIO_DIRECTION_PATH, "out") != 0) {
        perror("Failed to set GPIO direction");
        return -1;
    }

    return 0;
}

// Read light sensor value
int read_bh1750(float *lux)
{
    uint8_t buffer[2];
    int16_t raw_value;

    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Failed to read from I2C");
        return -1;
    }

    raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Write to GPIO
int write_gpio(int value)
{
    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);
    if (write_to_file(GPIO_VALUE_PATH, val_str) != 0) {
        perror("Failed to write to GPIO");
        return -1;
    }
    return 0;
}

// Calculate average lux
float calculate_average_lux()
{
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += lux_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Map lux to frequency
float map_lux_to_frequency(float average_lux)
{
    float frequency = 0.5 + (average_lux / 1000.0) * 4.5;
    if (frequency < 0.5) {
        frequency = 0.5;
    } else if (frequency > 5.0) {
        frequency = 5.0;
    }
    return frequency;
}

// Set GPIO frequency (blink rate)
int set_gpio_frequency(float frequency)
{
    // Calculate on/off times in microseconds
    long period_us = (long)(1000000.0 / frequency);
    long on_time_us = period_us / 2;
    long off_time_us = period_us / 2;

    // Blink the LED
    if (write_gpio(1) != 0) return -1;
    usleep(on_time_us);
    if (write_gpio(0) != 0) return -1;
    usleep(off_time_us);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("Caught signal, exiting...\n");
}

// Cleanup resources
void cleanup()
{
    printf("Cleaning up...\n");

    // Unexport GPIO
    write_to_file(GPIO_UNEXPORT_PATH, "17");

    // Close I2C file descriptor
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

int main()
{
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    for (int i = 0; i < BUFFER_SIZE; i++) {
        lux_buffer[i] = 0.0;
    }

    float lux;
    float average_lux;
    float frequency;

    // Main loop
    while (keep_running) {
        // Read light sensor value
        if (read_bh1750(&lux) == 0) {
            // Update circular buffer
            lux_buffer[buffer_index] = lux;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Calculate average lux
            average_lux = calculate_average_lux();

            // Map lux to frequency
            frequency = map_lux_to_frequency(average_lux);

            // Set GPIO frequency
            if (set_gpio_frequency(frequency) != 0) {
                fprintf(stderr, "Failed to set GPIO frequency.\n");
            }

            printf("Lux: %.2f, Average Lux: %.2f, Frequency: %.2f Hz\n", lux, average_lux, frequency);

            // Tamper detection
            if (lux > LUX_THRESHOLD) {
                printf("Tamper detected! Lux value exceeds threshold.\n");
            }
        } else {
            fprintf(stderr, "Failed to read light sensor value.\n");
        }

        sleep(1);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

