#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define segment patterns for digit 5
const unsigned char segment_patterns[] = {0x06, 0x0E, 0x0E, 0x06, 0x00}; // Digit 5 patterns

// Global variables for GPIO lines and chip
struct gpiod_line *data_line, *clock_line, *latch_line;
struct gpiod_chip *chip;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (chip) {
        if (data_line) gpiod_line_release(data_line);
        if (clock_line) gpiod_line_release(clock_line);
        if (latch_line) gpiod_line_release(latch_line);
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to shift out data to the 74HC595
void shift_out(unsigned char data)
{
    for (int i = 0; i < 8; i++)
    {
        // Set data pin
        gpiod_line_set_value(data_line, (data >> (7 - i)) & 1);

        // Clock high
        gpiod_line_set_value(clock_line, 1);
        usleep(100); // Short delay

        // Clock low
        gpiod_line_set_value(clock_line, 0);
        usleep(100); // Short delay
    }
}

// Function to display a digit on the seven-segment display
void display_digit(int digit)
{
    shift_out(segment_patterns[digit]);

    // Latch data
    gpiod_line_set_value(latch_line, 1);
    usleep(100); // Short delay
    gpiod_line_set_value(latch_line, 0);
    usleep(100); // Short delay
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip)
    {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);

    if (!data_line || !clock_line || !latch_line)
    {
        perror("Error getting GPIO line");
        if (chip) gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as outputs
    if (gpiod_line_request_output(data_line, "main", 0) < 0 ||
        gpiod_line_request_output(clock_line, "main", 0) < 0 ||
        gpiod_line_request_output(latch_line, "main", 0) < 0)
    {
        perror("Error requesting GPIO line as output");
        if (chip) gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1)
    {
        // Display digit 5
        display_digit(0);
        usleep(500000); // 500 ms

        // Turn off display
        shift_out(0x00);
        gpiod_line_set_value(latch_line, 1);
        usleep(100);
        gpiod_line_set_value(latch_line, 0);
        usleep(100);
        usleep(500000); // 500 ms
    }

    // Cleanup (should not reach here in normal execution due to the infinite loop)
    gpiod_line_release(data_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(latch_line);
    gpiod_chip_close(chip);

    return 0;
}

