#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Global variables for GPIO chip and line handles
int chip_handle;
int led_line_handle;
int button_line_handle;

// Function prototypes
int initialize_gpio();
void blink_led();
void handle_button_press();
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold GPIO line handles
typedef struct {
    int led_line;
    int button_line;
} gpio_lines_t;

gpio_lines_t lines;

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        blink_led();
        handle_button_press();
    }

    return 0;
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially turn LED off

    // Set button pin as input with pull-up resistor
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    return 0;
}

// Blink the LED
void blink_led() {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(1000000);    // Wait for 1 second
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioDelay(1000000);    // Wait for 1 second
}

// Handle button press
void handle_button_press() {
    // Read button state
    int button_state = gpioRead(BUTTON_PIN);

    // Check for falling edge (button press)
    if (button_state == 0) {
        printf("Button pressed!\n");
        gpioWrite(LED_PIN, 0); // Turn off LED
        gpioDelay(1000000);    // Wait for 1 second
        cleanup_gpio();
        exit(0);
    }
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();       // Terminate pigpio
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting gracefully.\n");
    cleanup_gpio();
    exit(0);
}

