#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define LED_PIN 24
#define BUTTON_PIN 22

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *led_line = NULL;
struct gpiod_line *button_line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    fprintf(stderr, "Cleanup complete. Exiting.\n");
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio()
{
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get button line
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Error getting button line %d: %s\n", BUTTON_PIN, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request LED line for output
    ret = gpiod_line_request_output(led_line, "led_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting LED line for output: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request button line for input with pull-down
    ret = gpiod_line_request_input(button_line, "button_input");
    if (ret < 0) {
        fprintf(stderr, "Error requesting button line for input: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to control the LED
void control_led(int state)
{
    int ret = gpiod_line_set_value(led_line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
    }
}

// Function to read the button state
int read_button()
{
    int value = gpiod_line_get_value(button_line);
    if (value < 0) {
        fprintf(stderr, "Error reading button value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    fprintf(stderr, "GPIO initialized successfully. Running...\n");

    // Main loop
    while (1) {
        int button_state = read_button();
        if (button_state < 0) {
            // Error reading button, exit loop
            break;
        }

        if (button_state == 0) { // Button is pressed (active low)
            control_led(1); // Turn LED on
            usleep(500000);  // 500 ms
            control_led(0); // Turn LED off
            usleep(500000);  // 500 ms
        } else {
            control_led(0); // Ensure LED is off when button is released
        }

        usleep(10000); // Small delay to prevent busy-waiting
    }

    // Cleanup (in case of error)
    signal_handler(SIGTERM);

    return 0;
}

