#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins
#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18

// Define PWM parameters
#define PWM_PERIOD_NS 10000000 // 10 ms
#define PWM_DUTY_CYCLE_MIN 0
#define PWM_DUTY_CYCLE_MAX 100

// Global variables for GPIO lines and chip
struct gpiod_line *red_line = NULL;
struct gpiod_line *green_line = NULL;
struct gpiod_line *blue_line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set the PWM duty cycle for a given GPIO line
int set_pwm_duty_cycle(struct gpiod_line *line, int duty_cycle) {
    if (duty_cycle < PWM_DUTY_CYCLE_MIN || duty_cycle > PWM_DUTY_CYCLE_MAX) {
        fprintf(stderr, "Error: Duty cycle out of range (0-100)\n");
        return -1;
    }

    // Calculate the number of nanoseconds to keep the line high
    long high_time_ns = (long)((double)duty_cycle / PWM_DUTY_CYCLE_MAX * PWM_PERIOD_NS);

    // Keep the line high for the calculated time
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting GPIO value (high)");
        return -1;
    }
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = high_time_ns;
    nanosleep(&ts, NULL);

    // Then set the line low for the remaining time
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO value (low)");
        return -1;
    }
    ts.tv_sec = 0;
    ts.tv_nsec = PWM_PERIOD_NS - high_time_ns;
    nanosleep(&ts, NULL);

    return 0;
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Open GPIO chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        perror("Error getting GPIO line");
        if (red_line) gpiod_line_release(red_line);
        if (green_line) gpiod_line_release(green_line);
        if (blue_line) gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as outputs
    if (gpiod_line_request_output(red_line, "rgb_led", 0) < 0) {
        perror("Error requesting red GPIO line");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(green_line, "rgb_led", 0) < 0) {
        perror("Error requesting green GPIO line");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(blue_line, "rgb_led", 0) < 0) {
        perror("Error requesting blue GPIO line");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Generate random RGB values
        int red_duty_cycle = rand() % (PWM_DUTY_CYCLE_MAX + 1);
        int green_duty_cycle = rand() % (PWM_DUTY_CYCLE_MAX + 1);
        int blue_duty_cycle = rand() % (PWM_DUTY_CYCLE_MAX + 1);

        // Set PWM duty cycles
        if (set_pwm_duty_cycle(red_line, red_duty_cycle) < 0) {
            fprintf(stderr, "Error setting red PWM duty cycle\n");
        }
        if (set_pwm_duty_cycle(green_line, green_duty_cycle) < 0) {
            fprintf(stderr, "Error setting green PWM duty cycle\n");
        }
        if (set_pwm_duty_cycle(blue_line, blue_duty_cycle) < 0) {
            fprintf(stderr, "Error setting blue PWM duty cycle\n");
        }

        // Print RGB values to console
        printf("R: %d, G: %d, B: %d\n", red_duty_cycle, green_duty_cycle, blue_duty_cycle);

        // Wait for 100 ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000; // 100 ms
        nanosleep(&ts, NULL);
    }

    return 0;
}

