#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x39
#define MODE_REGISTER 0x0D
#define ALS_LSB_REGISTER 0x64
#define ALS_MSB_REGISTER 0x65
#define RED_REGISTER 0x66
#define GREEN_REGISTER 0x68
#define BLUE_REGISTER 0x6A
#define LED_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_als_data(uint16_t *als_value);
int read_color_data(uint16_t *red_value, uint16_t *green_value, uint16_t *blue_value);
void log_data(uint16_t als_value, uint16_t red_value, uint16_t green_value, uint16_t blue_value);
void set_led_brightness(uint16_t als_value);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the ADPD188BI sensor
int initialize_sensor() {
    int result = i2cWriteByteData(i2c_handle, MODE_REGISTER, 0x01);
    if (result != 0) {
        fprintf(stderr, "Error writing to MODE register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read ALS data from the sensor
int read_als_data(uint16_t *als_value) {
    int lsb = i2cReadByteData(i2c_handle, ALS_LSB_REGISTER);
    int msb = i2cReadByteData(i2c_handle, ALS_MSB_REGISTER);

    if (lsb < 0 || msb < 0) {
        fprintf(stderr, "Error reading ALS data: %d, %d\n", lsb, msb);
        return -1;
    }

    *als_value = (uint16_t)((msb << 8) | lsb);
    return 0;
}

// Read color data from the sensor
int read_color_data(uint16_t *red_value, uint16_t *green_value, uint16_t *blue_value) {
    int red_lsb = i2cReadByteData(i2c_handle, RED_REGISTER);
    int red_msb = i2cReadByteData(i2c_handle, RED_REGISTER + 1);
    int green_lsb = i2cReadByteData(i2c_handle, GREEN_REGISTER);
    int green_msb = i2cReadByteData(i2c_handle, GREEN_REGISTER + 1);
    int blue_lsb = i2cReadByteData(i2c_handle, BLUE_REGISTER);
    int blue_msb = i2cReadByteData(i2c_handle, BLUE_REGISTER + 1);

    if (red_lsb < 0 || red_msb < 0 || green_lsb < 0 || green_msb < 0 || blue_lsb < 0 || blue_msb < 0) {
        fprintf(stderr, "Error reading color data: %d, %d, %d, %d, %d, %d\n", red_lsb, red_msb, green_lsb, green_msb, blue_lsb, blue_msb);
        return -1;
    }

    *red_value = (uint16_t)((red_msb << 8) | red_lsb);
    *green_value = (uint16_t)((green_msb << 8) | green_lsb);
    *blue_value = (uint16_t)((blue_msb << 8) | blue_lsb);

    return 0;
}

// Log data to a CSV file
void log_data(uint16_t als_value, uint16_t red_value, uint16_t green_value, uint16_t blue_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als_value, red_value, green_value, blue_value);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Set LED brightness using PWM
void set_led_brightness(uint16_t als_value) {
    // Map ALS value (0-65535) to PWM duty cycle (0-255)
    int duty_cycle = (int)(((float)als_value / 65535.0) * 255.0);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;

    gpioPWM(LED_GPIO, duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_GPIO, 255);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t als_value, red_value, green_value, blue_value;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_als_data(&als_value) == 0 && read_color_data(&red_value, &green_value, &blue_value) == 0) {
            // Log the data
            log_data(als_value, red_value, green_value, blue_value);

            // Set LED brightness
            set_led_brightness(als_value);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    gpioPWM(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

