    int16_t x, y, z;

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", i2c_handle);
        return -1;
    }

    // Combine MSB and LSB, shift right by 2 bits, and convert to m/s^2
    x = (int16_t)((raw_data[0] << 8 | raw_data[1]) >> 2);
    y = (int16_t)((raw_data[2] << 8 | raw_data[3]) >> 2);
    z = (int16_t)((raw_data[4] << 8 | raw_data[5]) >> 2);

    data->x = (float)x * 9.81 / SENSITIVITY;
    data->y = (float)y * 9.81 / SENSITIVITY;
    data->z = (float)z * 9.81 / SENSITIVITY;

    return 0;
}

