    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, data->x, data->y, data->z, data->magnitude);
    fflush(log_file); // Ensure data is written to disk immediately

    printf("Impact logged: %s, x=%.3f, y=%.3f, z=%.3f, magnitude=%.3f\n", timestamp, data->x, data->y, data->z, data->magnitude);
