        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Starting impact detection...\n");

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&accel_data) == 0) {
            // Calculate magnitude
            accel_data.magnitude = calculate_magnitude(&accel_data);

            // Check for impact
            if (accel_data.magnitude > IMPACT_THRESHOLD) {
                log_impact(&accel_data);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        gpioDelay(50); // Sample every 50 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

