#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define gyroscope registers
#define CTRL_REG1   0x20
#define CTRL_REG4   0x23
#define OUT_X_L     0x28
#define WHO_AM_I    0x0F

// Define gyroscope sensitivity (0.00875 dps/LSB)
#define SENSITIVITY 0.00875

// Define I2C bus and address
#define I2C_BUS     "/dev/i2c-1"
#define I2C_ADDRESS 0x69

// Define calibration samples
#define CALIBRATION_SAMPLES 100

// Define logging interval (20 Hz)
#define LOGGING_INTERVAL_MS 50

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Structure to hold calibration data
typedef struct {
    double x_offset;
    double y_offset;
    double z_offset;
} calibration_data_t;

// Function prototypes
int i2c_setup(const char *bus, int address);
int gyro_init(int fd);
gyro_data_t read_gyro_data(int fd);
calibration_data_t calibrate_gyro(int fd, int samples);
void log_data(FILE *fp, gyro_data_t data, calibration_data_t calibration);
void check_thresholds(gyro_data_t data, calibration_data_t calibration);
void signal_handler(int sig);
void cleanup(int fd, FILE *fp);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// I2C setup function
int i2c_setup(const char *bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Gyroscope initialization function
int gyro_init(int fd) {
    uint8_t who_am_i;

    // Check WHO_AM_I register
    if (read(fd, &who_am_i, 1) != 1) {
        perror("Error reading WHO_AM_I register");
        return -1;
    }

    if (who_am_i != 0xD3) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0xD3\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, all axes enabled, 100 Hz ODR)
    uint8_t ctrl_reg1_value = 0x0F;
    uint8_t ctrl_reg1[2] = {CTRL_REG1, ctrl_reg1_value};
    if (write(fd, ctrl_reg1, 2) != 2) {
        perror("Error writing to CTRL_REG1");
        return -1;
    }

    // Configure CTRL_REG4 (250 dps full-scale, continuous update)
    uint8_t ctrl_reg4_value = 0x00;
    uint8_t ctrl_reg4[2] = {CTRL_REG4, ctrl_reg4_value};
    if (write(fd, ctrl_reg4, 2) != 2) {
        perror("Error writing to CTRL_REG4");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
gyro_data_t read_gyro_data(int fd) {
    gyro_data_t data;
    uint8_t buffer[6];

    // Set the register address to read from (OUT_X_L)
    uint8_t reg = OUT_X_L;
    if (write(fd, &reg, 1) != 1) {
        perror("Error setting register address for read");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    // Read 6 bytes of data (X, Y, Z axes)
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading gyroscope data");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    // Combine high and low bytes for each axis
    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Function to calibrate the gyroscope
calibration_data_t calibrate_gyro(int fd, int samples) {
    calibration_data_t calibration;
    double x_sum = 0, y_sum = 0, z_sum = 0;
    gyro_data_t data;

    printf("Calibrating gyroscope...\n");

    for (int i = 0; i < samples; i++) {
        data = read_gyro_data(fd);
        x_sum += data.x;
        y_sum += data.y;
        z_sum += data.z;
        usleep(10000); // 10 ms delay
    }

    calibration.x_offset = x_sum / samples;
    calibration.y_offset = y_sum / samples;
    calibration.z_offset = z_sum / samples;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", calibration.x_offset, calibration.y_offset, calibration.z_offset);

    return calibration;
}

// Function to log data to file
void log_data(FILE *fp, gyro_data_t data, calibration_data_t calibration) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(fp, "%s, %.2f, %.2f, %.2f\n", timestamp,
            (data.x - calibration.x_offset) * SENSITIVITY,
            (data.y - calibration.y_offset) * SENSITIVITY,
            (data.z - calibration.z_offset) * SENSITIVITY);
    fflush(fp); // Ensure data is written to disk immediately
}

// Function to check for thresholds
void check_thresholds(gyro_data_t data, calibration_data_t calibration) {
    if (abs((data.x - calibration.x_offset) * SENSITIVITY) > 50.0 ||
        abs((data.y - calibration.y_offset) * SENSITIVITY) > 50.0 ||
        abs((data.z - calibration.z_offset) * SENSITIVITY) > 50.0) {
        fprintf(stderr, "Warning: Gyroscope reading exceeds threshold!\n");
    }
}

// Cleanup function
void cleanup(int fd, FILE *fp) {
    if (fd != -1) {
        close(fd);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    printf("Cleaned up and exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize gyroscope
    if (gyro_init(i2c_fd) < 0) {
        cleanup(i2c_fd, NULL);
        return 1;
    }

    // Calibrate gyroscope
    calibration_data_t calibration = calibrate_gyro(i2c_fd, CALIBRATION_SAMPLES);

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup(i2c_fd, NULL);
        return 1;
    }

    // Main loop
    gyro_data_t data;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = LOGGING_INTERVAL_MS * 1000000; // 50 ms

    printf("Starting data logging...\n");

    while (!terminate) {
        data = read_gyro_data(i2c_fd);
        log_data(log_file, data, calibration);
        check_thresholds(data, calibration);
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup(i2c_fd, log_file);
    return 0;
}

