#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

// Sensor addresses
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E

// Accelerometer registers
#define CTRL_REG1_A 0x20
#define OUT_X_L_A 0x28

// Magnetometer registers
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03

// I2C bus
#define I2C_BUS 1

// Global variables for I2C handles
int accel_handle = -1;
int mag_handle = -1;

// Function prototypes
int init_accelerometer(int handle);
int init_magnetometer(int handle);
int read_accelerometer(int handle, float *x, float *y, float *z);
int read_magnetometer(int handle, float *x, float *y, float *z);
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
void log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (accel_handle >= 0) {
        i2cClose(accel_handle);
    }
    if (mag_handle >= 0) {
        i2cClose(mag_handle);
    }
    gpioTerminate();
    exit(0);
}

// Initialize accelerometer
int init_accelerometer(int handle) {
    if (i2cWriteByteData(handle, CTRL_REG1_A, 0x27) != 0) {
        fprintf(stderr, "Error writing to accelerometer CTRL_REG1_A\n");
        return -1;
    }
    return 0;
}

// Initialize magnetometer
int init_magnetometer(int handle) {
    if (i2cWriteByteData(handle, MR_REG_M, 0x00) != 0) {
        fprintf(stderr, "Error writing to magnetometer MR_REG_M\n");
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accelerometer(int handle, float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, OUT_X_L_A | 0x80, buf, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    // Combine high and low bytes, convert to g
    *x = (float)((int16_t)(buf[1] << 8 | buf[0])) / 16384.0f;
    *y = (float)((int16_t)(buf[3] << 8 | buf[2])) / 16384.0f;
    *z = (float)((int16_t)(buf[5] << 8 | buf[4])) / 16384.0f;

    return 0;
}

// Read magnetometer data
int read_magnetometer(int handle, float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, OUT_X_H_M, buf, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    // Combine high and low bytes, convert to gauss
    *x = (float)((int16_t)(buf[0] << 8 | buf[1])) / 1100.0f;
    *y = (float)((int16_t)(buf[2] << 8 | buf[3])) / 1100.0f;
    *z = (float)((int16_t)(buf[4] << 8 | buf[5])) / 1100.0f;

    return 0;
}

// Calculate heading using tilt compensation
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    float roll = atan2(accel_y, accel_z);
    float pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z));

    float mag_x_comp = mag_x * cos(pitch) + mag_z * sin(pitch);
    float mag_y_comp = mag_x * sin(roll) * sin(pitch) + mag_y * cos(roll) - mag_z * sin(roll) * cos(pitch);

    float heading = atan2(mag_y_comp, mag_x_comp) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Log data to file
void log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    FILE *fp = fopen("compass_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    // Write data to file
    fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", timestamp, heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);

    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles
    accel_handle = i2cOpen(I2C_BUS, ACCEL_ADDR, 0);
    if (accel_handle < 0) {
        fprintf(stderr, "Error opening accelerometer I2C device\n");
        gpioTerminate();
        return 1;
    }

    mag_handle = i2cOpen(I2C_BUS, MAG_ADDR, 0);
    if (mag_handle < 0) {
        fprintf(stderr, "Error opening magnetometer I2C device\n");
        i2cClose(accel_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    if (init_accelerometer(accel_handle) != 0) {
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }

    if (init_magnetometer(mag_handle) != 0) {
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float accel_x, accel_y, accel_z;
    float mag_x, mag_y, mag_z;
    float heading;

