                fprintf(stderr, "Error: Could not open I2C bus after re-initialization. Error code: %d\n", i2c_handle);
                program_running = 0; // Exit loop if re-initialization fails
            } else {
                if (vl6180x_init() < 0) {
                    fprintf(stderr, "Error: VL6180X initialization failed after re-initialization.\n");
                    program_running = 0; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(100000); // 100ms delay
    }

    // Clean up
    printf("Cleaning up resources...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

