#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REG 0x01
#define CTRL_REG 0x00
#define CTRL_VAL 0x80
#define SAMPLE_INTERVAL_US 10000 // 10 ms
#define LOG_FILE "audio_log.dat"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, int16_t *data);
int compute_tdoa(int16_t sensor1_sample, int16_t sensor2_sample);
int log_data(FILE *fp, struct timespec ts, int16_t sensor1_sample, int16_t sensor2_sample, int tdoa);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initializes the sensor by writing to the control register
int initialize_sensor(int i2c_handle) {
    int result = i2cWriteByteData(i2c_handle, CTRL_REG, CTRL_VAL);
    if (result != 0) {
        fprintf(stderr, "Error initializing sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Reads 16-bit data from the sensor
int read_sensor_data(int i2c_handle, int16_t *data) {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, DATA_REG, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *data = (int16_t)((buffer[0] << 8) | buffer[1]);
    return 0;
}

// Computes the TDOA based on the two sensor samples
int compute_tdoa(int16_t sensor1_sample, int16_t sensor2_sample) {
    return sensor1_sample - sensor2_sample;
}

// Logs the data to the CSV file
int log_data(FILE *fp, struct timespec ts, int16_t sensor1_sample, int16_t sensor2_sample, int tdoa) {
    fprintf(fp, "%ld,%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, sensor1_sample, sensor2_sample, tdoa);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Initialize both sensors
    if (initialize_sensor(i2c_handle1) != 0) {
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }
    if (initialize_sensor(i2c_handle2) != 0) {
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Write the CSV header
    fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    struct timespec ts;
    int16_t sensor1_sample, sensor2_sample, tdoa;

    while (1) {
        // Read data from both sensors
        if (read_sensor_data(i2c_handle1, &sensor1_sample) != 0) {
            fprintf(stderr, "Error reading sensor 1 data, skipping sample\n");
            continue; // Skip to the next iteration
        }
        if (read_sensor_data(i2c_handle2, &sensor2_sample) != 0) {
            fprintf(stderr, "Error reading sensor 2 data, skipping sample\n");
            continue; // Skip to the next iteration
        }

        // Compute TDOA
        tdoa = compute_tdoa(sensor1_sample, sensor2_sample);

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            continue; // Skip to the next iteration
        }

        // Log the data
        log_data(log_file, ts, sensor1_sample, sensor2_sample, tdoa);

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_US);
    }

