void log_data(float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z);
void cleanup(int signum);

// Function to read data from an ADIS16488A register
int read_register(int reg_addr, int *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct the transmit buffer (read command)
    tx_buf[0] = (reg_addr << 1) & 0xFE; // Set MSB to 0 for read
    tx_buf[1] = 0x00; // Dummy byte

    // Perform the SPI transfer
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result < 0) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the received bytes to form the 16-bit data
    *data = (rx_buf[0] << 8) | rx_buf[1];

    return 0; // Indicate success
}

// Function to write data to an ADIS16488A register
int write_register(int reg_addr, int data) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct the transmit buffer (write command)
    tx_buf[0] = (reg_addr << 1) | 0x01; // Set MSB to 1 for write
    tx_buf[1] = data & 0xFF; //LSB

    // Perform the SPI transfer
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result < 0) {
