#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// ADIS16448 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// SPI Configuration
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_MODE SPI_MODE_3
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000 // 1 MHz

// GPIO Configuration
#define CS_GPIO 8

// Global Variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(void);
int spi_transfer(uint8_t tx_buf[2], uint8_t rx_buf[2]);
int read_register(uint8_t reg_addr, int16_t *data);
void process_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int16_t accel_x, int16_t accel_y, int16_t accel_z, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps, float *accel_x_g, float *accel_y_g, float *accel_z_g);
void log_data(float gyro_x_dps, float gyro_y_dps, float gyro_z_dps, float accel_x_g, float accel_y_g, float accel_z_g);
void signal_handler(int sig);
int gpio_init(void);
void gpio_deinit(void);

// SPI Initialization
int spi_init(void) {
    char spi_dev[20];
    snprintf(spi_dev, sizeof(spi_dev), "/dev/spidev%d.%d", SPI_BUS, SPI_DEVICE);

    spi_fd = open(spi_dev, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set max speed Hz
    uint32_t speed = SPI_MAX_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed Hz");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Transfer Function
int spi_transfer(uint8_t tx_buf[2], uint8_t rx_buf[2]) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 2,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read Register Function
int read_register(uint8_t reg_addr, int16_t *data) {
    uint8_t tx_buf[2], rx_buf[2];

    // Set the read bit in the register address
    tx_buf[0] = reg_addr | 0x80;
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (gpio_line_set_value(cs_line, 0) < 0) {
        perror("Error setting CS low");
        return -1;
    }

    if (spi_transfer(tx_buf, rx_buf) < 0) {
        gpio_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpio_line_set_value(cs_line, 1) < 0) {
        perror("Error setting CS high");
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
