#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Scaling factors
#define GYRO_SCALE 0.05
#define ACCL_SCALE 0.00025

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float gyro_x, gyro_y, gyro_z;
    float accl_x, accl_y, accl_z;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to read data from ADIS16448 register
int read_register(int handle, uint8_t reg, uint16_t *data) {
    char tx[2], rx[2];
    tx[0] = (reg << 1) | 0x80; // Set MSB for read operation
    tx[1] = 0x00; // Dummy byte

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    gpioDelay(40); // Stall time

    tx[0] = 0x00; // Dummy byte
    tx[1] = 0x00; // Dummy byte

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X (data read)\n", reg);
        return -1;
    }

    *data = (rx[0] << 8) | rx[1];
    return 0;
}

// Function to read IMU data
int read_imu_data(int handle, sensor_data_t *data) {
    uint16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    uint16_t raw_accl_x, raw_accl_y, raw_accl_z;

    if (read_register(handle, X_GYRO_OUT, &raw_gyro_x) != 0) return -1;
    if (read_register(handle, Y_GYRO_OUT, &raw_gyro_y) != 0) return -1;
    if (read_register(handle, Z_GYRO_OUT, &raw_gyro_z) != 0) return -1;
    if (read_register(handle, X_ACCL_OUT, &raw_accl_x) != 0) return -1;
    if (read_register(handle, Y_ACCL_OUT, &raw_accl_y) != 0) return -1;
    if (read_register(handle, Z_ACCL_OUT, &raw_accl_z) != 0) return -1;

    data->gyro_x = (float)((int16_t)raw_gyro_x) * GYRO_SCALE;
    data->gyro_y = (float)((int16_t)raw_gyro_y) * GYRO_SCALE;
    data->gyro_z = (float)((int16_t)raw_gyro_z) * GYRO_SCALE;
    data->accl_x = (float)((int16_t)raw_accl_x) * ACCL_SCALE;
    data->accl_y = (float)((int16_t)raw_accl_y) * ACCL_SCALE;
    data->accl_z = (float)((int16_t)raw_accl_z) * ACCL_SCALE;

    return 0;
}

