    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_imu_data(spi_handle, &sensor_data) == 0) {
            printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s  Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
                   sensor_data.gyro_x, sensor_data.gyro_y, sensor_data.gyro_z,
