#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define LED_GPIO 17
#define IMPACT_THRESHOLD 2.5f // g
#define LED_ON_TIME 500       // ms
#define SAMPLE_RATE_MS 10
#define SCALE_FACTOR 256.0f

// ADXL345 Registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37
#define ADXL345_DEVID 0x00

// Global Variables
static int i2c_handle;
static FILE *log_file;
static volatile int running = 1;

// Function Prototypes
int init_adxl345();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_impact(float magnitude, int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Structure for grouping sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
    float magnitude;
} SensorData;

// Function to initialize the ADXL345 sensor
int init_adxl345() {
    // Verify device ID
    char buf[1];
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DEVID, buf, 1) != 1) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }
    if (buf[0] != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", buf[0]);
        return -1;
    }

    // Set full resolution mode and measure bit
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL345
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, buf, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Function to calculate the magnitude of the acceleration vector
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / SCALE_FACTOR;
    float y_g = (float)y / SCALE_FACTOR;
    float z_g = (float)z / SCALE_FACTOR;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Function to log impact data to a file
void log_impact(float magnitude, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Magnitude: %.2f g, X: %d, Y: %d, Z: %d\n", timestamp, magnitude, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345 sensor
    if (init_adxl345() != 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (running) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);

                // Turn on LED
                gpioWrite(LED_GPIO, 1);
                gpioDelay(LED_ON_TIME * 1000); // Delay in microseconds
                gpioWrite(LED_GPIO, 0);

                // Log impact data
                log_impact(magnitude, x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data in main loop\n");
        }

        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay for sample rate
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

