#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VALUE 0x1A
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define LED_GPIO 17
#define THRESHOLD 2.0 // g
#define LED_ON_TIME_MS 500
#define SAMPLE_RATE_MS 100

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int init_gpio(int gpio_pin);
int init_mma8451q(int i2c_fd);
int read_acceleration(int i2c_fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
int check_threshold(double magnitude, double threshold);
int control_led(struct gpiod_line *led_line, int on);
int log_impact(FILE *log_file);
void signal_handler(int sig);
void cleanup();

// I2C initialization function
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// GPIO initialization function
int init_gpio(int gpio_pin) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }
    led_line = gpiod_chip_get_line(gpio_chip, gpio_pin);
    if (!led_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }
    if (gpiod_line_request_output(led_line, "mma8451q_led", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }
    return 0;
}

// MMA8451Q initialization function
int init_mma8451q(int i2c_fd) {
    uint8_t who_am_i;
    // Verify WHO_AM_I register
    if (read(i2c_fd, &who_am_i, 1) != 1) {
        perror("Error reading WHO_AM_I register");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: WHO_AM_I value mismatch. Expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 for active mode and 800 Hz ODR
    uint8_t ctrl_reg1_value = 0x39; // Active mode, 800 Hz ODR
    uint8_t ctrl_reg1_reg = CTRL_REG1;
    if (write(i2c_fd, &ctrl_reg1_reg, 1) != 1) {
        perror("Error writing to CTRL_REG1 register");
        return -1;
    }
    if (write(i2c_fd, &ctrl_reg1_value, 1) != 1) {
        perror("Error writing CTRL_REG1 value");
        return -1;
    }

    return 0;
}

// Function to read acceleration data
int read_acceleration(int i2c_fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading acceleration data");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 4;
    *y = (int16_t)((buffer[2] << 8) | buffer[3]) >> 4;
    *z = (int16_t)((buffer[4] << 8) | buffer[5]) >> 4;

    return 0;
}

// Function to calculate the magnitude of acceleration
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 2048.0; // Assuming +-2g range
    double y_g = (double)y / 2048.0;
    double z_g = (double)z / 2048.0;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Function to check if the magnitude exceeds the threshold
int check_threshold(double magnitude, double threshold) {
    return (magnitude > threshold) ? 1 : 0;
}

// Function to control the LED
int control_led(struct gpiod_line *led_line, int on) {
    if (gpiod_line_set_value(led_line, on) < 0) {
        perror("Error setting LED value");
        return -1;
    }
    return 0;
}

// Function to log impact events
int log_impact(FILE *log_file) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s Impact detected\n", timestamp) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (led_line) {
        gpiod_line_set_value(led_line, 0); // Turn off LED
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, MMA8451Q_ADDR);
    if (i2c_fd < 0) {
        cleanup();
        return 1;
    }

    // Initialize MMA8451Q
    if (init_mma8451q(i2c_fd) < 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(LED_GPIO) < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    int16_t x, y, z;
    double magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check threshold
            if (check_threshold(magnitude, THRESHOLD)) {
                // Trigger LED
                if (control_led(led_line, 1) == 0) {
                    // Log impact
                    log_impact(log_file);

                    // Wait for LED on time
                    usleep(LED_ON_TIME_MS * 1000); // Convert ms to us

                    // Turn off LED
                    control_led(led_line, 0);
                }
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        // Wait for the next sample
        usleep(SAMPLE_RATE_MS * 1000); // Convert ms to us
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

