    }

    // Map it to INT1 via INT_MAP (0x2F = 0x00)
    if (adxl345_write_register(fd, ADXL345_REG_INT_MAP, 0x00) < 0) {
        fprintf(stderr, "Error writing INT_MAP\n");
        return -1;
    }

    // Enter measurement mode by setting POWER_CTL (0x2D) to 0x08
    if (adxl345_write_register(fd, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing POWER_CTL\n");
        return -1;
    }

    return 0;
}

// Read acceleration data
int adxl345_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    // Read 6 bytes from DATAX0 (0x32) in a single I2C block read
    if (write(fd, (uint8_t[]){ADXL345_REG_DATAX0}, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }
    if (read(fd, data, 6) != 6) {
        perror("Failed to read acceleration data from I2C device");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Read INT_SOURCE register
int adxl345_read_int_source(int fd) {
    uint8_t int_source;

    if (adxl345_read_register(fd, ADXL345_REG_INT_SOURCE, &int_source) < 0) {
        fprintf(stderr, "Error reading INT_SOURCE\n");
        return -1;
    }

    return int_source;
}

// Initialize GPIO
int gpio_init(void) {
    int ret;

    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_rising_edge_events(gpio_line, "freefall_detector");
    if (ret < 0) {
        perror("Failed to request GPIO line for rising edge events");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Wait for GPIO interrupt
int gpio_interrupt_wait(void) {
    struct gpiod_line_event event;
    int ret;

    ret = gpiod_line_event_wait(gpio_line, NULL);
    if (ret < 0) {
        perror("Failed to wait for GPIO event");
        return -1;
    }

    ret = gpiod_line_event_read(gpio_line, &event);
    if (ret < 0) {
        perror("Failed to read GPIO event");
        return -1;
    }

    return 0;
}

// Log data to CSV file
int log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    char milliseconds[5];
    snprintf(milliseconds, sizeof(milliseconds), ".%03ld", ts.tv_nsec / 1000000);
    strcat(timestamp, milliseconds);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file);

    return 0;
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup(void) {
    // Disable interrupts
    if (i2c_fd != -1) {
        adxl345_write_register(i2c_fd, ADXL345_REG_INT_ENABLE, 0x00); // Disable all interrupts
    }

    // Close I2C device
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Release GPIO line
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main(void) {
    int ret;
    int16_t x, y, z;
    int int_source;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, 0x53) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("freefall_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    fflush(log_file);

    // Main loop
    while (!terminate) {
        // Wait for GPIO interrupt
        if (gpio_interrupt_wait() < 0) {
            fprintf(stderr, "GPIO interrupt wait failed\n");
            break;
        }

        // Read INT_SOURCE register
        int_source = adxl345_read_int_source(i2c_fd);
        if (int_source < 0) {
            fprintf(stderr, "Failed to read INT_SOURCE\n");
            break;
        }

        // Check if freefall bit is set
        if (int_source & 0x04) {
            // Read acceleration data
            if (adxl345_read_acceleration(i2c_fd, &x, &y, &z) < 0) {
                fprintf(stderr, "Failed to read acceleration data\n");
                break;
            }

            // Log data
            if (log_data(x, y, z) < 0) {
                fprintf(stderr, "Failed to log data\n");
                break;
            }
        }
    }

    // Cleanup resources
    cleanup();

    return EXIT_SUCCESS;
}

