#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28
#define WHO_AM_I 0x0F

// Scaling factors
#define ACCEL_SCALE 0.061  // mg/LSB for +-2g range
#define GYRO_SCALE 8.75   // mdps/LSB for +-250 dps range

// Fall detection parameters
#define FREEFALL_THRESHOLD 0.2 // g
#define IMPACT_THRESHOLD 2.5  // g
#define WINDOW_SIZE 1.0       // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x;
    float accel_y;
    float accel_z;
    float gyro_x;
    float gyro_y;
    float gyro_z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_lsm6dsr();
int read_lsm6dsr_data(sensor_data_t *data);
float calculate_acceleration_magnitude(const sensor_data_t *data);
void log_data(const sensor_data_t *data);
void fall_detection(float magnitude);
void signal_handler(int signal);
void cleanup();

// State machine variables
enum {IDLE, FREEFALL, IMPACT} state = IDLE;
time_t freefall_start_time = 0;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() != 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_lsm6dsr_data(&sensor_data) == 0) {
            // Calculate acceleration magnitude
            float magnitude = calculate_acceleration_magnitude(&sensor_data);

            // Log data
            log_data(&sensor_data);

            // Fall detection
            fall_detection(magnitude);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Delay for 10 ms (104 Hz ODR)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0); // Bus 1, address 0x6A, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize LSM6DSR
int init_lsm6dsr() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x6A) {
        fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0x6A\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: +-2g, 104 Hz
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) { // 0x80 = 104 Hz, +-2g
        fprintf(stderr, "Failed to write CTRL1_XL register\n");
        return -1;
    }

    // Configure gyroscope: +-250 dps, 104 Hz
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) { // 0x80 = 104 Hz, +-250 dps
        fprintf(stderr, "Failed to write CTRL2_G register\n");
        return -1;
    }

    return 0;
}

// Read accelerometer and gyroscope data
int read_lsm6dsr_data(sensor_data_t *data) {
    char buffer[12];

    // Read accelerometer and gyroscope data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12) < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    // Combine high and low bytes for accelerometer data
    int16_t gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    int16_t accel_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t accel_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t accel_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert to g and dps
    data->gyro_x = (float)gyro_x * GYRO_SCALE / 1000.0;
    data->gyro_y = (float)gyro_y * GYRO_SCALE / 1000.0;
    data->gyro_z = (float)gyro_z * GYRO_SCALE / 1000.0;
    data->accel_x = (float)accel_x * ACCEL_SCALE / 1000.0;
    data->accel_y = (float)accel_y * ACCEL_SCALE / 1000.0;
    data->accel_z = (float)accel_z * ACCEL_SCALE / 1000.0;

    return 0;
}

// Calculate acceleration magnitude
float calculate_acceleration_magnitude(const sensor_data_t *data) {
    return sqrt(data->accel_x * data->accel_x + data->accel_y * data->accel_y + data->accel_z * data->accel_z);
}

// Log data to file
void log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data->accel_x, data->accel_y, data->accel_z,
            data->gyro_x, data->gyro_y, data->gyro_z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Fall detection state machine
void fall_detection(float magnitude) {
    time_t now = time(NULL);

    switch (state) {
        case IDLE:
            if (magnitude < FREEFALL_THRESHOLD) {
                state = FREEFALL;
                freefall_start_time = now;
                printf("Freefall detected\n");
            }
            break;
        case FREEFALL:
            if (magnitude > IMPACT_THRESHOLD) {
                state = IMPACT;
                printf("Impact detected\n");
            } else if (difftime(now, freefall_start_time) > WINDOW_SIZE) {
                state = IDLE;
                printf("Freefall timeout, returning to IDLE\n");
            }
            break;
        case IMPACT:
            state = IDLE;
            printf("Returning to IDLE\n");
            break;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

