#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Define ADIS16266 register addresses
#define WHO_AM_I 0x02
#define X_GYRO_OUT 0x04

// Define scaling factor
#define SCALE_FACTOR 0.0305

// Define log file name
#define LOG_FILE "gyro_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int verify_who_am_i();
int read_register(uint8_t address, uint16_t *data);
double scale_gyro_data(int16_t raw_data);
int log_data(double angular_rate);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Verify WHO_AM_I register
int verify_who_am_i() {
    uint16_t who_am_i_value;
    if (read_register(WHO_AM_I, &who_am_i_value) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
