#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define gyroscope registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define WHO_AM_I 0x0F

// Define gyroscope sensitivity
#define SENSITIVITY 8.75f

// Define I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x69

// Define sampling interval
#define SAMPLE_INTERVAL_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int initialize_gyroscope();
gyro_data_t read_gyro_data();
void convert_to_dps(int16_t raw_x, int16_t raw_y, int16_t raw_z, gyro_data_t *dps_data);
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the gyroscope
int initialize_gyroscope() {
    int retries = 3;
    int result;

    // Set CTRL_REG1 to 0x0F (Normal mode, all axes enabled)
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
        if (result == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
            retries--;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1 after multiple retries.\n");
        return -1;
    }

    // Set CTRL_REG4 to 0x00 (Full-scale range +-250 dps)
    retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
        if (result == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG4: %s\n", strerror(errno));
            retries--;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4 after multiple retries.\n");
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != 0xD3) {
        fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0xD3.\n", who_am_i);
        return -1;
    }

    printf("Gyroscope initialized successfully.\n");
    return 0;
}

// Function to read gyroscope data
gyro_data_t read_gyro_data() {
    char buffer[6];
    gyro_data_t data;
    int result;

    result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
        data.x = 0.0f; // Set to 0 to avoid garbage values
        data.y = 0.0f;
        data.z = 0.0f;
        return data;
    }

    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    convert_to_dps(raw_x, raw_y, raw_z, &data);

    return data;
}

// Function to convert raw data to degrees per second
void convert_to_dps(int16_t raw_x, int16_t raw_y, int16_t raw_z, gyro_data_t *dps_data) {
    dps_data->x = (float)raw_x / SENSITIVITY;
    dps_data->y = (float)raw_y / SENSITIVITY;
    dps_data->z = (float)raw_z / SENSITIVITY;
}

// Function to log data to a file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    fprintf(log_file, "%ld.%09ld,%.3f,%.3f,%.3f\n", ts.tv_sec, ts.tv_nsec, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize gyroscope
    if (initialize_gyroscope() != 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        gyro_data_t data = read_gyro_data();
        log_data(data);
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 10ms
    }

    // Clean up resources
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

