#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Define the I2C bus and slave address
#define I2C_BUS "/dev/i2c-1"
#define I2C_SLAVE_ADDRESS 0x53

// Define the registers for the Omron D7S-0001
#define D7S_REG_X_LSB 0x28
#define D7S_REG_X_MSB 0x29
#define D7S_REG_Y_LSB 0x2A
#define D7S_REG_Y_MSB 0x2B
#define D7S_REG_Z_LSB 0x2C
#define D7S_REG_Z_MSB 0x2D

// Define the sampling interval in milliseconds
#define SAMPLING_INTERVAL_MS 100

// Global variables for I2C file descriptor and CSV file pointer
int i2c_fd = -1;
FILE *csv_file = NULL;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg, int16_t *value);
int16_t combine_bytes(uint8_t lsb, uint8_t msb);
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size);
int log_data_to_csv(FILE *fp, const char *timestamp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signum);

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function to read a 16-bit word from the I2C device
int i2c_read_word(int fd, uint8_t reg, int16_t *value) {
    uint8_t buffer[2];
    int ret;

    // Write the register address to be read
    ret = write(fd, &reg, 1);
    if (ret != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Read two bytes from the I2C device
    ret = read(fd, buffer, 2);
    if (ret != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *value = combine_bytes(buffer[0], buffer[1]);

    return 0;
}

// Function to combine two bytes into a signed 16-bit integer
int16_t combine_bytes(uint8_t lsb, uint8_t msb) {
    return (int16_t)((msb << 8) | lsb);
}

// Function to get the current timestamp in ISO-8601 format
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp_str;
}

// Function to log the data to the CSV file
int log_data_to_csv(FILE *fp, const char *timestamp, int16_t x, int16_t y, int16_t z) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (csv_file != NULL) {
            fclose(csv_file);
        }
        exit(0);
    }
}

int main() {
    char timestamp[32];
    sensor_data_t sensor_data;

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open the CSV file for writing
    csv_file = fopen("vibration_log.csv", "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write the CSV header
    fprintf(csv_file, "Timestamp,X,Y,Z\n");

    // Main loop
    while (1) {
        // Read the sensor data
        if (i2c_read_word(i2c_fd, D7S_REG_X_LSB, &sensor_data.x) != 0) {
            fprintf(stderr, "Error reading X axis data. Skipping sample.\n");
            continue;
        }
        if (i2c_read_word(i2c_fd, D7S_REG_Y_LSB, &sensor_data.y) != 0) {
            fprintf(stderr, "Error reading Y axis data. Skipping sample.\n");
            continue;
        }
        if (i2c_read_word(i2c_fd, D7S_REG_Z_LSB, &sensor_data.z) != 0) {
            fprintf(stderr, "Error reading Z axis data. Skipping sample.\n");
            continue;
        }

        // Get the current timestamp
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        // Log the data to the CSV file
        if (log_data_to_csv(csv_file, timestamp, sensor_data.x, sensor_data.y, sensor_data.z) != 0) {
            fprintf(stderr, "Error logging data to CSV file. Skipping sample.\n");
        }

        // Wait for the next sample
        usleep(SAMPLING_INTERVAL_MS * 1000); // Convert milliseconds to microseconds
    }

    // The following lines will never be reached because of the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    close(i2c_fd);
    fclose(csv_file);
    return 0;
}

