#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "conveyor_log.txt"

// Global variables for GPIO resources
struct gpiod_chip *chip;
struct gpiod_line *sensor1_line;
struct gpiod_line *sensor2_line;
FILE *log_file;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int log_data(FILE *fp, int sensor1_state, int sensor2_state);
void handle_conveyor_halt(int sensor1_state, int sensor2_state);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO resources
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

// Function to read sensor state
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %d\n", value);
        return -1; // Indicate error
    }
    return value;
}

// Function to log data to file
int log_data(FILE *fp, int sensor1_state, int sensor2_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    if (fprintf(fp, "%ld,%d,%d\n", timestamp_ms, sensor1_state, sensor2_state) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1; // Indicate error
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Function to handle conveyor halt
void handle_conveyor_halt(int sensor1_state, int sensor2_state) {
    if (sensor1_state == 1 && sensor2_state == 1) {
        printf("Conveyor Halted!\n");
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIOCHIP);
        return 1;
    }

    // Request GPIO lines
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        fprintf(stderr, "Error requesting GPIO line %d\n", SENSOR1_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        fprintf(stderr, "Error requesting GPIO line %d\n", SENSOR2_PIN);
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO line direction to input
    if (gpiod_line_request_input(sensor1_line, "conveyor_monitor") < 0) {
        fprintf(stderr, "Error requesting input direction for GPIO line %d\n", SENSOR1_PIN);
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(sensor2_line, "conveyor_monitor") < 0) {
        fprintf(stderr, "Error requesting input direction for GPIO line %d\n", SENSOR2_PIN);
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_state = read_sensor(sensor1_line);
        int sensor2_state = read_sensor(sensor2_line);

        if (sensor1_state == -1 || sensor2_state == -1) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break;
        }

        if (log_data(log_file, sensor1_state, sensor2_state) == -1) {
            fprintf(stderr, "Error logging data, exiting...\n");
            break;
        }

        handle_conveyor_halt(sensor1_state, sensor2_state);

        usleep(50000); // 50 ms delay
    }

    // Cleanup (should not reach here under normal circumstances due to signal handler)
    gpiod_line_release(sensor1_line);
    gpiod_line_release(sensor2_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

