// Define sensor parameters
#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define GRAVITY 9.81f
#define TILT_THRESHOLD 45.0f

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(const char *bus, int addr);
int verify_sensor_id(int fd);
int init_sensor(int fd);
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
bool check_tilt_threshold(float angle);
int log_fall_event(int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
}

// Initialize I2C interface
int init_i2c(const char *bus, int addr) {
