#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

// Define sensor parameters
#define I2C_BUS "/dev/i2c-1"
#define LIS3MDL_ADDR 0x1E
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0x3D
#define CTRL_REG1 0x20
#define CTRL_REG4 0x24
#define CTRL_REG3 0x26
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Define calibration parameters
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 1.0
#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Define metal detector threshold
#define METAL_THRESHOLD 800.0

// Define logging parameters
#define LOG_FILE "magnetic_log.txt"
#define LOG_INTERVAL_MS 100

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

// Function prototypes
int init_i2c(const char *bus, int address);
int init_sensor(int fd);
int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z);
magnetometer_data_t process_sensor_data(int16_t x, int16_t y, int16_t z);
void log_data(FILE *fp, magnetometer_data_t data);
void check_metal_detector(magnetometer_data_t data);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
    terminate = 1;
}

// Initialize I2C interface
int init_i2c(const char *bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize LIS3MDL sensor
int init_sensor(int fd) {
    int retries = 3;
    while (retries > 0) {
        // Check WHO_AM_I register
        uint8_t who_am_i;
        if (read(fd, &who_am_i, 1) != 1) {
            perror("Error reading WHO_AM_I register");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        if (who_am_i != WHO_AM_I_VALUE) {
            fprintf(stderr, "WHO_AM_I check failed. Expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        // Configure CTRL_REG1 (ODR = 80 Hz, Continuous conversion)
        uint8_t ctrl_reg1 = 0x70; // 0b01110000
        if (write(fd, &ctrl_reg1, 1) != 1) {
            perror("Error writing to CTRL_REG1");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        // Configure CTRL_REG4 (High-performance mode, all axes)
        uint8_t ctrl_reg4 = 0x0C; // 0b00001100
        if (write(fd, &ctrl_reg4, 1) != 1) {
            perror("Error writing to CTRL_REG4");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        // Configure CTRL_REG3 (Enable continuous conversion)
        uint8_t ctrl_reg3 = 0x00; // 0b00000000
        if (write(fd, &ctrl_reg3, 1) != 1) {
            perror("Error writing to CTRL_REG3");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        printf("Sensor initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Sensor initialization failed after multiple retries.\n");
    return -1; // Failure
}

// Read sensor data
int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];

    if (read(fd, buffer, 6) != 6) {
        perror("Error reading sensor data");
        return -1;
    }

    // Combine low and high bytes for each axis
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Process sensor data and apply calibration
magnetometer_data_t process_sensor_data(int16_t x, int16_t y, int16_t z) {
    magnetometer_data_t data;

    // Apply calibration
    data.x = ((float)x + X_OFFSET) * X_SCALE * 0.146; // Convert to mG
    data.y = ((float)y + Y_OFFSET) * Y_SCALE * 0.146;
    data.z = ((float)z + Z_OFFSET) * Z_SCALE * 0.146;

    return data;
}

// Log data to file
void log_data(FILE *fp, magnetometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Check for metal detector threshold
void check_metal_detector(magnetometer_data_t data) {
    float magnitude = sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr, "Metal Detected! Magnitude: %.2f mG\n", magnitude);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, LIS3MDL_ADDR);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Initialize sensor
    if (init_sensor(i2c_fd) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = LOG_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds

    int16_t x, y, z;
    magnetometer_data_t data;

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &x, &y, &z) == 0) {
            // Process sensor data
            data = process_sensor_data(x, y, z);

            // Log data
            log_data(log_file, data);

            // Check for metal detector
            check_metal_detector(data);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        // Sleep for the specified interval
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

