#define ADXL354B_XDATA_H 0x0A
#define ADXL354B_YDATA_L 0x0B
#define ADXL354B_YDATA_M 0x0C
#define ADXL354B_YDATA_H 0x0D
#define ADXL354B_ZDATA_L 0x0E
#define ADXL354B_ZDATA_M 0x0F
#define ADXL354B_ZDATA_H 0x10

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len);
int spi_write_register(int handle, uint8_t reg, uint8_t data);
int adxl354b_reset(int handle);
int adxl354b_init(int handle);
int adxl354b_read_acceleration(int handle, int32_t *x, int32_t *y, int32_t *z);
void log_data(FILE *fp, int32_t x, int32_t y, int32_t z);
void signal_handler(int signal);

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len) {
    char tx_buf[1];
    char rx_buf[len];
    tx_buf[0] = (reg << 1) | 0x80; // Set read bit (bit 7)

    if (spiXfer(handle, tx_buf, rx_buf, len + 1) != 0) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    for (int i = 0; i < len; i++) {
        data[i] = rx_buf[i + 1];
    }

    return 0;
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t reg, uint8_t data) {
    char tx_buf[2];
    tx_buf[0] = (reg << 1) & 0x7F; // Clear read bit (bit 7)
    tx_buf[1] = data;

    if (spiWrite(handle, tx_buf, 2) != 0) {
        fprintf(stderr, "SPI write error\n");
        return -1;
    }

    return 0;
}

// ADXL354B Reset Function
int adxl354b_reset(int handle) {
    if (spi_write_register(handle, ADXL354B_RESET, 0x52) != 0) {
        fprintf(stderr, "Reset write error\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms
    return 0;
}

// ADXL354B Initialization Function
int adxl354b_init(int handle) {
    uint8_t partid;

    // Check PARTID
    if (spi_read_register(handle, ADXL354B_PARTID, &partid, 1) != 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }
    if (partid != 0x1D) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X\n", partid);
        return -1;
    }

    // Reset the device
    if (adxl354b_reset(handle) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        return -1;
    }

    // Set measurement mode to single-shot mode
    if (spi_write_register(handle, ADXL354B_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Failed to set POWER_CTL\n");
        return -1;
    }

    // Wait for STABLE bit to clear
    uint8_t status;
    int stable_timeout = 100; // 100 ms timeout
    while (stable_timeout > 0) {
        if (spi_read_register(handle, ADXL354B_STATUS, &status, 1) != 0) {
            fprintf(stderr, "Failed to read STATUS\n");
            return -1;
        }
        if ((status & 0x01) == 0) break; // STABLE bit is clear
        gpioDelay(1000); // Wait 1 ms
        stable_timeout--;
    }
    if (stable_timeout == 0) {
        fprintf(stderr, "STABLE bit timeout\n");
        return -1;
    }

    // Set measurement mode to measurement mode
    if (spi_write_register(handle, ADXL354B_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Failed to set POWER_CTL for measurement mode\n");
        return -1;
    }

    return 0;
}

// ADXL354B Read Acceleration Data Function
int adxl354b_read_acceleration(int handle, int32_t *x, int32_t *y, int32_t *z) {
    uint8_t x_l, x_m, x_h, y_l, y_m, y_h, z_l, z_m, z_h;

    if (spi_read_register(handle, ADXL354B_XDATA_L, &x_l, 1) != 0) return -1;
    if (spi_read_register(handle, ADXL354B_XDATA_M, &x_m, 1) != 0) return -1;
    if (spi_read_register(handle, ADXL354B_XDATA_H, &x_h, 1) != 0) return -1;
    if (spi_read_register(handle, ADXL354B_YDATA_L, &y_l, 1) != 0) return -1;
    if (spi_read_register(handle, ADXL354B_YDATA_M, &y_m, 1) != 0) return -1;
    if (spi_read_register(handle, ADXL354B_YDATA_H, &y_h, 1) != 0) return -1;
    if (spi_read_register(handle, ADXL354B_ZDATA_L, &z_l, 1) != 0) return -1;
    if (spi_read_register(handle, ADXL354B_ZDATA_M, &z_m, 1) != 0) return -1;
    if (spi_read_register(handle, ADXL354B_ZDATA_H, &z_h, 1) != 0) return -1;

    *x = ((int32_t)x_h << 12) | ((int32_t)x_m << 4) | ((int32_t)x_l >> 4);
    *y = ((int32_t)y_h << 12) | ((int32_t)y_m << 4) | ((int32_t)y_l >> 4);
    *z = ((int32_t)z_h << 12) | ((int32_t)z_m << 4) | ((int32_t)z_l >> 4);

    // Sign extend 20-bit data to 32-bit
    if (*x & 0x80000) *x |= 0xFFF00000;
    if (*y & 0x80000) *y |= 0xFFF00000;
    if (*z & 0x80000) *z |= 0xFFF00000;

    return 0;
}

// Log Data Function
void log_data(FILE *fp, int32_t x, int32_t y, int32_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, %.6f, %.6f, %.6f\n", timestamp,
            x * 0.0000039, y * 0.0000039, z * 0.0000039);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal Handler Function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int32_t x, y, z;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
