#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// ADIS16362 Register Addresses
#define X_GYRO   0x04
#define Y_GYRO   0x06
#define Z_GYRO   0x08
#define X_ACCL   0x0A
#define Y_ACCL   0x0C
#define Z_ACCL   0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_MODE 3

// Scaling factors
#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.0025

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    double timestamp;
    double x_gyro;
    double y_gyro;
    double z_gyro;
    double x_accel;
    double y_accel;
    double z_accel;
} sensor_data_t;

// Function prototypes
int initialize();
int read_register(uint8_t address, uint16_t *data);
sensor_data_t read_imu_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    return 0;
}

// Read a 16-bit register from the ADIS16362
int read_register(uint8_t address, uint16_t *data) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    tx_buf[0] = address | 0x80; // Set MSB to indicate read
    tx_buf[1] = 0x00; // Dummy byte

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI Xfer failed: %d\n", result);
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Read IMU data and convert to physical units
sensor_data_t read_imu_data() {
    sensor_data_t data;
    struct timespec ts;
    uint16_t raw_data;

    clock_gettime(CLOCK_REALTIME, &ts);
    data.timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    if (read_register(X_GYRO, &raw_data) == 0) {
        data.x_gyro = (double)raw_data * GYRO_SCALE;
    } else {
        data.x_gyro = 0.0; // Handle error
    }

    if (read_register(Y_GYRO, &raw_data) == 0) {
        data.y_gyro = (double)raw_data * GYRO_SCALE;
    } else {
        data.y_gyro = 0.0; // Handle error
    }

    if (read_register(Z_GYRO, &raw_data) == 0) {
        data.z_gyro = (double)raw_data * GYRO_SCALE;
    } else {
        data.z_gyro = 0.0; // Handle error
    }

    if (read_register(X_ACCL, &raw_data) == 0) {
        data.x_accel = (double)raw_data * ACCEL_SCALE;
    } else {
        data.x_accel = 0.0; // Handle error
    }

    if (read_register(Y_ACCL, &raw_data) == 0) {
        data.y_accel = (double)raw_data * ACCEL_SCALE;
    } else {
        data.y_accel = 0.0; // Handle error
    }

    if (read_register(Z_ACCL, &raw_data) == 0) {
        data.z_accel = (double)raw_data * ACCEL_SCALE;
    } else {
        data.z_accel = 0.0; // Handle error
    }

    return data;
}

// Log data to CSV file
void log_data(sensor_data_t data) {
    fprintf(log_file, "%.9f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            data.timestamp, data.x_gyro, data.y_gyro, data.z_gyro,
            data.x_accel, data.y_accel, data.z_accel);
    fflush(log_file);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    printf("IMU data logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        sensor_data_t data = read_imu_data();
        log_data(data);
        gpioDelay(10000); // 10 ms delay
    }

    cleanup();
    return 0;
}

