#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define the GPIO pin number
#define GPIO_PIN 17

// Define the GPIO chip name
#define GPIO_CHIP "gpiochip4"

// Global variables for GPIO resources
struct gpiod_chip *chip = NULL;
struct gpiod_line *line = NULL;

// Function prototypes
int read_sensor(struct gpiod_line *line);
void start_self_parking_sequence(void);
void end_self_parking_sequence(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        // Release GPIO resources
        if (line) {
            gpiod_line_release(line);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(0);
    }
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to start the self-parking sequence
void start_self_parking_sequence(void) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Self-parking sequence started\n", timestamp);
}

// Function to end the self-parking sequence
void end_self_parking_sequence(void) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Self-parking sequence completed\n", timestamp);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    // Open the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for input
    if (gpiod_line_request_input(line, "obstacle_detector") < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for input\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Obstacle detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int sensor_value = read_sensor(line);
        if (sensor_value < 0) {
            // Error reading sensor, exit loop
            break;
        }

        if (sensor_value == 0) {
            // Obstacle detected
            start_self_parking_sequence();
            sleep(2); // Simulate self-parking sequence
            end_self_parking_sequence();
        }

        sleep(1); // Poll every 1 second
    }

    // Release GPIO resources before exiting
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

