#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO17 17
#define GPIO27 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *line17 = NULL;
struct gpiod_line *line27 = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int read_sensor(int gpio_pin);
void log_status(int sensor1_value, int sensor2_value);
void cleanup(int signum);

// Signal handler for Ctrl+C
void cleanup(int signum) {
    printf("\nCleaning up and exiting...\n");

    // Release GPIO lines
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line27) {
        gpiod_line_release(line27);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    struct gpiod_line *line = (gpio_pin == GPIO17) ? line17 : line27;
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d\n", gpio_pin);
        return -1; // Indicate error
    }
    return value;
}

// Function to log sensor status with timestamp
void log_status(int sensor1_value, int sensor2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Sensor 17: %d, Sensor 27: %d\n", timestamp, sensor1_value, sensor2_value);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIOCHIP);
        return 1;
    }

    // Get GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO17);
        gpiod_chip_close(chip);
        return 1;
    }

    line27 = gpiod_chip_get_line(chip, GPIO27);
    if (!line27) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO27);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for input
    if (gpiod_line_request_input(line17, "obstacle_sensor_17") < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for input\n", GPIO17);
        gpiod_line_release(line27);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line27, "obstacle_sensor_27") < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for input\n", GPIO27);
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_value = read_sensor(GPIO17);
        int sensor2_value = read_sensor(GPIO27);

        if (sensor1_value != -1 && sensor2_value != -1) {
            log_status(sensor1_value, sensor2_value);
        } else {
            fprintf(stderr, "Error reading sensor values. Skipping logging.\n");
        }

        usleep(100000); // 100 ms
    }

    return 0;
}

