#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// ADIS16266 Register Addresses
#define ADIS16266_MSC_CTRL 0x024
#define ADIS16266_XGYRO_OUT 0x004
#define ADIS16266_YGYRO_OUT 0x006
#define ADIS16266_ZGYRO_OUT 0x008

// SPI Device and Chip Select Pin Definitions
#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 8

// SPI Configuration
#define SPI_MODE SPI_MODE_3
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Global Variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(void);
int gpio_init(void);
int adis16266_init(void);
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void convert_to_degrees(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *x_deg, float *y_deg, float *z_deg);
void log_data(float x, float y, float z);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization Function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// GPIO Initialization Function
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_PIN);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "adis16266_cs", 1) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// ADIS16266 Initialization Function
int adis16266_init(void) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Enable Data Ready Mode (MSC_CTRL = 0x0004)
    tx_buf[0] = ADIS16266_MSC_CTRL >> 8; // Address MSB
    tx_buf[1] = ADIS16266_MSC_CTRL & 0xFF; // Address LSB
    tx_buf[2] = 0x04; // Data to write

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;
    transfer[0].cs_change = 0; // Keep CS active for the entire transfer

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Error setting CS low");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error writing to SPI device");
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("Error setting CS high");
        }
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Error setting CS high");
        return -1;
    }

    return 0;
}

// Function to Read Gyroscope Data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Read X Gyro Data
    tx_buf[0] = ADIS16266_XGYRO_OUT >> 8; // Address MSB
    tx_buf[1] = ADIS16266_XGYRO_OUT & 0xFF; // Address LSB
