#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6B

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define WHO_AM_I 0x0F

// Sensitivity values
#define GYRO_SENSITIVITY 0.00875 // dps/LSB
#define ACCEL_SENSITIVITY 0.000061 // g/LSB

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float gyro_x, gyro_y, gyro_z;
    float accel_x, accel_y, accel_z;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the LSM6DSR sensor
int init_lsm6dsr() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != LSM6DSR_ADDR) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%X, got 0x%X\n", LSM6DSR_ADDR, who_am_i);
        return -1;
    }

    // Configure accelerometer
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x42) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    // Configure gyroscope
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x42) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_sensor_data(sensor_data_t *data) {
    char buffer[12];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12);

    if (bytes_read != 12) {
        fprintf(stderr, "Error reading sensor data: %d bytes read\n", bytes_read);
        return -1;
    }

    // Convert raw data to physical units
    int16_t gyro_x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t gyro_y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t gyro_z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);
    int16_t accel_x_raw = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t accel_y_raw = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t accel_z_raw = (int16_t)((buffer[11] << 8) | buffer[10]);

    data->gyro_x = (float)gyro_x_raw * GYRO_SENSITIVITY;
    data->gyro_y = (float)gyro_y_raw * GYRO_SENSITIVITY;
    data->gyro_z = (float)gyro_z_raw * GYRO_SENSITIVITY;
    data->accel_x = (float)accel_x_raw * ACCEL_SENSITIVITY;
    data->accel_y = (float)accel_y_raw * ACCEL_SENSITIVITY;
    data->accel_z = (float)accel_z_raw * ACCEL_SENSITIVITY;

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR sensor
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            printf("%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
                   sensor_data.gyro_x, sensor_data.gyro_y, sensor_data.gyro_z,
                   sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

