        return -1;
    }

    // Configure CTRL_REG1 for hybrid mode (active, 100 Hz, all axes)
    status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01); // Active mode, 100 Hz
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", status);
        return -1;
    }

    // Configure CTRL_REG2 for reduced noise
    status = i2cWriteByteData(i2c_handle, CTRL_REG2, 0x02); // High resolution
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2: %d\n", status);
        return -1;
    }

