#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// Sensitivity scale factor (3.9mg/LSB)
#define SCALE_FACTOR 0.0039

// Tilt threshold (degrees)
#define TILT_THRESHOLD 30.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int init_adxl345();
accelerometer_data_t read_accelerometer_data();
float calculate_tilt_angle(float x, float y, float z);
void log_tilt_event(float x, float y, float z, float tilt_x, float tilt_y);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the ADXL345 accelerometer
int init_adxl345() {
    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Error: Could not enable measurement mode.\n");
        return -1;
    }
    return 0;
}

// Read accelerometer data from the ADXL345
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char raw_data[6];

    // Read 6 bytes of data (X, Y, Z)
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, raw_data, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data.\n");
        data.x = 0.0; // Set to 0 to avoid using uninitialized values
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g-force units
    data.x = (float)x * SCALE_FACTOR;
    data.y = (float)y * SCALE_FACTOR;
    data.z = (float)z * SCALE_FACTOR;

    return data;
}

// Calculate tilt angles using atan2
float calculate_tilt_angle(float x, float y, float z) {
    return atan2(x, sqrt(y * y + z * z)) * 180 / M_PI;
}

// Log tilt events to a file
void log_tilt_event(float x, float y, float z, float tilt_x, float tilt_y) {
    FILE *fp = fopen("/var/log/tilt_events.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, X: %.2f g, Y: %.2f g, Z: %.2f g, Tilt X: %.2f deg, Tilt Y: %.2f deg\n",
            s, x, y, z, tilt_x, tilt_y);

    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("ADXL345 tilt monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        accelerometer_data_t data = read_accelerometer_data();

        // Calculate tilt angles
        float tilt_x = calculate_tilt_angle(data.x, data.y, data.z);
        float tilt_y = calculate_tilt_angle(data.y, data.x, data.z);

        // Log tilt events
        if (fabs(tilt_x) > TILT_THRESHOLD || fabs(tilt_y) > TILT_THRESHOLD) {
            log_tilt_event(data.x, data.y, data.z, tilt_x, tilt_y);
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("ADXL345 tilt monitoring stopped.\n");

    return 0;
}

