#define WINDOW_DURATION_S 5
#define PAUSE_DURATION_S 1

static volatile int running = 1;
static int alert_threshold = ALERT_THRESHOLD_DEFAULT;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int high_count = 0;
    time_t start_time, current_time;
    struct tm *time_info;
    char timestamp[20];

    // Parse command-line argument for alert threshold
    if (argc > 1) {
        char *endptr;
        long threshold = strtol(argv[1], &endptr, 10);

        if (*endptr != '\0' || threshold <= 0) {
            fprintf(stderr, "Error: Invalid alert threshold. Using default value (%d).\n", ALERT_THRESHOLD_DEFAULT);
        } else {
            alert_threshold = (int)threshold;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring ambient noise levels... Press Ctrl+C to exit.\n");

    while (running) {
        high_count = 0;
        time(&start_time);

        // Sample GPIO17 for 5 seconds
        while (running && (time(NULL) - start_time) < WINDOW_DURATION_S) {
            if (gpioRead(GPIO_PIN) == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 1ms
        }

        // Get current timestamp
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Check if alert threshold is exceeded
        if (high_count > alert_threshold) {
            printf("%s ALERT: High noise level detected! (High readings: %d)\n", timestamp, high_count);
        } else {
            printf("%s Status: Normal (High readings: %d)\n", timestamp, high_count);
        }

        // Pause for 1 second
        gpioDelay(PAUSE_DURATION_S * 1000000); // Delay for 1 second
    }

    // Clean up and exit
    gpioTerminate();
    printf("pigpio terminated. Exiting.\n");
    return 0;
}

