#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_DOOR_A 17
#define GPIO_DOOR_B 27

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define log file name
#define LOG_FILE "access_log.txt"

// Define code range
#define MIN_CODE 100000
#define MAX_CODE 999999

// Define unlock duration
#define UNLOCK_DURATION 5 // seconds

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line_a = NULL;
static struct gpiod_line *line_b = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int generate_code(int *code);
int validate_code(int entered_code, int expected_code);
int unlock_door(int gpio_pin);
int lock_door(int gpio_pin);
int log_access(int code);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to generate a random 6-digit code
int generate_code(int *code) {
    *code = (rand() % (MAX_CODE - MIN_CODE + 1)) + MIN_CODE;
    return 0;
}

// Function to validate the entered code
int validate_code(int entered_code, int expected_code) {
    return (entered_code == expected_code) ? 1 : 0;
}

// Function to unlock a door
int unlock_door(int gpio_pin) {
    int ret;
    struct gpiod_line *line = (gpio_pin == GPIO_DOOR_A) ? line_a : line_b;

    if (!line) {
        fprintf(stderr, "Error: Invalid GPIO pin %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_set_value(line, 1); // Set GPIO HIGH to unlock
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", gpio_pin, strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to lock a door
int lock_door(int gpio_pin) {
    int ret;
    struct gpiod_line *line = (gpio_pin == GPIO_DOOR_A) ? line_a : line_b;

    if (!line) {
        fprintf(stderr, "Error: Invalid GPIO pin %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_set_value(line, 0); // Set GPIO LOW to lock
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d LOW: %s\n", gpio_pin, strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to log access attempts
int log_access(int code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%06d\n", timestamp, code) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    int code;
    int entered_code;
    char input_buffer[20]; // Buffer for user input
    int ret;

    // Seed the random number generator
    srand(time(NULL));

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO lines
    line_a = gpiod_chip_get_line(chip, GPIO_DOOR_A);
    if (!line_a) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_DOOR_A, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line_b = gpiod_chip_get_line(chip, GPIO_DOOR_B);
    if (!line_b) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_DOOR_B, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line_a);
        return EXIT_FAILURE;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line_a, "door_access", 0); // Initial value LOW
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_DOOR_A, strerror(-ret));
        gpiod_chip_close(chip);
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_b, "door_access", 0); // Initial value LOW
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_DOOR_B, strerror(-ret));
        gpiod_chip_close(chip);
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_line_release(line_a);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Generate a new code
        if (generate_code(&code) != 0) {
            fprintf(stderr, "Error generating code.\n");
            break;
        }

        printf("Enter the 6-digit code: ");
        fflush(stdout);

        // Read user input
        if (fgets(input_buffer, sizeof(input_buffer), stdin) == NULL) {
            if (feof(stdin)) {
                fprintf(stderr, "\nExiting on end of file.\n");
                break;
            } else {
                fprintf(stderr, "Error reading from stdin: %s\n", strerror(errno));
                break;
            }
        }

        // Remove trailing newline
        input_buffer[strcspn(input_buffer, "\n")] = 0;

        // Validate input
        if (sscanf(input_buffer, "%d", &entered_code) != 1) {
            fprintf(stderr, "Invalid input. Please enter a 6-digit number.\n");
            // Clear the input buffer
            while (getchar() != '\n');
            continue;
        }

        // Validate code
        if (validate_code(entered_code, code)) {
            printf("Code accepted. Unlocking Door A...\n");

            // Unlock Door A
            if (unlock_door(GPIO_DOOR_A) != 0) {
                fprintf(stderr, "Error unlocking Door A.\n");
                break;
            }

            // Wait for unlock duration
            sleep(UNLOCK_DURATION);

            // Lock Door A
            if (lock_door(GPIO_DOOR_A) != 0) {
                fprintf(stderr, "Error locking Door A.\n");
                break;
            }

            // Log access
            if (log_access(code) != 0) {
                fprintf(stderr, "Error logging access.\n");
                break;
            }

            printf("Door A locked.\n");
        } else {
            printf("Access denied.\n");
        }
    }

    // Cleanup
    printf("Cleaning up...\n");

    // Lock both doors
    lock_door(GPIO_DOOR_A);
    lock_door(GPIO_DOOR_B);

    // Release GPIO lines
    gpiod_line_release(line_a);
    gpiod_line_release(line_b);

    // Close GPIO chip
    gpiod_chip_close(chip);

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

