#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define HIGH_RES_MODE_2 0x21
#define LOG_FILE "light_log.txt"

static volatile int keep_running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

int set_i2c_slave(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    return 0;
}

int write_i2c_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

int read_i2c_data(int fd, uint16_t *data) {
    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }
    *data = (buffer[0] << 8) | buffer[1];
    return 0;
}

float calculate_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2f;
}

int log_data(FILE *fp, float lux_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (t == NULL) {
        perror("Error getting local time");
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux_value) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    if (set_i2c_slave(i2c_fd, BH1750_ADDR) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (write_i2c_reg(i2c_fd, HIGH_RES_MODE_2) < 0) {
            fprintf(stderr, "Error setting sensor mode, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        usleep(180000); // Wait for conversion (180 ms)

        uint16_t raw_value;
        if (read_i2c_data(i2c_fd, &raw_value) < 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        float lux_value = calculate_lux(raw_value);

        if (log_data(log_file, lux_value) < 0) {
            fprintf(stderr, "Error logging data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        printf("Lux: %.2f\n", lux_value);
        sleep(5);
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

