#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_GPIO 18
#define PORT 12345
#define BUFFER_SIZE 1024
#define SECRET_KEY "MySecretKey"
#define LOG_FILE "frequency_log.txt"

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;

// Function prototypes
int initialize_mpr121();
int read_mpr121_data(int *data);
float map_data_to_frequency(int max_data);
void play_tone(float frequency);
void log_frequency(float frequency);
void handle_client(int client_socket);
void signal_handler(int signum);

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nCaught signal %d, cleaning up...\n", signum);
        gpioPWM(PWM_GPIO, 0); // Stop PWM
        i2cClose(i2c_handle); // Close I2C
        close(new_socket); // Close client socket
        close(server_fd); // Close server socket
        gpioTerminate(); // Terminate pigpio
        if (log_file != NULL) {
            fclose(log_file);
        }
        exit(0);
    }
}

// Initialize MPR121
int initialize_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Configure electrode touch and release thresholds
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x0F) < 0) { // Touch threshold
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x0A) < 0) { // Release threshold
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Configure MPR121 for operation
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Set Electrode Configuration
        fprintf(stderr, "Error: Failed to set electrode configuration\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) { // Enable all electrodes
        fprintf(stderr, "Error: Failed to enable electrodes\n");
        return -1;
    }

    return 0;
}

// Read MPR121 data
int read_mpr121_data(int *data) {
    char buf[24]; // 2 bytes per electrode * 12 electrodes
    if (i2cReadI2CBlockData(i2c_handle, 0x04, buf, 24) < 0) {
        fprintf(stderr, "Error: Failed to read MPR121 data\n");
        return -1;
    }

    for (int i = 0; i < 12; i++) {
        data[i] = (buf[i * 2 + 1] << 8) | buf[i * 2];
    }
    return 0;
}

// Map data to frequency
float map_data_to_frequency(int max_data) {
    // Logarithmic scale mapping
    float frequency = 220.0 * pow(860.0 / 220.0, (float)max_data / 4095.0);
    return frequency;
}

// Play tone using hardware PWM
void play_tone(float frequency) {
    int duty_cycle = 128; // 50% duty cycle
    gpioPWM(PWM_GPIO, duty_cycle);
    gpioSetPWMfrequency(PWM_GPIO, (int)frequency);
}

// Log frequency to file
void log_frequency(float frequency) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Frequency: %.2f Hz\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, frequency);
    fflush(log_file); // Ensure data is written to disk
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;

    while ((bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        printf("Received: %s\n", buffer);

        if (strncmp(buffer, "MOTION_DETECTED:", 16) == 0 && strstr(buffer, SECRET_KEY) != NULL) {
            printf("Motion detected and secret key found!\n");

            int data[12];
            time_t start_time = time(NULL);
            while (time(NULL) - start_time < 5) {
                if (read_mpr121_data(data) == 0) {
                    int max_data = 0;
                    for (int i = 0; i < 12; i++) {
                        if (data[i] > max_data) {
                            max_data = data[i];
                        }
                    }

                    float frequency = map_data_to_frequency(max_data);
                    play_tone(frequency);
                    log_frequency(frequency);
                } else {
                    fprintf(stderr, "Error reading MPR121 data, exiting playback loop.\n");
                    break;
                }
                gpioDelay(20); // Sample every 20ms
            }
            gpioPWM(PWM_GPIO, 0); // Stop PWM after playback
            printf("Playback complete.\n");
        }
    }

    if (bytes_received < 0) {
        perror("Error receiving data");
    }

    close(client_socket);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, 440); // Initial frequency

    // Set PWM range
    gpioSetPWMrange(PWM_GPIO, 255);

    // Set PWM duty cycle to 0 initially
    gpioPWM(PWM_GPIO, 0);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        perror("Socket creation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    // Accept connections
    while (1) {
        struct sockaddr_in client_address;
        int addrlen = sizeof(client_address);
        new_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&addrlen);
        if (new_socket < 0) {
            perror("Accept failed");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        handle_client(new_socket);
    }

    // Cleanup (should not reach here under normal circumstances due to the while loop)
    close(new_socket);
    close(server_fd);
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

