#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define LED_GPIO 17
#define PWM_CHIP 0
#define PWM_NUM 0
#define PWM_PERIOD 1000000 // 1 ms
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *led_line = NULL;
FILE *log_file = NULL;

// Function prototypes
int init_i2c(int bus, int address);
int init_magnetometer(int fd);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
int set_led_brightness(double magnitude);
void log_error(const char *message);
void signal_handler(int sig);

// I2C initialization function
int init_i2c(int bus, int address) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// Magnetometer initialization function
int init_magnetometer(int fd) {
    uint8_t config_data = 0x18; // 10 Hz continuous conversion
    if (write(fd, &config_data, 1) != 1) {
        perror("Error writing to magnetometer");
        return -1;
    }
    return 0;
}

// Magnetometer data reading function
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading magnetometer data");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Magnitude calculation function
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// LED brightness control function using PWM
int set_led_brightness(double magnitude) {
    // Map magnitude to PWM duty cycle (0-100%)
    int duty_cycle = (int)(magnitude / 1000.0 * 100.0); // Assuming max magnitude is 1000
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    // Set PWM duty cycle using gpiod
    int ret = gpiod_line_set_value(led_line, duty_cycle);
    if (ret < 0) {
        perror("Error setting LED brightness");
        return -1;
    }
    return 0;
}

// Error logging function
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
