#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// I2C bus
#define I2C_BUS 1

// Number of samples for offset calculation
#define NUM_OFFSET_SAMPLES 100

// Offset update interval (ms)
#define OFFSET_UPDATE_INTERVAL 500

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Structure to hold offsets
typedef struct {
    double x;
    double y;
    double z;
} offsets_t;

// Function prototypes
int initialize_magnetometer();
magnetometer_data_t read_magnetometer_data();
offsets_t calculate_offsets(magnetometer_data_t *data, int num_samples);
void apply_offsets(magnetometer_data_t raw_data, offsets_t offsets, magnetometer_data_t *corrected_data);
void print_data(magnetometer_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the HMC5883L magnetometer
int initialize_magnetometer() {
    // Configure Register A: 8-sample averaging, 15 Hz output rate
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to Configuration Register A\n");
        return -1;
    }

    // Configure Register B: Gain setting of 1.3 Gauss
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to Configuration Register B\n");
        return -1;
    }

    // Mode Register: Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to Mode Register\n");
        return -1;
    }

    return 0;
}

// Function to read raw magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0; // Set to 0 to avoid garbage values
        data.y = 0;
        data.z = 0;
        return data;
    }

    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Function to calculate hard-iron offsets
offsets_t calculate_offsets(magnetometer_data_t *data, int num_samples) {
    offsets_t offsets = {0.0, 0.0, 0.0};
    for (int i = 0; i < num_samples; i++) {
        offsets.x += data[i].x;
        offsets.y += data[i].y;
        offsets.z += data[i].z;
    }
    offsets.x /= num_samples;
    offsets.y /= num_samples;
    offsets.z /= num_samples;
    return offsets;
}

// Function to apply offsets to raw data
void apply_offsets(magnetometer_data_t raw_data, offsets_t offsets, magnetometer_data_t *corrected_data) {
    corrected_data->x = raw_data.x - offsets.x;
    corrected_data->y = raw_data.y - offsets.y;
    corrected_data->z = raw_data.z - offsets.z;
}

// Function to print the magnetometer data
void print_data(magnetometer_data_t data) {
    printf("X: %d, Y: %d, Z: %d\n", data.x, data.y, data.z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize magnetometer
    if (initialize_magnetometer() < 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Data buffers
    magnetometer_data_t raw_data[NUM_OFFSET_SAMPLES];
    magnetometer_data_t corrected_data;
    offsets_t offsets;
    int sample_index = 0;

    // Main loop
    while (!terminate) {
        // Read raw data
        raw_data[sample_index] = read_magnetometer_data();

        // Update offsets every OFFSET_UPDATE_INTERVAL ms
        if (sample_index == NUM_OFFSET_SAMPLES - 1) {
            offsets = calculate_offsets(raw_data, NUM_OFFSET_SAMPLES);
            sample_index = 0; // Reset index for next update
        } else {
            sample_index++;
        }

        // Apply offsets
        apply_offsets(raw_data[NUM_OFFSET_SAMPLES - 1], offsets, &corrected_data);

        // Print data
        print_data(corrected_data);

        // Wait for OFFSET_UPDATE_INTERVAL ms
        gpioDelay(OFFSET_UPDATE_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

