    // Verify WHO_AM_I register
    who_am_i = i2c_smbus_read_byte_data(i2c_fd, WHO_AM_I);
    if (who_am_i < 0) {
        perror("Error reading WHO_AM_I register");
        return -1;
    }
    if (who_am_i != 0x49) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x49\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: 50 Hz ODR, all axes enabled
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG1_A, 0x57) < 0) {
        perror("Error writing to CTRL_REG1_A");
        return -1;
    }

    // Configure accelerometer: +-2g full-scale
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG4_A, 0x00) < 0) {
        perror("Error writing to CTRL_REG4_A");
        return -1;
    }

    // Configure interrupt: Any-axis-high event
    if (i2c_smbus_write_byte_data(i2c_fd, INT1_CFG, 0x2A) < 0) {
        perror("Error writing to INT1_CFG");
        return -1;
    }

