// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *solenoid1_line, *solenoid2_line;

// Function prototypes
int gpio_init(void);
void solenoid_on(int pin);
void solenoid_off(int pin);
void delay_ms(int milliseconds);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    solenoid_off(SOLENOID_1_PIN);
    solenoid_off(SOLENOID_2_PIN);

    if (solenoid1_line)
        gpiod_line_release(solenoid1_line);
    if (solenoid2_line)
        gpiod_line_release(solenoid2_line);
    if (chip)
        gpiod_chip_close(chip);

    exit(0);
}

// Initialize GPIO lines
int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP);
        return -1;
    }

    solenoid1_line = gpiod_chip_get_line(chip, SOLENOID_1_PIN);
    if (!solenoid1_line) {
        fprintf(stderr, "Error getting GPIO line %d\n", SOLENOID_1_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    solenoid2_line = gpiod_chip_get_line(chip, SOLENOID_2_PIN);
    if (!solenoid2_line) {
        fprintf(stderr, "Error getting GPIO line %d\n", SOLENOID_2_PIN);
        gpiod_line_release(solenoid1_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(solenoid1_line, "solenoid1", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output\n", SOLENOID_1_PIN);
        gpiod_line_release(solenoid1_line);
        gpiod_line_release(solenoid2_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(solenoid2_line, "solenoid2", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output\n", SOLENOID_2_PIN);
        gpiod_line_release(solenoid1_line);
        gpiod_line_release(solenoid2_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Turn solenoid on
void solenoid_on(int pin) {
    if (pin == SOLENOID_1_PIN) {
        gpiod_line_set_value(solenoid1_line, 1);
    } else if (pin == SOLENOID_2_PIN) {
        gpiod_line_set_value(solenoid2_line, 1);
    }
}

// Turn solenoid off
void solenoid_off(int pin) {
    if (pin == SOLENOID_1_PIN) {
        gpiod_line_set_value(solenoid1_line, 0);
    } else if (pin == SOLENOID_2_PIN) {
        gpiod_line_set_value(solenoid2_line, 0);
    }
}

// Delay function using nanosleep
void delay_ms(int milliseconds) {
    struct timespec req;
    req.tv_sec = 0;
    req.tv_nsec = milliseconds * 1000000L;
    nanosleep(&req, NULL);
}

int main(void) {
    // Register signal handlers for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO lines
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Solenoid control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Activate solenoid 1
        solenoid_on(SOLENOID_1_PIN);
        delay_ms(500);

        // Deactivate solenoid 1 and activate solenoid 2
        solenoid_off(SOLENOID_1_PIN);
        solenoid_on(SOLENOID_2_PIN);
        delay_ms(500);

        // Deactivate solenoid 2
        solenoid_off(SOLENOID_2_PIN);
    }

    return 0;
}

