#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins for the door locks
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27

// Define the expected authentication code
#define EXPECTED_CODE "123456"

// Define the serial port file names
#define SERIAL_PORT_1 "/dev/serial0"
#define SERIAL_PORT_2 "/dev/serial1"

// Define the baud rate for the serial ports
#define BAUD_RATE 9600

// Define the timeout duration in seconds
#define TIMEOUT_SECONDS 5

// Define the unlock duration in seconds
#define UNLOCK_DURATION_SECONDS 2

// Global variables for serial port file descriptors
int serial_fd1 = -1;
int serial_fd2 = -1;

// Function prototypes
int initialize_gpio();
int open_serial_port(const char *port);
int read_code(int fd, char *code, int timeout_seconds);
int validate_code(const char *code, const char *expected_code);
int unlock_doors();
int lock_doors();
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);

    // Lock the doors
    lock_doors();

    // Close serial ports
    if (serial_fd1 != -1) {
        close(serial_fd1);
    }
    if (serial_fd2 != -1) {
        close(serial_fd2);
    }

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Cleanup complete. Exiting.\n");
    exit(0);
}

// Initializes the pigpio library and sets the GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);

    // Ensure locks are locked on startup
    lock_doors();

    return 0;
}

// Opens the specified serial port
int open_serial_port(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Error opening serial port %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

