#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <gpiod.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON_TIME_MS 1000
#define PIR_POLL_INTERVAL_MS 50
#define FAILSAFE_TIMEOUT_S 10

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;
static struct gpiod_line *relay_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_init(void);
void pir_interrupt_handler(struct gpiod_line *line, void *user_data);
void failsafe_timer_handler(void *user_data);
void signal_handler(int sig);
void cleanup(void);

// Structure to hold GPIO line information
typedef struct {
    struct gpiod_line *line;
    int pin;
    const char *name;
} gpio_line_t;

// Function to request a GPIO line
static int request_gpio_line(gpio_line_t *gpio_line, struct gpiod_chip *chip, int direction)
{
    gpio_line->line = gpiod_chip_get_line(chip, gpio_line.pin);
    if (!gpio_line->line) {
        syslog(LOG_ERR, "Failed to get line %d for %s", gpio_line.pin, gpio_line.name);
        return -1;
    }

    int ret = gpiod_line_request(gpio_line->line, NULL, direction);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request line %d for %s: %s", gpio_line.pin, gpio_line.name, strerror(-ret));
        gpiod_line_release(gpio_line->line);
        gpio_line->line = NULL;
        return -1;
    }

    return 0;
}

// Function to release a GPIO line
static void release_gpio_line(gpio_line_t *gpio_line)
{
    if (gpio_line->line) {
        gpiod_line_release(gpio_line->line);
        gpio_line->line = NULL;
    }
}

// Function to set the value of a GPIO line
static int set_gpio_value(gpio_line_t *gpio_line, int value)
{
    int ret = gpiod_line_set_value(gpio_line->line, value);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set value on line %d for %s: %s", gpio_line.pin, gpio_line.name, strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to get the value of a GPIO line
static int get_gpio_value(gpio_line_t *gpio_line)
{
    int value = gpiod_line_get_value(gpio_line->line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to get value on line %d for %s: %s", gpio_line.pin, gpio_line.name, strerror(-value));
        return -1;
    }
    return value;
}

// Signal handler function
void signal_handler(int sig)
{
    syslog(LOG_INFO, "Signal %d received, terminating...", sig);
    terminate = 1;
}

// Cleanup function
void cleanup(void)
{
    syslog(LOG_INFO, "Cleaning up...");

    // De-energize the relay
    if (relay_line) {
        set_gpio_value(&relay_line, 0);
    }

    // Release GPIO lines
    release_gpio_line(&relay_line);
    release_gpio_line(&pir_line);

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close syslog
    closelog();

    syslog(LOG_INFO, "Cleanup complete. Exiting.");
    exit(0);
}

// PIR interrupt handler function
void pir_interrupt_handler(struct gpiod_line *line, void *user_data)
{
    int value = get_gpio_value(&pir_line);
    if (value < 0) {
        syslog(LOG_ERR, "Error reading PIR value in interrupt handler");
        return;
    }

    if (value == 1) {
        syslog(LOG_INFO, "Motion detected!");
        set_gpio_value(&relay_line, 1);
        usleep(RELAY_ON_TIME_MS * 1000); // Convert ms to microseconds
        set_gpio_value(&relay_line, 0);
        syslog(LOG_INFO, "Relay de-energized.");
    }
}

// Failsafe timer handler function
void failsafe_timer_handler(void *user_data)
{
    int value = get_gpio_value(&pir_line);
    if (value < 0) {
        syslog(LOG_ERR, "Error reading PIR value in failsafe handler");
        return;
    }

    if (value == 1) {
        syslog(LOG_WARNING, "PIR sensor malfunction: sensor remains HIGH for more than %d seconds. De-energizing relay.", FAILSAFE_TIMEOUT_S);
        set_gpio_value(&relay_line, 0);
    }
}

// GPIO initialization function
int gpio_init(void)
{
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    // Define GPIO lines
    gpio_line_t pir_gpio = { .line = NULL, .pin = PIR_PIN, .name = "PIR Sensor" };
    gpio_line_t relay_gpio = { .line = NULL, .pin = RELAY_PIN, .name = "Relay" };

    // Request PIR line as input
    if (request_gpio_line(&pir_gpio, chip, GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        gpiod_chip_close(chip);
        return -1;
    }
    pir_line = pir_gpio.line;

    // Request Relay line as output
    if (request_gpio_line(&relay_gpio, chip, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        gpiod_chip_close(chip);
        return -1;
    }
    relay_line = relay_gpio.line;

    // Set initial relay state to LOW
    if (set_gpio_value(&relay_line, 0) < 0) {
        gpiod_chip_close(chip);
        return -1;
    }

    // Set up interrupt on PIR line
    int ret = gpiod_line_request_rising_edge_events(pir_line, "motion_detected");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request rising edge events: %s", strerror(-ret));
        gpiod_chip_close(chip);
        return -1;
    }

    // Set up failsafe timer (not implemented in this version, but would be done in a real application)
    // In a real application, you would use a timer library like libev or glib to set up a timer
    // that calls the failsafe_timer_handler function after FAILSAFE_TIMEOUT_S seconds.
    // For this example, we'll just log a message indicating the failsafe timer is not implemented.
    syslog(LOG_INFO, "Failsafe timer not implemented in this version.");

    return 0;
}

int main(void)
{
    // Open syslog
    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed. Exiting.");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Door strike system started.");

    // Main loop
    while (!terminate) {
        // Poll PIR sensor
        int pir_value = get_gpio_value(&pir_line);
        if (pir_value < 0) {
            syslog(LOG_ERR, "Error reading PIR value. Exiting.");
            cleanup();
            return 1;
        }

        // Check for motion
        if (pir_value == 1) {
            syslog(LOG_INFO, "Motion detected!");
            set_gpio_value(&relay_line, 1);
            usleep(RELAY_ON_TIME_MS * 1000); // Convert ms to microseconds
            set_gpio_value(&relay_line, 0);
            syslog(LOG_INFO, "Relay de-energized.");
        }

        usleep(PIR_POLL_INTERVAL_MS * 1000); // Poll every PIR_POLL_INTERVAL_MS milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

