#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the duration of relay activation (seconds)
#define RELAY_ACTIVATION_DURATION 300

// Define the pause duration between relay activations (seconds)
#define RELAY_PAUSE_DURATION 60

// Define the total number of relays
#define NUM_RELAYS 4

// Define the timer interval (seconds)
#define TIMER_INTERVAL 60

// Global variables
volatile sig_atomic_t program_running = 1;
int current_relay = 0;
int current_state = 0; // 0 = activation, 1 = deactivation, 2 = pause

// Function prototypes
void signal_handler(int signal);
void relay_control(int relay_pin, int state);
void timer_callback(int timer_id, void *user_data);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received: %d. Shutting down...", signal);
    program_running = 0;
}

// Function to control the state of a relay
void relay_control(int relay_pin, int state) {
    int result;
    if (state == 1) { // Activate relay (LOW)
        result = gpioWrite(relay_pin, 0);
        if (result != 0) {
            syslog(LOG_ERR, "Error writing to GPIO %d (activate): %d", relay_pin, result);
        } else {
            syslog(LOG_INFO, "Relay %d activated", relay_pin);
        }
    } else { // Deactivate relay (HIGH)
        result = gpioWrite(relay_pin, 1);
        if (result != 0) {
            syslog(LOG_ERR, "Error writing to GPIO %d (deactivate): %d", relay_pin, result);
        } else {
            syslog(LOG_INFO, "Relay %d deactivated", relay_pin);
        }
    }
}

// Timer callback function
void timer_callback(int timer_id, void *user_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (current_state == 0) { // Activation
        relay_control(current_relay, 1); // Activate the current relay
        current_state = 1; // Move to deactivation state
    } else if (current_state == 1) { // Deactivation
        relay_control(current_relay, 0); // Deactivate the current relay
        current_state = 2; // Move to pause state
    } else if (current_state == 2) { // Pause
        // Do nothing, wait for the next timer event
    }

    // Update the current relay
    current_relay = (current_relay == RELAY1_PIN) ? RELAY2_PIN :
                    (current_relay == RELAY2_PIN) ? RELAY3_PIN :
                    (current_relay == RELAY3_PIN) ? RELAY4_PIN : RELAY1_PIN;

    // Update the state based on the current state and duration
    if (current_state == 0) {
        // Activation
        if (timeinfo->tm_sec < RELAY_ACTIVATION_DURATION) {
            // Still within activation duration
        } else {
            // Activation duration exceeded, move to deactivation
            current_state = 1;
        }
    } else if (current_state == 1) {
        // Deactivation
        if (timeinfo->tm_sec < RELAY_ACTIVATION_DURATION + RELAY_PAUSE_DURATION) {
            // Still within pause duration
        } else {
            // Pause duration exceeded, move to activation
            current_state = 0;
        }
    } else if (current_state == 2) {
        // Pause
        if (timeinfo->tm_sec < RELAY_PAUSE_DURATION) {
            // Still within pause duration
        } else {
            // Pause duration exceeded, move to activation
            current_state = 0;
        }
    }
}

int main() {
    int result;

    // Initialize syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins as outputs
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < NUM_RELAYS; i++) {
        result = gpioSetMode(pins[i], PI_OUTPUT);
        if (result != 0) {
            syslog(LOG_ERR, "Error setting GPIO %d as output: %d", pins[i], result);
            gpioTerminate();
            closelog();
            return 1;
        }
        // Initialize all relays to OFF (HIGH)
        gpioWrite(pins[i], 1);
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up the timer
    result = gpioSetTimerFuncEx(0, TIMER_INTERVAL * 1000, timer_callback, NULL); // Timer ID 0, interval in milliseconds
    if (result != 0) {
        syslog(LOG_ERR, "Error setting up timer: %d", result);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (program_running) {
        sleep(1);
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");

    // Deactivate all relays
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(pins[i], 1); // Set HIGH to deactivate
    }

    // Terminate pigpio
    gpioTerminate();

    // Close syslog
    closelog();

    syslog(LOG_INFO, "Exiting.");
    return 0;
}

