#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/timerfd.h>
#include <sys/stat.h>
#include <sys/types.h>

// MPU6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

// Circular Buffer Size
#define BUFFER_SIZE 100

// Global Variables
int i2c_fd = -1;
int sysfs_fd = -1;
timer_t timerid;

// Circular Buffer Structure
typedef struct {
    float x[BUFFER_SIZE];
    float y[BUFFER_SIZE];
    float z[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer buffer = {{0}, {0}, {0}, 0, 0};

// Function Prototypes
int init_mpu6050(int fd);
int read_acceleration(int fd, float *x, float *y, float *z);
void add_to_buffer(CircularBuffer *buffer, float x, float y, float z);
int write_to_sysfs(int fd, const char *data);
void signal_handler(int sig);

// Function to initialize the MPU6050
int init_mpu6050(int fd) {
    unsigned char wake_up = 0x00;
    unsigned char accel_range = 0x00;

    // Wake up the MPU6050
    if (write(fd, &wake_up, 1) != 1) {
        perror("Failed to write to PWR_MGMT_1");
        return -1;
    }
    usleep(10000); // Short delay after waking up

    // Set accelerometer range to +-2g
    if (write(fd, &accel_range, 1) != 1) {
        perror("Failed to write to ACCEL_CONFIG");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the MPU6050
int read_acceleration(int fd, float *x, float *y, float *z) {
    unsigned char reg = ACCEL_XOUT_H;
    unsigned char data[6];
    int16_t raw_x, raw_y, raw_z;

    // Write the register address to be read
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    // Read 6 bytes of acceleration data
    if (read(fd, data, 6) != 6) {
        perror("Failed to read acceleration data");
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (data[0] << 8) | data[1];
    raw_y = (data[2] << 8) | data[3];
    raw_z = (data[4] << 8) | data[5];

    // Scale the raw values to g units
    *x = (float)raw_x / 16384.0;
    *y = (float)raw_y / 16384.0;
    *z = (float)raw_z / 16384.0;

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(CircularBuffer *buffer, float x, float y, float z) {
    buffer->x[buffer->head] = x;
    buffer->y[buffer->head] = y;
    buffer->z[buffer->head] = z;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to write data to the sysfs file
int write_to_sysfs(int fd, const char *data) {
    if (write(fd, data, strlen(data)) != strlen(data)) {
        perror("Failed to write to sysfs file");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Disable the timer
    struct itimerspec its;
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 0;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 0;
    timer_settime(timerid, 0, &its, NULL);

    // Close the I2C device
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close the sysfs file
    if (sysfs_fd != -1) {
        close(sysfs_fd);
    }

    // Delete the sysfs file
    unlink("/sys/kernel/mpu6050_accel/latest");

    // Delete the sysfs directory
    rmdir("/sys/kernel/mpu6050_accel");

    // Destroy the timer
    timer_delete(timerid);

    exit(0);
}

int main() {
    float x, y, z;
    char sysfs_data[100];
    struct sigaction sa;
    struct itimerspec its;

    // Set up signal handlers
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return 1;
    }

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the MPU6050
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Create the sysfs directory
    if (mkdir("/sys/kernel/mpu6050_accel", 0755) == -1 && errno != EEXIST) {
        perror("Failed to create sysfs directory");
        close(i2c_fd);
        return 1;
    }

    // Create the sysfs file
    sysfs_fd = open("/sys/kernel/mpu6050_accel/latest", O_WRONLY | O_CREAT, 0644);
    if (sysfs_fd < 0) {
        perror("Failed to create sysfs file");
        close(i2c_fd);
        rmdir("/sys/kernel/mpu6050_accel");
        return 1;
    }

    // Create the timer
    if (timer_create(CLOCK_REALTIME, NULL, &timerid) == -1) {
        perror("Failed to create timer");
        close(i2c_fd);
        close(sysfs_fd);
        rmdir("/sys/kernel/mpu6050_accel");
        return 1;
    }

    // Configure the timer
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 10000000; // 10 ms (100 Hz)
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 10000000; // 10 ms (100 Hz)

    // Start the timer
    if (timer_settime(timerid, 0, &its, NULL) == -1) {
        perror("Failed to start timer");
        close(i2c_fd);
        close(sysfs_fd);
        rmdir("/sys/kernel/mpu6050_accel");
        timer_delete(timerid);
        return 1;
    }

    // Main loop
    while (1) {
        // Read acceleration data
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Add data to the circular buffer
            add_to_buffer(&buffer, x, y, z);

            // Format the data for sysfs
            snprintf(sysfs_data, sizeof(sysfs_data), "%.3f,%.3f,%.3f", x, y, z);

            // Write data to sysfs
            if (write_to_sysfs(sysfs_fd, sysfs_data) != 0) {
                fprintf(stderr, "Failed to write to sysfs.\n");
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }

        // Sleep for a short time to avoid busy-waiting
        usleep(10000); // 10 ms
    }

    return 0;
}

