    cleanup_gpio();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize all relays to OFF state
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    return 0; // Indicate success
}

// Toggle the state of a relay
void toggle_relay(int pin) {
    int current_state = gpioRead(pin);
    gpioWrite(pin, !current_state);
}

// Cleanup GPIO pins
void cleanup_gpio() {
    // Turn off all relays
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        struct timespec current_time;

        // Relay 1
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if ((current_time.tv_sec - last_toggle1.tv_sec) >= INTERVAL1) {
            toggle_relay(RELAY1_PIN);
            last_toggle1 = current_time;
        }

        // Relay 2
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if ((current_time.tv_sec - last_toggle2.tv_sec) >= INTERVAL2) {
            toggle_relay(RELAY2_PIN);
            last_toggle2 = current_time;
        }

        // Relay 3
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if ((current_time.tv_sec - last_toggle3.tv_sec) >= INTERVAL3) {
            toggle_relay(RELAY3_PIN);
            last_toggle3 = current_time;
        }

        // Relay 4
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if ((current_time.tv_sec - last_toggle4.tv_sec) >= INTERVAL4) {
            toggle_relay(RELAY4_PIN);
            last_toggle4 = current_time;
        }

        // Small delay to avoid busy-waiting
        usleep(10000); // 10ms
    }

    return 0; // This line will never be reached due to the infinite loop
}

