#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 500

// Define cooldown time (in milliseconds)
#define COOLDOWN_TIME 1000

// Global variables
static volatile int running = 1;
static volatile unsigned long last_trigger_time = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
void activate_relay();
void log_alarm();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Read the sound sensor's digital output
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Activate the relay for 3 seconds
void activate_relay() {
    gpioWrite(RELAY_PIN, 1); // Turn relay ON
    gpioDelay(3000);          // Wait for 3 seconds
    gpioWrite(RELAY_PIN, 0); // Turn relay OFF
}

// Log the alarm event to a file
void log_alarm() {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alarm_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: Alarm triggered\n", s);
    fclose(fp);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == 1) {
            unsigned long current_time = gpioTick();

            // Debounce and cooldown
            if (current_time - last_trigger_time > DEBOUNCE_TIME * 1000 &&
                current_time - last_trigger_time > COOLDOWN_TIME * 1000) {

                printf("Sound detected! Activating relay.\n");
                activate_relay();
                log_alarm();
                last_trigger_time = current_time;
            }
        }

        gpioDelay(100); // Poll every 100 milliseconds
    }

    // Cleanup
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();          // Terminate pigpio

    printf("Exiting.\n");
    return 0;
}

