#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define WHO_AM_I     0x75

// Gyroscope sensitivity (LSB/deg/s)
#define GYRO_SENSITIVITY 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold (deg/s)
#define ANGULAR_VELOCITY_THRESHOLD 50.0

// Global variables
int i2c_fd = -1; // I2C file descriptor
volatile sig_atomic_t program_running = 1; // Flag to control program execution

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int i2c_setup(int address);
int mpu6050_init(int fd);
int read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
float convert_to_dps(int16_t raw_data);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_angular_velocity(float x, float y, float z);
void callback_function(float angular_velocity);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// I2C setup function
int i2c_setup(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// MPU-6050 initialization function
int mpu6050_init(int fd) {
    // Wake up the sensor (clear sleep bit)
    if (write(fd, &(uint8_t){0x00}, 1) != 1) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }

    // Verify WHO_AM_I register
    uint8_t who_am_i;
    if (write(fd, &(uint8_t){WHO_AM_I}, 1) != 1) {
        perror("Error writing to WHO_AM_I register address");
        return -1;
    }
    if (read(fd, &who_am_i, 1) != 1) {
        perror("Error reading WHO_AM_I register");
        return -1;
    }

    if (who_am_i != 0x68) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0x68\n", who_am_i);
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t reg = GYRO_XOUT_H;
    uint8_t data[6];

    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to GYRO_XOUT_H register address");
        return -1;
    }

    if (read(fd, data, 6) != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    *gyro_x = (int16_t)((data[0] << 8) | data[1]);
    *gyro_y = (int16_t)((data[2] << 8) | data[3]);
    *gyro_z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Function to convert raw data to degrees per second
float convert_to_dps(int16_t raw_data) {
    return (float)raw_data / GYRO_SENSITIVITY;
}

// Function to add data to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Function to calculate the magnitude of the angular velocity vector
float calculate_angular_velocity(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Callback function to handle threshold exceedance
void callback_function(float angular_velocity) {
    printf("Threshold exceeded! Angular velocity: %.2f deg/s\n", angular_velocity);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C setup failed. Exiting.\n");
        return 1;
    }

    // Initialize MPU-6050
    if (mpu6050_init(i2c_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer gyro_buffer = {{0.0}, 0, 0};

    // Main loop
    while (program_running) {
        int16_t gyro_x_raw, gyro_y_raw, gyro_z_raw;

        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_x_raw, &gyro_y_raw, &gyro_z_raw) == 0) {
            // Convert raw data to degrees per second
            float gyro_x = convert_to_dps(gyro_x_raw);
            float gyro_y = convert_to_dps(gyro_y_raw);
            float gyro_z = convert_to_dps(gyro_z_raw);

            // Calculate angular velocity
            float angular_velocity = calculate_angular_velocity(gyro_x, gyro_y, gyro_z);

            // Add angular velocity to the circular buffer
            add_to_buffer(&gyro_buffer, angular_velocity);

            // Check if threshold is exceeded
