#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define READ_COMMAND {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define CO2_READ_INTERVAL 5 // seconds

int uart_fd = -1;
FILE *log_file = NULL;
FILE *error_log_file = NULL;

// Function to log errors with timestamps
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (error_log_file != NULL) {
        fprintf(error_log_file, "%s: %s\n", timestamp, message);
        fflush(error_log_file);
    } else {
        fprintf(stderr, "%s: %s\n", timestamp, message);
    }
}

// Function to read CO2 data from the sensor
int read_co2(int uart_fd, int *co2_ppm) {
    unsigned char response[9];
    unsigned char read_command[9] = READ_COMMAND;
    int bytes_read;
    int i;
    unsigned short checksum;

    // Send read command
    if (serWrite(uart_fd, (char *)read_command, 9) != 9) {
        log_error("Failed to send read command");
        return -1;
    }

    // Wait for data to be available
    gpioDelay(100); // 100 ms

    // Read response
    bytes_read = 0;
    while (bytes_read < 9 && serDataAvailable(uart_fd) > 0) {
        response[bytes_read++] = serReadByte(uart_fd);
    }

    if (bytes_read != 9) {
        log_error("Incomplete response received");
        return -1;
    }

    // Validate checksum
    checksum = 0;
    for (i = 1; i < 8; i++) {
        checksum += response[i];
    }
    checksum = ~checksum + 1;

    if (checksum != response[8]) {
        log_error("Checksum mismatch");
        return -1;
    }

    // Extract CO2 value
    *co2_ppm = (response[2] << 8) | response[3];

    return 0;
}

// Function to log CO2 data to a file
void log_co2_data(FILE *log_file, int co2_ppm, int error_flag) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    long long microseconds = 0;
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    microseconds = ts.tv_nsec / 1000;

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "{\"timestamp\": \"%s.%06lld\", \"co2_ppm\": %d, \"error\": %d}\n", timestamp, microseconds, co2_ppm, error_flag);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (uart_fd != -1) {
        serClose(uart_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    if (error_log_file != NULL) {
        fclose(error_log_file);
    }

    gpioTerminate();

    exit(0);
}

int main() {
    int co2_ppm;
    int error_flag;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open UART
    uart_fd = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for no flags
    if (uart_fd < 0) {
        log_error("Failed to open UART");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        serClose(uart_fd);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        fclose(log_file);
        serClose(uart_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        error_flag = 0;
        result = read_co2(uart_fd, &co2_ppm);
        if (result != 0) {
            error_flag = 1;
            co2_ppm = -1; // Indicate error
        }

        log_co2_data(log_file, co2_ppm, error_flag);

        printf("{\"timestamp\": \"NOW\", \"co2_ppm\": %d, \"error\": %d}\n", co2_ppm, error_flag);

        gpioDelay(CO2_READ_INTERVAL * 1000); // Wait 5 seconds
    }

    return 0;
}

