#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define DATA_START 0x03
#define GPIO_PIN 17
#define TARGET_HEADING 90.0
#define HEADING_THRESHOLD 10.0
#define BUFFER_SIZE 100

// Calibration offsets
#define X_OFFSET 100.0
#define Y_OFFSET -50.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float heading_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_magnetometer();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
float compensate_heading(int16_t x, int16_t y, int16_t z);
void control_gpio(float heading);
void add_to_buffer(float heading);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the magnetometer
int initialize_magnetometer() {
    // Configure CONFIG_A
    if (i2cWriteByteData(i2c_handle, CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to CONFIG_A\n");
        return -1;
    }

    // Configure CONFIG_B
    if (i2cWriteByteData(i2c_handle, CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to CONFIG_B\n");
        return -1;
    }

    // Configure MODE
    if (i2cWriteByteData(i2c_handle, MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to MODE\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, DATA_START, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Compensate heading
float compensate_heading(int16_t x, int16_t y, int16_t z) {
    float x_comp = (float)x - X_OFFSET;
    float y_comp = (float)y - Y_OFFSET;

    float heading = atan2(y_comp, x_comp) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Control GPIO
void control_gpio(float heading) {
    float diff = fabs(heading - TARGET_HEADING);
    if (diff > 180) diff = 360 - diff; // Handle wrap-around

    if (diff > HEADING_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1); // Set HIGH
    } else {
        gpioWrite(GPIO_PIN, 0); // Set LOW
    }
}

// Add to circular buffer
void add_to_buffer(float heading) {
    heading_buffer[buffer_index] = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize magnetometer
    if (initialize_magnetometer() < 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float heading;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Compensate heading
            heading = compensate_heading(x, y, z);

            // Control GPIO
            control_gpio(heading);

            // Add to buffer
            add_to_buffer(heading);

            // Print heading (for debugging)
            printf("Heading: %.2f\n", heading);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Retrying...\n");
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

