// Define GPIO pins for relays
#define RED_RELAY_PIN 17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN 22

// Define I2C bus and address
#define I2C_BUS 1
#define BH1750_ADDR 0x23

// Define BH1750 command for continuous high-resolution mode
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10

// Define log file name
#define LOG_FILE "lighting_log.txt"

// Global variables for GPIO and I2C resources
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *red_relay_line = NULL;
struct gpiod_line *green_relay_line = NULL;
struct gpiod_line *blue_relay_line = NULL;
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int init_gpio(void);
int init_i2c(void);
int read_bh1750(int fd);
void control_relays(int lux);
void log_data(int lux, int red_state, int green_state, int blue_state);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");

    // Turn off all relays
    if (red_relay_line) {
        gpiod_line_set_value(red_relay_line, 0);
    }
    if (green_relay_line) {
        gpiod_line_set_value(green_relay_line, 0);
    }
    if (blue_relay_line) {
        gpiod_line_set_value(blue_relay_line, 0);
    }

    // Release GPIO lines
    if (red_relay_line) {
        gpiod_line_release(red_relay_line);
    }
    if (green_relay_line) {
        gpiod_line_release(green_relay_line);
    }
    if (blue_relay_line) {
        gpiod_line_release(blue_relay_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close I2C file descriptor
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

// Initialize GPIO lines
int init_gpio(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    red_relay_line = gpiod_chip_get_line(gpio_chip, RED_RELAY_PIN);
    green_relay_line = gpiod_chip_get_line(gpio_chip, GREEN_RELAY_PIN);
    blue_relay_line = gpiod_chip_get_line(gpio_chip, BLUE_RELAY_PIN);

    if (!red_relay_line || !green_relay_line || !blue_relay_line) {
        perror("Error getting GPIO line");
        return -1;
    }

    if (gpiod_line_request_output(red_relay_line, "lighting_system", 0) < 0 ||
        gpiod_line_request_output(green_relay_line, "lighting_system", 0) < 0 ||
        gpiod_line_request_output(blue_relay_line, "lighting_system", 0) < 0) {
        perror("Error requesting GPIO line for output");
        return -1;
    }

    return 0;
}

// Initialize I2C communication
int init_i2c(void) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    unsigned char config_cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &config_cmd, 1) != 1) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(int fd) {
    unsigned char buffer[2];
    int lux = -1; // Initialize to an error value

    // Wait for at least 120 ms for the first conversion
    usleep(120000);

    if (read(fd, buffer, 2) == 2) {
        lux = (buffer[0] << 8) | buffer[1];
        lux = lux / 1.2; // Apply lux calculation
    } else {
        perror("Error reading from I2C device");
    }

    return lux;
}

// Control relays based on lux value
void control_relays(int lux) {
    int red_state = 0, green_state = 0, blue_state = 0;

    if (lux < 50) {
        red_state = 1;
    } else if (lux >= 50 && lux < 150) {
        green_state = 1;
    } else if (lux >= 150 && lux < 300) {
        blue_state = 1;
    } else if (lux >= 300) {
        red_state = 1;
        green_state = 1;
        blue_state = 1;
    }

    if (red_relay_line) {
        gpiod_line_set_value(red_relay_line, red_state);
    }
    if (green_relay_line) {
        gpiod_line_set_value(green_relay_line, green_state);
    }
    if (blue_relay_line) {
        gpiod_line_set_value(blue_relay_line, blue_state);
    }
}

// Log data to file
void log_data(int lux, int red_state, int green_state, int blue_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d\n", timestamp, lux, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup(0); // Call cleanup before exiting
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup(0);
        return 1;
    }

    // Main loop
    while (1) {
        int lux = read_bh1750(i2c_fd);
        if (lux >= 0) {
            control_relays(lux);
            log_data(lux, gpiod_line_get_value(red_relay_line), gpiod_line_get_value(green_relay_line), gpiod_line_get_value(blue_relay_line));
        } else {
            fprintf(stderr, "Error reading lux value.\n");
        }

        sleep(1);
    }

    return 0;
}

