// Motor A GPIOs
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B GPIOs
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM Frequency
#define PWM_FREQUENCY 1000

// Distance thresholds
#define FORWARD_THRESHOLD 50
#define BACKWARD_THRESHOLD 100

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to set motor direction and PWM duty cycle
void set_motor_speed(int motor_num, int distance) {
    int in1_pin, in2_pin;
    int duty_cycle;

    if (motor_num == 1) {
        in1_pin = MOTOR_A_IN1;
        in2_pin = MOTOR_A_IN2;
    } else if (motor_num == 2) {
        in1_pin = MOTOR_B_IN3;
        in2_pin = MOTOR_B_IN4;
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor_num);
        return;
    }

    // Map distance to duty cycle (10-100 cm to 0-255)
    duty_cycle = 255 - ((distance - 10) * 255) / 90;
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;

    // Determine motor direction based on distance
    if (distance < FORWARD_THRESHOLD) {
        gpioWrite(in1_pin, 1);
        gpioPWM(in2_pin, duty_cycle);
    } else if (distance >= BACKWARD_THRESHOLD) {
        gpioWrite(in1_pin, 0);
        gpioPWM(in2_pin, duty_cycle);
    } else {
        gpioWrite(in1_pin, 0);
        gpioWrite(in2_pin, 0);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
