    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    // Main loop
    while (!terminate) {
        // Simulate distance readings (replace with actual sensor readings)
        int distance_a = 10 + (rand() % 91); // 10-100 cm
        int distance_b = 10 + (rand() % 91); // 10-100 cm

        // Set motor speeds
        set_motor_speed(1, distance_a);
        set_motor_speed(2, distance_b);

        // Delay
        gpioDelay(100000); // 100 ms
    }

    // Stop motors
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

