#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define PWR_MGMT_1 0x6B
#define SERVO_GPIO 18
#define PWM_CHIP 2
#define PWM_NUM 0
#define PWM_PERIOD 20000 // 50Hz
#define SERVO_MIN_PULSE 1000
#define SERVO_MAX_PULSE 2000
#define LOG_FILE "solar_tracker.log"
#define RETRY_DELAY_BASE_MS 10
#define MAX_RETRIES 5

// Global variables
static int i2c_fd = -1;
static int pwm_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c(void);
int init_mpu6050(void);
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
double calculate_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z);
double calculate_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z);
int set_servo_angle(double pitch);
int log_data(double pitch, double roll, int servo_pulse);
void signal_handler(int sig);
int init_pwm(void);
int enable_pwm(void);
int disable_pwm(void);
int set_pwm_duty_cycle(int pulse_width);

// I2C initialization function
int init_i2c(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// MPU6050 initialization function
int init_mpu6050(void) {
    uint8_t data = 0x00; // Wake up the MPU6050
    if (write(i2c_fd, &data, 1) != 1) {
        perror("Error writing to MPU6050");
        return -1;
    }
    return 0;
}

// Function to read raw sensor data from MPU6050
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buffer[14];
    if (read(i2c_fd, buffer, 14) != 14) {
        perror("Error reading from MPU6050");
        return -1;
    }

    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    *gyro_x = (int16_t)((buffer[8] << 8) | buffer[9]);
    *gyro_y = (int16_t)((buffer[10] << 8) | buffer[11]);
    *gyro_z = (int16_t)((buffer[12] << 8) | buffer[13]);

    return 0;
}

// Function to calculate pitch
double calculate_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    double pitch = atan2(accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;
    return pitch;
}

// Function to calculate roll
double calculate_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    double roll = atan2(accel_y, sqrt(accel_x * accel_x + accel_z * accel_z)) * 180 / M_PI;
    return roll;
}

// PWM initialization function
int init_pwm(void) {
    char path[64];
    int fd;

    // Export PWM channel
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        if (errno == EBUSY) {
            // Already exported, continue
        } else {
            perror("Error opening PWM export file");
            return -1;
        }
    } else {
        if (write(fd, "0", 1) != 1) {
            perror("Error writing to PWM export file");
            close(fd);
            return -1;
        }
        close(fd);
    }

    // Set PWM period
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening PWM period file");
        return -1;
    }
    if (dprintf(fd, "%d", PWM_PERIOD) < 0) {
        perror("Error writing to PWM period file");
        close(fd);
        return -1;
    }
    close(fd);

    return 0;
}

// Function to enable PWM
int enable_pwm(void) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening PWM enable file");
        return -1;
    }
    if (write(fd, "1", 1) != 1) {
        perror("Error writing to PWM enable file");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to disable PWM
int disable_pwm(void) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening PWM enable file");
        return -1;
    }
    if (write(fd, "0", 1) != 1) {
        perror("Error writing to PWM enable file");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to set PWM duty cycle
int set_pwm_duty_cycle(int pulse_width) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening PWM duty_cycle file");
        return -1;
    }
    if (dprintf(fd, "%d", pulse_width) < 0) {
        perror("Error writing to PWM duty_cycle file");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to set servo angle based on pitch
int set_servo_angle(double pitch) {
    // Map pitch to servo pulse width
    int pulse_width = (int)(((pitch + 90.0) / 180.0) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) + SERVO_MIN_PULSE);

    // Clamp pulse width to valid range
    if (pulse_width < SERVO_MIN_PULSE) {
        pulse_width = SERVO_MIN_PULSE;
    } else if (pulse_width > SERVO_MAX_PULSE) {
        pulse_width = SERVO_MAX_PULSE;
    }

    if (set_pwm_duty_cycle(pulse_width) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }

    return pulse_width;
}

// Function to log data to file
int log_data(double pitch, double roll, int servo_pulse) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_pulse);
    fflush(log_file);

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int main(void) {
    int retries = 0;
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    double pitch, roll;
    int servo_pulse;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    while (retries < MAX_RETRIES) {
        i2c_fd = init_i2c();
        if (i2c_fd < 0) {
            fprintf(stderr, "I2C initialization failed, retrying in %d ms...\n", RETRY_DELAY_BASE_MS << retries);
            usleep((RETRY_DELAY_BASE_MS << retries) * 1000); // Exponential backoff
            retries++;
        } else {
            break;
        }
    }
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed after %d retries. Exiting.\n", MAX_RETRIES);
        return EXIT_FAILURE;
    }

    // Initialize MPU6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU6050 initialization failed. Exiting.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize PWM
    if (init_pwm() != 0) {
        fprintf(stderr, "PWM initialization failed. Exiting.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Enable PWM
    if (enable_pwm() != 0) {
        fprintf(stderr, "Failed to enable PWM. Exiting.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Read sensor data
        if (read_mpu6050_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Calculate pitch and roll
            pitch = calculate_pitch(accel_x, accel_y, accel_z);
            roll = calculate_roll(accel_x, accel_y, accel_z);

            // Set servo angle
            servo_pulse = set_servo_angle(pitch);

            // Log data
            if (log_data(pitch, roll, servo_pulse) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        usleep(50000); // 50ms delay
    }

    // Cleanup
    disable_pwm();
    close(i2c_fd);
    if (log_file != NULL) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

