#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for relays
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define transition duration (seconds)
#define TRANSITION_DURATION 1800

// Define schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Structure to represent a schedule entry
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int state;
} schedule_entry_t;

// Global variables
static volatile int running = 1;
static FILE *schedule_file = NULL;

// Function prototypes
int initialize_gpio();
int read_schedule(schedule_entry_t *schedule, int *num_entries);
int parse_time(const char *time_str, int *hour, int *minute, int *second);
int set_relay_state(int relay_number, int state);
int fade_lamp(int relay_number, int target_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Turn off all relays
    set_relay_state(1, 0);
    set_relay_state(2, 0);
    set_relay_state(3, 0);
    set_relay_state(4, 0);

    // Close the schedule file if it's open
    if (schedule_file != NULL) {
        fclose(schedule_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    gpioSetPWMfrequency(RELAY1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_GPIO, PWM_FREQUENCY);

    return 0;
}

// Read schedule from file
int read_schedule(schedule_entry_t *schedule, int *num_entries) {
    char line[256];
    int i = 0;

    schedule_file = fopen(SCHEDULE_FILE, "r");
    if (schedule_file == NULL) {
        perror("Error opening schedule file");
        return 1;
    }

    while (fgets(line, sizeof(line), schedule_file) != NULL) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Parse the line
        char *time_str = strtok(line, ",");
        char *relay_str = strtok(NULL, ",");
        char *state_str = strtok(NULL, ",");

        if (time_str == NULL || relay_str == NULL || state_str == NULL) {
            fprintf(stderr, "Invalid schedule entry: %s\n", line);
            continue;
        }

        if (parse_time(time_str, &schedule[i].hour, &schedule[i].minute, &schedule[i].second) != 0) {
            fprintf(stderr, "Invalid time format: %s\n", time_str);
            continue;
        }

        schedule[i].relay_number = atoi(relay_str);
        if (strcmp(state_str, "on") == 0) {
            schedule[i].state = 1;
        } else if (strcmp(state_str, "off") == 0) {
            schedule[i].state = 0;
        } else {
            fprintf(stderr, "Invalid state: %s\n", state_str);
            continue;
        }

        i++;
        if (i >= 100) { // Limit the number of entries to prevent buffer overflow
            fprintf(stderr, "Too many schedule entries, ignoring the rest.\n");
            break;
        }
    }

    *num_entries = i;
    fclose(schedule_file);
    schedule_file = NULL; // Reset schedule_file after closing
    return 0;
}

// Parse time string
int parse_time(const char *time_str, int *hour, int *minute, int *second) {
    if (sscanf(time_str, "%d:%d:%d", hour, minute, second) != 3) {
        return 1;
    }
    return 0;
}

// Set relay state
int set_relay_state(int relay_number, int state) {
    int gpio_pin;

    switch (relay_number) {
        case 1:
            gpio_pin = RELAY1_GPIO;
            break;
        case 2:
            gpio_pin = RELAY2_GPIO;
            break;
        case 3:
            gpio_pin = RELAY3_GPIO;
            break;
        case 4:
            gpio_pin = RELAY4_GPIO;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return 1;
    }

    gpioWrite(gpio_pin, state);
    return 0;
}

// Fade lamp brightness using PWM
int fade_lamp(int relay_number, int target_state) {
    int gpio_pin;
    int current_duty = 0;
    int target_duty;
    int increment;
    int i;

    switch (relay_number) {
        case 1:
            gpio_pin = RELAY1_GPIO;
            break;
        case 2:
            gpio_pin = RELAY2_GPIO;
            break;
        case 3:
            gpio_pin = RELAY3_GPIO;
            break;
        case 4:
            gpio_pin = RELAY4_GPIO;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return 1;
    }

    if (target_state == 1) {
        target_duty = 100;
        increment = 1;
    } else {
        target_duty = 0;
        increment = -1;
    }

    for (i = 0; i <= TRANSITION_DURATION; i++) {
        if (!running) return 0; // Exit if signal received
        gpioPWM(gpio_pin, current_duty);
        current_duty += increment;
        if (current_duty < 0) current_duty = 0;
        if (current_duty > 100) current_duty = 100;
        gpioDelay(1000000 / PWM_FREQUENCY); // Delay to achieve desired frequency
    }

    gpioPWM(gpio_pin, target_duty); // Ensure final state is set
    return 0;
}

int main() {
    schedule_entry_t schedule[100];
    int num_entries = 0;
    time_t current_time;
    struct tm *time_info;
    int current_hour, current_minute, current_second;
    int i;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Read schedule
    if (read_schedule(schedule, &num_entries) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Smart Home Lighting System started.\n");

    while (running) {
        // Get current time
        current_time = time(NULL);
        time_info = localtime(&current_time);
        current_hour = time_info->tm_hour;
        current_minute = time_info->tm_min;
        current_second = time_info->tm_sec;

        // Check schedule
        for (i = 0; i < num_entries; i++) {
            if (schedule[i].hour == current_hour &&
                schedule[i].minute == current_minute &&
                schedule[i].second == current_second) {
                printf("Time match: Relay %d, State %s\n", schedule[i].relay_number, schedule[i].state ? "on" : "off");
                fade_lamp(schedule[i].relay_number, schedule[i].state);
            }
        }

        gpioDelay(1000); // Check every second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    return 0;
}

