// Function prototypes
void triggerSensor();
float getDistance();
float mapDistanceToFrequency(float distance);
void setBuzzerFrequency(float frequency);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    setBuzzerFrequency(0); // Silence the buzzer
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
float getDistance() {
    long long start_tick, end_tick, diff_tick;

    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);

    // Trigger the sensor
    triggerSensor();

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) {
        gpioDelay(1); // Wait 1 microsecond
        count++;
    }

    if (count >= 10000) {
        fprintf(stderr, "Error: Echo pin did not go high (timeout).\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 10000) {
        gpioDelay(1); // Wait 1 microsecond
        count++;
    }

    if (count >= 10000) {
        fprintf(stderr, "Error: Echo pin did not go low (timeout).\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate the distance in centimeters (speed of sound: 343 m/s)
    // distance = (time * speed of sound) / 2
    // distance = (diff_tick * 0.000001 * 34300) / 2
    // Simplified: distance = (diff_tick * 0.00001715)
    float distance = (float)diff_tick * 0.00001715;

    return distance;
}

// Function to map the distance to a frequency
float mapDistanceToFrequency(float distance) {
    float frequency;

    // Clamp the distance to the defined range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Linear mapping
    frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);

    return frequency;
}

// Function to set the buzzer frequency
void setBuzzerFrequency(float frequency) {
    if (frequency > 0) {
        gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);
        gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
    } else {
        gpioPWM(BUZZER_PIN, 0); // Silence the buzzer
    }
}

