    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(BUZZER_PIN, 255);

    // Set PWM frequency (initial value)
    gpioSetPWMfrequency(BUZZER_PIN, MIN_FREQUENCY);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Theremin running. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        float distance = getDistance();

        if (distance > 0) {
            float frequency = mapDistanceToFrequency(distance);
            setBuzzerFrequency(frequency);
            printf("Distance: %.2f cm, Frequency: %.0f Hz\n", distance, frequency);
        } else {
            fprintf(stderr, "Error: Invalid distance reading.\n");
            setBuzzerFrequency(0); // Silence the buzzer on error
        }

        gpioDelay(MEASUREMENT_INTERVAL * 1000); // Delay for 60 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    setBuzzerFrequency(0);
    gpioTerminate();

    return 0;
}

