#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to simulate proximity value (sine wave)
float simulate_proximity() {
    static float time = 0.0;
    float proximity = 0.5 + 0.5 * sin(time);
    time += 0.01; // Increment time for sine wave
    return proximity;
}

// Function to map proximity value to RGB color
void proximity_to_color(float proximity, int *red, int *green, int *blue) {
    // Map proximity (0.0 to 1.0) to color (Red -> Green -> Blue -> Red)
    if (proximity < 0.33) {
        // Red to Green
        *red = 255 - (int)(255 * proximity / 0.33);
        *green = (int)(255 * proximity / 0.33);
        *blue = 0;
    } else if (proximity < 0.66) {
        // Green to Blue
        *red = 0;
        *green = 255 - (int)(255 * (proximity - 0.33) / 0.33);
        *blue = (int)(255 * (proximity - 0.33) / 0.33);
    } else {
        // Blue to Red
        *red = (int)(255 * (proximity - 0.66) / 0.34);
        *green = 0;
        *blue = 255 - (int)(255 * (proximity - 0.66) / 0.34);
    }
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency to 1 kHz
    gpioSetPWMfrequency(RED_PIN, 1000);
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    // Main loop
    while (program_running) {
        // Simulate proximity value
        float proximity = simulate_proximity();

        // Map proximity to RGB color
        int red, green, blue;
        proximity_to_color(proximity, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Delay for a short period
        gpioDelay(10000); // 10ms
    }

    // Turn off LED
    set_led_color(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

