#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Sensitivity scale factor
#define GYRO_SCALE 131.0

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int read_register(int fd, uint8_t reg) {
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a block of data from the I2C device
int read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to convert raw gyroscope data to degrees per second
float convert_to_degrees_per_second(int16_t raw_data) {
    return (float)raw_data / GYRO_SCALE;
}

// Function to log the gyroscope data to a file
int log_data(float x, float y, float z) {
    FILE *fp = fopen("gyro_log.txt", "a");
    if (fp == NULL) {
        perror("Failed to open gyro_log.txt");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f, %.2f, %.2f\n", timestamp, x, y, z);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Wake up the MPU-6050
    if (write_register(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU-6050\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        uint8_t gyro_data[6];

        // Read gyroscope data
        if (read_block(i2c_fd, GYRO_XOUT_H, gyro_data, 6) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            close(i2c_fd);
            return 1;
        }

        // Combine high and low bytes for each axis
        int16_t gyro_x_raw = (gyro_data[0] << 8) | gyro_data[1];
        int16_t gyro_y_raw = (gyro_data[2] << 8) | gyro_data[3];
        int16_t gyro_z_raw = (gyro_data[4] << 8) | gyro_data[5];

        // Convert to degrees per second
        float gyro_x = convert_to_degrees_per_second(gyro_x_raw);
        float gyro_y = convert_to_degrees_per_second(gyro_y_raw);
        float gyro_z = convert_to_degrees_per_second(gyro_z_raw);

        // Log the data
        if (log_data(gyro_x, gyro_y, gyro_z) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait 100 milliseconds
        usleep(100000);
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    close(i2c_fd);
    return 0;
}

