#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define DEFAULT_POLL_TIMEOUT_MS 1000
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5

// Structure to hold event data
typedef struct {
    struct timespec timestamp;
    int value;
} Event;

// Global variables
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static int poll_timeout_ms = DEFAULT_POLL_TIMEOUT_MS;
static volatile sig_atomic_t terminate = 0;

// Circular buffer for event history
Event event_history[WINDOW_SIZE];
int history_index = 0;
int history_count = 0;

// Function prototypes
int init_gpio(int pin);
int read_sensor(struct gpiod_line *line);
void log_event(FILE *fp, struct timespec timestamp, int value);
void check_earthquake(int value);
void signal_handler(int sig);
void cleanup();

// Function to initialize GPIO using libgpiod
int init_gpio(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line_tmp;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line_tmp = gpiod_chip_get_line(chip, pin);
    if (!line_tmp) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(line_tmp, "vibration_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line_tmp);
        return -1;
    }

    gpiod_chip_close(chip);
    line = line_tmp; // Store the line pointer
    return 0;
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to log an event to the file
void log_event(FILE *fp, struct timespec timestamp, int value) {
    char timestamp_str[32];
    struct tm tm_info;

    localtime_r(&timestamp.tv_sec, &tm_info);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(fp, "%s.%09ld,%d\n", timestamp_str, timestamp.tv_nsec, value);
    fflush(fp);
}

// Function to check for earthquake conditions
void check_earthquake(int value) {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);

    // Update circular buffer
    event_history[history_index].timestamp = now;
    event_history[history_index].value = value;
    history_index = (history_index + 1) % WINDOW_SIZE;
    if (history_count < WINDOW_SIZE) {
        history_count++;
    }

    // Count HIGH values in the window
    int high_count = 0;
    for (int i = 0; i < history_count; i++) {
        if (event_history[i].value == 1) {
            high_count++;
        }
    }

    // Check for earthquake condition
    if (high_count >= 3) {
        printf("EARTHQUAKE ALERT!\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    struct timespec timeout;
    struct timespec last_event_time;
    int last_value = -1; // Initialize to an invalid value
    int current_value;

    // Parse command-line arguments
    if (argc > 1) {
        poll_timeout_ms = atoi(argv[1]);
        if (poll_timeout_ms <= 0) {
            fprintf(stderr, "Invalid poll timeout value. Using default: %d ms\n", DEFAULT_POLL_TIMEOUT_MS);
            poll_timeout_ms = DEFAULT_POLL_TIMEOUT_MS;
        }
    }

    // Initialize GPIO
    if (init_gpio(GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    timeout.tv_sec = 0;
    timeout.tv_nsec = poll_timeout_ms * 1000000; // Convert milliseconds to nanoseconds
    clock_gettime(CLOCK_REALTIME, &last_event_time);

    while (!terminate) {
        current_value = read_sensor(line);
        if (current_value < 0) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);

        // Check for rising edge
        if (current_value == 1 && last_value == 0) {
            log_event(log_file, now, current_value);
            check_earthquake(current_value);
            last_event_time = now;
        }

        // Check for falling edge
        if (current_value == 0 && last_value == 1) {
            log_event(log_file, now, current_value);
            check_earthquake(current_value);
            last_event_time = now;
        }

        last_value = current_value;

        // Sleep for the remaining time in the poll timeout
        struct timespec remaining_time;
        long remaining_nsec = (timeout.tv_nsec - (now.tv_nsec - last_event_time.tv_nsec));
        if (remaining_nsec < 0) {
            remaining_nsec += 1000000000L; // Add 1 second
            timeout.tv_sec--;
        }
        remaining_time.tv_sec = timeout.tv_sec;
        remaining_time.tv_nsec = remaining_nsec;

        if (remaining_time.tv_sec >= 0 || remaining_time.tv_nsec > 0) {
            nanosleep(&remaining_time, NULL);
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

