#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MAG_ADDR 0x1E
#define MR_REG_M 0x02
#define CRA_REG_M 0x00
#define OUT_X_H_M 0x03
#define X_OFFSET 10.0f
#define Y_OFFSET -5.0f
#define Z_OFFSET 20.0f
#define CSV_FILE "mag_log.csv"

// Global variables
static int i2c_fd = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_setup(const char *bus, int addr);
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int16_t read_mag_axis(int fd, uint8_t msb_reg);
float calibrate_axis(int16_t raw_value, float offset);
float calculate_heading(float x, float y);
char *map_heading_to_direction(float heading);
int log_data(FILE *fp, float x, float y, float z, float heading, char *direction);
void signal_handler(int sig);

// I2C setup function
int i2c_setup(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Read magnetometer axis data function
int16_t read_mag_axis(int fd, uint8_t msb_reg) {
    int msb = i2c_read_reg(fd, msb_reg);
    int lsb = i2c_read_reg(fd, msb_reg + 1);

    if (msb < 0 || lsb < 0) {
        return 0; // Return 0 on error
    }

    return (int16_t)((msb << 8) | lsb);
}

// Calibrate axis function
float calibrate_axis(int16_t raw_value, float offset) {
    return (float)raw_value - offset;
}

// Calculate heading function
float calculate_heading(float x, float y) {
    float heading = atan2f(y, x) * 180.0f / M_PI;
    if (heading < 0) {
        heading += 360.0f;
    }
    return heading;
}

// Map heading to direction function
char *map_heading_to_direction(float heading) {
    if (heading >= 337.5 || heading < 22.5) return "N";
    if (heading >= 22.5 && heading < 67.5) return "NE";
    if (heading >= 67.5 && heading < 112.5) return "E";
    if (heading >= 112.5 && heading < 157.5) return "SE";
    if (heading >= 157.5 && heading < 202.5) return "S";
    if (heading >= 202.5 && heading < 247.5) return "SW";
    if (heading >= 247.5 && heading < 292.5) return "W";
    if (heading >= 292.5 && heading < 337.5) return "NW";
    return "N"; // Should never reach here
}

// Log data to CSV file function
int log_data(FILE *fp, float x, float y, float z, float heading, char *direction) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f,%s\n", timestamp, x, y, z, heading, direction) < 0) {
        perror("Error writing to CSV file");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // I2C setup
    i2c_fd = i2c_setup(I2C_BUS, MAG_ADDR);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Configure magnetometer
    if (i2c_write_reg(i2c_fd, MR_REG_M, 0x00) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (i2c_write_reg(i2c_fd, CRA_REG_M, 0x14) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write CSV header if the file is new
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n");
    }
    rewind(csv_file);

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        int16_t raw_x = read_mag_axis(i2c_fd, OUT_X_H_M);
        int16_t raw_z = read_mag_axis(i2c_fd, 0x05);
        int16_t raw_y = read_mag_axis(i2c_fd, 0x07);

        // Calibrate data
        float x = calibrate_axis(raw_x, X_OFFSET);
        float y = calibrate_axis(raw_y, Y_OFFSET);
        float z = calibrate_axis(raw_z, Z_OFFSET);

        // Calculate heading
        float heading = calculate_heading(x, y);

        // Map heading to direction
        char *direction = map_heading_to_direction(heading);

        // Log data
        if (log_data(csv_file, x, y, z, heading, direction) < 0) {
            terminate = 1; // Stop on error
        }

        fflush(csv_file); // Flush the buffer to ensure data is written

        // Print to console
        printf("X: %.2f, Y: %.2f, Z: %.2f, Heading: %.2f, Direction: %s\n", x, y, z, heading, direction);

        sleep(1); // Wait for 1 second
    }

    // Cleanup
    close(i2c_fd);
    if (csv_file != NULL) {
        fclose(csv_file);
    }

    return EXIT_SUCCESS;
}

