    if (heading >= 22.5 && heading < 67.5) return "NE";
    if (heading >= 67.5 && heading < 112.5) return "E";
    if (heading >= 112.5 && heading < 157.5) return "SE";
    if (heading >= 157.5 && heading < 202.5) return "S";
    if (heading >= 202.5 && heading < 247.5) return "SW";
    if (heading >= 247.5 && heading < 292.5) return "W";
    if (heading >= 292.5 && heading < 337.5) return "NW";
    return "N"; // Should never reach here
}

// Log data to CSV file function
int log_data(FILE *fp, float x, float y, float z, float heading, char *direction) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f,%s\n", timestamp, x, y, z, heading, direction) < 0) {
        perror("Error writing to CSV file");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // I2C setup
    i2c_fd = i2c_setup(I2C_BUS, MAG_ADDR);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Configure magnetometer
    if (i2c_write_reg(i2c_fd, MR_REG_M, 0x00) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (i2c_write_reg(i2c_fd, CRA_REG_M, 0x14) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write CSV header if the file is new
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n");
    }
    rewind(csv_file);

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        int16_t raw_x = read_mag_axis(i2c_fd, OUT_X_H_M);
        int16_t raw_z = read_mag_axis(i2c_fd, 0x05);
        int16_t raw_y = read_mag_axis(i2c_fd, 0x07);

        // Calibrate data
        float x = calibrate_axis(raw_x, X_OFFSET);
        float y = calibrate_axis(raw_y, Y_OFFSET);
        float z = calibrate_axis(raw_z, Z_OFFSET);

        // Calculate heading
        float heading = calculate_heading(x, y);

        // Map heading to direction
        char *direction = map_heading_to_direction(heading);

        // Log data
        if (log_data(csv_file, x, y, z, heading, direction) < 0) {
            terminate = 1; // Stop on error
        }

        fflush(csv_file); // Flush the buffer to ensure data is written

        // Print to console
        printf("X: %.2f, Y: %.2f, Z: %.2f, Heading: %.2f, Direction: %s\n", x, y, z, heading, direction);

        sleep(1); // Wait for 1 second
    }

    // Cleanup
    close(i2c_fd);
    if (csv_file != NULL) {
        fclose(csv_file);
    }

    return EXIT_SUCCESS;
}

