#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile unsigned int last_touch_time = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
int initialize_gpio();
void touch_callback(int gpio, int level, unsigned int tick, void *user_data);
int toggle_relay();
int log_relay_state();
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int relay_state;
    unsigned int last_touch_time;
} ProgramState;

ProgramState state;

int main() {
    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("relay_log.json", "a");
    if (log_file == NULL) {
        perror("Failed to open relay_log.json");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Do other tasks here, if needed
        sleep(1); // Reduce CPU usage
    }

    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input with pull-down resistor
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Set GPIO17 as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set up interrupt on GPIO4
    if (gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Touch sensor callback function
void touch_callback(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned int current_time = gpioTick();

    // Debounce the touch
    if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) {
        // Toggle the relay state
        if (toggle_relay() != 0) {
            fprintf(stderr, "Failed to toggle relay\n");
        }

        // Log the relay state
        if (log_relay_state() != 0) {
            fprintf(stderr, "Failed to log relay state\n");
        }

        // Update the last touch time
        last_touch_time = current_time;
    }
}

// Toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    return 0;
}

// Log the relay state to relay_log.json
int log_relay_state() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to the file immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Shutting down...\n");
    running = 0;

    // Turn off the relay
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;

    // Log the final relay state
    log_relay_state();

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

