#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay1_line = NULL;
static struct gpiod_line *relay2_line = NULL;
static struct gpiod_line *relay3_line = NULL;
static struct gpiod_line *relay4_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int generate_moisture_value();
int activate_relay(int relay_number, int moisture_level);
int deactivate_relay(int relay_number);
int log_event(int relay_number, int moisture_level);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Initialize GPIO lines
int initialize_gpio() {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the GPIO lines
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        perror("Error getting GPIO line");
        cleanup();
        return -1;
    }

    // Request the GPIO lines as outputs
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "irrigation_system";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(relay1_line, &config, 1);
    if (ret < 0) {
        perror("Error requesting GPIO line 1");
        cleanup();
        return -1;
    }

    ret = gpiod_line_request(relay2_line, &config, 1);
    if (ret < 0) {
        perror("Error requesting GPIO line 2");
        cleanup();
        return -1;
    }

    ret = gpiod_line_request(relay3_line, &config, 1);
    if (ret < 0) {
        perror("Error requesting GPIO line 3");
        cleanup();
        return -1;
    }

    ret = gpiod_line_request(relay4_line, &config, 1);
    if (ret < 0) {
        perror("Error requesting GPIO line 4");
        cleanup();
        return -1;
    }

    return 0;
}

// Generate a random soil moisture value
int generate_moisture_value() {
    return rand() % 101;
}

// Activate a relay for 5 seconds
int activate_relay(int relay_number, int moisture_level) {
    int ret;
    struct gpiod_line *line;

    switch (relay_number) {
        case 1:
            line = relay1_line;
            break;
        case 2:
            line = relay2_line;
            break;
        case 3:
            line = relay3_line;
            break;
        case 4:
            line = relay4_line;
            break;
        default:
            fprintf(stderr, "Error: Invalid relay number: %d\n", relay_number);
            return -1;
    }

    ret = gpiod_line_set_value(line, 0); // Activate the relay (active-low)
    if (ret < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }

    log_event(relay_number, moisture_level);
    sleep(5);

    return 0;
}

// Deactivate a relay
int deactivate_relay(int relay_number) {
    int ret;
    struct gpiod_line *line;

    switch (relay_number) {
        case 1:
            line = relay1_line;
            break;
        case 2:
            line = relay2_line;
            break;
        case 3:
            line = relay3_line;
            break;
        case 4:
            line = relay4_line;
            break;
        default:
            fprintf(stderr, "Error: Invalid relay number: %d\n", relay_number);
            return -1;
    }

    ret = gpiod_line_set_value(line, 1); // Deactivate the relay
    if (ret < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }

    return 0;
}

// Log an event to the log file
int log_event(int relay_number, int moisture_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, Relay %d, Moisture Level: %d\n", timestamp, relay_number, moisture_level);
    fflush(log_file);

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    int ret;

    // Deactivate all relays
    if (relay1_line) {
        ret = gpiod_line_set_value(relay1_line, 1);
        if (ret < 0) {
            perror("Error deactivating relay 1");
        }
    }
    if (relay2_line) {
        ret = gpiod_line_set_value(relay2_line, 1);
        if (ret < 0) {
            perror("Error deactivating relay 2");
        }
    }
    if (relay3_line) {
        ret = gpiod_line_set_value(relay3_line, 1);
        if (ret < 0) {
            perror("Error deactivating relay 3");
        }
    }
    if (relay4_line) {
        ret = gpiod_line_set_value(relay4_line, 1);
        if (ret < 0) {
            perror("Error deactivating relay 4");
        }
    }

    // Release GPIO lines
    if (relay1_line) {
        gpiod_line_release(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_release(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_release(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_release(relay4_line);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close the log file
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    int moisture_level;
    int i;

    // Seed the random number generator
    srand(time(NULL));

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        moisture_level = generate_moisture_value();

        if (moisture_level < 30) {
            for (i = 1; i <= 4; i++) {
                if (activate_relay(i, moisture_level) < 0) {
                    fprintf(stderr, "Error activating relay %d. Continuing.\n", i);
                }
                if (deactivate_relay(i) < 0) {
                    fprintf(stderr, "Error deactivating relay %d. Continuing.\n", i);
                }
                sleep(1);
            }
        }

        sleep(10);
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

