        if (ret < 0) {
            perror("Error deactivating relay 1");
        }
    }
    if (relay2_line) {
        ret = gpiod_line_set_value(relay2_line, 1);
        if (ret < 0) {
            perror("Error deactivating relay 2");
        }
    }
    if (relay3_line) {
        ret = gpiod_line_set_value(relay3_line, 1);
        if (ret < 0) {
            perror("Error deactivating relay 3");
        }
    }
    if (relay4_line) {
        ret = gpiod_line_set_value(relay4_line, 1);
        if (ret < 0) {
            perror("Error deactivating relay 4");
        }
    }

    // Release GPIO lines
    if (relay1_line) {
        gpiod_line_release(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_release(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_release(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_release(relay4_line);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close the log file
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    int moisture_level;
    int i;

    // Seed the random number generator
    srand(time(NULL));

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        moisture_level = generate_moisture_value();

        if (moisture_level < 30) {
            for (i = 1; i <= 4; i++) {
                if (activate_relay(i, moisture_level) < 0) {
                    fprintf(stderr, "Error activating relay %d. Continuing.\n", i);
                }
                if (deactivate_relay(i) < 0) {
                    fprintf(stderr, "Error deactivating relay %d. Continuing.\n", i);
                }
                sleep(1);
            }
        }

        sleep(10);
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

