#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins for servos
#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

// Define moisture thresholds
#define WATERING_THRESHOLD 50
#define MOISTURE_READINGS_COUNT 5

// Define servo pulse width ranges
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define watering sequence parameters
#define WATERING_DURATION 5 // seconds
#define NOZZLE_SWEEP_DURATION 2 // seconds
#define NOZZLE_SWEEP_STEPS 5

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to set servo pulse width with retry
int set_servo_pulse_width(int gpio, int pulse_width) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = gpioServo(gpio, pulse_width);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error setting servo pulse width on GPIO %d to %d: %d. Retrying...\n", gpio, pulse_width, result);
            gpioDelay(100); // 100 ms backoff
            retries--;
        }
    }
    fprintf(stderr, "Failed to set servo pulse width on GPIO %d to %d after multiple retries.\n", gpio, pulse_width);
    return -1; // Failure
}

// Function to open the water valve
int open_valve() {
    return set_servo_pulse_width(VALVE_SERVO_PIN, SERVO_MAX_PULSE_WIDTH);
}

// Function to close the water valve
int close_valve() {
    return set_servo_pulse_width(VALVE_SERVO_PIN, SERVO_MIN_PULSE_WIDTH);
}

// Function to set the nozzle angle
int set_nozzle_angle(int angle) {
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    return set_servo_pulse_width(NOZZLE_SERVO_PIN, pulse_width);
}

// Function to simulate soil moisture readings
int simulate_moisture_readings() {
    static int moisture_readings[MOISTURE_READINGS_COUNT] = {20, 40, 60, 80, 100};
    static int index = 0;
    int reading = moisture_readings[index];
    index = (index + 1) % MOISTURE_READINGS_COUNT;
    return reading;
}

// Function to perform watering cycle
void perform_watering_cycle() {
    printf("Performing watering cycle...\n");
    if (open_valve() != 0) {
        fprintf(stderr, "Critical error: Failed to open valve. Aborting watering cycle.\n");
        return;
    }

    for (int i = 0; i < NOZZLE_SWEEP_STEPS; i++) {
        int angle = i * 180 / (NOZZLE_SWEEP_STEPS - 1);
        if (set_nozzle_angle(angle) != 0) {
            fprintf(stderr, "Error setting nozzle angle to %d degrees. Continuing to next angle.\n", angle);
        }
        gpioDelay(NOZZLE_SWEEP_DURATION * 1000 / NOZZLE_SWEEP_STEPS); // Delay for each step
    }

    gpioDelay(WATERING_DURATION * 1000); // Hold for watering duration

    if (close_valve() != 0) {
        fprintf(stderr, "Warning: Failed to close valve.\n");
    }

    printf("Watering cycle complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    printf("Automated Plant Watering System started.\n");

    while (!terminate) {
        // Simulate soil moisture reading
        int moisture_level = simulate_moisture_readings();
        printf("Simulated moisture level: %d\n", moisture_level);

        // Check if watering is needed
        if (moisture_level < WATERING_THRESHOLD) {
            perform_watering_cycle();
        } else {
            printf("Moisture level is sufficient (%d >= %d). Skipping watering.\n", moisture_level, WATERING_THRESHOLD);
        }

        // Wait before next cycle
        gpioDelay(5000); // 5 seconds
    }

    // Stop servos and terminate pigpio
    printf("Stopping servos and terminating pigpio...\n");
    set_servo_pulse_width(VALVE_SERVO_PIN, 0);
    set_servo_pulse_width(NOZZLE_SERVO_PIN, 0);
    gpioTerminate();

    printf("Automated Plant Watering System terminated.\n");
    return 0;
}

