#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Gyroscope sensitivity (±250 deg/sec)
#define GYRO_SENSITIVITY 131.0

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int wake_sensor(int fd);
int read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void convert_to_degrees(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *x_dps, float *y_dps, float *z_dps);
void log_data(FILE *fp, float x_dps, float y_dps, float z_dps);
void signal_handler(int signum);

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Wake the sensor function
int wake_sensor(int fd) {
    return i2c_write_byte(fd, PWR_MGMT_1, 0x00);
}

// Read gyroscope data function
int read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t data[6];
    if (i2c_read_bytes(fd, GYRO_XOUT_H, data, 6) != 0) {
        return -1;
    }

    *gyro_x = (int16_t)((data[0] << 8) | data[1]);
    *gyro_y = (int16_t)((data[2] << 8) | data[3]);
    *gyro_z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Convert raw data to degrees/second
void convert_to_degrees(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)gyro_x / GYRO_SENSITIVITY;
    *y_dps = (float)gyro_y / GYRO_SENSITIVITY;
    *z_dps = (float)gyro_z / GYRO_SENSITIVITY;
}

// Log data to file function
void log_data(FILE *fp, float x_dps, float y_dps, float z_dps) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x_dps, y_dps, z_dps);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        exit(0);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Wake the sensor
    if (wake_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Failed to wake sensor\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    int16_t gyro_x, gyro_y, gyro_z;
    float x_dps, y_dps, z_dps;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100 ms (10 Hz)

    while (1) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Convert to degrees/second
            convert_to_degrees(gyro_x, gyro_y, gyro_z, &x_dps, &y_dps, &z_dps);

            // Log data
            log_data(log_file, x_dps, y_dps, z_dps);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        // Sleep for 100 ms
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

