#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_RELAY 18
#define DISTANCE_THRESHOLD 50 // cm
#define I2C_RETRY_COUNT 3

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0080
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0091
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle, int *distance);
void gpio_set_relay_state(int gpio_pin, int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// VL53L1X initialization function
int vl53l1x_init(int i2c_handle) {
    int status;
    uint8_t model_id, revision_id;

    // Check sensor ID
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }
    model_id = (uint8_t)status;

    status = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_REVISION_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading revision ID: %s\n", strerror(errno));
        return -1;
    }
    revision_id = (uint8_t)status;

    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid sensor ID. Expected 0xEA, got 0x%02X\n", model_id);
        return -1;
    }

    // Software reset (register 0x0000 = 0x00)
    status = i2cWriteByteData(i2c_handle, 0x0000, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x0000: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Initialise sensor (set ranging mode and start continuous ranging)
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x0080: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance(int i2c_handle, int *distance) {
    int status;
    uint8_t range_status;
    uint8_t msb, lsb;
    int retry = 0;

    // Check for data ready (register 0x0044)
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error reading interrupt status: %s\n", strerror(errno));
        return -1;
    }

    range_status = (uint8_t)status;

    if (!(range_status & 0x04)) {
        // Data not ready
        return -1;
    }

    // Read distance (register 0x0096 (MSB) and 0x0097 (LSB))
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (status < 0) {
        fprintf(stderr, "Error reading MSB: %s\n", strerror(errno));
        return -1;
    }
    msb = (uint8_t)status;

    status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1);
    if (status < 0) {
        fprintf(stderr, "Error reading LSB: %s\n", strerror(errno));
        return -1;
    }
    lsb = (uint8_t)status;

    *distance = (msb << 8) | lsb;

    return 0;
}

// GPIO relay control function
void gpio_set_relay_state(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

int main() {
    int distance;
    int init_result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    init_result = vl53l1x_init(i2c_handle);
    if (init_result != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
            printf("Distance: %d mm\n", distance);

            if (distance <= DISTANCE_THRESHOLD * 10) { // Convert cm to mm
                gpio_set_relay_state(GPIO_RELAY, 1); // Open door
            } else {
                gpio_set_relay_state(GPIO_RELAY, 0); // Close door
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Cleanup
    gpio_set_relay_state(GPIO_RELAY, 0); // Ensure relay is off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

