#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define watering interval (seconds)
#define WATERING_INTERVAL 86400

// Define watering duration (seconds)
#define WATERING_DURATION 5

// Define polling interval (seconds)
#define POLLING_INTERVAL 60

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *relay1_line, *relay2_line, *relay3_line, *relay4_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
void cleanup_gpio(void);
void activate_relay(int pin);
void deactivate_relay(int pin);
void log_watering_event(int pin);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig)
{
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", sig);
}

// Initialize GPIO lines
int initialize_gpio(void)
{
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get line handles
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        perror("Error getting line handle");
        cleanup_gpio();
        return -1;
    }

    // Request lines as output, active-low
    ret = gpiod_line_request_output(relay1_line, "watering", 1);
    if (ret < 0) {
        perror("Error requesting relay 1 line");
        cleanup_gpio();
        return -1;
    }
    ret = gpiod_line_request_output(relay2_line, "watering", 1);
    if (ret < 0) {
        perror("Error requesting relay 2 line");
        cleanup_gpio();
        return -1;
    }
    ret = gpiod_line_request_output(relay3_line, "watering", 1);
    if (ret < 0) {
        perror("Error requesting relay 3 line");
        cleanup_gpio();
        return -1;
    }
    ret = gpiod_line_request_output(relay4_line, "watering", 1);
    if (ret < 0) {
        perror("Error requesting relay 4 line");
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Cleanup GPIO lines
void cleanup_gpio(void)
{
    if (relay1_line) {
        gpiod_line_release(relay1_line);
        relay1_line = NULL;
    }
    if (relay2_line) {
        gpiod_line_release(relay2_line);
        relay2_line = NULL;
    }
    if (relay3_line) {
        gpiod_line_release(relay3_line);
        relay3_line = NULL;
    }
    if (relay4_line) {
        gpiod_line_release(relay4_line);
        relay4_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

// Activate a relay
void activate_relay(int pin)
{
    int ret;
    struct gpiod_line *line;

    switch (pin) {
        case RELAY1_PIN:
            line = relay1_line;
            break;
        case RELAY2_PIN:
            line = relay2_line;
            break;
        case RELAY3_PIN:
            line = relay3_line;
            break;
        case RELAY4_PIN:
            line = relay4_line;
            break;
        default:
            fprintf(stderr, "Invalid pin number: %d\n", pin);
            return;
    }

    ret = gpiod_line_set_value(line, 0); // Active-low
    if (ret < 0) {
        perror("Error setting relay value");
    }
}

// Deactivate a relay
void deactivate_relay(int pin)
{
    int ret;
    struct gpiod_line *line;

    switch (pin) {
        case RELAY1_PIN:
            line = relay1_line;
            break;
        case RELAY2_PIN:
            line = relay2_line;
            break;
        case RELAY3_PIN:
            line = relay3_line;
            break;
        case RELAY4_PIN:
            line = relay4_line;
            break;
        default:
            fprintf(stderr, "Invalid pin number: %d\n", pin);
            return;
    }

    ret = gpiod_line_set_value(line, 1); // Active-low
    if (ret < 0) {
        perror("Error setting relay value");
    }
}

// Log watering event
void log_watering_event(int pin)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Relay %d activated for %d seconds\n", timestamp, pin, WATERING_DURATION);
    fflush(log_file);
}

int main(void)
{
    time_t last_watering_time = 0;
    time_t current_time;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("watering_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fclose(log_file);
        return EXIT_FAILURE;
    }

    printf("Watering system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        time(&current_time);

        // Check if it's time for watering
        if (difftime(current_time, last_watering_time) >= WATERING_INTERVAL) {
            // Watering cycle
            printf("Starting watering cycle...\n");

            activate_relay(RELAY1_PIN);
            log_watering_event(RELAY1_PIN);
            sleep(WATERING_DURATION);
            deactivate_relay(RELAY1_PIN);

            activate_relay(RELAY2_PIN);
            log_watering_event(RELAY2_PIN);
            sleep(WATERING_DURATION);
            deactivate_relay(RELAY2_PIN);

            activate_relay(RELAY3_PIN);
            log_watering_event(RELAY3_PIN);
            sleep(WATERING_DURATION);
            deactivate_relay(RELAY3_PIN);

            activate_relay(RELAY4_PIN);
            log_watering_event(RELAY4_PIN);
            sleep(WATERING_DURATION);
            deactivate_relay(RELAY4_PIN);

            printf("Watering cycle complete.\n");

            last_watering_time = current_time;
        }

        // Sleep for polling interval
        sleep(POLLING_INTERVAL);
    }

    // Cleanup
    cleanup_gpio();
    fclose(log_file);

    printf("Watering system stopped.\n");

    return EXIT_SUCCESS;
}

