#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 17
#define RELAY2_GPIO 18
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define sunrise duration (in seconds)
#define SUNRISE_DURATION 1800

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_relay_pwm(int gpio, int duty_cycle);
int simulate_sunrise();
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RELAY1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY1_GPIO);
        return 1;
    }
    if (gpioSetMode(RELAY2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY2_GPIO);
        return 1;
    }
    if (gpioSetMode(RELAY3_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY3_GPIO);
        return 1;
    }
    if (gpioSetMode(RELAY4_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY4_GPIO);
        return 1;
    }

    // Configure PWM frequency
    if (gpioSetPWMfrequency(RELAY1_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", RELAY1_GPIO);
        return 1;
    }
    if (gpioSetPWMfrequency(RELAY2_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", RELAY2_GPIO);
        return 1;
    }
    if (gpioSetPWMfrequency(RELAY3_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", RELAY3_GPIO);
        return 1;
    }
    if (gpioSetPWMfrequency(RELAY4_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", RELAY4_GPIO);
        return 1;
    }

    return 0; // Indicate success
}

// Function to set the PWM duty cycle for a relay
int set_relay_pwm(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", gpio);
        return 1;
    }
    return 0;
}

// Function to simulate the sunrise effect
int simulate_sunrise() {
    int duty_cycle = 0;
    int step_size = 256 / (SUNRISE_DURATION / 1); // Calculate step size based on sunrise duration

    while (duty_cycle <= 255 && program_running) {
        // Set PWM duty cycle for each relay
        if (set_relay_pwm(RELAY1_GPIO, duty_cycle) != 0) return 1;
        if (set_relay_pwm(RELAY2_GPIO, duty_cycle) != 0) return 1;
        if (set_relay_pwm(RELAY3_GPIO, duty_cycle) != 0) return 1;
        if (set_relay_pwm(RELAY4_GPIO, duty_cycle) != 0) return 1;

        // Log the event
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Duty cycle: %d", duty_cycle);
        log_event(log_message);

        // Increment duty cycle
        duty_cycle += step_size;

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    return 0;
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting...");
        return 1;
    }
    log_event("GPIO initialized successfully");

    // Simulate sunrise
    if (simulate_sunrise() != 0) {
        log_event("Sunrise simulation failed");
    } else {
        log_event("Sunrise simulation complete");
    }

    // Clean up GPIO resources
    gpioTerminate();
    log_event("pigpio terminated");

    return 0;
}

