#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define WHO_AM_I     0x75

// GPIO pin for LED
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Gyroscope sensitivity (±250 deg/s)
#define GYRO_SENSITIVITY 131.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data and timestamp
typedef struct {
    long long timestamp;
    float x, y, z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void store_data(long long timestamp, float x, float y, float z);
void check_threshold(float x, float y, float z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize MPU-6050
int init_mpu6050() {
    int retries = 3;
    while (retries > 0) {
        // Wake up the sensor
        if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
            fprintf(stderr, "Error: Could not wake up MPU-6050 (PWR_MGMT_1). Retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Set sample rate divider
        if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
            fprintf(stderr, "Error: Could not set SMPLRT_DIV. Retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Set gyroscope full-scale range
        if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
            fprintf(stderr, "Error: Could not set GYRO_CONFIG. Retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Verify WHO_AM_I register
        int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
        if (who_am_i < 0) {
            fprintf(stderr, "Error: Could not read WHO_AM_I register. Retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }
        if (who_am_i != 0x68) {
            fprintf(stderr, "Error: WHO_AM_I returned 0x%x, expected 0x68. Retrying...\n", who_am_i);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        printf("MPU-6050 initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Error: Failed to initialize MPU-6050 after multiple retries.\n");
    return -1; // Failure
}

// Read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Error: Could not read gyroscope data.\n");
        return -1;
    }

    // Convert big-endian to signed 16-bit integers
    int16_t raw_x = (buf[0] << 8) | buf[1];
    int16_t raw_y = (buf[2] << 8) | buf[3];
    int16_t raw_z = (buf[4] << 8) | buf[5];

    // Convert to degrees/second
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Store data in circular buffer
void store_data(long long timestamp, float x, float y, float z) {
    gyro_buffer[buffer_index].timestamp = timestamp;
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check if any axis exceeds the threshold
void check_threshold(float x, float y, float z) {
    if (fabs(x) > 250.0 || fabs(y) > 250.0 || fabs(z) > 250.0) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (error code %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;
    struct timespec ts;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Get timestamp
            clock_gettime(CLOCK_REALTIME, &ts);
            long long timestamp = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

            // Store data in circular buffer
            store_data(timestamp, x, y, z);

            // Check threshold and control LED
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data. Attempting re-initialisation...\n");
            i2cClose(i2c_handle);
            gpioDelay(100000); // 100ms delay
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not reopen I2C bus (error code %d)\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialisation fails
            } else {
                if (init_mpu6050() != 0) {
                    terminate = 1; // Exit loop if re-initialisation fails
                }
            }
        }

        // Delay for 50ms (20 Hz sampling rate)
        gpioDelay(50000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

