#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// MPU-9250 Registers
#define MPU9250_ADDR 0x68
#define MPU9250_WHO_AM_I 0x75
#define MPU9250_PWR_MGMT_1 0x6B
#define MPU9250_GYRO_CONFIG 0x1B
#define MPU9250_GYRO_XOUT_H 0x43

// SPI Configuration
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8

// Chip Select GPIO
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8

// Gyroscope Scale Factor
#define GYRO_SCALE 131.0

// Retry Attempts
#define MAX_RETRIES 3

// Global Variables
static int spi_fd = -1;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(void);
int gpio_init(void);
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void convert_gyro_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *x_rate, float *y_rate, float *z_rate);
void log_data(float x_rate, float y_rate, float z_rate);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization
int spi_init(void) {
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", SPI_BUS, SPI_DEVICE);

    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// GPIO Initialization
int gpio_init(void) {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(gpio_line, "gyro_app", 1); // Initial value HIGH
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Read Gyroscope Data
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t tx_buf[1];
    uint8_t rx_buf[6];
    struct spi_ioc_transfer transfer[2];
    int retries = 0;

    // MPU-9250 register addresses for gyro data (0x43-0x48)
    uint8_t gyro_regs[3] = {MPU9250_GYRO_XOUT_H, MPU9250_GYRO_YOUT_H, MPU9250_GYRO_ZOUT_H};

    while (retries < MAX_RETRIES) {
        // Set chip select low
        if (gpiod_line_set_value(gpio_line, 0) < 0) {
            perror("Error setting GPIO line low");
            retries++;
            usleep(10000); // Wait 10ms before retry
            continue;
        }

        // Read gyro data
        memset(transfer, 0, sizeof(transfer));

        for (int i = 0; i < 3; i++) {
            tx_buf[0] = gyro_regs[i] | 0x80; // Set MSB for read operation

            transfer[i].tx_buf = (unsigned long)tx_buf;
            transfer[i].rx_buf = (unsigned long)rx_buf + i * 2;
            transfer[i].len = 1;
            transfer[i].delay_usecs = 0;
            transfer[i].speed_hz = SPI_SPEED;
            transfer[i].bits_per_word = SPI_BITS_PER_WORD;

            if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer[i]) < 0) {
                perror("Error sending SPI message");
                // Set chip select high
                if (gpiod_line_set_value(gpio_line, 1) < 0) {
                    perror("Error setting GPIO line high");
                }
                retries++;
                usleep(10000); // Wait 10ms before retry
                continue;
            }

            // Read the next byte
            transfer[i].tx_buf = (unsigned long)tx_buf;
            transfer[i].rx_buf = (unsigned long)rx_buf + i * 2 + 1;
            transfer[i].len = 1;
            transfer[i].delay_usecs = 0;
            transfer[i].speed_hz = SPI_SPEED;
            transfer[i].bits_per_word = SPI_BITS_PER_WORD;

            if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer[i]) < 0) {
                perror("Error sending SPI message");
                // Set chip select high
                if (gpiod_line_set_value(gpio_line, 1) < 0) {
                    perror("Error setting GPIO line high");
                }
                retries++;
                usleep(10000); // Wait 10ms before retry
                continue;
            }
        }

        // Set chip select high
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            perror("Error setting GPIO line high");
            retries++;
            usleep(10000); // Wait 10ms before retry
            continue;
        }

        // Combine high and low bytes to form 16-bit values
        *gyro_x = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
        *gyro_y = (int16_t)((rx_buf[2] << 8) | rx_buf[3]);
        *gyro_z = (int16_t)((rx_buf[4] << 8) | rx_buf[5]);

        return 0; // Success
    }

    fprintf(stderr, "Error: Max retries reached for reading gyro data.\n");
    return -1; // Failure
}

// Convert Gyroscope Data
void convert_gyro_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *x_rate, float *y_rate, float *z_rate) {
    *x_rate = (float)gyro_x / GYRO_SCALE;
    *y_rate = (float)gyro_y / GYRO_SCALE;
    *z_rate = (float)gyro_z / GYRO_SCALE;
}

// Log Data to File
void log_data(float x_rate, float y_rate, float z_rate) {
    struct timespec ts;
    char timestamp[30];

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("Error getting time");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);

    if (fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x_rate, y_rate, z_rate) < 0) {
        perror("Error writing to log file");
    }
    fflush(log_file); // Ensure data is written immediately
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup Resources
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_line != NULL) {
        gpiod_line_release(gpio_line);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    fprintf(stderr, "Cleanup complete. Exiting.\n");
    exit(0);
}

int main(void) {
    int16_t gyro_x, gyro_y, gyro_z;
    float x_rate, y_rate, z_rate;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Configure MPU-9250 (example: set gyro range to ±250 dps)
    uint8_t config_data[2];
    config_data[0] = MPU9250_GYRO_CONFIG;
    config_data[1] = 0x00; // Full scale range = ±250 dps

    // Set chip select low
    if (gpiod_line_set_value(gpio_line, 0) < 0) {
        perror("Error setting GPIO line low");
        cleanup();
        return 1;
    }

    // Write configuration data
    if (write(spi_fd, config_data, 2) != 2) {
        perror("Error writing to SPI device");
        // Set chip select high
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            perror("Error setting GPIO line high");
        }
        cleanup();
        return 1;
    }

    // Set chip select high
    if (gpiod_line_set_value(gpio_line, 1) < 0) {
        perror("Error setting GPIO line high");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) == 0) {
            convert_gyro_data(gyro_x, gyro_y, gyro_z, &x_rate, &y_rate, &z_rate);
            log_data(x_rate, y_rate, z_rate);
        } else {
            fprintf(stderr, "Error reading gyro data.\n");
        }
        usleep(10000); // 10ms delay
    }

    cleanup();
    return 0;
}

