#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// MPU-6050 Registers
#define MPU6050_ADDR 0x68
#define MPU6050_WHO_AM_I 0x75
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_GYRO_YOUT_H 0x45
#define MPU6050_GYRO_ZOUT_H 0x47

// Sensitivity scale factor
#define GYRO_SENSITIVITY 131.0

// Threshold for angular velocity (deg/s)
#define ANGULAR_VELOCITY_THRESHOLD 200.0

// LED GPIO pin
#define LED_GPIO 17

// SPI device
#define SPI_DEVICE "/dev/spidev0.0"

// SPI mode
#define SPI_MODE SPI_MODE_0

// SPI speed
#define SPI_SPEED 3900000

// Chip select GPIO
#define CS_GPIO 8

// Circular buffer size
#define BUFFER_SIZE 64

// Structure to hold gyroscope data
typedef struct {
    struct timespec timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int spi_fd;
struct gpiod_chip *gpio_chip;
struct gpiod_line *cs_line;
struct gpiod_line *led_line;

// Function prototypes
int spi_init(void);
int spi_read_reg(uint8_t reg, uint8_t *data, int len);
int spi_write_reg(uint8_t reg, uint8_t data);
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void convert_to_dps(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps);
