void signal_handler(int sig);
void gpio_init(void);
void gpio_cleanup(void);

// SPI Initialization
int spi_init(void) {
    int ret;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Read Register
int spi_read_reg(uint8_t reg, uint8_t *data, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)NULL,
        .rx_buf = (unsigned long)data,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    uint8_t tx_buf[1];
    tx_buf[0] = reg | 0x80; // Set MSB for read operation

    tr.tx_buf = (unsigned long)tx_buf;

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Error asserting CS");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error reading SPI data");
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("Error deasserting CS after read error");
        }
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Error deasserting CS");
        return -1;
    }

    return 0;
}

// SPI Write Register
int spi_write_reg(uint8_t reg, uint8_t data) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)&data,
        .rx_buf = (unsigned long)NULL,
        .len = 1,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    uint8_t tx_buf[2];
    tx_buf[0] = reg & 0x7F; // Clear MSB for write operation
    tx_buf[1] = data;

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Error asserting CS");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error writing SPI data");
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("Error deasserting CS after write error");
        }
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Error deasserting CS");
        return -1;
    }

    return 0;
}

// Read Gyroscope Data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    if (spi_read_reg(MPU6050_GYRO_XOUT_H, data, 6) < 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Convert to Degrees Per Second
void convert_to_dps(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)x / GYRO_SENSITIVITY;
    *y_dps = (float)y / GYRO_SENSITIVITY;
    *z_dps = (float)z / GYRO_SENSITIVITY;
}

// Store Data in Circular Buffer
void store_data(struct timespec timestamp, int16_t x, int16_t y, int16_t z) {
    gyro_buffer[buffer_index].timestamp = timestamp;
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check Threshold and Blink LED
void check_threshold(float x_dps, float y_dps, float z_dps) {
