        perror("Error setting LED high");
        return;
    }
    usleep(500000); // 500 ms
    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("Error setting LED low");
        return;
    }
    usleep(500000); // 500 ms
}

// Signal Handler
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully.\n", sig);

    // Print circular buffer to CSV
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Correct order
        printf("%ld.%09ld,%d,%d,%d\n", gyro_buffer[index].timestamp.tv_sec, gyro_buffer[index].timestamp.tv_nsec, gyro_buffer[index].x, gyro_buffer[index].y, gyro_buffer[index].z);
    }

    gpio_cleanup();
    close(spi_fd);
    exit(0);
}

// GPIO Initialization
void gpio_init(void) {
