    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        exit(1);
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_GPIO);
    if (!cs_line) {
        perror("Error getting CS line");
        gpiod_chip_close(gpio_chip);
        exit(1);
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(gpio_chip);
        exit(1);
    }

    ret = gpiod_line_request_output(cs_line, "gyro_cs", 1); // Initial value HIGH
    if (ret < 0) {
        perror("Error requesting CS line as output");
        gpiod_chip_close(gpio_chip);
        exit(1);
    }

    ret = gpiod_line_request_output(led_line, "led", 0); // Initial value LOW
    if (ret < 0) {
        perror("Error requesting LED line as output");
        gpiod_chip_close(gpio_chip);
        exit(1);
    }
}

// GPIO Cleanup
void gpio_cleanup(void) {
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main(void) {
    int16_t x, y, z;
    float x_dps, y_dps, z_dps;
    struct timespec timestamp;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    gpio_init();

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpio_cleanup();
        return 1;
    }

    // Verify MPU-6050 connection
    uint8_t who_am_i;
    if (spi_read_reg(MPU6050_WHO_AM_I, &who_am_i, 1) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        gpio_cleanup();
        close(spi_fd);
        return 1;
    }

    if (who_am_i != 0x68) {
        fprintf(stderr, "MPU-6050 not found. WHO_AM_I = 0x%02x\n", who_am_i);
        gpio_cleanup();
        close(spi_fd);
        return 1;
    }

    // Wake up the MPU-6050
    if (spi_write_reg(MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        gpio_cleanup();
        close(spi_fd);
        return 1;
    }

    printf("MPU-6050 initialized successfully.\n");

    // Main loop
    while (1) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &timestamp) == -1) {
                perror("clock_gettime");
                continue; // Continue to the next iteration
            }

            // Convert to degrees per second
            convert_to_dps(x, y, z, &x_dps, &y_dps, &z_dps);

            // Store data in circular buffer
            store_data(timestamp, x, y, z);

            // Check threshold and blink LED
            check_threshold(x_dps, y_dps, z_dps);
        } else {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
            usleep(100000); // Wait 100ms before retrying
        }

        usleep(10000); // 10 ms delay
    }

    return 0;
}

