#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define AMBIENT_LIGHT_REG 0x20
#define PROXIMITY_REG 0x22
#define GPIO_PIN 17
#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_line *gpio_line = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, unsigned char reg, unsigned short *value);
int i2c_write_byte(int fd, unsigned char reg, unsigned char value);
int gpio_set_value(struct gpiod_line *line, int value);
int log_data(FILE *fp, unsigned short ambient_light, unsigned short proximity);
void signal_handler(int sig);

// I2C read function with retry
int i2c_read_word(int fd, unsigned char reg, unsigned short *value) {
    int retries = RETRY_COUNT;
    unsigned char buf[2];

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, SI1145_ADDR) < 0) {
            perror("I2C_SLAVE failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 10ms
            continue;
        }

        if (write(fd, &reg, 1) != 1) {
            perror("I2C write (register select) failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 10ms
            continue;
        }

        if (read(fd, buf, 2) != 2) {
            perror("I2C read failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 10ms
            continue;
        }

        *value = (buf[1] << 8) | buf[0]; // Little-endian
        return 0; // Success
    }

    fprintf(stderr, "I2C read failed after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_byte(int fd, unsigned char reg, unsigned char value) {
    int retries = RETRY_COUNT;
    unsigned char buf[2];

    buf[0] = reg;
    buf[1] = value;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, SI1145_ADDR) < 0) {
            perror("I2C_SLAVE failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 10ms
            continue;
        }

        if (write(fd, buf, 2) != 2) {
            perror("I2C write failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 10ms
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "I2C write failed after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("gpiod_line_set_value failed");
        return -1;
    }
    return 0;
}

// Log data function
int log_data(FILE *fp, unsigned short ambient_light, unsigned short proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,AmbientLight:%04X,Proximity:%04X\n", timestamp, ambient_light, proximity);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Signal received, cleaning up...\n");
    terminate = 1;

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    if (gpio_line != NULL) {
        gpio_set_value(gpio_line, 0); // Turn off LED
        gpiod_line_release(gpio_line);
    }

    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

int main() {
    unsigned short ambient_light, proximity;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100ms

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // I2C initialization
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Log file initialization
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // GPIO initialization
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(gpio_line, "biometric_sensor", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (i2c_read_word(i2c_fd, AMBIENT_LIGHT_REG, &ambient_light) != 0) {
            fprintf(stderr, "Error reading ambient light\n");
        }
        if (i2c_read_word(i2c_fd, PROXIMITY_REG, &proximity) != 0) {
            fprintf(stderr, "Error reading proximity\n");
        }

        // Log data
        log_data(log_file, ambient_light, proximity);

        // Control LED based on proximity
        if (proximity > 100) {
            gpio_set_value(gpio_line, 1); // LED on
        } else {
            gpio_set_value(gpio_line, 0); // LED off
        }

        // Sleep for 100ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    close(i2c_fd);
    fclose(log_file);
    gpio_set_value(gpio_line, 0); // Turn off LED
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

