    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // I2C initialization
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Log file initialization
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // GPIO initialization
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(gpio_line, "biometric_sensor", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (i2c_read_word(i2c_fd, AMBIENT_LIGHT_REG, &ambient_light) != 0) {
            fprintf(stderr, "Error reading ambient light\n");
        }
        if (i2c_read_word(i2c_fd, PROXIMITY_REG, &proximity) != 0) {
            fprintf(stderr, "Error reading proximity\n");
        }

        // Log data
        log_data(log_file, ambient_light, proximity);

        // Control LED based on proximity
        if (proximity > 100) {
            gpio_set_value(gpio_line, 1); // LED on
        } else {
            gpio_set_value(gpio_line, 0); // LED off
        }

        // Sleep for 100ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    close(i2c_fd);
    fclose(log_file);
    gpio_set_value(gpio_line, 0); // Turn off LED
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

