volatile sig_atomic_t terminate = 0;

// Structure to hold gyro data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// Function prototypes
int init_spi();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize SPI
int init_spi() {
    int retries = 3;
    while (retries > 0) {
        spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
        if (spi_handle >= 0) {
            printf("SPI initialized successfully.\n");
            return 0; // Success
        } else {
            fprintf(stderr, "Error opening SPI: %d. Retrying...\n", spi_handle);
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
        }
    }
    fprintf(stderr, "Failed to initialize SPI after multiple retries.\n");
    return -1; // Failure
}

// Read gyro data from X and Y registers
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char tx_buf[3];
    char rx_buf[3];

    // Read X axis
    tx_buf[0] = X_AXIS_REG | 0x80; // Read bit set
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error reading X axis data.\n");
        data.x_rate = 0; // Set to 0 on error
    } else {
        data.x_rate = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);
    }

