    data_file = fopen("gyro_data.csv", "w");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file!\n");
        cleanup();
        return 1;
    }

    // Write CSV header
    fprintf(data_file, "timestamp,X_rate,Y_rate\n");

    // Main loop
    while (!terminate) {
        gyro_data_t gyro_data = read_gyro_data();
        log_data(gyro_data);
        gpioDelay(SAMPLE_PERIOD_US); // Delay for 10 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

