#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17

// Define alert duration (seconds)
#define ALERT_DURATION 2

// Define log file name
#define LOG_FILE "seismic_events.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void sensor_callback(int gpio, int level, uint32_t tick);
void trigger_alert();
void log_event();
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    uint32_t sensor1_tick;
    uint32_t sensor2_tick;
} SensorState;

SensorState sensor_state = {0, 0, 0, 0};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Register callbacks for both sensors
    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register callback for sensor 1. Exiting.\n");
        cleanup();
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR_2_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register callback for sensor 2. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Seismic monitoring system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        gpioDelay(100); // Reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Enable pull-down resistors
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    return 0;
}

// Callback function for sensor events
void sensor_callback(int gpio, int level, uint32_t tick) {
    if (gpio == SENSOR_1_PIN) {
        sensor_state.sensor1_state = level;
        if (level == 1) {
            sensor_state.sensor1_tick = tick;
        }
    } else if (gpio == SENSOR_2_PIN) {
        sensor_state.sensor2_state = level;
        if (level == 1) {
            sensor_state.sensor2_tick = tick;
        }
    }

    // Check if both sensors are HIGH for 500ms
    if (sensor_state.sensor1_state == 1 && sensor_state.sensor2_state == 1) {
        uint32_t diff = tick - sensor_state.sensor1_tick;
        if (diff >= 500000) { // 500ms in microseconds
            trigger_alert();
            log_event();
            sensor_state.sensor1_state = 0; // Reset states after triggering
            sensor_state.sensor2_state = 0;
        }
    }
}

// Trigger the alert by setting GPIO17 HIGH for 2 seconds
void trigger_alert() {
    gpioWrite(ALERT_PIN, 1);
    gpioDelay(ALERT_DURATION * 1000); // Convert seconds to milliseconds
    gpioWrite(ALERT_PIN, 0);
}

// Log the event to the log file with ISO-8601 timestamp
void log_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
    printf("%s - Seismic event detected!\n", timestamp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d. Exiting gracefully.\n", signal);
    program_running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

