#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 17
#define THRESHOLD 20.0
#define BUFFER_SIZE 100

// ADXRS290 Registers
#define RATE_XL 0x02
#define RATE_XH 0x03

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    struct timespec timestamp;
    float angular_rate;
} gyro_data_t;

gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_count = 0;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
int spi_read_register(int reg);
int spi_write_register(int reg, int value);
float read_gyro_data();
void add_to_buffer(struct timespec timestamp, float angular_rate);
void check_threshold(float angular_rate);
void signal_handler(int signal);

// SPI read function
int spi_read_register(int reg) {
    char tx[1], rx[1];
    tx[0] = (reg << 1) | 0x01; // Set MSB to 1 for read

    if (spiXfer(spi_handle, tx, rx, 1) != 0) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    return rx[0];
}

// SPI write function
int spi_write_register(int reg, int value) {
    char tx[2], rx[2];
    tx[0] = (reg << 1) & 0xFE; // Set MSB to 0 for write
    tx[1] = value;

    if (spiXfer(spi_handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI write error\n");
        return -1;
    }

    return 0;
}

// Read gyro data and convert to degrees per second
float read_gyro_data() {
    int16_t raw_data;
    int lsb, msb;

    msb = spi_read_register(RATE_XH);
    lsb = spi_read_register(RATE_XL);

    if (msb == -1 || lsb == -1) {
        return 0.0; // Return 0 on error
    }

    raw_data = (msb << 8) | lsb;

    // Sign extend 16-bit integer
    if (raw_data & 0x8000) {
        raw_data |= 0xFFFF0000;
    }

    return (float)raw_data / 200.0;
}

// Add data to the circular buffer
void add_to_buffer(struct timespec timestamp, float angular_rate) {
    pthread_mutex_lock(&buffer_mutex);
    gyro_buffer[buffer_head].timestamp = timestamp;
    gyro_buffer[buffer_head].angular_rate = angular_rate;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
    pthread_mutex_unlock(&buffer_mutex);
}

// Check if angular rate exceeds threshold and control LED
void check_threshold(float angular_rate) {
    if (fabs(angular_rate) > THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially off

    // Set up signal handlers
