#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define the PWM frequency
#define PWM_FREQUENCY 100

// Define the PWM range
#define PWM_RANGE 255

// Global variable to store the total fade duration
int total_fade_duration = 0;

// Function prototypes
void lamp_fade(int gpio, int duration);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Turn off all lamps
    gpioPWM(LAMP1_GPIO, 0);
    gpioPWM(LAMP2_GPIO, 0);
    gpioPWM(LAMP3_GPIO, 0);

    // Terminate the pigpio library
    gpioTerminate();

    // Exit the program
    exit(0);
}

// Function to fade a lamp from full brightness to off
void lamp_fade(int gpio, int duration) {
    int duty_cycle;
    int step_duration;
    int num_steps;
    int i;

    // Calculate the number of steps and step duration
    num_steps = PWM_RANGE; // Fade from 100% to 0%, so 256 steps
    step_duration = duration * 1000000 / num_steps; // Convert seconds to microseconds

    // Fade from full brightness (100%) to off (0%)
    for (duty_cycle = PWM_RANGE; duty_cycle >= 0; duty_cycle--) {
        gpioPWM(gpio, duty_cycle);
        usleep(step_duration);
    }

    // Ensure the lamp is completely off after the fade
    gpioPWM(gpio, 0);
}

int main(int argc, char *argv[]) {
    // Check if the user supplied a command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        return 1;
    }

    // Convert the command-line argument to an integer
    total_fade_duration = atoi(argv[1]);

    // Validate the fade duration
    if (total_fade_duration < 1 || total_fade_duration > 3600) {
        fprintf(stderr, "Error: Fade duration must be an integer between 1 and 3600\n");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
