// Define GPIO pins for the relays
#define RED_PIN 17
#define YELLOW_PIN 22
#define GREEN_PIN 23
#define BLUE_PIN 24

// Function prototypes
void set_relay_state(int red, int yellow, int green, int blue);
void red_state();
void red_yellow_state();
void green_state();
void yellow_state();
void blue_state();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(YELLOW_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to cycle through the traffic light states
    while (program_running) {
        red_state();
        red_yellow_state();
        green_state();
        yellow_state();
        blue_state();
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

// Function to set the state of the relays
void set_relay_state(int red, int yellow, int green, int blue) {
    gpioWrite(RED_PIN, red);
    gpioWrite(YELLOW_PIN, yellow);
    gpioWrite(GREEN_PIN, green);
    gpioWrite(BLUE_PIN, blue);
}

// Function to simulate the red state
void red_state() {
    printf("Red\n");
    set_relay_state(0, 1, 1, 1); // Red ON, Yellow, Green, Blue OFF
    gpioDelay(10000000); // 10 seconds
}

// Function to simulate the red+yellow state
void red_yellow_state() {
    printf("Red+Yellow\n");
    set_relay_state(0, 0, 1, 1); // Red and Yellow ON, Green, Blue OFF
    gpioDelay(2000000); // 2 seconds
}

// Function to simulate the green state
void green_state() {
    printf("Green\n");
    set_relay_state(1, 1, 0, 1); // Red OFF, Yellow, Green ON, Blue OFF
    gpioDelay(10000000); // 10 seconds
}

// Function to simulate the yellow state
void yellow_state() {
    printf("Yellow\n");
    set_relay_state(1, 0, 1, 1); // Red OFF, Yellow ON, Green, Blue OFF
    gpioDelay(3000000); // 3 seconds
}

// Function to simulate the blue state
void blue_state() {
    printf("Blue\n");
    set_relay_state(1, 1, 1, 0); // Red, Yellow, Green, Blue ON
    gpioDelay(5000000); // 5 seconds
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0; // Set the flag to exit the main loop
    set_relay_state(1, 1, 1, 1); // Turn off all relays
    gpioTerminate(); // Terminate the pigpio library
    exit(0); // Exit the program
}

