#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define DEBOUNCE_DELAY 100 // milliseconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int initialize_mpr121();
int read_touch_status();
void control_relay(int state);
void log_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    log_message("Received signal, shutting down...");
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF
    log_message("pigpio initialised successfully");
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Failed to open I2C device");
        return -1;
    }
    log_message("I2C device opened successfully");
    return 0;
}

// Initialize MPR121 sensor
int initialize_mpr121() {
    // Reset MPR121
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        log_message("Failed to reset MPR121");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x00) < 0) {
        log_message("Failed to set MPR121 to stop mode");
        return -1;
    }

    // Enable electrode 0
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) {
        log_message("Failed to enable electrode 0");
        return -1;
    }

    // Touch threshold
    if (i2cWriteByteData(i2c_handle, 0x41, TOUCH_THRESHOLD) < 0) {
        log_message("Failed to set touch threshold");
        return -1;
    }

    // Release threshold
    if (i2cWriteByteData(i2c_handle, 0x42, RELEASE_THRESHOLD) < 0) {
        log_message("Failed to set release threshold");
        return -1;
    }

    // Debounce
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x21) < 0) {
        log_message("Failed to set debounce");
        return -1;
    }

    // Charge time
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x0D) < 0) {
        log_message("Failed to set charge time");
        return -1;
    }

    // Run mode
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0D) < 0) {
        log_message("Failed to set run mode");
        return -1;
    }

    log_message("MPR121 initialised successfully");
    return 0;
}

// Read touch status from MPR121
int read_touch_status() {
    int touch_status = i2cReadWordData(i2c_handle, 0x00);
    if (touch_status < 0) {
        log_message("Failed to read touch status");
        return -1;
    }
    return touch_status;
}

// Control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    char message[50];
    snprintf(message, sizeof(message), "Relay set to %s", state ? "ON" : "OFF");
    log_message(message);
}

// Log messages to file
void log_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

int main() {
    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    int relay_state = 0; // 0 = OFF, 1 = ON
    int last_touch_status = 0;
    time_t last_debounce_time = 0;

    // Main loop
    while (!terminate) {
        int touch_status = read_touch_status();
        if (touch_status < 0) {
            // Error reading touch status, but continue running
            gpioDelay(10);
            continue;
        }

        // Check if electrode 0 is touched
        if ((touch_status & 0x01) && !(last_touch_status & 0x01)) {
            // Touched, check debounce
            time_t current_time = time(NULL);
            if (difftime(current_time, last_debounce_time) * 1000 >= DEBOUNCE_DELAY) {
                // Toggle relay state
                relay_state = !relay_state;
                control_relay(relay_state);
                last_debounce_time = current_time;
            }
        }

        last_touch_status = touch_status;
        gpioDelay(10); // Check every 10 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Turn off relay on exit
    gpioTerminate();
    fclose(log_file);

    return 0;
}

