void signal_handler(int signal);

// Function to read the flame sensor with debouncing
int read_flame_sensor() {
    int i;
    int flame_detected = 1; // Assume no flame initially

    for (i = 0; i < 3; i++) {
        if (gpioRead(FLAME_SENSOR_PIN) == 1) {
            flame_detected = 0; // Flame detected (active low)
            break; // Exit loop if any read indicates no flame
        }
        gpioDelay(DEBOUNCE_INTERVAL * 1000); // Delay in microseconds
    }

    return flame_detected;
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1); // Set GPIO high
}

