    if (signal == SIGINT) {
        printf("Ctrl+C detected. Shutting down gracefully...\n");
        program_running = 0;
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to dispense fluid from a solenoid
int dispense_solenoid(int pin, int duration_ms) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Failed to activate solenoid on GPIO%d\n", pin);
        return 1;
    }

    gpioDelay(duration_ms * 1000); // Convert milliseconds to microseconds

    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid on GPIO%d\n", pin);
        return 1;
    }

    return 0;
}

// Function to log dispense event to file
int log_dispense_event(int pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open dispense_log.txt for writing\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, GPIO%d, %d ms\n", s, pin, duration_ms);
    fclose(fp);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Dispenser system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Dispense from solenoid 1
        if (dispense_solenoid(SOLENOID_1_PIN, DISPENSE_DURATION) != 0) {
            fprintf(stderr, "Error dispensing from solenoid 1\n");
        } else {
            if (log_dispense_event(SOLENOID_1_PIN, DISPENSE_DURATION) != 0) {
                fprintf(stderr, "Error logging dispense event for solenoid 1\n");
            }
        }

        // Dispense from solenoid 2
        if (dispense_solenoid(SOLENOID_2_PIN, DISPENSE_DURATION) != 0) {
            fprintf(stderr, "Error dispensing from solenoid 2\n");
        } else {
            if (log_dispense_event(SOLENOID_2_PIN, DISPENSE_DURATION) != 0) {
