#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

// Motor A GPIOs
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_A_ENABLE 24

// Motor B GPIOs
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_B_ENABLE 25

// PID Constants
#define Kp 1.0
#define Ki 0.01
#define Kd 0.1

// Obstacle Avoidance Threshold
#define OBSTACLE_THRESHOLD 20.0

// Global Variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// PID Variables
float integral = 0.0;
float previous_error = 0.0;

// Function Prototypes
void signal_handler(int signal);
float generate_tilt_error();
float generate_distance();
int set_motor_speed(char motor, int speed);
int stop_motors();
int log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
int pid_control(float tilt_error);

// Signal Handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Generate Tilt Error
float generate_tilt_error() {
    return ((float)(rand() % 2001) / 100.0) - 10.0;
}

// Generate Distance
float generate_distance() {
    return ((float)(rand() % 3981) / 10.0) + 20.0;
}

// Set Motor Speed
int set_motor_speed(char motor, int speed) {
    int forward_pin, backward_pin, enable_pin;

    if (motor == 'A') {
        forward_pin = MOTOR_A_FORWARD;
        backward_pin = MOTOR_A_BACKWARD;
        enable_pin = MOTOR_A_ENABLE;
    } else if (motor == 'B') {
        forward_pin = MOTOR_B_FORWARD;
        backward_pin = MOTOR_B_BACKWARD;
        enable_pin = MOTOR_B_ENABLE;
    } else {
        fprintf(stderr, "Error: Invalid motor character: %c\n", motor);
        return -1;
    }

    if (speed > 0) {
        gpioWrite(forward_pin, 1);
        gpioWrite(backward_pin, 0);
        gpioPWM(enable_pin, speed);
    } else if (speed < 0) {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 1);
        gpioPWM(enable_pin, -speed);
    } else {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
        gpioPWM(enable_pin, 0);
    }

    return 0;
}

// Stop Motors
int stop_motors() {
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioPWM(MOTOR_A_ENABLE, 0);
