#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to store the relay state
static volatile int relay_state = 0;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_PIN, 0); // Deactivate the relay
    gpioTerminate(); // Terminate pigpio
    exit(0); // Exit the program
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistor on the touch sensor pin
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Initialize the relay to OFF state
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Smart Light Switch running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read the touch sensor state
        int touch_detected = gpioRead(TOUCH_SENSOR_PIN);

        // If a touch is detected
        if (touch_detected == 1) {
            // Toggle the relay state
            relay_state = !relay_state;
            gpioWrite(RELAY_PIN, relay_state);

            // Print the current relay state
            printf("Relay is now %s\n", relay_state ? "ON" : "OFF");

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds
        }

        // Small delay to prevent busy-waiting
        gpioDelay(1000); // 1 ms delay
    }

    return 0; // This line will never be reached due to the infinite loop
}

