#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>
#include <errno.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define ALSA parameters
#define SAMPLE_RATE 8000
#define NUM_CHANNELS 1
#define SAMPLE_SIZE 16 // bits
#define PERIOD_SIZE 1024

// Define ALSA buffer size (must be a multiple of period size)
#define BUFFER_SIZE (PERIOD_SIZE * 4)

// Define ALSA thread sleep time (in milliseconds)
#define ALSA_SLEEP_TIME 10

// Define ALSA thread wake-up signal
#define ALSA_WAKEUP_SIGNAL SIGUSR1

// Define ALSA thread ID
pthread_t alsa_thread_id;

// Define ALSA device name
#define ALSA_DEVICE "default"

// Global variables
snd_pcm_t *pcm_handle = NULL;
int running = 1;
float sensitivity = 1.0;

// Function prototypes
void signal_handler(int signal);
void *alsa_thread(void *arg);
float calculate_rms(short *data, int frames);
void map_rms_to_rgb(float rms, float sensitivity, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);

// Structure to hold ALSA data
typedef struct {
    short *buffer;
    int buffer_size;
    int frames_read;
    pthread_mutex_t mutex;
} alsa_data_t;

alsa_data_t alsa_data;

// Signal handler
void signal_handler(int signal) {
    fprintf(stdout, "Signal received: %d. Exiting...\n", signal);
    running = 0;
}

// ALSA thread function
void *alsa_thread(void *arg) {
    int err;
    int frames_to_read = PERIOD_SIZE;
    int frames_read;

    while (running) {
        pthread_mutex_lock(&alsa_data.mutex);
        frames_read = alsa_data.frames_read;
        pthread_mutex_unlock(&alsa_data.mutex);

        if (frames_read < BUFFER_SIZE) {
            frames_to_read = (BUFFER_SIZE - frames_read) > PERIOD_SIZE ? PERIOD_SIZE : (BUFFER_SIZE - frames_read);

            err = snd_pcm_readi(pcm_handle, alsa_data.buffer + frames_read, frames_to_read);
            if (err == -EPIPE) {
                fprintf(stderr, "ALSA: Overrun occurred\n");
                snd_pcm_prepare(pcm_handle);
            } else if (err == -ESTRPIPE) {
                fprintf(stderr, "ALSA: Suspended\n");
                snd_pcm_resume(pcm_handle);
                snd_pcm_wait(pcm_handle, -1);
            } else if (err < 0) {
                fprintf(stderr, "ALSA: Error reading PCM: %s\n", snd_strerror(err));
                break;
            } else {
                pthread_mutex_lock(&alsa_data.mutex);
                alsa_data.frames_read += err;
                pthread_mutex_unlock(&alsa_data.mutex);
            }
        } else {
            // Buffer is full, reset
            pthread_mutex_lock(&alsa_data.mutex);
            alsa_data.frames_read = 0;
            pthread_mutex_unlock(&alsa_data.mutex);
        }

        // Sleep for a short time
        usleep(ALSA_SLEEP_TIME * 1000); // Convert milliseconds to microseconds
    }

    pthread_exit(NULL);
}

// Function to calculate RMS amplitude
float calculate_rms(short *data, int frames) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < frames; i++) {
        sum_of_squares += (double)data[i] * data[i];
    }
    return sqrt(sum_of_squares / frames);
}

// Function to map RMS to RGB values
void map_rms_to_rgb(float rms, float sensitivity, int *red, int *green, int *blue) {
    float scaled_rms = rms * sensitivity;
    float normalized_rms = scaled_rms / 32768.0; // Normalize to 0-1 range

    // Non-linear mapping (example: logarithmic)
    float mapped_rms = log10(1 + normalized_rms * 9); // Map 0-1 to 0-9, then log10
    mapped_rms /= 3.0; // Scale down to 0-3

    // Cool colors (blue, cyan, white)
    if (mapped_rms < 1.0) {
        *red = 0;
        *green = (int)(mapped_rms * 255);
        *blue = 255 - (int)(mapped_rms * 255);
    }
    // Warm colors (yellow, orange, red)
    else {
        *red = (int)((mapped_rms - 1.0) * 255);
        *green = 255 - (int)((mapped_rms - 1.0) * 255);
        *blue = 0;
    }
}

// Function to set LED color using pigpio
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

int main(int argc, char *argv[]) {
    int red, green, blue;
    float rms;
    int err;

    // Parse command-line arguments
    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0) {
            fprintf(stderr, "Error: Sensitivity must be a positive number.\n");
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Initialize ALSA
    alsa_data.buffer = (short *)malloc(BUFFER_SIZE * sizeof(short));
    if (alsa_data.buffer == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for ALSA buffer\n");
        gpioTerminate();
        return 1;
    }
    alsa_data.buffer_size = BUFFER_SIZE;
    alsa_data.frames_read = 0;
    pthread_mutex_init(&alsa_data.mutex, NULL);

    err = snd_pcm_open(&pcm_handle, ALSA_DEVICE, SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Error: Cannot open audio device %s: %s\n", ALSA_DEVICE, snd_strerror(err));
        free(alsa_data.buffer);
        gpioTerminate();
        return 1;
    }

    snd_pcm_hw_params_t *hw_params;
    snd_pcm_hw_params_alloca(&hw_params);

    err = snd_pcm_hw_params_any(pcm_handle, hw_params);
    if (err < 0) {
        fprintf(stderr, "Error: Cannot initialize hardware parameter structure: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        free(alsa_data.buffer);
        gpioTerminate();
        return 1;
    }

    err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "Error: Cannot set access type: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        free(alsa_data.buffer);
        gpioTerminate();
        return 1;
    }

    err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        fprintf(stderr, "Error: Cannot set sample format: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        free(alsa_data.buffer);
        gpioTerminate();
        return 1;
    }

    err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, NUM_CHANNELS);
    if (err < 0) {
        fprintf(stderr, "Error: Cannot set channel count: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        free(alsa_data.buffer);
        gpioTerminate();
        return 1;
    }

    unsigned int rate = SAMPLE_RATE;
    err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0);
    if (err < 0) {
        fprintf(stderr, "Error: Cannot set sample rate: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        free(alsa_data.buffer);
        gpioTerminate();
        return 1;
    }

    err = snd_pcm_hw_params_set_period_size(pcm_handle, hw_params, PERIOD_SIZE, 0);
    if (err < 0) {
        fprintf(stderr, "Error: Cannot set period size: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        free(alsa_data.buffer);
        gpioTerminate();
        return 1;
    }

    err = snd_pcm_hw_params(pcm_handle, hw_params);
    if (err < 0) {
        fprintf(stderr, "Error: Cannot set hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        free(alsa_data.buffer);
        gpioTerminate();
        return 1;
    }

    // Create ALSA thread
    if (pthread_create(&alsa_thread_id, NULL, alsa_thread, NULL) != 0) {
        fprintf(stderr, "Error: Failed to create ALSA thread\n");
        snd_pcm_close(pcm_handle);
        free(alsa_data.buffer);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read RMS from ALSA buffer
        pthread_mutex_lock(&alsa_data.mutex);
        int frames_to_process = alsa_data.frames_read;
        pthread_mutex_unlock(&alsa_data.mutex);

        if (frames_to_process > 0) {
            rms = calculate_rms(alsa_data.buffer, frames_to_process);

            // Map RMS to RGB values
            map_rms_to_rgb(rms, sensitivity, &red, &green, &blue);

            // Set LED color
            set_led_color(red, green, blue);

            // Print status message
            fprintf(stdout, "RMS: %.2f, Red: %d, Green: %d, Blue: %d\n", rms, red, green, blue);
        } else {
            // No data available, use a sine wave for testing
            static float phase = 0.0;
            float amplitude = 32767.0 * (0.5 + 0.5 * sin(phase));
            phase += 0.01;
            if (phase > 2 * M_PI) phase -= 2 * M_PI;

            map_rms_to_rgb(amplitude, sensitivity, &red, &green, &blue);
            set_led_color(red, green, blue);

            fprintf(stdout, "Simulated RMS: %.2f, Red: %d, Green: %d, Blue: %d\n", amplitude, red, green, blue);
        }

        // Delay
        gpioDelay(10); // 10 ms
    }

    // Clean up
    pthread_cancel(alsa_thread_id);
    pthread_join(alsa_thread_id, NULL);
    snd_pcm_drain(pcm_handle);
    snd_pcm_close(pcm_handle);
    free(alsa_data.buffer);
    gpioTerminate();

    return 0;
}

