#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_I2C_ADDR 0x29

// TCS34725 registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to write a byte to a TCS34725 register
int tcs34725_write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a TCS34725 register
int tcs34725_read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cWriteDevice(handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%02X: %d\n", reg, result);
        return -1;
    }
    result = i2cReadDevice(handle, value, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from a TCS34725 register
int tcs34725_read_16bit(int handle, uint8_t reg, uint16_t *value) {
    char buf[1];
    buf[0] = reg;
    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for 16-bit read 0x%02X: %d\n", reg, result);
        return -1;
    }
    char read_buf[2];
    result = i2cReadDevice(handle, read_buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (read_buf[1] << 8) | read_buf[0];
    return 0;
}

// Function to initialize the TCS34725 sensor
int tcs34725_init(int handle) {
    // Enable power and RGBC
    if (tcs34725_write_register(handle, TCS34725_ENABLE, 0x03) != 0) {
        return -1;
    }

    // Set integration time to 154 ms
    if (tcs34725_write_register(handle, TCS34725_ATIME, 0xD5) != 0) {
        return -1;
    }

    return 0;
}

// Function to read color data from the sensor
int tcs34725_read_color_data(int handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (tcs34725_read_16bit(handle, TCS34725_CDATA, clear) != 0) return -1;
    if (tcs34725_read_16bit(handle, TCS34725_RDATA, red) != 0) return -1;
    if (tcs34725_read_16bit(handle, TCS34725_GDATA, green) != 0) return -1;
    if (tcs34725_read_16bit(handle, TCS34725_BDATA, blue) != 0) return -1;
    return 0;
}

// Function to log data to a CSV file
int log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t now = time(NULL);
    fprintf(fp, "%ld,%u,%u,%u,%u\n", now, clear, red, green, blue);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (tcs34725_init(i2c_handle) != 0) {
        fprintf(stderr, "Error initializing TCS34725 sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("color_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,clear,red,green,blue\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint16_t clear, red, green, blue;
    while (1) {
        // Read color data
        if (tcs34725_read_color_data(i2c_handle, &clear, &red, &green, &blue) == 0) {
            // Log the data
            log_data(log_file, clear, red, green, blue);
        } else {
            // Log error values
            time_t now = time(NULL);
            fprintf(log_file, "%ld,0,0,0,0\n", now);
            fflush(log_file);
            fprintf(stderr, "Error reading color data, logging 0s\n");
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // The following lines will never be reached because of the infinite loop.
    // However, they are included for completeness and to demonstrate proper cleanup.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

