#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>
#include <math.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define the number of GPIO lines
#define NUM_LINES 4

// Define the PWM cycle duration (in seconds)
#define PWM_CYCLE_DURATION 3600

// Define the brightness increase/decrease duration (in seconds)
#define BRIGHTNESS_CHANGE_DURATION 3600

// Define the daytime duration (in seconds)
#define DAYTIME_DURATION 21600

// Define the nighttime duration (in seconds)
#define NIGHTTIME_DURATION 57600

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_LINES];

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Turn off all relays
    for (int i = 0; i < NUM_LINES; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1); // Set to HIGH to turn off the relay
        }
    }

    // Release GPIO lines
    for (int i = 0; i < NUM_LINES; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio() {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO lines
