#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"
#define DEBOUNCE_DELAY 200 // milliseconds

static volatile int running = 1;
static FILE *log_fp = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log motion detection events to a file
int log_motion(const char *timestamp) {
    if (log_fp == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    fprintf(log_fp, "%s Motion detected\n", timestamp);
    fflush(log_fp); // Ensure the log is written immediately
    return 0;
}

// Function to record a video using raspivid
int record_video(const char *timestamp) {
    char filename[256];
    snprintf(filename, sizeof(filename), "%s%s.h264", VIDEO_DIR, timestamp);

    char command[512];
    snprintf(command, sizeof(command), "raspivid -o %s -t 5000", filename);

    int status = system(command);
    if (status == -1) {
        perror("Error executing raspivid command");
        return -1;
    }
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    if (log_fp != NULL) {
        fclose(log_fp);
        printf("Log file closed.\n");
    }

    gpioTerminate();
    printf("pigpio terminated.\n");

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Open the log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Create the videos directory if it doesn't exist
    struct stat st = {0};
    if (stat(VIDEO_DIR, &st) == -1) {
        if (mkdir(VIDEO_DIR, 0777) != 0) {
            perror("Error creating videos directory");
            fclose(log_fp);
            gpioTerminate();
            return 1;
        }
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    int last_state = 1; // Assume no motion initially (sensor outputs LOW when motion is detected)
    time_t last_trigger_time = 0;

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = gpioRead(GPIO_PIN);

        if (current_state == 0 && last_state == 1) { // Motion detected (LOW to HIGH transition)
            time_t current_time = time(NULL);
            if (difftime(current_time, last_trigger_time) * 1000 >= DEBOUNCE_DELAY) {
                char *timestamp = get_iso8601_timestamp();
                if (timestamp != NULL) {
                    printf("Motion detected at %s\n", timestamp);

                    if (log_motion(timestamp) != 0) {
                        fprintf(stderr, "Error logging motion event.\n");
                    }

                    if (record_video(timestamp) != 0) {
                        fprintf(stderr, "Error recording video.\n");
                    }

                    free(timestamp);
                    last_trigger_time = current_time;
                } else {
                    fprintf(stderr, "Error getting timestamp.\n");
                }
            }
        }

        last_state = current_state;
        gpioDelay(10); // Small delay to reduce CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_fp);
    gpioTerminate();

    return 0;
}

