#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Gyroscope sensitivity (LSB/°/s)
#define GYRO_SENSITIVITY 131.0

// Sampling rate (Hz)
#define SAMPLE_RATE 100

// Sample interval (ms)
#define SAMPLE_INTERVAL 10

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_mpu6050();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize MPU-6050
int init_mpu6050() {
    int retries = 3;
    while (retries > 0) {
        // Wake up the sensor (set power management register to 0x00)
        if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
            fprintf(stderr, "Error: Could not wake up MPU-6050 (attempt %d): %s\n", 4 - retries, strerror(errno));
            retries--;
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Set sample rate divider to 125 Hz (SMPLRT_DIV = 124)
        if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 124) < 0) {
            fprintf(stderr, "Error: Could not set sample rate divider (attempt %d): %s\n", 4 - retries, strerror(errno));
            retries--;
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Set gyroscope full-scale range to ±250°/s (GYRO_CONFIG = 0x00)
        if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
            fprintf(stderr, "Error: Could not set gyroscope full-scale range (attempt %d): %s\n", 4 - retries, strerror(errno));
            retries--;
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        fprintf(stderr, "MPU-6050 initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Error: Failed to initialize MPU-6050 after multiple retries.\n");
    return -1; // Failure
}

// Read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    // Read gyroscope data (X, Y, Z)
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Error: Could not read gyroscope data: %s\n", strerror(errno));
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert to degrees per second
    data.x = (float)raw_x / GYRO_SENSITIVITY;
    data.y = (float)raw_y / GYRO_SENSITIVITY;
    data.z = (float)raw_z / GYRO_SENSITIVITY;

    return data;
}

// Log data to file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    fprintf(log_file, "%.6f,%.6f,%.6f,%.6f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        gyro_data_t data = read_gyro_data();
        log_data(data);
        gpioDelay(SAMPLE_INTERVAL);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

