#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define moisture threshold
#define MOISTURE_THRESHOLD 30

// Define log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_moisture_sensor();
int control_relay(int zone, int state);
int log_data(int zone, int moisture_level, int relay_state);
void signal_handler(int signal);

// Structure to hold GPIO pin configurations
typedef struct {
    int relay_pin;
    int zone;
} ZoneConfig;

// Array of zone configurations
ZoneConfig zones[] = {
    {RELAY1_PIN, 1},
    {RELAY2_PIN, 2},
    {RELAY3_PIN, 3},
    {RELAY4_PIN, 4}
};

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Install signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        for (int i = 0; i < sizeof(zones) / sizeof(zones[0]); i++) {
            // Read moisture sensor
            int moisture_level = read_moisture_sensor();

            // Determine relay state based on moisture level
            int relay_state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1; // Active-low

            // Control the relay
            if (control_relay(zones[i].zone, relay_state) != 0) {
                fprintf(stderr, "Failed to control relay for zone %d. Continuing.\n", zones[i].zone);
            }

            // Log the data
            if (log_data(zones[i].zone, moisture_level, relay_state) != 0) {
                fprintf(stderr, "Failed to log data for zone %d. Continuing.\n", zones[i].zone);
            }
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    signal_handler(0); // Call signal handler to ensure cleanup

    return 0;
}

// Initialize pigpio and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < sizeof(zones) / sizeof(zones[0]); i++) {
        gpioSetMode(zones[i].relay_pin, PI_OUTPUT);
        gpioWrite(zones[i].relay_pin, 1); // Initialize relays to OFF (HIGH)
    }

    return 0;
}

// Read a simulated moisture sensor value
int read_moisture_sensor() {
    return rand() % 101; // Returns a value between 0 and 100
}

// Control a relay (zone)
int control_relay(int zone, int state) {
    int pin = -1;
    for (int i = 0; i < sizeof(zones) / sizeof(zones[0]); i++) {
        if (zones[i].zone == zone) {
            pin = zones[i].relay_pin;
            break;
        }
    }

    if (pin == -1) {
        fprintf(stderr, "Invalid zone number: %d\n", zone);
        return 1;
    }

    gpioWrite(pin, state);
    return 0;
}

// Log data to the file
int log_data(int zone, int moisture_level, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Zone: %d, Moisture: %d, Relay: %s\n",
            timestamp, zone, moisture_level, (relay_state == 0) ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Deactivate all relays
    for (int i = 0; i < sizeof(zones) / sizeof(zones[0]); i++) {
        gpioWrite(zones[i].relay_pin, 1); // Set HIGH to deactivate
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

