#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define DATA_FORMAT 0x31
#define POWER_CTL 0x2D
#define DATAX0 0x32

// GPIO pin for alarm
#define ALARM_PIN 27

// Freefall threshold (g)
#define FREEFALL_THRESHOLD 0.2

// Freefall duration (seconds)
#define FREEFALL_DURATION 0.5

// Alarm duration (seconds)
#define ALARM_DURATION 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int init_adxl345();
accelerometer_data_t read_accelerometer_data();
int detect_freefall(accelerometer_data_t data);
void trigger_alarm();
void log_freefall(accelerometer_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize ADXL345
int init_adxl345() {
    // Set data format: +/- 2g range, full resolution
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char raw_data[6];
    int16_t x, y, z;

    if (i2cReadI2CBlockData(i2c_handle, DATAX0, raw_data, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = 0.0; // Set to 0.0 to avoid garbage values
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes, convert to signed 16-bit
    x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g-force (256 LSB/g)
    data.x = (float)x / 256.0;
    data.y = (float)y / 256.0;
    data.z = (float)z / 256.0;

    return data;
}

// Detect freefall
int detect_freefall(accelerometer_data_t data) {
    if (fabs(data.x) < FREEFALL_THRESHOLD &&
        fabs(data.y) < FREEFALL_THRESHOLD &&
        fabs(data.z) < FREEFALL_THRESHOLD) {
        return 1;
    } else {
        return 0;
    }
}

// Trigger alarm
void trigger_alarm() {
    gpioWrite(ALARM_PIN, 1); // Set GPIO high
    gpioDelay(ALARM_DURATION * 1000000); // Wait for 5 seconds
    gpioWrite(ALARM_PIN, 0); // Set GPIO low
}

// Log freefall event
void log_freefall(accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0); // Bus 1, address 0x53, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0); // Ensure it starts low

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();

        if (detect_freefall(data)) {
            // Delay for 0.5 seconds
            gpioDelay(FREEFALL_DURATION * 1000000);

            // Re-read accelerometer data
            accelerometer_data_t data2 = read_accelerometer_data();

            // Check if still in freefall
            if (detect_freefall(data2)) {
                printf("Freefall detected!\n");
                trigger_alarm();
                log_freefall(data);
            }
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(ALARM_PIN, 0); // Set GPIO low
    gpioTerminate();
    fclose(log_file);

    return 0;
}

