#include <errno.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define TRIGGER_PULSE_DURATION 10 // 10 µs
#define MAX_DISTANCE 4.0         // 4 meters
#define MAX_PULSE_WIDTH (int)(MAX_DISTANCE * 2 * 29.1) // Calculate maximum pulse width in microseconds
#define TIMEOUT_US 100000 // 100 ms timeout for echo pulse

// Global variables
static volatile uint32_t rising_tick = 0;
static volatile uint32_t falling_tick = 0;
static volatile int echo_received = 0;
static pthread_mutex_t mutex;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Trigger pulse function
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Echo callback function
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pthread_mutex_lock(&mutex);
        rising_tick = tick;
        echo_received = 1; // Set the flag to indicate rising edge received
        pthread_mutex_unlock(&mutex);
    } else if (level == 0) {
        pthread_mutex_lock(&mutex);
        falling_tick = tick;
        pthread_mutex_unlock(&mutex);
    }
}

// Calculate distance function
double calculate_distance(uint32_t pulse_width) {
    return (double)pulse_width / 2.0 / 29.1;
}

// Log distance function
void log_distance(double distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ns = ts.tv_sec * 1000000000LL + ts.tv_nsec;

    if (log_file != NULL) {
        fprintf(log_file, "%ld,%.2f\n", timestamp_ns, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Cancel callbacks
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy mutex
    pthread_mutex_destroy(&mutex);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize mutex
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        return 1;
    }

    // Set signal handler
    signal(SIGINT, signal_handler);

    // Set alert function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        fclose(log_file);
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Trigger pulse
        trigger_pulse();

        // Wait for echo or timeout
        int timeout_count = 0;
        echo_received = 0; // Reset the flag
        while (!echo_received && timeout_count < (TIMEOUT_US / 10000)) { // Check every 10 ms
            gpioDelay(10000); // 10 ms delay
            timeout_count++;
        }

        if (!echo_received) {
            fprintf(stderr, "Timeout waiting for echo\n");
            continue;
        }

        // Calculate pulse width
        uint32_t pulse_width;
        pthread_mutex_lock(&mutex);
        if (rising_tick > falling_tick) {
            pulse_width = (0xFFFFFFFF - rising_tick) + falling_tick; // Handle wrap-around
        } else {
            pulse_width = falling_tick - rising_tick;
        }
        pthread_mutex_unlock(&mutex);

        // Validate pulse width
        if (pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Invalid pulse width: %u\n", pulse_width);
            continue;
        }

        // Calculate distance
        double distance = calculate_distance(pulse_width);

        // Log distance
        log_distance(distance);

        // Wait 200 ms
        gpioDelay(200000);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    fclose(log_file);
    pthread_mutex_destroy(&mutex);
    gpioTerminate();

    return 0;
}

