#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// LIS3DH I2C address
#define LIS3DH_ADDR 0x18

// LIS3DH registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// GPIO pin for buzzer
#define BUZZER_PIN 17

// Default freefall and impact thresholds
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5

// Global variables
int i2c_handle;
double freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
double impact_threshold = DEFAULT_IMPACT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_lis3dh();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void activate_buzzer();
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int lis3dh_address;
    int buzzer_pin;
    double freefall_threshold;
    double impact_threshold;
} config_t;

config_t config = {
    .i2c_bus = 1,
    .lis3dh_address = LIS3DH_ADDR,
    .buzzer_pin = BUZZER_PIN,
    .freefall_threshold = DEFAULT_FREEFALL_THRESHOLD,
    .impact_threshold = DEFAULT_IMPACT_THRESHOLD
};

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        config.freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        config.impact_threshold = atof(argv[2]);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh() != 0) {
        fprintf(stderr, "LIS3DH initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set buzzer pin as output
    gpioSetMode(config.buzzer_pin, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    double magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate acceleration magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for freefall
            if (magnitude < config.freefall_threshold) {
                printf("Freefall detected! Magnitude: %.2f g\n", magnitude);
            }

            // Check for impact
            if (magnitude > config.impact_threshold) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                activate_buzzer();
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        // Delay for 10ms (100Hz data rate)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.lis3dh_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize LIS3DH
int init_lis3dh() {
    int retries = 3;
    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) >= 0) {
            if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) >= 0) {
                return 0; // Success
            } else {
                fprintf(stderr, "Failed to write to CTRL_REG4\n");
            }
        } else {
            fprintf(stderr, "Failed to write to CTRL_REG1\n");
        }
        retries--;
        gpioDelay(1000); // Wait 1ms before retrying
    }
    return -1; // Failure after retries
}

// Read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) == 6) {
            *x = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
            retries--;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }
    return -1; // Failure after retries
}

// Calculate acceleration magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 16384.0;
    double y_g = (double)y / 16384.0;
    double z_g = (double)z / 16384.0;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Activate buzzer
void activate_buzzer() {
    gpioWrite(config.buzzer_pin, 1); // Turn buzzer on
    gpioDelay(1000000);             // Wait for 1 second
    gpioWrite(config.buzzer_pin, 0); // Turn buzzer off
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(config.buzzer_pin, 0); // Ensure buzzer is off
    gpioTerminate();
}

