#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for Motor 1 (X-axis)
#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

// Define GPIO pins for Motor 2 (Y-axis)
#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

// Define steps per mm for motor control
#define STEPS_PER_MM 10

// Define steps per revolution for the 28BYJ-48
#define STEPS_PER_REVOLUTION 2048

// Define delay between steps in microseconds
#define STEP_DELAY 1000

// Define the square side length in mm
#define SQUARE_SIDE_LENGTH 50

// Define the number of steps for a full revolution
#define FULL_REVOLUTION_STEPS (STEPS_PER_REVOLUTION / 64) // Assuming 1/64 gear ratio

// Define the number of steps for a single step
#define SINGLE_STEP_STEPS (FULL_REVOLUTION_STEPS / 4)

// Define the number of steps for one mm
#define STEPS_PER_MM_X (FULL_REVOLUTION_STEPS / 64) * STEPS_PER_MM
#define STEPS_PER_MM_Y (FULL_REVOLUTION_STEPS / 64) * STEPS_PER_MM

// Define the number of steps for the square side
#define SQUARE_SIDE_STEPS (SQUARE_SIDE_LENGTH * STEPS_PER_MM_X)

// Define the number of steps for the square diagonal
#define SQUARE_DIAGONAL_STEPS (SQUARE_SIDE_LENGTH * STEPS_PER_MM_X * 1.41421356237) // sqrt(2)

// Define the number of steps for the square diagonal
#define SQUARE_DIAGONAL_STEPS_Y (SQUARE_SIDE_LENGTH * STEPS_PER_MM_Y * 1.41421356237) // sqrt(2)

// Define the number of steps for the square diagonal
