#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

// LIS3DH Registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Default values
#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0
#define LOG_FILE "/var/log/high_acceleration.log"

// Global variables (minimize usage)
static int i2c_handle = -1;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static float threshold = DEFAULT_THRESHOLD;
static volatile int running = 1;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection(int address);
int configure_lis3dh(int handle);
accelerometer_data_t read_acceleration(int handle);
void log_event(float x, float y, float z);
void shutdown_system();
void signal_handler(int signal);

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C connection
int open_i2c_connection(int address) {
    int handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to configure LIS3DH
int configure_lis3dh(int handle) {
    // CTRL_REG1: Normal mode, 100Hz, enable all axes
    if (i2cWriteByteData(handle, CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return -1;
    }

    // CTRL_REG4: +/-2g range, high-resolution
    if (i2cWriteByteData(handle, CTRL_REG4, 0x88) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data
accelerometer_data_t read_acceleration(int handle) {
    accelerometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(handle, OUT_X_L | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes, shift right, and scale
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]) >> 4;
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]) >> 4;
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]) >> 4;

    data.x = (float)x * 0.0009765625;
    data.y = (float)y * 0.0009765625;
    data.z = (float)z * 0.0009765625;

    return data;
}

// Function to log event to file
void log_event(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

