#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Default values
#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0
#define LOG_FILE "/var/log/high_acceleration.log"

// Global variables (minimize usage)
static int i2c_handle = -1;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static float threshold = DEFAULT_THRESHOLD;
static volatile int running = 1;

// Structure to hold accelerometer data
