#include <time.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_LED 22

// Define motor control pins (placeholders)
#define MOTOR_FORWARD_PIN 23
#define MOTOR_BACKWARD_PIN 24
#define MOTOR_LEFT_PIN 25
#define MOTOR_RIGHT_PIN 26

// Define circular buffer size
#define BUFFER_SIZE 5

// Structure to hold sensor readings
typedef struct {
    int left;
    int center;
    int right;
} sensor_reading_t;

// Circular buffer
sensor_reading_t sensor_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_sensor(int gpio_pin);
void add_reading_to_buffer(sensor_reading_t reading);
int check_for_line_loss();
void control_motors(int left, int center, int right);
void activate_alert();
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d\n", gpio_pin);
        return -1; // Indicate error
    }
    return value;
}

// Function to add a reading to the circular buffer
void add_reading_to_buffer(sensor_reading_t reading) {
    sensor_buffer[buffer_index] = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check for line loss
int check_for_line_loss() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (sensor_buffer[i].center == 1) {
            return 0; // No line loss detected
        }
    }
    return 1; // Line loss detected
}

// Function to control motors (placeholders)
void control_motors(int left, int center, int right) {
    if (center == 0) {
        // Move forward
        gpioWrite(MOTOR_FORWARD_PIN, 1);
        gpioWrite(MOTOR_BACKWARD_PIN, 0);
    } else if (left == 0) {
        // Turn left
        gpioWrite(MOTOR_LEFT_PIN, 1);
        gpioWrite(MOTOR_RIGHT_PIN, 0);
    } else if (right == 0) {
        // Turn right
        gpioWrite(MOTOR_LEFT_PIN, 0);
        gpioWrite(MOTOR_RIGHT_PIN, 1);
    } else {
        // Stop
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_BACKWARD_PIN, 0);
        gpioWrite(MOTOR_LEFT_PIN, 0);
        gpioWrite(MOTOR_RIGHT_PIN, 0);
    }
}

// Function to activate the alert
void activate_alert() {
    gpioWrite(ALERT_LED, 1); // Turn LED on
    gpioDelay(2000);          // Wait for 2 seconds
    gpioWrite(ALERT_LED, 0); // Turn LED off
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Stop motors
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    gpioWrite(MOTOR_LEFT_PIN, 0);
    gpioWrite(MOTOR_RIGHT_PIN, 0);

    // Turn off LED
    gpioWrite(ALERT_LED, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(CENTER_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetMode(ALERT_LED, PI_OUTPUT);

    // Set motor control pins as output
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_LEFT_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_RIGHT_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int left = read_sensor(LEFT_SENSOR);
        int center = read_sensor(CENTER_SENSOR);
        int right = read_sensor(RIGHT_SENSOR);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break; // Exit loop on sensor read error
        }

        // Create sensor reading struct
        sensor_reading_t reading = {left, center, right};

        // Add reading to buffer
        add_reading_to_buffer(reading);

        // Check for line loss
        if (check_for_line_loss()) {
            printf("Line loss detected! Activating alert.\n");
            activate_alert();
        }

        // Control motors
        control_motors(left, center, right);

        // Delay
        gpioDelay(10); // 10 ms delay
    }

    // Cleanup (should not be reached if signal handler works correctly)
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    gpioWrite(MOTOR_LEFT_PIN, 0);
    gpioWrite(MOTOR_RIGHT_PIN, 0);
    gpioWrite(ALERT_LED, 0);
    gpioTerminate();

    return 0;
}

