#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define RELAY_GPIO 17
#define THRESHOLD 5.0
#define LOG_FILE "magnetic_events.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int16_t *raw_data);
float convert_to_millitesla(int16_t raw_data);
int check_threshold(float field_mT, float threshold);
int control_relay(int state);
int log_event(const char *event);
void signal_handler(int signal);

// Structure for sensor configuration (optional)
typedef struct {
    int i2c_bus;
    int si7210_address;
    int relay_gpio;
    float threshold_mt;
} sensor_config_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw sensor data
int read_sensor_data(int16_t *raw_data) {
    char buf[2];
    int retries = 0;
    int status;

    // Start measurement
    status = i2cWriteByteData(i2c_handle, 0xC1, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", status);
        return -1;
    }

    // Wait for conversion to complete (polling register 0xC1)
    while (1) {
        status = i2cReadByteData(i2c_handle, 0xC1);
        if (status < 0) {
            fprintf(stderr, "Error reading from I2C: %d\n", status);
            return -1;
        }
        if (status == 0) break; // Conversion complete
        if (retries++ > 50) {
            fprintf(stderr, "Timeout waiting for conversion\n");
            return -1;
        }
        gpioDelay(1); // Small delay before retrying
    }

    // Read field data (2 bytes)
    status = i2cReadI2CBlockData(i2c_handle, 0xC0, buf, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading field data from I2C: %d\n", status);
        return -1;
    }

    *raw_data = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

// Convert raw data to milliTesla
float convert_to_millitesla(int16_t raw_data) {
    return (float)raw_data * 25.0 / 1000.0;
}

// Check if field exceeds threshold
int check_threshold(float field_mT, float threshold) {
    return (field_mT > threshold) ? 1 : 0;
}

// Control the relay
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// Log events to file
int log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

int main() {
    int16_t raw_data;
    float field_mT;
    int relay_state = 0; // 0 = off, 1 = on
    int threshold_exceeded;
    char event_message[100];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        log_event("I2C initialization failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Install signal handler
    signal(SIGINT, signal_handler);

    log_event("Program started");

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_data) == 0) {
            // Convert to milliTesla
            field_mT = convert_to_millitesla(raw_data);

            // Check threshold
            threshold_exceeded = check_threshold(field_mT, THRESHOLD);

            // Control relay
            if (threshold_exceeded && !relay_state) {
                control_relay(1);
                relay_state = 1;
                snprintf(event_message, sizeof(event_message), "Relay activated, field: %.2f mT", field_mT);
                log_event(event_message);
            } else if (!threshold_exceeded && relay_state) {
                control_relay(0);
                relay_state = 0;
                snprintf(event_message, sizeof(event_message), "Relay deactivated, field: %.2f mT", field_mT);
                log_event(event_message);
            }

            // Log field reading
            snprintf(event_message, sizeof(event_message), "Field reading: %.2f mT", field_mT);
            log_event(event_message);
        } else {
            log_event("Error reading sensor data");
        }

        gpioDelay(100); // Sample every 100 ms
    }

    // Cleanup
    log_event("Program terminated");
    control_relay(0); // Deactivate relay
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

