#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024

int server_fd, new_socket;
FILE *log_file;

// Function to handle signals for graceful shutdown
void signal_handler(int signum) {
    printf("\nCaught signal %d, shutting down...\n", signum);

    // Close the socket if it's open
    if (new_socket > 0) {
        close(new_socket);
    }
    if (server_fd > 0) {
        close(server_fd);
    }

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Turn off the relay
    gpioWrite(GPIO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to log messages to the log file
void log_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file); // Ensure the message is written to the file immediately
}

// Function to activate the relay
void activate_relay() {
    gpioWrite(GPIO_PIN, 1);
    log_message("Relay activated.");
}

// Function to deactivate the relay
void deactivate_relay() {
    gpioWrite(GPIO_PIN, 0);
    log_message("Relay deactivated.");
}

int main() {
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE] = {0};

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Open the log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("Socket creation failed");
        log_message("Socket creation failed.");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set socket options to reuse address
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        log_message("setsockopt failed.");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        log_message("Bind failed.");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        log_message("Listen failed.");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);
    log_message("Server started.");

    // Main loop to accept connections and process commands
    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("Accept failed");
            log_message("Accept failed.");
            continue; // Continue listening for new connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(address.sin_addr), ntohs(address.sin_port));
        log_message("Connection accepted.");

        // Read the command from the socket
        ssize_t bytes_received = recv(new_socket, buffer, BUFFER_SIZE - 1, 0);
        if (bytes_received < 0) {
            perror("Receive failed");
            log_message("Receive failed.");
            close(new_socket);
            continue;
        } else if (bytes_received == 0) {
            printf("Client disconnected\n");
            log_message("Client disconnected.");
            close(new_socket);
            continue;
        }

        buffer[bytes_received] = '\0'; // Null-terminate the received data
        printf("Received command: %s\n", buffer);

        // Process the command
        char *command = strtok(buffer, " \t\n\r"); // Remove trailing whitespace
        if (command != NULL) {
            if (strcasecmp(command, "ON") == 0) {
                activate_relay();
            } else if (strcasecmp(command, "OFF") == 0) {
                deactivate_relay();
            } else {
                fprintf(stderr, "Invalid command: %s\n", command);
                log_message("Invalid command received.");
            }
        } else {
            log_message("Empty command received.");
        }

        close(new_socket);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    close(server_fd);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

