#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_handle(int bus, int addr, int flags);
int write_i2c_block_data(int handle, int reg, const char *data, int count);
int read_i2c_block_data(int handle, int reg, char *data, int count);
int start_measurement(int handle);
int read_flow_data(int handle, float *flow_rate);
uint8_t crc8(const uint8_t *data, size_t len);
int set_relay_state(int state);
int log_flow_data(float flow1, float flow2);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C handle
int open_i2c_handle(int bus, int addr, int flags) {
    int handle = i2cOpen(bus, addr, flags);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Write data to I2C device
int write_i2c_block_data(int handle, int reg, const char *data, int count) {
    int result = i2cWriteI2CBlockData(handle, reg, data, count);
    if (result < 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from I2C device
int read_i2c_block_data(int handle, int reg, char *data, int count) {
    int result = i2cReadI2CBlockData(handle, reg, data, count);
    if (result < 0) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }
    return result;
}

// Start measurement on SLF3S-1300F
int start_measurement(int handle) {
    char data[2] = {0x36, 0x08};
    return write_i2c_block_data(handle, 0, data, 2);
}

// Read flow data from SLF3S-1300F
int read_flow_data(int handle, float *flow_rate) {
    char data[3];
    int bytes_read = read_i2c_block_data(handle, 0, data, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Failed to read 3 bytes from sensor\n");
        return -1;
    }

    // CRC check
    uint8_t crc = crc8((uint8_t *)data, 2);
    if (crc != (uint8_t)data[2]) {
        fprintf(stderr, "CRC mismatch: calculated 0x%02X, received 0x%02X\n", crc, (uint8_t)data[2]);
        return -1;
    }

    // Convert raw data to flow rate
    int16_t raw_flow = (data[0] << 8) | data[1];
    *flow_rate = (float)raw_flow / 1500.0;

    return 0;
}

// Set relay state
int set_relay_state(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// Log flow data to file
int log_flow_data(float flow1, float flow2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fflush(log_file);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    set_relay_state(0); // De-energize relay
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C handles
    i2c_handle1 = open_i2c_handle(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = open_i2c_handle(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Start measurement on both sensors
    if (start_measurement(i2c_handle1) != 0 || start_measurement(i2c_handle2) != 0) {
        cleanup();
        return 1;
    }

    // Configure relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    set_relay_state(0); // Initialize relay to de-energized state

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    float flow1, flow2;
    while (!terminate) {
        // Read flow data from sensor 1
        if (read_flow_data(i2c_handle1, &flow1) == 0) {
            // Read flow data from sensor 2
            if (read_flow_data(i2c_handle2, &flow2) == 0) {
                // Log flow data
                log_flow_data(flow1, flow2);

                // Control relay based on flow rates
                if (flow1 < FLOW_THRESHOLD || flow2 < FLOW_THRESHOLD) {
                    set_relay_state(1); // Energize relay
                } else {
                    set_relay_state(0); // De-energize relay
                }
            } else {
                fprintf(stderr, "Error reading from sensor 2\n");
            }
        } else {
            fprintf(stderr, "Error reading from sensor 1\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

