// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor run duration (seconds)
#define MOTOR_RUN_DURATION 5

// Define dry state duration (polls)
#define DRY_DURATION 3

// Global variables
static volatile int running = 1;
static int dry_count = 0;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
int control_motor(int enable, int in1, int in2);
void log_message(int priority, const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Ensure motor is initially stopped
    control_motor(0, 0, 0);

    log_message(LOG_INFO, "GPIO initialisation complete");
    return 0;
}

// Read rain sensor value
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Control the motor
int control_motor(int enable, int in1, int in2) {
    int result;

    result = gpioWrite(MOTOR_ENA_PIN, enable);
    if (result != 0) {
        log_message(LOG_WARNING, "Failed to write to MOTOR_ENA_PIN");
    }

    result = gpioWrite(MOTOR_IN1_PIN, in1);
    if (result != 0) {
        log_message(LOG_WARNING, "Failed to write to MOTOR_IN1_PIN");
    }

    result = gpioWrite(MOTOR_IN2_PIN, in2);
    if (result != 0) {
        log_message(LOG_WARNING, "Failed to write to MOTOR_IN2_PIN");
    }

    return 0;
}

// Log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

int main() {
    // Open syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Rain-actuated window controller started");

    int last_rain_state = 1; // Assume dry initially

    while (running) {
        int rain_state = read_rain_sensor();

        if (rain_state == 0 && last_rain_state == 1) {
            // Rain detected (rising edge)
            log_message(LOG_INFO, "Rain detected!");
            dry_count = 0; // Reset dry count

            // Start the motor
            if (control_motor(1, 1, 0) == 0) {
                log_message(LOG_INFO, "Motor started");
                gpioDelay(MOTOR_RUN_DURATION * 1000000); // Run for 5 seconds

                // Stop the motor
                if (control_motor(0, 0, 0) == 0) {
                    log_message(LOG_INFO, "Motor stopped");
                } else {
                    log_message(LOG_ERR, "Failed to stop motor");
                }
            } else {
                log_message(LOG_ERR, "Failed to start motor");
            }
        } else if (rain_state == 1) {
            // Dry state
            dry_count++;
            if (dry_count >= DRY_DURATION) {
                // Enough dry polls, reset the counter
                dry_count = 0;
            }
        } else {
            // Rain persistently detected, do not re-trigger
            dry_count = 0; // Reset the counter
        }

        last_rain_state = rain_state;
        gpioDelay(200000); // Poll every 200 ms
    }

    // Cleanup
    log_message(LOG_INFO, "Stopping motor and cleaning up...");
    control_motor(0, 0, 0); // Ensure motor is stopped
    gpioTerminate();
    closelog();

    return 0;
}

