#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define pulse widths
#define LOCKED_PULSE_WIDTH 2000
#define UNLOCKED_PULSE_WIDTH 1000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_servo_pulse_width(int pulse_width);
int read_button(int gpio_pin);
void debounce_button(int gpio_pin);
void handle_signal(int signal);

// Signal handler function
void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, shutting down gracefully...\n", signal);
        program_running = 0;
        set_servo_pulse_width(0); // Stop the servo
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors on buttons
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Set servo pulse width
int set_servo_pulse_width(int pulse_width) {
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Error setting servo pulse width\n");
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Read button state
int read_button(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Debounce button
void debounce_button(int gpio_pin) {
    gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
}

int main() {
    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door-lock servo control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check lock button
        if (read_button(LOCK_BUTTON_PIN) == 0) { // Button is pressed (low signal)
            printf("Lock button pressed\n");
            if (set_servo_pulse_width(LOCKED_PULSE_WIDTH) == 0) {
                printf("Door locked\n");
            } else {
                fprintf(stderr, "Failed to lock door\n");
            }
            debounce_button(LOCK_BUTTON_PIN);
        }

        // Check unlock button
        if (read_button(UNLOCK_BUTTON_PIN) == 0) { // Button is pressed (low signal)
            printf("Unlock button pressed\n");
            if (set_servo_pulse_width(UNLOCKED_PULSE_WIDTH) == 0) {
                printf("Door unlocked\n");
            } else {
                fprintf(stderr, "Failed to unlock door\n");
            }
            debounce_button(UNLOCK_BUTTON_PIN);
        }

        gpioDelay(10000); // Small delay to reduce CPU usage (10ms)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_servo_pulse_width(0); // Stop the servo
    gpioTerminate(); // Terminate pigpio

    return 0;
}

