#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define PIR_PIN 4
#define LED_PIN 17

// Define log file name
#define LOG_FILE "security_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_led(int state);
int log_event(const char *event_type, const char *message);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int pir_pin;
    int led_pin;
} gpio_config_t;

// Structure to hold program state
typedef struct {
    int led_state;
    time_t start_time;
} program_state_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Control LED state
int control_led(int state) {
    gpioWrite(LED_PIN, state);
    return 0;
}

// Log events to file
int log_event(const char *event_type, const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "%s - %s: %s\n", buf, event_type, message);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to turn off LED and terminate pigpio
void cleanup() {
    control_led(0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Smart Security Light System started. Press Ctrl+C to exit.\n");

