#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_BASELINE_FILTERING 0x5B
#define MPR121_FFI_SFI_CDT 0x2C
#define MPR121_AUTOCONFIG_START 0x7B
#define MPR121_AUTOCONFIG_END 0x7D
#define MPR121_SOFTRESET 0x80

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void toggle_relay();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// MPR121 Initialization function
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure baseline filtering (MHD/NHD/NCL/FDL)
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x01) < 0) { // MHD_R
        fprintf(stderr, "Error: MHD_R configuration failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) { // NHD_R
        fprintf(stderr, "Error: NHD_R configuration failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0F) < 0) { // NCL_R
        fprintf(stderr, "Error: NCL_R configuration failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5F, 0x01) < 0) { // FDL_R
        fprintf(stderr, "Error: FDL_R configuration failed\n");
        return -1;
    }

    // Configure debounce (register 0x5B)
    if (i2cWriteByteData(i2c_handle, MPR121_BASELINE_FILTERING, 0x10) < 0) {
        fprintf(stderr, "Error: Debounce configuration failed\n");
        return -1;
    }

    // Configure FFI/SFI/CDT (register 0x2C)
    if (i2cWriteByteData(i2c_handle, MPR121_FFI_SFI_CDT, 0x01) < 0) {
        fprintf(stderr, "Error: FFI/SFI/CDT configuration failed\n");
        return -1;
    }

    // Configure auto-config (registers 0x7B-0x7D)
    if (i2cWriteByteData(i2c_handle, MPR121_AUTOCONFIG_START, 0x01) < 0) {
        fprintf(stderr, "Error: Auto-config start failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_AUTOCONFIG_START + 1, 0x01) < 0) {
        fprintf(stderr, "Error: Auto-config start+1 failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_AUTOCONFIG_START + 2, 0x01) < 0) {
        fprintf(stderr, "Error: Auto-config start+2 failed\n");
        return -1;
    }

    // Enable exactly 12 electrodes by writing 0x0C to register 0x5E
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: Electrode configuration failed\n");
        return -1;
    }

    // Enable the sensor (start in system mode)
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x8F) < 0) { // Set Electrode Configuration register to 0x8F
        fprintf(stderr, "Error: Sensor enable failed\n");
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }

    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to toggle the relay
void toggle_relay() {
    int current_level = gpioRead(RELAY_GPIO);
    gpioWrite(RELAY_GPIO, !current_level);
    gpioDelay(200); // Debounce delay
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is initially OFF

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status;
    uint16_t last_touch_status = 0; // Store the last touch status

    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            // Check if electrode 0 is touched and was not previously touched
            if ((touch_status & 0x0001) && !(last_touch_status & 0x0001)) {
                toggle_relay();
            }
            last_touch_status = touch_status; // Update the last touch status
        } else {
            fprintf(stderr, "Error reading touch status, retrying...\n");
        }
        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF on exit
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated cleanly.\n");
    return 0;
}

