#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <stdarg.h>

// Configuration
#define SERVO_GPIO 17
#define PIR_GPIO 4
#define PORT 5000
#define LOG_FILE "security.log"
#define PWM_FREQUENCY 50
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)

// Global variables
static int server_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static volatile sig_atomic_t running = 1;

// Function prototypes
void *handle_client(void *arg);
void set_servo_angle(int angle);
int read_pir_sensor();
void log_event(const char *format, ...);
void signal_handler(int sig);
void cleanup();

// Helper function to get current timestamp in ISO 8601 format
void get_iso8601_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%SZ", info);
}

// Function to log events to syslog and file
void log_event(const char *format, ...)
{
    char timestamp[30];
    get_iso8601_timestamp(timestamp);

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s ", timestamp);
    strcat(log_message, format);

    va_list args;
    va_start(args, format);
    vsyslog(LOG_USER | LOG_INFO, log_message, args);
    va_end(args);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL)
    {
        va_list args;
        va_start(args, format);
        fprintf(fp, "%s ", timestamp);
        vfprintf(fp, format, args);
        fprintf(fp, "\n");
        va_end(args);
        fclose(fp);
    }
    else
    {
        syslog(LOG_USER | LOG_ERR, "Failed to open log file: %s", strerror(errno));
    }
}

// Function to set the servo angle using software PWM
void set_servo_angle(int angle)
{
    if (angle < 0 || angle > 180)
    {
        log_event("Invalid servo angle: %d", angle);
        return;
    }

    // Calculate pulse width in microseconds (1-2ms for 0-180 degrees)
    int pulse_width_us = (int)((angle / 180.0) * 19000.0 + 1000.0);

    // Software PWM implementation
    struct timespec on_time, off_time;
    on_time.tv_sec = 0;
    on_time.tv_nsec = pulse_width_us * 1000; // Convert us to ns
    off_time.tv_sec = 0;
    off_time.tv_nsec = (PWM_PERIOD_US - pulse_width_us) * 1000; // Convert us to ns

    if (gpiod_line_set_value(servo_line, 1) < 0)
    {
        log_event("Error setting servo line high: %s", strerror(errno));
        return;
    }
    nanosleep(&on_time, NULL);

    if (gpiod_line_set_value(servo_line, 0) < 0)
    {
        log_event("Error setting servo line low: %s", strerror(errno));
        return;
    }
    nanosleep(&off_time, NULL);
}

// Function to read the PIR sensor
int read_pir_sensor()
{
    int value = gpiod_line_get_value(pir_line);
    if (value < 0)
    {
        log_event("Error reading PIR sensor: %s", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to handle client connections in a separate thread
void *handle_client(void *arg)
{
    int client_fd = *(int *)arg;
    char buffer[1024];
    ssize_t bytes_received;

    while (running)
    {
        memset(buffer, 0, sizeof(buffer));
        bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received > 0)
        {
            log_event("Received: %s", buffer);

            char command[10];
            int angle;

            if (sscanf(buffer, "%9s %d", command, &angle) == 2)
            {
                if (strcmp(command, "SERVO") == 0)
                {
                    set_servo_angle(angle);
                }
                else
                {
                    log_event("Invalid command format");
                }
            }
            else if (strcmp(buffer, "PIR") == 0)
            {
                int pir_value = read_pir_sensor();
                if (pir_value != -1)
                {
                    char response[20];
                    snprintf(response, sizeof(response), "PIR:%d", pir_value);
                    send(client_fd, response, strlen(response), 0);
                    log_event("Sent: %s", response);
                }
            }
            else
            {
                log_event("Invalid command");
            }
        }
        else if (bytes_received == 0)
        {
            log_event("Client disconnected");
            break;
        }
        else
        {
            log_event("Error receiving data: %s", strerror(errno));
            break;
        }
    }

    close(client_fd);
    free(arg);
    pthread_exit(NULL);
    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    log_event("Signal received: %d. Shutting down...", sig);
    running = 0;
}

// Cleanup function to release resources
void cleanup()
{
    log_event("Cleaning up resources...");

    if (servo_line)
    {
        gpiod_line_release(servo_line);
    }
    if (pir_line)
    {
        gpiod_line_release(pir_line);
    }
    if (chip)
    {
        gpiod_chip_close(chip);
    }

    if (server_fd != -1)
    {
        close(server_fd);
    }

    log_event("Cleanup complete. Exiting.");
    closelog();
    exit(0);
}

int main()
{
    // Initialize syslog
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip)
    {
        log_event("Error opening GPIO chip: %s", strerror(errno));
        cleanup();
        return 1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_GPIO);
    if (!servo_line)
    {
        log_event("Error getting servo GPIO line: %s", strerror(errno));
        cleanup();
        return 1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line)
    {
        log_event("Error getting PIR GPIO line: %s", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(servo_line, "security_system", 0) < 0)
    {
        log_event("Error requesting servo GPIO line as output: %s", strerror(errno));
        cleanup();
        return 1;
    }

