#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define BH1750_CMD_HIGH_RES 0x20
#define GPIO_RELAY 23
#define LUX_THRESHOLD_LOW 150
#define LUX_THRESHOLD_HIGH 200
#define SAMPLE_INTERVAL_SEC 2

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750();
void control_relay(int state);
void log_data(int lux);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to read lux value from BH1750 sensor
int read_bh1750() {
    char buf[2];
    int lux = -1; // Default to error value
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, BH1750_CMD_HIGH_RES);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 120ms)
    gpioDelay(120000); // 120ms

    // Read 2 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert to lux
    unsigned int raw = (buf[0] << 8) | buf[1];
    lux = (int)(raw / 1.2);

    return lux;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(GPIO_RELAY, state);
}

// Function to log data to file
void log_data(int lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %d\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    int lux;
    int relay_state = 0; // 0 = off, 1 = on

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // I2C1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO_RELAY as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Grow light control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        lux = read_bh1750();

        if (lux >= 0) {
            log_data(lux);

            if (lux < LUX_THRESHOLD_LOW && relay_state == 0) {
                control_relay(1); // Turn on relay
                relay_state = 1;
                printf("Lux: %d, Turning ON relay\n", lux);
            } else if (lux > LUX_THRESHOLD_HIGH && relay_state == 1) {
                control_relay(0); // Turn off relay
                relay_state = 0;
                printf("Lux: %d, Turning OFF relay\n", lux);
            }
        } else {
            fprintf(stderr, "Error reading lux value. Retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Delay for 2 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_relay(0); // Turn off relay
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

