// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *dout_line, *sck_line, *sol_line;
static double tare_offset = 0.0;
static double scale = DEFAULT_SCALE;
static double threshold = DEFAULT_THRESHOLD;
static int solenoid_duration = DEFAULT_DURATION;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_hx711(int32_t *raw_value);
double calculate_weight(int32_t raw_value);
void tare_load_cell();
void control_solenoid(double weight);
void signal_handler(int sig);
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);
int gpio_get_value(int pin);

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    terminate = 1;
}

// GPIO export function
int gpio_export(int pin) {
    char buffer[64];
    int len;
    int fd;

    len = snprintf(buffer, sizeof(buffer), "/sys/class/gpio/export");
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open export for GPIO %d: %s", pin, strerror(errno));
        return -1;
    }
    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        syslog(LOG_ERR, "Failed to write to export for GPIO %d: %s", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// GPIO unexport function
int gpio_unexport(int pin) {
    char buffer[64];
    int len;
    int fd;

    len = snprintf(buffer, sizeof(buffer), "/sys/class/gpio/unexport");
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open unexport for GPIO %d: %s", pin, strerror(errno));
        return -1;
    }
    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        syslog(LOG_ERR, "Failed to write to unexport for GPIO %d: %s", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// GPIO set direction function
int gpio_set_direction(int pin, const char *direction) {
    char buffer[64];
    int fd;

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open direction for GPIO %d: %s", pin, strerror(errno));
        return -1;
    }
    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        syslog(LOG_ERR, "Failed to write to direction for GPIO %d: %s", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// GPIO set value function
int gpio_set_value(int pin, int value) {
    char buffer[64];
    int fd;

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open value for GPIO %d: %s", pin, strerror(errno));
        return -1;
    }
    if (value == 0) {
        if (write(fd, "0", 1) != 1) {
            syslog(LOG_ERR, "Failed to write to value for GPIO %d: %s", pin, strerror(errno));
            close(fd);
            return -1;
        }
    } else {
        if (write(fd, "1", 1) != 1) {
            syslog(LOG_ERR, "Failed to write to value for GPIO %d: %s", pin, strerror(errno));
            close(fd);
            return -1;
        }
    }
    close(fd);
    return 0;
}

// GPIO get value function
int gpio_get_value(int pin) {
    char buffer[64];
    int fd;
    char value_str[3];

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(buffer, O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open value for GPIO %d: %s", pin, strerror(errno));
        return -1;
    }
    if (read(fd, value_str, 3) < 0) {
        syslog(LOG_ERR, "Failed to read value for GPIO %d: %s", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return atoi(value_str);
}

// HX711 read function
int read_hx711(int32_t *raw_value) {
    int32_t value = 0;
