#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_KEEPALIVE 60
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to set the relay state using pigpio
int set_relay_state(int state) {
    if (gpioWrite(GPIO_PIN, state) != 0) {
        syslog(LOG_ERR, "Failed to write to GPIO %d", GPIO_PIN);
        return -1;
    }
    return 0;
}

// Function to handle MQTT messages
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, payload);

        if (strcmp(payload, "ON") == 0) {
            if (set_relay_state(1) != 0) {
                syslog(LOG_ERR, "Failed to set relay state to ON");
            }
        } else if (strcmp(payload, "OFF") == 0) {
            if (set_relay_state(0) != 0) {
                syslog(LOG_ERR, "Failed to set relay state to OFF");
            }
        } else {
            syslog(LOG_ERR, "Invalid payload received: %s", payload);
        }
    } else {
        syslog(LOG_ERR, "Empty payload received");
    }
}

// Function to handle MQTT connection
int connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        int subscribe_result = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (subscribe_result != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to topic %s: %s", MQTT_TOPIC, mosquitto_strerror(subscribe_result));
            running = 0; // Exit the loop if subscription fails
        }
    } else {
        syslog(LOG_ERR, "Connection failed: %s", mosquitto_connack_string(result));
    }
    return 0;
}

// Function to handle MQTT disconnection
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "Disconnected from MQTT broker with code %d", rc);
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

int main() {
    openlog("mqtt_relay", LOG_PID, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO17 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set initial relay state to OFF
    if (set_relay_state(0) != 0) {
        syslog(LOG_ERR, "Failed to set initial relay state to OFF");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new mosquitto client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto client instance");
        gpioTerminate();
        closelog();
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set callbacks
    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    // Connect to the MQTT broker
    int connect_result = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (connect_result != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(connect_result));
        mosquitto_destroy(mosq);
        gpioTerminate();
        closelog();
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int loop_result = mosquitto_loop(mosq, -1, 1);
        if (loop_result != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Mosquitto loop error: %s", mosquitto_strerror(loop_result));
            sleep(5);
            mosquitto_reconnect(mosq);
        }
    }

    // Cleanup
    set_relay_state(0); // Set relay to OFF before disconnecting
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    gpioTerminate();
    closelog();
    mosquitto_lib_cleanup();

    return 0;
}

