#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Motor B
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// PWM Frequency
#define PWM_FREQUENCY 10000

// Target Speed (RPM)
#define TARGET_SPEED 50.0

// PI Controller Gains
#define Kp 0.5
#define Ki 0.05

// Encoder Ticks per Revolution
#define TICKS_PER_REVOLUTION 64.0

// Control Loop Period (ms)
#define CONTROL_PERIOD 100

// Stall Detection Timeout (s)
#define STALL_TIMEOUT 2

// Global Variables
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
volatile int encoder_a_last_count = 0;
volatile int encoder_b_last_count = 0;
volatile int motor_a_pwm = 0;
volatile int motor_b_pwm = 0;
volatile int running = 1;

// Mutexes
pthread_mutex_t encoder_a_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder_b_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function Prototypes
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
int calculate_pwm(int encoder_count, int target_speed);
void stop_motors();
void signal_handler(int signal);
void *control_loop(void *arg);

// Encoder A ISR
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    int a_level = gpioRead(ENCODER_A_A);
    int b_level = gpioRead(ENCODER_A_B);

    pthread_mutex_lock(&encoder_a_mutex);
    if (gpio == ENCODER_A_A) {
        if (a_level == 1 && b_level == 0) {
            encoder_a_count++;
        } else if (a_level == 0 && b_level == 1) {
            encoder_a_count--;
        }
    } else if (gpio == ENCODER_A_B) {
        if (a_level == 0 && b_level == 1) {
            encoder_a_count++;
        } else if (a_level == 1 && b_level == 0) {
            encoder_a_count--;
        }
    }
    pthread_mutex_unlock(&encoder_a_mutex);
}

// Encoder B ISR
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    int a_level = gpioRead(ENCODER_B_A);
    int b_level = gpioRead(ENCODER_B_B);

    pthread_mutex_lock(&encoder_b_mutex);
    if (gpio == ENCODER_B_A) {
        if (a_level == 1 && b_level == 0) {
            encoder_b_count++;
        } else if (a_level == 0 && b_level == 1) {
            encoder_b_count--;
        }
    } else if (gpio == ENCODER_B_B) {
        if (a_level == 0 && b_level == 1) {
            encoder_b_count++;
        } else if (a_level == 1 && b_level == 0) {
            encoder_b_count--;
        }
    }
    pthread_mutex_unlock(&encoder_b_mutex);
}

// PI Controller
int calculate_pwm(int encoder_count, int target_speed) {
    static double integral = 0.0;
    double error = (double)target_speed - (double)encoder_count;
    integral += error;
    double output = Kp * error + Ki * integral;

    // Anti-windup
    if (output > 255.0) {
        output = 255.0;
        integral = error;
    } else if (output < 0.0) {
        output = 0.0;
        integral = error;
    }

    return (int)output;
}

// Stop Motors
void stop_motors() {
    gpioPWM(MOTOR_A_IN1, 0);
    gpioPWM(MOTOR_B_IN3, 0);
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    running = 0;
    stop_motors();
    gpioTerminate();
    exit(0);
}

// Control Loop Thread
void *control_loop(void *arg) {
    time_t start_time, current_time;
    int stall_a = 0, stall_b = 0;
    time(&start_time);

    while (running) {
        // Read encoder counts
        int current_encoder_a_count, current_encoder_b_count;
        pthread_mutex_lock(&encoder_a_mutex);
        current_encoder_a_count = encoder_a_count;
        pthread_mutex_unlock(&encoder_a_mutex);

        pthread_mutex_lock(&encoder_b_mutex);
        current_encoder_b_count = encoder_b_count;
        pthread_mutex_unlock(&encoder_b_mutex);

        // Calculate RPM
        int rpm_a = (current_encoder_a_count - encoder_a_last_count) * (60.0 / TICKS_PER_REVOLUTION);
        int rpm_b = (current_encoder_b_count - encoder_b_last_count) * (60.0 / TICKS_PER_REVOLUTION);

        // Calculate PWM duty cycles
        motor_a_pwm = calculate_pwm(rpm_a, (int)TARGET_SPEED);
        motor_b_pwm = calculate_pwm(rpm_b, (int)TARGET_SPEED);

        // Set PWM duty cycles
        gpioPWM(MOTOR_A_IN1, motor_a_pwm);
        gpioPWM(MOTOR_B_IN3, motor_b_pwm);

        // Update last encoder counts
        pthread_mutex_lock(&encoder_a_mutex);
        encoder_a_last_count = current_encoder_a_count;
        pthread_mutex_unlock(&encoder_a_mutex);

        pthread_mutex_lock(&encoder_b_mutex);
        encoder_b_last_count = current_encoder_b_count;
        pthread_mutex_unlock(&encoder_b_mutex);

        // Stall detection
        time(&current_time);
        double elapsed_time = difftime(current_time, start_time);

        if (current_encoder_a_count == 0) {
            stall_a++;
        } else {
            stall_a = 0;
        }

        if (current_encoder_b_count == 0) {
            stall_b++;
        } else {
            stall_b = 0;
        }

        if (stall_a > STALL_TIMEOUT * (1000.0 / CONTROL_PERIOD)) {
            fprintf(stderr, "Motor A stall detected!\n");
        }

        if (stall_b > STALL_TIMEOUT * (1000.0 / CONTROL_PERIOD)) {
            fprintf(stderr, "Motor B stall detected!\n");
        }

        // Print data
        printf("Motor A RPM: %d, PWM: %d, Motor B RPM: %d, PWM: %d\n", rpm_a, motor_a_pwm, rpm_b, motor_b_pwm);

        // Sleep for control period
        gpioDelay(CONTROL_PERIOD * 1000); // Convert ms to us
    }

    return NULL;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);
    gpioSetMode(ENCODER_A_A, PI_INPUT);
    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN1, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN3, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(MOTOR_A_IN1, 255);
    gpioSetPWMrange(MOTOR_B_IN3, 255);

    // Set PWM duty cycle to 0 initially
    gpioPWM(MOTOR_A_IN1, 0);
    gpioPWM(MOTOR_B_IN3, 0);

    // Set direction (forward)
    gpioWrite(MOTOR_A_IN2, 1);
    gpioWrite(MOTOR_B_IN4, 1);

    // Register ISRs
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder A A-phase\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder A B-phase\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder B A-phase\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder B B-phase\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Create control loop thread
    pthread_t control_thread;
    if (pthread_create(&control_thread, NULL, control_loop, NULL) != 0) {
        fprintf(stderr, "Failed to create control loop thread\n");
        gpioTerminate();
        return 1;
    }

    // Wait for control loop thread to finish
    pthread_join(control_thread, NULL);

    // Cleanup
    gpioTerminate();
    return 0;
}

