#define LUX_ON_THRESHOLD 50.0
#define LUX_OFF_THRESHOLD 200.0
#define I2C_BUS 1
#define LOG_FILE "chicken_coop_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    char config_cmd = 0x21; // One-Time High-Resolution Mode 2
    char buffer[2];
    int result;

    result = i2cWriteByte(i2c_handle, config_cmd);
    if (result != 0) {
        fprintf(stderr, "Failed to write config command: %d\n", result);
        return -1;
    }
    gpioDelay(180); // Wait 180ms as per datasheet

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read lux data: %d\n", result);
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Control the relay
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// Log data to file
int log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_GPIO, 0); // Turn off relay on exit
    gpioTerminate();
}

int main() {
    float lux;
    int relay_state = 0; // 0 = OFF, 1 = ON
    int last_relay_state = -1; // Initialize to an invalid state

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Chicken coop lighting system started.\n");

    while (program_running) {
        // Read lux value
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            // Hysteresis control
            if (lux < LUX_ON_THRESHOLD && relay_state == 0) {
                relay_state = 1;
            } else if (lux > LUX_OFF_THRESHOLD && relay_state == 1) {
                relay_state = 0;
            }

            // Control relay if state has changed
            if (relay_state != last_relay_state) {
                control_relay(relay_state);
                log_data(lux, relay_state);
                last_relay_state = relay_state;
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Turning off relay.\n");
            log_data(-1.0, 0); // Log error
            control_relay(0); // Turn off relay
            relay_state = 0; // Update relay state
            last_relay_state = 0;
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    cleanup();
    printf("Chicken coop lighting system stopped.\n");
    return 0;
}

