#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to store the relay state
static volatile int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_relay();
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, turning relay OFF and exiting...\n");
        gpioWrite(RELAY_PIN, 0); // Turn relay OFF
        gpioTerminate(); // Terminate pigpio
        exit(0); // Exit program
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF
    return 0; // Indicate success
}

// Function to read the touch sensor with debouncing
int read_touch_sensor() {
    int touch_state = gpioRead(TOUCH_SENSOR_PIN);
    if (touch_state == 1) {
        gpioDelay(DEBOUNCE_DELAY * 1000); // Delay for debouncing (microseconds)
        if (gpioRead(TOUCH_SENSOR_PIN) == 1) {
            return 1; // Valid touch
        }
    }
    return 0; // No touch or invalid touch
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state; // Toggle the relay state
    gpioWrite(RELAY_PIN, relay_state); // Set the relay pin
    log_relay_state(relay_state); // Log the relay state
}

// Function to log the relay state with timestamp
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Relay is now %s\n", timestamp, state ? "ON" : "OFF");
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (read_touch_sensor()) {
            toggle_relay();
            // Wait for the touch sensor to release
            while (gpioRead(TOUCH_SENSOR_PIN) == 1) {
                gpioDelay(10000); // Small delay to avoid busy-waiting (microseconds)
            }
        }
        gpioDelay(10000); // Sleep for 10 milliseconds (microseconds)
    }

    return 0; // This line will never be reached due to the infinite loop
}

