#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <string.h>

// Define GPIO pins
#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27

// Define LPM thresholds
#define LPM_HIGH_THRESHOLD 5.0
#define LPM_LOW_THRESHOLD 4.5

// Define debounce timeout (in milliseconds)
#define DEBOUNCE_TIMEOUT 1000

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file = NULL;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data);
double calculate_lpm(int pulses);
void control_solenoid(double lpm);
void log_data(double lpm, int solenoid_state);
void signal_handler(int signal);

// Pulse counter ISR function
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data)
{
    if (level == PI_HIGH) // Rising edge detected
    {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Function to calculate LPM
double calculate_lpm(int pulses)
{
    return ((double)pulses / 450.0) * 60.0;
}

// Function to control the solenoid valve
void control_solenoid(double lpm)
{
    int solenoid_state = gpioRead(SOLENOID_PIN);

    if (lpm > LPM_HIGH_THRESHOLD && solenoid_state == PI_HIGH)
    {
        gpioWrite(SOLENOID_PIN, PI_LOW); // Close the solenoid
        log_data(lpm, PI_LOW);
    }
    else if (lpm < LPM_LOW_THRESHOLD && solenoid_state == PI_LOW)
    {
        gpioWrite(SOLENOID_PIN, PI_HIGH); // Open the solenoid
        log_data(lpm, PI_HIGH);
    }
}

// Function to log data to file
void log_data(double lpm, int solenoid_state)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL)
    {
        fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state == PI_HIGH ? "OPEN" : "CLOSED");
        fflush(log_file); // Ensure data is written to disk immediately
    }
    else
    {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);

    // Open the solenoid to its safe state
    gpioWrite(SOLENOID_PIN, PI_HIGH);

    // Close the log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    // Destroy the mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0)
    {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set GPIO %d as output\n", SOLENOID_PIN);
        gpioTerminate();
        return 1;
    }

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0)
    {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up ISR with debounce timeout
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, DEBOUNCE_TIMEOUT, pulse_counter, NULL) != 0)
    {
        fprintf(stderr, "Failed to set ISR function\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1)
    {
        // Sample pulse count every 1 second
        gpioDelay(1000); // 1 second delay

        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count
        pthread_mutex_unlock(&pulse_mutex);

        // Calculate LPM
        double lpm = calculate_lpm(current_pulse_count);

        // Control solenoid
        control_solenoid(lpm);

        // Log data
        int solenoid_state = gpioRead(SOLENOID_PIN);
        log_data(lpm, solenoid_state);
    }

    return 0;
}

