        fprintf(stderr, "Failed to set GPIO %d as input\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set GPIO %d as output\n", SOLENOID_PIN);
        gpioTerminate();
        return 1;
    }

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0)
    {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up ISR with debounce timeout
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, DEBOUNCE_TIMEOUT, pulse_counter, NULL) != 0)
    {
        fprintf(stderr, "Failed to set ISR function\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1)
    {
        // Sample pulse count every 1 second
        gpioDelay(1000); // 1 second delay

        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count
        pthread_mutex_unlock(&pulse_mutex);

        // Calculate LPM
        double lpm = calculate_lpm(current_pulse_count);

        // Control solenoid
        control_solenoid(lpm);

        // Log data
        int solenoid_state = gpioRead(SOLENOID_PIN);
        log_data(lpm, solenoid_state);
    }

    return 0;
}

