// Configuration structure
typedef struct {
    char server_ip[20];
    int server_port;
    float calibration_factor;
} Config;

// Global variables
static int data_pin = 23;
static int sck_pin = 24;
static int servo_pin = 18;
static int server_socket = -1;
static int client_socket = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;
static Config config = {"127.0.0.1", 12345, 1.0};

// Function prototypes
int read_config(const char *filename, Config *config);
int init_gpio();
int init_servo();
int read_hx711();
float calibrate_weight(int raw_value, float calibration_factor);
int open_servo();
int close_servo();
int map_weight_to_pulsewidth(float weight);
int send_weight(int client_socket, float weight);
int receive_weight(int client_socket, float *weight);
int log_event(float target_weight, float actual_weight, const char *error_message);
void signal_handler(int signal);

// INI parser callback function
static int handler(void* user, const char* section, const char* name, const char* value)
{
    Config* pconfig = (Config*)user;

    #define MATCH(s, n) strcmp(section, s) == 0 && strcmp(name, n) == 0
    if (MATCH("server", "ip")) {
        strncpy(pconfig->server_ip, value, sizeof(pconfig->server_ip) - 1);
        pconfig->server_ip[sizeof(pconfig->server_ip) - 1] = '\0';
    } else if (MATCH("server", "port")) {
        pconfig->server_port = atoi(value);
    } else if (MATCH("calibration", "factor")) {
        pconfig->calibration_factor = atof(value);
    } else {
        return 0;  /* unknown section/name, error */
    }
    return 1;
}

// Read configuration from INI file
int read_config(const char *filename, Config *config) {
    if (ini_parse(filename, handler, config) < 0) {
        fprintf(stderr, "Can't load '%s'\n", filename);
        return -1;
    }
    return 0;
}

// Initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(sck_pin, PI_OUTPUT);
    gpioSetMode(servo_pin, PI_OUTPUT);

    return 0;
}

// Initialize servo motor
int init_servo() {
    gpioSetPWMfrequency(servo_pin, 50); // 50 Hz
    gpioSetPWMrange(servo_pin, 20000); // 20 kHz
    return 0;
}

// Read raw data from HX711
int read_hx711() {
    int data = 0;
    int timeout = 0;

    gpioWrite(sck_pin, 0);
    while (gpioRead(data_pin) == 1) {
        gpioDelay(1); // Wait for DATA to go low
        timeout++;
        if (timeout > 1000) {
            fprintf(stderr, "HX711 timeout\n");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(sck_pin, 1);
        gpioDelay(1);
        data = data << 1;
        if (gpioRead(data_pin)) {
            data++;
        }
        gpioWrite(sck_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(sck_pin, 1);
    gpioDelay(1);
    gpioWrite(sck_pin, 0);
    gpioDelay(1);

    data = data ^ 0x800000; // Convert to signed 24-bit integer

    return data;
}

// Calibrate weight
float calibrate_weight(int raw_value, float calibration_factor) {
    return (float)raw_value / calibration_factor;
}

// Open servo motor
