int map_weight_to_pulsewidth(float weight) {
    // Assuming a linear relationship between weight and pulse-width
    // and a range of 1000-2000 us for the servo
    return (int)(1000 + (weight / 100.0) * 1000); // Example: 1000 us per 100 grams
}

// Send weight to client
int send_weight(int client_socket, float weight) {
    char buffer[50];
    snprintf(buffer, sizeof(buffer), "%.2f", weight);
    if (send(client_socket, buffer, strlen(buffer), 0) < 0) {
        perror("send failed");
        return -1;
    }
    return 0;
}

// Receive weight from client
int receive_weight(int client_socket, float *weight) {
    char buffer[50];
    memset(buffer, 0, sizeof(buffer));
    if (recv(client_socket, buffer, sizeof(buffer) - 1, 0) < 0) {
        perror("recv failed");
        return -1;
    }
    if (sscanf(buffer, "%f", weight) != 1) {
        fprintf(stderr, "Invalid weight received\n");
        return -1;
    }
    return 0;
}

// Log dispensing event
int log_event(float target_weight, float actual_weight, const char *error_message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[50];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    FILE *fp = fopen("dispensing_log.json", "a");
    if (fp == NULL) {
        perror("fopen failed");
        return -1;
    }

    fprintf(fp, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error\": \"%s\"}\n",
            timestamp, target_weight, actual_weight, error_message);

    fclose(fp);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received, cleaning up...\n");
    terminate = 1;

    if (client_socket != -1) {
        close(client_socket);
    }
    if (server_socket != -1) {
        close(server_socket);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read configuration
    if (read_config("config.ini", &config) != 0) {
        fprintf(stderr, "Using default configuration\n");
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize servo
    if (init_servo() != 0) {
        gpioTerminate();
        return 1;
    }

    // Create socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("socket failed");
        gpioTerminate();
        return 1;
    }

    // Bind socket
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = inet_addr(config.server_ip);
    address.sin_port = htons(config.server_port);

    if (bind(server_socket, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_socket);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_socket, 3) < 0) {
        perror("listen failed");
        close(server_socket);
        gpioTerminate();
        return 1;
    }

    printf("Listening on %s:%d...\n", config.server_ip, config.server_port);

    // Accept connection
    int addrlen = sizeof(address);
    client_socket = accept(server_socket, (struct sockaddr *)&address, (socklen_t*)&addrlen);
    if (client_socket < 0) {
        perror("accept failed");
        close(server_socket);
        gpioTerminate();
        return 1;
    }

    printf("Connection accepted\n");

    float target_weight;
    if (receive_weight(client_socket, &target_weight) != 0) {
        log_event(0.0, 0.0, "Failed to receive target weight");
        close(client_socket);
        close(server_socket);
        gpioTerminate();
        return 1;
    }

    printf("Received target weight: %.2f grams\n", target_weight);

    // Dispense ingredient
    if (open_servo() != 0) {
        log_event(target_weight, 0.0, "Failed to open servo");
        close(client_socket);
        close(server_socket);
        gpioTerminate();
        return 1;
    }

    gpioDelay(1000); // Wait for load cell to stabilize

    int raw_value = read_hx711();
    if (raw_value < 0) {
        log_event(target_weight, 0.0, "Failed to read HX711");
        close_servo();
        close(client_socket);
        close(server_socket);
        gpioTerminate();
        return 1;
    }

    float actual_weight = calibrate_weight(raw_value, config.calibration_factor);
    printf("Actual weight: %.2f grams\n", actual_weight);

    if (send_weight(client_socket, actual_weight) != 0) {
        log_event(target_weight, actual_weight, "Failed to send actual weight");
        close_servo();
        close(client_socket);
        close(server_socket);
        gpioTerminate();
        return 1;
    }

    if (close_servo() != 0) {
        log_event(target_weight, actual_weight, "Failed to close servo");
        close(client_socket);
        close(server_socket);
        gpioTerminate();
        return 1;
    }

    log_event(target_weight, actual_weight, "");

    // Cleanup
    close(client_socket);
    close(server_socket);
    gpioTerminate();

    printf("Dispensing complete\n");

    return 0;
}

