#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Default debounce time in milliseconds
#define DEFAULT_DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static int relay_state = 0; // 0 = OFF, 1 = ON
static int debounce_time = DEFAULT_DEBOUNCE_TIME;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int debounce(int current_state, int *last_state, int *last_tick, int debounce_ms);
int toggle_relay();
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioWrite(RELAY_PIN, 0); // Turn off relay
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF

    return 0;
}

// Read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Debounce function
int debounce(int current_state, int *last_state, int *last_tick, int debounce_ms) {
    int now = gpioTick();
    if (current_state != *last_state) {
        if ((now - *last_tick) > (debounce_ms * 1000)) {
            *last_state = current_state;
            *last_tick = now;
            return current_state;
        }
    }
    return *last_state;
}

// Toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    return relay_state;
}

// Log the relay state with timestamp
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (state == 1) {
        printf("%s Relay: ON\n", timestamp);
    } else {
        printf("%s Relay: OFF\n", timestamp);
    }
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_time = atoi(optarg);
                if (debounce_time <= 0) {
                    fprintf(stderr, "Invalid debounce time. Using default value (%d ms).\n", DEFAULT_DEBOUNCE_TIME);
                    debounce_time = DEFAULT_DEBOUNCE_TIME;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d debounce_time_ms]\n", argv[0]);
                return 1;
        }
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int touch_state = 0;
    int last_touch_state = 0;
    int last_touch_tick = 0;
    int relay_state_changed = 0;

    printf("Touch-controlled relay switch started. Debounce time: %d ms\n", debounce_time);

    while (running) {
        touch_state = read_touch_sensor();
        touch_state = debounce(touch_state, &last_touch_state, &last_touch_tick, debounce_time);

        if (touch_state == 1 && last_touch_state == 0) {
            // Rising edge detected
            toggle_relay();
            log_relay_state(relay_state);
            relay_state_changed = 1;
        }

        if (relay_state_changed) {
            gpioDelay(100); // Small delay to prevent rapid toggling
            relay_state_changed = 0;
        }

        last_touch_state = touch_state;
        gpioDelay(1); // Small delay to reduce CPU usage
    }

    return 0;
}

