#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_GPIO 18
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define ANGLE_INCREMENT 10

static volatile int running = 1;
static struct termios original_termios;

// Function to set terminal to raw mode
int set_raw_mode(void) {
    struct termios raw;
    if (tcgetattr(0, &original_termios) < 0) {
        perror("tcgetattr failed");
        return -1;
    }

    raw = original_termios;
    raw.c_lflag &= ~(ICANON | ECHO); // Disable canonical mode and echo
    raw.c_cc[VMIN] = 1;  // Read at least one character
    raw.c_cc[VTIME] = 0; // No timeout

    if (tcsetattr(0, TCSANOW, &raw) < 0) {
        perror("tcsetattr failed");
        return -1;
    }
    return 0;
}

// Function to restore terminal settings
void restore_terminal(void) {
    if (tcsetattr(0, TCSANOW, &original_termios) < 0) {
        perror("tcsetattr failed");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to map angle to pulse width
int angle_to_pulse_width(int angle) {
    return MIN_PULSE_WIDTH + (int)(((float)(angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));
}

int main() {
    int angle = 90;
    int pulse_width;
    char input;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 to output mode
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_GPIO, PWM_FREQUENCY);

    // Set PWM range (optional, but recommended)
    gpioSetPWMrange(SERVO_GPIO, 1000000); // Range of 1000000 for microseconds

    // Set initial angle
    pulse_width = angle_to_pulse_width(angle);
    gpioServo(SERVO_GPIO, pulse_width);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set terminal to raw mode
    if (set_raw_mode() < 0) {
        fprintf(stderr, "Failed to set raw mode\n");
        gpioTerminate();
        return 1;
    }

    printf("Servo control. Use '+' and '-' to increase/decrease angle. Press 'q' to quit.\n");

    while (running) {
        // Read input character
        input = getchar();

        // Process input
        switch (input) {
            case '+':
                angle += ANGLE_INCREMENT;
                if (angle > MAX_ANGLE) {
                    angle = MAX_ANGLE;
                }
                break;
            case '-':
                angle -= ANGLE_INCREMENT;
                if (angle < MIN_ANGLE) {
                    angle = MIN_ANGLE;
                }
                break;
            case 'q':
                running = 0;
                break;
            default:
                // Ignore other characters
                continue;
        }

        // Update servo position
        pulse_width = angle_to_pulse_width(angle);
        gpioServo(SERVO_GPIO, pulse_width);

        // Print current angle
        printf("Angle: %d, Pulse Width: %d\n", angle, pulse_width);
    }

    // Stop PWM pulses
    gpioServo(SERVO_GPIO, 0);

    // Restore terminal settings
    restore_terminal();

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

