#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_NS 2000000 // 2 milliseconds in nanoseconds

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;
static volatile unsigned long pulse_count = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get current timestamp in ISO 8601 format
int get_iso8601_timestamp(char *timestamp)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }

    strftime(timestamp, 32, "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), 32 - strlen(timestamp), ".%09ldZ", ts.tv_nsec);
    return 0;
}

// Function to log RPM data to file
int log_rpm(double rpm)
{
    char timestamp[32];
    if (get_iso8601_timestamp(timestamp) != 0) {
        fprintf(stderr, "Error getting timestamp.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, rpm) < 0) {
        perror("fprintf");
        return -1;
    }
    fflush(log_file);
    return 0;
}

// Function to calculate RPM
double calculate_rpm(unsigned long pulse_count, double time_interval_seconds)
{
    return ((double)pulse_count / time_interval_seconds) * 60.0;
}

// Function to handle GPIO events
void handle_gpio_event(struct gpiod_line *line)
{
    struct timespec start_time, end_time;
    if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
        perror("clock_gettime (start)");
        return;
    }

    // Wait for the rising edge to go away
    if (gpiod_line_wait_for_rising_edge(line, NULL) == -1) {
        perror("gpiod_line_wait_for_rising_edge");
        return;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &end_time) == -1) {
        perror("clock_gettime (end)");
        return;
    }

    // Calculate the time difference in nanoseconds
    long time_diff_ns = (end_time.tv_sec - start_time.tv_sec) * 1000000000L + (end_time.tv_nsec - start_time.tv_nsec);

    // Debounce the signal
    if (time_diff_ns > DEBOUNCE_DELAY_NS) {
        pulse_count++;
    }
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line as input with pull-up
    if (gpiod_line_request_input_flags(line, "motor_rpm_monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("motor_rpm.log", "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    unsigned long local_pulse_count = 0;
    double rpm;
    struct timespec sleep_time = {5, 0}; // 5 seconds

    printf("Monitoring motor RPM... Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Reset local pulse count
        local_pulse_count = pulse_count;
        pulse_count = 0;

        // Wait for 5 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            if (errno == EINTR) {
                fprintf(stderr, "nanosleep interrupted by signal.\n");
            } else {
                perror("nanosleep");
            }
        }

        // Calculate RPM
        rpm = calculate_rpm(local_pulse_count, 5.0);

        // Log RPM data
        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Error logging RPM data.\n");
        }

        // Print RPM to stdout
        printf("RPM: %.2f\n", rpm);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

