#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON 1
#define RELAY_OFF 0
#define TOUCH_DEBOUNCE_MS 50
#define FAILSAFE_TIMEOUT_S 10

// Global variables
volatile sig_atomic_t program_running = 1;
time_t last_touch_time = 0;
int relay_state = RELAY_OFF;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int toggle_relay();
void failsafe_check();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set TOUCH_SENSOR_PIN to input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RELAY_PIN to output\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(RELAY_PIN, relay_state); // Initialize relay state
    return 0;
}

// Read the touch sensor with debouncing
int read_touch_sensor() {
    int touch_value = gpioRead(TOUCH_SENSOR_PIN);
    if (touch_value < 0) {
        fprintf(stderr, "Error reading TOUCH_SENSOR_PIN\n");
        return -1; // Indicate an error
    }
    gpioDelay(TOUCH_DEBOUNCE_MS * 1000); // Debounce delay
    return touch_value;
}

// Toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Failed to write to RELAY_PIN\n");
        return 1;
    }
    return 0;
}

// Failsafe check
void failsafe_check() {
    time_t current_time = time(NULL);
    if (last_touch_time != 0 && difftime(current_time, last_touch_time) > FAILSAFE_TIMEOUT_S) {
        printf("Failsafe triggered! Forcing relay OFF.\n");
        relay_state = RELAY_OFF;
        gpioWrite(RELAY_PIN, relay_state);
        last_touch_time = 0; // Reset last touch time to prevent repeated triggering
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(RELAY_PIN, RELAY_OFF); // Turn off the relay
    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

