#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Define PWM range
#define PWM_RANGE 255

// Define pulse to liter conversion factor
#define PULSES_PER_LITER 450.0

// Define proportional gain
#define KP 1.0

// Define pulse accumulation interval (in milliseconds)
#define PULSE_ACCUMULATION_INTERVAL 100

// Define control loop interval (in milliseconds)
#define CONTROL_LOOP_INTERVAL 100

// Global variables
volatile int pulse_count = 0;
double target_flow_rate = 0.0;
FILE *log_file = NULL;

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate(int pulse_count);
int calculate_valve_position(double flow_rate, double target_flow_rate);
void log_data(double flow_rate, int valve_position);
void signal_handler(int signal);

// Interrupt service routine for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data)
{
    (void)gpio; // unused
    (void)level; // unused
    (void)tick;  // unused
    (void)user_data; // unused
    pulse_count++;
}

// Function to calculate flow rate in L/min
double calculate_flow_rate(int pulse_count)
{
    return (double)pulse_count / PULSES_PER_LITER * (60000.0 / PULSE_ACCUMULATION_INTERVAL); // pulses/liter * (60 sec/min) / (accumulation interval in ms)
}

// Function to calculate valve position based on proportional control
int calculate_valve_position(double flow_rate, double target_flow_rate)
{
    double error = target_flow_rate - flow_rate;
    double output = KP * error;
    int valve_position = (int)output;

    // Clamp the valve position to the valid range
    if (valve_position < 0)
    {
        valve_position = 0;
    }
    else if (valve_position > PWM_RANGE)
    {
        valve_position = PWM_RANGE;
    }

    return valve_position;
}

// Function to log data to file
void log_data(double flow_rate, int valve_position)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, flow_rate, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);

    // Disable the valve
    gpioWrite(VALVE_ENABLE_PIN, 0);

    // Set PWM to 0
    gpioPWM(VALVE_PWM_PIN, 0);

    // Close the log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main(int argc, char *argv[])
{
    // Parse command-line arguments
    if (argc != 2)
    {
        fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
        return 1;
    }

    if (strcmp(argv[1], "-t") != 0)
    {
        fprintf(stderr, "Error: Invalid argument. Usage: %s -t <target_flow_rate>\n", argv[0]);
        return 1;
    }

    if (argc < 3)
    {
        fprintf(stderr, "Error: Target flow rate is missing. Usage: %s -t <target_flow_rate>\n", argv[0]);
        return 1;
    }

    char *endptr;
    target_flow_rate = strtod(argv[2], &endptr);

    if (*endptr != '\0' || target_flow_rate <= 0.0)
    {
        fprintf(stderr, "Error: Invalid target flow rate. Must be a positive number.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT);
    gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE);

    // Enable the valve
    gpioWrite(VALVE_ENABLE_PIN, 1);

    // Open the log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register interrupt service routine
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0)
    {
        fprintf(stderr, "Error: Could not register ISR\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (1)
    {
        // Reset pulse count
        int current_pulse_count = pulse_count;
        pulse_count = 0;

        // Calculate flow rate
        double flow_rate = calculate_flow_rate(current_pulse_count);

        // Calculate valve position
        int valve_position = calculate_valve_position(flow_rate, target_flow_rate);

        // Set valve position
        gpioPWM(VALVE_PWM_PIN, valve_position);

        // Log data
        log_data(flow_rate, valve_position);

        // Sleep for the control loop interval
        gpioDelay(CONTROL_LOOP_INTERVAL * 1000); // Convert ms to us
    }

    return 0;
}

