#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK_1_PIN 17
#define LOCK_2_PIN 27
#define BUTTON_PIN 22

// Define SPI channel
#define SPI_CHANNEL 0
#define SPI_SPEED 100000 // 100 kHz

// Define valid RFID tag
const unsigned char VALID_TAG[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};
const int VALID_TAG_LENGTH = sizeof(VALID_TAG);

// Define log file path
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rfid_tag(unsigned char *tag);
int validate_tag(const unsigned char *tag);
int button_pressed();
void disengage_locks();
void engage_locks();
void log_event(const char *event);
void signal_handler(int signal);

// Function to read RFID tag via SPI
int read_rfid_tag(unsigned char *tag) {
    char tx_buf[1] = {0x00}; // Dummy byte for reading
    char rx_buf[VALID_TAG_LENGTH];
    int result;

    result = spiXfer(spi_handle, tx_buf, rx_buf, VALID_TAG_LENGTH);
    if (result != VALID_TAG_LENGTH) {
        log_event("RFID read failure");
        return -1; // Indicate failure
    }

    memcpy(tag, rx_buf, VALID_TAG_LENGTH);
    return 0; // Indicate success
}

// Function to validate RFID tag
int validate_tag(const unsigned char *tag) {
    return (memcmp(tag, VALID_TAG, VALID_TAG_LENGTH) == 0);
}

// Function to detect button press with debouncing
int button_pressed() {
    static unsigned long last_press_time = 0;
    unsigned long current_time = gpioTick();

    if (gpioRead(BUTTON_PIN) == 0) { // Button is active low
        if (current_time - last_press_time > 50000) { // 50 ms debounce
            last_press_time = current_time;
            return 1; // Button pressed
        }
    }
    return 0; // Button not pressed or debouncing
}

// Function to disengage locks
void disengage_locks() {
    gpioWrite(LOCK_1_PIN, 0); // Lock 1
    gpioWrite(LOCK_2_PIN, 0); // Lock 2
    gpioDelay(5000000);       // 5 seconds
    engage_locks();
}

// Function to engage locks
void engage_locks() {
    gpioWrite(LOCK_1_PIN, 1); // Lock 1
    gpioWrite(LOCK_2_PIN, 1); // Lock 2
}

// Function to log events with ISO-8601 timestamp
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(log_file, "%s: %s\n", buf, event);
    fflush(log_file); // Ensure immediate write
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 100kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK_1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char tag[VALID_TAG_LENGTH];
    int rfid_read_result;
    int button_press_result;

    printf("Two-Factor Authentication System running...\n");

    while (!terminate) {
        rfid_read_result = read_rfid_tag(tag);
        if (rfid_read_result == 0) {
            if (validate_tag(tag)) {
                log_event("Valid RFID tag read");
                button_press_result = button_pressed();
                if (button_press_result) {
                    log_event("Button pressed");
                    log_event("Successful authentication");
                    disengage_locks();
                } else {
                    log_event("Button not pressed");
                }
            } else {
                log_event("Invalid RFID tag");
            }
        } else {
            // RFID read failure is already logged in read_rfid_tag
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    engage_locks(); // Engage locks
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

