#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID Constants
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Target RPMs
#define TARGET_RPM 60.0

// PWM Frequency (Hz)
#define PWM_FREQUENCY 100.0

// PWM Period (seconds)
#define PWM_PERIOD (1.0 / PWM_FREQUENCY)

// Encoder Pulses Per Revolution
#define ENCODER_PPR 600.0

// Encoder Counts Per Revolution
#define ENCODER_CPR (ENCODER_PPR / 4.0) // Assuming quadrature encoding

// Encoder Scaling Factor (counts per second to RPM)
#define ENCODER_SCALE (60.0 / ENCODER_CPR)

// Encoder 1
static volatile int encoder1_count = 0;
static pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;

// Encoder 2
static volatile int encoder2_count = 0;
static pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

// Global flag to signal program termination
static volatile int terminate = 0;

// File pointer for logging
FILE *log_file = NULL;

// Function Prototypes
void *encoder1_thread(void *arg);
void *encoder2_thread(void *arg);
double calculate_pid(double setpoint, double actual, double *integral, double *previous_error);
void set_motor_speed(int motor_num, double duty_cycle);
void stop_motors();
void signal_handler(int signal);
void log_data(double motor1_rpm, double motor2_rpm, double pid1_p, double pid1_i, double pid1_d, double pid1_output, double pid2_p, double pid2_i, double pid2_d, double pid2_output);

// Encoder 1 Interrupt Handler
void encoder1_interrupt(int gpio, int level, uint32_t tick, void *user)
{
    int b_level = gpioRead(ENCODER1_B);

    if (gpio == ENCODER1_A)
    {
        if (b_level == 0)
        {
            pthread_mutex_lock(&encoder1_mutex);
            encoder1_count++;
            pthread_mutex_unlock(&encoder1_mutex);
        }
        else if (b_level == 1)
        {
            pthread_mutex_lock(&encoder1_mutex);
            encoder1_count--;
            pthread_mutex_unlock(&encoder1_mutex);
        }
    }
}

// Encoder 2 Interrupt Handler
void encoder2_interrupt(int gpio, int level, uint32_t tick, void *user)
{
    int b_level = gpioRead(ENCODER2_B);

    if (gpio == ENCODER2_A)
    {
        if (b_level == 0)
        {
            pthread_mutex_lock(&encoder2_mutex);
            encoder2_count++;
            pthread_mutex_unlock(&encoder2_mutex);
        }
        else if (b_level == 1)
        {
            pthread_mutex_lock(&encoder2_mutex);
            encoder2_count--;
            pthread_mutex_unlock(&encoder2_mutex);
        }
    }
}

// Encoder 1 Thread Function
void *encoder1_thread(void *arg)
{
    while (!terminate)
    {
        // Placeholder for encoder 1 thread logic
        // This thread could perform additional tasks or sleep to reduce CPU usage
        sleep(1); // Sleep for 1 second
    }
