}

// Encoder 2 Thread Function
void *encoder2_thread(void *arg)
{
    while (!terminate)
    {
        // Placeholder for encoder 2 thread logic
        // This thread could perform additional tasks or sleep to reduce CPU usage
        sleep(1); // Sleep for 1 second
    }
    return NULL;
}

// PID Calculation Function
double calculate_pid(double setpoint, double actual, double *integral, double *previous_error)
{
    double error = setpoint - actual;
    *integral += error;
    double derivative = error - *previous_error;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Motor Control Function
void set_motor_speed(int motor_num, double duty_cycle)
{
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;

    int on_time_us = (int)(duty_cycle * PWM_PERIOD * 1000000.0);
    int off_time_us = (int)((1.0 - duty_cycle) * PWM_PERIOD * 1000000.0);

    if (motor_num == 1)
    {
        gpioWrite(MOTOR1_ENA, 1); // Enable motor
        gpioWrite(MOTOR1_IN1, 1);
        gpioWrite(MOTOR1_IN2, 0);
        gpioDelay(on_time_us);
        gpioWrite(MOTOR1_IN1, 0);
        gpioWrite(MOTOR1_IN2, 0);
        gpioDelay(off_time_us);
    }
    else if (motor_num == 2)
    {
        gpioWrite(MOTOR2_ENB, 1); // Enable motor
        gpioWrite(MOTOR2_IN3, 1);
        gpioWrite(MOTOR2_IN4, 0);
        gpioDelay(on_time_us);
        gpioWrite(MOTOR2_IN3, 0);
        gpioWrite(MOTOR2_IN4, 0);
        gpioDelay(off_time_us);
    }
}

// Stop Motors Function
void stop_motors()
{
    gpioWrite(MOTOR1_ENA, 0); // Disable motor 1
    gpioWrite(MOTOR2_ENB, 0); // Disable motor 2
}

// Signal Handler Function
void signal_handler(int signal)
{
    printf("Caught signal %d, terminating...\n", signal);
