    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    gpioTerminate();

    if (log_file != NULL)
    {
        fclose(log_file);
    }

    exit(0);
}

// Logging Function
void log_data(double motor1_rpm, double motor2_rpm, double pid1_p, double pid1_i, double pid1_d, double pid1_output, double pid2_p, double pid2_i, double pid2_d, double pid2_output)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

