    gpioSetPullUpDown(ENCODER2_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER2_B, PI_PUD_UP);

    // Set up interrupts for encoder 1
    gpioSetISRFuncEx(ENCODER1_A, EITHER_EDGE, 0, encoder1_interrupt, NULL);

    // Set up interrupts for encoder 2
    gpioSetISRFuncEx(ENCODER2_A, EITHER_EDGE, 0, encoder2_interrupt, NULL);

    // Initialize PID variables
    double motor1_integral = 0.0;
    double motor1_previous_error = 0.0;
    double motor2_integral = 0.0;
    double motor2_previous_error = 0.0;

    // Initialize target RPMs
    double target_rpm1 = TARGET_RPM;
    double target_rpm2 = TARGET_RPM;

