        set_motor_speed(2, motor2_duty_cycle);

        // Log data
        log_data(motor1_rpm, motor2_rpm, motor1_previous_error, motor1_integral, 0.0, pid1_output, motor2_previous_error, motor2_integral, 0.0, pid2_output);

        // Sleep for 100 ms (10 Hz)
        gpioDelay(100000); // 100 ms
    }

    // Clean up
    pthread_join(encoder1_thread_id, NULL);
    pthread_join(encoder2_thread_id, NULL);
    stop_motors();
    gpioTerminate();
    fclose(log_file);

    return 0;
}

