#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPR121 I2C address
#define MPR121_ADDR 0x5A

// MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_BASELINE_FILTER_CONFIG 0x5D
#define MPR121_TOUCH_THRESHOLD_0 0x41
#define MPR121_RELEASE_THRESHOLD_0 0x42

// GPIO pin for relay control
#define RELAY_GPIO 17

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status(uint16_t *touch_status);
void relay_on();
void relay_off();
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// MPR121 initialization function
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure filtering (example values)
    if (i2cWriteByteData(i2c_handle, MPR121_BASELINE_FILTER_CONFIG, 0x10) < 0) {
        fprintf(stderr, "Error: Baseline filter config failed\n");
        return -1;
    }

    // Set touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCH_THRESHOLD_0 + 2 * i, 0x30) < 0) {
            fprintf(stderr, "Error: Touch threshold config failed for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_RELEASE_THRESHOLD_0 + 2 * i, 0x10) < 0) {
            fprintf(stderr, "Error: Release threshold config failed for electrode %d\n", i);
            return -1;
        }
    }

    // Enable run mode
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: Run mode enable failed\n");
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int mpr121_read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }

    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to turn the relay ON
void relay_on() {
    gpioWrite(RELAY_GPIO, 1); // Set GPIO HIGH
    log_relay_state(1);
}

// Function to turn the relay OFF
void relay_off() {
    gpioWrite(RELAY_GPIO, 0); // Set GPIO LOW
    log_relay_state(0);
}

// Function to log relay state changes
void log_relay_state(int state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - Relay is now %s\n", timestamp, state ? "ON" : "OFF");
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t touch_status;
    int relay_state = 0; // 0 = OFF, 1 = ON

    // Main loop
    while (program_running) {
        if (mpr121_read_touch_status(&touch_status) == 0) {
            if (touch_status > 0) {
                if (relay_state == 0) {
                    relay_on();
                    relay_state = 1;
                }
            } else {
                if (relay_state == 1) {
                    relay_off();
                    relay_state = 0;
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
            // Attempt to re-initialize I2C and MPR121
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: I2C re-open failed\n");
                program_running = 0; // Exit loop if re-initialization fails
            } else {
                if (mpr121_init() < 0) {
                    fprintf(stderr, "Error: MPR121 re-initialisation failed\n");
                    program_running = 0; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(50); // Poll every 50 ms
    }

    // Cleanup
    relay_off(); // Ensure relay is off before exiting
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

