#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for the valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the log file name
#define LOG_FILE "valve_log.txt"

// Global variables for GPIO lines and the log file
struct gpiod_line *valve1_line = NULL;
struct gpiod_line *valve2_line = NULL;
struct gpiod_chip *gpio_chip = NULL;
FILE *log_file = NULL;

// Function prototypes
int gpio_init(void);
int valve_control(int valve_number, int duration_ms);
int log_event(int valve_number, int duration_ms);
void signal_handler(int signal);
void cleanup(void);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to initialize the GPIO lines
int gpio_init(void) {
    int ret;

    // Open the GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the GPIO line for Valve 1
    valve1_line = gpiod_chip_get_line(gpio_chip, VALVE1_GPIO);
    if (!valve1_line) {
        perror("Error getting Valve 1 GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request the GPIO line for output
    ret = gpiod_line_request_output(valve1_line, "valve_control", 0);
    if (ret < 0) {
        perror("Error requesting Valve 1 GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Get the GPIO line for Valve 2
    valve2_line = gpiod_chip_get_line(gpio_chip, VALVE2_GPIO);
    if (!valve2_line) {
        perror("Error getting Valve 2 GPIO line");
        gpiod_line_release(valve1_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request the GPIO line for output
    ret = gpiod_line_request_output(valve2_line, "valve_control", 0);
    if (ret < 0) {
        perror("Error requesting Valve 2 GPIO line for output");
        gpiod_line_release(valve1_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to control the valves
int valve_control(int valve_number, int duration_ms) {
    int ret;
    struct timespec ts;

    // Get the current time
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    // Activate the valve
    if (valve_number == 1) {
        ret = gpiod_line_set_value(valve1_line, 1);
        if (ret < 0) {
            perror("Error setting Valve 1 GPIO line value");
            return -1;
        }
    } else if (valve_number == 2) {
        ret = gpiod_line_set_value(valve2_line, 1);
        if (ret < 0) {
            perror("Error setting Valve 2 GPIO line value");
            return -1;
        }
    } else {
        fprintf(stderr, "Invalid valve number: %d\n", valve_number);
        return -1;
    }

    // Log the event
    if (log_event(valve_number, duration_ms) != 0) {
        fprintf(stderr, "Error logging event.\n");
    }

    // Wait for the specified duration
    struct timespec req, rem;
    req.tv_sec = duration_ms / 1000;
    req.tv_nsec = (duration_ms % 1000) * 1000000;

    nanosleep(&req, &rem);

    // Deactivate the valve
    if (valve_number == 1) {
        ret = gpiod_line_set_value(valve1_line, 0);
        if (ret < 0) {
            perror("Error setting Valve 1 GPIO line value");
            return -1;
        }
    } else if (valve_number == 2) {
        ret = gpiod_line_set_value(valve2_line, 0);
        if (ret < 0) {
            perror("Error setting Valve 2 GPIO line value");
            return -1;
        }
    }

    return 0;
}

// Function to log the valve activation event
int log_event(int valve_number, int duration_ms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    // Get the current time
    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    // Format the timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    // Write the log entry
    fprintf(log_file, "%s Valve %d activated for %d ms\n", timestamp, valve_number, duration_ms);

    // Close the log file
    fclose(log_file);

    return 0;
}

// Function to clean up GPIO resources and close the log file
void cleanup(void) {
    int ret;

    // Deactivate both valves
    if (valve1_line) {
        ret = gpiod_line_set_value(valve1_line, 0);
        if (ret < 0) {
            perror("Error setting Valve 1 GPIO line value during cleanup");
        }
        gpiod_line_release(valve1_line);
    }
    if (valve2_line) {
        ret = gpiod_line_set_value(valve2_line, 0);
        if (ret < 0) {
            perror("Error setting Valve 2 GPIO line value during cleanup");
        }
        gpiod_line_release(valve2_line);
    }

    // Close the GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close the log file
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO lines
    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Automated greenhouse water distribution started.\n");

    // Main loop
    while (1) {
        // Activate Valve 1 for 500 ms
        if (valve_control(1, 500) != 0) {
            fprintf(stderr, "Error controlling Valve 1.\n");
        }

        // Pause for 5 seconds
        struct timespec req, rem;
        req.tv_sec = 5;
        req.tv_nsec = 0;
        nanosleep(&req, &rem);

        // Activate Valve 2 for 1000 ms
        if (valve_control(2, 1000) != 0) {
            fprintf(stderr, "Error controlling Valve 2.\n");
        }

        // Pause for 10 seconds
        req.tv_sec = 10;
        req.tv_nsec = 0;
        nanosleep(&req, &rem);
    }

    return 0;
}

