#include <time.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define POLL_INTERVAL_MS 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static unsigned long last_unlock_time = 0;

// Function prototypes
int initialize_gpio();
int detect_motion();
void unlock_door();
void log_event(const char *event_type, const char *message);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int pir_pin;
    int relay_pin;
} gpio_config_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Detect motion using the PIR sensor
int detect_motion() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Unlock the door by activating the relay
void unlock_door() {
    gpioWrite(RELAY_PIN, 1); // Activate relay
    gpioDelay(UNLOCK_DURATION_MS * 1000); // Delay for unlock duration
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
}

// Log events to the log file
void log_event(const char *event_type, const char *message) {
    if (log_file == NULL) return; // Check if log file is open

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&(ts.tv_sec)));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s [%s]: %s\n", timestamp, event_type, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Door unlock system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (detect_motion()) {
            unsigned long current_time = gpioTick();
            if (current_time - last_unlock_time > RATE_LIMIT_MS * 1000) {
                log_event("Motion Detected", "Motion detected by PIR sensor");
                unlock_door();
                log_event("Door Unlocked", "Door unlocked for 500ms");
                last_unlock_time = current_time;
            } else {
                log_event("Rate Limited", "Motion detected, but rate limited");
            }
        }
        gpioDelay(POLL_INTERVAL_MS * 1000); // Poll every 50ms
    }

    cleanup();
    return 0;
}

