    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Failed to set GPIO %d mode to %d\n", pin, mode);
        return -1;
    }
    return 0;
}

// Function to set the PWM frequency for a pin
int set_pwm_frequency(int pin, int frequency) {
    if (gpioSetPWMfrequency(pin, frequency) != frequency) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d to %d\n", pin, frequency);
        return -1;
    }
    return 0;
}

// Function to generate a random integer within a specified range
int generate_random_integer(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to generate a haptic pattern
HapticPattern generate_pattern() {
    HapticPattern pattern;
    pattern.length = generate_random_integer(MIN_PATTERN_LENGTH, MAX_PATTERN_LENGTH);

    pattern.motor1_duty_cycles = (int *)malloc(pattern.length * sizeof(int));
    pattern.motor2_duty_cycles = (int *)malloc(pattern.length * sizeof(int));
    pattern.durations = (int *)malloc(pattern.length * sizeof(int));

    if (pattern.motor1_duty_cycles == NULL || pattern.motor2_duty_cycles == NULL || pattern.durations == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        // Handle memory allocation failure (e.g., set pointers to NULL and return)
        pattern.motor1_duty_cycles = NULL;
        pattern.motor2_duty_cycles = NULL;
        pattern.durations = NULL;
        pattern.length = 0; // Indicate failure
        return pattern;
    }

    for (int i = 0; i < pattern.length; i++) {
        pattern.motor1_duty_cycles[i] = generate_random_integer(MIN_DUTY_CYCLE, MAX_DUTY_CYCLE);
        pattern.motor2_duty_cycles[i] = generate_random_integer(MIN_DUTY_CYCLE, MAX_DUTY_CYCLE);
        pattern.durations[i] = generate_random_integer(MIN_DURATION, MAX_DURATION);
    }

    return pattern;
}

// Function to play a haptic pattern
void play_pattern(HapticPattern pattern) {
    if (pattern.motor1_duty_cycles == NULL || pattern.motor2_duty_cycles == NULL || pattern.durations == NULL) {
        fprintf(stderr, "Invalid haptic pattern, cannot play\n");
        return;
    }

    for (int i = 0; i < pattern.length; i++) {
        gpioPWM(MOTOR1_PIN, pattern.motor1_duty_cycles[i]);
        gpioPWM(MOTOR2_PIN, pattern.motor2_duty_cycles[i]);
        gpioDelay(pattern.durations[i]);
    }
}

// Function to free the memory allocated for a haptic pattern
void free_pattern(HapticPattern pattern) {
    if (pattern.motor1_duty_cycles != NULL) free(pattern.motor1_duty_cycles);
    if (pattern.motor2_duty_cycles != NULL) free(pattern.motor2_duty_cycles);
    if (pattern.durations != NULL) free(pattern.durations);
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Set GPIO modes
    if (set_gpio_mode(MOTOR1_PIN, PI_OUTPUT) != 0 || set_gpio_mode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    if (set_pwm_frequency(MOTOR1_PIN, PWM_FREQUENCY) != 0 || set_pwm_frequency(MOTOR2_PIN, PWM_FREQUENCY) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!shutdown) {
        // Generate a haptic pattern
        HapticPattern pattern = generate_pattern();

        // Play the pattern
        if (pattern.length > 0) {
            play_pattern(pattern);
            free_pattern(pattern);
        }
    }

    // Stop the motors
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

