#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Default calibration values
#define DEFAULT_SCALE 1.0
#define DEFAULT_OFFSET 0.0

// Calibration file path
#define CALIBRATION_FILE "calibration.txt"

// Log file path
#define LOG_FILE "weight_log.txt"

// Weight threshold in kg
#define WEIGHT_THRESHOLD 10.0

// Timeout for HX711 reading (in seconds)
#define HX711_TIMEOUT 0.5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Calibration data
static double scale_factor = DEFAULT_SCALE;
static double offset = DEFAULT_OFFSET;

// Function prototypes
int read_calibration_data(const char *filename, double *scale, double *offset);
int save_calibration_data(const char *filename, double scale, double offset);
long read_hx711(int data_pin, int clock_pin);
double convert_to_weight(long raw_value, double scale, double offset);
void control_solenoid(int solenoid_pin, double weight, double threshold);
void log_weight_reading(const char *filename, double weight);
void signal_handler(int signal);

// Function to read calibration data from file
int read_calibration_data(const char *filename, double *scale, double *offset) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s. Using default values.\n", filename);
        return -1; // Indicate failure
    }

    if (fscanf(fp, "%lf %lf", scale, offset) != 2) {
        fprintf(stderr, "Error: Invalid calibration data in %s. Using default values.\n", filename);
        fclose(fp);
        return -1; // Indicate failure
    }

    fclose(fp);
    printf("Calibration data loaded: scale = %lf, offset = %lf\n", *scale, *offset);
    return 0; // Indicate success
}

// Function to save calibration data to file
int save_calibration_data(const char *filename, double scale, double offset) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s for writing.\n", filename);
        return -1; // Indicate failure
    }

    fprintf(fp, "%lf %lf", scale, offset);
    fclose(fp);
    printf("Calibration data saved: scale = %lf, offset = %lf\n", scale, offset);
    return 0; // Indicate success
}

// Function to read raw data from HX711
long read_hx711(int data_pin, int clock_pin) {
    long count = 0;
    int i;
    double start_time, current_time;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);

    // Wait for data pin to go low
    start_time = time_time();
    while (gpioRead(data_pin) == 1) {
        current_time = time_time();
        if (current_time - start_time > HX711_TIMEOUT) {
            fprintf(stderr, "Error: HX711 read timeout.\n");
            return -1; // Indicate timeout error
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1); // Small delay
        count = count << 1;
        if (gpioRead(data_pin))
            count++;
        gpioWrite(clock_pin, 0);
        gpioDelay(1); // Small delay
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(clock_pin, 1);
    gpioDelay(1); // Small delay
    gpioWrite(clock_pin, 0);
    gpioDelay(1); // Small delay

    count = count ^ 0x800000; // Convert to signed 24-bit integer

    return count;
}

// Function to convert raw value to weight
double convert_to_weight(long raw_value, double scale, double offset) {
    return (raw_value - offset) / scale;
}

// Function to control the solenoid lock
void control_solenoid(int solenoid_pin, double weight, double threshold) {
    if (weight > threshold) {
        gpioWrite(solenoid_pin, 1); // Activate solenoid (lock)
        printf("Weight: %lf kg - Locking\n", weight);
    } else {
        gpioWrite(solenoid_pin, 0); // Deactivate solenoid (release)
        printf("Weight: %lf kg - Releasing\n", weight);
    }
}

// Function to log weight reading to file
void log_weight_reading(const char *filename, double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %lf\n", timestamp, weight);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    int i;
    long raw_value;
    double weight;
    double offset_sum = 0.0;
    int num_readings = 100;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration data
    if (read_calibration_data(CALIBRATION_FILE, &scale_factor, &offset) != 0) {
        // Use default values and perform one-time calibration
        printf("Performing one-time calibration...\n");
        for (i = 0; i < num_readings; i++) {
            raw_value = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
            if (raw_value == -1) {
                fprintf(stderr, "Error during calibration reading, using previous offset.\n");
                break; // Exit calibration if there's an error
            }
            offset_sum += raw_value;
            gpioDelay(10); // Small delay between readings
        }
        offset = offset_sum / num_readings;
        save_calibration_data(CALIBRATION_FILE, scale_factor, offset);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        raw_value = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw_value != -1) {
            weight = convert_to_weight(raw_value, scale_factor, offset);
            control_solenoid(SOLENOID_PIN, weight, WEIGHT_THRESHOLD);
            log_weight_reading(LOG_FILE, weight);
        } else {
            fprintf(stderr, "Error: Failed to read HX711 value. Skipping.\n");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Clean up
    gpioWrite(SOLENOID_PIN, 0); // Release solenoid
    fclose(log_file);
    gpioTerminate();

    return 0;
}

