#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define motor control parameters
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150
#define MOTOR_RUN_TIME 5 // seconds

// Define debounce parameters
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_MS 50

// Define wait time after closing the window
#define WAIT_TIME_AFTER_CLOSE 60 // seconds

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void close_window();
void stop_motor();
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_event("Received signal, stopping motor and exiting.");
        stop_motor();
        gpioTerminate();
        closelog();
        program_running = 0;
        exit(0);
    }
}

// Function to read the rain sensor with debouncing
int read_rain_sensor() {
    int rain_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (gpioRead(RAIN_SENSOR_PIN) == 0) {
            rain_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    }
    return (rain_count >= (DEBOUNCE_READINGS / 2)); // Return 1 if rain detected, 0 otherwise
}

// Function to close the window
void close_window() {
    log_event("Closing window.");
    gpioWrite(MOTOR_IN1_PIN, 1);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, PWM_DUTY_CYCLE);
    gpioDelay(MOTOR_RUN_TIME * 1000000); // Run for MOTOR_RUN_TIME seconds
    stop_motor();
    log_event("Window closed.");
}

// Function to stop the motor
void stop_motor() {
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    syslog(LOG_INFO, "%s: %s", buf, message);
}

int main() {
    // Initialize syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Window control program started.");

    // Main loop
    while (program_running) {
        if (read_rain_sensor()) {
            log_event("Rain detected, closing window.");
            close_window();
            sleep(WAIT_TIME_AFTER_CLOSE);
        } else {
            log_event("No rain detected.");
        }
        sleep(60); // Check every 60 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motor();
    gpioTerminate();
    closelog();
    return 0;
}

