#define LOG_FILE "security.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static double calibration_factor = 1.0; // Default calibration factor

// Function prototypes
int read_hx711();
double convert_to_kg(int raw_value);
void control_solenoid(int state);
void log_event(double weight);
int load_calibration_factor();
int save_calibration_factor(double factor);
void calibrate_load_cell();
void signal_handler(int signal);

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int timeout_count = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data line to go low
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_count++;
        if (timeout_count > 100) {
            fprintf(stderr, "Error: HX711 data line timeout\n");
            return -1; // Indicate timeout error
        }
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low delay
    }

    // Pulse the clock pin 25th time to set the gain to 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to convert raw value to kilograms
double convert_to_kg(int raw_value) {
    return (double)raw_value / calibration_factor;
}

// Function to control the solenoid lock
void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
    if (state == 1) {
        printf("Solenoid locked\n");
    } else {
        printf("Solenoid unlocked\n");
    }
}

// Function to log events to a file
void log_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Weight: %.2f kg\n", timestamp, weight);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened\n");
    }
}

