    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Calibration file not found. Using default calibration factor.\n");
        return -1; // Indicate file not found
    }

    if (fscanf(fp, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Error: Invalid calibration factor in file. Using default calibration factor.\n");
        fclose(fp);
        return -1; // Indicate invalid data
    }

    fclose(fp);
    printf("Calibration factor loaded: %.2f\n", calibration_factor);
    return 0;
}

// Function to save the calibration factor to file
int save_calibration_factor(double factor) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing\n");
        return -1; // Indicate file open failure
    }

    fprintf(fp, "%.2f", factor);
    fclose(fp);
    printf("Calibration factor saved: %.2f\n", factor);
    return 0;
}

// Function to calibrate the load cell
void calibrate_load_cell() {
    double known_weight;
    int raw_value;

    printf("Place a known weight on the load cell and press Enter.\n");
    getchar(); // Wait for user input

    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: Failed to read raw value during calibration\n");
        return;
    }

    printf("Enter the weight in kilograms: ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Error: Invalid weight entered\n");
        return;
    }

    calibration_factor = (double)raw_value / known_weight;
    if (save_calibration_factor(calibration_factor) != 0) {
        fprintf(stderr, "Error: Failed to save calibration factor\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    control_solenoid(0); // Unlock the solenoid

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration factor
    if (load_calibration_factor() != 0) {
        printf("Calibration file not found. Performing initial calibration...\n");
        calibrate_load_cell();
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = convert_to_kg(raw_value);
            printf("Weight: %.2f kg\n", weight);

            if (weight > WEIGHT_THRESHOLD) {
                printf("Weight threshold exceeded!\n");
                log_event(weight);
                control_solenoid(1); // Lock the solenoid
                gpioDelay(SOLENOID_DURATION * 1000); // Wait for 5 seconds
                control_solenoid(0); // Unlock the solenoid
            }
        } else {
            fprintf(stderr, "Error: Failed to read HX711 value\n");
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup (should not reach here if signal handler is working)
    control_solenoid(0); // Unlock the solenoid
    fclose(log_file);
    gpioTerminate();

    return 0;
}

