#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR_PIN 16
#define RELAY_PIN 20

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define log file name
#define LOG_FILE "relay_events.log"

// Global variables for GPIO resources
struct gpiod_chip *chip;
struct gpiod_line *sensor_line;
struct gpiod_line *relay_line;

// Function prototypes
int read_sensor(struct gpiod_line *sensor_line);
int toggle_relay(struct gpiod_line *relay_line, int current_state);
int log_event(const char *event_message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *sensor_line) {
    int value = gpiod_line_get_value(sensor_line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(-value));
        return -1; // Indicate error
    }
    return value;
}

// Function to toggle the relay state
