#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define log file name
#define LOG_FILE "motion_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_pir_sensor();
void activate_buzzer(int duration_ms);
void log_motion_event();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Function to activate the buzzer
void activate_buzzer(int duration_ms) {
    gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
}

// Function to log motion events
void log_motion_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(log_file, "%s Motion detected\n", timestamp);
    fclose(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (read_pir_sensor() == 1) {
            printf("Motion detected!\n");
            activate_buzzer(2000); // Activate buzzer for 2 seconds
            log_motion_event();     // Log the event
        }
        gpioDelay(100000); // Delay 100ms to avoid excessive CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio

    return 0;
}

