#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define CONFIG_FILE "watering.conf"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int parse_config(const char *filename, int *duration);
int set_gpio_output(struct gpiod_line *line, int value);
int read_duration_from_file(const char *filename, int *duration);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        fprintf(stderr, "\nSignal received, setting terminate flag.\n");
        terminate = 1;
    }
}

// Function to parse the configuration file
int parse_config(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading from config file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *token = strtok(line, "=");
    if (token == NULL || strcmp(token, "duration") != 0) {
        fprintf(stderr, "Invalid config file format: %s\n", line);
        return -1;
    }

    token = strtok(NULL, "=");
    if (token == NULL) {
        fprintf(stderr, "Invalid config file format: %s\n", line);
        return -1;
    }

    char *endptr;
    long value = strtol(token, &endptr, 10);

    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Invalid duration value: %s\n", token);
        return -1;
    }

    if (value < 1 || value > 3600) {
        fprintf(stderr, "Duration value out of range (1-3600): %ld\n", value);
        return -1;
    }

    *duration = (int)value;
    return 0;
}

// Function to set the GPIO line output value
int set_gpio_output(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to read the watering duration from the file
int read_duration_from_file(const char *filename, int *duration) {
    if (parse_config(filename, duration) != 0) {
        fprintf(stderr, "Failed to parse duration from file %s\n", filename);
        return -1;
    }
    return 0;
}

int main() {
    int duration;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line as output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "watering_system";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_LINE, strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Read watering duration from file
    if (read_duration_from_file(CONFIG_FILE, &duration) != 0) {
        fprintf(stderr, "Failed to read watering duration from file. Exiting.\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Watering duration: %d seconds\n", duration);

    // Turn valve on
    if (set_gpio_output(line, 1) != 0) {
        fprintf(stderr, "Failed to turn valve on. Exiting.\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    printf("Valve ON\n");

    // Wait for duration, checking for signal
    for (int i = 0; i < duration; ++i) {
        if (terminate) {
            fprintf(stderr, "Terminate flag set, exiting loop.\n");
            break;
        }
        sleep(1);
    }

    // Turn valve off
    if (set_gpio_output(line, 0) != 0) {
        fprintf(stderr, "Failed to turn valve off. Exiting.\n");
    }
    printf("Valve OFF\n");

    // Release GPIO line and close chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Watering system exiting.\n");
    return EXIT_SUCCESS;
}

