#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27

#define LEFT_MOTOR_PWM 22
#define LEFT_MOTOR_DIR 23
#define RIGHT_MOTOR_PWM 24
#define RIGHT_MOTOR_DIR 25

// Define motor directions
#define FORWARD 1
#define BACKWARD 0

// Define base speed
#define BASE_SPEED 150

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensors();
void set_motor_speed(int left_speed, int right_speed);
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_motor_speed, int right_motor_speed);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set sensor pins as input
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);

    // Set motor control pins as output
    gpioSetMode(LEFT_MOTOR_PWM, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_DIR, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_PWM, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_DIR, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LEFT_MOTOR_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(RIGHT_MOTOR_PWM, PWM_FREQUENCY);

    return 0;
}

// Read sensor values
int read_sensors() {
    int left_sensor = gpioRead(LEFT_SENSOR);
    int middle_sensor = gpioRead(MIDDLE_SENSOR);
    int right_sensor = gpioRead(RIGHT_SENSOR);

    return (left_sensor << 2) | (middle_sensor << 1) | right_sensor;
}

// Set motor speeds
void set_motor_speed(int left_speed, int right_speed) {
    if (left_speed > 0) {
        gpioWrite(LEFT_MOTOR_DIR, FORWARD);
    } else if (left_speed < 0) {
        gpioWrite(LEFT_MOTOR_DIR, BACKWARD);
        left_speed = -left_speed; // Make speed positive for PWM
    } else {
        gpioWrite(LEFT_MOTOR_DIR, BACKWARD); // Set direction to stop
    }

    if (right_speed > 0) {
        gpioWrite(RIGHT_MOTOR_DIR, FORWARD);
    } else if (right_speed < 0) {
        gpioWrite(RIGHT_MOTOR_DIR, BACKWARD);
        right_speed = -right_speed; // Make speed positive for PWM
    } else {
        gpioWrite(RIGHT_MOTOR_DIR, BACKWARD); // Set direction to stop
    }

    gpioPWM(LEFT_MOTOR_PWM, left_speed);
    gpioPWM(RIGHT_MOTOR_PWM, right_speed);
}

// Log data to file
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_motor_speed, int right_motor_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, left_sensor, middle_sensor, right_sensor, left_motor_speed, right_motor_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("trace_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        int sensor_value = read_sensors();
        int left_motor_speed = 0;
        int right_motor_speed = 0;

        switch (sensor_value) {
            case 0b000: // No sensor detected
                left_motor_speed = 0;
                right_motor_speed = 0;
                break;
            case 0b001: // Right sensor detected
                left_motor_speed = BASE_SPEED;
                right_motor_speed = -(BASE_SPEED / 2);
                break;
            case 0b010: // Middle sensor detected
                left_motor_speed = BASE_SPEED;
                right_motor_speed = BASE_SPEED;
                break;
            case 0b100: // Left sensor detected
                left_motor_speed = -(BASE_SPEED / 2);
                right_motor_speed = BASE_SPEED;
                break;
            default:
                left_motor_speed = 0;
                right_motor_speed = 0;
                break;
        }

        set_motor_speed(left_motor_speed, right_motor_speed);
        log_data(sensor_value & 4 ? 1 : 0, sensor_value & 2 ? 1 : 0, sensor_value & 1 ? 1 : 0, left_motor_speed, right_motor_speed);

        gpioDelay(10000); // 10 ms delay
    }

    // Stop motors
    set_motor_speed(0, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

