#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_RELAY 23
#define LUX_THRESHOLD 150.0
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_lux();
void control_relay(int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Function to read illuminance from BH1750 sensor
float read_lux() {
    char buf[2];
    int result;
    float lux = -1.0; // Default error value

    // Send measurement command (0x10: Continuous H-resolution mode)
    result = i2cWriteByteData(i2c_handle, 0x00, 0x10);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        log_data(-1.0, -1); // Log the error
        return -1.0;
    }

    // Delay for measurement (180ms)
    gpioDelay(180000); // 180ms

    // Read 2 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        log_data(-1.0, -1); // Log the error
        return -1.0;
    }

    // Convert data to lux
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    lux = (float)raw_value / 1.2;

    return lux;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(GPIO_RELAY, state);
}

// Function to log data to file
void log_data(float lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    long milliseconds = (long)(t->tm_usec / 1000);

    fprintf(log_file, "%s.%03ld, Lux: %.2f, Relay: %d\n", timestamp, milliseconds, lux, relay_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    int relay_state = 0; // 0 = off, 1 = on
    float lux;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO23 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Grow lamp control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        lux = read_lux();

        if (lux >= 0) {
            log_data(lux, relay_state);

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
                log_data(lux, relay_state);
                printf("Lux: %.2f, Relay ON\n", lux);
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
                log_data(lux, relay_state);
                printf("Lux: %.2f, Relay OFF\n", lux);
            }
        } else {
            fprintf(stderr, "Error reading lux value.\n");
        }

        gpioDelay(500000); // 0.5 second delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_relay(0); // Turn off relay
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

