#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse width constants
#define LOCKED_PULSE_WIDTH 1000
#define UNLOCKED_PULSE_WIDTH 2000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
void lock_door();
void unlock_door();
void button_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        program_running = 0;
        gpioTerminate();
        exit(0);
    }
}

// Function to lock the door
void lock_door() {
    gpioServo(SERVO_PIN, LOCKED_PULSE_WIDTH);
    printf("Door locked.\n");
}

// Function to unlock the door
void unlock_door() {
    gpioServo(SERVO_PIN, UNLOCKED_PULSE_WIDTH);
    printf("Door unlocked.\n");
}

// Callback function for button presses
void button_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Button pressed (active-low)
        if (gpio == LOCK_BUTTON_PIN) {
            lock_door();
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce
        } else if (gpio == UNLOCK_BUTTON_PIN) {
            unlock_door();
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce
        }
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Set up interrupt handlers for button presses
    gpioSetAlertFunc(LOCK_BUTTON_PIN, button_callback);
    gpioSetAlertFunc(UNLOCK_BUTTON_PIN, button_callback);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Do other tasks here, if needed
        gpioDelay(100000); // Sleep for 0.1 seconds to reduce CPU usage
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

