// Define GPIO pins for the vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define pulse durations in milliseconds
#define MOTOR1_PULSE_DURATION 200
#define MOTOR2_PULSE_DURATION 300

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, stopping motors and exiting...\n");
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR2_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to pulse the first vibration motor
void pulse_motor1() {
    if (gpioWrite(MOTOR1_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d high\n", MOTOR1_GPIO);
    }
    gpioDelay(MOTOR1_PULSE_DURATION * 1000); // Delay in microseconds
    if (gpioWrite(MOTOR1_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO %d low\n", MOTOR1_GPIO);
    }
}

// Function to pulse the second vibration motor
void pulse_motor2() {
    if (gpioWrite(MOTOR2_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d high\n", MOTOR2_GPIO);
    }
    gpioDelay(MOTOR2_PULSE_DURATION * 1000); // Delay in microseconds
    if (gpioWrite(MOTOR2_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO %d low\n", MOTOR2_GPIO);
    }
}

