        perror("Failed to register SIGTERM handler");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Haptic feedback system started. Press Ctrl+C to exit.\n");

    // Main loop to continuously pulse the motors
    while (program_running) {
        pulse_motor1();
        pulse_motor2();
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    fprintf(stderr, "Haptic feedback system stopped.\n");
    return 0;
}

