#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <zmq.h>
#include <time.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ endpoint
#define ZMQ_ENDPOINT "tcp://*:5555"

// Define ZeroMQ topic
#define ZMQ_TOPIC "SOUND_ALERTS"

// Global variables for GPIO and ZeroMQ resources
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *sound_sensor_line = NULL;
struct gpiod_line *alarm_led_line = NULL;
void *zmq_context = NULL;
void *zmq_publisher = NULL;
void *zmq_subscriber = NULL;

// Signal handler for clean shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Release GPIO resources
    if (sound_sensor_line) {
        gpiod_line_release(sound_sensor_line);
    }
    if (alarm_led_line) {
        gpiod_line_release(alarm_led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close and destroy ZeroMQ sockets and context
    if (zmq_subscriber) {
        zmq_close(zmq_subscriber);
    }
    if (zmq_publisher) {
        zmq_close(zmq_publisher);
    }
    if (zmq_context) {
        zmq_ctx_destroy(zmq_context);
    }

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    sound_sensor_line = gpiod_chip_get_line(gpio_chip, SOUND_SENSOR_PIN);
    if (!sound_sensor_line) {
        perror("Error getting sound sensor GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    alarm_led_line = gpiod_chip_get_line(gpio_chip, ALARM_LED_PIN);
    if (!alarm_led_line) {
        perror("Error getting alarm LED GPIO line");
        gpiod_line_release(sound_sensor_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_input(sound_sensor_line, "sound_sensor") < 0) {
        perror("Error requesting sound sensor GPIO line as input");
        gpiod_line_release(sound_sensor_line);
        gpiod_line_release(alarm_led_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(alarm_led_line, "alarm_led", 0) < 0) {
        perror("Error requesting alarm LED GPIO line as output");
        gpiod_line_release(sound_sensor_line);
        gpiod_line_release(alarm_led_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to publish sound alert via ZeroMQ
int publish_sound_alert(void *context) {
    zmq_publisher = zmq_socket(context, ZMQ_PUB);
    if (!zmq_publisher) {
        perror("Error creating ZeroMQ publisher socket");
        return -1;
    }

    int bind_result = zmq_bind(zmq_publisher, ZMQ_ENDPOINT);
    if (bind_result < 0) {
        perror("Error binding ZeroMQ publisher socket");
        zmq_close(zmq_publisher);
        return -1;
    }

    // Small delay to allow the subscriber to connect
    usleep(100000); // 100ms

    char message[20];
    snprintf(message, sizeof(message), "Sound Detected");

    zmq_msg_t zmq_message;
    zmq_msg_init_size(&zmq_message, strlen(message));
    memcpy(zmq_msg_data(&zmq_message), message, strlen(message));

    int send_result = zmq_msg_send(&zmq_message, zmq_publisher, 0);
    zmq_msg_close(&zmq_message);

    if (send_result < 0) {
        perror("Error sending ZeroMQ message");
        return -1;
    }

    printf("Published sound alert: %s\n", message);
    return 0;
}

// Function to subscribe to sound alerts via ZeroMQ
int subscribe_sound_alerts(void *context) {
    zmq_subscriber = zmq_socket(context, ZMQ_SUB);
    if (!zmq_subscriber) {
        perror("Error creating ZeroMQ subscriber socket");
        return -1;
    }

    int connect_result = zmq_connect(zmq_subscriber, "tcp://localhost:5555");
    if (connect_result < 0) {
        perror("Error connecting ZeroMQ subscriber socket");
        zmq_close(zmq_subscriber);
        return -1;
    }

    int subscribe_result = zmq_setsockopt(zmq_subscriber, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC));
    if (subscribe_result < 0) {
        perror("Error subscribing to ZeroMQ topic");
        zmq_close(zmq_subscriber);
        return -1;
    }

    printf("Subscribed to ZeroMQ topic: %s\n", ZMQ_TOPIC);

    while (1) {
        zmq_msg_t zmq_message;
        zmq_msg_init(&zmq_message);

        int recv_result = zmq_msg_recv(&zmq_message, zmq_subscriber, 0);

        if (recv_result >= 0) {
            char *message = (char *)zmq_msg_data(&zmq_message);
            size_t message_size = zmq_msg_size(&zmq_message);
            char received_message[message_size + 1];
            strncpy(received_message, message, message_size);
            received_message[message_size] = '\0';

            printf("Received sound alert: %s\n", received_message);

            // Activate alarm LED
            if (gpiod_line_set_value(alarm_led_line, 1) < 0) {
                perror("Error setting alarm LED value");
            }
            usleep(1000000); // 1 second
            if (gpiod_line_set_value(alarm_led_line, 0) < 0) {
                perror("Error setting alarm LED value");
            }

            zmq_msg_close(&zmq_message);
        } else {
            if (errno == EINTR) {
                printf("Interrupted by signal, exiting.\n");
                break;
            }
            perror("Error receiving ZeroMQ message");
            zmq_msg_close(&zmq_message);
            break;
        }
    }

    return 0;
}

int main(int argc, char *argv[]) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Check command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return 1;
    }

    const char *mode = argv[1];

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Initialize ZeroMQ context
    zmq_context = zmq_ctx_new();
    if (!zmq_context) {
        perror("Error creating ZeroMQ context");
        // Cleanup GPIO resources before exiting
        if (sound_sensor_line) {
            gpiod_line_release(sound_sensor_line);
        }
        if (alarm_led_line) {
            gpiod_line_release(alarm_led_line);
        }
        if (gpio_chip) {
            gpiod_chip_close(gpio_chip);
        }
        return 1;
    }

    // Determine mode and execute corresponding logic
    if (strcmp(mode, "sound_sensor") == 0) {
        printf("Running in sound_sensor mode...\n");
        while (1) {
            int value = gpiod_line_get_value(sound_sensor_line);
            if (value < 0) {
                perror("Error reading sound sensor value");
                break;
            }

            if (value == 0) { // Sound detected (active low)
                if (publish_sound_alert(zmq_context) < 0) {
                    break;
                }
            }

            usleep(10000); // 10ms delay
        }
    } else if (strcmp(mode, "alarm_node") == 0) {
        printf("Running in alarm_node mode...\n");
        if (subscribe_sound_alerts(zmq_context) < 0) {
            // The function handles cleanup and exits on error
        }
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return 1;
    }

    // Cleanup resources before exiting (in case the loop exited due to an error)
    if (sound_sensor_line) {
        gpiod_line_release(sound_sensor_line);
    }
    if (alarm_led_line) {
        gpiod_line_release(alarm_led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (zmq_subscriber) {
        zmq_close(zmq_subscriber);
    }
    if (zmq_publisher) {
        zmq_close(zmq_publisher);
    }
    if (zmq_context) {
        zmq_ctx_destroy(zmq_context);
    }

    return 0;
}

