#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005

// Sensor addresses
const int sensor_addresses[] = {0x23, 0x24, 0x25, 0x26};
const int num_sensors = sizeof(sensor_addresses) / sizeof(sensor_addresses[0]);

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read light level from a single BH1750 sensor
float read_bh1750(int i2c_fd, int address) {
    unsigned char data[2];
    int lux;

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", address, strerror(errno));
        return NAN;
    }

    // Write the One-Time High-Resolution mode command
    unsigned char mode = 0x20;
    if (write(i2c_fd, &mode, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device 0x%02x: %s\n", address, strerror(errno));
        return NAN;
    }

    // Wait for conversion (at least 180ms)
    usleep(180000);

    // Read the data
    if (read(i2c_fd, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device 0x%02x: %s\n", address, strerror(errno));
        return NAN;
    }

    // Convert the data to lux
    lux = (data[0] << 8) | data[1];
    return (float)lux / 1.2;
}

// Function to format the sensor readings into a string
char* format_sensor_data(float sensor_values[]) {
    char *data_string = malloc(256); // Allocate memory for the string
    if (data_string == NULL) {
        fprintf(stderr, "Error allocating memory for data string\n");
        return NULL;
    }
    data_string[0] = '\0'; // Initialize as an empty string

    for (int i = 0; i < num_sensors; i++) {
        char sensor_data[64];
        if (isnan(sensor_values[i])) {
            snprintf(sensor_data, sizeof(sensor_data), "%d,NaN", i + 1);
        } else {
            snprintf(sensor_data, sizeof(sensor_data), "%d,%.2f", i + 1, sensor_values[i]);
        }
        strcat(data_string, sensor_data);
        if (i < num_sensors - 1) {
            strcat(data_string, ";");
        }
    }
    return data_string;
}

// Function to send the data string via UDP multicast
int send_udp_multicast(const char *data_string, const char *multicast_addr, int multicast_port) {
    int sockfd;
    struct sockaddr_in addr;
    int ttl = 1; // Time-to-live for multicast packets

    // Create a UDP socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        return -1;
    }

    // Set the time-to-live for multicast packets
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "Error setting multicast TTL: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Configure the destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(multicast_addr);
    addr.sin_port = htons(multicast_port);

    // Send the data
    if (sendto(sockfd, data_string, strlen(data_string), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error sending data: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Close the socket
    close(sockfd);
    return 0;
}

int main() {
    int i2c_fd;
    float sensor_values[num_sensors];
    char *data_string;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor values
        for (int i = 0; i < num_sensors; i++) {
            sensor_values[i] = read_bh1750(i2c_fd, sensor_addresses[i]);
        }

        // Format sensor data
        data_string = format_sensor_data(sensor_values);
        if (data_string == NULL) {
            continue; // Skip to the next iteration if formatting fails
        }

        // Send UDP multicast packet
        if (send_udp_multicast(data_string, MULTICAST_ADDR, MULTICAST_PORT) != 0) {
            fprintf(stderr, "Error sending UDP multicast packet\n");
        }

        free(data_string); // Free the allocated memory

        // Wait for 1 second
        sleep(1);
    }

    // Close the I2C bus
    close(i2c_fd);

    return 0;
}

