#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x28
#define LOG_FILE "airflow_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static volatile int keep_running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

// Structure to hold sensor data and configuration
typedef struct {
    int i2c_address;
    char *log_file;
    int sample_interval;
} sensor_config_t;

// Function to handle SIGINT signal (Ctrl+C)
void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nCaught SIGINT, exiting...\n");
}

// Function to initialize the I2C bus
int init_i2c(int address) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read flow data from the sensor
int read_flow_data(int fd) {
    unsigned char buffer[2];
    int retries = 3;
    int bytes_read;

    while (retries > 0) {
        // Start reading by issuing a zero-length write
        if (write(fd, NULL, 0) != 0) {
            perror("Error starting I2C read");
            retries--;
            usleep(100000); // 100 ms delay
            continue;
        }

        bytes_read = read(fd, buffer, 2);
        if (bytes_read == 2) {
            // Combine the two bytes into a 14-bit value
            int raw_flow = ((buffer[0] << 8) | buffer[1]) & 0x3FFF;
            return raw_flow;
        } else {
            perror("Error reading flow data");
            retries--;
            usleep(100000); // 100 ms delay
        }
    }

    fprintf(stderr, "Failed to read flow data after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to convert raw data to SLPM
float convert_to_slpm(int raw_flow) {
    return (float)(raw_flow - 3277) * 0.1;
}

// Function to log the flow rate to a file
int log_flow_rate(FILE *fp, float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (t == NULL) {
        perror("Error getting local time");
        return -1;
    }

    if (fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f SLPM\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                t->tm_hour, t->tm_min, t->tm_sec, flow_rate) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    sensor_config_t config = {
        .i2c_address = I2C_ADDRESS,
        .log_file = LOG_FILE,
        .sample_interval = SAMPLE_INTERVAL_SEC
    };

    // Install signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Initialize I2C
    i2c_fd = init_i2c(config.i2c_address);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Open the log file
    log_fp = fopen(config.log_file, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        int raw_flow = read_flow_data(i2c_fd);
        if (raw_flow >= 0) {
            float flow_rate = convert_to_slpm(raw_flow);
            if (log_flow_rate(log_fp, flow_rate) != 0) {
                fprintf(stderr, "Error logging flow rate.\n");
            }
        } else {
            fprintf(stderr, "Failed to read flow data.\n");
        }

        sleep(config.sample_interval);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_fp);

    printf("Airflow monitoring stopped.\n");
    return EXIT_SUCCESS;
}

