#include <string.h>
#include <errno.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 Registers
#define AS7341_WHO_AM_I 0x24
#define AS7341_ENABLE 0x80
#define AS7341_CFG6 0xAF
#define AS7341_SP_EN 0x86
#define AS7341_F1_L 0x60
#define AS7341_F1_H 0x61
#define AS7341_F2_L 0x62
#define AS7341_F2_H 0x63
#define AS7341_F3_L 0x64
#define AS7341_F3_H 0x65
#define AS7341_F4_L 0x66
#define AS7341_F4_H 0x67
#define AS7341_F5_L 0x68
#define AS7341_F5_H 0x69
#define AS7341_F6_L 0x6A
#define AS7341_F6_H 0x6B
#define AS7341_F7_L 0x6C
#define AS7341_F7_H 0x6D
#define AS7341_F8_L 0x6E
#define AS7341_F8_H 0x6F
#define AS7341_CLEAR_L 0x70
#define AS7341_CLEAR_H 0x71
#define AS7341_NIR_L 0x72
#define AS7341_NIR_H 0x73

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_byte(int fd, uint8_t reg);
int initialize_sensor(int fd);
int read_sensor_data(int fd, uint16_t *data);
float calculate_lux(uint16_t *data);
int log_data(FILE *fp, uint16_t *data, float lux);
void signal_handler(int sig);

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return value;
}

// Sensor initialization function
int initialize_sensor(int fd) {
    // Verify WHO_AM_I register
    int who_am_i = i2c_read_byte(fd, AS7341_WHO_AM_I);
    if (who_am_i < 0 || who_am_i != 0x19) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X, expected 0x19\n", who_am_i);
        return -1;
    }

    // Power on the sensor
    if (i2c_write_byte(fd, AS7341_ENABLE, 0x01) < 0) return -1;
    usleep(10000); // Wait for power-on

    // Configure SMUX for spectral readings
    if (i2c_write_byte(fd, AS7341_CFG6, 0x03) < 0) return -1;

    // Enable spectral measurement
    if (i2c_write_byte(fd, AS7341_SP_EN, 0x01) < 0) return -1;

    return 0;
}

// Read sensor data function
int read_sensor_data(int fd, uint16_t *data) {
    uint8_t buffer[2];
    uint8_t reg;

    // Read all 10 spectral channels
    for (int i = 0; i < 10; i++) {
        switch (i) {
            case 0: reg = AS7341_F1_L; break;
            case 1: reg = AS7341_F2_L; break;
            case 2: reg = AS7341_F3_L; break;
            case 3: reg = AS7341_F4_L; break;
            case 4: reg = AS7341_F5_L; break;
            case 5: reg = AS7341_F6_L; break;
            case 6: reg = AS7341_F7_L; break;
            case 7: reg = AS7341_F8_L; break;
            case 8: reg = AS7341_CLEAR_L; break;
            case 9: reg = AS7341_NIR_L; break;
            default: return -1; // Should never happen
        }

        if (write(fd, &reg, 1) != 1) {
            perror("I2C write (register select) failed");
            return -1;
        }

        if (read(fd, buffer, 2) != 2) {
            perror("I2C read failed");
            return -1;
        }

        data[i] = (buffer[1] << 8) | buffer[0];
    }

    return 0;
}

// Lux calculation function (simplified)
float calculate_lux(uint16_t *data) {
    // This is a placeholder.  A real implementation would use a lookup table
    // or a more complex formula based on the sensor's datasheet.
    // For example, you might use the ratio of F1 to F2 to estimate lux.
    // This example just averages the data.
    float sum = 0.0;
    for (int i = 0; i < 10; i++) {
        sum += data[i];
    }
    return sum / 10.0;
}

// Log data function
int log_data(FILE *fp, uint16_t *data, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            timestamp,
            data[0], data[1], data[2], data[3], data[4], data[5], data[6], data[7], data[8], data[9],
            lux);
    fflush(fp); // Ensure data is written to file immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    }
    rewind(log_file);

    uint16_t sensor_data[10];
    float lux;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, sensor_data) < 0) {
            fprintf(stderr, "Error reading sensor data\n");
        } else {
            // Calculate lux
            lux = calculate_lux(sensor_data);

            // Log data
            if (log_data(log_file, sensor_data, lux) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Clean up
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

