#include <errno.h>

// Define sensor-specific constants
#define D7S_I2C_ADDR 0x37
#define D7S_REG_X_L 0x28
#define D7S_REG_X_H 0x29
#define D7S_REG_Y_L 0x2A
#define D7S_REG_Y_H 0x2B
#define D7S_REG_Z_L 0x2C
#define D7S_REG_Z_H 0x2D
#define D7S_SENSITIVITY 0.000244 // g/raw

// Global variables
static int i2c_fd = -1;
static FILE *data_file = NULL;
static FILE *error_file = NULL;
static volatile sig_atomic_t terminate = 0;
static int i2c_address = D7S_I2C_ADDR;
static int interval = 1;
static char *filename = "seismic_data.csv";

// Structure to hold sensor data
typedef struct {
    float x_g;
    float y_g;
    float z_g;
} sensor_data_t;

// Function prototypes
int init_i2c(int address);
int read_sensor_data(int fd, sensor_data_t *data);
float convert_to_g(int16_t raw);
int log_data(FILE *fp, sensor_data_t data);
int log_error(FILE *fp, const char *message);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

// Initialize I2C interface
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read sensor data with retry mechanism
int read_sensor_data(int fd, sensor_data_t *data) {
    uint8_t buffer[6];
    int retries = 3;
    int bytes_read;

    while (retries > 0) {
        bytes_read = read(fd, buffer, 6);
        if (bytes_read == 6) {
            // Combine low and high bytes for each axis
            int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
            int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
            int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

            // Convert to g
            data->x_g = convert_to_g(x);
            data->y_g = convert_to_g(y);
            data->z_g = convert_to_g(z);

            return 0; // Success
        } else {
            log_error(error_file, "I2C read failed, retrying...");
            usleep(10000); // 10 ms backoff
            retries--;
        }
    }

    log_error(error_file, "I2C read failed after multiple retries.");
    return -1; // Failure
}

// Convert raw data to g
float convert_to_g(int16_t raw) {
    return (float)raw * D7S_SENSITIVITY;
}

