    while (!terminate) {
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            log_data(data_file, sensor_data);
        } else {
            log_error(error_file, "Failed to read sensor data.");
        }

        sleep(interval);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

