#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000

static int i2c_fd = -1;
static int udp_socket = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    exit(0);
}

// Function to initialize the BH1750 sensor
int init_bh1750(int fd) {
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    // Send power-on command
    if (write(fd, "\x01", 1) != 1) {
        perror("Error: Could not write power-on command");
        return -1;
    }
    usleep(10000); // Wait for power-on

    // Send continuous high-resolution mode command
    if (write(fd, "\x10", 1) != 1) {
        perror("Error: Could not write continuous high-resolution mode command");
        return -1;
    }
    usleep(10000); // Wait for mode change

    return 0;
}

// Function to read raw data from the BH1750 sensor
int read_bh1750(int fd, unsigned int *raw_value) {
    unsigned char buffer[2];

    if (read(fd, buffer, 2) != 2) {
        perror("Error: Could not read data from BH1750");
        return -1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to convert raw value to lux
float convert_to_lux(unsigned int raw_value) {
    return (float)raw_value / 1.2f;
}

// Function to send lux value over UDP multicast
int send_lux_udp(float lux_value) {
    struct sockaddr_in addr;
    char buffer[32];
    int ttl = 1;

    // Create socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error: Could not create socket");
        return -1;
    }

    // Set TTL
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Error: Could not set TTL");
        close(udp_socket);
        udp_socket = -1;
        return -1;
    }

    // Configure destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Format lux value as string
    snprintf(buffer, sizeof(buffer), "%.2f", lux_value);

    // Send data
    if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error: Could not send data");
        close(udp_socket);
        udp_socket = -1;
        return -1;
    }

    return 0;
}

int main() {
    unsigned int raw_value;
    float lux_value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C bus");
        return 1;
    }

    // Initialize BH1750 sensor
    if (init_bh1750(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read raw value from BH1750
        if (read_bh1750(i2c_fd, &raw_value) == 0) {
            // Convert to lux
            lux_value = convert_to_lux(raw_value);

            // Send lux value over UDP
            if (send_lux_udp(lux_value) != 0) {
                fprintf(stderr, "Error: Failed to send lux value over UDP.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read raw value from BH1750.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

