#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define BUFFER_SIZE 256
#define TIMEOUT_SEC 2
#define TIMEOUT_USEC 0

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signal);
}

int configure_uart(int fd) {
    struct termios tty;

    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr failed");
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD; // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNBRK; // Ignore break condition
    tty.c_oflag = 0; // Raw output
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 5; // Wait for 0.5 seconds (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr failed");
        return -1;
    }

    return 0;
}

int open_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("open failed");
    }
    return fd;
}

int parse_data(char *buffer, size_t len) {
    char *timestamp_str = strtok(buffer, ",");
    char *range_str = strtok(NULL, "\n");

    if (timestamp_str == NULL || range_str == NULL) {
        fprintf(stderr, "Error: Invalid data format\n");
        return -1;
    }

    long timestamp_seconds = strtol(timestamp_str, NULL, 10);
    double range_meters = strtod(range_str, NULL);

    if (timestamp_seconds == 0 && errno == EINVAL) {
        fprintf(stderr, "Error: Invalid timestamp\n");
        return -1;
    }

    if (range_meters == 0.0 && errno == EINVAL) {
        fprintf(stderr, "Error: Invalid range\n");
        return -1;
    }

    struct tm *timeinfo;
    char time_string[20];
    timeinfo = localtime(&timestamp_seconds);
    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", time_string, range_meters);

    return 0;
}

int main() {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;
    size_t buffer_index = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = open_uart(UART_DEVICE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    if (configure_uart(uart_fd) == -1) {
        close(uart_fd);
        return EXIT_FAILURE;
    }

    fprintf(stderr, "UART configured and opened successfully.\n");

    while (program_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = TIMEOUT_SEC;
        timeout.tv_usec = TIMEOUT_USEC;

        int select_result = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);

        if (select_result == -1) {
            perror("select failed");
            break;
        } else if (select_result == 0) {
            // Timeout occurred
            fprintf(stderr, "Timeout waiting for data.\n");
            continue;
        } else {
            // Data is available
            bytes_read = read(uart_fd, buffer + buffer_index, BUFFER_SIZE - buffer_index);
            if (bytes_read == -1) {
                if (errno == EAGAIN || errno == EWOULDBLOCK) {
                    // No data available
                    continue;
                } else {
                    perror("read failed");
                    break;
                }
            } else if (bytes_read == 0) {
                // End of file
                fprintf(stderr, "End of file reached.\n");
                break;
            } else {
                buffer_index += bytes_read;
                buffer[buffer_index] = '\0'; // Null-terminate the buffer

                // Process complete lines
                char *line_start = buffer;
                char *line_end = strchr(line_start, '\n');

                while (line_end != NULL) {
                    *line_end = '\0'; // Null-terminate the line
                    if (parse_data(line_start, line_end - line_start) != 0) {
                        fprintf(stderr, "Error parsing data.\n");
                    }
                    line_start = line_end + 1;
                    line_end = strchr(line_start, '\n');
                }

                // Move any remaining data to the beginning of the buffer
                size_t remaining_len = strlen(line_start);
                memmove(buffer, line_start, remaining_len);
                buffer_index = remaining_len;
                buffer[buffer_index] = '\0';
            }
        }
    }

    close(uart_fd);
    fprintf(stderr, "UART closed.\n");

    return EXIT_SUCCESS;
}

